    public struct MoonPos
    {
        public double Az, El, Ra, Dec, Dist, Ha;
        public double ElGeo;    // elevazione geometrica (senza rifrazione)
        public double DistTopo; // distanza stazione-Luna (km)
        public double Lambda;   // longitudine eclittica topocentrica (gradi), come in WSJT-X
        public double DecGeo;   // declinazione geocentrica (gradi): curva mensile senza l'oscillazione diurna della parallasse
        public double RaGeo;    // ascensione retta geocentrica (gradi)
        public double Gast;     // tempo siderale apparente di Greenwich (gradi)
    }

