        public static string IanaDa(double lat, double lon)
        {
            if (double.IsNaN(lat) || double.IsNaN(lon)) return null;
            if (lat > 90) lat = 90;
            if (lat < -90) lat = -90;
            if (lon > 180) lon = 180;
            if (lon < -180) lon = -180;
            if (lat >= 90) return "Etc/GMT";
            int n = -1;
            double x = (180.0 + lon) * 48.0 / 360.00000000000006;
            double y = (90.0 - lat) * 24.0 / 180.00000000000003;
            int u = (int)x, v = (int)y;
            int i = v * 96 + u * 2;
            i = TZDATA[i] * 56 + TZDATA[i + 1] - 1995;
            while (i + TZLIST.Length < 3136)
            {
                n = n + i + 1;
                x = ((x - u) * 2.0) % 2.0;
                y = ((y - v) * 2.0) % 2.0;
                u = (int)x; v = (int)y;
                i = n * 8 + v * 4 + u * 2 + 2304;
                i = TZDATA[i] * 56 + TZDATA[i + 1] - 1995;
            }
            int k = i + TZLIST.Length - 3136;
            return (k >= 0 && k < TZLIST.Length) ? TZLIST[k] : null;
        }

        static readonly Dictionary<string, TimeZoneInfo> cache = new Dictionary<string, TimeZoneInfo>();

        // Restituisce il fuso di Windows per la posizione; se non lo trova, un fuso fisso da longitudine/15.
        public static TimeZoneInfo Trova(double lat, double lon, out string nome, out bool stimato)
        {
            stimato = false;
            nome = IanaDa(lat, lon);
            if (nome != null)
            {
                int k = Array.IndexOf(TZLIST, nome);
                if (k >= 0)
                {
                    string win = Piattaforma.Windows ? WINZONE[k] : nome;   // Linux e macOS usano gli identificativi IANA
                    TimeZoneInfo tz;
                    if (cache.TryGetValue(win, out tz)) return tz;
                    try
                    {
                        tz = TimeZoneInfo.FindSystemTimeZoneById(win);
                        cache[win] = tz;
                        return tz;
                    }
                    catch { }
                }
            }
            stimato = true;
            int h = (int)Math.Round(lon / 15.0);
            nome = "UTC" + (h >= 0 ? "+" : "") + h.ToString(CultureInfo.InvariantCulture) + Lang.T(" (stimato dalla longitudine)");
            return TimeZoneInfo.CreateCustomTimeZone("LunaCalc" + h.ToString(CultureInfo.InvariantCulture),
                TimeSpan.FromHours(h), nome, nome);
        }
    }

