        static ushort[] t144;

        static void Carica()
        {
            byte[] b = Convert.FromBase64String(DATA);
            ushort[] t = new ushort[b.Length / 2];
            for (int i = 0; i < t.Length; i++) t[i] = (ushort)(b[2 * i] | (b[2 * i + 1] << 8));
            t144 = t;
        }

        static double Cella(int iy, int ix)
        {
            if (iy < 0) iy = 0;
            if (iy > 89) iy = 89;
            ix = ((ix % 180) + 180) % 180;
            return t144[iy * 180 + ix];
        }

        // Temperatura del cielo (K) alla frequenza f (MHz), con interpolazione bilineare;
        // da 144 MHz alle altre frequenze con indice spettrale 2,6 come in WSJT-X.
        public static double Tsky(double raDeg, double decDeg, double fMHz)
        {
            if (t144 == null) Carica();
            double x = (((raDeg % 360) + 360) % 360) / 2.0 - 0.5;
            double y = (decDeg + 90.0) / 2.0 - 0.5;
            int x0 = (int)Math.Floor(x), y0 = (int)Math.Floor(y);
            double fx = x - x0, fy = y - y0;
            double t = Cella(y0, x0) * (1 - fx) * (1 - fy) + Cella(y0, x0 + 1) * fx * (1 - fy)
                     + Cella(y0 + 1, x0) * (1 - fx) * fy + Cella(y0 + 1, x0 + 1) * fx * fy;
            return (t - 2.7) * Math.Pow(144.0 / fMHz, 2.6) + 2.7;
        }
    }

