    class BudgetParams
    {
        public double P, CavoTx, AccTx, GAnt, PreLoss, PreGain, PostLoss, TvGain, Mds, Nf, GroundOn, GroundH = 10, TvCavo = 0.5, TvNf = 1.5, Tant = 250;
        public int NAnt;
        // schema dell'impianto (v27): cavi scelti dal database, lunghezze, relè, transverter, modo
        public double CavoAnt = -1, LenAnt = 3, Rele = 0.3, CavoPa = -1, LenPa = 30, CavoDis = -1, LenDis = 30, TvOn = 0, TvGainSet = 25, Modo = 0, SnReq = -25, TvMod = -1;
        public double LossAnt, LossPa, LossDis;   // perdite dei cavi calcolate alla frequenza della banda

        public static double Freq = 144;   // frequenza della banda corrente, per le perdite dei cavi

        public static readonly string[] Keys = { "p", "cavotx", "acctx", "gant", "nant", "preloss", "pregain", "postloss", "tvgain", "mds", "nf", "groundon", "groundh", "tvcavo", "tvnf", "tant",
            "cavoant", "lenant", "rele", "cavopa", "lenpa", "cavodis", "lendis", "tvon", "tvgainset", "modo", "snreq", "tvmod" };

        // Transverter della tabella del manuale (§ 3.7.2) con figura di rumore e guadagno dichiarati dai costruttori;
        // l'ultima voce della tendina è "personalizzato" (TvMod = -1)
        public static readonly string[] TvNome = { "Kuhne (DB6NT) MKU 144 G2", "Kuhne (DB6NT) TR 144 H +40", "Q5 Signal L144-28M", "HA1YA ME2T-PRO-II / ME2HT-PRO-II" };
        public static readonly double[] TvNfMod = { 0.9, 1.2, 1.0, 1.0 };
        public static readonly double[] TvGMod = { 25, 25, 20, 25 };

        // Modi digitali e S/N richiesto in 2500 Hz (Guida di WSJT-X, § 7.1; FT4 = FT8 + 3,5 dB;
        // Q65: "Quick-Start Guide to Q65", K1JT e altri, 3 aprile 2021, soglia 50 % senza AP).
        // I nuovi modi vanno aggiunti in fondo: l'indice del modo è salvato nelle impostazioni.
        public static readonly string[] ModiNome = { "JT65", "JT9", "JT4", "FT8", "FT4", "Q65-60A", "WSPR", "Q65-30A", "Q65-120A", "Q65-15A", "Q65-300A" };
        public static readonly double[] ModiSn = { -25, -27, -23, -20, -16.5, -27.6, -31, -24.8, -30.8, -22.2, -33.8 };
        public static readonly bool[] ModiDaVerificare = { false, false, false, false, false, false, false, false, false, false, false };
        // Ordine nella tendina (voce → indice del modo): JT65, JT9, JT4, FT8, FT4, Q65-15A … Q65-300A, WSPR
        public static readonly int[] ModiOrdine = { 0, 1, 2, 3, 4, 9, 7, 5, 8, 10, 6 };
        public static int ModoDaVoce(int voce) { return voce >= 0 && voce < ModiOrdine.Length ? ModiOrdine[voce] : -1; }
        public static int VoceDaModo(int modo) { return Array.IndexOf(ModiOrdine, modo); }

        // Temperatura d'antenna indicativa per banda (da sostituire con il valore Ta delle tabelle VE7BQH)
        public static double TantPredefinita(int band)
        {
            switch (band)
            {
                case 50: return 3500; case 70: return 1500; case 144: return 250; case 222: return 120; case 432: return 50;
                default: return 150;
            }
        }

        public static BudgetParams Default(int band)
        {
            BudgetParams b = new BudgetParams();
            b.PreLoss = 0.3; b.PreGain = 20; b.PostLoss = 3; b.TvGain = 0; b.Mds = -130;
            b.AccTx = 0.5;
            b.Tant = TantPredefinita(band);
            b.CavoAnt = CaviDb.Indice("Hyperflex 13"); b.CavoPa = CaviDb.Indice("Ecoflex 10 Plus"); b.CavoDis = b.CavoPa;
            b.LenAnt = 3; b.LenPa = 30; b.LenDis = 30; b.Rele = 0.3;
            if (band == 50) { b.P = 1000; b.CavoTx = 1.0; b.GAnt = 12.0; b.NAnt = 1; b.Nf = 1.0; }
            else if (band == 70) { b.P = 400; b.CavoTx = 1.0; b.GAnt = 14.0; b.NAnt = 2; b.Nf = 0.8; }
            else if (band == 222) { b.P = 1000; b.CavoTx = 1.5; b.GAnt = 18.5; b.NAnt = 4; b.Nf = 0.4; }
            else if (band == 432) { b.P = 500; b.CavoTx = 2.0; b.GAnt = 21.0; b.NAnt = 4; b.Nf = 0.4; b.CavoAnt = CaviDb.Indice("LDF4-50A (Heliax 1/2\")"); b.CavoPa = b.CavoAnt; b.CavoDis = b.CavoAnt; }
            else { b.P = 1000; b.CavoTx = 1.5; b.GAnt = 17.0; b.NAnt = 4; b.Nf = 0.5; }
            double fs = Freq;
            Freq = band;
            b.Calcola();
            Freq = fs;
            return b;
        }

        static double PerditaCavo(double idx, double len)
        {
            int i = (int)Math.Round(idx);
            if (i < 0 || i >= CaviDb.Elenco.Count) return 0;
            return CaviDb.Elenco[i].Perdita(Freq, len);
        }

        // Perdite effettive dalle scelte dello schema: TX = cavo PA-relè + relè + cavo antenna; RX = cavo antenna + relè prima del preampli
        public void Calcola()
        {
            LossAnt = PerditaCavo(CavoAnt, LenAnt);
            LossPa = PerditaCavo(CavoPa, LenPa);
            LossDis = PerditaCavo(CavoDis, LenDis);
            CavoTx = LossPa;
            AccTx = Rele + LossAnt;
            PreLoss = LossAnt + Rele;
            PostLoss = LossDis;
            TvGain = TvOn > 0.5 ? TvGainSet : 0;
        }

        public double SnRichiesto { get { return SnReq; } }
        public string NomeModo
        {
            get
            {
                int m = (int)Math.Round(Modo);
                return m >= 0 && m < ModiNome.Length ? ModiNome[m] : Lang.T("personalizzato");
            }
        }

        public static BudgetParams FromUi(BudgetUi u)
        {
            BudgetParams b = new BudgetParams();
            b.P = (double)u.P.Value;
            b.GAnt = (double)u.GAnt.Value; b.NAnt = (int)u.NAnt.Value;
            b.PreGain = (double)u.PreGain.Value;
            b.Mds = (double)u.Mds.Value;
            b.Nf = (double)u.Nf.Value;
            b.GroundOn = u.Ground.Checked ? 1 : 0;
            b.GroundH = (double)u.GroundH.Value;
            b.TvCavo = (double)u.TvCavo.Value;
            b.TvNf = (double)u.TvNf.Value;
            b.Tant = (double)u.Tant.Value;
            b.CavoAnt = u.CavoAnt.SelectedIndex; b.LenAnt = (double)u.LenAnt.Value;
            b.Rele = (double)u.Rele.Value;
            b.CavoPa = u.CavoPa.SelectedIndex; b.LenPa = (double)u.LenPa.Value;
            b.CavoDis = u.CavoDis.SelectedIndex; b.LenDis = (double)u.LenDis.Value;
            b.TvOn = u.TvOn.Checked ? 1 : 0;
            b.TvGainSet = (double)u.TvGain.Value;
            b.TvMod = u.TvMod.SelectedIndex >= 0 && u.TvMod.SelectedIndex < TvNome.Length ? u.TvMod.SelectedIndex : -1;
            b.Modo = ModoDaVoce(u.Modo.SelectedIndex);   // -1 = personalizzato
            b.SnReq = (double)u.SnReq.Value;
            b.Calcola();
            return b;
        }

        static void Set(NumericUpDown n, double v)
        {
            decimal d = (decimal)v;
            if (d < n.Minimum) d = n.Minimum;
            if (d > n.Maximum) d = n.Maximum;
            n.Value = d;
        }

        static void SetC(ComboBox c, double v)
        {
            int i = (int)Math.Round(v);
            if (i >= 0 && i < c.Items.Count) c.SelectedIndex = i;
            else if (c.Items.Count > 0 && c.SelectedIndex < 0) c.SelectedIndex = 0;
        }

        public void ToUi(BudgetUi u)
        {
            Set(u.P, P); Set(u.GAnt, GAnt); Set(u.NAnt, NAnt);
            Set(u.PreGain, PreGain); Set(u.Mds, Mds);
            Set(u.Nf, Nf);
            u.Ground.Checked = GroundOn > 0.5;
            Set(u.GroundH, GroundH);
            u.GroundH.Enabled = u.Ground.Checked;
            Set(u.TvCavo, TvCavo);
            Set(u.TvNf, TvNf);
            Set(u.Tant, Tant);
            SetC(u.CavoAnt, CavoAnt); Set(u.LenAnt, LenAnt); Set(u.Rele, Rele);
            SetC(u.CavoPa, CavoPa); Set(u.LenPa, LenPa);
            SetC(u.CavoDis, CavoDis); Set(u.LenDis, LenDis);
            u.TvOn.Checked = TvOn > 0.5;
            Set(u.TvGain, TvGainSet);
            u.TvGain.Enabled = u.TvOn.Checked; u.TvNf.Enabled = u.TvOn.Checked; u.TvMod.Enabled = u.TvOn.Checked;
            int ti = (int)Math.Round(TvMod);
            if (u.TvMod.Items.Count > 0) u.TvMod.SelectedIndex = ti >= 0 && ti < TvNome.Length ? ti : u.TvMod.Items.Count - 1;
            int mi = (int)Math.Round(Modo);
            if (mi >= 0 && mi < ModiNome.Length) { SetC(u.Modo, VoceDaModo(mi)); Set(u.SnReq, ModiSn[mi]); }
            else { Set(u.SnReq, SnReq); if (u.Modo.Items.Count > 0) u.Modo.SelectedIndex = u.Modo.Items.Count - 1; }
            Calcola();
            Set(u.CavoTx, CavoTx); Set(u.AccTx, AccTx); Set(u.PreLoss, PreLoss); Set(u.PostLoss, PostLoss);
        }

        public double Get(string k)
        {
            switch (k)
            {
                case "p": return P; case "cavotx": return CavoTx; case "acctx": return AccTx; case "gant": return GAnt;
                case "nant": return NAnt; case "preloss": return PreLoss; case "pregain": return PreGain;
                case "postloss": return PostLoss; case "tvgain": return TvGain; case "nf": return Nf;
                case "groundon": return GroundOn; case "groundh": return GroundH; case "tvcavo": return TvCavo; case "tvnf": return TvNf; case "tant": return Tant;
                case "cavoant": return CavoAnt; case "lenant": return LenAnt; case "rele": return Rele; case "cavopa": return CavoPa; case "lenpa": return LenPa;
                case "cavodis": return CavoDis; case "lendis": return LenDis; case "tvon": return TvOn; case "tvgainset": return TvGainSet; case "modo": return Modo; case "snreq": return SnReq;
                case "tvmod": return TvMod;
                default: return Mds;
            }
        }

        public void Put(string k, double v)
        {
            switch (k)
            {
                case "p": P = v; break; case "cavotx": CavoTx = v; break; case "acctx": AccTx = v; break;
                case "gant": GAnt = v; break; case "nant": NAnt = (int)Math.Round(v); break;
                case "preloss": PreLoss = v; break; case "pregain": PreGain = v; break;
                case "postloss": PostLoss = v; break; case "mds": Mds = v; break;
                case "tvgain": TvGain = v; if (v != 0) { TvGainSet = v; TvOn = 1; } break;   // impostazioni delle versioni precedenti
                case "nf": Nf = v; break;
                case "groundon": GroundOn = v; break;
                case "groundh": GroundH = v; break;
                case "tvcavo": TvCavo = v; break;
                case "tvnf": TvNf = v; break;
                case "tant": Tant = v; break;
                case "cavoant": CavoAnt = v; break; case "lenant": LenAnt = v; break; case "rele": Rele = v; break;
                case "cavopa": CavoPa = v; break; case "lenpa": LenPa = v; break; case "cavodis": CavoDis = v; break; case "lendis": LenDis = v; break;
                case "tvon": TvOn = v; break; case "tvgainset": TvGainSet = v; break; case "modo": Modo = v; break; case "snreq": SnReq = v; break;
                case "tvmod": TvMod = v; break;
            }
        }
    }

    class SfuStation
    {
        public string Name, Descr;
        public double Lat, Lon;
        public DateTime Latest = DateTime.MinValue;
        // per frequenza: valore più recente (a parità di ora preferisce quello di qualità "Good")
        Dictionary<int, double> flux = new Dictionary<int, double>();
        Dictionary<int, DateTime> when = new Dictionary<int, DateTime>();
        Dictionary<int, bool> good = new Dictionary<int, bool>();

        public SfuStation(string name, string descr, double lat, double lon)
        {
            Name = name; Descr = descr; Lat = lat; Lon = lon;
        }

        public void Clear()
        {
            flux.Clear(); when.Clear(); good.Clear();
            Latest = DateTime.MinValue;
        }

        public void Add(int f, double v, DateTime t, bool isGood)
        {
            DateTime t0;
            bool newer = !when.TryGetValue(f, out t0) || t > t0 || (t == t0 && isGood && !good[f]);
            if (!newer) return;
            flux[f] = v; when[f] = t; good[f] = isGood;
            if (t > Latest) Latest = t;
        }

        // NaN se manca o se è più vecchio di 3 giorni rispetto all'ultima misura della stazione
        public double Get(int f)
        {
            double v;
            if (!flux.TryGetValue(f, out v)) return double.NaN;
            if ((Latest - when[f]).TotalDays > 3) return double.NaN;
            return v;
        }
    }

    // Fumetto sulle intestazioni delle colonne di una ListView (intercetta i messaggi dell'header)
    class HeaderToolTip : NativeWindow
    {
        [StructLayout(LayoutKind.Sequential)]
        struct HDHITTESTINFO { public int x; public int y; public int flags; public int iItem; }

        [StructLayout(LayoutKind.Sequential)]
        struct TRACKMOUSEEVENT { public int cbSize; public int dwFlags; public IntPtr hwndTrack; public int dwHoverTime; }

        [DllImport("user32.dll")]
        static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);
        [DllImport("user32.dll", EntryPoint = "SendMessage")]
        static extern IntPtr SendMessageHit(IntPtr hWnd, int msg, IntPtr wParam, ref HDHITTESTINFO lParam);
        [DllImport("user32.dll")]
        static extern bool TrackMouseEvent(ref TRACKMOUSEEVENT tme);

        const int LVM_GETHEADER = 0x101F, HDM_HITTEST = 0x1206, WM_MOUSEMOVE = 0x0200, WM_MOUSELEAVE = 0x02A3, TME_LEAVE = 2;

        readonly ListView lv;
        readonly Func<int, string> testo;
        readonly ToolTip tt = new ToolTip();
        int ultima = -2;
        bool tracking;

        public HeaderToolTip(ListView lv, Func<int, string> testo)
        {
            this.lv = lv;
            this.testo = testo;
            Fumetto.Stile(tt);
            if (!Piattaforma.Windows) return;   // usa i messaggi di Windows dell'intestazione: con Mono niente fumetti sulle colonne
            lv.HandleCreated += (s, e) => Aggancia();
            lv.MouseMove += (s, e) => Nascondi();
            if (lv.IsHandleCreated) Aggancia();
        }

        void Aggancia()
        {
            IntPtr h = SendMessage(lv.Handle, LVM_GETHEADER, IntPtr.Zero, IntPtr.Zero);
            if (h != IntPtr.Zero && h != this.Handle)
            {
                if (this.Handle != IntPtr.Zero) ReleaseHandle();
                AssignHandle(h);
            }
        }

        void Nascondi()
        {
            if (ultima != -2) { ultima = -2; tt.Hide(lv); }
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == WM_MOUSEMOVE)
            {
                if (!tracking)
                {
                    TRACKMOUSEEVENT t = new TRACKMOUSEEVENT();
                    t.cbSize = Marshal.SizeOf(typeof(TRACKMOUSEEVENT));
                    t.dwFlags = TME_LEAVE;
                    t.hwndTrack = this.Handle;
                    tracking = TrackMouseEvent(ref t);
                }
                long lp = m.LParam.ToInt64();
                int x = (short)(lp & 0xFFFF);
                int y = (short)((lp >> 16) & 0xFFFF);
                HDHITTESTINFO hi = new HDHITTESTINFO();
                hi.x = x; hi.y = y; hi.iItem = -1;
                SendMessageHit(this.Handle, HDM_HITTEST, IntPtr.Zero, ref hi);
                if (hi.iItem != ultima)
                {
                    ultima = hi.iItem;
                    string s = hi.iItem >= 0 ? testo(hi.iItem) : null;
                    if (string.IsNullOrEmpty(s)) tt.Hide(lv);
                    else { Fumetto.Ultimo = s; tt.Show(s, lv, x + 12, y + 26, 30000); }
                }
            }
            else if (m.Msg == WM_MOUSELEAVE)
            {
                tracking = false;
                Nascondi();
            }
            base.WndProc(ref m);
        }
    }

