    class Radiosorgente
    {
        public string Nome, Tipo;
        public double Ra, Dec;   // J2000, gradi
        public double S160;      // flusso indicativo a ~160 MHz (Jy)
        public double Alfa;      // indice spettrale (S ~ f^-alfa)

        public Radiosorgente(string nome, string tipo, double raH, double raM, double raS, double decD, double decM, double s160, double alfa)
        {
            Nome = nome; Tipo = tipo;
            Ra = (raH + raM / 60.0 + raS / 3600.0) * 15.0;
            double sg = decD < 0 || (decD == 0 && decM < 0) ? -1 : 1;
            Dec = sg * (Math.Abs(decD) + Math.Abs(decM) / 60.0);
            S160 = s160; Alfa = alfa;
        }

        public double Flusso(double fMHz) { return S160 * Math.Pow(fMHz / 160.0, -Alfa); }
    }

