            card.Controls.Add(b.GAnt); card.Controls.Add(b.NAnt); card.Controls.Add(b.Ground); card.Controls.Add(b.GroundH);
            b.Card = card;
            card.Layout += (s, e) => DisponiStazione(bb);
            card.Paint += (s, e) => DisegnaStazione(e.Graphics, bb, title, colore);
            return card;
        }

        float StazRiga(BudgetUi u) { return Math.Max(S(28), u.GAnt.Height + S(4)); }
        int StazAltezza(BudgetUi u) { return (int)(S(36) + 3 * StazRiga(u) + S(78)); }

        void DisponiStazione(BudgetUi u)
        {
            Control c = u.Card;
            if (c == null) return;
            int pad = S(16), fw = S(86);
            float rh = StazRiga(u), y0 = S(36);
            NumericUpDown[] n = { u.GAnt, u.NAnt };
            for (int k = 0; k < 2; k++)
            {
                n[k].Width = fw;
                n[k].Location = new Point(c.Width - pad - fw, (int)(y0 + k * rh + (rh - n[k].Height) / 2));
            }
            u.Ground.Location = new Point(c.Width - pad - u.Ground.Width + S(2), (int)(y0 + 2 * rh + (rh - u.Ground.Height) / 2));
            u.GroundH.Width = S(70);
            u.GroundH.Location = new Point(u.Ground.Left - S(10) - u.GroundH.Width, (int)(y0 + 2 * rh + (rh - u.GroundH.Height) / 2));
            u.GroundH.Visible = u.Ground.Checked;
        }

        void DisegnaStazione(Graphics g, BudgetUi u, string title, Color col)
        {
            Control c = u.Card;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            RectangleF r = new RectangleF(S(2), S(2), c.Width - S(6), c.Height - S(7));
            Scheda(g, r, Color.Empty);
            using (GraphicsPath p = Arrotondato(r, S(12)))
            {
                Region old = g.Clip;
                g.SetClip(p, CombineMode.Intersect);
                using (Brush bc = new SolidBrush(col)) g.FillRectangle(bc, r.Left, r.Top, r.Width, S(4));
                g.Clip = old;
            }
            int pad = S(16);
            float rh = StazRiga(u), y0 = S(36);
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(11.5f), false))
            using (Font fl = FontPx(Lang.FontUi, S(13.5f), false))
            using (Font fi = FontPx(Lang.FontUi, S(12.5f), false))
            {
                string tt = title.ToUpper(Lang.Cultura);
                float wt = g.MeasureString(tt, ft).Width;
                Testo(g, tt, ft, col, new RectangleF(r.Left + pad, r.Top + S(10), wt + S(6), S(22)), StringAlignment.Near, StringAlignment.Center);
                Testo(g, u.Sotto, fs, Tema.Muted, new RectangleF(r.Left + pad + wt + S(12), r.Top + S(10), Math.Max(1, r.Width - 2 * pad - wt - S(12)), S(22)), StringAlignment.Far, StringAlignment.Center);
                string[] et = { Lang.T("Guadagno singola antenna"), Lang.T("Numero di antenne"), Lang.T("BETA- antenna senza elevazione") };
                for (int k = 0; k < 3; k++)
                {
                    float wl = r.Width - 2 * pad - S(96) - (k == 2 && u.GroundH.Visible ? u.GroundH.Width + S(10) : 0);
                    Testo(g, et[k], fl, Tema.Fore, new RectangleF(r.Left + pad, y0 + k * rh, Math.Max(1, wl), rh), StringAlignment.Near, StringAlignment.Center);
                }
                float yi = y0 + 3 * rh + S(2);
                string i1 = u.Info1.Text ?? "", d1 = "";
                int ip = i1.LastIndexOf(" (");
                if (ip > 0 && i1.EndsWith(")")) { d1 = i1.Substring(ip + 1); i1 = i1.Substring(0, ip); }
                if (d1.Length > 0) Testo(g, d1, fs, Tema.Muted, new RectangleF(r.Left + pad, yi, r.Width - 2 * pad, S(20)), StringAlignment.Far, StringAlignment.Center);
                Testo(g, i1, fi, Tema.Muted, new RectangleF(r.Left + pad, yi, r.Width - 2 * pad - (d1.Length > 0 ? g.MeasureString(d1, fs).Width + S(8) : 0), S(20)), StringAlignment.Near, StringAlignment.Center);
                using (Brush bi = new SolidBrush(Tema.Accent))
                    g.DrawString(u.Info2.Text ?? "", fi, bi, new RectangleF(r.Left + pad, yi + S(22), r.Width - 2 * pad, Math.Max(1, r.Bottom - yi - S(26))));
            }
        }

        ComboBox ComboCavi()
        {
            ComboBox c = new ComboBox();
            c.DropDownStyle = ComboBoxStyle.DropDownList;
            c.DropDownWidth = S(380);
            c.MaxDropDownItems = 20;
            foreach (Cavo k in CaviDb.Elenco) c.Items.Add(k.Etichetta);
            return c;
        }

        // Aggiorna l'elenco dei cavi in tutte le tendine (dopo un cavo personalizzato aggiunto o tolto)
        void RicaricaTendineCavi()
        {
            foreach (BudgetUi u in new BudgetUi[] { bMe, bDx })
            {
                if (u == null) continue;
                foreach (ComboBox c in new ComboBox[] { u.CavoAnt, u.CavoPa, u.CavoDis })
                {
                    int i = c.SelectedIndex;
                    loadingB = true;
                    c.Items.Clear();
                    foreach (Cavo k in CaviDb.Elenco) c.Items.Add(k.Etichetta);
                    c.SelectedIndex = Math.Min(Math.Max(0, i), c.Items.Count - 1);
                    loadingB = false;
                }
            }
            RecalcBudget();
        }

