            Label nb = L(Lang.T("   Parametri delle stazioni: quelli della linguetta \"Budget EME\"."));
            nb.ForeColor = Tema.Muted;
            bar.Controls.Add(L(Lang.T("Banda"))); bar.Controls.Add(cmbBand3);
            bar.Controls.Add(L(Lang.T("Istante (UTC)"))); bar.Controls.Add(dtpS); bar.Controls.Add(bNow); bar.Controls.Add(bRow);
            bar.Controls.Add(nb);
            root.Controls.Add(bar, 0, 0);
            root.SetColumnSpan(bar, 2);

            // indicatori
            pnlSfuKpi = new PannelloDisegno();
            pnlSfuKpi.Dock = DockStyle.Fill;
            pnlSfuKpi.Paint += DisegnaSfuKpi;
            root.Controls.Add(pnlSfuKpi, 0, 1);
            root.SetColumnSpan(pnlSfuKpi, 2);

            // a sinistra: fonte dei dati e scelte per il calcolo
            TableLayoutPanel sx = new TableLayoutPanel();
            sx.Dock = DockStyle.Fill;
            sx.ColumnCount = 1; sx.RowCount = 2;
            sx.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            sx.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            sx.Margin = new Padding(0);
            TableLayoutPanel gd = new TableLayoutPanel();
            gd.Dock = DockStyle.Fill;
            gd.ColumnCount = 1;
            gd.RowCount = 3;
            gd.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            gd.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            gd.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            FlowLayoutPanel fu = new FlowLayoutPanel();
            fu.AutoSize = true;
            fu.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            fu.Dock = DockStyle.Fill;
            cmbSfuFonte = new ComboBox();
            cmbSfuFonte.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbSfuFonte.Items.AddRange(new object[] {
                new VoceFonte(Lang.T("NOAA SWPC · rete RSTN, 245 – 15400 MHz (consigliata)"), "NOAA SWPC · " + Lang.T("rete RSTN, 245 – 15400 MHz"), " " + Lang.T("(consigliata: 4 stazioni, 8 frequenze)")),
                new VoceFonte(Lang.T("NOAA SWPC · F10.7 (2800 MHz), stima grossolana"), "NOAA SWPC · " + Lang.T("solo F10.7"), " " + Lang.T("(2800 MHz, Penticton): il resto dello spettro è stimato")),
                new VoceFonte(Lang.T("Penticton (Canada, DRAO) · F10.7 (2800 MHz), stima grossolana"), Lang.T("Penticton DRAO (Canada)") + " · F10.7", " " + Lang.T("osservato, tre misure al giorno")),
                new VoceFonte(Lang.T("Learmonth (Australia, BoM) · Sole quieto, 8 frequenze"), Lang.T("Learmonth (Australia, BoM)"), " · " + Lang.T("Sole quieto, 8 frequenze")),
                new VoceFonte(Lang.T("Indirizzo personalizzato (formato RSTN)"), Lang.T("Indirizzo personalizzato…"), " " + Lang.T("(file JSON nel formato SWPC)")) });
            cmbSfuFonte.SelectedIndex = 0;
            cmbSfuFonte.Width = S(390);
            cmbSfuFonte.DropDownWidth = S(560);
            cmbSfuFonte.DrawMode = DrawMode.OwnerDrawFixed;
            cmbSfuFonte.ItemHeight = S(22);
            cmbSfuFonte.DrawItem += (s, e) =>
            {
                e.DrawBackground();
                if (e.Index < 0) return;
                VoceFonte v = cmbSfuFonte.Items[e.Index] as VoceFonte;
                bool sel = (e.State & DrawItemState.Selected) != 0;
                Color ct = sel ? SystemColors.HighlightText : cmbSfuFonte.ForeColor;
                TextFormatFlags tf = TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine;
                Rectangle r = new Rectangle(e.Bounds.X + S(4), e.Bounds.Y, e.Bounds.Width - S(6), e.Bounds.Height);
                if (v == null || (e.State & DrawItemState.ComboBoxEdit) != 0)
                {
                    TextRenderer.DrawText(e.Graphics, cmbSfuFonte.Items[e.Index].ToString(), cmbSfuFonte.Font, r, ct, tf | TextFormatFlags.EndEllipsis);
                    return;
                }
                using (Font fb = new Font(cmbSfuFonte.Font, FontStyle.Bold))
                {
                    int wb = TextRenderer.MeasureText(e.Graphics, v.Grassetto, fb, r.Size, tf).Width;
                    TextRenderer.DrawText(e.Graphics, v.Grassetto, fb, r, ct, tf);
                    TextRenderer.DrawText(e.Graphics, v.Resto, cmbSfuFonte.Font, new Rectangle(r.X + wb, r.Y, Math.Max(1, r.Width - wb), r.Height), ct, tf | TextFormatFlags.EndEllipsis);
                }
            };
