            gc.Controls.Add(L(Lang.T("Lobi laterali DX")), 2, 1); gc.Controls.Add(nudSlDx, 3, 1);
            gc.Controls.Add(chkSfuMan, 0, 2); gc.Controls.Add(nudSfuMan, 1, 2);
            gc.Controls.Add(lblSfuEst, 2, 2); gc.SetColumnSpan(lblSfuEst, 2);
            sx.Controls.Add(SchedaCampi(Lang.T("SCELTE PER IL CALCOLO"), Color.FromArgb(25, 65, 127), gc, null), 0, 1);
            root.Controls.Add(sx, 0, 2);

            // a destra: spettro del flusso solare
            pnlSfuSpettro = new PannelloDisegno();
            pnlSfuSpettro.Dock = DockStyle.Fill;
            pnlSfuSpettro.Paint += DisegnaSpettroSfu;
            tip.SetToolTip(pnlSfuSpettro, Lang.T("Punti = misure; tratteggio = estrapolazione con legge di potenza fino alla frequenza di lavoro (la parte più incerta: confronta con il valore manuale)."));
            root.Controls.Add(pnlSfuSpettro, 1, 2);

            lvS = new DBListView();
            lvS.Dock = DockStyle.Fill;
            lvS.View = View.Details;
            lvS.FullRowSelect = true;
            lvS.GridLines = true;
            lvS.HeaderStyle = ColumnHeaderStyle.Nonclickable;
            lvS.Columns.Add(Lang.T("Grandezza"), S(330));
            lvS.Columns.Add(Lang.T("Io trasmetto → il DX riceve"), S(330));
            lvS.Columns.Add(Lang.T("Il DX trasmette → io ricevo"), S(330));
            tip.SetToolTip(lvS, Lang.T("SPERIMENTALE. Flusso alla frequenza di lavoro: 432 MHz interpolato tra 410 e 610 MHz, 144 e 50 MHz estrapolati da 245 e 410 MHz con legge di potenza (la parte più incerta: confronta con il valore manuale). Sole trattato come sorgente puntiforme non polarizzata (l'antenna ne raccoglie metà): T = S·Ae/(2k), con Ae dal guadagno totale, attenuata dal diagramma (lobo gaussiano con la larghezza stimata dal guadagno, poi lobi laterali al livello impostato). Sole sotto l'orizzonte del ricevitore: contributo nullo. Le misure RSTN sono valori di mezzogiorno locale e non seguono i burst del momento."));
            root.Controls.Add(lvS, 0, 3);
            root.SetColumnSpan(lvS, 2);

            tp.Controls.Add(root);
            CaricaCacheSfu();
        }

        // Riquadri in alto: flusso per me e per il DX, aumento del rumore, data dei dati
        void DisegnaSfuKpi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlSfuKpi.ClientRectangle;
            float gap = S(10), w = (cr.Width - 5 * gap) / 4f, h = cr.Height - 2 * gap;
            string f = curBand.ToString(inv) + " MHz";
            string[] tit = { Lang.T("FLUSSO SOLARE A") + " " + f + " · " + Lang.T("IO"), Lang.T("FLUSSO SOLARE A") + " " + f + " · DX",
                Lang.T("AUMENTO DEL RUMORE (SOLE NEL FASCIO)"), Lang.T("DATI AGGIORNATI") };
            string[] val = new string[4], uni = new string[4], sot = new string[4];
            Color[] col = { Color.FromArgb(204, 51, 68), Color.FromArgb(217, 119, 6), Color.FromArgb(31, 111, 209), Tema.OkFg };
            SolarInfo m = sfuInfoMe, d = sfuInfoDx;
            val[0] = m != null && m.Valid ? m.Flux.ToString("F1", ci) : "–"; uni[0] = "SFU";
            sot[0] = m == null ? "" : (m.Manual ? Lang.T("valore manuale") : (m.Station != null ? m.Station.Name + " · " + DistTxt(m.Station, me) + " · " + m.Metodo : Lang.T("nessuna stazione con dati")));
            val[1] = d != null && d.Valid ? d.Flux.ToString("F1", ci) : "–"; uni[1] = "SFU";
            sot[1] = d == null ? "" : (d.Manual ? Lang.T("valore manuale") : (d.Station != null ? d.Station.Name + " · " + DistTxt(d.Station, dx) : Lang.T("nessuna stazione con dati")));
            val[2] = double.IsNaN(sfuDbMe) ? "–" : (sfuDbMe >= 0 ? "+" : "") + sfuDbMe.ToString("F1", ci);
            uni[2] = double.IsNaN(sfuDbDx) ? "dB" : "dB " + Lang.T("io") + " · " + (sfuDbDx >= 0 ? "+" : "") + sfuDbDx.ToString("F1", ci) + " dB DX";
            sot[2] = m == null ? "" : string.Format(ci, Lang.T("Sole a {0:F1}° dalla Luna: {1}"), m.Sep, m.Zona);
            val[3] = sfuDownloaded > DateTime.MinValue ? sfuDownloaded.ToString("dd/MM HH:mm", inv) : "–"; uni[3] = "UTC";
            sot[3] = chkSfuAuto != null && chkSfuAuto.Checked ? Lang.T("prossimo aggiornamento automatico all'avvio") : Lang.T("aggiornamento solo a mano");
            using (Font fh = FontPx(Lang.FontUi, S(11), false))
            using (Font fv = FontPx(FamigliaNumeri, S(28), true))
            using (Font fu = FontPx(Lang.FontUi, S(15), false))
            using (Font fs = FontPx(Lang.FontUi, S(12), false))
                for (int i = 0; i < 4; i++)
                {
                    RectangleF r = new RectangleF(gap + i * (w + gap), gap, w, h);
                    Scheda(g, r, col[i]);
                    Testo(g, tit[i], fh, Tema.Muted, new RectangleF(r.Left + S(18), r.Top + S(8), r.Width - S(24), S(18)), StringAlignment.Near, StringAlignment.Near);
                    float wv = g.MeasureString(val[i], fv).Width;
                    Testo(g, val[i], fv, col[i], new RectangleF(r.Left + S(14), r.Top + S(24), wv + S(6), S(40)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, uni[i], fu, Tema.Fore, new RectangleF(r.Left + S(18) + wv, r.Top + S(30), r.Width - wv - S(24), S(32)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, sot[i], fs, Tema.Fore, new RectangleF(r.Left + S(18), r.Top + S(64), r.Width - S(24), r.Height - S(68)), StringAlignment.Near, StringAlignment.Near);
                }
        }

        // Spettro del flusso solare (scala log-log) con l'estrapolazione alla frequenza di lavoro
        void DisegnaSpettroSfu(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlSfuSpettro.ClientRectangle;
            RectangleF card = new RectangleF(S(4), S(4), cr.Width - S(12), cr.Height - S(12));
            Scheda(g, card, Color.Empty);
            using (Font fh = FontPx(Lang.FontUi, S(13), true))
                Testo(g, Lang.T("SPETTRO DEL FLUSSO SOLARE E FREQUENZA DI LAVORO"), fh, Tema.Accent, new RectangleF(card.Left + S(16), card.Top + S(8), card.Width - S(24), S(20)), StringAlignment.Near, StringAlignment.Near);
            RectangleF a = new RectangleF(card.Left + S(62), card.Top + S(40), card.Width - S(84), card.Height - S(96));
            if (a.Width < 60 || a.Height < 60) return;
            double fmin = curBand < 100 ? 40 : 100, fmax = 20000, smin = 5, smax = 1000;
            double lf0 = Math.Log10(fmin), lf1 = Math.Log10(fmax), ls0 = Math.Log10(smin), ls1 = Math.Log10(smax);
            Func<double, float> X = fq => a.Left + (float)((Math.Log10(fq) - lf0) / (lf1 - lf0) * a.Width);
            Func<double, float> Y = sv => a.Bottom - (float)((Math.Log10(Math.Max(smin, Math.Min(smax, sv))) - ls0) / (ls1 - ls0) * a.Height);
            using (Font ft = FontPx(Lang.FontUi, S(11), false))
            using (Pen pg = new Pen(Tema.Linea))
            using (Brush bt = new SolidBrush(Tema.Muted))
            {
                using (Brush bb = new SolidBrush(Tema.Field)) g.FillRectangle(bb, a);
                foreach (double fq in new double[] { 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000 })
                {
                    if (fq < fmin) continue;
                    g.DrawLine(pg, X(fq), a.Top, X(fq), a.Bottom);
                    string t = fq >= 1000 ? (fq / 1000).ToString("0", inv) + " k" : fq.ToString("0", inv);
                    g.DrawString(t, ft, bt, X(fq) - S(10), a.Bottom + S(4));
                }
                foreach (double sv in new double[] { 5, 10, 20, 50, 100, 200, 500, 1000 })
                {
                    g.DrawLine(pg, a.Left, Y(sv), a.Right, Y(sv));
                    g.DrawString(sv.ToString("0", inv), ft, bt, a.Left - S(40), Y(sv) - S(8));
                }
                g.DrawString(Lang.T("frequenza (MHz, scala logaritmica)"), ft, bt, a.Left + a.Width / 2 - S(90), a.Bottom + S(22));
                g.DrawString(Lang.T("flusso (SFU)"), ft, bt, card.Left + S(6), a.Top - S(20));
            }
            double fw = curBand;
            // 432 MHz, la banda più alta del programma: linea tratteggiata viola chiaro
            using (Pen p4 = new Pen(Color.FromArgb(150, 120, 210), S(1.2f)))
            using (Font f4 = FontPx(Lang.FontUi, S(10), false))
            using (Brush b4 = new SolidBrush(Color.FromArgb(130, 100, 200)))
            {
                p4.DashStyle = DashStyle.Dash;
                g.DrawLine(p4, X(432), a.Top, X(432), a.Bottom);
                if (Math.Abs(fw - 432) > 1) g.DrawString("432", f4, b4, X(432) + S(2), a.Top + S(2));
            }
            using (Pen pw = new Pen(Color.FromArgb(91, 63, 168), S(2)))
                g.DrawLine(pw, X(fw), a.Top, X(fw), a.Bottom);
            // una curva per stazione con dati, con l'estrapolazione tratteggiata alla frequenza di lavoro
            int k = 0;
            float yLeg = a.Bottom - S(16);
            using (Font fl = FontPx(Lang.FontUi, S(11), false))
                foreach (SfuStation st in sfuStations)
                {
                    List<PointF> pts = new List<PointF>();
                    foreach (int fq in SfuFreqs) { double v = st.Get(fq); if (!double.IsNaN(v)) pts.Add(new PointF(X(fq), Y(v))); }
                    double v2800 = st.Get(2800);
                    if (!double.IsNaN(v2800)) pts.Add(new PointF(X(2800), Y(v2800)));
                    if (pts.Count == 0) continue;
                    Color c = ColStazioni[k % ColStazioni.Length];
                    k++;
                    using (Pen p = new Pen(c, S(2)))
                    {
                        if (pts.Count > 1) g.DrawLines(p, pts.ToArray());
                        foreach (PointF q in pts) { g.FillEllipse(Brushes.White, q.X - S(4), q.Y - S(4), S(8), S(8)); g.DrawEllipse(p, q.X - S(4), q.Y - S(4), S(8), S(8)); }
                        string m;
                        double sw = StimaFlusso(st, fw, out m);
                        if (!double.IsNaN(sw))
                        {
                            p.DashStyle = DashStyle.Dash;
                            g.DrawLine(p, X(fw), Y(sw), pts[0].X, pts[0].Y);
                        }
                    }
                    using (Pen p = new Pen(c, S(2)))
                    {
                        g.DrawLine(p, a.Right - S(230), yLeg, a.Right - S(208), yLeg);
                        g.FillEllipse(Brushes.White, a.Right - S(223), yLeg - S(3.5f), S(7), S(7));
                        g.DrawEllipse(p, a.Right - S(223), yLeg - S(3.5f), S(7), S(7));
                    }
                    using (Brush b = new SolidBrush(Tema.Fore)) g.DrawString(st.Descr, fl, b, a.Right - S(203), yLeg - S(8));
                    yLeg -= S(16);
                }
            // valori alla frequenza di lavoro per me e per il DX
            using (Font fb = FontPx(Lang.FontUi, S(12), true))
            {
                SolarInfo[] si = { sfuInfoMe, sfuInfoDx };
                string[] nm = { Lang.T("io"), "DX" };
                Color[] cc = { Color.FromArgb(204, 51, 68), Color.FromArgb(217, 119, 6) };
                for (int i = 0; i < 2; i++)
                {
                    if (si[i] == null || !si[i].Valid) continue;
                    float y = Y(si[i].Flux);
                    using (Brush b = new SolidBrush(cc[i])) g.FillEllipse(b, X(fw) - S(5), y - S(5), S(10), S(10));
                    string t = nm[i] + " " + si[i].Flux.ToString("F1", ci);
                    SizeF sz = g.MeasureString(t, fb);
                    using (Brush b = new SolidBrush(cc[i])) g.DrawString(t, fb, b, X(fw) - sz.Width - S(8), y - sz.Height / 2 + (i == 0 ? -S(6) : S(6)));
                }
                string tf = fw.ToString("0.###", ci);
                SizeF szf = g.MeasureString(tf, fb);
                RectangleF rf = new RectangleF(X(fw) - S(2), a.Top + S(2), szf.Width + S(8), szf.Height + S(2));
                using (Brush b = new SolidBrush(Color.FromArgb(91, 63, 168))) g.FillRectangle(b, rf);
                g.DrawString(tf, fb, Brushes.White, rf.Left + S(4), rf.Top + 1);
            }
        }

        // Sincronizza banda e istante tra linguetta 2 e 3
        void SyncTab3()
        {
            if (cmbBand3 == null) return;
            syncing = true;
            try
            {
                cmbBand3.SelectedIndex = bandeAttive.IndexOf(curBand);
                dtpS.Value = dtpB.Value;
                loadingB = true;
                double v;
                if (!sfuManual.TryGetValue(curBand, out v)) v = 8;
                decimal d = (decimal)v;
                if (d < nudSfuMan.Minimum) d = nudSfuMan.Minimum;
                if (d > nudSfuMan.Maximum) d = nudSfuMan.Maximum;
                nudSfuMan.Value = d;
            }
            finally { loadingB = false; syncing = false; }
        }

        void CaricaCacheSfu()
        {
            try
            {
                sfuCachePath = CacheSfu;
                foreach (SfuStation st in sfuStations) st.Clear();
                sfuDownloaded = DateTime.MinValue;
                lblSfu.Text = Lang.T("Nessun dato: premi \"Aggiorna dal web\".");
                if (File.Exists(sfuCachePath))
                {
                    ElaboraSfu(File.ReadAllText(sfuCachePath, Encoding.UTF8));
                    sfuDownloaded = File.GetLastWriteTimeUtc(sfuCachePath);
                    lblSfu.Text = Lang.T("Dati in memoria scaricati il ") + sfuDownloaded.ToString("dd/MM/yyyy HH:mm", inv) + " UTC";
                }
            }
            catch (Exception ex) { lblSfu.Text = Lang.T("Dati in memoria non leggibili: ") + ex.Message; }
            AggiornaTabellaSfu();
        }

        void ScaricaSfu()
        {
            sfuSessione = true;
            string url = txtSfuUrl.Text.Trim();
            if (url.Length == 0) url = SfuFontiUrl[FonteSfu].Length > 0 ? SfuFontiUrl[FonteSfu] : SfuUrlDefault;
            sfuCachePath = CacheSfu;
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls;
            }
            catch { }
            WebClient wc = new WebClient();
            wc.Encoding = Encoding.UTF8;
            wc.Headers.Add("User-Agent", "YAEC/27 (EME calculator for radio amateurs)");
            btnSfu.Enabled = false;
            lblSfu.Text = Lang.T("Scaricamento in corso…");
            bool learmonth = FonteSfu == 3;
            int passo = 0;   // Learmonth: 0 = indice del mese, 1 = indice del mese prima, 2 = bollettino
            DownloadStringCompletedEventHandler fine = null;
            Action<string> avvia = null;   // i passi successivi usano un WebClient nuovo
            fine = (s, e) =>
            {
                if (learmonth && passo < 2 && e.Error == null)
                {
                    // dall'indice del mese: il numero di messaggio più alto è l'ultimo bollettino
                    int ultimo = -1;
                    foreach (System.Text.RegularExpressions.Match mm in System.Text.RegularExpressions.Regex.Matches(e.Result, "href=\"(\\d+)\\.html\""))
                    {
                        int nmsg;
                        if (int.TryParse(mm.Groups[1].Value, NumberStyles.Integer, inv, out nmsg) && nmsg > ultimo) ultimo = nmsg;
                    }
                    DateTime mese = DateTime.UtcNow.AddMonths(-passo);
                    string baseMese = SfuUrlLearmonth + mese.ToString("yyyy-MMMM", CultureInfo.InvariantCulture) + "/";
                    if (ultimo >= 0)
                    {
                        passo = 2;
                        ((WebClient)s).Dispose();
                        avvia(baseMese + ultimo.ToString("000000", inv) + ".html");
                        return;
                    }
                    if (passo == 0)
                    {
                        passo = 1;
                        ((WebClient)s).Dispose();
                        avvia(SfuUrlLearmonth + DateTime.UtcNow.AddMonths(-1).ToString("yyyy-MMMM", CultureInfo.InvariantCulture) + "/date.html");
                        return;
                    }
                }
                if (learmonth && passo == 0 && e.Error != null)
                {
                    passo = 1;   // il mese nuovo può non avere ancora un indice
                    ((WebClient)s).Dispose();
                        avvia(SfuUrlLearmonth + DateTime.UtcNow.AddMonths(-1).ToString("yyyy-MMMM", CultureInfo.InvariantCulture) + "/date.html");
                    return;
                }
                btnSfu.Enabled = true;
                if (e.Error != null)
                {
                    lblSfu.Text = Lang.T("Errore di scaricamento: ") + e.Error.Message
                        + (sfuDownloaded > DateTime.MinValue ? Lang.T("  (uso i dati del ") + sfuDownloaded.ToString("dd/MM HH:mm", inv) + " UTC)" : "");
                }
                else
                {
                    try
                    {
                        ElaboraSfu(e.Result);
                        Directory.CreateDirectory(Path.GetDirectoryName(sfuCachePath));
                        File.WriteAllText(sfuCachePath, e.Result, Encoding.UTF8);
                        sfuDownloaded = DateTime.UtcNow;
                        lblSfu.Text = Lang.T("Aggiornato il ") + sfuDownloaded.ToString("dd/MM/yyyy HH:mm", inv) + " UTC";
                    }
                    catch (Exception ex)
                    {
                        lblSfu.Text = Lang.T("Formato dei dati non riconosciuto: ") + ex.Message;
                    }
                }
                ((WebClient)s).Dispose();
                AggiornaTabellaSfu();
                RecalcBudget();
            };
            wc.DownloadStringCompleted += fine;
            avvia = u =>
            {
                WebClient w2 = new WebClient();
                w2.Encoding = Encoding.UTF8;
                w2.Headers.Add("User-Agent", "YAEC/28 (EME calculator for radio amateurs)");
                w2.DownloadStringCompleted += fine;
                try { w2.DownloadStringAsync(new Uri(u)); }
                catch (Exception ex2) { btnSfu.Enabled = true; lblSfu.Text = Lang.T("Indirizzo non valido: ") + ex2.Message; w2.Dispose(); }
            };
            if (learmonth) url = SfuUrlLearmonth + DateTime.UtcNow.ToString("yyyy-MMMM", CultureInfo.InvariantCulture) + "/date.html";
            try { wc.DownloadStringAsync(new Uri(url)); }
            catch (Exception ex)
            {
                btnSfu.Enabled = true;
                lblSfu.Text = Lang.T("Indirizzo non valido: ") + ex.Message;
                wc.Dispose();
            }
        }

        static double ToD(object o)
        {
            if (o == null) return double.NaN;
            try { return Convert.ToDouble(o, CultureInfo.InvariantCulture); }
            catch { return double.NaN; }
        }

        // Legge i dati della fonte scelta
        void ElaboraSfu(string testo)
        {
            if (FonteSfu == 1) { ElaboraF107Json(testo); return; }
            if (FonteSfu == 2) { ElaboraFluxtable(testo); return; }
            if (FonteSfu == 3) { ElaboraIflux(testo); return; }
            ElaboraRstn(testo);
        }

        // Bollettino "Daily Quiet Sun Radio Fluxes From Learmonth" (ASWFC, Bureau of Meteorology):
        // Learmonth  dd/mm/yy   hh:mm    final     245       57        ?   e poi una riga per frequenza (freq, flusso, qualità)
        void ElaboraIflux(string testo)
        {
            foreach (SfuStation st in sfuStations) st.Clear();
            SfuStation lm = null;
            foreach (SfuStation x in sfuStations) if (x.Name == "Learmonth") lm = x;
            if (lm == null) { lm = new SfuStation("Learmonth", Lang.T("Learmonth (Australia)"), -22.22, 114.10); sfuStations.Add(lm); }
            System.Text.RegularExpressions.Regex r1 = new System.Text.RegularExpressions.Regex(@"Learmonth\s+(\d\d)/(\d\d)/(\d\d)\s+(\d\d):(\d\d)\s+\S+\s+(\d{3,5})\s+([\d.]+)\s+(\S+)");
            System.Text.RegularExpressions.Regex r2 = new System.Text.RegularExpressions.Regex(@"^\s*(\d{3,5})\s+([\d.]+)\s+(\S+)\s*$");
            DateTime t = DateTime.MinValue;
            int n = 0;
            foreach (string riga0 in testo.Replace("\r", "").Split('\n'))
            {
                string riga = System.Text.RegularExpressions.Regex.Replace(riga0, "<[^>]*>", "");
                System.Text.RegularExpressions.Match m = r1.Match(riga);
                int fq; double fl;
                if (m.Success)
                {
                    t = new DateTime(2000 + int.Parse(m.Groups[3].Value, inv), int.Parse(m.Groups[2].Value, inv), int.Parse(m.Groups[1].Value, inv),
                        int.Parse(m.Groups[4].Value, inv), int.Parse(m.Groups[5].Value, inv), 0, DateTimeKind.Utc);
                    if (int.TryParse(m.Groups[6].Value, NumberStyles.Integer, inv, out fq) && double.TryParse(m.Groups[7].Value, NumberStyles.Float, inv, out fl) && fl > 0)
                    { lm.Add(fq, fl, t, m.Groups[8].Value.Equals("good", StringComparison.OrdinalIgnoreCase)); n++; }
                    continue;
                }
                if (t == DateTime.MinValue) continue;
                m = r2.Match(riga);
                if (m.Success && int.TryParse(m.Groups[1].Value, NumberStyles.Integer, inv, out fq) && double.TryParse(m.Groups[2].Value, NumberStyles.Float, inv, out fl) && fl > 0)
                { lm.Add(fq, fl, t, m.Groups[3].Value.Equals("good", StringComparison.OrdinalIgnoreCase)); n++; }
                else if (n > 0 && riga.Trim().Length > 0) break;   // fine della tabella
            }
            if (n == 0) throw new Exception(Lang.T("nessun valore di flusso trovato"));
        }


        // Stazione fittizia per l'indice F10.7 (misurato a Penticton, Canada)
        SfuStation StazioneF107()
        {
            foreach (SfuStation st in sfuStations) st.Clear();
            SfuStation f = null;
            foreach (SfuStation x in sfuStations) if (x.Name == "F10.7") f = x;
            if (f == null)
            {
                f = new SfuStation("F10.7", Lang.T("F10.7 (Penticton, Canada)"), 49.32, -119.62);
                sfuStations.Add(f);
            }
            return f;
        }

        // NOAA SWPC f107_cm_flux.json: [{time_tag, frequency, flux, ...}]
        void ElaboraF107Json(string json)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = int.MaxValue;
            object[] arr = js.DeserializeObject(json) as object[];
            if (arr == null) throw new Exception(Lang.T("non è un elenco JSON"));
            SfuStation f = StazioneF107();
            int n = 0;
            foreach (object o in arr)
            {
                Dictionary<string, object> rec = o as Dictionary<string, object>;
                if (rec == null || !rec.ContainsKey("flux") || !rec.ContainsKey("time_tag")) continue;
                double fl = ToD(rec["flux"]);
                DateTime t;
                if (double.IsNaN(fl) || fl <= 0 || !DateTime.TryParse(Convert.ToString(rec["time_tag"], inv), inv,
                        DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out t)) continue;
                f.Add(2800, fl, t, true);
                n++;
            }
            if (n == 0) throw new Exception(Lang.T("nessun valore di flusso trovato"));
        }

        // Penticton (DRAO) fluxtable.txt: fluxdate fluxtime fluxjulian fluxcarrington fluxobsflux fluxadjflux fluxursi
        void ElaboraFluxtable(string testo)
        {
            SfuStation f = StazioneF107();
            int n = 0;
            foreach (string riga in testo.Split('\n'))
            {
                string[] c = riga.Trim().Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
                if (c.Length < 5 || c[0].Length != 8 || !char.IsDigit(c[0][0])) continue;
                DateTime t;
                if (!DateTime.TryParseExact(c[0] + (c[1].Length == 6 ? c[1] : "200000"), "yyyyMMddHHmmss", inv, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out t)) continue;
                double fl;
                if (!double.TryParse(c[4], NumberStyles.Float, inv, out fl) || fl <= 0) continue;
                f.Add(2800, fl, t, true);
                n++;
            }
            if (n == 0) throw new Exception(Lang.T("nessun valore di flusso trovato"));
        }

        // Legge il JSON NOAA: [{time_tag, common_name, details:[{frequency, flux, observed_quality}]}]
        void ElaboraRstn(string json)
        {
            JavaScriptSerializer js = new JavaScriptSerializer();
            js.MaxJsonLength = int.MaxValue;
            object[] arr = js.DeserializeObject(json) as object[];
            if (arr == null) throw new Exception(Lang.T("non è un elenco JSON"));
            foreach (SfuStation st in sfuStations) st.Clear();
            int n = 0;
            foreach (object o in arr)
            {
                Dictionary<string, object> rec = o as Dictionary<string, object>;
                if (rec == null || !rec.ContainsKey("common_name") || !rec.ContainsKey("time_tag")) continue;
                string name = Convert.ToString(rec["common_name"], inv);
                SfuStation st = null;
                foreach (SfuStation x in sfuStations)
                    if (string.Equals(x.Name, name, StringComparison.OrdinalIgnoreCase)) st = x;
                if (st == null)
                {
                    st = new SfuStation(name, name + Lang.T(" (posizione sconosciuta)"), double.NaN, double.NaN);
                    sfuStations.Add(st);
                }
                DateTime t;
                if (!DateTime.TryParse(Convert.ToString(rec["time_tag"], inv), inv,
                        DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out t)) continue;
                object[] det = rec.ContainsKey("details") ? rec["details"] as object[] : null;
                if (det == null) continue;
                foreach (object d0 in det)
                {
                    Dictionary<string, object> d = d0 as Dictionary<string, object>;
                    if (d == null) continue;
                    double f = d.ContainsKey("frequency") ? ToD(d["frequency"]) : double.NaN;
                    double fl = d.ContainsKey("flux") ? ToD(d["flux"]) : double.NaN;
                    string q = d.ContainsKey("observed_quality") ? Convert.ToString(d["observed_quality"], inv) : "";
                    if (double.IsNaN(f) || double.IsNaN(fl) || fl <= 0) continue;
                    bool good = q.IndexOf("good", StringComparison.OrdinalIgnoreCase) >= 0;
                    st.Add((int)Math.Round(f), fl, t, good);
                    n++;
                }
            }
            if (n == 0) throw new Exception(Lang.T("nessun valore di flusso trovato"));
        }

        void AggiornaTabellaSfu()
        {
            if (lvSfu == null) return;
            // aggiunge alle tendine eventuali stazioni nuove trovate nel file
            foreach (ComboBox c in new ComboBox[] { cmbSfuMe, cmbSfuDx })
                while (c.Items.Count < sfuStations.Count + 1) c.Items.Add(sfuStations[c.Items.Count - 1].Descr);
            lvSfu.BeginUpdate();
            lvSfu.Items.Clear();
            int kc = 0;
            foreach (SfuStation st in sfuStations)
            {
                ListViewItem it = new ListViewItem(st.Descr);
                bool conDati = st.Latest != DateTime.MinValue;
                it.ImageIndex = conDati ? (kc++ % ColStazioni.Length) : -1;
                it.SubItems.Add(DistTxt(st, me));
                it.SubItems.Add(chkDx.Checked ? DistTxt(st, dx) : "");
                it.SubItems.Add(st.Latest == DateTime.MinValue ? Lang.T("nessun dato") : st.Latest.ToString("dd/MM/yyyy HH:mm", inv));
                foreach (int f in SfuFreqs)
                {
                    double v = st.Get(f);
                    it.SubItems.Add(double.IsNaN(v) ? "-" : v.ToString("0.#", ci));
                }
                lvSfu.Items.Add(it);
            }
            lvSfu.EndUpdate();
        }

        string DistTxt(SfuStation st, StationUi s)
        {
            if (!s.Ok || double.IsNaN(st.Lat)) return "";
            return GreatCircleKm(s.Lat, s.Lon, st.Lat, st.Lon).ToString("N0", ci) + " km";
        }

        // Flusso alla frequenza di lavoro da una stazione; NaN se mancano i dati
        static double StimaFlusso(SfuStation st, double f, out string metodo)
        {
            metodo = "";
            double s245 = st.Get(245), s410 = st.Get(410), s610 = st.Get(610);
            double s2800 = st.Get(2800);
            if (double.IsNaN(s245) && double.IsNaN(s410) && !double.IsNaN(s2800))
            {
                // solo F10.7: Sole calmo tipico (F10.7 = 70 SFU) scalato in proporzione (stima grossolana)
                metodo = Lang.T("stima da F10.7 (grossolana)");
                return SfuPredefinito((int)Math.Round(f)) * s2800 / 70.0;
            }
            if (f > 610)
            {
                // sopra 610 MHz: interpolazione logaritmica tra le misure più vicine (fino a 15400 MHz); oltre si estrapola
                List<int> disp = new List<int>();
                foreach (int x in SfuFreqs) if (!double.IsNaN(st.Get(x))) disp.Add(x);
                foreach (int x in disp)
                    if (Math.Abs(x - f) < 0.5)
                    {
                        metodo = string.Format(CultureInfo.CurrentCulture, Lang.T("misurato a {0} MHz"), x);
                        return st.Get(x);
                    }
                int lo = -1, hi = -1;
                foreach (int x in disp) { if (x < f) lo = x; if (x > f && hi < 0) hi = x; }
                if (lo > 0 && hi > 0)
                {
                    double a = Math.Log(st.Get(hi) / st.Get(lo)) / Math.Log((double)hi / lo);
                    metodo = string.Format(CultureInfo.CurrentCulture, Lang.T("interpolato tra {0} e {1} MHz"), lo, hi);
                    return st.Get(lo) * Math.Pow(f / lo, a);
                }
                if (lo > 0 && hi < 0 && disp.Count >= 2)
                {
                    int l1 = disp[disp.Count - 2], l2 = disp[disp.Count - 1];
                    double a = Math.Log(st.Get(l2) / st.Get(l1)) / Math.Log((double)l2 / l1);
                    if (a < 0) a = 0;
                    if (a > 2.5) a = 2.5;
                    metodo = string.Format(CultureInfo.CurrentCulture, Lang.T("estrapolato da {0} e {1} MHz, indice {2:F2}"), l1, l2, a);
                    return st.Get(l2) * Math.Pow(f / l2, a);
                }
            }
            if (f >= 410 && f <= 610 && !double.IsNaN(s410) && !double.IsNaN(s610))
            {
                double a = Math.Log(s610 / s410) / Math.Log(610.0 / 410.0);
                metodo = Lang.T("interpolato tra 410 e 610 MHz");
                return s410 * Math.Pow(f / 410.0, a);
            }
            if (!double.IsNaN(s245) && !double.IsNaN(s410))
            {
                double a = Math.Log(s410 / s245) / Math.Log(410.0 / 245.0);
                if (a < 0) a = 0;
                if (a > 2.5) a = 2.5;
                metodo = string.Format(CultureInfo.CurrentCulture, Lang.T("estrapolato da 245 e 410 MHz, indice {0:F2}"), a);
                return s245 * Math.Pow(f / 245.0, a);
            }
            if (!double.IsNaN(s245) && f < 245)
            {
                metodo = Lang.T("da 245 MHz con indice 1,0 (manca 410 MHz)");
                return s245 * (f / 245.0);
            }
            if (!double.IsNaN(s410))
            {
                metodo = Lang.T("da 410 MHz con indice 1,0");
                return s410 * (f / 410.0);
            }
            return double.NaN;
        }

        SfuStation ScegliStazione(ComboBox c, StationUi s, double f, out bool auto)
        {
            auto = c.SelectedIndex <= 0;
            string m;
            if (!auto) return sfuStations[c.SelectedIndex - 1];
            SfuStation best = null;
            double bd = double.MaxValue;
            foreach (SfuStation st in sfuStations)
            {
                if (double.IsNaN(st.Lat) || double.IsNaN(StimaFlusso(st, f, out m))) continue;
                double d = GreatCircleKm(s.Lat, s.Lon, st.Lat, st.Lon);
                if (d < bd) { bd = d; best = st; }
            }
            return best;
        }

        SolarInfo CalcSolar(DateTime t, MoonPos moonRx, StationUi rxSt, BudgetParams rx, double freq, bool rxIsMe)
        {
            SolarInfo si = new SolarInfo();
            si.Station = ScegliStazione(rxIsMe ? cmbSfuMe : cmbSfuDx, rxSt, freq, out si.Auto);
            si.Manual = chkSfuMan.Checked;
            string metodo = "";
            if (si.Manual) { si.Flux = (double)nudSfuMan.Value; metodo = Lang.T("valore manuale"); }
            else if (si.Station != null) si.Flux = StimaFlusso(si.Station, freq, out metodo);
            else si.Flux = double.NaN;
            si.Metodo = metodo;
            si.Valid = !double.IsNaN(si.Flux) && si.Flux > 0;

            double sra, sdec;
            Moon.SunPos(t, rxSt.Lat, rxSt.Lon, out si.SunAz, out si.SunEl, out sra, out sdec);
            si.Sep = Moon.Separation(sra, sdec, moonRx.Ra, moonRx.Dec);
            double g = Math.Pow(10.0, (rx.GAnt + 10.0 * Math.Log10(rx.NAnt)) / 10.0);
            si.Beam = Math.Sqrt(41253.0 / g);
            double sl = (double)(rxIsMe ? nudSlMe.Value : nudSlDx.Value);
            double gauss = Math.Exp(-4.0 * Math.Log(2.0) * (si.Sep / si.Beam) * (si.Sep / si.Beam));
            double att;
            if (si.SunEl < 0) { att = 0; si.Zona = Lang.T("Sole sotto l'orizzonte"); }
            else if (si.Sep > 90) { att = Math.Pow(10.0, (sl - 10.0) / 10.0); si.Zona = Lang.T("lobi posteriori"); }
            else if (gauss >= Math.Pow(10.0, sl / 10.0)) { att = gauss; si.Zona = Lang.T("lobo principale"); }
            else { att = Math.Pow(10.0, sl / 10.0); si.Zona = Lang.T("lobi laterali"); }
            si.AttDb = att > 0 ? 10.0 * Math.Log10(att) : double.NegativeInfinity;
            if (si.Valid)
            {
                double lambda = 299.792458 / freq;
                double ae = g * lambda * lambda / (4.0 * Math.PI);
                si.Tsun = si.Flux * 1e-22 * ae / (2.0 * KBOLTZ) * att;
            }
            return si;
        }

        string SfuTxt(SolarInfo s)
        {
            if (s.Manual) return Lang.T("valore manuale");
            if (s.Station == null) return Lang.T("nessuna stazione con dati: aggiorna o usa il valore manuale");
            return s.Station.Name + (s.Auto ? Lang.T(" (automatica)") : "") + ", " +
                (s.Station.Latest == DateTime.MinValue ? Lang.T("senza dati") : s.Station.Latest.ToString("dd/MM HH:mm", inv) + " UTC");
        }

        string FluxTxt(SolarInfo s)
        {
            if (!s.Valid) return Lang.T("non disponibile");
            return s.Flux.ToString("F1", ci) + " SFU  (" + s.Metodo + ")";
        }

        void AddSolarRows(Tratta a, Tratta b, Tratta a2, Tratta b2, SolarInfo sa, SolarInfo sb)
        {
            sfuInfoMe = sb; sfuInfoDx = sa;
            sfuDbMe = sb.Valid ? 10.0 * Math.Log10(b2.Tsys / b.Tsys) : double.NaN;
            sfuDbDx = sa.Valid ? 10.0 * Math.Log10(a2.Tsys / a.Tsys) : double.NaN;
            if (pnlSfuKpi != null) pnlSfuKpi.Invalidate();
            if (pnlSfuSpettro != null) pnlSfuSpettro.Invalidate();
            lblSfuEst.Text = sb.Valid || sa.Valid
                ? Lang.T("Flusso a ") + curBand.ToString(inv) + Lang.T(" MHz:  me ") + (sb.Valid ? sb.Flux.ToString("F1", ci) : "-")
                  + " SFU,  DX " + (sa.Valid ? sa.Flux.ToString("F1", ci) : "-") + " SFU"
                : Lang.T("Flusso non disponibile: aggiorna i dati o usa il valore manuale.");

            SezioneB(Lang.T("RUMORE SOLARE (SPERIMENTALE) - stazione che riceve"));
            RigaB(Lang.T("Stazione SFU usata"), SfuTxt(sa), SfuTxt(sb));
            RigaB(Lang.T("Flusso solare a ") + curBand.ToString(inv) + " MHz", FluxTxt(sa), FluxTxt(sb));
            RigaB(Lang.T("Sole visto dal ricevitore"),
                string.Format(ci, "Az {0:F1}°  El {1:F1}°", sa.SunAz, sa.SunEl),
                string.Format(ci, "Az {0:F1}°  El {1:F1}°", sb.SunAz, sb.SunEl));
            RigaB(Lang.T("Distanza angolare Sole - Luna"), sa.Sep.ToString("F1", ci) + "°", sb.Sep.ToString("F1", ci) + "°");
            RigaB(Lang.T("Larghezza del fascio RX stimata (-3 dB)"), sa.Beam.ToString("F1", ci) + "°", sb.Beam.ToString("F1", ci) + "°");
            RigaB(Lang.T("Guadagno del diagramma verso il Sole"),
                (double.IsInfinity(sa.AttDb) ? "-" : Db(sa.AttDb)) + "  (" + sa.Zona + ")",
                (double.IsInfinity(sb.AttDb) ? "-" : Db(sb.AttDb)) + "  (" + sb.Zona + ")");
            RigaB(Lang.T("Temperatura aggiunta dal Sole"), sa.Valid ? K(a2.Tsun) : "-", sb.Valid ? K(b2.Tsun) : "-");
            RigaB(Lang.T("Tsys senza Sole / con Sole"), K(a.Tsys) + " / " + K(a2.Tsys), K(b.Tsys) + " / " + K(b2.Tsys));
            RigaB(Lang.T("Aumento del rumore dovuto al Sole"),
                Db(10.0 * Math.Log10(a2.Tsys / a.Tsys)), Db(10.0 * Math.Log10(b2.Tsys / b.Tsys)),
                Tema.Field, true, Color.DarkOrange, Color.DarkOrange);
            RigaSN(Lang.T("S/N in ") + a.Bw.ToString("0", ci) + Lang.T(" Hz senza il Sole"), a.SNb, b.SNb);
            RigaSN(Lang.T("S/N in ") + a.Bw.ToString("0", ci) + Lang.T(" Hz con il Sole"), a2.SNb, b2.SNb);
            RigaB(Lang.T("Peggioramento dell'S/N per il Sole"), Db(a.SNb - a2.SNb), Db(b.SNb - b2.SNb));
        }

