            };
            skyTimer.Start();
        }

        // RA/Dec -> Az/El (gradi), con il tempo siderale locale
        static void AzElDa(double ra, double dec, double lst, double lat, out double az, out double el)
        {
            double r = Math.PI / 180.0;
            double H = (lst - ra) * r, d = dec * r, f = lat * r;
            el = Math.Asin(Math.Sin(f) * Math.Sin(d) + Math.Cos(f) * Math.Cos(d) * Math.Cos(H)) / r;
            az = Math.Atan2(Math.Sin(H), Math.Cos(H) * Math.Sin(f) - Math.Tan(d) * Math.Cos(f)) / r + 180.0;
            az = ((az % 360) + 360) % 360;
        }

        // Az/El -> RA/Dec (gradi)
        static void RaDecDa(double az, double el, double lst, double lat, out double ra, out double dec)
        {
            double r = Math.PI / 180.0;
            double A = az * r, h = el * r, f = lat * r;
            double sd = Math.Sin(f) * Math.Sin(h) + Math.Cos(f) * Math.Cos(h) * Math.Cos(A);
            if (sd > 1) sd = 1;
            if (sd < -1) sd = -1;
            dec = Math.Asin(sd) / r;
            double H = Math.Atan2(-Math.Sin(A) * Math.Cos(h), Math.Cos(f) * Math.Sin(h) - Math.Sin(f) * Math.Cos(h) * Math.Cos(A)) / r;
            ra = (((lst - H) % 360) + 360) % 360;
        }

        static double ElevDa(double ra, double dec, double lst, double lat)
        {
            double az, el;
            AzElDa(ra, dec, lst, lat, out az, out el);
            return el;
        }

