        // Colore del fondo della Volta celeste secondo la scala scelta (0 arcobaleno, 1 nero-bianco, 2 giallo-rosso)
        Color ColoreCielo(double t)
        {
            if (skyPalette == 0) return Spettro(t, skyTlo, skyThi);
            double x = Math.Log(Math.Max(t, skyTlo) / skyTlo) / Math.Log(skyThi / skyTlo);
            if (x < 0) x = 0;
            if (x > 1) x = 1;
            if (skyPalette == 1)
            {
                int v = (int)Math.Round(8 + 247 * x);
                return Color.FromArgb(v, v, v);
            }
            // giallo chiaro -> arancio -> rosso scuro
            double r, g, b;
            if (x < 0.5) { double u = x / 0.5; r = 255; g = 240 - 100 * u; b = 120 - 120 * u; }
            else { double u = (x - 0.5) / 0.5; r = 255 - 80 * u; g = 140 - 140 * u; b = 0; }
            return Color.FromArgb((int)r, (int)g, (int)b);
        }

        // Cerca per una scritta una posizione libera intorno al punto (px, py), dentro l'area; con forza = true la scritta si mette comunque
        static bool PostoLibero(SizeF sz, float px, float py, float gap, List<RectangleF> occ, RectangleF area, bool forza, out RectangleF scelto)
        {
            PointF[] cand = {
                new PointF(px + gap, py - sz.Height / 2), new PointF(px - gap - sz.Width, py - sz.Height / 2),
                new PointF(px - sz.Width / 2, py - gap - sz.Height), new PointF(px - sz.Width / 2, py + gap),
                new PointF(px + gap, py - sz.Height - gap / 2), new PointF(px + gap, py + gap / 2),
                new PointF(px - gap - sz.Width, py - sz.Height - gap / 2), new PointF(px - gap - sz.Width, py + gap / 2),
                new PointF(px + 3 * gap, py - sz.Height / 2), new PointF(px - 3 * gap - sz.Width, py - sz.Height / 2),
                new PointF(px - sz.Width / 2, py - 3 * gap - sz.Height), new PointF(px - sz.Width / 2, py + 3 * gap) };
            scelto = RectangleF.Empty;
            for (int k = 0; k < cand.Length; k++)
            {
                float x = Math.Max(area.Left + 2, Math.Min(area.Right - sz.Width - 2, cand[k].X));
                float y = Math.Max(area.Top + 2, Math.Min(area.Bottom - sz.Height - 2, cand[k].Y));
                RectangleF r = new RectangleF(x, y, sz.Width, sz.Height);
                bool libero = true;
                foreach (RectangleF o in occ) if (o.IntersectsWith(r)) { libero = false; break; }
                if (libero) { scelto = r; occ.Add(r); return true; }
                if (k == 0) scelto = r;
            }
            if (!forza) return false;
            occ.Add(scelto);
            return true;
        }

        // Scritta con il bordo scuro: si legge su qualsiasi colore del fondo
        static void TestoBordato(Graphics g, string t, Font f, Color c, float x, float y)
        {
            using (GraphicsPath p = new GraphicsPath())
            {
                float em = g.DpiY * f.SizeInPoints / 72f;
                p.AddString(t, f.FontFamily, (int)f.Style, em, new PointF(x, y), StringFormat.GenericDefault);
                using (Pen pn = new Pen(Color.FromArgb(235, 0, 0, 0), Math.Max(2.5f, em / 4.2f)))
                {
                    pn.LineJoin = LineJoin.Round;
                    g.DrawPath(pn, p);
                }
                using (Brush b = new SolidBrush(c)) g.FillPath(b, p);
            }
        }

        // Colore dello spettro: blu (rumore minimo) -> ciano -> verde -> giallo -> arancio -> rosso (massimo)
        internal static Color Spettro(double t, double tlo, double thi)
        {
            double x = Math.Log(Math.Max(t, tlo) / tlo) / Math.Log(thi / tlo);
            if (x < 0) x = 0;
            if (x > 1) x = 1;
            double hue = 240.0 * (1.0 - x);   // 240 = blu, 0 = rosso
            double s = 0.85, v = 0.95;
            double c = v * s, hp = hue / 60.0, xx = c * (1 - Math.Abs(hp % 2 - 1)), m = v - c;
            double r1 = 0, g1 = 0, b1 = 0;
            if (hp < 1) { r1 = c; g1 = xx; }
            else if (hp < 2) { r1 = xx; g1 = c; }
            else if (hp < 3) { g1 = c; b1 = xx; }
            else if (hp < 4) { g1 = xx; b1 = c; }
            else { r1 = xx; b1 = c; }
            return Color.FromArgb((int)((r1 + m) * 255), (int)((g1 + m) * 255), (int)((b1 + m) * 255));
        }

        void RecalcSky()
        {
            if (sky == null) return;
            skyValid = me.Ok;
            if (!skyValid) { lblSky.Text = Lang.T("Imposta un locator valido nella prima linguetta."); sky.Invalidate(); return; }
            double f;
            if (!ReadFreq(out f)) f = 144;
            skyFreq = f;
            lblSkyFreq.Text = Lang.T("Rumore del cielo calcolato a ") + f.ToString("0.000", ci) + Lang.T(" MHz  (frequenza della linguetta Posizione della Luna)");
            skyT = DateTime.SpecifyKind(dtpSky.Value, DateTimeKind.Utc);
            skyMoon = Moon.Compute(skyT, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
            Moon.SunPos(skyT, me.Lat, me.Lon, out skySunAz, out skySunEl, out skySunRa, out skySunDec);
            skyLstMe = Moon.Lst(skyT, me.Lon);
            skyLstDx = (chkDx.Checked && dx.Ok) ? Moon.Lst(skyT, dx.Lon) : double.NaN;

            // Sfondo: temperatura del cielo per ogni grado di azimut ed elevazione (da +90° a -30°)
            double sc = Math.Pow(144.0 / f, 2.6);
            skyTlo = (150.0 - 2.7) * sc + 2.7;
            skyThi = (4000.0 - 2.7) * sc + 2.7;
            int bw = 360, bh = (int)(90 - SkyElMin);
            Bitmap bmp = new Bitmap(bw, bh);
            for (int j = 0; j < bh; j++)
            {
                double el = 90.0 - j - 0.5;
                for (int i = 0; i < bw; i++)
                {
                    double az = i + 0.5, ra, dec;
                    RaDecDa(az, el, skyLstMe, me.Lat, out ra, out dec);
                    Color c = ColoreCielo(CieloGsm.Tsky(ra, dec, f));
                    if (el < 0) c = Color.FromArgb(c.R * 45 / 100, c.G * 45 / 100, c.B * 45 / 100);
                    bmp.SetPixel(i, j, c);
                }
            }
            if (skyBmp != null) skyBmp.Dispose();
            skyBmp = bmp;

            // Percorso della Luna nelle prossime 24 ore, ogni 30 minuti
            skyTrack.Clear();
            skyTrackT.Clear();
            for (int k = 0; k <= 48; k++)
            {
                DateTime t = skyT.AddMinutes(30 * k);
                MoonPos p = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, false);
                skyTrack.Add(new double[] { p.Az, p.El, (t.Minute == 0 && t.Hour % 3 == 0) ? 1 : 0 });
                skyTrackT.Add(t);
            }

            // Elenco delle sorgenti ordinato per distanza dalla Luna
            List<KeyValuePair<double, string[]>> rows = new List<KeyValuePair<double, string[]>>();
            foreach (Radiosorgente rs in Sorgenti)
            {
                double d = Moon.Separation(rs.Ra, rs.Dec, skyMoon.Ra, skyMoon.Dec);
                double az, el;
                AzElDa(rs.Ra, rs.Dec, skyLstMe, me.Lat, out az, out el);
                rows.Add(new KeyValuePair<double, string[]>(d, new string[] {
                    rs.Nome, rs.Flusso(f).ToString("N0", ci), d.ToString("F1", ci) + "°", az.ToString("F0", ci) + "°", el.ToString("F0", ci) + "°" }));
            }
            {
                double d = Moon.Separation(skySunRa, skySunDec, skyMoon.Ra, skyMoon.Dec);
                rows.Add(new KeyValuePair<double, string[]>(d, new string[] {
                    Lang.T("Sole"), "≈ 1e6+", d.ToString("F1", ci) + "°", skySunAz.ToString("F0", ci) + "°", skySunEl.ToString("F0", ci) + "°" }));
            }
            rows.Sort((x1, x2) => x1.Key.CompareTo(x2.Key));
            lvSky.BeginUpdate();
            lvSky.Items.Clear();
            foreach (KeyValuePair<double, string[]> kv in rows)
            {
                ListViewItem it = new ListViewItem(kv.Value);
                if (kv.Key < 5) it.BackColor = Tema.Warn1;
                else if (kv.Key < 15) it.BackColor = Tema.Warn2;
                lvSky.Items.Add(it);
            }
            lvSky.EndUpdate();

            double tsky = CieloGsm.Tsky(skyMoon.Ra, skyMoon.Dec, f);
            lblSky.Text = string.Format(ci,
                Lang.T("{0} UTC - Luna da {1}: Az {2:F1}°  El {3:F1}°  Dec {4:F2}°  Tsky dietro la Luna {5:F0} K a {6} MHz.   Sole: Az {7:F1}°  El {8:F1}°, a {9:F1}° dalla Luna.\nCielo visto dalla tua stazione: azimut in orizzontale (N-E-S-O-N), elevazione in verticale, orizzonte = riga piatta a 0°. Colori = rumore del cielo alla frequenza di lavoro (blu = minimo, rosso = massimo; Global Sky Model). Puntini bianchi = piano galattico, puntini chiari = eclittica; linea viola = orizzonte del DX; linee gialle = limiti della tua antenna. Flussi delle radiosorgenti indicativi."),
                FmtDT(skyT), me.Loc.Text.Trim(), skyMoon.Az, skyMoon.El, skyMoon.Dec, tsky, f.ToString("0.###", ci),
                skySunAz, skySunEl, Moon.Separation(skySunRa, skySunDec, skyMoon.Ra, skyMoon.Dec))
                + (chkSkyLim.Checked ? " " + Lang.T("Zone a righe diagonali grigie = fuori dai limiti della tua antenna.") : "");
            sky.Invalidate();
        }

        void Sky_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
            Rectangle cr = sky.ClientRectangle;
            int ml = S(64), mr = S(12), mt = S(12), mb = S(54);
            RectangleF a = new RectangleF(cr.Left + ml, cr.Top + mt, Math.Max(10, cr.Width - ml - mr), Math.Max(10, cr.Height - mt - mb));
            Func<double, float> X = zz => a.Left + (float)((((zz % 360) + 360) % 360) / 360.0 * a.Width);
            Func<double, float> Y = ee => a.Top + (float)((90.0 - ee) / (90.0 - SkyElMin) * a.Height);
            Font fs = new Font(Lang.FontUi, 15F);
            Font fm = new Font(Lang.FontUi, 17F, FontStyle.Bold);
            Brush tbGrid = new SolidBrush(Color.FromArgb(170, 180, 205));

            if (skyValid && skyBmp != null)
            {
                g.InterpolationMode = InterpolationMode.Bilinear;
                g.PixelOffsetMode = PixelOffsetMode.Half;
                g.DrawImage(skyBmp, a);
                g.PixelOffsetMode = PixelOffsetMode.Default;
            }

            // Griglia azimut / elevazione
            string[] punti = { "N", "30", "60", "E", "120", "150", "S", "210", "240", Lang.T("O"), "300", "330", "N" };
            using (Pen grid = new Pen(Color.FromArgb(90, 255, 255, 255)))
            using (Pen gridScura = new Pen(Color.FromArgb(70, 0, 0, 0), 3f))
            {
                for (int k = 0; k <= 12; k++)
                {
                    float x = k == 12 ? a.Right : X(k * 30.0);
                    g.DrawLine(gridScura, x, a.Top, x, a.Bottom);
                    g.DrawLine(grid, x, a.Top, x, a.Bottom);
                    SizeF sz = g.MeasureString(punti[k], fs);
                    g.DrawString(punti[k], fs, tbGrid, x - sz.Width / 2, a.Bottom + S(3));
                }
                for (int d = -30; d <= 90; d += 15)
                {
                    float y = Y(d);
                    g.DrawLine(gridScura, a.Left, y, a.Right, y);
                    g.DrawLine(grid, a.Left, y, a.Right, y);
                    g.DrawString((d > 0 ? "+" : "") + d.ToString(inv) + "°", fs, tbGrid, cr.Left + S(2), y - S(13));
                }
                g.DrawString(Lang.T("Azimut"), fs, tbGrid, a.Left + a.Width / 2 - S(30), a.Bottom + S(26));
            }
            if (!skyValid) { fs.Dispose(); fm.Dispose(); tbGrid.Dispose(); return; }

            // spazi già occupati dalle scritte: legenda, orizzonte, Luna e Sole hanno la precedenza
            List<RectangleF> occ = new List<RectangleF>();
            occ.Add(new RectangleF(a.Right - S(330) - S(30), a.Top + S(2), S(330) + S(26), S(chkSkyLim.Checked ? 110 : 88)));
            RectangleF rLuna = RectangleF.Empty, rSole = RectangleF.Empty;
            string tLuna = string.Format(ci, Lang.T("LUNA  Az {0:F1}° El {1:F1}°"), skyMoon.Az, skyMoon.El);
            if (skyMoon.El >= SkyElMin)
            {
                occ.Add(new RectangleF(X(skyMoon.Az) - S(14), Y(skyMoon.El) - S(14), S(28), S(28)));
                PostoLibero(g.MeasureString(tLuna, fm), X(skyMoon.Az), Y(skyMoon.El), S(16), occ, a, true, out rLuna);
            }
            if (skySunEl >= SkyElMin)
            {
                occ.Add(new RectangleF(X(skySunAz) - S(10), Y(skySunEl) - S(10), S(20), S(20)));
                PostoLibero(g.MeasureString(Lang.T("Sole"), fm), X(skySunAz), Y(skySunEl), S(12), occ, a, true, out rSole);
            }
            string tOriz = Lang.T("orizzonte ") + me.Loc.Text.Trim();
            occ.Add(new RectangleF(a.Left + S(6), Y(0) + S(3), g.MeasureString(tOriz, fm).Width, S(28)));

            // Orizzonte: riga piatta a elevazione 0
            using (Pen hp0 = new Pen(Color.FromArgb(160, 0, 0, 0), 5f)) g.DrawLine(hp0, a.Left, Y(0), a.Right, Y(0));
            using (Pen hp = new Pen(Color.White, 2.5f)) g.DrawLine(hp, a.Left, Y(0), a.Right, Y(0));
            TestoBordato(g, tOriz, fm, Color.White, a.Left + S(6), Y(0) + S(3));

            // Limiti della mia antenna
            if (chkSkyLim.Checked)
            {
                using (Pen lp = new Pen(Color.FromArgb(230, 255, 230, 60), 3.2f))
                {
                    lp.DashStyle = DashStyle.Dash;
                    double e1 = (double)me.El1.Value, e2 = (double)me.El2.Value, z1 = (double)me.Az1.Value, z2 = (double)me.Az2.Value;
                    // zone fuori dai limiti dell'antenna: righe diagonali grigio chiaro
                    using (Region fuori = new Region(a))
                    {
                        double e1c = Math.Max(SkyElMin, e1), e2c = Math.Min(90.0, e2);
                        bool azLib = z2 - z1 >= 360 || z1 == z2;
                        Func<double, float> Xd = zz => a.Left + (float)(zz / 360.0 * a.Width);
                        if (e2c > e1c)
                        {
                            float yt = Y(e2c), yb = Y(e1c);
                            double s1 = ((z1 % 360.0) + 360.0) % 360.0, s2 = z2 >= 360 ? 360.0 : ((z2 % 360.0) + 360.0) % 360.0;
                            if (azLib) fuori.Exclude(new RectangleF(a.Left, yt, a.Width, yb - yt));
                            else if (s1 < s2) fuori.Exclude(new RectangleF(Xd(s1), yt, Xd(s2) - Xd(s1), yb - yt));
                            else
                            {
                                fuori.Exclude(new RectangleF(Xd(s1), yt, Xd(360) - Xd(s1), yb - yt));
                                fuori.Exclude(new RectangleF(Xd(0), yt, Xd(s2) - Xd(0), yb - yt));
                            }
                        }
                        Region primaClip = g.Clip;
                        g.SetClip(fuori, CombineMode.Intersect);
                        using (Pen ph = new Pen(Color.FromArgb(150, GrigioRgb, GrigioRgb, GrigioRgb), S(4)))
                            for (float dd = -a.Height; dd < a.Width + a.Height; dd += S(34))
                                g.DrawLine(ph, a.Left + dd, a.Bottom, a.Left + dd + a.Height, a.Top);
                        g.Clip = primaClip;
                    }
                    if (e1 > SkyElMin) g.DrawLine(lp, a.Left, Y(e1), a.Right, Y(e1));
                    if (e2 < 90) g.DrawLine(lp, a.Left, Y(e2), a.Right, Y(e2));
                    if (!(z2 - z1 >= 360 || z1 == z2))
                    {
                        g.DrawLine(lp, X(z1), a.Top, X(z1), a.Bottom);
                        g.DrawLine(lp, X(z2), a.Top, X(z2), a.Bottom);
                    }
                }
            }

            // Orizzonte del DX visto nel mio cielo: per ogni azimut, l'elevazione dove il DX ha la Luna a 0°
            if (!double.IsNaN(skyLstDx))
            {
                using (Pen dp = new Pen(Color.FromArgb(230, 200, 120, 255), 2f))
                {
                    dp.DashStyle = DashStyle.Dash;
                    PointF? prev = null;
                    for (int az = 0; az <= 360; az += 2)
                    {
                        double prevE = double.NaN, found = double.NaN, ePrev = 90;
                        for (double el = 90; el >= SkyElMin; el -= 1)
                        {
                            double ra, dec;
                            RaDecDa(az, el, skyLstMe, me.Lat, out ra, out dec);
                            double ed = ElevDa(ra, dec, skyLstDx, dx.Lat);
                            if (!double.IsNaN(prevE) && Math.Sign(ed) != Math.Sign(prevE))
                            {
                                found = ePrev + (el - ePrev) * (prevE / (prevE - ed));
                                break;
                            }
                            prevE = ed; ePrev = el;
                        }
                        if (double.IsNaN(found)) { prev = null; continue; }
                        PointF p = new PointF(az == 360 ? a.Right : X(az), Y(found));
                        if (prev.HasValue && Math.Abs(p.Y - prev.Value.Y) < a.Height / 4) g.DrawLine(dp, prev.Value, p);
                        prev = p;
                    }
                }
            }

            // Piano galattico ed eclittica (puntini)
            using (Brush gb = new SolidBrush(Color.FromArgb(220, 255, 255, 255)))
            using (Brush eb = new SolidBrush(Color.FromArgb(200, 255, 240, 200)))
            using (Brush contorno = new SolidBrush(Color.FromArgb(150, 0, 0, 0)))
            {
                for (double l = 0; l < 360; l += 1.5)
                {
                    double ra, dec, az, el;
                    Moon.GalToEq(l, 0, out ra, out dec);
                    AzElDa(ra, dec, skyLstMe, me.Lat, out az, out el);
                    if (el >= SkyElMin) { g.FillEllipse(contorno, X(az) - 2.5f, Y(el) - 2.5f, 5, 5); g.FillEllipse(gb, X(az) - 1.5f, Y(el) - 1.5f, 3, 3); }
                    Moon.EclToEq(l, out ra, out dec);
                    AzElDa(ra, dec, skyLstMe, me.Lat, out az, out el);
                    if (el >= SkyElMin && ((int)(l / 1.5)) % 2 == 0) { g.FillEllipse(contorno, X(az) - 2f, Y(el) - 2f, 4, 4); g.FillEllipse(eb, X(az) - 1f, Y(el) - 1f, 2, 2); }
                }
                double rgc, dgc, azc, elc;
                Moon.GalToEq(0, 0, out rgc, out dgc);
                AzElDa(rgc, dgc, skyLstMe, me.Lat, out azc, out elc);
                // la scritta del centro galattico è quella della radiosorgente Sgr A
            }

            // Percorso della Luna nelle prossime 24 ore (le scritte delle ore si posano dopo le radiosorgenti)
            List<object[]> oreEtich = new List<object[]>();
            if (chkSkyTrack.Checked)
            {
                using (Brush db = new SolidBrush(Color.FromArgb(230, 255, 255, 255)))
                using (Brush tb = new SolidBrush(Color.White))
                {
                    for (int i = 1; i < skyTrack.Count; i++)
                    {
                        if (skyTrack[i][1] < SkyElMin) continue;
                        float x = X(skyTrack[i][0]), y = Y(skyTrack[i][1]);
                        float r = skyTrack[i][2] > 0 ? S(5) : S(3);
                        using (Brush bc = new SolidBrush(Color.FromArgb(160, 0, 0, 0))) g.FillEllipse(bc, x - r / 2 - 1.5f, y - r / 2 - 1.5f, r + 3, r + 3);
                        g.FillEllipse(db, x - r / 2, y - r / 2, r, r);
                        if (skyTrack[i][2] > 0) oreEtich.Add(new object[] { skyTrackT[i].ToString("HH", inv) + "h", x, y });
                    }
                }
            }

            // Radiosorgenti
            using (Brush sb = new SolidBrush(Color.FromArgb(255, 255, 255)))
            using (Pen sp = new Pen(Color.Black, 1))
            using (Brush tb = new SolidBrush(Color.White))
            using (Brush bg = new SolidBrush(Color.FromArgb(120, 0, 0, 0)))
            {
                foreach (Radiosorgente rs in Sorgenti)
                {
                    double az, el;
                    AzElDa(rs.Ra, rs.Dec, skyLstMe, me.Lat, out az, out el);
                    if (el < SkyElMin) continue;
                    double fl = rs.Flusso(skyFreq);
                    float r = (float)Math.Max(S(4), Math.Min(S(14), S(4) + S(3) * Math.Log10(Math.Max(1.0, fl / 50.0))));
                    float x = X(az), y = Y(el);
                    g.FillEllipse(sb, x - r / 2, y - r / 2, r, r);
                    g.DrawEllipse(sp, x - r / 2, y - r / 2, r, r);
                    RectangleF rr;
                    if (PostoLibero(g.MeasureString(rs.Nome, fs), x, y, r / 2 + S(4), occ, a, false, out rr))
                        TestoBordato(g, rs.Nome, fs, Color.White, rr.X, rr.Y);
                }
            }
            foreach (object[] oe in oreEtich)
            {
                RectangleF rr;
                string to = (string)oe[0];
                if (PostoLibero(g.MeasureString(to, fs), (float)oe[1], (float)oe[2], S(6), occ, a, false, out rr))
                    TestoBordato(g, to, fs, Color.White, rr.X, rr.Y);
            }

            // Sole
            if (skySunEl >= SkyElMin)
            {
                float x = X(skySunAz), y = Y(skySunEl), r = S(16);
                using (Brush b = new SolidBrush(Color.FromArgb(255, 230, 60))) g.FillEllipse(b, x - r / 2, y - r / 2, r, r);
                using (Pen p = new Pen(Color.Black, 1.5f)) g.DrawEllipse(p, x - r / 2, y - r / 2, r, r);
                TestoBordato(g, Lang.T("Sole"), fm, Color.Yellow, rSole.X, rSole.Y);
            }

            // Luna
            if (skyMoon.El >= SkyElMin)
            {
                float x = X(skyMoon.Az), y = Y(skyMoon.El), r = S(18);
                using (Brush b = new SolidBrush(Color.FromArgb(240, 240, 230))) g.FillEllipse(b, x - r / 2, y - r / 2, r, r);
                using (Pen p = new Pen(Color.Black, 2)) g.DrawEllipse(p, x - r / 2 - 3, y - r / 2 - 3, r + 6, r + 6);
                TestoBordato(g, tLuna, fm, Color.White, rLuna.X, rLuna.Y);
            }

            // Legenda: scala dei colori dal blu al rosso
            {
                float lw = S(330), lh = S(14), lx = a.Right - lw - S(14), ly = a.Top + S(10);
                using (Brush bg = new SolidBrush(Color.FromArgb(190, 0, 0, 0))) g.FillRectangle(bg, lx - S(8), ly - S(6), lw + S(16), lh + S(chkSkyLim.Checked ? 84 : 62));
                for (int i = 0; i < (int)lw; i++)
                {
                    double t = skyTlo * Math.Pow(skyThi / skyTlo, i / (double)lw);
                    using (Pen p = new Pen(ColoreCielo(t))) g.DrawLine(p, lx + i, ly, lx + i, ly + lh);
                }
                using (Brush tb = new SolidBrush(Color.White))
                {
                    TestoBordato(g, skyTlo.ToString("F0", ci) + " K", fs, Color.White, lx - S(2), ly + lh + S(3));
                    string hi = "≥ " + skyThi.ToString("F0", ci) + " K";
                    TestoBordato(g, hi, fs, Color.White, lx + lw - g.MeasureString(hi, fs).Width, ly + lh + S(3));
                    TestoBordato(g, Lang.T("rumore del cielo a ") + skyFreq.ToString("0.###", ci) + " MHz", fs, Color.White, lx, ly + lh + S(28));
                    if (chkSkyLim.Checked)
                        using (Font fp = new Font(Lang.FontUi, 10F))
                            TestoBordato(g, Lang.T("righe diagonali grigie = fuori dai limiti della tua antenna"), fp, Color.FromArgb(225, 225, 225), lx, ly + lh + S(56));
                }
            }
            fs.Dispose();
            fm.Dispose();
            tbGrid.Dispose();
        }

        // ---------- Scelta delle linguette su due livelli: gruppi e linguette del gruppo ----------

        class GruppoNav
        {
            public string Nome, Icona;
            public TabPage[] Pagine;
            public TabPage Ultima;
        }
        List<GruppoNav> gruppiNav = new List<GruppoNav>();
        PannelloDisegno pnlNav;
        List<KeyValuePair<RectangleF, object>> navZone = new List<KeyValuePair<RectangleF, object>>();
        object navSopra;

        void CostruisciNav()
        {
            gruppiNav.Clear();
            Action<string, string, TabPage[]> add = (nome, icona, pagine) =>
            {
                GruppoNav g = new GruppoNav();
                g.Nome = nome; g.Icona = icona; g.Pagine = pagine; g.Ultima = pagine[0];
                gruppiNav.Add(g);
            };
            add(Lang.T("In diretta"), "◎", new TabPage[] { tpTrack, tpPunt, tpSky });
            add(Lang.T("Pianificazione"), "◐", new TabPage[] { tpDgrd, tpPos, tpMondo });
            add(Lang.T("Collegamento"), "⇄", new TabPage[] { tpBudget, tpSolar, tpExcel, tpDebug });
            add(Lang.T("Log"), "▦", new TabPage[] { tpMap });
            add(Lang.T("Aiuto e tools"), "?", new TabPage[] { tpIstr, tpEme, tpCavi });
            add("Credits and thanks", "★", new TabPage[] { tpAbout, tpContatti, tpLicenza });   // nome non tradotto (scelta dell'autore)

            // le linguette native restano, ma senza intestazioni: si sceglie dalla barra disegnata
            tabs.Appearance = TabAppearance.FlatButtons;
            tabs.SizeMode = TabSizeMode.Fixed;
            tabs.ItemSize = new Size(0, 1);

            pnlNav = new PannelloDisegno();
            pnlNav.Dock = DockStyle.Top;
            pnlNav.Height = S(92);
            pnlNav.BackColor = Tema.Back;
            pnlNav.Paint += DisegnaNav;
            pnlNav.MouseMove += (s, e) =>
            {
                object z = ZonaNav(e.Location);
                pnlNav.Cursor = z != null ? Cursors.Hand : Cursors.Default;
                if (!object.Equals(z, navSopra)) { navSopra = z; pnlNav.Invalidate(); }
            };
            pnlNav.MouseLeave += (s, e) => { navSopra = null; pnlNav.Invalidate(); };
            pnlNav.MouseClick += (s, e) =>
            {
                object z = ZonaNav(e.Location);
                GruppoNav g = z as GruppoNav;
                TabPage p = z as TabPage;
                if (g != null) p = g.Ultima;
                if (p != null) tabs.SelectedTab = p;
                pnlNav.Invalidate();
            };
            tabs.SelectedIndexChanged += (s, e) =>
            {
                GruppoNav g = GruppoDi(tabs.SelectedTab);
                if (g != null) g.Ultima = tabs.SelectedTab;
                if (pnlNav != null) pnlNav.Invalidate();
            };
        }

        GruppoNav GruppoDi(TabPage p)
        {
            foreach (GruppoNav g in gruppiNav) if (Array.IndexOf(g.Pagine, p) >= 0) return g;
            return null;
        }

        object ZonaNav(Point pt)
        {
            foreach (KeyValuePair<RectangleF, object> kv in navZone) if (kv.Key.Contains(pt)) return kv.Value;
            return null;
        }

        bool PaginaSpenta(TabPage p) { return (p == tpSolar || p == tpDebug || p == tpExcel) && !complessi; }

        void DisegnaNav(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            pnlNav.BackColor = Tema.Back;
            Rectangle cr = pnlNav.ClientRectangle;
            navZone.Clear();
            GruppoNav att = GruppoDi(tabs.SelectedTab);
            float h1 = S(44), y1 = S(6);
            float x = S(12);
            // sei gruppi: se non entrano nella larghezza della finestra, il carattere dei gruppi si riduce (fino a 10 px)
            float pxG = S(15);
            for (; pxG > S(10); pxG -= 0.5f)
            {
                float tot = S(12);
                using (Font fgp = FontPx(Lang.FontUi, pxG, true))
                using (Font fip = FontPx("Segoe UI Symbol", pxG, false))
                    foreach (GruppoNav gr in gruppiNav)
                        tot += g.MeasureString(gr.Icona, fip).Width + g.MeasureString(gr.Nome, fgp).Width + pxG * 2f + S(4);
                if (tot <= cr.Width - S(8)) break;
            }
            using (Font fg = FontPx(Lang.FontUi, pxG, true))
            using (Font fi = FontPx("Segoe UI Symbol", pxG, false))
            using (Font fs = FontPx(Lang.FontUi, S(14), false))
            using (Font fsb = FontPx(Lang.FontUi, S(14), true))
            {
                // riga 1: i gruppi, come linguette
                foreach (GruppoNav gr in gruppiNav)
                {
                    float wi = g.MeasureString(gr.Icona, fi).Width, wt = g.MeasureString(gr.Nome, fg).Width;
                    RectangleF r = new RectangleF(x, y1, wi + wt + pxG * 2f, h1);
                    bool on = gr == att, sopra = object.Equals(navSopra, gr);
                    if (on || sopra)
                    {
                        using (GraphicsPath p = new GraphicsPath())
                        {
                            float rr = S(10);
                            p.AddArc(r.Left, r.Top, 2 * rr, 2 * rr, 180, 90);
                            p.AddArc(r.Right - 2 * rr, r.Top, 2 * rr, 2 * rr, 270, 90);
                            p.AddLine(r.Right, r.Bottom + 1, r.Left, r.Bottom + 1);
                            p.CloseFigure();
                            using (Brush b = new SolidBrush(on ? Tema.Section : Color.FromArgb(90, Tema.Section))) g.FillPath(b, p);
                            if (on) using (Pen pn = new Pen(Tema.Linea)) g.DrawPath(pn, p);
                        }
                    }
                    Color c = on ? Tema.Fore : Tema.Muted;
                    Testo(g, gr.Icona, fi, on ? Tema.Accent : c, new RectangleF(r.Left + pxG * 0.8f, r.Top, wi + S(4), r.Height), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, gr.Nome, fg, c, new RectangleF(r.Left + pxG * 0.93f + wi, r.Top, wt + S(6), r.Height), StringAlignment.Near, StringAlignment.Center);
                    navZone.Add(new KeyValuePair<RectangleF, object>(r, gr));
                    x = r.Right + S(4);
                }
                // fascia della riga 2
                RectangleF fascia = new RectangleF(0, y1 + h1, cr.Width, cr.Height - y1 - h1);
                using (Brush b = new SolidBrush(Tema.Section)) g.FillRectangle(b, fascia);
                using (Pen pn = new Pen(Tema.Linea)) g.DrawLine(pn, 0, fascia.Top, cr.Width, fascia.Top);
                if (att == null) return;
                // riga 2: le linguette del gruppo scelto
                x = S(26);
                foreach (TabPage p in att.Pagine)
                {
                    bool on = p == tabs.SelectedTab, spenta = PaginaSpenta(p), sopra = object.Equals(navSopra, p);
                    Font f = on ? fsb : fs;
                    float wt = g.MeasureString(p.Text, f).Width;
                    RectangleF r = new RectangleF(x, fascia.Top, wt + S(8), fascia.Height);
                    Color c = spenta ? Color.FromArgb(Tema.Scuro ? 90 : 140, Tema.Muted) : (on ? Tema.Fore : (sopra ? Tema.Fore : Tema.Muted));
                    Testo(g, p.Text, f, c, r, StringAlignment.Center, StringAlignment.Center);
                    if (on) using (Brush b = new SolidBrush(Tema.Accent)) g.FillRectangle(b, r.Left, r.Bottom - S(4), r.Width, S(3));
                    navZone.Add(new KeyValuePair<RectangleF, object>(r, p));
                    x = r.Right + S(26);
                }
            }
        }


        // ---------- Linguetta DEBUG FORMULE: documento in stile Word con le formule del Budget EME e del Rumore solare ----------

        DocView docDebug;
        ComboBox cmbDbgDir, cmbDbgZoom;

        void BuildDebugTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 1; root.RowCount = 2;
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Margin = new Padding(0); root.Padding = new Padding(0);
            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true; bar.Dock = DockStyle.Fill; bar.Padding = new Padding(S(6), S(3), S(6), S(3));
            cmbDbgDir = new ComboBox(); cmbDbgDir.DropDownStyle = ComboBoxStyle.DropDownList; cmbDbgDir.Width = S(170);
            cmbDbgDir.Items.AddRange(new object[] { Lang.T("tu → DX e DX → tu"), Lang.T("tu → DX"), Lang.T("DX → tu") });
            cmbDbgDir.SelectedIndex = 0;
            cmbDbgDir.SelectedIndexChanged += (s, e) => RiempiDebug();
            cmbDbgZoom = new ComboBox(); cmbDbgZoom.DropDownStyle = ComboBoxStyle.DropDownList; cmbDbgZoom.Width = S(80);
            cmbDbgZoom.Items.AddRange(new object[] { "75 %", "100 %", "125 %", "150 %" });
            cmbDbgZoom.SelectedIndex = 1;
            cmbDbgZoom.SelectedIndexChanged += (s, e) => { docDebug.Zoom = new float[] { 0.75f, 1f, 1.25f, 1.5f }[cmbDbgZoom.SelectedIndex]; docDebug.Aggiorna(); };
            Button bc = new Button(); bc.Text = Lang.T("Copia negli appunti"); bc.AutoSize = true;
            bc.Click += (s, e) => { try { Clipboard.SetText(docDebug.TestoSemplice()); } catch { } };
            Button bw = new Button(); bw.Text = Lang.T("Salva in Word (.docx)"); bw.AutoSize = true;
            bw.Click += (s, e) =>
            {
                using (SaveFileDialog d = new SaveFileDialog())
                {
                    d.Filter = "Word (*.docx)|*.docx";
                    d.FileName = "YAEC_debug_" + curBand.ToString(inv) + "MHz_" + DateTime.UtcNow.ToString("yyyyMMdd_HHmm", inv) + ".docx";
                    if (d.ShowDialog(this) != DialogResult.OK) return;
                    try { docDebug.SalvaDocx(d.FileName, Lang.T("DEBUG FORMULE")); }
                    catch (Exception ex) { Messaggio(this, Lang.T("Impossibile salvare il file:\n") + ex.Message, "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Error); }
                }
            };
            Label sp = new Label(); sp.AutoSize = true; sp.Width = S(30);
            bar.Controls.Add(L(Lang.T("Direzione"))); bar.Controls.Add(cmbDbgDir);
            bar.Controls.Add(L(Lang.T("Zoom"))); bar.Controls.Add(cmbDbgZoom);
            bar.Controls.Add(sp); bar.Controls.Add(bc); bar.Controls.Add(bw);
            tip.SetToolTip(bar, Lang.T("Tutti i parametri e le formule del Budget EME e del Rumore solare, con i valori sostituiti e i risultati, per l'istante e la banda scelti nel Budget EME. Si aggiorna a ogni ricalcolo."));
            root.Controls.Add(bar, 0, 0);
            docDebug = new DocView();
            docDebug.Dock = DockStyle.Fill;
            docDebug.Pagine = true;
            docDebug.Scala = scale;
            docDebug.Rtl = Lang.Rtl;
            docDebug.Intestazione = "YAEC " + Versione + " · " + Lang.T("DEBUG FORMULE");
            root.Controls.Add(docDebug, 0, 1);
            tp.Controls.Add(root);
        }

        string Fd(double v, string fmt) { return double.IsNaN(v) ? "-" : (double.IsInfinity(v) ? (v > 0 ? "+∞" : "-∞") : v.ToString(fmt, ci)); }

        // numero in notazione scientifica per le formule: 6,164 · 10^{11}
        string Sci(double v, int dec)
        {
            if (v == 0 || double.IsNaN(v) || double.IsInfinity(v)) return Fd(v, "F" + dec);
            int e = (int)Math.Floor(Math.Log10(Math.Abs(v)));
            double m = v / Math.Pow(10, e);
            return m.ToString("F" + dec, ci) + " · 10^{" + (e < 0 ? "−" + (-e).ToString(inv) : e.ToString(inv)) + "}";
        }

        List<DocBlocco> dbg;
        int dbgSez, dbgSotto, dbgEq;

        void DSez(string t) { dbgSez++; dbgSotto = 0; dbgEq = 0; dbg.Add(DocBlocco.P(DocTipo.Sez, dbgSez.ToString(inv) + ". " + t)); }
        void DSotto(string t) { dbgSotto++; dbg.Add(DocBlocco.P(DocTipo.Sotto, dbgSez.ToString(inv) + "." + dbgSotto.ToString(inv) + " " + t)); }
        // un passo: titolo, formula simbolica, formula con i valori, risultato evidenziato
        void DPasso(string nome, string formula, string valori, string risultato)
        {
            if (nome != null) DSotto(nome);
            if (formula == null && valori == null) { dbg.Add(DocBlocco.P(DocTipo.Par, risultato)); return; }
            DocBlocco f = DocBlocco.P(DocTipo.Formula, formula ?? valori);
            f.Valori = formula == null ? null : valori;
            f.Risultato = risultato;
            dbgEq++;
            f.Num = "(" + dbgSez.ToString(inv) + "." + dbgEq.ToString(inv) + ")";
            dbg.Add(f);
        }
        void DNota(string t) { dbg.Add(DocBlocco.P(DocTipo.Didascalia, t)); }

        void RiempiDebug()
        {
            if (docDebug == null || tabs == null || tabs.SelectedTab != tpDebug) return;
            dbg = new List<DocBlocco>();
            dbgSez = 0;
            dbg.Add(DocBlocco.P(DocTipo.Titolo, Lang.T("Debug delle formule – Budget EME e Rumore solare")));
            BudgetParams.Freq = curBand;
            BudgetParams pm = BudgetParams.FromUi(bMe), pd = BudgetParams.FromUi(bDx);
            if (!me.Ok || !chkDx.Checked || !dx.Ok)
            {
                dbg.Add(DocBlocco.P(DocTipo.Box, Lang.T("Imposta un locator valido per la tua stazione e attiva la seconda stazione") + " " + Lang.T("nella linguetta \"Posizione della Luna\": servono le posizioni di entrambe.")));
                docDebug.Blocchi = dbg; docDebug.Aggiorna();
                return;
            }
            double freq = curBand, bw = LeggiBw();
            DateTime t = DateTime.SpecifyKind(dtpB.Value, DateTimeKind.Utc);
            Riga r = Calcola1(t, true, freq, chkRefr.Checked);
            double path = Moon.PathLoss(freq, r.P.DistTopo, r.Q.DistTopo);
            double pol = chkPol.Checked ? r.PolLoss : 0.0;
            double tskyDx = Moon.Tsky(r.Q.Lambda, freq), tskyMe = Moon.Tsky(r.P.Lambda, freq);
            double ggMe = pm.GroundOn > 0.5 ? GroundGain(pm.GroundH, r.P.El, freq) : 0.0;
            double ggDx = pd.GroundOn > 0.5 ? GroundGain(pd.GroundH, r.Q.El, freq) : 0.0;
            Tratta a = CalcTratta(pm, pd, path, pol, tskyDx, 0, bw, ggMe, ggDx, 0, freq);
            Tratta b = CalcTratta(pd, pm, path, pol, tskyMe, 0, bw, ggDx, ggMe, 0, freq);
            SolarInfo sa = CalcSolar(t, r.Q, dx, pd, freq, false), sbs = CalcSolar(t, r.P, me, pm, freq, true);
            int dir = cmbDbgDir.SelectedIndex;

            DocBlocco intest = DocBlocco.P(DocTipo.Tabella, "");
            intest.Righe = new List<string[]>();
            intest.Righe.Add(new string[] { Lang.T("Istante e banda"), Lang.T("La mia stazione"), Lang.T("Stazione DX") });
            intest.Righe.Add(new string[] { FmtDT(t) + " UTC · " + freq.ToString(inv) + " MHz · B = " + bw.ToString("0", ci) + " Hz", me.Loc.Text.Trim(), dx.Loc.Text.Trim() });
            dbg.Add(intest);

            // 1. parametri di ingresso
            DSez(Lang.T("Parametri di ingresso"));
            DocBlocco tp_ = DocBlocco.P(DocTipo.Tabella, "");
            tp_.Righe = new List<string[]>();
            tp_.Destra = new bool[] { false, true, true };
            tp_.Righe.Add(new string[] { Lang.T("Parametro"), Lang.T("La mia stazione"), Lang.T("Stazione DX") });
            tp_.Righe.Add(new string[] { Lang.T("Potenza in uscita") + " §P§", Fd(pm.P, "0.###") + " W", Fd(pd.P, "0.###") + " W" });
            tp_.Righe.Add(new string[] { Lang.T("Cavo PA – relè + relè + cavo antenna") + " §L_{TX}§", Fd(pm.LossPa, "0.00") + " + " + Fd(pm.Rele, "0.00") + " + " + Fd(pm.LossAnt, "0.00") + " dB", Fd(pd.LossPa, "0.00") + " + " + Fd(pd.Rele, "0.00") + " + " + Fd(pd.LossAnt, "0.00") + " dB" });
            tp_.Righe.Add(new string[] { Lang.T("Antenne") + " §N × G_{ant}§", pm.NAnt + " × " + Fd(pm.GAnt, "0.00") + " dBi", pd.NAnt + " × " + Fd(pd.GAnt, "0.00") + " dBi" });
            tp_.Righe.Add(new string[] { Lang.T("Prima del preampli") + " §L_{pre}§", Fd(pm.PreLoss, "0.00") + " dB", Fd(pd.PreLoss, "0.00") + " dB" });
            tp_.Righe.Add(new string[] { Lang.T("Preampli") + " §G_{pre}§, NF", Fd(pm.PreGain, "0.0") + " dB, " + Fd(pm.Nf, "0.00") + " dB", Fd(pd.PreGain, "0.0") + " dB, " + Fd(pd.Nf, "0.00") + " dB" });
            tp_.Righe.Add(new string[] { Lang.T("Cavo di discesa") + " §L_{post}§", Fd(pm.PostLoss, "0.00") + " dB", Fd(pd.PostLoss, "0.00") + " dB" });
            tp_.Righe.Add(new string[] { Lang.T("Transverter") + " §G_{tv}§, NF", pm.TvOn > 0.5 ? Fd(pm.TvGain, "0.0") + " dB, " + Fd(pm.TvNf, "0.0") + " dB" : "–", pd.TvOn > 0.5 ? Fd(pd.TvGain, "0.0") + " dB, " + Fd(pd.TvNf, "0.0") + " dB" : "–" });
            tp_.Righe.Add(new string[] { Lang.T("Cavetti fino alla radio"), Fd(pm.TvCavo, "0.0") + " dB", Fd(pd.TvCavo, "0.0") + " dB" });
            tp_.Righe.Add(new string[] { Lang.T("MDS della radio"), Fd(pm.Mds, "0") + " dBm", Fd(pd.Mds, "0") + " dBm" });
            tp_.Righe.Add(new string[] { Lang.T("Modo · soglia tipica (riferimento)"), pm.NomeModo + " · " + Fd(pm.SnReq, "0.#") + " dB", pd.NomeModo + " · " + Fd(pd.SnReq, "0.#") + " dB" });
            tp_.Righe.Add(new string[] { "§T_{ant}§", Fd(pm.Tant, "0") + " K", Fd(pd.Tant, "0") + " K" });
            tp_.Righe.Add(new string[] { Lang.T("Luna: Az / El / distanza topocentrica"), string.Format(ci, "{0:F1}° / {1:F1}° / {2:N0} km", r.P.Az, r.P.El, r.P.DistTopo), string.Format(ci, "{0:F1}° / {1:F1}° / {2:N0} km", r.Q.Az, r.Q.El, r.Q.DistTopo) });
            dbg.Add(tp_);
            DNota("Dpol = " + Fd(r.Dpol, "F1") + "°" + (chkPol.Checked ? "" : "  (" + Lang.T("non inclusa") + ")") + " · k = 1,380649 · 10⁻²³ J/K");

            // 2. percorso comune
            DSez(Lang.T("Percorso Terra – Luna – Terra"));
            double lambda = 299.792458 / freq, rm = 1737.4e3, sigma = 0.065 * Math.PI * rm * rm;
            DPasso(Lang.T("Lunghezza d'onda e sezione radar della Luna"), "λ = \\frac{c}{f}", "\\frac{299,792458}{" + freq.ToString("0.###", ci) + "}", Fd(lambda, "0.0000") + " m");
            DPasso(null, "σ = 0,065 · π · R_L^2", "0,065 · π · \\p{1,7374 · 10^{6}}^2", Sci(sigma, 3) + " m^2");
            DPasso(Lang.T("Perdita di tratta EME"), "L_{EME} = 10 · log_{10} \\frac{\\p{4π}^3 d_1^2 d_2^2}{σ λ^2}",
                "10 · log_{10} \\frac{\\p{4π}^3 · \\p{" + Sci(r.P.DistTopo * 1000, 5) + "}^2 · \\p{" + Sci(r.Q.DistTopo * 1000, 5) + "}^2}{" + Sci(sigma, 3) + " · " + Fd(lambda, "0.0000") + "^2}",
                Fd(path, "0.00") + " dB");
            DPasso(Lang.T("Perdita di polarizzazione spaziale"), "L_{pol} = −20 · log_{10} \\a{cos D_{pol}}", "−20 · log_{10} \\a{cos " + Fd(r.Dpol, "0.0") + "°}",
                Fd(r.PolLoss, "0.00") + " dB");
            if (!chkPol.Checked) DNota(Lang.T("non inclusa") + " → 0 dB");

            if (dir != 2) DebugTratta(Lang.T("La mia stazione") + " → DX", pm, pd, a, ggMe, ggDx, r.P.El, r.Q.El, path, pol, tskyDx, freq, bw);
            if (dir != 1) DebugTratta("DX → " + Lang.T("La mia stazione"), pd, pm, b, ggDx, ggMe, r.Q.El, r.P.El, path, pol, tskyMe, freq, bw);
            if (complessi)
            {
                if (dir != 2) DebugSole("DX", sa, pd, a, pm, pd, path, pol, tskyDx, bw, ggMe, ggDx, freq, (double)nudSlDx.Value);
                if (dir != 1) DebugSole(Lang.T("La mia stazione"), sbs, pm, b, pd, pm, path, pol, tskyMe, bw, ggDx, ggMe, freq, (double)nudSlMe.Value);
            }
            int prima = -docDebug.AutoScrollPosition.Y;
            docDebug.Blocchi = dbg;
            docDebug.Aggiorna();
            docDebug.AutoScrollPosition = new Point(0, prima);
        }

        void DebugTratta(string titolo, BudgetParams tx, BudgetParams rx, Tratta t, double ggTx, double ggRx, double elTx, double elRx,
            double path, double pol, double tsky, double freq, double bw)
        {
            DSez(titolo);
            double lambda = 299.792458 / freq;
            DPasso(Lang.T("Potenza in uscita"), "P_{dBW} = 10 · log_{10} P", "10 · log_{10} " + Fd(tx.P, "0.###"), Fd(t.PdBW, "0.00") + " dBW");
            DPasso(Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna)"), "L_{TX} = L_{PA} + L_{relè} + L_{ant}", Fd(tx.LossPa, "0.00") + " + " + Fd(tx.Rele, "0.00") + " + " + Fd(tx.LossAnt, "0.00"), Fd(t.LossTx, "0.00") + " dB");
            DPasso(Lang.T("Potenza all'antenna"), "P_{ant} = P · 10^{−L_{TX}/10}", Fd(tx.P, "0.###") + " · 10^{−" + Fd(t.LossTx, "0.00") + "/10}", Fd(t.PantW, "0.0") + " W");
            if (tx.GroundOn > 0.5)
                DPasso(Lang.T("BETA - ground gain antenna TX senza elevazione"), "G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}}",
                    string.Format(ci, "h = {0:0.#} \\t{{ m, }} El = {1:F2}°, λ = {2:F4} \\t{{ m}}", tx.GroundH, elTx, lambda), Fd(ggTx, "0.00") + " dB");
            DPasso(Lang.T("Guadagno antenna TX totale"), "G_{TX} = G_{ant} + 10 · log_{10} N + G_g", Fd(tx.GAnt, "0.00") + " + 10 · log_{10} " + tx.NAnt + " + " + Fd(ggTx, "0.00"), Fd(t.Gtx, "0.00") + " dBi");
            DPasso("EIRP", "EIRP = P_{dBW} − L_{TX} + G_{TX}", Fd(t.PdBW, "0.00") + " − " + Fd(t.LossTx, "0.00") + " + " + Fd(t.Gtx, "0.00"), Fd(t.EirpDbW, "0.00") + " dBW");
            DNota("EIRP = " + FmtW(Math.Pow(10.0, t.EirpDbW / 10.0), ci));
            if (rx.GroundOn > 0.5)
                DPasso(Lang.T("BETA - ground gain antenna RX senza elevazione"), "G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}}",
                    string.Format(ci, "h = {0:0.#} \\t{{ m, }} El = {1:F2}°, λ = {2:F4} \\t{{ m}}", rx.GroundH, elRx, lambda), Fd(ggRx, "0.00") + " dB");
            DPasso(Lang.T("Guadagno antenna RX totale"), "G_{RX} = G_{ant} + 10 · log_{10} N + G_g", Fd(rx.GAnt, "0.00") + " + 10 · log_{10} " + rx.NAnt + " + " + Fd(ggRx, "0.00"), Fd(t.Grx, "0.00") + " dBi");
            DPasso(Lang.T("Segnale ai morsetti dell'antenna RX"), "S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                Fd(t.EirpDbW, "0.00") + " + 30 − " + Fd(path, "0.00") + " − " + Fd(pol, "0.00") + " + " + Fd(t.Grx, "0.00"), Fd(t.Sant, "0.00") + " dBm");
            DPasso(Lang.T("All'ingresso della radio (dopo i cavetti)"), "S_5 = S_{ant} − L_{pre} + G_{pre} − L_{post} + G_{tv} − L_{cav}",
                Fd(t.Sant, "0.00") + " − " + Fd(rx.PreLoss, "0.00") + " + " + Fd(rx.PreGain, "0.0") + " − " + Fd(rx.PostLoss, "0.00") + " + " + Fd(rx.TvGain, "0.0") + " − " + Fd(rx.TvCavo, "0.0"),
                Fd(t.S5, "0.00") + " dBm");
            DPasso(Lang.T("Margine sopra il MDS"), "M_{MDS} = S_5 − MDS", Fd(t.S5, "0.00") + " − \\p{" + Fd(rx.Mds, "0") + "}", Fd(t.Margin, "0.00") + " dB");
            DPasso(Lang.T("NF della radio dal MDS"), "NF_{radio} = MDS + 174 − 10 · log_{10} B", Fd(rx.Mds, "0") + " + 174 − 10 · log_{10} " + Fd(bw, "0"), Fd(t.NfRadio, "0.00") + " dB");
            double[] fl = { Math.Pow(10.0, rx.PreLoss / 10.0), Math.Pow(10.0, rx.Nf / 10.0), Math.Pow(10.0, rx.PostLoss / 10.0),
                rx.TvGain == 0 ? 1.0 : Math.Pow(10.0, rx.TvNf / 10.0), Math.Pow(10.0, rx.TvCavo / 10.0), Math.Pow(10.0, t.NfRadio / 10.0) };
            double[] gl = { Math.Pow(10.0, -rx.PreLoss / 10.0), Math.Pow(10.0, rx.PreGain / 10.0), Math.Pow(10.0, -rx.PostLoss / 10.0),
                Math.Pow(10.0, rx.TvGain / 10.0), Math.Pow(10.0, -rx.TvCavo / 10.0), 1.0 };
            StringBuilder vf = new StringBuilder(Fd(fl[0], "0.000"));
            double gc = gl[0];
            for (int i = 1; i < fl.Length; i++) { vf.Append(" + \\frac{" + Fd(fl[i], "0.000") + " − 1}{" + (gc < 10000 ? Fd(gc, "0.###") : Sci(gc, 3)) + "}"); gc *= gl[i]; }
            DPasso(Lang.T("Ricevitore (Friis)"), "F = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + …", vf.ToString(),
                Fd(Math.Pow(10.0, t.NfTot / 10.0), "0.0000") + " \\t{  (NF } " + Fd(t.NfTot, "0.000") + " \\t{ dB)}");
            DPasso("Te", "T_e = 290 · \\p{10^{NF/10} − 1}", "290 · \\p{10^{" + Fd(t.NfTot, "0.000") + "/10} − 1}", Fd(t.Tloss, "0.0") + " K");
            double rif = TskyRif(freq);
            double t144 = (tsky - 2.7) / Math.Pow(144.0 / freq, 2.6) + 2.7;
            DPasso(Lang.T("Temperatura del cielo dietro la Luna (Tsky)"), "T_{sky} = \\p{T_{144} − 2,7} · \\p{\\frac{144}{f}}^{2,6} + 2,7",
                "\\p{" + Fd(t144, "0.0") + " − 2,7} · \\p{\\frac{144}{" + freq.ToString("0.###", ci) + "}}^{2,6} + 2,7", Fd(tsky, "0.0") + " K");
            DPasso("ΔTsky", "ΔT_{sky} = max \\p{0, T_{sky} − T_{rif}}", "max \\p{0, " + Fd(tsky, "0.0") + " − " + Fd(rif, "0.0") + "}", Fd(t.TskyEcc, "0.0") + " K");
            DPasso("Tsys", "T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e", Fd(t.Tant, "0.0") + " + " + Fd(t.TskyEcc, "0.0") + " + 0 + " + Fd(t.Tloss, "0.0"), Fd(t.Tsys, "0.0") + " K");
            DPasso(Lang.T("Rumore nella banda passante"), "N = 10 · log_{10} \\p{k · T_{sys} · B} + 30",
                "10 · log_{10} \\p{1,3806 · 10^{−23} · " + Fd(t.Tsys, "0.0") + " · " + Fd(bw, "0") + "} + 30", Fd(t.Nb, "0.00") + " dBm");
            DPasso("S/N", "\\frac{S}{N} = S_{ant} − N", Fd(t.Sant, "0.00") + " − \\p{" + Fd(t.Nb, "0.00") + "}", Fd(t.SNb, "0.00") + " dB");
            double s25 = Sn2500(t.SNb, bw);
            DPasso(string.Format(ci, Lang.T("S/N riportato a 2500 Hz (soglia tipica {0}: {1}, solo riferimento)"), rx.NomeModo, Fd(rx.SnReq, "0.#") + " dB"),
                "\\frac{S}{N}_{2500} = \\frac{S}{N} + 10 · log_{10} \\frac{B}{2500}",
                Fd(t.SNb, "0.00") + " + 10 · log_{10} \\frac{" + Fd(bw, "0") + "}{2500}", (s25 >= 0 ? "+" : "") + Fd(s25, "0.00") + " dB");
        }

        void DebugSole(string ricevente, SolarInfo s, BudgetParams rx, Tratta senza, BudgetParams ptx, BudgetParams prx, double path, double pol, double tsky,
            double bw, double ggTx, double ggRx, double freq, double sl)
        {
            DSez(Lang.T("RUMORE SOLARE (SPERIMENTALE) - stazione che riceve") + ": " + ricevente);
            double lambda = 299.792458 / freq;
            double glin = Math.Pow(10.0, (rx.GAnt + 10.0 * Math.Log10(rx.NAnt)) / 10.0);
            DPasso(Lang.T("Flusso solare a ") + freq.ToString(inv) + " MHz", null, null, SfuTxt(s) + " · " + FluxTxt(s));
            DPasso(Lang.T("Sole visto dal ricevitore"), null, null, string.Format(ci, "Az {0:F2}°  El {1:F2}°", s.SunAz, s.SunEl));
            DPasso(Lang.T("Distanza angolare Sole - Luna"), "cos θ = sin δ_s sin δ_m + cos δ_s cos δ_m cos \\p{α_s − α_m}", null, Fd(s.Sep, "0.00") + "°");
            DPasso("G (" + Lang.T("lineare") + ")", "G = 10^{\\p{G_{ant} + 10 · log_{10} N}/10}", "10^{\\p{" + Fd(rx.GAnt, "0.00") + " + 10 · log_{10} " + rx.NAnt + "}/10}", Fd(glin, "0.0"));
            DPasso(Lang.T("Larghezza del fascio RX stimata (-3 dB)"), "θ_{3dB} = \\sqrt{\\frac{41253}{G}}", "\\sqrt{\\frac{41253}{" + Fd(glin, "0.0") + "}}", Fd(s.Beam, "0.00") + "°");
            double gauss = Math.Exp(-4.0 * Math.Log(2.0) * (s.Sep / s.Beam) * (s.Sep / s.Beam));
            DPasso(Lang.T("Guadagno del diagramma verso il Sole"), "a = exp \\p{−4 ln 2 · \\p{\\frac{θ}{θ_{3dB}}}^2}",
                "exp \\p{−4 ln 2 · \\p{\\frac{" + Fd(s.Sep, "0.00") + "}{" + Fd(s.Beam, "0.00") + "}}^2} = " + Sci(gauss, 3),
                (double.IsInfinity(s.AttDb) ? "−∞" : Fd(s.AttDb, "0.00")) + " dB");
            DNota(s.Zona + " · " + Lang.T("lobi laterali") + ": SL = " + Fd(sl, "0.#") + " dB; " + Lang.T("lobi posteriori") + ": SL − 10 dB");
            double ae = glin * lambda * lambda / (4.0 * Math.PI);
            DPasso(Lang.T("Area efficace"), "A_e = \\frac{G · λ^2}{4π}", "\\frac{" + Fd(glin, "0.0") + " · " + Fd(lambda, "0.0000") + "^2}{4π}", Fd(ae, "0.000") + " m^2");
            if (!s.Valid) { DPasso(Lang.T("Temperatura aggiunta dal Sole"), null, null, Lang.T("non disponibile")); return; }
            DPasso(Lang.T("Temperatura aggiunta dal Sole"), "T_{sun} = \\frac{S · 10^{−22} · A_e}{2k} · a",
                "\\frac{" + Fd(s.Flux, "0.0") + " · 10^{−22} · " + Fd(ae, "0.000") + "}{2 · 1,3806 · 10^{−23}} · " + (double.IsInfinity(s.AttDb) ? "0" : Sci(Math.Pow(10.0, s.AttDb / 10.0), 3)),
                Fd(s.Tsun, "0.0") + " K");
            Tratta con = CalcTratta(ptx, prx, path, pol, tsky, s.Tsun, bw, ggTx, ggRx, 0, freq);
            DPasso(Lang.T("Tsys senza Sole / con Sole"), "T'_{sys} = T_{sys} + T_{sun}", Fd(senza.Tsys, "0.0") + " + " + Fd(s.Tsun, "0.0"), Fd(con.Tsys, "0.0") + " K");
            DPasso(Lang.T("Aumento del rumore dovuto al Sole"), "ΔN = 10 · log_{10} \\frac{T'_{sys}}{T_{sys}}", "10 · log_{10} \\frac{" + Fd(con.Tsys, "0.0") + "}{" + Fd(senza.Tsys, "0.0") + "}",
                Fd(10.0 * Math.Log10(con.Tsys / senza.Tsys), "0.00") + " dB");
            DPasso(Lang.T("S/N in ") + Fd(bw, "0") + Lang.T(" Hz con il Sole"), "\\frac{S}{N}' = S_{ant} − N'", Fd(con.Sant, "0.00") + " − \\p{" + Fd(con.Nb, "0.00") + "}", Fd(con.SNb, "0.00") + " dB");
        }

        // ---------- Avviso di assorbimento polare (PCA) e aurorale ----------

        // Polo geomagnetico nord del dipolo IGRF-14 per il 2025
        const double PoloGmLat = 80.8, PoloGmLon = -72.8;

        static double LatGeomagnetica(double lat, double lon)
        {
            double d = Math.PI / 180.0;
            double s = Math.Sin(lat * d) * Math.Sin(PoloGmLat * d) + Math.Cos(lat * d) * Math.Cos(PoloGmLat * d) * Math.Cos((lon - PoloGmLon) * d);
            return Math.Asin(Math.Max(-1.0, Math.Min(1.0, s))) / d;
        }

        // 0 nessuna, 1 zona aurorale (60-75° geomagnetici), 2 calotta polare (oltre il circolo polare o oltre 75° geomagnetici)
        static int ZonaAssorbimento(double lat, double lon, out double latGm)
        {
            latGm = LatGeomagnetica(lat, lon);
            if (Math.Abs(lat) >= 66.56 || Math.Abs(latGm) > 75.0) return 2;
            if (Math.Abs(latGm) >= 60.0) return 1;
            return 0;
        }

        string avvisatoMe = "", avvisatoDx = "";
        Timer timerZone;

        void AgganciaAvvisiZone()
        {
            timerZone = new Timer();
            timerZone.Interval = 1500;
            timerZone.Tick += (s, e) => { timerZone.Stop(); ControllaZone(true); ControllaDpol(true); };
            EventHandler riparti = (s, e) => { if (caricamento) return; timerZone.Stop(); timerZone.Start(); };
            me.Loc.TextChanged += riparti;
            dx.Loc.TextChanged += riparti;
            chkDx.CheckedChanged += riparti;
        }

        // Avviso di polarizzazione (v28e): se nelle prossime 24 ore, con la Luna sopra l'orizzonte di entrambe le stazioni,
        // |Dpol| arriva a 60° o più, la perdita con antenne a polarizzazione lineare diventa forte (6 dB a 60°, molto di più
        // verso 90°). Capita soprattutto tra stazioni lontane, per esempio tra emisfero boreale e australe.
        // Fonte indicata da IC8TEM: le videointerviste di Franco I2FAK su YouTube. Una volta per coppia di quadrati.
        string avvisatoDpol = "";

        void ControllaDpol(bool popup)
        {
            if (!me.Ok || !chkDx.Checked || !dx.Ok) { avvisatoDpol = ""; return; }
            string l1 = me.Loc.Text.Trim().ToUpperInvariant(), l2 = dx.Loc.Text.Trim().ToUpperInvariant();
            string chiave = (l1.Length >= 4 ? l1.Substring(0, 4) : l1) + "|" + (l2.Length >= 4 ? l2.Substring(0, 4) : l2);
            if (chiave == avvisatoDpol) return;
            avvisatoDpol = chiave;
            if (!popup) return;
            double f;
            if (!ReadFreq(out f)) f = 144;
            double dmax = 0;
            DateTime tmax = DateTime.UtcNow;
            bool visibile = false;
            for (int k = 0; k < 48; k++)
            {
                DateTime t = DateTime.UtcNow.AddMinutes(30 * k);
                Riga r = Calcola1(t, true, f, false);
                if (r.P.El < 0 || r.Q.El < 0) continue;
                visibile = true;
                if (Math.Abs(r.Dpol) > Math.Abs(dmax)) { dmax = r.Dpol; tmax = t; }
            }
            if (!visibile || Math.Abs(dmax) < 60) return;
            string testo = string.Format(ci, Lang.T("Nelle prossime 24 ore Dpol arriva a {0:F0}° (alle {1} UTC): con antenne a polarizzazione lineare la perdita è di {2:F1} dB."),
                    dmax, tmax.ToString("HH:mm", inv), Moon.PolLoss(dmax))
                + "\n" + Lang.T("Tra stazioni lontane, per esempio tra l'emisfero boreale e quello australe, la sola posizione geografica può ruotare molto la polarizzazione; la rotazione di Faraday, non prevedibile, si aggiunge. Valuta la polarizzazione circolare o la commutazione H/V. Fonte: videointerviste di Franco I2FAK su YouTube.");
            Messaggio(this, testo, Lang.T("Polarizzazione tra le due stazioni"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }

        // Una sola volta per ogni nuovo locator (e per ogni cambio di zona) compare l'avviso
        void ControllaZone(bool popup)
        {
            for (int i = 0; i < 2; i++)
            {
                StationUi st = i == 0 ? me : dx;
                string chiave = "";
                double lgm = 0;
                int zona = 0;
                if (st.Ok && (i == 0 || chkDx.Checked))
                {
                    zona = ZonaAssorbimento(st.Lat, st.Lon, out lgm);
                    chiave = st.Loc.Text.Trim().ToUpperInvariant() + "|" + zona.ToString(inv);
                }
                string prima = i == 0 ? avvisatoMe : avvisatoDx;
                if (zona == 0 || chiave == prima) { if (zona == 0) { if (i == 0) avvisatoMe = ""; else avvisatoDx = ""; } continue; }
                if (i == 0) avvisatoMe = chiave; else avvisatoDx = chiave;
                if (!popup) continue;
                string nome = i == 0 ? Lang.T("La mia stazione") : Lang.T("Stazione DX");
                double f;
                if (!ReadFreq(out f)) f = curBand;
                string testo = (zona == 2
                    ? string.Format(ci, Lang.T("{0} ({1}) si trova nella calotta polare: dopo forti eventi solari a protoni può esserci PCA (Polar Cap Absorption), un assorbimento della bassa ionosfera che può durare alcuni giorni."), nome, st.Loc.Text.Trim())
                    : string.Format(ci, Lang.T("{0} ({1}) si trova nella zona aurorale (latitudine geomagnetica {2:F0}°): durante le tempeste geomagnetiche può esserci assorbimento aurorale."), nome, st.Loc.Text.Trim(), lgm))
                    + "\n\n" + string.Format(ci, Lang.T("L'assorbimento diminuisce con la frequenza (circa 1/f²): conta soprattutto a 50 MHz, meno a 144 MHz, ed è di solito trascurabile da 432 MHz in su. Frequenza attuale: {0} MHz."), f.ToString("0.###", ci))
                    + "\n\n" + Lang.T("La situazione attuale si controlla con il servizio NOAA D-RAP: https://www.swpc.noaa.gov/products/d-region-absorption-predictions-d-rap");
                Messaggio(this, testo, Lang.T("Possibile assorbimento ionosferico"), MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        // Riga per la schermata principale
        string AvvisoZona(StationUi st, string nome)
        {
            if (!st.Ok) return "";
            double lgm;
            int z = ZonaAssorbimento(st.Lat, st.Lon, out lgm);
            if (z == 0) return "";
            return "⚠ " + nome + ": " + (z == 2 ? Lang.T("calotta polare, possibile PCA") : Lang.T("zona aurorale, possibile assorbimento"));
        }

        // ---------- Linguetta "Mappa di puntamento": mappa aerea o topografica con la volta celeste in pianta ----------

        PannelloDisegno pnlPunt;
        ComboBox cmbPuntMappa;
        CheckBox chkPuntPercorso, chkPuntSfuma;
        Label lblPuntZoom;
        int puntZoom = 16;
        int puntDrag;                          // 0 nessuna, 1 azimut da, 2 azimut a, 3 elevazione minima, 4 elevazione massima
        bool puntNuovoOn;                      // clic fuori dal cerchio: punto proposto come nuovo locator
        double puntNuovoLat, puntNuovoLon;
        string puntNuovoLoc = "";
        PointF hAz1, hAz2, hEl1, hEl2;         // posizione delle maniglie (aggiornata a ogni disegno)
        bool hEl2Vis;
        List<double[]> puntPercorso = new List<double[]>();   // az, el, ore dall'inizio
        DateTime puntPercorsoT0 = DateTime.MinValue;
        double puntSorgeAz = double.NaN, puntTramAz = double.NaN;
        DateTime puntSorgeT, puntTramT;
        Timer puntTimer;

        // Fondi disponibili: aerofotografico (Esri World Imagery), OpenTopoMap, OpenStreetMap
        static readonly int[] PuntMappe = { 5, 1, 0 };

        TileProvider PuntProv
        {
            get
            {
                int i = cmbPuntMappa == null ? 0 : Math.Max(0, cmbPuntMappa.SelectedIndex);
                return Mappe[PuntMappe[Math.Min(i, PuntMappe.Length - 1)]];
            }
        }

        // Grigio delle zone fuori dai limiti: opacità (solo nella Ricognizione) e tono condiviso da tutte le mappe
        int grigioOpacita = 59, grigioTono = 9;     // percentuali; tono 0 = bianco, 100 = nero
        TrackBar tbOpacita, tbTonoPunt, tbTonoSky;
        Label lblOpacita, lblTonoPunt;
        TableLayoutPanel pnlGrigi;
        bool syncTono;
        int GrigioRgb { get { return (int)Math.Round(255 - grigioTono * 2.55); } }

        TrackBar SliderGrigio(bool punt)
        {
            TrackBar t = new TrackBar();
            t.Minimum = 0; t.Maximum = 100; t.TickFrequency = 10; t.SmallChange = 5; t.LargeChange = 10;
            t.AutoSize = false; t.Height = S(30); t.Width = S(150);
            t.Value = grigioTono;
            t.ValueChanged += (s, e) =>
            {
                if (syncTono) return;
                syncTono = true;
                grigioTono = t.Value;
                foreach (TrackBar x in new TrackBar[] { tbTonoPunt, tbTonoSky }) if (x != null && x != t) x.Value = grigioTono;
                if (lblTonoPunt != null) lblTonoPunt.Text = grigioTono + " %";
                syncTono = false;
                if (pnlPunt != null) pnlPunt.Invalidate();
                if (sky != null) sky.Invalidate();
                if (!caricamento) SaveSettings();
            };
            tip.SetToolTip(t, Lang.T("Tono del grigio delle zone fuori dai limiti, dal bianco al nero: vale per tutte le mappe."));
            return t;
        }

        // Gli slider servono solo se le zone fuori dai limiti sono disegnate
        void AbilitaGrigi()
        {
            if (tbOpacita != null && chkPuntSfuma != null) { tbOpacita.Enabled = chkPuntSfuma.Checked; tbTonoPunt.Enabled = chkPuntSfuma.Checked; }
            if (tbTonoSky != null && chkSkyLim != null) tbTonoSky.Enabled = chkSkyLim.Checked;
        }

        void ImpostaGrigi(int opac, int tono)
        {
            grigioOpacita = Math.Max(0, Math.Min(100, opac));
            grigioTono = Math.Max(0, Math.Min(100, tono));
            if (tbOpacita != null) tbOpacita.Value = grigioOpacita;
            syncTono = true;
            foreach (TrackBar x in new TrackBar[] { tbTonoPunt, tbTonoSky }) if (x != null) x.Value = grigioTono;
            syncTono = false;
            if (lblOpacita != null) lblOpacita.Text = grigioOpacita + " %";
            if (lblTonoPunt != null) lblTonoPunt.Text = grigioTono + " %";
            AbilitaGrigi();
        }

        void BuildPuntTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 1;
            root.RowCount = 2;
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Padding = new Padding(S(4));

            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true;
            bar.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            bar.Dock = DockStyle.Fill;
            cmbPuntMappa = new ComboBox();
            cmbPuntMappa.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbPuntMappa.Items.AddRange(new object[] { Lang.T("Aerofotografica (Esri World Imagery)"), Mappe[1].Nome, Mappe[0].Nome });
            cmbPuntMappa.SelectedIndex = 0;
            cmbPuntMappa.Width = S(280);
            cmbPuntMappa.SelectedIndexChanged += (s, e) =>
            {
                puntZoom = Math.Min(puntZoom, PuntProv.MaxZoom);
                AggiornaZoomPunt();
                if (!caricamento) SaveSettings();
            };
            Button bMeno = new Button();
            bMeno.Text = "−";
            bMeno.Width = S(34);
            bMeno.Click += (s, e) => CambiaZoomPunt(-1);
            Button bPiu = new Button();
            bPiu.Text = "+";
            bPiu.Width = S(34);
            bPiu.Click += (s, e) => CambiaZoomPunt(1);
            lblPuntZoom = L("");
            chkPuntPercorso = new CheckBox();
            chkPuntPercorso.Text = Lang.T("Percorso della Luna nelle prossime 24 ore");
            chkPuntPercorso.AutoSize = true;
            chkPuntPercorso.Checked = true;
            chkPuntPercorso.Margin = new Padding(S(14), S(6), S(3), S(3));
            chkPuntPercorso.CheckedChanged += (s, e) => pnlPunt.Invalidate();
            chkPuntSfuma = new CheckBox();
            chkPuntSfuma.Text = Lang.T("Sfuma le zone fuori dai limiti");
            chkPuntSfuma.AutoSize = true;
            chkPuntSfuma.Checked = true;
            chkPuntSfuma.Margin = new Padding(S(14), S(6), S(3), S(3));
            chkPuntSfuma.CheckedChanged += (s, e) => { pnlPunt.Invalidate(); if (!caricamento) SaveSettings(); };
            Label hint = new Label();
            hint.Text = Lang.T("Trascina le maniglie gialle per spostare i limiti dell'antenna (azimut ed elevazione): i valori cambiano anche nella linguetta Posizione della Luna.");
            hint.AutoSize = true;
            hint.ForeColor = Tema.Muted;
            hint.Margin = new Padding(S(6), S(2), S(3), S(4));
            Label lMappa = L(Lang.T("Mappa"));
            lMappa.AutoSize = true;
            lMappa.Margin = new Padding(S(3), S(6), S(3), S(3));
            bar.Controls.Add(lMappa); bar.Controls.Add(cmbPuntMappa);
            bar.Controls.Add(bMeno); bar.Controls.Add(bPiu); bar.Controls.Add(lblPuntZoom);
            bar.Controls.Add(chkPuntPercorso); bar.Controls.Add(chkPuntSfuma);
            bar.WrapContents = true;
            bar.Controls.Add(hint);
            bar.SetFlowBreak(chkPuntSfuma, true);
            chkPuntSfuma.CheckedChanged += (s, e) => AbilitaGrigi();
            root.Controls.Add(bar, 0, 0);

            pnlPunt = new PannelloDisegno();
            pnlPunt.Dock = DockStyle.Fill;
            pnlPunt.BackColor = Color.FromArgb(14, 22, 40);
            pnlPunt.Paint += DisegnaPunt;
            pnlPunt.Paint += DisegnaNuovoLocPunt;
            pnlPunt.MouseDown += PuntMouseDown;
            pnlPunt.MouseMove += PuntMouseMove;
            pnlPunt.MouseUp += (s, e) => { if (puntDrag != 0) { puntDrag = 0; if (!caricamento) SaveSettings(); } };
            pnlPunt.MouseEnter += (s, e) => pnlPunt.Focus();
            pnlPunt.MouseWheel += (s, e) => CambiaZoomPunt(e.Delta > 0 ? 1 : -1);
            root.Controls.Add(pnlPunt, 0, 1);
            // in alto a destra sulla mappa: opacità e tono del grigio delle zone fuori dai limiti
            pnlGrigi = new TableLayoutPanel();
            pnlGrigi.AutoSize = true;
            pnlGrigi.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            pnlGrigi.ColumnCount = 3;
            pnlGrigi.BackColor = Color.FromArgb(245, 247, 250);
            pnlGrigi.Padding = new Padding(S(8), S(4), S(8), S(4));
            pnlGrigi.Anchor = AnchorStyles.Top | AnchorStyles.Right;
            tbOpacita = new TrackBar();
            tbOpacita.Minimum = 0; tbOpacita.Maximum = 100; tbOpacita.TickFrequency = 10; tbOpacita.SmallChange = 5; tbOpacita.LargeChange = 10;
            tbOpacita.Width = S(150); tbOpacita.AutoSize = false; tbOpacita.Height = S(30);
            tbOpacita.Value = grigioOpacita;
            tbOpacita.ValueChanged += (s, e) => { grigioOpacita = tbOpacita.Value; lblOpacita.Text = grigioOpacita + " %"; pnlPunt.Invalidate(); if (!caricamento) SaveSettings(); };
            tip.SetToolTip(tbOpacita, Lang.T("Opacità del velo grigio sulle zone fuori dai limiti dell'antenna (0 % = trasparente, 100 % = coprente). Si usa con la casella \"Sfuma le zone fuori dai limiti\"."));
            tbTonoPunt = SliderGrigio(true);
            lblOpacita = new Label(); lblOpacita.AutoSize = true; lblOpacita.Text = grigioOpacita + " %"; lblOpacita.ForeColor = Color.FromArgb(29, 36, 51);
            lblTonoPunt = new Label(); lblTonoPunt.AutoSize = true; lblTonoPunt.Text = grigioTono + " %"; lblTonoPunt.ForeColor = Color.FromArgb(29, 36, 51);
            Label l1 = new Label(); l1.Text = Lang.T("Opacità del grigio"); l1.AutoSize = true; l1.ForeColor = Color.FromArgb(29, 36, 51); l1.Anchor = AnchorStyles.Left;
            Label l2 = new Label(); l2.Text = Lang.T("Tono del grigio"); l2.AutoSize = true; l2.ForeColor = Color.FromArgb(29, 36, 51); l2.Anchor = AnchorStyles.Left;
            foreach (Label l in new Label[] { lblOpacita, lblTonoPunt }) l.Anchor = AnchorStyles.Left;
            pnlGrigi.Controls.Add(l1, 0, 0); pnlGrigi.Controls.Add(tbOpacita, 1, 0); pnlGrigi.Controls.Add(lblOpacita, 2, 0);
            pnlGrigi.Controls.Add(l2, 0, 1); pnlGrigi.Controls.Add(tbTonoPunt, 1, 1); pnlGrigi.Controls.Add(lblTonoPunt, 2, 1);
            pnlPunt.Controls.Add(pnlGrigi);
            pnlPunt.Resize += (s, e) => { pnlGrigi.Location = new Point(pnlPunt.ClientSize.Width - pnlGrigi.Width - S(10), S(10)); };
            tp.Controls.Add(root);
            AggiornaZoomPunt();

            puntTimer = new Timer();
            puntTimer.Interval = 30000;
            puntTimer.Tick += (s, e) => { if (tabs != null && tabs.SelectedTab == tpPunt) pnlPunt.Invalidate(); };
            puntTimer.Start();
        }

        // I limiti cambiati in altre linguette ridisegnano la mappa
        void AgganciaLimitiPunt()
        {
            foreach (NumericUpDown n in new NumericUpDown[] { me.Az1, me.Az2, me.El1, me.El2 })
                n.ValueChanged += (s, e) => { if (pnlPunt != null) pnlPunt.Invalidate(); };
            me.Loc.TextChanged += (s, e) => { puntPercorsoT0 = DateTime.MinValue; if (pnlPunt != null) pnlPunt.Invalidate(); };
        }

        // Senza locator la mappa si centra su JJ00AA: un clic sceglie il locator a 10 caratteri del punto
        int puntZoomVuoto = 3;
        double PuntCLat { get { double la, lo; if (me.Ok) return me.Lat; Locator.TryParse("JJ00AA", out la, out lo); return la; } }
        double PuntCLon { get { double la, lo; if (me.Ok) return me.Lon; Locator.TryParse("JJ00AA", out la, out lo); return lo; } }
        int PuntZ { get { return Math.Min(me.Ok ? puntZoom : puntZoomVuoto, PuntProv.MaxZoom); } }

        void DisegnaPuntVuota(Graphics g, int W, int H)
        {
            TileProvider prov = PuntProv;
            int z = PuntZ, n = 1 << z;
            double ox = LonToX(PuntCLon, z) - W / 2.0, oy = LatToY(PuntCLat, z) - H / 2.0;
            g.Clear(Color.FromArgb(14, 22, 40));
            g.InterpolationMode = InterpolationMode.HighQualityBilinear;
            int tx0 = (int)Math.Floor(ox / 256.0), tx1 = (int)Math.Floor((ox + W) / 256.0);
            int ty0 = Math.Max(0, (int)Math.Floor(oy / 256.0)), ty1 = Math.Min(n - 1, (int)Math.Floor((oy + H) / 256.0));
            for (int ty = ty0; ty <= ty1; ty++)
                for (int tx = tx0; tx <= tx1; tx++)
                {
                    Image img = Tessera(prov, z, ((tx % n) + n) % n, ty, true);
                    if (img != null) g.DrawImage(img, (float)(tx * 256 - ox), (float)(ty * 256 - oy), 256, 256);
                }
            PreparaGrafica(g);
            using (Font f = FontPx(Lang.FontUi, S(15), true))
            {
                string t = Lang.T("Nessun locator inserito: la mappa è centrata su JJ00AA. Clicca il punto della tua stazione per sceglierne il locator a 10 caratteri; con la rotella del mouse cambi lo zoom.");
                RectangleF r = new RectangleF(S(16), S(14), Math.Min(W - S(32), S(760)), S(58));
                using (GraphicsPath gp = Arrotondato(r, S(10)))
                using (Brush b = new SolidBrush(Color.FromArgb(225, 29, 36, 51))) g.FillPath(b, gp);
                Testo(g, t, f, Color.White, new RectangleF(r.X + S(14), r.Y, r.Width - S(28), r.Height), StringAlignment.Near, StringAlignment.Center);
            }
        }

        void CambiaZoomPunt(int d)
        {
            if (!me.Ok)
            {
                puntZoomVuoto = Math.Max(2, Math.Min(PuntProv.MaxZoom, puntZoomVuoto + d));
                if (pnlPunt != null) pnlPunt.Invalidate();
                return;
            }
            puntZoom = Math.Max(3, Math.Min(PuntProv.MaxZoom, puntZoom + d));
            AggiornaZoomPunt();
            if (!caricamento) SaveSettings();
        }

        void AggiornaZoomPunt()
        {
            if (lblPuntZoom != null) lblPuntZoom.Text = "zoom " + puntZoom.ToString(inv);
            if (pnlPunt != null) pnlPunt.Invalidate();
        }

        // Percorso della Luna nelle prossime 24 ore (passo 10 minuti), sorgere e tramonto
        void CalcolaPercorsoPunt(DateTime now)
        {
            DateTime t0 = new DateTime(now.Year, now.Month, now.Day, now.Hour, now.Minute / 10 * 10, 0, DateTimeKind.Utc);
            if (t0 == puntPercorsoT0 && puntPercorso.Count > 0) return;
            puntPercorsoT0 = t0;
            puntPercorso.Clear();
            puntSorgeAz = double.NaN; puntTramAz = double.NaN;
            double ePrec = double.NaN, aPrec = 0;
            for (int i = 0; i <= 144; i++)
            {
                DateTime t = t0.AddMinutes(10 * i);
                MoonPos p = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                puntPercorso.Add(new double[] { p.Az, p.El, i / 6.0 });
                if (!double.IsNaN(ePrec))
                {
                    double f = ePrec / (ePrec - p.El);
                    double az = aPrec + f * (((p.Az - aPrec + 540.0) % 360.0) - 180.0);
                    if (ePrec < 0 && p.El >= 0 && double.IsNaN(puntSorgeAz)) { puntSorgeAz = (az + 360.0) % 360.0; puntSorgeT = t.AddMinutes(-10 * (1 - f)); }
                    if (ePrec >= 0 && p.El < 0 && double.IsNaN(puntTramAz)) { puntTramAz = (az + 360.0) % 360.0; puntTramT = t.AddMinutes(-10 * (1 - f)); }
                }
                ePrec = p.El; aPrec = p.Az;
            }
        }

        static PointF Polare(PointF c, float R, double az, double el)
        {
            double r = R * (90.0 - Math.Max(0.0, Math.Min(90.0, el))) / 90.0;
            double a = az * Math.PI / 180.0;
            return new PointF(c.X + (float)(r * Math.Sin(a)), c.Y - (float)(r * Math.Cos(a)));
        }

        static float RaggioEl(float R, double el) { return (float)(R * (90.0 - Math.Max(0.0, Math.Min(90.0, el))) / 90.0); }

        void DisegnaPunt(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            if (W < 50 || H < 50) return;
            if (!me.Ok) { DisegnaPuntVuota(g, W, H); return; }
            // 1. mappa centrata sulla stazione, disegnata fuori schermo (serve anche per la sfocatura)
            TileProvider prov = PuntProv;
            int z = Math.Min(puntZoom, prov.MaxZoom);
            int n = 1 << z;
            double ox = LonToX(me.Lon, z) - W / 2.0, oy = LatToY(me.Lat, z) - H / 2.0;
            using (Bitmap fondo = new Bitmap(W, H))
            {
                using (Graphics gb = Graphics.FromImage(fondo))
                {
                    gb.Clear(Color.FromArgb(14, 22, 40));
                    gb.InterpolationMode = InterpolationMode.HighQualityBilinear;
                    int tx0 = (int)Math.Floor(ox / 256.0), tx1 = (int)Math.Floor((ox + W) / 256.0);
                    int ty0 = Math.Max(0, (int)Math.Floor(oy / 256.0)), ty1 = Math.Min(n - 1, (int)Math.Floor((oy + H) / 256.0));
                    for (int ty = ty0; ty <= ty1; ty++)
                        for (int tx = tx0; tx <= tx1; tx++)
                        {
                            Image img = Tessera(prov, z, ((tx % n) + n) % n, ty, true);
                            if (img != null) gb.DrawImage(img, (float)(tx * 256 - ox), (float)(ty * 256 - oy), 256, 256);
                        }
                }
                g.DrawImage(fondo, 0, 0, W, H);
                PreparaGrafica(g);

                PointF c = new PointF(W / 2f, H / 2f);
                float R = Math.Min(W, H) * 0.43f;
                double az1 = (double)me.Az1.Value, az2 = (double)me.Az2.Value, el1 = (double)me.El1.Value, el2 = (double)me.El2.Value;
                bool azLibero = az2 - az1 >= 360.0 || az1 == az2;
                float sweep = (float)(((az2 - az1) % 360.0 + 360.0) % 360.0);
                float rOut = RaggioEl(R, el1), rIn = RaggioEl(R, el2);

                // 2. zone fuori dai limiti: mappa sfocata e velo grigio chiaro (si può spegnere)
                if (chkPuntSfuma.Checked)
                using (GraphicsPath disco = new GraphicsPath())
                using (GraphicsPath consentita = new GraphicsPath())
                {
                    disco.AddEllipse(c.X - R, c.Y - R, 2 * R, 2 * R);
                    if (azLibero) consentita.AddEllipse(c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut);
                    else if (sweep > 0) consentita.AddPie(c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut, (float)az1 - 90f, sweep);
                    using (Region fuori = new Region(disco))
                    {
                        if (rOut > 0.5f && (azLibero || sweep > 0))
                        {
                            using (Region ok = new Region(consentita))
                            {
                                if (rIn > 0.5f)
                                    using (GraphicsPath interno = new GraphicsPath())
                                    {
                                        interno.AddEllipse(c.X - rIn, c.Y - rIn, 2 * rIn, 2 * rIn);
                                        ok.Exclude(interno);
                                    }
                                fuori.Exclude(ok);
                            }
                        }
                        Region vecchia = g.Clip;
                        g.Clip = fuori;
                        using (Bitmap piccola = new Bitmap(Math.Max(1, W / 14), Math.Max(1, H / 14)))
                        {
                            using (Graphics gp = Graphics.FromImage(piccola))
                            {
                                gp.InterpolationMode = InterpolationMode.HighQualityBilinear;
                                gp.DrawImage(fondo, 0, 0, piccola.Width, piccola.Height);
                            }
                            g.InterpolationMode = InterpolationMode.HighQualityBilinear;
                            g.DrawImage(piccola, -W / 28f, -H / 28f, W + W / 14f, H + H / 14f);
                        }
                        using (Brush velo = new SolidBrush(Color.FromArgb(grigioOpacita * 255 / 100, GrigioRgb, GrigioRgb, Math.Min(255, GrigioRgb + 6)))) g.FillRegion(velo, fuori);
                        g.Clip = vecchia;
                    }
                }
                // fuori dall'orizzonte la mappa resta visibile ma un po' più scura
                using (GraphicsPath esterno = new GraphicsPath())
                {
                    esterno.AddRectangle(new RectangleF(0, 0, W, H));
                    esterno.AddEllipse(c.X - R, c.Y - R, 2 * R, 2 * R);
                    using (Brush b = new SolidBrush(Color.FromArgb(70, 0, 0, 0))) g.FillPath(b, esterno);
                }

                // 3. orizzonte, cerchi di elevazione ogni 30°, punti cardinali
                using (Pen ph = new Pen(Color.FromArgb(200, 255, 255, 255), 1.5f)) g.DrawEllipse(ph, c.X - R, c.Y - R, 2 * R, 2 * R);
                using (Pen pe = new Pen(Color.FromArgb(110, 255, 255, 255), 1f))
                {
                    pe.DashStyle = DashStyle.Dot;
                    foreach (int el in new int[] { 30, 60 })
                    {
                        float r = RaggioEl(R, el);
                        g.DrawEllipse(pe, c.X - r, c.Y - r, 2 * r, 2 * r);
                    }
                    g.DrawLine(pe, c.X, c.Y - R, c.X, c.Y + R);
                    g.DrawLine(pe, c.X - R, c.Y, c.X + R, c.Y);
                }
                using (Font fc = FontPx(Lang.FontUi, S(13), true))
                {
                    string[] pc = { "N", "E", "S", Lang.T("O") };
                    for (int i = 0; i < 4; i++)
                    {
                        PointF p = Polare(c, R + S(16), i * 90, 0);
                        RectangleF rb = new RectangleF(p.X - S(11), p.Y - S(11), S(22), S(22));
                        using (Brush b = new SolidBrush(Color.FromArgb(235, 255, 255, 255))) g.FillRectangle(b, rb);
                        Testo(g, pc[i], fc, Color.FromArgb(20, 25, 35), rb, StringAlignment.Center, StringAlignment.Center);
                    }
                }

                // 4. limiti dell'antenna (gialli) con le maniglie
                Color cl = Color.FromArgb(255, 209, 72);
                using (Pen ps = new Pen(Color.FromArgb(150, 0, 0, 0), S(7)))
                using (Pen pl = new Pen(cl, S(4)))
                {
                    ps.StartCap = pl.StartCap = LineCap.Round;
                    ps.EndCap = pl.EndCap = LineCap.Round;
                    foreach (Pen p in new Pen[] { ps, pl })
                    {
                        if (!azLibero)
                        {
                            PointF a1i = Polare(c, R, az1, el2 >= 90 ? 90 : el2), a1o = Polare(c, R, az1, Math.Max(0, el1));
                            PointF a2i = Polare(c, R, az2, el2 >= 90 ? 90 : el2), a2o = Polare(c, R, az2, Math.Max(0, el1));
                            g.DrawLine(p, a1i, a1o);
                            g.DrawLine(p, a2i, a2o);
                            if (sweep > 0)
                            {
                                if (rOut > 1) g.DrawArc(p, c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut, (float)az1 - 90f, sweep);
                                if (rIn > 1) g.DrawArc(p, c.X - rIn, c.Y - rIn, 2 * rIn, 2 * rIn, (float)az1 - 90f, sweep);
                            }
                        }
                        else
                        {
                            if (rOut > 1) g.DrawEllipse(p, c.X - rOut, c.Y - rOut, 2 * rOut, 2 * rOut);
                            if (rIn > 1) g.DrawEllipse(p, c.X - rIn, c.Y - rIn, 2 * rIn, 2 * rIn);
                        }
                    }
                }
                double azMezzo = azLibero ? 180.0 : az1 + sweep / 2.0;
                hAz1 = Polare(c, R, az1, 0);
                hAz2 = Polare(c, R, azLibero ? az1 + 1 : az2, 0);
                hEl1 = Polare(c, R, azMezzo, Math.Max(0, el1));
                hEl2 = Polare(c, R, azMezzo, Math.Min(90, el2));
                hEl2Vis = el2 < 90;
                using (Font fh = new Font(Lang.FontUi, 10F, FontStyle.Bold))
                {
                    Maniglia(g, hAz1, cl, Lang.T("Azimut da (°)").Replace("(°)", "").Trim() + " " + az1.ToString("0", ci) + "°", fh);
                    Maniglia(g, hAz2, cl, azLibero ? "" : "→ " + az2.ToString("0", ci) + "°", fh);
                    Maniglia(g, hEl1, cl, "El min " + el1.ToString("0", ci) + "°", fh);
                    if (hEl2Vis) Maniglia(g, hEl2, cl, "El max " + el2.ToString("0", ci) + "°", fh);
                }

                // 5. percorso della Luna, sorgere e tramonto
                DateTime now = DateTime.UtcNow;
                CalcolaPercorsoPunt(now);
                using (Font fs = new Font(Lang.FontUi, 9.5F, FontStyle.Bold))
                {
                    if (!double.IsNaN(puntSorgeAz)) LineaOrizzonte(g, c, R, puntSorgeAz, Color.FromArgb(235, 120, 40), Lang.T("sorge") + " " + OraLoc(puntSorgeT), fs);
                    if (!double.IsNaN(puntTramAz)) LineaOrizzonte(g, c, R, puntTramAz, Color.FromArgb(220, 170, 30), Lang.T("tramonta") + " " + OraLoc(puntTramT), fs);
                    if (chkPuntPercorso.Checked && puntPercorso.Count > 1)
                    {
                        using (Pen ps = new Pen(Color.FromArgb(140, 0, 0, 0), S(7)))
                        using (Pen pp = new Pen(Color.FromArgb(235, 255, 220, 90), S(4)))
                        {
                            ps.StartCap = pp.StartCap = ps.EndCap = pp.EndCap = LineCap.Round;
                            for (int pass = 0; pass < 2; pass++)
                                for (int i = 1; i < puntPercorso.Count; i++)
                                {
                                    double[] p0 = puntPercorso[i - 1], p1 = puntPercorso[i];
                                    if (p0[1] < 0 || p1[1] < 0) continue;
                                    g.DrawLine(pass == 0 ? ps : pp, Polare(c, R, p0[0], p0[1]), Polare(c, R, p1[0], p1[1]));
                                }
                        }
                        // le ore vicine alla Luna di adesso non si scrivono: la sua etichetta resta leggibile
                        MoonPos mpOra = Moon.Compute(now, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                        PointF qLuna = Polare(c, R, mpOra.Az, mpOra.El);
                        for (int i = 6; i < puntPercorso.Count; i += 6)
                        {
                            double[] p = puntPercorso[i];
                            if (p[1] < 0) continue;
                            PointF q = Polare(c, R, p[0], p[1]);
                            if (mpOra.El >= 0 && Math.Abs(q.X - qLuna.X) < S(190) && Math.Abs(q.Y - qLuna.Y) < S(44)) continue;
                            using (Brush b = new SolidBrush(Color.White)) g.FillEllipse(b, q.X - S(4), q.Y - S(4), S(8), S(8));
                            using (Pen pn = new Pen(Color.Black, 1.5f)) g.DrawEllipse(pn, q.X - S(4), q.Y - S(4), S(8), S(8));
                            TestoBordato(g, puntPercorsoT0.AddMinutes(10 * i).ToString("HH", inv) + "h", fs, Color.White, q.X + S(6), q.Y - S(8));
                        }
                    }
                }

                // 6. la Luna adesso
                MoonPos mp = Moon.Compute(now, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                bool okMe;
                me.Valuta(mp, out okMe);
                int stato = okMe ? 0 : (mp.El < 0 ? 2 : 1);
                Color cs = stato == 0 ? Color.FromArgb(61, 220, 132) : (stato == 1 ? Color.FromArgb(255, 179, 64) : Color.FromArgb(150, 160, 180));
                PointF pm = Polare(c, R, mp.Az, mp.El);
                using (Pen pl = new Pen(Color.FromArgb(200, 255, 230, 120), S(3)))
                {
                    pl.DashStyle = mp.El >= 0 ? DashStyle.Solid : DashStyle.Dash;
                    g.DrawLine(pl, c, pm);
                }
                float rg = S(34);
                using (GraphicsPath alone = new GraphicsPath())
                {
                    alone.AddEllipse(pm.X - rg, pm.Y - rg, 2 * rg, 2 * rg);
                    using (PathGradientBrush pg = new PathGradientBrush(alone))
                    {
                        pg.CenterColor = Color.FromArgb(mp.El >= 0 ? 170 : 70, 255, 245, 200);
                        pg.SurroundColors = new Color[] { Color.FromArgb(0, 255, 245, 200) };
                        g.FillPath(pg, alone);
                    }
                }
                double saz, sel, sra, sdec;
                Moon.SunPos(now, me.Lat, me.Lon, out saz, out sel, out sra, out sdec);
                double elong = Moon.Separation(sra, sdec, mp.Ra, mp.Dec);
                float rmn = S(15);
                DisegnaFase(g, pm, rmn, (1 - Math.Cos(elong * Math.PI / 180.0)) / 2.0, ((mp.Ra - sra + 720.0) % 360.0) < 180.0);
                using (Pen pr = new Pen(cs, S(4))) g.DrawEllipse(pr, pm.X - rmn - S(3), pm.Y - rmn - S(3), 2 * rmn + S(6), 2 * rmn + S(6));
                using (Pen pr = new Pen(Color.Black, 1.5f)) g.DrawEllipse(pr, pm.X - rmn - S(6), pm.Y - rmn - S(6), 2 * rmn + S(12), 2 * rmn + S(12));
                using (Font fm = new Font(Lang.FontUi, 11F, FontStyle.Bold))
                {
                    string tl = string.Format(ci, Lang.T("LUNA  Az {0:F1}° El {1:F1}°"), mp.Az, mp.El);
                    SizeF sz = g.MeasureString(tl, fm);
                    float tx = pm.X + rmn + S(12);
                    if (tx + sz.Width > W - S(6)) tx = pm.X - rmn - S(12) - sz.Width;
                    TestoBordato(g, tl, fm, cs, tx, pm.Y - sz.Height / 2);
                }

                // 7. la mia stazione al centro
                float rs = S(9);
                using (Brush b = new SolidBrush(Color.White)) g.FillEllipse(b, c.X - rs, c.Y - rs, 2 * rs, 2 * rs);
                using (Pen p = new Pen(Color.FromArgb(220, 30, 30), S(3))) g.DrawEllipse(p, c.X - rs, c.Y - rs, 2 * rs, 2 * rs);
                using (Brush b = new SolidBrush(Color.FromArgb(220, 30, 30))) g.FillEllipse(b, c.X - S(3), c.Y - S(3), S(6), S(6));
                string call = txtCall == null ? "" : txtCall.Text.Trim();
                using (Font fm = new Font(Lang.FontUi, 10F, FontStyle.Bold))
                    TestoBordato(g, (call.Length > 0 ? call + "  " : "") + me.Loc.Text.Trim(), fm, Color.White, c.X + rs + S(6), c.Y + S(4));

                // 8. riquadro informativo e attribuzione della mappa
                string[] stTxt = { Lang.T("PUNTABILE"), Lang.T("FUORI LIMITI"), Lang.T("SOTTO L'ORIZZONTE") };
                string info1 = stTxt[stato] + string.Format(ci, "   Az {0:F1}°  El {1:F1}°", mp.Az, mp.El);
                string info2 = azLibero ? Lang.T("nessun limite di azimut") + string.Format(ci, " · El {0:0}° → {1:0}°", el1, el2)
                    : string.Format(ci, Lang.T("Limiti: azimut {0}° → {1}°, elevazione {2}° → {3}°"), az1.ToString("0", ci), az2.ToString("0", ci), el1.ToString("0", ci), el2.ToString("0", ci));
                string info3 = Lang.T("Zone grigie = fuori dai limiti della tua antenna");
                using (Font f1 = FontPx(Lang.FontUi, S(17), true))
                using (Font f2 = FontPx(Lang.FontUi, S(14), false))
                {
                    float wbox = Math.Max(g.MeasureString(info1, f1).Width, Math.Max(g.MeasureString(info2, f2).Width, g.MeasureString(info3, f2).Width)) + S(28);
                    RectangleF rb = new RectangleF(S(12), S(12), wbox, S(86));
                    using (GraphicsPath p = Arrotondato(rb, S(10)))
                    {
                        using (Brush b = new SolidBrush(Color.FromArgb(205, 14, 22, 40))) g.FillPath(b, p);
                        using (Pen pn = new Pen(cs, 2f)) g.DrawPath(pn, p);
                    }
                    Testo(g, info1, f1, cs, new RectangleF(rb.Left + S(14), rb.Top + S(8), wbox, S(26)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, info2, f2, Color.FromArgb(225, 230, 240), new RectangleF(rb.Left + S(14), rb.Top + S(36), wbox, S(22)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, info3, f2, Color.FromArgb(170, 180, 200), new RectangleF(rb.Left + S(14), rb.Top + S(58), wbox, S(22)), StringAlignment.Near, StringAlignment.Center);
                }
                using (Font fa = new Font(Lang.FontUi, 7.5F))
                {
                    SizeF sa = g.MeasureString(prov.Attribuzione, fa);
                    using (Brush b = new SolidBrush(Color.FromArgb(170, 255, 255, 255))) g.FillRectangle(b, W - sa.Width - S(6), H - sa.Height - S(4), sa.Width + S(4), sa.Height + S(2));
                    using (Brush b = new SolidBrush(Color.FromArgb(40, 40, 40))) g.DrawString(prov.Attribuzione, fa, b, W - sa.Width - S(4), H - sa.Height - S(3));
                }
            }
        }

        string OraLoc(DateTime utc)
        {
            return TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(utc, DateTimeKind.Utc), TimeZoneInfo.Local).ToString("HH:mm", inv);
        }

        void LineaOrizzonte(Graphics g, PointF c, float R, double az, Color col, string testo, Font f)
        {
            PointF p = Polare(c, R, az, 0);
            using (Pen ps = new Pen(Color.FromArgb(140, 0, 0, 0), S(7))) g.DrawLine(ps, c, p);
            using (Pen pl = new Pen(col, S(4))) g.DrawLine(pl, c, p);
            // scritta oltre il cerchio, lontana dalle caselle dei punti cardinali e sempre dentro la finestra
            SizeF sz = g.MeasureString(testo, f);
            PointF q = Polare(c, R + S(40) + sz.Width / 2, az, 0);
            float tx = q.X - sz.Width / 2, ty = q.Y - sz.Height / 2;
            double resto = ((az % 90.0) + 90.0) % 90.0;
            if (resto < 8 || resto > 82) ty += (q.Y <= c.Y ? -S(18) : S(18));
            tx = Math.Max(S(4), Math.Min(pnlPunt.ClientSize.Width - sz.Width - S(4), tx));
            ty = Math.Max(S(104), Math.Min(pnlPunt.ClientSize.Height - sz.Height - S(20), ty));
            TestoBordato(g, testo, f, col, tx, ty);
        }

        void Maniglia(Graphics g, PointF p, Color col, string testo, Font f)
        {
            float r = S(9);
            using (Brush b = new SolidBrush(col)) g.FillEllipse(b, p.X - r, p.Y - r, 2 * r, 2 * r);
            using (Pen pn = new Pen(Color.FromArgb(30, 30, 30), 2f)) g.DrawEllipse(pn, p.X - r, p.Y - r, 2 * r, 2 * r);
            if (testo.Length > 0) TestoBordato(g, testo, f, col, p.X + r + S(4), p.Y - r - S(14));
        }

        int ManigliaVicina(Point m)
        {
            PointF[] h = { hAz1, hAz2, hEl1, hEl2 };
            int best = 0;
            double dmin = S(14);
            for (int i = 0; i < 4; i++)
            {
                double d = Math.Sqrt((m.X - h[i].X) * (m.X - h[i].X) + (m.Y - h[i].Y) * (m.Y - h[i].Y));
                if (d < dmin) { dmin = d; best = i + 1; }
            }
            return best;
        }

        void PuntMouseDown(object sender, MouseEventArgs e)
        {
            if (e.Button != MouseButtons.Left) return;
            if (!me.Ok) { puntDrag = 0; ProponiLocatorPunt(e.Location); return; }
            puntDrag = ManigliaVicina(e.Location);
            if (puntDrag == 0 && FuoriDalCerchioPunt(e.Location)) ProponiLocatorPunt(e.Location);
        }

        bool FuoriDalCerchioPunt(Point m)
        {
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            float R = Math.Min(W, H) * 0.43f;
            double dx0 = m.X - W / 2.0, dy0 = m.Y - H / 2.0;
            return Math.Sqrt(dx0 * dx0 + dy0 * dy0) > R + S(6);
        }

        // Clic fuori dal cerchio dei punti cardinali: locator a 10 caratteri del punto cliccato, segnaposto e domanda
        void ProponiLocatorPunt(Point m)
        {
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            int z = PuntZ;
            double ox = LonToX(PuntCLon, z) - W / 2.0, oy = LatToY(PuntCLat, z) - H / 2.0;
            double lon = XToLon(ox + m.X, z), lat = YToLat(oy + m.Y, z);
            lon = ((lon + 180.0) % 360.0 + 360.0) % 360.0 - 180.0;
            string nuovo = Locator.Da(lat, lon, 10);
            puntNuovoOn = true; puntNuovoLat = lat; puntNuovoLon = lon; puntNuovoLoc = nuovo;
            pnlPunt.Refresh();
            bool ok = ChiediSiNo(Lang.T("Cambio del locatore"),
                string.Format(Lang.T("Hai cambiato locatore, a favore di {0}: accetti la modifica?"), nuovo),
                Lang.T("Il nuovo locatore vale per tutti i calcoli del programma; la quota viene cercata di nuovo sul web e la mappa si centra sul nuovo punto."));
            puntNuovoOn = false;
            if (ok && txtTrkLoc != null)
            {
                txtTrkLoc.Text = nuovo;              // aggiorna anche il locator della Posizione della Luna e tutti i calcoli
                if (me.Loc.Text != nuovo) me.Loc.Text = nuovo;
                if (!caricamento) SaveSettings();
            }
            pnlPunt.Invalidate();
        }

        // Segnaposto del punto proposto, sopra la mappa
        void DisegnaNuovoLocPunt(object sender, PaintEventArgs e)
        {
            if (!puntNuovoOn) return;
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            int z = PuntZ;
            double ox = LonToX(PuntCLon, z) - W / 2.0, oy = LatToY(PuntCLat, z) - H / 2.0;
            float x = (float)(LonToX(puntNuovoLon, z) - ox), y = (float)(LatToY(puntNuovoLat, z) - oy);
            Color rosso = Color.FromArgb(220, 38, 38);
            using (Pen pn = new Pen(Color.White, S(3))) { g.DrawLine(pn, x, y, x, y - S(26)); }
            using (Pen pn = new Pen(rosso, S(2))) { g.DrawLine(pn, x, y, x, y - S(26)); }
            using (Brush b = new SolidBrush(rosso)) g.FillEllipse(b, x - S(9), y - S(40), S(18), S(18));
            using (Pen pn = new Pen(Color.White, S(2))) g.DrawEllipse(pn, x - S(9), y - S(40), S(18), S(18));
            using (Brush b = new SolidBrush(Color.FromArgb(120, 0, 0, 0))) g.FillEllipse(b, x - S(4), y - S(2), S(8), S(4));
            using (Font f = FontPx(FamigliaNumeri, S(15), true))
                TestoBordato(g, puntNuovoLoc, f, Color.White, x + S(12), y - S(44));
        }

        void PuntMouseMove(object sender, MouseEventArgs e)
        {
            if (puntDrag == 0)
            {
                pnlPunt.Cursor = !me.Ok ? Cursors.Cross : (ManigliaVicina(e.Location) != 0 ? Cursors.Hand : (FuoriDalCerchioPunt(e.Location) ? Cursors.Cross : Cursors.Default));
                return;
            }
            int W = pnlPunt.ClientSize.Width, H = pnlPunt.ClientSize.Height;
            float R = Math.Min(W, H) * 0.43f;
            double dx0 = e.X - W / 2.0, dy0 = e.Y - H / 2.0;
            double az = Math.Round((Math.Atan2(dx0, -dy0) * 180.0 / Math.PI + 360.0) % 360.0);
            double el = Math.Round(90.0 * (1.0 - Math.Sqrt(dx0 * dx0 + dy0 * dy0) / R));
            el = Math.Max(0, Math.Min(90, el));
            try
            {
                if (puntDrag == 1)
                {
                    if (az == (double)me.Az2.Value % 360.0) az = (az + 1) % 360.0;
                    me.Az1.Value = (decimal)az;
                }
                else if (puntDrag == 2)
                {
                    double a1 = (double)me.Az1.Value;
                    if (az == a1 % 360.0) az = (az + 359.0) % 360.0;
                    if (az == 0) az = 360;
                    me.Az2.Value = (decimal)az;
                }
                else if (puntDrag == 3) me.El1.Value = (decimal)Math.Min(el, (double)me.El2.Value);
                else if (puntDrag == 4) me.El2.Value = (decimal)Math.Max(el, (double)me.El1.Value);
            }
            catch { }
            pnlPunt.Invalidate();
        }

