        double mondoSubLat, mondoSubLon, mondoDist, mondoDec;
        MoonPos mondoMe;
        bool mondoMeOk, mondoPuntabile;
        string mondoStato = "";   // come nelle altre linguette: PUNTABILE, fuori azimut, elev. troppo bassa, sotto l'orizzonte…
        const double MondoLatN = 84.0, MondoLatS = -72.0;   // l'Antartide è tagliata a 72° S

        // colore dell'elevazione: 0° rosso, 10° arancio, 25° giallo, 45° verde chiaro, 90° verde scuro
        static readonly double[] MondoTappe = { 0, 10, 25, 45, 90 };
        static readonly Color[] MondoColori = { Color.FromArgb(214, 48, 39), Color.FromArgb(244, 140, 40), Color.FromArgb(246, 212, 60), Color.FromArgb(120, 196, 90), Color.FromArgb(26, 128, 64) };
        static Color ColoreElevazione(double el)
        {
            if (el <= 0) return MondoColori[0];
            for (int i = 1; i < MondoTappe.Length; i++)
                if (el <= MondoTappe[i])
                {
                    double t = (el - MondoTappe[i - 1]) / (MondoTappe[i] - MondoTappe[i - 1]);
                    Color a = MondoColori[i - 1], b = MondoColori[i];
                    return Color.FromArgb((int)(a.R + (b.R - a.R) * t), (int)(a.G + (b.G - a.G) * t), (int)(a.B + (b.B - a.B) * t));
                }
            return MondoColori[MondoColori.Length - 1];
        }

        DateTime MondoMomento()
        {
            DateTime d = dtpMondoData.Value.Date, o = dtpMondoOra.Value;
            return DateTime.SpecifyKind(new DateTime(d.Year, d.Month, d.Day, o.Hour, o.Minute, 0), DateTimeKind.Utc);
        }

        // il momento è quello di Posizione della Luna (dtp): si copia in qua, e se lo cambi qua si copia là
        void MondoDaPosizione()
        {
            if (dtpMondoData == null) return;
            // un momento scelto a mano (qui o in Posizione della Luna) spegne "Segui l'ora attuale"
            if (!mondoDaTimer && chkMondoSegui != null && chkMondoSegui.Checked && dtp.Value != NowUtcMinute()) chkMondoSegui.Checked = false;
            mondoSync = true;
            try { dtpMondoData.Value = dtp.Value.Date; dtpMondoOra.Value = dtp.Value; }
            finally { mondoSync = false; }
            MondoAggiorna();
        }

        void MondoVersoPosizione()
        {
            if (mondoSync) return;
            DateTime t = MondoMomento();
            if (dtp.Value != t) dtp.Value = t;   // dtp.ValueChanged richiama MondoDaPosizione
            else MondoAggiorna();
        }

        void MondoAggiorna()
        {
            mondoSporca = true;
            if (pnlMondo != null && tabs != null && tabs.SelectedTab == tpMondo) pnlMondo.Invalidate();
        }

