        void RecalcDgrd()
        {
            if (dgChart == null) return;
            dgT.Clear(); dgDgrd.Clear(); dgDec.Clear(); dgOk.Clear(); dgGiorni.Clear(); dgTop.Clear(); dgNuova.Clear(); dgPiena.Clear(); dgOrd.Clear();
            if (!me.Ok) { lblDg.Text = Lang.T("Imposta un locator valido nella prima linguetta."); lvDg.Items.Clear(); dgChart.Invalidate(); pnlDgTop.Invalidate(); pnlDgCal.Invalidate(); return; }
            double f;
            if (!ReadFreq(out f)) f = 144;
            dgFreq = f;
            dgDx = chkDx.Checked && dx.Ok;
            DateTime now = DateTime.UtcNow;
            dgStart = new DateTime(now.Year, now.Month, now.Day, 0, 0, 0, DateTimeKind.Utc);
            int ngiorni = (int)nudDgGiorni.Value;
            dgEnd = dgStart.AddDays(ngiorni);
            GiornoEme gcur = null;
            double sepPrev2 = double.NaN, sepPrev = double.NaN;
            DateTime tPrev = dgStart;
            for (DateTime t = dgStart; t <= dgEnd; t = t.AddMinutes(30))
            {
                Riga r = Calcola1(t, dgDx, f, chkRefr.Checked);
                double score = dgDx ? Math.Min(r.DgrdMe, r.DgrdDx) : r.DgrdMe;
                dgT.Add(t); dgDgrd.Add(r.DgrdMe); dgOk.Add(r.Ok); dgDec.Add(r.P.DecGeo);

                // luna nuova: minimo della distanza angolare Sole-Luna (sotto 15°)
                double saz, sel, sra, sdec;
                Moon.SunPos(t, me.Lat, me.Lon, out saz, out sel, out sra, out sdec);
                double sep = Moon.Separation(sra, sdec, r.P.Ra, r.P.Dec);
                if (!double.IsNaN(sepPrev2) && sepPrev < sepPrev2 && sepPrev <= sep && sepPrev < 15) dgNuova.Add(tPrev);
                // luna piena: massimo della distanza angolare Sole-Luna (sopra 165°)
                if (!double.IsNaN(sepPrev2) && sepPrev > sepPrev2 && sepPrev >= sep && sepPrev > 165) dgPiena.Add(tPrev);
                sepPrev2 = sepPrev; sepPrev = sep; tPrev = t;

                if (t == dgEnd) break;
                if (gcur == null || gcur.Giorno != t.Date)
                {
                    gcur = new GiornoEme();
                    gcur.Giorno = DateTime.SpecifyKind(t.Date, DateTimeKind.Utc);
                    dgGiorni.Add(gcur);
                }
                gcur.DistSomma += r.P.DistTopo; gcur.DistN++;
                if (r.P.El >= 0 && (double.IsNaN(gcur.SepSopra) || sep < gcur.SepSopra)) gcur.SepSopra = sep;
                if (r.Ok && (double.IsNaN(gcur.SepUtile) || sep < gcur.SepUtile)) gcur.SepUtile = sep;
                if (t.Hour == 12 && t.Minute == 0)
                {
                    gcur.Illum = (1 - Math.Cos(sep * Math.PI / 180.0)) / 2.0;
                    gcur.Crescente = ((r.P.Ra - sra + 720.0) % 360.0) < 180.0;
                }
                if (r.Ok)
                {
                    gcur.Ore += 0.5;
                    if (double.IsNaN(gcur.Score) || score > gcur.Score)
                    {
                        gcur.Score = score; gcur.Migliore = t; gcur.DgrdMe = r.DgrdMe; gcur.DgrdDx = r.DgrdDx;
                        gcur.Dist = r.P.DistTopo; gcur.Tsky = r.Tsky;
                    }
                }
            }
            foreach (DateTime tn in dgNuova)
                foreach (GiornoEme gg in dgGiorni) if (gg.Giorno == tn.Date) gg.LunaNuova = true;
            foreach (DateTime tn in dgPiena)
                foreach (GiornoEme gg in dgGiorni) if (gg.Giorno == tn.Date) gg.LunaPiena = true;
            // Sole vicino alla Luna: confronto con la larghezza del fascio della mia antenna (stessa stima della linguetta Rumore solare)
            dgFascio = double.NaN;
            if (bMe != null)
            {
                BudgetParams pmF = BudgetParams.FromUi(bMe);
                double gl = Math.Pow(10.0, (pmF.GAnt + 10.0 * Math.Log10(Math.Max(1, pmF.NAnt))) / 10.0);
                dgFascio = Math.Sqrt(41253.0 / gl);
            }
            foreach (GiornoEme gg in dgGiorni)
            {
                gg.SoleLiv = 0;
                if (double.IsNaN(gg.Sep) || double.IsNaN(dgFascio)) continue;
                if (gg.Sep < 3 * dgFascio) gg.SoleLiv = 2;
                else if (gg.Sep < 6 * dgFascio) gg.SoleLiv = 1;
            }

            // classifica: Dgrd migliore più alta (meno degradazione); a parità, più ore utili
            List<GiornoEme> ord = new List<GiornoEme>();
            foreach (GiornoEme gg in dgGiorni) if (!double.IsNaN(gg.Score)) ord.Add(gg);
            ord.Sort((x1, x2) =>
            {
                int c = x2.Score.CompareTo(x1.Score);
                return c != 0 ? c : x2.Ore.CompareTo(x1.Ore);
            });
            for (int i = 0; i < ord.Count; i++) ord[i].Rango = i + 1;
            dgOrd = ord;
            for (int i = 0; i < Math.Min(3, ord.Count); i++) dgTop.Add(ord[i].Giorno);
            RiempiTabellaDg();

            if (ord.Count > 0)
            {
                GiornoEme b = ord[0];
                lblDg.Text = string.Format(ci, Lang.T("Giorno migliore nei prossimi ") + ngiorni.ToString(ci) + Lang.T(" giorni: {0}, Dgrd {1:F2} dB alle {2} UTC (distanza {3:N0} km), {4:0.0} ore utili.   Calcolato per {5} a {6} MHz (frequenza della linguetta Posizione della Luna){7}. Aggiornato alle {8} UTC."),
                    b.Giorno.ToString("dddd dd/MM", itCi), b.Score, FmtT(b.Migliore), b.Dist, b.Ore,
                    me.Loc.Text.Trim(), f.ToString("0.000", ci),
                    dgDx ? Lang.T(", con il DX ") + dx.Loc.Text.Trim() + Lang.T(" (conta la Dgrd peggiore delle due stazioni e solo le finestre comuni)") : Lang.T(", solo le ore con la Luna dentro i limiti della tua antenna"),
                    now.ToString("HH:mm", inv));
            }
            else lblDg.Text = Lang.T("Nessuna finestra utile nei prossimi ") + ngiorni.ToString(ci) + Lang.T(" giorni con i limiti di puntamento attuali.");
            dgChart.Invalidate();
            pnlDgTop.Invalidate();
            pnlDgCal.Invalidate();
        }

        void RiempiTabellaDg()
        {
            if (lvDg == null) return;
            lvDg.BeginUpdate();
            // senza CALCOLI APPROFONDITI la classifica è corta: giorno, ora migliore, Dgrd, ore utili
            int[] largh = { 75, 110, 90, 70, 120, 75, 120, 190, 70, 95 };
            bool[] sempre = { true, true, false, true, true, true, false, false, false, true };
            for (int c = 0; c < lvDg.Columns.Count && c < largh.Length; c++) lvDg.Columns[c].Width = (sempre[c] || complessi) ? S(largh[c]) : 0;
            lvDg.Items.Clear();
            foreach (GiornoEme gg in dgGiorni)
            {
                bool valido = !double.IsNaN(gg.Score);
                if (chkDgSoloUtili.Checked && !valido) continue;
                ListViewItem it = new ListViewItem(valido ? (gg.Rango <= 3 ? "★ " + gg.Rango.ToString(ci) + "°" : gg.Rango.ToString(ci) + "°") : "-");
                it.SubItems.Add(gg.Giorno.ToString("ddd dd/MM/yyyy", itCi));
                it.SubItems.Add(gg.LunaNuova ? Lang.T("● Luna nuova") : (gg.LunaPiena ? Lang.T("Luna piena") : ""));
                it.SubItems.Add(gg.Ore.ToString("0.0", ci));
                it.SubItems.Add(valido ? gg.Score.ToString("F2", ci) : Lang.T("nessuna finestra"));
                it.SubItems.Add(valido ? FmtT(gg.Migliore) : "");
                it.SubItems.Add(valido ? (gg.DgrdMe.ToString("F2", ci) + (dgDx ? " / " + gg.DgrdDx.ToString("F2", ci) : "")) : "");
                it.SubItems.Add(gg.DistMedia.ToString("N0", ci));
                it.SubItems.Add(valido ? gg.Tsky.ToString("F0", ci) : "");
                it.SubItems.Add(double.IsNaN(gg.Sep) ? "" : (gg.SoleLiv > 0 ? "☀ " : "") + gg.Sep.ToString("F0", ci));
                if (valido && gg.Rango <= 3) it.BackColor = Tema.OkBg;
                else if (!valido) it.ForeColor = Tema.SottoFg;
                if (gg.Giorno == dgStart) it.Font = new Font(lvDg.Font, FontStyle.Bold);
                lvDg.Items.Add(it);
            }
            lvDg.EndUpdate();
        }

        Color ColoreDg()
        {
            if (!dgColDg.IsEmpty) return dgColDg;
            return Tema.Scuro ? Color.FromArgb(255, 93, 93) : Color.FromArgb(212, 44, 44);
        }

        Color ColoreKm() { return dgColKm.IsEmpty ? Color.FromArgb(220, 120, 30) : dgColKm; }

        bool ScegliColore(Color attuale, out Color scelto)
        {
            scelto = attuale;
            using (ColorDialog cd = new ColorDialog())
            {
                cd.Color = attuale;
                cd.FullOpen = true;
                if (cd.ShowDialog(this) != DialogResult.OK) return false;
                scelto = cd.Color;
                return true;
            }
        }

        void AggiornaStileDg() { AggiornaStileDg(true); }

        void AggiornaStileDg(bool salva)
        {
            if (btnColDg != null) { btnColDg.BackColor = ColoreDg(); btnColDg.FlatStyle = FlatStyle.Flat; }
            if (btnColKm != null) { btnColKm.BackColor = ColoreKm(); btnColKm.FlatStyle = FlatStyle.Flat; }
            if (dgChart != null) dgChart.Invalidate();
            if (salva && !caricamento) SaveSettings();
        }

        // I tre giorni migliori, in grande
        void DisegnaDgTop(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            Rectangle cr = pnlDgTop.ClientRectangle;
            if (cr.Width < 100 || cr.Height < 40) return;
            float gap = S(14), w = (cr.Width - S(12) - 2 * gap) / 3f, h = cr.Height - S(12);
            using (Font fd = FontPx(Lang.FontUi, Math.Min(S(22), h * 0.2f), true))
            using (Font fo = FontPx(FamigliaNumeri, Math.Min(S(30), h * 0.27f), true))
            using (Font fl = FontPx(Lang.FontUi, Math.Min(S(16), h * 0.15f), true))
            using (Font fs = FontPx(Lang.FontUi, Math.Min(S(15), h * 0.14f), false))
            using (Font fr = FontPx(Lang.FontUi, S(20), true))
                for (int i = 0; i < 3; i++)
                {
                    RectangleF r = new RectangleF(cr.Left + S(4) + i * (w + gap), cr.Top + S(4), w, h);
                    if (i >= dgOrd.Count)
                    {
                        Scheda(g, r, Color.Empty);
                        if (i == 0)
                            Testo(g, lblDg.Text, fs, Tema.Muted, new RectangleF(r.Left + S(20), r.Top, r.Width - S(30), r.Height), StringAlignment.Near, StringAlignment.Center);
                        continue;
                    }
                    GiornoEme gg = dgOrd[i];
                    Scheda(g, r, Tema.OkFg);
                    float rf = Math.Min(S(30), h * 0.3f);
                    PointF cm = new PointF(r.Left + S(22) + rf, r.Top + r.Height / 2f);
                    DisegnaFase(g, cm, rf, double.IsNaN(gg.Illum) ? 0.5 : gg.Illum, gg.Crescente);
                    float x = cm.X + rf + S(18), wt = r.Right - x - S(10);
                    Testo(g, "★ " + (i + 1).ToString(ci) + "°", fr, Tema.OkFg, new RectangleF(r.Right - S(80), r.Top + S(6), S(70), S(28)), StringAlignment.Far, StringAlignment.Near);
                    string giorno = gg.Giorno.ToString("dddd dd/MM", itCi);
                    if (giorno.Length > 0) giorno = char.ToUpper(giorno[0]) + giorno.Substring(1);
                    float y = r.Top + h * 0.1f;
                    Testo(g, giorno, fd, Tema.Fore, new RectangleF(x, y, wt - S(70), h * 0.26f), StringAlignment.Near, StringAlignment.Center);
                    y += h * 0.26f;
                    string utc = FmtT(gg.Migliore) + " UTC";
                    SizeF so = g.MeasureString(utc, fo);
                    Testo(g, utc, fo, Tema.OkFg, new RectangleF(x, y, so.Width + S(4), h * 0.32f), StringAlignment.Near, StringAlignment.Center);
                    string loc = "· " + TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(gg.Migliore, DateTimeKind.Utc), TimeZoneInfo.Local).ToString("HH:mm", inv) + " " + Lang.T("ora locale");
                    Testo(g, loc, fl, Tema.Muted, new RectangleF(x + so.Width + S(4), y, Math.Max(10, wt - so.Width), h * 0.32f), StringAlignment.Near, StringAlignment.Center);
                    y += h * 0.32f;
                    string riga = string.Format(ci, Lang.T("{0} dB · {1} h utili · {2}% illuminata"), gg.Score.ToString("F2", ci), gg.Ore.ToString("0.0", ci),
                        double.IsNaN(gg.Illum) ? "--" : (gg.Illum * 100).ToString("0", ci));
                    if (gg.SoleLiv > 0) riga += "  ·  ☀ " + string.Format(ci, Lang.T("Sole a {0}°"), gg.Sep.ToString("F0", ci));
                    Testo(g, riga, fs, gg.SoleLiv == 2 ? Color.FromArgb(240, 80, 60) : (gg.SoleLiv == 1 ? Tema.WarnFg : Tema.Muted),
                        new RectangleF(x, y, wt, h * 0.24f), StringAlignment.Near, StringAlignment.Center);
                }
        }

        // Calendario: una casella per giorno, colore dalla Dgrd migliore (verde = buona), grigio = nessuna finestra
        void DisegnaDgCal(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            Rectangle cr = pnlDgCal.ClientRectangle;
            if (cr.Width < 100 || cr.Height < 40) return;
            RectangleF card = new RectangleF(cr.Left + S(4), cr.Top + S(2), cr.Width - S(12), cr.Height - S(10));
            Scheda(g, card, Color.Empty);
            int n = dgGiorni.Count;
            using (Font fh = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(12), false))
            {
                Testo(g, string.Format(ci, Lang.T("Prossimi {0} giorni"), n).ToUpper(Lang.Cultura), fh, Tema.Muted,
                    new RectangleF(card.Left + S(20), card.Top + S(6), card.Width / 2, S(20)), StringAlignment.Near, StringAlignment.Near);
                // legenda
                string[] lt = { Lang.T("Dgrd migliore"), Lang.T("Dgrd peggiore"), Lang.T("nessuna finestra con i tuoi limiti"), "☀ " + Lang.T("Sole vicino alla Luna") };
                Color[] lc = { Tema.OkFg, Tema.WarnFg, Tema.SottoFg, Color.FromArgb(230, 60, 40) };
                float xl = card.Right - S(20);
                for (int i = 3; i >= 0; i--)
                {
                    float wl = g.MeasureString(lt[i], fs).Width;
                    xl -= wl;
                    Testo(g, lt[i], fs, Tema.Muted, new RectangleF(xl, card.Top + S(6), wl + S(4), S(20)), StringAlignment.Near, StringAlignment.Near);
                    using (Brush b = new SolidBrush(lc[i])) g.FillRectangle(b, xl - S(15), card.Top + S(10), S(11), S(11));
                    xl -= S(34);
                }
            }
            dgCelle.Clear();
            if (n == 0) return;
            float x0 = card.Left + S(16), y0 = card.Top + S(30), wc = (card.Width - S(32)) / n, hc = card.Bottom - S(8) - y0;
            bool stretta = wc < S(38);
            using (Font fw = FontPx(Lang.FontUi, Math.Min(S(12), wc * 0.32f), true))
            using (Font fn = FontPx(FamigliaNumeri, Math.Min(S(24), wc * 0.5f), true))
            using (Font fo = FontPx(Lang.FontUi, Math.Min(S(12), wc * 0.3f), true))
                for (int i = 0; i < n; i++)
                {
                    GiornoEme gg = dgGiorni[i];
                    bool ok = !double.IsNaN(gg.Score);
                    RectangleF c = new RectangleF(x0 + i * wc + 1.5f, y0, wc - 3f, hc);
                    Color fondo;
                    if (ok)
                    {
                        double q = Math.Max(0, Math.Min(1, (gg.Score + 4.0) / 4.0));
                        fondo = Color.FromArgb((int)(Tema.WarnFg.R + (Tema.OkFg.R - Tema.WarnFg.R) * q), (int)(Tema.WarnFg.G + (Tema.OkFg.G - Tema.WarnFg.G) * q),
                            (int)(Tema.WarnFg.B + (Tema.OkFg.B - Tema.WarnFg.B) * q));
                    }
                    else fondo = Color.FromArgb(Tema.Scuro ? 90 : 110, Tema.SottoFg);
                    bool sel = gg.Giorno.Date == dgEvid;
                    if (sel) fondo = Color.FromArgb(200, 224, 250);   // giorno scelto: cella azzurra con bordo blu
                    using (GraphicsPath p = Arrotondato(c, S(7)))
                    using (Brush b = new SolidBrush(fondo)) g.FillPath(b, p);
                    if (gg.Giorno == dgStart)
                        using (GraphicsPath p = Arrotondato(c, S(7)))
                        using (Pen pn = new Pen(Tema.Fore, 2f)) g.DrawPath(pn, p);
                    if (sel)
                        using (GraphicsPath p = Arrotondato(new RectangleF(c.X - 1, c.Y - 1, c.Width + 2, c.Height + 2), S(8)))
                        using (Pen pn = new Pen(Color.FromArgb(31, 111, 209), S(2.5f))) g.DrawPath(pn, p);
                    dgCelle.Add(new KeyValuePair<RectangleF, DateTime>(c, gg.Giorno.Date));
                    Color ct = ok || sel ? Color.FromArgb(14, 20, 34) : Tema.Fore;
                    Color cm = ok || sel ? Color.FromArgb(40, 48, 64) : Tema.Muted;
                    float y = c.Top + S(3);
                    if (!stretta)
                        Testo(g, gg.Giorno.ToString("ddd", itCi), fw, cm, new RectangleF(c.Left, y, c.Width, hc * 0.18f), StringAlignment.Center, StringAlignment.Center);
                    y += hc * 0.18f;
                    Testo(g, gg.Giorno.Day.ToString(ci), fn, ct, new RectangleF(c.Left - 4, y, c.Width + 8, hc * 0.27f), StringAlignment.Center, StringAlignment.Center);
                    y += hc * 0.27f;
                    float rm = Math.Min(c.Width * 0.3f, hc * 0.1f);
                    if (!double.IsNaN(gg.Illum)) DisegnaFase(g, new PointF(c.Left + c.Width / 2, y + hc * 0.13f), rm, gg.Illum, gg.Crescente);
                    y += hc * 0.28f;
                    if (gg.SoleLiv > 0)
                        using (Font fsun = FontPx("Segoe UI Symbol", Math.Min(S(16), c.Width * 0.4f), true))
                        using (Brush bsun = new SolidBrush(gg.SoleLiv == 2 ? Color.FromArgb(230, 40, 30) : Color.FromArgb(200, 120, 0)))
                            g.DrawString("☀", fsun, bsun, c.Right - fsun.Size * 1.05f, c.Top + 1);
                    string ore = ok ? (gg.Rango <= 3 ? "★" + gg.Rango.ToString(ci) + (stretta ? "" : " ") : "") + (stretta && gg.Rango <= 3 ? "" : gg.Ore.ToString("0.0", ci) + (stretta ? "" : " h")) : "—";
                    Testo(g, ore, fo, cm, new RectangleF(c.Left - 4, y, c.Width + 8, hc * 0.22f), StringAlignment.Center, StringAlignment.Center);
                }
        }

        // Disco della luna nuova: nero con bordo bianco e contorno scuro, leggibile su fondo chiaro e scuro
        static void DiscoLunaNuova(Graphics g, float cx, float cy, float r)
        {
            using (Brush b = new SolidBrush(Color.Black)) g.FillEllipse(b, cx - r, cy - r, 2 * r, 2 * r);
            using (Pen p = new Pen(Color.White, Math.Max(1.5f, r / 4))) g.DrawEllipse(p, cx - r, cy - r, 2 * r, 2 * r);
            using (Pen p2 = new Pen(Color.Black, 1f)) g.DrawEllipse(p2, cx - r - 1.5f, cy - r - 1.5f, 2 * r + 3, 2 * r + 3);
        }

        DateTime dgEvid = DateTime.MinValue;    // giorno evidenziato con un clic nella striscia dei giorni
        RectangleF titoloKm;

        // Scritta della luna nuova / piena: a destra del disco, oppure a sinistra se coprirebbe il titolo della scala dei km
        void EtichettaLuna(Graphics g, string t, Font f, Brush b, float x, float y)
        {
            SizeF sz = g.MeasureString(t, f);
            RectangleF r = new RectangleF(x + S(10), y, sz.Width, sz.Height);
            if (r.IntersectsWith(titoloKm)) r.X = x - S(10) - sz.Width;
            g.DrawString(t, f, b, r.X, r.Y);
        }

        void DgChart_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
            dgChart.BackColor = Tema.ChartBg;
            Rectangle cr = dgChart.ClientRectangle;
            if (dgT.Count < 2) return;
            int ml = S(56), mr = S(70), mt = S(40), mb = S(36);
            RectangleF a = new RectangleF(ml, mt, Math.Max(10, cr.Width - ml - mr), Math.Max(10, cr.Height - mt - mb));
            // striscia della declinazione sotto il grafico, con lo stesso asse dei giorni
            RectangleF dRet = RectangleF.Empty;
            if (chkDgDec != null && chkDgDec.Checked && dgDec.Count == dgT.Count && a.Height > S(240))
            {
                float hd = Math.Max(S(78), a.Height * 0.24f), gap = S(26);
                dRet = new RectangleF(a.Left, a.Bottom - hd, a.Width, hd);
                a.Height -= hd + gap;
            }
            float yFine = dRet.IsEmpty ? a.Bottom : dRet.Bottom;
            double t0 = dgStart.Ticks, t1 = dgEnd.Ticks;
            // distanza media diurna
            double kmin = double.MaxValue, kmax = double.MinValue;
            foreach (GiornoEme gg in dgGiorni) { kmin = Math.Min(kmin, gg.DistMedia); kmax = Math.Max(kmax, gg.DistMedia); }
            kmin = Math.Floor(kmin / 5000) * 5000; kmax = Math.Ceiling(kmax / 5000) * 5000;
            if (kmax - kmin < 10000) kmax = kmin + 10000;
            Func<DateTime, float> X = tq => a.Left + (float)((tq.Ticks - t0) / (t1 - t0) * a.Width);
            // asse Dgrd invertito: 0 dB in basso, -15 dB in alto
            Func<double, float> Yd = vd => a.Top + (float)((Math.Max(DgMin, Math.Min(0, vd)) - DgMin) / (0 - DgMin) * a.Height);
            Func<double, float> Yk = vk => a.Top + (float)((kmax - vk) / (kmax - kmin) * a.Height);
            Font fs = new Font(Lang.FontUi, 8F);
            Font fb = new Font(Lang.FontUi, 8.5F, FontStyle.Bold);
            Color cDg = ColoreDg();
            Color cKm = ColoreKm(), cOk = Tema.Scuro ? Color.FromArgb(90, 210, 120) : Color.FromArgb(20, 150, 70);

            // giorni con il Sole vicino alla Luna (fascia gialla o arancione e simbolo del Sole in alto)
            using (Font fsun = new Font("Segoe UI Symbol", 10F, FontStyle.Bold))
                foreach (GiornoEme gg in dgGiorni)
                {
                    if (gg.SoleLiv == 0) continue;
                    float x0 = X(gg.Giorno), x1 = X(gg.Giorno.AddDays(1));
                    Color cs = gg.SoleLiv == 2 ? Color.FromArgb(230, 60, 40) : Color.FromArgb(240, 160, 30);
                    using (Brush bs = new SolidBrush(Color.FromArgb(gg.SoleLiv == 2 ? 50 : 30, cs))) g.FillRectangle(bs, x0, a.Top, x1 - x0, yFine - a.Top);
                    using (Brush bt = new SolidBrush(cs)) g.DrawString("☀", fsun, bt, (x0 + x1) / 2 - S(8), a.Bottom - S(22));
                }

            // giorno scelto nella striscia dei giorni: fascia azzurra sulle sue 24 ore UTC
            if (dgEvid != DateTime.MinValue && dgEvid >= dgStart.Date && dgEvid < dgEnd)
            {
                float x0 = Math.Max(a.Left, X(dgEvid)), x1 = Math.Min(a.Right, X(dgEvid.AddDays(1)));
                using (Brush be = new SolidBrush(Color.FromArgb(Tema.Scuro ? 70 : 60, 80, 160, 255))) g.FillRectangle(be, x0, a.Top, x1 - x0, yFine - a.Top);
                using (Pen pe = new Pen(Color.FromArgb(160, 31, 111, 209), 1.2f)) { g.DrawLine(pe, x0, a.Top, x0, yFine); g.DrawLine(pe, x1, a.Top, x1, yFine); }
                string et = dgEvid.ToString("ddd dd/MM", Lang.Cultura);
                SizeF sze = g.MeasureString(et, fb);
                RectangleF re = new RectangleF((x0 + x1 - sze.Width) / 2 - S(4), a.Top + S(4), sze.Width + S(8), sze.Height + S(2));
                using (GraphicsPath pr = Arrotondato(re, S(4)))
                {
                    g.FillPath(Brushes.White, pr);
                    using (Pen pb = new Pen(Color.FromArgb(31, 111, 209), S(1.2f))) g.DrawPath(pb, pr);
                }
                using (Brush tb2 = new SolidBrush(Color.FromArgb(31, 111, 209))) g.DrawString(et, fb, tb2, re.Left + S(4), re.Top + 1);
            }

            // giorni migliori (fasce verdi con stella)
            using (Brush top = new SolidBrush(Color.FromArgb(55, 40, 180, 80)))
            using (Brush tb = new SolidBrush(cOk))
            {
                for (int i = 0; i < dgTop.Count; i++)
                {
                    float x0 = X(dgTop[i]), x1 = X(dgTop[i].AddDays(1));
                    g.FillRectangle(top, x0, a.Top, x1 - x0, yFine - a.Top);
                    string s = "★" + (i + 1).ToString(ci);
                    SizeF sz = g.MeasureString(s, fb);
                    g.DrawString(s, fb, tb, (x0 + x1 - sz.Width) / 2, a.Top - sz.Height - 2);
                }
            }

            // griglia e assi
            using (Pen gp = new Pen(Tema.ChartGrid))
            using (Brush txt = new SolidBrush(Tema.ChartText))
            using (Brush tdg = new SolidBrush(cDg))
            using (Brush tkm = new SolidBrush(cKm))
            {
                int giorni = (int)Math.Round((t1 - t0) / TimeSpan.TicksPerDay);
                int passo = Math.Max(1, (int)Math.Ceiling(giorni / (a.Width / S(55))));
                for (int d = 0; d <= giorni; d++)
                {
                    float x = X(dgStart.AddDays(d));
                    g.DrawLine(gp, x, a.Top, x, a.Bottom);
                    if (!dRet.IsEmpty) g.DrawLine(gp, x, dRet.Top, x, dRet.Bottom);
                    if (d % passo == 0 && d < giorni)
                        g.DrawString(dgStart.AddDays(d).ToString("dd/MM", inv), fs, txt, x + 2, yFine + S(3));
                }
                for (int v = 0; v >= (int)DgMin; v--)
                {
                    float y = Yd(v);
                    g.DrawLine(gp, a.Left, y, a.Right, y);
                    if (v % 3 == 0)
                    {
                        string s = v.ToString(ci);
                        g.DrawString(s, fs, tdg, a.Left - g.MeasureString(s, fs).Width - 4, y - S(7));
                    }
                }
                for (double v = kmin; v <= kmax + 1; v += 5000)
                    g.DrawString((v / 1000).ToString("0", ci) + "k", fs, tkm, a.Right + 4, Yk(v) - S(7));
                g.DrawString("Dgrd (dB)", fb, tdg, 4, 4);
                SizeF szk = g.MeasureString(Lang.T("Distanza media del giorno (km)"), fb);
                g.DrawString(Lang.T("Distanza media del giorno (km)"), fb, tkm, cr.Width - szk.Width - 4, 4);
                titoloKm = new RectangleF(cr.Width - szk.Width - 8, 0, szk.Width + 8, szk.Height + 6);
                g.DrawString(Lang.T("giorno (UTC)"), fs, txt, a.Left + a.Width / 2 - S(25), yFine + S(18));
            }

            // distanza media diurna (un punto per giorno, al centro del giorno) con perigeo e apogeo
            if (dgGiorni.Count > 1)
            {
                PointF[] pts = new PointF[dgGiorni.Count];
                for (int i = 0; i < dgGiorni.Count; i++) pts[i] = new PointF(X(dgGiorni[i].Giorno.AddHours(12)), Yk(dgGiorni[i].DistMedia));
                using (Pen pk = new Pen(cKm, (float)dgSpKm)) g.DrawLines(pk, pts);
                using (Brush tkm = new SolidBrush(cKm))
                {
                    for (int i = 0; i < pts.Length; i++) g.FillEllipse(tkm, pts[i].X - 2.5f, pts[i].Y - 2.5f, 5, 5);
                    for (int i = 1; i < dgGiorni.Count - 1; i++)
                    {
                        double dv = dgGiorni[i].DistMedia;
                        bool min = dv < dgGiorni[i - 1].DistMedia && dv <= dgGiorni[i + 1].DistMedia;
                        bool max = dv > dgGiorni[i - 1].DistMedia && dv >= dgGiorni[i + 1].DistMedia;
                        if (min || max)
                            g.DrawString((min ? Lang.T("perigeo ") : Lang.T("apogeo ")) + (dv / 1000).ToString("0", ci) + "k", fb, tkm,
                                pts[i].X + 4, min ? pts[i].Y + 3 : pts[i].Y - S(16));
                    }
                }
            }

            // Dgrd: linea sottile sempre, linea spessa verde nelle ore utili
            using (Pen pd = new Pen(cDg, (float)dgSpDg))
            using (Pen po = new Pen(cOk, (float)dgSpDg + 2f))
            {
                PointF[] pts = new PointF[dgT.Count];
                for (int i = 0; i < dgT.Count; i++) pts[i] = new PointF(X(dgT[i]), Yd(dgDgrd[i]));
                g.DrawLines(pd, pts);
                for (int i = 1; i < dgT.Count; i++)
                    if (dgOk[i] && dgOk[i - 1]) g.DrawLine(po, pts[i - 1], pts[i]);
            }

            // luna nuova: disco bianco e nero in alto, sulla giornata
            using (Brush tb = new SolidBrush(Tema.ChartText))
            {
                foreach (DateTime tn in dgNuova)
                {
                    float x = X(tn.Date.AddHours(12));
                    DiscoLunaNuova(g, x, a.Top - S(26), S(7));
                    EtichettaLuna(g, Lang.T("luna nuova"), fs, tb, x, a.Top - S(33));
                }
                foreach (DateTime tn in dgPiena)
                {
                    float x = X(tn.Date.AddHours(12));
                    using (Brush bp = new SolidBrush(Color.FromArgb(236, 233, 220))) g.FillEllipse(bp, x - S(7), a.Top - S(33), S(14), S(14));
                    using (Pen pp = new Pen(Color.FromArgb(120, 120, 120))) g.DrawEllipse(pp, x - S(7), a.Top - S(33), S(14), S(14));
                    EtichettaLuna(g, Lang.T("luna piena"), fs, tb, x, a.Top - S(33));
                }
            }

            if (!dRet.IsEmpty) DisegnaDeclinazione(g, dRet, X, fs, fb);

            // adesso
            DateTime now = DateTime.UtcNow;
            if (now >= dgStart && now <= dgEnd)
            {
                float x = X(now);
                using (Pen pn = new Pen(Tema.BadFg, 1.5f)) { pn.DashStyle = DashStyle.Dash; g.DrawLine(pn, x, a.Top, x, yFine); }
                using (Brush bn = new SolidBrush(Tema.BadFg)) g.DrawString(Lang.T("adesso"), fb, bn, x + 3, a.Top + S(2));
            }
            // legenda (in basso a sinistra, dove la Dgrd è vicina a 0 dB solo raramente)
            {
                float lx = a.Left + S(8), ly = a.Bottom - S(54);
                using (Brush bg = new SolidBrush(Color.FromArgb(220, Tema.ChartBg))) g.FillRectangle(bg, lx - 4, ly - 3, S(390), S(50));
                using (Pen p1 = new Pen(cDg, (float)dgSpDg)) g.DrawLine(p1, lx, ly + S(7), lx + S(24), ly + S(7));
                using (Pen p2 = new Pen(cOk, (float)dgSpDg + 2f)) g.DrawLine(p2, lx, ly + S(22), lx + S(24), ly + S(22));
                using (Pen p3 = new Pen(cKm, (float)dgSpKm)) g.DrawLine(p3, lx, ly + S(37), lx + S(24), ly + S(37));
                using (Brush tt = new SolidBrush(Tema.ChartText))
                {
                    g.DrawString(Lang.T("Dgrd per ") + me.Loc.Text.Trim() + " a " + dgFreq.ToString("0.000", ci) + Lang.T(" MHz (0 dB = ideale, in basso)"), fs, tt, lx + S(30), ly);
                    g.DrawString(dgDx ? Lang.T("ore con finestra comune con il DX") : Lang.T("ore con la Luna dentro i limiti della tua antenna"), fs, tt, lx + S(30), ly + S(15));
                    g.DrawString(Lang.T("distanza media del giorno (scala a destra)  -  ★ = 3 giorni migliori"), fs, tt, lx + S(30), ly + S(30));
                }
            }
            fs.Dispose();
            fb.Dispose();
        }

        // Striscia della declinazione della Luna (geocentrica), sotto il grafico Dgrd/distanza.
        // Verde: Luna dalla parte del mio emisfero (più alta e più ore sopra l'orizzonte); arancione: dalla parte opposta.
        void DisegnaDeclinazione(Graphics g, RectangleF d, Func<DateTime, float> X, Font fs, Font fb)
        {
            const double DecScala = 30.0;
            Func<double, float> Yc = vc => d.Top + (float)((DecScala - Math.Max(-DecScala, Math.Min(DecScala, vc))) / (2 * DecScala) * d.Height);
            Color cDec = Tema.Scuro ? Color.FromArgb(110, 175, 255) : Color.FromArgb(31, 111, 209);
            Color cMio = Tema.Scuro ? Color.FromArgb(90, 210, 120) : Color.FromArgb(20, 150, 70);
            Color cOpp = Color.FromArgb(240, 150, 40);
            bool nord = me.Lat >= 0;
            float y0 = Yc(0);
            using (Pen gp = new Pen(Tema.ChartGrid))
            using (Brush tdc = new SolidBrush(cDec))
            {
                g.DrawRectangle(gp, d.Left, d.Top, d.Width, d.Height);
                for (int v = -20; v <= 20; v += 20)
                {
                    float y = Yc(v);
                    if (v != 0) g.DrawLine(gp, d.Left, y, d.Right, y);
                    string sv = (v > 0 ? "+" : (v < 0 ? "−" : "")) + Math.Abs(v).ToString(ci) + "°";
                    g.DrawString(sv, fs, tdc, d.Left - g.MeasureString(sv, fs).Width - 4, y - S(7));
                }
                using (Pen p0 = new Pen(Tema.ChartText, 1f)) { p0.DashStyle = DashStyle.Dot; g.DrawLine(p0, d.Left, y0, d.Right, y0); }
            }
            int n = dgT.Count;
            PointF[] pts = new PointF[n];
            for (int i = 0; i < n; i++) pts[i] = new PointF(X(dgT[i]), Yc(dgDec[i]));
            // area tra la curva e lo zero: sopra (nord) e sotto (sud) con il colore del mio emisfero o di quello opposto
            using (GraphicsPath area = new GraphicsPath())
            {
                PointF[] poli = new PointF[n + 2];
                Array.Copy(pts, poli, n);
                poli[n] = new PointF(pts[n - 1].X, y0);
                poli[n + 1] = new PointF(pts[0].X, y0);
                area.AddPolygon(poli);
                GraphicsState st = g.Save();
                g.SetClip(new RectangleF(d.Left, d.Top, d.Width, y0 - d.Top));
                using (Brush bn = new SolidBrush(Color.FromArgb(Tema.Scuro ? 70 : 55, nord ? cMio : cOpp))) g.FillPath(bn, area);
                g.Restore(st);
                st = g.Save();
                g.SetClip(new RectangleF(d.Left, y0, d.Width, d.Bottom - y0));
                using (Brush bs = new SolidBrush(Color.FromArgb(Tema.Scuro ? 70 : 55, nord ? cOpp : cMio))) g.FillPath(bs, area);
                g.Restore(st);
            }
            using (Pen pc = new Pen(cDec, 1.8f)) g.DrawLines(pc, pts);
            // massimi a nord e a sud: punto e valore con la data (un estremo per ogni finestra di ±1 giorno)
            using (Brush tdc = new SolidBrush(cDec))
            {
                const int Fin = 48;   // campioni ogni 30 minuti: ±1 giorno
                for (int i = 1; i < n - 1; i++)
                {
                    bool mx = true, mn = true;
                    for (int j = Math.Max(0, i - Fin); j <= Math.Min(n - 1, i + Fin); j++)
                    {
                        if (j == i) continue;
                        if (dgDec[j] > dgDec[i] || (dgDec[j] == dgDec[i] && j < i)) mx = false;
                        if (dgDec[j] < dgDec[i] || (dgDec[j] == dgDec[i] && j < i)) mn = false;
                    }
                    if (!(mx && Math.Abs(dgDec[i]) > 5) && !(mn && Math.Abs(dgDec[i]) > 5)) continue;
                    // un estremo vicino al bordo del periodo non è affidabile
                    if (i < Fin / 2 || i > n - 1 - Fin / 2) continue;
                    g.FillEllipse(tdc, pts[i].X - S(3), pts[i].Y - S(3), S(6), S(6));
                    string et = (dgDec[i] > 0 ? "+" : "−") + Math.Abs(dgDec[i]).ToString("0.0", ci) + "° " + dgT[i].ToString("dd/MM", inv);
                    SizeF sz = g.MeasureString(et, fb);
                    float xe = Math.Min(d.Right - sz.Width - 2, Math.Max(d.Left + 2, pts[i].X - sz.Width / 2));
                    float ye = mx ? pts[i].Y + S(4) : pts[i].Y - sz.Height - S(4);
                    using (Brush bg = new SolidBrush(Color.FromArgb(200, Tema.ChartBg))) g.FillRectangle(bg, xe - 2, ye, sz.Width + 4, sz.Height);
                    g.DrawString(et, fb, tdc, xe, ye);
                }
                // titolo e legenda, sopra la striscia
                string tit = Lang.T("Declinazione della Luna (°)");
                SizeF szt = g.MeasureString(tit, fb);
                g.DrawString(tit, fb, tdc, d.Left, d.Top - szt.Height - 2);
                float lx = d.Left + szt.Width + S(18), ly = d.Top - szt.Height;
                using (Brush b1 = new SolidBrush(Color.FromArgb(150, cMio))) g.FillRectangle(b1, lx, ly + S(2), S(11), S(11));
                using (Brush tt = new SolidBrush(Tema.ChartText))
                {
                    string l1 = Lang.T("Luna più alta e più ore sopra l'orizzonte per ") + me.Loc.Text.Trim();
                    g.DrawString(l1, fs, tt, lx + S(15), ly);
                    lx += S(15) + g.MeasureString(l1, fs).Width + S(14);
                    string l2 = Lang.T("Luna dalla parte dell'emisfero opposto");
                    if (lx + S(15) + g.MeasureString(l2, fs).Width <= d.Right)
                    {
                        using (Brush b2 = new SolidBrush(Color.FromArgb(150, cOpp))) g.FillRectangle(b2, lx, ly + S(2), S(11), S(11));
                        g.DrawString(l2, fs, tt, lx + S(15), ly);
                    }
                }
            }
        }

