        // Legge un valore dal file delle impostazioni prima che le finestre siano costruite
        string LeggiImpostazione(string chiave)
        {
            try
            {
                if (!File.Exists(settingsPath)) return "";
                foreach (string line in File.ReadAllLines(settingsPath))
                {
                    int k = line.IndexOf('=');
                    if (k > 0 && line.Substring(0, k).Trim() == chiave) return line.Substring(k + 1).Trim();
                }
            }
            catch { }
            return "";
        }

        // Ricalcola la volta celeste o il grafico della Dgrd quando cambia la frequenza (con un breve ritardo)
        void FreqCambiata()
        {
            if (tabs == null) return;
            if (freqTimer == null)
            {
                freqTimer = new Timer();
                freqTimer.Interval = 700;
                freqTimer.Tick += (s, e) =>
                {
                    freqTimer.Stop();
                    if (tabs.SelectedTab == tpSky) RecalcSky();
                    if (tabs.SelectedTab == tpDgrd) RecalcDgrd();
                    if (tabs.SelectedTab == tpTrack) AggiornaTracciamento(true);
                };
            }
            freqTimer.Stop();
            freqTimer.Start();
        }

        void Tabs_DrawItem(object sender, DrawItemEventArgs e)
        {
            TabControl tc = (TabControl)sender;
            bool sel = e.Index == tc.SelectedIndex;
            Rectangle r = e.Bounds;
            using (Brush b = new SolidBrush(sel ? Tema.Section : Tema.Back)) e.Graphics.FillRectangle(b, r);
            bool spenta = tc == tabs && PaginaSpenta(tc.TabPages[e.Index]);
            TextRenderer.DrawText(e.Graphics, tc.TabPages[e.Index].Text, sel ? new Font(tc.Font, FontStyle.Bold) : tc.Font, r, spenta ? Tema.Muted : Tema.Fore,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);
        }

        bool NellaBarraBianca(Control c)
        {
            if ((c.Tag as string) == "su-carta") return true;
            for (Control x = c; x != null; x = x.Parent)
                if (x == barImp || (x is PannelloDisegno && (x.Tag as string) == "carta")) return x != c;
            return false;
        }

        Color temaForePrima = SystemColors.ControlText, temaMutedPrima = SystemColors.GrayText;

        void Colora(Control c)
        {
            if (c is SkyPanel || c is MapPanel) return;
            if (c is Pillola) { c.Invalidate(); return; }
            if (c is CorniceTonda)
            {
                CorniceTonda ct = (CorniceTonda)c;
                Colora(ct.Dentro);
                ct.Dentro.FlatStyle = FlatStyle.Flat;
                ct.Invalidate();
                return;
            }
            if (c is TextBox || c is RichTextBox || c is ComboBox || c is NumericUpDown || c is ListView)
            {
                c.BackColor = Tema.Field;
                c.ForeColor = Tema.FieldFore;
                ComboBox cb = c as ComboBox;
                if (cb != null) cb.FlatStyle = Tema.Scuro ? FlatStyle.Flat : FlatStyle.Standard;
            }
            else if (c is Button)
            {
                Button b = (Button)c;
                if (Tema.Scuro)
                {
                    b.FlatStyle = FlatStyle.Flat;
                    b.BackColor = Tema.Button;
                    b.ForeColor = Tema.Fore;
                    b.FlatAppearance.BorderColor = Tema.ChartGrid;
                }
                else
                {
                    b.FlatStyle = FlatStyle.Standard;
                    b.BackColor = SystemColors.Control;
                    b.UseVisualStyleBackColor = true;
                    b.ForeColor = SystemColors.ControlText;
                }
            }
            else if (c is DateTimePicker) { }
            else if (c is TabControl)
            {
                TabControl tc = (TabControl)c;
                tc.DrawMode = (Tema.Scuro || tc == tabs) ? TabDrawMode.OwnerDrawFixed : TabDrawMode.Normal;
                tc.Invalidate();
            }
            else
            {
                c.BackColor = NellaBarraBianca(c) ? Tema.Carta : Tema.Back;   // niente macchie grigie sulla fascia bianca
                if (c.ForeColor == temaMutedPrima || c.ForeColor == SystemColors.GrayText) c.ForeColor = Tema.Muted;
                else if (c.ForeColor == temaForePrima || c.ForeColor == SystemColors.ControlText) c.ForeColor = Tema.Fore;
            }
            foreach (Control ch in c.Controls) Colora(ch);
        }

        void ApplicaTema()
        {
            MondoAggiorna();   // la mappa di Luna sul mondo ha i colori del tema dentro la bitmap
            this.BackColor = Tema.Back;
            this.ForeColor = Tema.Fore;
            foreach (Control c in this.Controls) Colora(c);
            if (tabBande != null) Colora(tabBande);
            temaForePrima = Tema.Fore;
            temaMutedPrima = Tema.Muted;
            if (txtWin != null) { txtWin.BackColor = Tema.Field; txtWin.ForeColor = Tema.FieldFore; }
            if (dgChart != null) { dgChart.BackColor = Tema.ChartBg; dgChart.Invalidate(); }
