            if (rtAbout != null) ScriviAbout();
            UpdateLocators();
            UpdateLive();
            RecalcBudget();
            RiempiTabellaDg();
            AggiornaTracciamento(false);
            ApplicaSfondoTracciamento();
            AggiornaStileDg(false);
            if (pnlNav != null) pnlNav.Invalidate();
        }

        // Sfondo della schermata principale: Luna crescente sfocata, la parte in ombra non si vede
        void ApplicaSfondoTracciamento()
        {
            if (tpTrack == null) return;
            Bitmap nuovo = null;
            try { nuovo = LunaCrescente(Tema.Back, Tema.Scuro ? 0.42 : 0.30); } catch { nuovo = null; }
            tpTrack.BackgroundImage = nuovo;
            tpTrack.BackgroundImageLayout = ImageLayout.Zoom;
            if (sfondoTrk != null) sfondoTrk.Dispose();
            sfondoTrk = nuovo;
            if (nuovo == null) return;
            Trasparenti(tpTrack);
            DoppioBuffer(tpTrack);
        }

        static void Trasparenti(Control c)
        {
            foreach (Control ch in c.Controls)
            {
                if (ch is TextBox || ch is ComboBox || ch is NumericUpDown || ch is Button || ch is ListView) continue;
                if ((ch.Tag as string) == "opaco") { ch.BackColor = Tema.Field; ch.ForeColor = Tema.FieldFore; continue; }
                if (ch is Label || ch is CheckBox || ch is GroupBox || ch is Panel)
                {
                    try { ch.BackColor = Color.Transparent; } catch { }
                }
                Trasparenti(ch);
            }
        }

        static void DoppioBuffer(Control c)
        {
            try
            {
                System.Reflection.PropertyInfo pi = typeof(Control).GetProperty("DoubleBuffered",
                    System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                if (pi != null) pi.SetValue(c, true, null);
            }
            catch { }
            foreach (Control ch in c.Controls) if (ch is Panel || ch is GroupBox) DoppioBuffer(ch);
        }

        static Bitmap LunaCrescente(Color fondo, double alfa)
        {
            Image src = SplashForm.ImmagineLuna();
            if (src == null) return null;
            const int n = 140;
            Bitmap small = new Bitmap(n, n);
            using (Graphics g = Graphics.FromImage(small))
            {
                g.Clear(Color.Black);
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.DrawImage(src, 0, 0, n, n);
            }
            src.Dispose();
            double k = 0.32;          // frazione illuminata: Luna crescente, illuminata a destra
            double r = n / 2.0 - 1;
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    double dx = (x + 0.5 - n / 2.0) / r, dy = (y + 0.5 - n / 2.0) / r;
                    double rr = dx * dx + dy * dy;
                    double m = 0;
                    if (rr < 1)
                    {
                        double w = Math.Sqrt(1 - dy * dy);
                        double xt = (1 - 2 * k) * w;   // terminatore
                        m = Math.Max(0, Math.Min(1, (dx - xt) / 0.12));
                        m *= Math.Max(0, Math.Min(1, (1 - Math.Sqrt(rr)) / 0.04));
                    }
                    Color p = small.GetPixel(x, y);
                    double a = alfa * m;
                    small.SetPixel(x, y, Color.FromArgb(
                        (int)(fondo.R + (p.R - fondo.R) * a), (int)(fondo.G + (p.G - fondo.G) * a), (int)(fondo.B + (p.B - fondo.B) * a)));
                }
            Bitmap big = new Bitmap(720, 720);
            using (Graphics g = Graphics.FromImage(big))
            using (System.Drawing.Imaging.ImageAttributes ia = new System.Drawing.Imaging.ImageAttributes())
            {
                ia.SetWrapMode(WrapMode.TileFlipXY);
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                g.DrawImage(small, new Rectangle(0, 0, 720, 720), 0, 0, n, n, GraphicsUnit.Pixel, ia);
            }
            small.Dispose();
            return big;
        }

