            cardDx.Paint += (s, e) => DisegnaScheda(e.Graphics, cardDx, Lang.T("QTH - Locator WWL DX"), null, Color.Empty, subDx, subDxCol, "", txtTrkDx, Tema.Linea, 1f);
            txtTrkLoc.TextChanged += (s, e) =>
            {
