            dtpTrkGiorno.Format = DateTimePickerFormat.Custom;
            dtpTrkGiorno.CustomFormat = "dd/MM/yyyy";
            dtpTrkGiorno.Font = new Font(Lang.FontUi, 11F * fontFactor, FontStyle.Bold);
            dtpTrkGiorno.Value = DateTime.UtcNow.Date;
            tip.SetToolTip(dtpTrkGiorno, Lang.T("Giorno del tracciamento (UTC): apri il calendario per scegliere un giorno passato o futuro; l'ora si sceglie trascinando la linea rossa delle 24 ore in basso."));
            btnTrkAdesso = new Pillola("▶ " + Lang.T("Adesso"), StilePillola.Pieno, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 8.5F * fontFactor, FontStyle.Bold));
            tip.SetToolTip(btnTrkAdesso, Lang.T("Torna al tracciamento in diretta, con l'ora attuale."));
            cardFreq.Controls.Add(dtpTrkGiorno);
            cardFreq.Controls.Add(btnTrkAdesso);
            cardFreq.Layout += (s, e) =>
            {
                dtpTrkGiorno.Location = new Point(S(14), S(29));
                dtpTrkGiorno.Width = Math.Max(S(90), Math.Min(cardFreq.Width - S(28), S(150)));
                btnTrkAdesso.Location = new Point(S(14), dtpTrkGiorno.Bottom + S(4));
            };
            cardFreq.Paint += (s, e) => DisegnaScheda(e.Graphics, cardFreq, Lang.T("Giorno (UTC)"), null, Color.Empty, "", Tema.Muted,
                trkScelto.HasValue ? "" : Lang.T("in diretta"), null, Color.Empty, 0);
            dtpTrkGiorno.ValueChanged += (s, e) =>
            {
                if (trkSyncGiorno) return;
                DateTime g0 = dtpTrkGiorno.Value.Date;
                DateTime ora = trkScelto.HasValue ? trkScelto.Value : DateTime.UtcNow;
                trkScelto = DateTime.SpecifyKind(g0.Add(new TimeSpan(ora.Hour, ora.Minute, 0)), DateTimeKind.Utc);
                AggiornaTracciamento(true);
            };
            btnTrkAdesso.Click += (s, e) => { trkScelto = null; AggiornaTracciamento(true); };
            cmbTrkMhz.TextChanged += (s, e) => { if (!syncFreq) { syncFreq = true; cmbFreq.Text = cmbTrkMhz.Text; syncFreq = false; } AggiornaSottoFreq(); };
            cmbTrkKhz.TextChanged += (s, e) => { if (!syncFreq) { syncFreq = true; cmbKhz.Text = cmbTrkKhz.Text; syncFreq = false; } };

            cardUtc.Paint += (s, e) => DisegnaOrologio(e.Graphics, cardUtc, 0);
            cardLoc.Paint += (s, e) => DisegnaOrologio(e.Graphics, cardLoc, 1);
            cardLocDx.Paint += (s, e) => DisegnaOrologio(e.Graphics, cardLocDx, 2);

            // fascia di stato, bussola, elevazione, riquadri dei dati e prossime 24 ore: tutto disegnato
            pnlTrk = new PannelloDisegno();
            pnlTrk.Dock = DockStyle.Fill;
            pnlTrk.Margin = new Padding(S(10), S(4), S(10), S(6));
            pnlTrk.Paint += DisegnaTrk;
            pnlTrk.Controls.Add(cmbTrkMhz);
            pnlTrk.Controls.Add(lblTrkPunto);
            pnlTrk.Controls.Add(cmbTrkKhz);
            // la linea rossa delle 24 ore si trascina (o si clicca un punto della striscia): tracciamento per quel momento
            pnlTrk.MouseDown += (s, e) =>
            {
                if (e.Button != MouseButtons.Left || !trkStrRett.Contains(e.Location) || trk.StrisciaT0 == DateTime.MinValue) return;
                trkTrascina = true;
                TrkOraDaX(e.X);
            };
            pnlTrk.MouseUp += (s, e) => { if (trkTrascina) { trkTrascina = false; AggiornaTracciamento(true); } };
            bool tipTrk = false;
            pnlTrk.MouseMove += (s, e) =>
            {
                if (trkTrascina) { TrkOraDaX(e.X); return; }
                bool su = trkStrRett.Contains(e.Location);
                foreach (KeyValuePair<RectangleF, Action> kv in trkZone) if (kv.Key.Contains(e.Location)) su = true;
                pnlTrk.Cursor = trkStrRett.Contains(e.Location) ? Cursors.SizeWE : (su ? Cursors.Hand : Cursors.Default);
                bool sopra = trkTipZona.Contains(e.Location);
                if (sopra && !tipTrk)
                {
                    Fumetto.Ultimo = Lang.T("CALCOLI APPROFONDITI") + "\u0001" + Lang.T("Attiva la linguetta Rumore solare, le colonne da Dpol in poi nella tabella della Posizione della Luna e tutte le righe intermedie del Budget EME (i calcoli vengono fatti sempre tutti).")
                        + "\n" + Lang.T("Casella sincronizzata: è la stessa casella che trovi in alto a destra nel Budget EME; se la cambi qui cambia anche là, e viceversa.");
                    tip.Show(Fumetto.Ultimo, pnlTrk, (int)trkTipZona.Left, (int)trkTipZona.Bottom + S(6), 15000);
                }
                else if (!sopra && tipTrk) tip.Hide(pnlTrk);
                tipTrk = sopra;
            };
            pnlTrk.MouseLeave += (s, e) => { if (tipTrk) { tip.Hide(pnlTrk); tipTrk = false; } };
            pnlTrk.MouseClick += (s, e) =>
            {
                foreach (KeyValuePair<RectangleF, Action> kv in trkZone)
                    if (kv.Key.Contains(e.Location)) { kv.Value(); pnlTrk.Invalidate(); break; }
            };
            root.Controls.Add(pnlTrk, 0, 2);

            tp.Controls.Add(root);

            trkTimer = new Timer();
            trkTimer.Interval = 1000;
            trkTimer.Tick += (s, e) => { if (tabs != null && tabs.SelectedTab == tpTrack) AggiornaTracciamento(false); };
            trkTimer.Start();
        }

        // Posizione x nella striscia delle 24 ore → momento scelto (al minuto)
        void TrkOraDaX(int x)
        {
            if (trkStrBw <= 0) return;
            double h = Math.Max(0, Math.Min(24.0 - 1.0 / 60.0, (x - trkStrBx) / trkStrBw * 24.0));
            DateTime t = trk.StrisciaT0.AddMinutes(Math.Round(h * 60.0));
            if (trkScelto.HasValue && trkScelto.Value == t) return;
            trkScelto = t;
            AggiornaTracciamento(false);
        }

        // "banda 144 MHz" sotto la frequenza, se i MHz sono una delle bande scelte
        void AggiornaSottoFreq()
        {
            if (cardFreq == null || cmbTrkMhz == null) return;
            double mhz;
            string t = "";
            if (double.TryParse(cmbTrkMhz.Text.Trim().Replace(',', '.'), NumberStyles.Float, inv, out mhz) && bandeAttive.Contains((int)Math.Floor(mhz)))
                t = string.Format(ci, Lang.T("banda {0} MHz"), (int)Math.Floor(mhz));
            if (t != subFreq) { subFreq = t; cardFreq.Invalidate(); }
        }

        // Scheda della riga in alto: titolo, valore grande o casella con bordo, riga sotto con eventuale etichetta verde
        void DisegnaScheda(Graphics g, Control p, string titolo, string valore, Color cv, string sotto, Color cs, string badge, Control box, Color bordo, float spess)
        {
            PreparaGrafica(g);
            RectangleF r = new RectangleF(0, 0, p.ClientSize.Width - S(3), p.ClientSize.Height - S(5));
            if (r.Width < 30 || r.Height < 30) return;
            Scheda(g, r, Color.Empty);
            using (Font ft = FontPx(Lang.FontUi, S(12), false))
            using (Font fv = FontPx(FamigliaNumeri, S(30), true))
            using (Font fs = FontPx(Lang.FontUi, S(13), false))
            using (Font fb = FontPx(Lang.FontUi, S(12), true))
            {
                Testo(g, titolo.ToUpper(Lang.Cultura), ft, Tema.Muted, new RectangleF(r.Left + S(12), r.Top + S(7), r.Width - S(18), S(18)), StringAlignment.Near, StringAlignment.Near);
                if (valore != null)
                    Testo(g, valore, fv, cv, new RectangleF(r.Left + S(9), r.Top + S(23), r.Width - S(12), S(40)), StringAlignment.Near, StringAlignment.Center);
                if (box != null)
                {
                    RectangleF rb = new RectangleF(box.Left - S(7), box.Top - S(4), box.Width + S(14), box.Height + S(8));
                    using (GraphicsPath gp = Arrotondato(rb, S(5)))
                    {
                        using (Brush b = new SolidBrush(Tema.Field)) g.FillPath(b, gp);
                        using (Pen pn = new Pen(bordo, spess)) g.DrawPath(pn, gp);
                    }
                }
                if (!string.IsNullOrEmpty(sotto) || !string.IsNullOrEmpty(badge))
                {
                    float y = r.Bottom - S(26), x = r.Left + S(12), wMax = r.Width - S(22);
                    float ws = string.IsNullOrEmpty(sotto) ? 0 : Math.Min(wMax, g.MeasureString(sotto, fs).Width);
                    if (ws > 0) Testo(g, sotto, fs, cs, new RectangleF(x, y, ws + S(2), S(20)), StringAlignment.Near, StringAlignment.Center);
                    if (!string.IsNullOrEmpty(badge))
                    {
                        // l'etichetta va intera accanto alla riga sotto; se non ci sta, in alto a destra accanto al titolo
                        SizeF sb = g.MeasureString(badge, fb);
                        float wp = sb.Width + S(10);
                        RectangleF rp;
                        if (ws + S(5) + wp <= wMax) rp = new RectangleF(x + ws + S(5), y + S(1), wp, S(18));
                        else
                        {
                            float wt = g.MeasureString(titolo.ToUpper(Lang.Cultura), ft).Width;
                            if (S(12) + wt + S(8) + wp > r.Width - S(8)) return;
                            rp = new RectangleF(r.Right - S(8) - wp, r.Top + S(6), wp, S(18));
                        }
                        using (GraphicsPath gp = Arrotondato(rp, S(8)))
                        using (Brush b = new SolidBrush(Tema.Scuro ? Color.FromArgb(70, Tema.OkFg) : Color.FromArgb(227, 244, 232))) g.FillPath(b, gp);
                        Testo(g, badge, fb, Tema.OkFg, rp, StringAlignment.Center, StringAlignment.Center);
                    }
                }
            }
        }

        // Orologi: 0 ora UTC, 1 ora locale (mia), 2 ora locale del DX
        void DisegnaOrologio(Graphics g, Control p, int i)
        {
            DateTime now = trk.Utc == DateTime.MinValue ? DateTime.UtcNow : trk.Utc;
            string tit, val, sot;
            Color c = CVal;
            if (i == 0)
            {
                tit = Lang.T("ORA UTC");
                val = now.ToString("HH:mm:ss", inv);
                sot = now.ToString("ddd dd/MM/yyyy", Lang.Cultura);
            }
            else if (i == 1)
            {
                tit = Lang.T("Ora locale (mia)");
                val = TimeZoneInfo.ConvertTimeFromUtc(now, TimeZoneInfo.Local).ToString("HH:mm", inv);
                sot = ScartoBreve(TimeZoneInfo.Local.GetUtcOffset(now));
            }
            else
            {
                tit = Lang.T("Ora locale del DX");
                c = ColArancio;
                if (trk.DxValido && trk.DxTz != null)
                {
                    val = TimeZoneInfo.ConvertTimeFromUtc(now, trk.DxTz).ToString("HH:mm", inv);
                    sot = ScartoBreve(trk.DxTz.GetUtcOffset(now));
                }
                else { val = "--:--"; sot = ""; }
            }
            DisegnaScheda(g, p, tit, val, c, sot, Tema.Muted, "", null, Color.Empty, 0);
        }

        static string Scarto(TimeSpan off)
        {
            return string.Format(CultureInfo.InvariantCulture, "UTC{0}{1:00}:{2:00}", off < TimeSpan.Zero ? "-" : "+", Math.Abs(off.Hours), Math.Abs(off.Minutes));
        }

        // "UTC+9", "UTC+5:30", "UTC−3"
        static string ScartoBreve(TimeSpan off)
        {
            string s = off < TimeSpan.Zero ? "−" : "+";
            int h = Math.Abs(off.Hours), m = Math.Abs(off.Minutes);
            return "UTC" + s + h.ToString(CultureInfo.InvariantCulture) + (m != 0 ? ":" + m.ToString("00", CultureInfo.InvariantCulture) : "");
        }

        void InvalidaSchede()
        {
            foreach (Control c in new Control[] { cardMe, cardDx, cardFreq, cardUtc, cardLoc, cardLocDx }) if (c != null) c.Invalidate();
        }

        // "40,556° N 14,234° E"
        static string CoordBreve(double lat, double lon, CultureInfo c)
        {
            return string.Format(c, "{0:F3}° {1} {2:F3}° {3}", Math.Abs(lat), lat >= 0 ? "N" : "S", Math.Abs(lon), lon >= 0 ? "E" : "W");
        }

        // Collega le caselle della linguetta principale a quelle delle altre linguette (nei due sensi)
        void AgganciaLocatorTracciamento()
        {
            syncLoc = true; txtTrkLoc.Text = me.Loc.Text; syncLoc = false;
            syncDx = true; txtTrkDx.Text = dx.Loc.Text; syncDx = false;
            syncFreq = true; cmbTrkMhz.Text = cmbFreq.Text; cmbTrkKhz.Text = cmbKhz.Text; syncFreq = false;
            me.Loc.TextChanged += (s, e) =>
            {
                if (syncLoc) return;
                syncLoc = true; txtTrkLoc.Text = me.Loc.Text; syncLoc = false;
                trkWinCalc = DateTime.MinValue;
            };
            dx.Loc.TextChanged += (s, e) =>
            {
                if (syncDx) return;
                syncDx = true; txtTrkDx.Text = dx.Loc.Text; syncDx = false;
                trkWinCalc = DateTime.MinValue;
            };
            cmbFreq.TextChanged += (s, e) =>
            {
                if (!syncFreq) { syncFreq = true; cmbTrkMhz.Text = cmbFreq.Text; syncFreq = false; }
                FreqVersoBanda();
            };
            cmbKhz.TextChanged += (s, e) =>
            {
                if (!syncFreq) { syncFreq = true; cmbTrkKhz.Text = cmbKhz.Text; syncFreq = false; }
            };
            chkDx.CheckedChanged += (s, e) => { trkWinCalc = DateTime.MinValue; };
            FreqVersoBanda();
            AggiornaTracciamento(true);
        }

        // Se i MHz della frequenza di lavoro sono 50, 144 o 432, il budget passa a quella banda
        bool syncBanda;
        void FreqVersoBanda()
        {
            if (syncBanda || cmbBand == null) return;
            double mhz;
            if (!double.TryParse(cmbFreq.Text.Trim().Replace(',', '.'), NumberStyles.Float, inv, out mhz)) return;
            int idx = bandeAttive.IndexOf((int)Math.Floor(mhz));
            if (idx >= 0 && idx != cmbBand.SelectedIndex)
            {
                syncBanda = true;
                cmbBand.SelectedIndex = idx;
                syncBanda = false;
            }
        }

        // Se nel budget si cambia banda, la frequenza di lavoro passa a quei MHz (i kHz restano)
        void BandaVersoFreq()
        {
            if (syncBanda || cmbFreq == null) return;
            double mhz;
            bool ok = double.TryParse(cmbFreq.Text.Trim().Replace(',', '.'), NumberStyles.Float, inv, out mhz);
            if (ok && (int)Math.Floor(mhz) == curBand) return;
            syncBanda = true;
            cmbFreq.Text = curBand.ToString(inv);
            syncBanda = false;
        }

        // Prossima finestra utile (o fine di quella in corso), passo 2 minuti fino a 3 giorni
        string ProssimaFinestra(DateTime t0)
        {
            Func<DateTime, bool> ok = tt =>
            {
                bool okMe;
                MoonPos p = Moon.Compute(tt, me.Lat, me.Lon, (double)me.H.Value, chkRefr.Checked);
                me.Valuta(p, out okMe);
                if (!okMe || !(chkDx.Checked && dx.Ok)) return okMe;
                bool okDx;
                MoonPos q = Moon.Compute(tt, dx.Lat, dx.Lon, (double)dx.H.Value, chkRefr.Checked);
                dx.Valuta(q, out okDx);
                return okDx;
            };
            string chi = (chkDx.Checked && dx.Ok) ? Lang.T("finestra comune con il DX") : Lang.T("finestra utile");
            DateTime lim = t0.AddDays(3);
            DateTime t = t0;
            if (ok(t))
            {
                while (t < lim && ok(t)) t = t.AddMinutes(2);
                return string.Format(ci, Lang.T("In corso: {0} fino alle {1} UTC (ora locale {2}), ancora {3}."), chi, FmtT(t),
                    FmtT(TimeZoneInfo.ConvertTimeFromUtc(t, TimeZoneInfo.Local)), Durata(t - t0));
            }
            while (t < lim && !ok(t)) t = t.AddMinutes(2);
            if (t >= lim) return Lang.T("Nessuna ") + chi + Lang.T(" nei prossimi 3 giorni con i limiti attuali.");
            DateTime a = t;
            while (t < lim && ok(t)) t = t.AddMinutes(2);
            return string.Format(ci, Lang.T("Prossima {0}: {1} → {2} UTC (ora locale {3} → {4}), tra {5}, durata {6}."), chi,
                FmtWD(a).Substring(0, 9) + " " + FmtT(a), FmtT(t),
                FmtT(TimeZoneInfo.ConvertTimeFromUtc(a, TimeZoneInfo.Local)), FmtT(TimeZoneInfo.ConvertTimeFromUtc(t, TimeZoneInfo.Local)),
                Durata(a - t0), Durata(t - a));
        }

        static string Durata(TimeSpan d)
        {
            int m = (int)Math.Round(d.TotalMinutes);
            return (m / 60).ToString(CultureInfo.InvariantCulture) + " h " + (m % 60).ToString("00", CultureInfo.InvariantCulture) + " min";
        }

        // Carattere che si adatta allo spazio disponibile (testo su più righe compreso)
        void AdattaFont(Label l, float maxPt)
        {
            if (l == null || l.Width < 10 || l.Height < 10 || string.IsNullOrEmpty(l.Text)) return;
            Size area = new Size(l.ClientSize.Width - S(8), l.ClientSize.Height - S(4));
            float pt = maxPt * fontFactor;
            while (pt > 7F)
            {
                using (Font f = new Font(Lang.FontUi, pt, FontStyle.Bold))
                {
                    Size sz = TextRenderer.MeasureText(l.Text, f);
                    if (sz.Width <= area.Width && sz.Height <= area.Height) break;
                }
                pt -= 1F;
            }
            if (Math.Abs(l.Font.Size - pt) > 0.1F) l.Font = new Font(Lang.FontUi, pt, FontStyle.Bold);
        }

