            AggiungiParametro(Lang.T("Guadagno preampli (dB)"), bMe.PreGain, bDx.PreGain);
            AggiungiParametro(Lang.T("Cifra di rumore preampli (dB)"), bMe.Nf, bDx.Nf);
            AggiungiParametro(Lang.T("Cavo di discesa: lunghezza (m)"), bMe.LenDis, bDx.LenDis);
            AggiungiParametro(Lang.T("Guadagno transverter (dB)"), bMe.TvGain, bDx.TvGain);
            AggiungiParametro(Lang.T("Cifra di rumore transverter (dB)"), bMe.TvNf, bDx.TvNf);
            AggiungiParametro(Lang.T("Perdita cavetti transverter-radio (dB)"), bMe.TvCavo, bDx.TvCavo);
            AggiungiParametro(Lang.T("MDS della radio (dBm)"), bMe.Mds, bDx.Mds);
            AggiungiParametro(Lang.T("Temperatura d'antenna Tant (K)"), bMe.Tant, bDx.Tant);

