            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.Padding = new Padding(S(4));

            Label nota = L(Lang.T("Le caselle verdi si possono modificare: scrivi il valore e premi Invio. I parametri sono gli stessi della linguetta Budget EME (banda e istante compresi)."));
            nota.ForeColor = Tema.Muted;
            root.Controls.Add(nota, 0, 0);

            // barra della formula, come in Excel
            TableLayoutPanel fb = new TableLayoutPanel();
            fb.AutoSize = true;
            fb.Dock = DockStyle.Fill;
            fb.ColumnCount = 3;
            fb.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
            fb.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
            fb.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100f));
            xlsNome = new TextBox();
            xlsNome.ReadOnly = true;
            xlsNome.Width = S(80);
            xlsNome.TextAlign = HorizontalAlignment.Center;
            Label fx = new Label();
            fx.Text = "fx";
            fx.AutoSize = true;
            fx.Font = new Font("Times New Roman", 11F, FontStyle.Italic);
            fx.Margin = new Padding(S(10), S(4), S(10), S(3));
            xlsFx = new TextBox();
            xlsFx.ReadOnly = true;
            xlsFx.Dock = DockStyle.Fill;
            fb.Controls.Add(xlsNome, 0, 0); fb.Controls.Add(fx, 1, 0); fb.Controls.Add(xlsFx, 2, 0);
            root.Controls.Add(fb, 0, 1);

            xls = new DataGridView();
            xls.Dock = DockStyle.Fill;
            xls.AllowUserToAddRows = false;
            xls.AllowUserToDeleteRows = false;
            xls.AllowUserToResizeRows = false;
            xls.AllowUserToOrderColumns = false;
            xls.EnableHeadersVisualStyles = false;
            xls.BackgroundColor = Color.White;
            xls.GridColor = Color.FromArgb(212, 212, 212);
            xls.BorderStyle = BorderStyle.FixedSingle;
            xls.CellBorderStyle = DataGridViewCellBorderStyle.Single;
            xls.SelectionMode = DataGridViewSelectionMode.CellSelect;
            xls.MultiSelect = false;
            xls.RowHeadersVisible = true;
            xls.RowHeadersWidth = S(46);
            xls.RowHeadersWidthSizeMode = DataGridViewRowHeadersWidthSizeMode.DisableResizing;
            xls.ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.DisableResizing;
            xls.ColumnHeadersHeight = S(22);
            xls.RowTemplate.Height = S(22);
            xls.EditMode = DataGridViewEditMode.EditOnKeystrokeOrF2;
            Font fc = new Font("Calibri", 11F);
            xls.DefaultCellStyle.Font = fc;
            xls.DefaultCellStyle.BackColor = Color.White;
            xls.DefaultCellStyle.ForeColor = Color.Black;
            xls.DefaultCellStyle.SelectionBackColor = Color.FromArgb(217, 234, 211);
            xls.DefaultCellStyle.SelectionForeColor = Color.Black;
            foreach (DataGridViewCellStyle hs in new DataGridViewCellStyle[] { xls.ColumnHeadersDefaultCellStyle, xls.RowHeadersDefaultCellStyle })
            {
                hs.BackColor = Color.FromArgb(230, 230, 230);
                hs.ForeColor = Color.FromArgb(68, 68, 68);
                hs.Font = new Font("Calibri", 10F);
                hs.Alignment = DataGridViewContentAlignment.MiddleCenter;
                hs.SelectionBackColor = Color.FromArgb(210, 210, 210);
                hs.SelectionForeColor = Color.FromArgb(33, 115, 70);
            }
            string[] lettere = { "A", "B", "C", "D", "E", "F", "G", "H" };
            int[] larghezze = { 420, 300, 300, 80, 80, 80, 80, 80 };
            for (int i = 0; i < lettere.Length; i++)
            {
                DataGridViewTextBoxColumn c = new DataGridViewTextBoxColumn();
                c.HeaderText = lettere[i];
                c.Width = S(larghezze[i]);
                c.SortMode = DataGridViewColumnSortMode.NotSortable;
                xls.Columns.Add(c);
            }
            xls.CellEnter += (s, e) => AggiornaFx();
            xls.CellEndEdit += (s, e) =>
            {
                if (xlsRiempimento) return;
                int r = e.RowIndex, c = e.ColumnIndex;
                object v = xls.Rows[r].Cells[c].Value;
                string t = v == null ? "" : v.ToString().Trim().Replace(',', '.');
                this.BeginInvoke((MethodInvoker)delegate { ApplicaValoreExcel(r, c, t); });
            };
            root.Controls.Add(xls, 0, 2);

            Label foglio = new Label();
            foglio.Text = "  " + Lang.T("Budget EME") + "  ";
            foglio.AutoSize = true;
            foglio.BackColor = Color.White;
            foglio.ForeColor = Color.FromArgb(33, 115, 70);
            foglio.Font = new Font("Calibri", 10.5F, FontStyle.Bold | FontStyle.Underline);
            foglio.BorderStyle = BorderStyle.FixedSingle;
            foglio.Padding = new Padding(S(6), S(3), S(6), S(3));
            foglio.Margin = new Padding(S(30), 0, S(3), S(3));
            root.Controls.Add(foglio, 0, 3);
            tp.Controls.Add(root);
        }

        void AggiornaFx()
        {
            if (xls == null || xls.CurrentCell == null) return;
            DataGridViewCell c = xls.CurrentCell;
            xlsNome.Text = xls.Columns[c.ColumnIndex].HeaderText + (c.RowIndex + 1).ToString(inv);
            xlsFx.Text = c.Value == null ? "" : c.Value.ToString();
        }

        // Colori del foglio: sempre su fondo bianco come in Excel, testi colorati come nella linguetta Budget EME
        static Color XlsTesto(Color c)
        {
            if (!Tema.Scuro) return c;
            if (c == Tema.OkFg) return Color.DarkGreen;
            if (c == Tema.BadFg) return Color.Firebrick;
            if (c == Tema.Accent) return Color.DarkBlue;
            if (c == Tema.FieldFore || c == Tema.Fore) return Color.Black;
            return c;
        }

        static Color XlsFondo(Color c)
        {
            if (c == Tema.Section) return Color.FromArgb(230, 232, 240);
            if (c == Tema.SnBg) return Color.FromArgb(235, 245, 255);
            if (c == Tema.MarginBg) return Color.FromArgb(245, 245, 225);
            return Color.White;
        }

        static readonly Color XlsVerde = Color.FromArgb(198, 239, 206);

        int AggiungiRigaXls(string a, string b, string c, bool grassetto, Color fondo, Color testoB, Color testoC)
        {
            int i = xls.Rows.Add();
            DataGridViewRow r = xls.Rows[i];
            r.HeaderCell.Value = (i + 1).ToString(inv);
            r.Cells[0].Value = a; r.Cells[1].Value = b; r.Cells[2].Value = c;
            foreach (DataGridViewCell cell in r.Cells)
            {
                cell.ReadOnly = true;
                cell.Style.BackColor = fondo;
                if (grassetto) cell.Style.Font = new Font("Calibri", 11F, FontStyle.Bold);
            }
            r.Cells[1].Style.ForeColor = testoB;
            r.Cells[2].Style.ForeColor = testoC;
            return i;
        }

        static string ValXls(NumericUpDown n, CultureInfo c)
        {
            return ((double)n.Value).ToString(n.DecimalPlaces > 0 ? "0.0#" : "0", c);
        }

        void RiempiExcel()
        {
            if (xls == null || lvX == null || bMe == null) return;
            xlsRiempimento = true;
            try
            {
                int cr = xls.CurrentCell != null ? xls.CurrentCell.RowIndex : -1;
                int cc = xls.CurrentCell != null ? xls.CurrentCell.ColumnIndex : -1;
                FillBudget(lvX, false);
                xls.Rows.Clear();
                Color nero = Color.Black, grigio = Color.FromArgb(242, 242, 242);
                AggiungiRigaXls(Lang.T("Budget EME") + "  (" + Lang.T("Export in Excel dei calcoli") + ")", NomeBanda(curBand),
                    FmtDT(DateTime.SpecifyKind(dtpB.Value, DateTimeKind.Utc)) + " UTC", true, Color.White, Color.DarkBlue, Color.DarkBlue);
                AggiungiRigaXls("", "", "", false, Color.White, nero, nero);
                AggiungiRigaXls(Lang.T("Parametro"), Lang.T("La mia stazione"), Lang.T("Stazione DX"), true, grigio, nero, nero);
                xlsPrimaParam = xls.Rows.Count;
                foreach (XlsPar p in xlsParam)
                {
                    string vm = p.CMe != null ? (p.CMe.Checked ? "1" : "0") : ValXls(p.Me, ci);
                    string vd = p.CDx != null ? (p.CDx.Checked ? "1" : "0") : ValXls(p.Dx, ci);
                    int i = AggiungiRigaXls(p.Nome, vm, vd, false, Color.White, nero, nero);
                    for (int k = 1; k <= 2; k++)
                    {
                        DataGridViewCell cell = xls.Rows[i].Cells[k];
                        bool attiva = p.CMe != null || (k == 1 ? p.Me : p.Dx).Enabled;
                        cell.ReadOnly = !attiva;
                        cell.Style.BackColor = attiva ? XlsVerde : Color.FromArgb(235, 235, 235);
                        cell.Style.Alignment = DataGridViewContentAlignment.MiddleRight;
                    }
                }
                xlsBwRow = AggiungiRigaXls(Lang.T("Banda passante (Hz)"), cmbBw.Text, "", false, Color.White, nero, nero);
                xls.Rows[xlsBwRow].Cells[1].ReadOnly = false;
                xls.Rows[xlsBwRow].Cells[1].Style.BackColor = XlsVerde;
                xls.Rows[xlsBwRow].Cells[1].Style.Alignment = DataGridViewContentAlignment.MiddleRight;
                AggiungiRigaXls("", "", "", false, Color.White, nero, nero);
                AggiungiRigaXls(Lang.T("Grandezza"), Lang.T("Io trasmetto → il DX riceve"), Lang.T("Il DX trasmette → io ricevo"), true, grigio, nero, nero);
                foreach (ListViewItem it in lvX.Items)
                {
                    string b = it.SubItems.Count > 1 ? it.SubItems[1].Text : "";
                    string c = it.SubItems.Count > 2 ? it.SubItems[2].Text : "";
                    Color tb = it.SubItems.Count > 1 ? XlsTesto(it.SubItems[1].ForeColor) : nero;
                    Color tc = it.SubItems.Count > 2 ? XlsTesto(it.SubItems[2].ForeColor) : nero;
                    bool g = it.Font != null && it.Font.Bold;
                    AggiungiRigaXls(it.Text, b, c, g, XlsFondo(it.BackColor), tb, tc);
                }
                if (cr >= 0 && cr < xls.Rows.Count && cc >= 0) xls.CurrentCell = xls.Rows[cr].Cells[cc];
            }
            finally { xlsRiempimento = false; }
            AggiornaFx();
        }

        void ApplicaValoreExcel(int r, int c, string t)
        {
            double d;
            bool ok = double.TryParse(t, NumberStyles.Float, inv, out d);
            int k = r - xlsPrimaParam;
            if (ok && xlsPrimaParam >= 0 && k >= 0 && k < xlsParam.Count && (c == 1 || c == 2))
            {
                XlsPar p = xlsParam[k];
                if (p.CMe != null) (c == 1 ? p.CMe : p.CDx).Checked = d >= 0.5;
                else
                {
                    NumericUpDown n = c == 1 ? p.Me : p.Dx;
                    decimal dv = (decimal)d;
                    if (dv < n.Minimum) dv = n.Minimum;
                    if (dv > n.Maximum) dv = n.Maximum;
                    n.Value = dv;
                }
            }
            else if (ok && r == xlsBwRow && c == 1)
            {
                int hzv = (int)(Math.Round(d / 50.0) * 50.0);
                if (hzv < 50) hzv = 50;
                if (hzv > 3000) hzv = 3000;
                cmbBw.SelectedItem = hzv.ToString(inv);
            }
            RiempiExcel();
        }

