            dx_.Controls.Add(pnlCaviGrafico, 0, 0);
            pnlCaviCalc = new PannelloDisegno(); pnlCaviCalc.Dock = DockStyle.Fill; pnlCaviCalc.Paint += DisegnaCalcCavi;
            pnlCaviCalc.Tag = "carta";
