            cmbCaviCalcBanda.SelectedIndex = ib;
            cmbCaviCalcBanda.SelectedIndexChanged += (s, e) => pnlCaviCalc.Invalidate();
            Pillola bUsa = new Pillola(Lang.T("usa nel Budget EME") + " →", StilePillola.Bordo, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 8.5F * fontFactor));
            tip.SetToolTip(bUsa, Lang.T("Mette il primo cavo spuntato, con questa lunghezza, come cavo di discesa della tua stazione nel Budget EME."));
            bUsa.Click += (s, e) =>
            {
                foreach (Cavo c in caviMostrati)
                    if (caviSpuntati.Contains(c))
                    {
                        int i = CaviDb.Elenco.IndexOf(c);
                        if (i >= 0) { bMe.CavoDis.SelectedIndex = i; bMe.LenDis.Value = nudCaviLen.Value; impSel = 0; MostraSchema(); tabs.SelectedTab = tpBudget; }
                        break;
                    }
            };
            Label lLen = L(Lang.T("Lunghezza")), lBan = L(Lang.T("Banda"));
            foreach (Control c in new Control[] { lLen, nudCaviLen, lBan, cmbCaviCalcBanda, bUsa }) pnlCaviCalc.Controls.Add(c);
            pnlCaviCalc.Layout += (s, e) =>
            {
