                int y = pnlCaviCalc.Height - S(14) - nudCaviLen.Height, x = S(18);
                foreach (Control c in new Control[] { lLen, nudCaviLen, lBan, cmbCaviCalcBanda, bUsa })
                {
                    c.Location = new Point(x, y + (nudCaviLen.Height - c.Height) / 2);
                    x += c.Width + (c is Label ? S(2) : S(12));
                }
            };
            dx_.Controls.Add(pnlCaviCalc, 0, 1);
            pnlCaviCome = new PannelloDisegno(); pnlCaviCome.Dock = DockStyle.Fill; pnlCaviCome.Paint += DisegnaComeCavi;
            dx_.Controls.Add(pnlCaviCome, 0, 2);
            root.Controls.Add(dx_, 1, 1);
            tp.Controls.Add(root);
            RiempiCavi();
