        void ScegliFiltroCavi(int k)
        {
            cmbCaviTipo.SelectedIndex = k;
            for (int i = 0; i < caviFiltri.Count; i++)
            {
                caviFiltri[i].Stile = i == k ? StilePillola.Pieno : StilePillola.Bordo;
                caviFiltri[i].Colore = i == k ? Color.FromArgb(31, 111, 209) : Color.FromArgb(75, 85, 99);
                caviFiltri[i].Invalidate();
            }
            RiempiCavi();
        }

        void RiempiCavi()
        {
            if (pnlCavi == null) return;
            string q = txtCercaCavi.Text.Trim();
            int ti = cmbCaviTipo.SelectedIndex, di = cmbCaviDiam.SelectedIndex;
            caviMostrati.Clear();
            List<Cavo> l = new List<Cavo>(CaviDb.Elenco);
            int ord = cmbCaviOrd == null ? 0 : cmbCaviOrd.SelectedIndex;
            int bo = Math.Max(0, Math.Min(CaviDb.Fb.Length - 1, cmbCaviBanda.SelectedIndex));
            // a parità, l'ordine per diametro (Sort non è stabile)
            l.Sort((a, b) =>
            {
                int c0 = ord == 1 ? a.Db[bo].CompareTo(b.Db[bo]) : (ord == 2 ? b.Db[bo].CompareTo(a.Db[bo]) : 0);
                return c0 != 0 ? c0 : a.Diam.CompareTo(b.Diam);
            });
            if (lblNotaCavi != null)
                lblNotaCavi.Text = ord == 0 ? Lang.T("attenuazione in dB/100 m a 20 °C · ordinati per diametro")
                    : Lang.T("attenuazione in dB/100 m a 20 °C") + " · " + string.Format(ord == 1 ? Lang.T("ordinati per perdita crescente a {0} MHz") : Lang.T("ordinati per perdita decrescente a {0} MHz"), CaviDb.Fb[bo].ToString(inv));
            foreach (Cavo c in l)
            {
                if (ti == 1 && c.Tipo != "flessibile") continue;
                if (ti == 2 && c.Tipo != "superflessibile") continue;
                if (ti == 3 && c.Tipo != "semirigido") continue;
                if (ti == 4 && !c.Personale) continue;
                if (di == 1 && c.Diam > 7) continue;
                if (di == 2 && (c.Diam <= 7 || c.Diam > 11)) continue;
                if (di == 3 && (c.Diam <= 11 || c.Diam > 16)) continue;
                if (di == 4 && c.Diam <= 16) continue;
                if (q.Length > 0)
                {
                    string tutto = string.Join(" ", c.Nomi) + " " + string.Join(" ", c.Costruttori) + " " + c.Anche + (c.Marino ? " " + Lang.T("ambienti marini") + " SeaTex" : "");
                    if (tutto.IndexOf(q, StringComparison.CurrentCultureIgnoreCase) < 0) continue;
                }
                caviMostrati.Add(c);
            }
            if (caviFiltri.Count > 4)
            {
                caviFiltri[0].Text = Lang.T("Tutti") + " · " + CaviDb.Elenco.Count.ToString(ci);
                caviFiltri[4].Visible = CaviDb.Elenco.Exists(x => x.Personale);
            }
            caviTipRiga = -1;
            DimensionaCavi();
            pnlCaviGrafico.Invalidate(); pnlCaviCalc.Invalidate();
        }

        // bordi delle colonne: cavo, costruttore, tipo, Ø mm e le cinque bande
        float[] ColonneCavi(float w)
        {
            float x0 = S(8), wt = w - S(16);
            float[] p = { 0.31f, 0.20f, 0.11f, 0.06f };
            float[] c = new float[10];
            c[0] = x0;
            for (int i = 0; i < 4; i++) c[i + 1] = c[i] + wt * p[i];
            float wb = (x0 + wt - c[4]) / 5f;
            for (int i = 0; i < 5; i++) c[5 + i] = c[4] + wb * (i + 1);
            return c;
        }

        float AltezzaRigaCavo(Graphics g, Cavo c, float wNome, float wCostr, Font fr, Font fs)
        {
            float h = S(24);
            float hn = fr.Height;
            for (int i = 1; i < c.Nomi.Length; i++) hn += fs.Height;
            if (c.Anche.Length > 0) hn += g.MeasureString(Lang.T("anche:") + " " + c.Anche, fs, (int)Math.Max(10, wNome - S(30))).Height + S(4);
            float hc = g.MeasureString(string.Join(" · ", c.Costruttori), fs, (int)Math.Max(10, wCostr - S(8))).Height;
            return Math.Max(h, Math.Max(hn, hc) + S(10));
        }

        void DimensionaCavi()
        {
            if (pnlCavi == null || pnlCaviHost == null) return;
            int w = pnlCaviHost.ClientSize.Width;
            caviRighe.Clear();
            float y = 0;
            using (Graphics g = pnlCavi.CreateGraphics())
            using (Font fr = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(11), false))
            {
                float[] cx = ColonneCavi(w - SystemInformation.VerticalScrollBarWidth);
                foreach (Cavo c in caviMostrati)
                {
                    float h = AltezzaRigaCavo(g, c, cx[1] - cx[0], cx[2] - cx[1], fr, fs);
                    caviRighe.Add(new RectangleF(0, y, w, h));
                    y += h;
                }
            }
            int H = (int)y + S(4);
            if (H <= pnlCaviHost.ClientSize.Height) H = pnlCaviHost.ClientSize.Height;
            else w -= SystemInformation.VerticalScrollBarWidth;
            Size sz = new Size(Math.Max(S(300), w), H);
            if (pnlCavi.Size != sz) pnlCavi.Size = sz;
            pnlCavi.Invalidate();
            if (pnlCaviTesta != null) pnlCaviTesta.Invalidate();
        }

        int RigaCavoA(Point p)
        {
            for (int i = 0; i < caviRighe.Count && i < caviMostrati.Count; i++) if (caviRighe[i].Contains(p)) return i;
            return -1;
        }

        // colore della cella: dal verde (poca perdita) al rosso (molta)
        static Color ColoreAttenuazione(double v)
        {
            double q = Math.Max(0, Math.Min(1, Math.Log10(Math.Max(0.5, v) / 1.0) / Math.Log10(40.0)));
            return Color.FromArgb((int)(225 + 25 * q), (int)(245 - 75 * q), (int)(220 - 60 * q));
        }

        void DisegnaTestaCavi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            Rectangle cr = pnlCaviTesta.ClientRectangle;
            using (Brush b = new SolidBrush(Tema.Scuro ? Tema.Section : Color.FromArgb(234, 239, 247))) g.FillRectangle(b, cr);
            float[] cx = ColonneCavi(pnlCavi != null ? pnlCavi.Width : cr.Width);
            string[] tit = { Lang.T("Cavo e nomi equivalenti"), Lang.T("Costruttore"), Lang.T("Tipo"), "Ø mm" };
            int sel = cmbCaviBanda == null ? -1 : cmbCaviBanda.SelectedIndex;
            using (Font fh = FontPx(Lang.FontUi, S(11), true))
            {
                for (int i = 0; i < 9; i++)
                {
                    RectangleF r = new RectangleF(cx[i], 0, cx[i + 1] - cx[i], cr.Height);
                    bool banda = i >= 4 && i - 4 == sel;
                    if (banda) using (Brush bb = new SolidBrush(Color.FromArgb(31, 111, 209))) g.FillRectangle(bb, r);
                    string t = i < 4 ? tit[i].ToUpper(Lang.Cultura) : CaviDb.Fb[i - 4].ToString(inv);
                    int ordH = cmbCaviOrd == null ? 0 : cmbCaviOrd.SelectedIndex;
                    if (banda && ordH > 0) t += ordH == 1 ? " ▲" : " ▼";
                    Color ct = banda ? Color.White : (Tema.Scuro ? Tema.Fore : Color.FromArgb(25, 45, 80));
                    float pad = S(6);
                    Testo(g, t, fh, ct, new RectangleF(r.Left + (i == 0 ? S(26) : pad), r.Top, Math.Max(1, r.Width - 2 * pad - (i == 0 ? S(20) : 0)), r.Height),
                        i >= 3 ? (i == 3 ? StringAlignment.Far : StringAlignment.Center) : StringAlignment.Near, StringAlignment.Center);
                }
            }
        }

        void DisegnaTabellaCavi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Carta);
            float[] cx = ColonneCavi(pnlCavi.Width);
            int sel = cmbCaviBanda.SelectedIndex;
            Color blu = Color.FromArgb(31, 111, 209), linea = Tema.Scuro ? Tema.Linea : Color.FromArgb(232, 236, 242);
            using (Font fr = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(11), false))
            using (Font fv = FontPx(FamigliaNumeri, S(13), false))
            using (Font fe = FontPx(Lang.FontUi, S(8), false))
            using (Font ftg = FontPx(Lang.FontUi, S(9.5f), false))
            using (Pen pl = new Pen(linea))
            using (StringFormat tg = (StringFormat)StringFormat.GenericTypographic.Clone())
            {
                tg.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
                for (int i = 0; i < caviMostrati.Count && i < caviRighe.Count; i++)
                {
                    Cavo c = caviMostrati[i];
                    RectangleF rr = caviRighe[i];
                    if (rr.Bottom < e.ClipRectangle.Top || rr.Top > e.ClipRectangle.Bottom) continue;
                    bool sp = caviSpuntati.Contains(c);
                    if (sp) using (Brush bs = new SolidBrush(Tema.Scuro ? Tema.Section : Color.FromArgb(244, 248, 255))) g.FillRectangle(bs, rr.Left, rr.Top, cx[4] - rr.Left, rr.Height);
                    // celle delle bande colorate e colonna della banda evidenziata
                    for (int k = 0; k < 5; k++)
                    {
                        RectangleF cc = new RectangleF(cx[4 + k] + 1, rr.Top, cx[5 + k] - cx[4 + k] - 2, rr.Height);
                        using (Brush bc = new SolidBrush(ColoreAttenuazione(c.Db[k]))) g.FillRectangle(bc, cc);
                        string v = c.Db[k].ToString("0.0", ci);
                        string apice = c.Segno[k] == 'i' ? "≈" : (c.Segno[k] == 'e' ? "e" : "");
                        float wv = g.MeasureString(v, fv, PointF.Empty, tg).Width;
                        float xv = cc.Left + (cc.Width - wv) / 2f, yv = rr.Top + S(6);
                        using (Brush bt = new SolidBrush(Color.FromArgb(29, 36, 51))) g.DrawString(v, fv, bt, xv, yv, tg);
                        if (apice.Length > 0) using (Brush ba = new SolidBrush(Color.FromArgb(120, 126, 136))) g.DrawString(apice, fe, ba, xv + wv + S(1), yv - S(2), tg);
                        if (k == sel)
                            using (Pen pb = new Pen(blu, S(2)))
                            {
                                g.DrawLine(pb, cc.Left, rr.Top, cc.Left, rr.Bottom);
                                g.DrawLine(pb, cc.Right, rr.Top, cc.Right, rr.Bottom);
                                if (i == caviMostrati.Count - 1) g.DrawLine(pb, cc.Left, rr.Bottom - S(1), cc.Right, rr.Bottom - S(1));
                            }
                    }
                    // casella colorata come la curva del grafico
                    RectangleF cb = new RectangleF(cx[0] + S(6), rr.Top + S(7), S(14), S(14));
                    using (GraphicsPath p = Arrotondato(cb, S(3)))
                    {
                        if (sp)
                        {
                            using (Brush b = new SolidBrush(ColoreCavo(c))) g.FillPath(b, p);
                            using (Pen pv = new Pen(Color.White, S(1.8f)))
                                g.DrawLines(pv, new PointF[] { new PointF(cb.Left + S(3), cb.Top + S(7)), new PointF(cb.Left + S(6), cb.Top + S(10)), new PointF(cb.Left + S(11), cb.Top + S(4)) });
                        }
                        else
                        {
                            using (Brush b = new SolidBrush(Tema.Field)) g.FillPath(b, p);
                            using (Pen pg = new Pen(Color.FromArgb(160, 166, 176))) g.DrawPath(pg, p);
                        }
                    }
                    // nome, nomi equivalenti a capo e "anche:"
                    float xn = cx[0] + S(28), wn = cx[1] - xn - S(6), yn = rr.Top + S(5);
                    float wnome = g.MeasureString(c.NomeVisto, fr, PointF.Empty, tg).Width;
                    using (Brush bn = new SolidBrush(Tema.Fore)) g.DrawString(c.NomeVisto, fr, bn, new RectangleF(xn, yn, wn, fr.Height + S(2)), tg);
                    float yl = yn + fr.Height;
                    using (Brush bq = new SolidBrush(Tema.Muted))
                        for (int k = 1; k < c.Nomi.Length; k++) { g.DrawString("≡ " + c.Nomi[k], fs, bq, new RectangleF(xn, yl, wn, fs.Height + S(2)), tg); yl += fs.Height; }
                    if (c.Anche.Length > 0)
                    {
                        string an = Lang.T("anche:") + " " + c.Anche;
                        SizeF sa = g.MeasureString(an, fs, (int)Math.Max(10, wn - S(8)));
                        RectangleF ra;
                        if (c.Nomi.Length == 1 && wnome + S(10) + sa.Width + S(8) <= wn && sa.Height < fs.Height * 1.5f)
                            ra = new RectangleF(xn + wnome + S(8), yn + (fr.Height - sa.Height) / 2f - S(1), sa.Width + S(8), sa.Height + S(2));   // sulla stessa riga del nome
                        else
                            ra = new RectangleF(xn, yl + S(2), Math.Min(wn, sa.Width + S(10)), sa.Height + S(2));
                        using (GraphicsPath p = Arrotondato(ra, S(3)))
                        using (Brush b = new SolidBrush(Color.FromArgb(255, 243, 205))) g.FillPath(b, p);
                        using (Brush bt = new SolidBrush(Color.FromArgb(150, 95, 0))) g.DrawString(an, fs, bt, new RectangleF(ra.Left + S(4), ra.Top + S(1), ra.Width - S(6), ra.Height));
                    }
                    // costruttore, tipo a pastiglia, diametro
                    using (Brush bm = new SolidBrush(Tema.Muted))
                        g.DrawString(string.Join(" · ", c.Costruttori), fs, bm, new RectangleF(cx[1] + S(6), rr.Top + S(6), cx[2] - cx[1] - S(8), rr.Height - S(8)));
                    string tt = TipoCavo(c.Tipo);
                    Color tf = c.Tipo == "semirigido" ? Color.FromArgb(91, 63, 168) : (c.Tipo == "superflessibile" ? blu : (c.Tipo == "flessibile" ? Color.FromArgb(23, 128, 61) : Color.FromArgb(150, 95, 0)));
                    Color tb = c.Tipo == "semirigido" ? Color.FromArgb(237, 232, 250) : (c.Tipo == "superflessibile" ? Color.FromArgb(227, 238, 252) : (c.Tipo == "flessibile" ? Color.FromArgb(222, 244, 229) : Color.FromArgb(255, 243, 205)));
                    SizeF st = g.MeasureString(tt, ftg);
                    RectangleF rt = new RectangleF(cx[2] + S(6), rr.Top + S(7), Math.Min(cx[3] - cx[2] - S(8), st.Width + S(10)), st.Height + S(1));
                    using (GraphicsPath p = Arrotondato(rt, rt.Height / 2f))
                    using (Brush b = new SolidBrush(tb)) g.FillPath(b, p);
                    Testo(g, tt, ftg, tf, rt, StringAlignment.Center, StringAlignment.Center);
                    using (Brush bd = new SolidBrush(Tema.Fore))
                    using (StringFormat sr = new StringFormat())
                    {
                        sr.Alignment = StringAlignment.Far;
                        g.DrawString(c.Diam.ToString("0.0", ci), fv, bd, new RectangleF(cx[3], rr.Top + S(6), cx[4] - cx[3] - S(8), fv.Height + S(2)), sr);
                    }
                    g.DrawLine(pl, rr.Left, rr.Bottom - 1, cx[4], rr.Bottom - 1);
                }
                if (caviMostrati.Count == 0)
                    Testo(g, Lang.T("Nessun cavo corrisponde alla ricerca."), fs, Tema.Muted, new RectangleF(S(20), S(20), pnlCavi.Width - S(40), S(30)), StringAlignment.Near, StringAlignment.Near);
            }
        }

        // Confronto dei cavi spuntati (dB/100 m, scala logaritmica da 1 a 20, allargata se serve)
        void DisegnaGraficoCavi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlCaviGrafico.ClientRectangle;
            RectangleF card = new RectangleF(S(4), S(4), cr.Width - S(12), cr.Height - S(10));
            Scheda(g, card, Color.Empty);
            int nSel = 0;
            double vmin = 1, vmax = 20;
            foreach (Cavo c in caviMostrati)
                if (caviSpuntati.Contains(c))
                {
                    nSel++;
                    for (int i = 0; i < 5; i++) { vmin = Math.Min(vmin, c.Db[i]); vmax = Math.Max(vmax, c.Db[i]); }
                }
            if (vmin < 1) vmin = 0.5;
            if (vmax > 20) vmax = 50;
            using (Font fh = FontPx(Lang.FontUi, S(13), true))
            using (Font fn = FontPx(Lang.FontUi, S(11.5f), false))
            {
                Testo(g, Lang.T("CONFRONTO DEI CAVI SPUNTATI"), fh, Color.FromArgb(25, 65, 127), new RectangleF(card.Left + S(14), card.Top + S(10), card.Width * 0.7f, S(20)), StringAlignment.Near, StringAlignment.Center);
                Testo(g, string.Format(ci, Lang.T("{0} selezionati"), nSel), fn, Tema.Muted, new RectangleF(card.Left, card.Top + S(10), card.Width - S(14), S(20)), StringAlignment.Far, StringAlignment.Center);
            }
            RectangleF a = new RectangleF(card.Left + S(62), card.Top + S(44), card.Width - S(84), card.Height - S(86));
            if (a.Width < 50 || a.Height < 40) return;
            double l0 = Math.Log10(40), l1 = Math.Log10(500), y0 = Math.Log10(vmin), y1 = Math.Log10(vmax);
            Func<double, float> X = f => a.Left + (float)((Math.Log10(f) - l0) / (l1 - l0) * a.Width);
            Func<double, float> Y = v => a.Bottom - (float)((Math.Log10(Math.Max(vmin, Math.Min(vmax, v))) - y0) / (y1 - y0) * a.Height);
            using (Font ft = FontPx(Lang.FontUi, S(11), false))
            using (Pen pg = new Pen(Tema.Linea))
            using (Brush bt = new SolidBrush(Tema.Muted))
            using (StringFormat sc = new StringFormat())
            {
                sc.Alignment = StringAlignment.Center;
                using (Brush bb = new SolidBrush(Tema.Field)) g.FillRectangle(bb, a);
                foreach (double f in CaviDb.Fb) { g.DrawLine(pg, X(f), a.Top, X(f), a.Bottom); g.DrawString(f.ToString(inv), ft, bt, X(f), a.Bottom + S(4), sc); }
                foreach (double v in new double[] { 0.5, 1, 2, 5, 10, 20, 50 })
                {
                    if (v < vmin - 1e-9 || v > vmax + 1e-9) continue;
                    g.DrawLine(pg, a.Left, Y(v), a.Right, Y(v));
                    g.DrawString(v.ToString("0.#", ci), ft, bt, new RectangleF(a.Left - S(34), Y(v) - S(8), S(28), S(16)), new StringFormat { Alignment = StringAlignment.Far });
                }
                g.DrawString("MHz", ft, bt, a.Left + a.Width / 2f, a.Bottom + S(20), sc);
                // titolo dell'asse verticale ruotato: non si sovrappone al titolo della scheda
                GraphicsState gs = g.Save();
                g.TranslateTransform(card.Left + S(16), a.Top + a.Height / 2f);
                g.RotateTransform(-90);
                g.DrawString("dB/100 m", ft, bt, 0, 0, sc);
                g.Restore(gs);
            }
            foreach (Cavo c in caviMostrati)
            {
                if (!caviSpuntati.Contains(c)) continue;
                Color col = ColoreCavo(c);
                PointF[] pts = new PointF[5];
                for (int i = 0; i < 5; i++) pts[i] = new PointF(X(CaviDb.Fb[i]), Y(c.Db[i]));
                using (Pen p = new Pen(col, S(2)))
                {
                    g.DrawLines(p, pts);
                    foreach (PointF q in pts) { g.FillEllipse(Brushes.White, q.X - S(4), q.Y - S(4), S(8), S(8)); g.DrawEllipse(p, q.X - S(4), q.Y - S(4), S(8), S(8)); }
                }
            }
        }

        // Perdita dei cavi spuntati sulla lunghezza scelta (i comandi stanno in fondo alla scheda)
        void DisegnaCalcCavi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlCaviCalc.ClientRectangle;
            RectangleF card = new RectangleF(S(4), S(4), cr.Width - S(12), cr.Height - S(8));
            Scheda(g, card, Color.Empty);
            double len = (double)nudCaviLen.Value, f = CaviDb.Fb[Math.Max(0, cmbCaviCalcBanda.SelectedIndex)];
            float fondo = nudCaviLen.Top - S(8);
            using (Font fh = FontPx(Lang.FontUi, S(13), true))
            using (Font fl = FontPx(Lang.FontUi, S(13), false))
            using (Font fv = FontPx(FamigliaNumeri, S(13), true))
            {
                Testo(g, Lang.T("PERDITA SULLA TUA LUNGHEZZA"), fh, Color.FromArgb(25, 65, 127), new RectangleF(card.Left + S(14), card.Top + S(10), card.Width * 0.6f, S(20)), StringAlignment.Near, StringAlignment.Center);
                Testo(g, string.Format(ci, "{0} m · {1} MHz", len, f), FontDx(fl), Tema.Muted, new RectangleF(card.Left, card.Top + S(10), card.Width - S(14), S(20)), StringAlignment.Far, StringAlignment.Center);
                float y = card.Top + S(38);
                int k = 0;
                double max = 0.1;
                foreach (Cavo c in caviMostrati) if (caviSpuntati.Contains(c)) max = Math.Max(max, c.Perdita(f, len));
                foreach (Cavo c in caviMostrati)
                {
                    if (!caviSpuntati.Contains(c)) continue;
                    if (y > fondo - S(20)) break;
                    Color col = ColoreCavo(c);
                    k++;
                    double p = c.Perdita(f, len);
                    using (Brush b = new SolidBrush(col)) g.FillEllipse(b, card.Left + S(14), y + S(4), S(11), S(11));
                    Testo(g, c.NomeVisto, fl, Tema.Fore, new RectangleF(card.Left + S(32), y, card.Width * 0.4f, S(20)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, p.ToString("F2", ci) + " dB", fv, Tema.Fore, new RectangleF(card.Left + card.Width * 0.42f, y, card.Width * 0.18f, S(20)), StringAlignment.Far, StringAlignment.Center);
                    RectangleF bar = new RectangleF(card.Left + card.Width * 0.63f, y + S(6), card.Width * 0.33f, S(8));
                    using (GraphicsPath pb = Arrotondato(bar, S(4))) using (Brush b = new SolidBrush(Tema.Scuro ? Tema.Section : Color.FromArgb(238, 240, 244))) g.FillPath(b, pb);
                    RectangleF piena = new RectangleF(bar.Left, bar.Top, Math.Max(S(4), (float)(bar.Width * p / max)), bar.Height);
                    using (GraphicsPath pb = Arrotondato(piena, S(4))) using (Brush b = new SolidBrush(col)) g.FillPath(b, pb);
                    y += S(24);
                }
                if (k == 0) Testo(g, Lang.T("Spunta uno o più cavi nella tabella."), fl, Tema.Muted, new RectangleF(card.Left + S(14), y, card.Width - S(20), S(40)), StringAlignment.Near, StringAlignment.Near);
            }
        }

        // "Come leggere la tabella" in una scheda compatta: la parte prima di "=" in grassetto
        void DisegnaComeCavi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlCaviCome.ClientRectangle;
            RectangleF card = new RectangleF(S(4), S(4), cr.Width - S(12), cr.Height - S(10));
            Scheda(g, card, Color.Empty);
            string[] righe = {
                Lang.T("Numero pieno = valore della scheda del costruttore a quella frequenza (entro il 2,5 %)."),
                Lang.T("≈ = interpolato tra due frequenze della scheda con la legge di potenza (retta sul grafico log-log)."),
                Lang.T("e = estrapolato oltre l'ultima frequenza della scheda: da usare con cautela."),
                Lang.T("≡ = cavi accorpati in una riga: stesso tipo, diametro uguale (±0,2 mm) e attenuazione entro 0,2 dB/100 m in tutte le bande; il valore è la media."),
                Lang.T("anche: = altre sigle commerciali equivalenti (per esempio LMR-400 = HF400, CNT-400)."),
                Lang.T("Le sigle cinesi (50-3, 50-5, 50-7, 50-9, 50-12…) indicano il diametro del dielettrico in mm: 50-7 ≈ classe RG-213/LMR-400, 50-9 ≈ 1/2\" superflessibile, 50-12 ≈ 1/2\" corrugato."),
                Lang.T("Le fonti di ogni cavo sono nel fumetto della sua riga e nel manuale, § 3.8.") };
            using (Font fh = FontPx(Lang.FontUi, S(13), true))
            using (Font fr = FontPx(Lang.FontUi, S(12), false))
            using (Font fb = FontPx(Lang.FontUi, S(12), true))
            {
                Testo(g, Lang.T("Come leggere la tabella").ToUpper(Lang.Cultura), fh, Color.FromArgb(25, 65, 127), new RectangleF(card.Left + S(14), card.Top + S(10), card.Width - S(24), S(20)), StringAlignment.Near, StringAlignment.Center);
                float y = card.Top + S(38), w = card.Width - S(28);
                for (int i = 0; i < righe.Length; i++)
                {
                    string t = righe[i];
                    int k = i < 5 ? t.IndexOf(" = ", StringComparison.Ordinal) : -1;
                    if (k > 0) t = "**" + t.Substring(0, k) + "**" + t.Substring(k);
                    if (y > card.Bottom - S(10)) break;
                    y += TestoRicco(g, t, fr, fb, Tema.Fore, card.Left + S(14), y, w, 1.3f, true) + S(3);
                }
            }
        }

        // Nuovo cavo personalizzato: nome, diametro e attenuazione nelle cinque bande
        void AggiungiCavo()
        {
            using (Form f = new Form())
            {
                f.Text = Lang.T("Aggiungi cavo personalizzato");
                f.FormBorderStyle = FormBorderStyle.FixedDialog;
                f.MaximizeBox = false; f.MinimizeBox = false; f.ShowInTaskbar = false;
                f.StartPosition = FormStartPosition.CenterParent;
                f.Font = this.Font; f.AutoSize = true; f.AutoSizeMode = AutoSizeMode.GrowAndShrink;
                TableLayoutPanel t = new TableLayoutPanel(); t.AutoSize = true; t.ColumnCount = 2; t.Padding = new Padding(S(12));
                TextBox nome = new TextBox(); nome.Width = S(220);
                NumericUpDown d = Nud(1, 100, 10, 1, 80);
                NumericUpDown[] v = new NumericUpDown[5];
                t.Controls.Add(L(Lang.T("Nome")), 0, 0); t.Controls.Add(nome, 1, 0);
                t.Controls.Add(L(Lang.T("Diametro (mm)")), 0, 1); t.Controls.Add(d, 1, 1);
                for (int i = 0; i < 5; i++)
                {
                    v[i] = Nud(0, 200, 5, 2, 80);
                    t.Controls.Add(L(string.Format(inv, "{0} MHz (dB/100 m)", CaviDb.Fb[i])), 0, 2 + i); t.Controls.Add(v[i], 1, 2 + i);
                }
                Button ok = new Button(); ok.Text = "OK"; ok.DialogResult = DialogResult.OK;
                Button an = new Button(); an.Text = Lang.T("Annulla"); an.DialogResult = DialogResult.Cancel;
                StileDialogo(f, t, ok, an);
                f.AcceptButton = ok; f.CancelButton = an;
                if (f.ShowDialog(this) != DialogResult.OK || nome.Text.Trim().Length == 0) return;
                Cavo c = new Cavo();
                c.Nomi = new string[] { nome.Text.Trim() };
                c.Costruttori = new string[] { Lang.T("personalizzato") };
                c.Tipo = "personale"; c.Anche = ""; c.Fonti = new string[] { Lang.T("inserito dall'utente") };
                c.Personale = true; c.Diam = (double)d.Value;
                for (int i = 0; i < 5; i++) { c.Db[i] = (double)v[i].Value; c.Segno[i] = 'm'; }
                CaviDb.Elenco.Add(c);
                CaviDb.SalvaPersonali();
                RicaricaTendineCavi();
                RiempiCavi();
            }
        }

        // ---------- Linguette "CONTATTI DELL'AUTORE E RINGRAZIAMENTI" e "LICENZA D'USO" ----------

        PannelloDisegno pnlContatti;
        readonly List<KeyValuePair<RectangleF, string>> contattiLink = new List<KeyValuePair<RectangleF, string>>();
        Image logoAri;

        void BuildContattiTab(TabPage tp)
        {
            pnlContatti = new PannelloDisegno();
            pnlContatti.Dock = DockStyle.Fill;
            pnlContatti.Paint += DisegnaContatti;
            pnlContatti.MouseMove += (s, e) =>
            {
                bool su = false;
                foreach (KeyValuePair<RectangleF, string> kv in contattiLink) if (kv.Key.Contains(e.Location)) su = true;
                pnlContatti.Cursor = su ? Cursors.Hand : Cursors.Default;
            };
            pnlContatti.MouseClick += (s, e) =>
            {
                foreach (KeyValuePair<RectangleF, string> kv in contattiLink)
                    if (kv.Key.Contains(e.Location))
                    {
                        if (kv.Value.StartsWith("copia:")) { try { Clipboard.SetText(kv.Value.Substring(6)); } catch { } }
                        else ApriLink(kv.Value);
                        break;
                    }
            };
            try { logoAri = SplashForm.LogoAri(); } catch { logoAri = null; }
            tp.Controls.Add(pnlContatti);
        }

