        void IconaQuadra(Graphics g, RectangleF ic, Color c, string s, Font f)
        {
            using (GraphicsPath p = Arrotondato(ic, S(8))) using (Brush b = new SolidBrush(c)) g.FillPath(b, p);
            // TextRenderer: i simboli ✉ e ♥ arrivano anche dai caratteri di riserva di Windows
            TextRenderer.DrawText(g, s, f, new Rectangle((int)ic.X, (int)ic.Y, (int)ic.Width, (int)ic.Height), Color.White,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
        }

        // maiuscoletto spaziato delle etichette delle schede
        static string Spaziato(string s)
        {
            foreach (char c in s) if (c >= '\u0530') return s.ToUpper();
            StringBuilder sb = new StringBuilder();
            foreach (char c in s.ToUpper()) { if (sb.Length > 0) sb.Append(' '); sb.Append(c); }
            return sb.ToString();
        }

        // Pagina della licenza disegnata come nel bozzetto approvato: sigillo e titolo, introduzione,
        // quattro schede dei principi, condizioni su due colonne, riquadro "In breve" e piede
        Panel pnlLicScroll;
        PannelloDisegno pnlLicenza;

        void BuildLicenzaTab(TabPage tp)
        {
            pnlLicScroll = new Panel();
            pnlLicScroll.Dock = DockStyle.Fill;
            pnlLicScroll.AutoScroll = true;
            pnlLicenza = new PannelloDisegno();
            pnlLicenza.Location = new Point(0, 0);
            pnlLicenza.Paint += (s, e) => { PreparaGrafica(e.Graphics); PaginaLicenza(e.Graphics, pnlLicenza.Width, true); };
            pnlLicScroll.Controls.Add(pnlLicenza);
            pnlLicScroll.Resize += (s, e) => DimensionaLicenza();
            tp.Controls.Add(pnlLicScroll);
            DimensionaLicenza();
        }

        void DimensionaLicenza()
        {
            if (pnlLicScroll == null || pnlLicenza == null) return;
            int w = Math.Max(S(600), pnlLicScroll.ClientSize.Width);
            float h;
            using (Graphics g = pnlLicenza.CreateGraphics()) { PreparaGrafica(g); h = PaginaLicenza(g, w, false); }
            int hh = Math.Max(pnlLicScroll.ClientSize.Height, (int)Math.Ceiling(h));
            if (pnlLicenza.Width != w || pnlLicenza.Height != hh) pnlLicenza.Size = new Size(w, hh);
            pnlLicenza.Invalidate();
        }

        // Testo con parti in grassetto (**...**) che va a capo parola per parola; restituisce l'altezza
        // Testo a capo automatico con parti in **grassetto**, allineato a sinistra.
        // L'interlinea è un multiplo della grandezza del carattere (come line-height nei bozzetti);
        // le parole consecutive con lo stesso carattere si disegnano insieme, così gli spazi restano regolari.
        float TestoRicco(Graphics g, string t, Font fr, Font fb, Color c, float x, float y, float w, float interlinea, bool disegna)
        {
            using (StringFormat sf = (StringFormat)StringFormat.GenericTypographic.Clone())
            using (Brush br = new SolidBrush(c))
            {
                sf.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
                List<KeyValuePair<string, bool>> par = new List<KeyValuePair<string, bool>>();
                bool gr = false;
                foreach (string pezzo in (t ?? "").Split(new string[] { "**" }, StringSplitOptions.None))
                {
                    foreach (string p in pezzo.Split(' '))
                        if (p.Length > 0) par.Add(new KeyValuePair<string, bool>(p, gr));
                    gr = !gr;
                }
                float em = fr.Unit == GraphicsUnit.Pixel ? fr.Size : fr.SizeInPoints * g.DpiY / 72f;
                float lh = em * interlinea;
                float sp = g.MeasureString(" ", fr, 1000, sf).Width;
                // righe: elenco di parole con il loro carattere
                List<List<KeyValuePair<string, bool>>> righe = new List<List<KeyValuePair<string, bool>>>();
                List<KeyValuePair<string, bool>> cur = new List<KeyValuePair<string, bool>>();
                float xx = 0;
                foreach (KeyValuePair<string, bool> p in par)
                {
                    float wp = g.MeasureString(p.Key, p.Value ? fb : fr, 10000, sf).Width;
                    if (cur.Count > 0 && xx + wp > w) { righe.Add(cur); cur = new List<KeyValuePair<string, bool>>(); xx = 0; }
                    cur.Add(p);
                    xx += wp + sp;
                }
                if (cur.Count > 0) righe.Add(cur);
                if (disegna)
                {
                    // spostamento verticale: la riga si centra nella sua interlinea
                    float dy = Math.Max(0, (lh - fr.GetHeight(g)) / 2f);
                    for (int r = 0; r < righe.Count; r++)
                    {
                        float xr = x, yr = y + r * lh + dy;
                        int i = 0;
                        while (i < righe[r].Count)
                        {
                            bool b = righe[r][i].Value;
                            StringBuilder run = new StringBuilder();
                            while (i < righe[r].Count && righe[r][i].Value == b)
                            {
                                if (run.Length > 0) run.Append(' ');
                                run.Append(righe[r][i].Key);
                                i++;
                            }
                            if (i < righe[r].Count) run.Append(' ');
                            Font f = b ? fb : fr;
                            string sr = run.ToString();
                            g.DrawString(sr, f, br, xr, yr, sf);
                            xr += g.MeasureString(sr, f, 10000, sf).Width;
                        }
                    }
                }
                return Math.Max(1, righe.Count) * lh;
            }
        }

        float PaginaLicenza(Graphics g, float W, bool disegna)
        {
            Color blu = Color.FromArgb(25, 65, 127);
            Color cTit = Tema.Scuro ? Tema.Fore : blu, cTesto = Tema.Scuro ? Tema.Fore : Color.FromArgb(29, 36, 51), cGrigio = Tema.Scuro ? Tema.Muted : Color.FromArgb(75, 85, 99);
            Color cScheda = Tema.Scuro ? Tema.Carta : Color.White, cBordo = Tema.Scuro ? Tema.Linea : Color.FromArgb(225, 231, 240);
            if (disegna)
            {
                RectangleF tutto = new RectangleF(0, 0, W, pnlLicenza.Height);
                Color a = Tema.Scuro ? Tema.Back : Color.FromArgb(247, 249, 252), b = Tema.Scuro ? Tema.Section : Color.FromArgb(234, 240, 248);
                using (LinearGradientBrush lb = new LinearGradientBrush(tutto, a, b, 70f)) g.FillRectangle(lb, tutto);
            }
            float mx = S(60), x = mx, y = S(30), wi = W - 2 * mx;
            using (Font fSeal = FontPx(Lang.FontUi, S(21), true))
            using (Font fSeal2 = FontPx(Lang.FontUi, S(10), true))
            using (Font fH1 = FontPx(Lang.FontUi, S(32), true))
            using (Font fSub = FontPx(Lang.FontUi, S(16), false))
            using (Font fIntro = FontPx(Lang.FontUi, S(16), false))
            using (Font fIntroB = FontPx(Lang.FontUi, S(16), true))
            using (Font fIc = FontPx(Lang.FontUi, S(19), true))
            using (Font fH3 = FontPx(Lang.FontUi, S(17), true))
            using (Font fP = FontPx(Lang.FontUi, S(14), false))
            using (Font fPB = FontPx(Lang.FontUi, S(14), true))
            using (Font fH2 = FontPx(Lang.FontUi, S(18), true))
            using (Font fFoot = FontPx(Lang.FontUi, S(13), false))
            {
                // sigillo, titolo e sottotitolo
                RectangleF seal = new RectangleF(x, y, S(84), S(84));
                if (disegna)
                {
                    using (Brush b = new SolidBrush(Color.FromArgb(55, blu))) g.FillEllipse(b, seal.X + S(2), seal.Y + S(4), seal.Width, seal.Height);
                    using (Brush b = new SolidBrush(blu)) g.FillEllipse(b, seal);
                    Testo(g, "YAEC", fSeal, Color.White, new RectangleF(seal.X, seal.Y + S(18), seal.Width, S(28)), StringAlignment.Center, StringAlignment.Center);
                    Testo(g, Lang.T("LICENZA"), fSeal2, Color.White, new RectangleF(seal.X, seal.Y + S(46), seal.Width, S(16)), StringAlignment.Center, StringAlignment.Center);
                    Testo(g, Lang.T("Licenza d'uso"), fH1, cTit, new RectangleF(x + S(106), y + S(10), wi - S(106), S(44)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, "YAEC – Yet Another EME Calc · " + Lang.T("a cura di Costantino IC8TEM"), fSub, cGrigio, new RectangleF(x + S(106), y + S(52), wi - S(106), S(24)), StringAlignment.Near, StringAlignment.Center);
                }
                y += S(84) + S(16);
                // introduzione
                string intro = Lang.T("YAEC è un programma libero, scritto da un radioamatore per i radioamatori. Il suo codice è stato sviluppato anche con l'aiuto di un assistente di intelligenza artificiale, e la licenza ne riprende il modo di lavorare: essere davvero utile, dire sempre come stanno le cose, mostrare il proprio ragionamento, non nuocere a nessuno e riconoscere il lavoro degli altri. Sotto ci sono i principi e poi le condizioni vere e proprie.");
                y += TestoRicco(g, intro, fIntro, fIntroB, cTesto, x, y, Math.Min(wi, S(1300)), 1.5f, disegna) + S(18);
                // quattro schede dei principi
                string[][] pr = {
                    new string[] { "✦", Lang.T("Utile e gratuito"), Lang.T("Il programma è gratuito e lo puoi usare senza limiti per la tua attività radioamatoriale, per studio e per insegnamento. Serve a far nascere QSO, non a vendere qualcosa.") },
                    new string[] { "◎", Lang.T("Trasparente"), Lang.T("Il sorgente è sempre consegnato insieme al programma; ogni formula è visibile nella linguetta DEBUG FORMULE e ogni dato riporta la sua fonte. Niente scatole nere.") },
                    new string[] { "≈", Lang.T("Onesto"), Lang.T("I valori misurati, quelli ricavati e quelli stimati sono distinti; ciò che non è verificato viene dichiarato come tale. Un risultato incerto è indicato come incerto, non presentato come certo.") },
                    new string[] { "✓", Lang.T("Rispettoso"), Lang.T("Rispetta il lavoro di chi ha misurato, scritto e pubblicato prima di noi, la privacy di chi lo usa (nessun dato raccolto, niente pubblicità) e le regole del servizio di radioamatore.") } };
                Color[] cpr = { Color.FromArgb(31, 111, 209), Color.FromArgb(23, 128, 61), Color.FromArgb(180, 83, 9), Color.FromArgb(91, 63, 168) };
                float gap = S(16), cw = (wi - 3 * gap) / 4f, pad = S(18);
                float hTesto = 0;
                for (int i = 0; i < 4; i++) hTesto = Math.Max(hTesto, TestoRicco(g, pr[i][2], fP, fPB, cTesto, 0, 0, cw - 2 * pad, 1.45f, false));
                float hCard = S(5) + S(16) + S(38) + S(8) + S(26) + hTesto + S(18);
                for (int i = 0; i < 4 && disegna; i++)
                {
                    RectangleF c = new RectangleF(x + i * (cw + gap), y, cw, hCard);
                    using (GraphicsPath p = Arrotondato(c, S(14)))
                    {
                        using (Brush b = new SolidBrush(Color.FromArgb(18, 30, 50, 90)))
                        using (GraphicsPath po = Arrotondato(new RectangleF(c.X, c.Y + S(2), c.Width, c.Height), S(14))) g.FillPath(b, po);
                        using (Brush b = new SolidBrush(cScheda)) g.FillPath(b, p);
                        Region old = g.Clip;
                        g.SetClip(p, CombineMode.Intersect);
                        using (Brush b = new SolidBrush(cpr[i])) g.FillRectangle(b, c.Left, c.Top, c.Width, S(5));
                        g.Clip = old;
                        using (Pen pn = new Pen(cBordo)) g.DrawPath(pn, p);
                    }
                    RectangleF ic = new RectangleF(c.Left + pad, c.Top + S(21), S(38), S(38));
                    using (GraphicsPath p = Arrotondato(ic, S(10))) using (Brush b = new SolidBrush(cpr[i])) g.FillPath(b, p);
                    Testo(g, pr[i][0], fIc, Color.White, ic, StringAlignment.Center, StringAlignment.Center);
                    TestoRicco(g, pr[i][1], fH3, fH3, cpr[i], c.Left + pad, ic.Bottom + S(6), c.Width - 2 * pad, 1.5f, true);   // allineato al testo sotto
                    TestoRicco(g, pr[i][2], fP, fPB, cTesto, c.Left + pad, ic.Bottom + S(36), c.Width - 2 * pad, 1.45f, true);
                }
                y += hCard + S(20);
                // condizioni su due colonne
                string[][] cond = {
                    new string[] { Lang.T("Uso."), Lang.T("Puoi usare, copiare e installare YAEC gratuitamente, su quanti computer vuoi.") },
                    new string[] { Lang.T("Modifiche."), Lang.T("Puoi studiare il sorgente, correggerlo e migliorarlo per uso personale o del tuo radio club.") },
                    new string[] { Lang.T("Ridistribuzione."), Lang.T("Puoi ridistribuire il programma, originale o modificato, solo insieme al suo sorgente completo e con questa stessa licenza.") },
                    new string[] { Lang.T("Dichiarare le modifiche."), Lang.T("Una versione modificata deve dirlo chiaramente nel titolo o nelle note di versione, indicando chi l'ha modificata e che cosa è cambiato, così nessuno scambia il tuo lavoro per quello dell'autore, o viceversa.") },
                    new string[] { Lang.T("Attribuzione."), Lang.T("Vanno mantenuti il nome dell'autore (Costantino IC8TEM), il capitolo «Fonti, dati e crediti» del manuale e tutte le citazioni delle fonti di terzi: dati, tabelle, articoli e misure appartengono a chi li ha prodotti.") },
                    new string[] { Lang.T("Niente uso commerciale."), Lang.T("Non è consentito vendere YAEC o versioni derivate, né includerlo in prodotti a pagamento, senza il permesso scritto dell'autore.") },
                    new string[] { Lang.T("Niente dati nascosti."), Lang.T("Nessuna versione distribuita può raccogliere dati degli utenti, mostrare pubblicità o inviare informazioni a terzi senza dirlo apertamente.") },
                    new string[] { Lang.T("Uso corretto della radio."), Lang.T("Il programma aiuta a pianificare: le frequenze, le potenze e le modalità usate restano sotto la responsabilità dell'operatore e della sua licenza di radioamatore.") },
                    new string[] { Lang.T("Nessuna garanzia."), Lang.T("YAEC è fornito così com'è. I calcoli sono fatti con cura e con fonti dichiarate, ma possono contenere errori: verifica i dati importanti prima di affidarti a essi.") },
                    new string[] { Lang.T("Segnalazioni."), Lang.T("Se trovi un errore o un dato migliore, scrivilo all'autore (linguetta CONTATTI DELL'AUTORE E RINGRAZIAMENTI): sarà corretto citandoti come fonte.") } };
                float padC = S(24), gapC = S(40), num = S(26);
                float colW = (wi - 2 * padC - gapC) / 2f, wTxt = colW - num;
                float[] hItem = new float[10];
                for (int i = 0; i < 10; i++) hItem[i] = TestoRicco(g, "**" + cond[i][0] + "** " + cond[i][1], fP, fPB, cTesto, 0, 0, wTxt, 1.48f, false) + S(7);
                float hCol1 = 0, hCol2 = 0;
                for (int i = 0; i < 5; i++) { hCol1 += hItem[i]; hCol2 += hItem[i + 5]; }
                float hCond = S(16) + S(30) + Math.Max(hCol1, hCol2) + S(10);
                if (disegna)
                {
                    RectangleF c = new RectangleF(x, y, wi, hCond);
                    using (GraphicsPath p = Arrotondato(c, S(14)))
                    {
                        using (Brush b = new SolidBrush(Color.FromArgb(18, 30, 50, 90)))
                        using (GraphicsPath po = Arrotondato(new RectangleF(c.X, c.Y + S(2), c.Width, c.Height), S(14))) g.FillPath(b, po);
                        using (Brush b = new SolidBrush(cScheda)) g.FillPath(b, p);
                        using (Pen pn = new Pen(cBordo)) g.DrawPath(pn, p);
                    }
                    Testo(g, Lang.T("Condizioni"), fH2, cTit, new RectangleF(c.Left + padC, c.Top + S(14), c.Width - 2 * padC, S(28)), StringAlignment.Near, StringAlignment.Center);
                    for (int col = 0; col < 2; col++)
                    {
                        float yy = c.Top + S(16) + S(34);
                        float xc = c.Left + padC + col * (colW + gapC);
                        for (int i = col * 5; i < col * 5 + 5; i++)
                        {
                            Testo(g, (i + 1).ToString(inv) + ".", fP, cTesto, new RectangleF(xc, yy, num - S(6), fP.GetHeight(g) * 1.48f), StringAlignment.Far, StringAlignment.Near);
                            TestoRicco(g, "**" + cond[i][0] + "** " + cond[i][1], fP, fPB, cTesto, xc + num, yy, wTxt, 1.48f, true);
                            yy += hItem[i];
                        }
                    }
                }
                y += hCond + S(16);
                // riquadro "In breve"
                string breve = "**" + Lang.T("In breve:") + "** " + Lang.T("usalo liberamente, impara dal codice, miglioralo e condividilo, ma sempre con il sorgente, con le fonti citate, dicendo cosa hai cambiato e senza farne commercio. Se dubiti di un risultato, la risposta giusta è controllare, non fidarsi.");
                float hB = TestoRicco(g, breve, fP, fPB, cTesto, 0, 0, wi - S(36), 1.45f, false) + S(24);
                if (disegna)
                {
                    RectangleF c = new RectangleF(x, y, wi, hB);
                    using (GraphicsPath p = Arrotondato(c, S(12)))
                    {
                        using (Brush b = new SolidBrush(Tema.Scuro ? Color.FromArgb(60, 240, 195, 109) : Color.FromArgb(255, 248, 230))) g.FillPath(b, p);
                        using (Pen pn = new Pen(Color.FromArgb(240, 195, 109))) g.DrawPath(pn, p);
                    }
                    TestoRicco(g, breve, fP, fPB, cTesto, c.Left + S(18), c.Top + S(12), wi - S(36), 1.45f, true);
                }
                y += hB + S(14);
                // piede: a sinistra il copyright, a destra la nota sulle traduzioni
                string f1 = "© 2026 Costantino IC8TEM · " + Lang.T("Licenza d'uso YAEC, versione 1");
                string f2 = Lang.T("Il testo è tradotto in tutte le lingue del programma; in caso di dubbio fa fede la versione italiana.");
                float w1 = g.MeasureString(f1, fFoot).Width, w2 = g.MeasureString(f2, fFoot).Width;
                bool unaRiga = w1 + w2 + S(30) < wi;
                if (disegna)
                {
                    Testo(g, f1, fFoot, Tema.Muted, new RectangleF(x, y, unaRiga ? w1 + S(4) : wi, S(20)), StringAlignment.Near, StringAlignment.Near);
                    Testo(g, f2, fFoot, Tema.Muted, new RectangleF(unaRiga ? x + wi - w2 - S(4) : x, unaRiga ? y : y + S(20), unaRiga ? w2 + S(4) : wi, S(20)), unaRiga ? StringAlignment.Far : StringAlignment.Near, StringAlignment.Near);
                }
                y += (unaRiga ? S(20) : S(40)) + S(24);
            }
            return y;
        }

        // Descrizione di ogni linguetta, nello stesso ordine delle linguette
        string[][] DescrizioniLinguette()
        {
            return new string[][] {
                new string[] { Lang.T("Posizione live e +- 24h"), Lang.T("La schermata principale, aggiornata ogni secondo. In alto le impostazioni generali (nominativo, lingua, colori, caratteri e tipo di carattere), il pulsante SCELTA BANDE e la casella dei dati complessi; sotto, i locator tuo e del DX (da 4 a 14 caratteri, con la precisione della posizione), la frequenza e gli orologi UTC, locale e del DX. La fascia di stato (verde = puntabile, arancione = fuori dai limiti, grigio = sotto l'orizzonte, blu = finestra comune) ha il conto alla rovescia; seguono la bussola e l'arco dell'elevazione con i limiti dell'antenna in giallo e quattro riquadri: Luna (fase, sorgere e tramonto), Eco e frequenze (Doppler, ritardo dell'eco e frequenze CFOM), Cielo e geometria (Tsky, distanza, declinazione, angolo orario, Dgrd e il pulsante VAI A VOLTA CELESTE) e S/N stimato (in 2500 Hz con la soglia tipica del modo come riferimento, dati del DX, la casella CALCOLI APPROFONDITI e il pulsante VAI AI CALCOLI). In basso le prossime 24 ore.") },
                new string[] { Lang.T("Distanza e Dgrd"), Lang.T("Grafico da 7 a 61 giorni della Dgrd (0 dB in basso, -15 dB in alto) e della distanza media giornaliera della Luna, con perigeo, apogeo, luna nuova e i tre giorni migliori (★). La classifica tiene conto solo delle ore in cui la Luna è davvero puntabile con i tuoi limiti.") + " " + Lang.T("Il simbolo ☀ segna i giorni in cui la Luna è vicina al Sole (rosso: entro 3 larghezze del fascio, arancione: entro 6): il rumore solare può peggiorare la ricezione. Colore e spessore delle due curve si cambiano nella barra sopra il grafico.") },
                new string[] { Lang.T("Volta celeste"), Lang.T("Il cielo visto dal tuo QTH, con l'orizzonte piatto e i colori del rumore del cielo (dal blu al rosso) alla frequenza scelta, i limiti della tua antenna, l'orizzonte del DX, le radiosorgenti, il Sole e il percorso della Luna nelle prossime 24 ore.") + " " + Lang.T("Le zone fuori dai limiti della tua antenna sono coperte da righe diagonali grigio chiaro.") },
                new string[] { Lang.T("Ricognizione dei miei ostacoli"), Lang.T("Mappa aerofotografica o topografica centrata sulla tua stazione, con sopra la volta celeste in pianta (orizzonte = cerchio esterno, zenit = centro): posizione attuale della Luna, percorso nelle prossime 24 ore con sorgere e tramonto, limiti dell'antenna in giallo e zone fuori dai limiti sfocate in grigio chiaro. Le maniglie gialle si trascinano con il mouse per regolare i limiti direttamente sulla mappa; la rotella cambia lo zoom.") + " " + Lang.T("La casella \"Sfuma le zone fuori dai limiti\" accende o spegne la sfocatura.") + " " + Lang.T("In alto a destra due cursori regolano l'opacità e il tono del grigio delle zone fuori dai limiti (il tono vale anche per la Volta celeste).") },
                new string[] { Lang.T("Luna sul mondo"), Lang.T("Mappa del mondo con le terre colorate secondo l'elevazione della Luna vista da ogni località, nello stesso momento della Posizione della Luna; passando il mouse si leggono elevazione, azimut e distanza, con un clic il punto diventa la stazione DX.") },
                new string[] { Lang.T("Posizione della Luna"), Lang.T("Tabella per il periodo scelto (in giorni, con l'intervallo in minuti) con il colore della puntabilità; passando il mouse sull'intestazione di una colonna compare la sua spiegazione. Esportazione CSV per Excel.") },
                new string[] { Lang.T("Budget EME"), Lang.T("Bilancio del collegamento per ogni banda scelta (da 50 a 432 MHz), con i dati di ogni banda memorizzati separatamente. A sinistra le due stazioni (antenna e guadagno, BETA per le antenne senza elevazione), sei indicatori (collegamento possibile, EIRP, perdita di tratta, segnale all'antenna, S/N e S/N in 2500 Hz con la soglia tipica del modo) e la tabella con tutti i passaggi; a destra lo schema dell'impianto di trasmissione e ricezione della stazione scelta: antenna e Tant, cavo antenna – relè, relè coassiale, trasmettitore con il suo cavo, preamplificatore, cavo di discesa, transverter facoltativo, cavetti e radio con MDS e modo. I cavi si scelgono dal database della linguetta CAVI COASSIALI e le perdite si calcolano da sole. In alto a destra la casella CALCOLI APPROFONDITI, la stessa della schermata principale.") },
                new string[] { Lang.T("Rumore solare"), Lang.T("Scarica dal web i flussi solari misurati dalla rete RSTN e stima quanto il Sole aumenta il rumore del ricevitore, in base alla distanza angolare tra Sole e Luna e al diagramma dell'antenna. Utile vicino alla luna nuova.") + " " + Lang.T("In alto quattro indicatori, a sinistra la fonte dei dati (NOAA RSTN consigliata, oppure F10.7 di NOAA o di Penticton, oppure un indirizzo personalizzato) con le stazioni, a destra lo spettro del flusso solare con l'estrapolazione alla frequenza di lavoro.") },
                new string[] { Lang.T("Mappa WWL e ADIF"), Lang.T("Mappa del mondo con il reticolo Maidenhead; caricando il file ADIF del log si colorano i quadrati lavorati (arancione), confermati via LoTW (verde) o solo con QSL (blu), anche per banda e solo EME.") + " " + Lang.T("Con \"Scarica da LoTW…\" il log viene scaricato direttamente da LoTW (nome utente e password vengono chiesti e memorizzati nelle impostazioni).") },
                new string[] { "ABOUT & CREDITS", Lang.T("Crediti con i link e storia delle versioni.") },
                new string[] { Lang.T("MANUALE D'USO APPROFONDITO"), Lang.T("Questo manuale, dentro il programma e in tutte le lingue: indice cliccabile, ricerca, formule e fonti.") },
                new string[] { Lang.T("TEORIA E CONSIGLI SULL'EME"), Lang.T("Come funziona l'EME e come lavorarlo al meglio: rumore del cielo e Dgrd, Sole, polarizzazione, budget del collegamento, Doppler, procedure operative e fonti; indice cliccabile, ricerca e formule, come il manuale.") },
                new string[] { Lang.T("Export in Excel dei calcoli"), Lang.T("Lo stesso Budget EME in forma di foglio Excel: le caselle verdi si modificano e i risultati si aggiornano subito.") },
                new string[] { Lang.T("DEBUG FORMULE"), Lang.T("Tutti i parametri e le formule del Budget EME e del Rumore solare, per entrambe le direzioni (tu → DX e DX → tu), con i valori sostituiti e il risultato di ogni passaggio: lunghezza d'onda, sezione radar della Luna, perdita di tratta, EIRP, segnale lungo la catena di ricezione, MDS e margine, figura di rumore con Friis, temperature, rumore e S/N, e per il Sole flusso, fascio, attenuazione del diagramma, area efficace e aumento del rumore. Si attiva con la casella \"CALCOLI APPROFONDITI\"; il pulsante in basso copia tutto negli appunti.") + " " + Lang.T("È impaginato come un documento di Word, con le formule in stile Equation Editor: si può copiare negli appunti o salvare in Word (.docx).") }
            };
        }

        // Testo della guida (linguetta ISTRUZIONI e manuale PDF): w(testo, dimensione in punti, grassetto)
        void TestoIstruzioni(Action<string, float, bool> w, bool conLinguette)
        {
            w(Lang.T("ISTRUZIONI PER L'USO DI YAEC"), 15F, true);
            w("", 5F, false);
            w(Lang.T("PERCHÉ QUESTO PROGRAMMA"), 11F, true);
            w(Lang.T("YAEC nasce per avere in un unico programma tutti i dettagli utili all'esercizio di una stazione EME, anche e soprattutto quando la stazione ha dei vincoli: un'antenna fissa in elevazione (senza rotore di elevazione), un rotore con escursione limitata, ostruzioni del QTH (edifici, alberi, montagne, il profilo della costa) che nascondono parte del cielo. I programmi EME più diffusi dicono dove si trova la Luna; YAEC dice anche se la Luna è davvero raggiungibile dalla TUA antenna, quando lo sarà, in quali condizioni (distanza, rumore del cielo, polarizzazione, Sole) e quanto segnale ci si può aspettare."), 10F, false);
            w("", 5F, false);
            w(Lang.T("PRIMI PASSI"), 11F, true);
            w(Lang.T("1. Nella linguetta Posizione live e +- 24h inserisci il tuo locator WWL, quello della stazione che vuoi ascoltare (DX) e la frequenza (MHz + kHz). Questi dati vengono ricopiati automaticamente in tutte le linguette, e se li cambi in un'altra linguetta tornano aggiornati anche qui. Se i MHz sono quelli di una delle bande scelte, il Budget EME passa automaticamente a quella banda (e viceversa)."), 10F, false);
            w(Lang.T("2. In Posizione della Luna imposta la quota e i limiti della tua antenna: settore di azimut (in senso orario, da → a) ed elevazione minima e massima. Esempi: antenna fissa sull'orizzonte = elevazione da 0 a 0 (o da 0 a 10 per il lobo); ostacoli fino a 8° = elevazione minima 8; rotore che non supera 60° = elevazione massima 60."), 10F, false);
            w(Lang.T("3. Scegli la frequenza: MHz e kHz (la frequenza CFOM, es. 144 e 180 = 144,180 MHz)."), 10F, false);
            w(Lang.T("4. Se vuoi pianificare un QSO, attiva la seconda stazione e inserisci il locator e i limiti del DX."), 10F, false);
            w(Lang.T("5. Premi \"Calcola tabella\": le righe verdi sono quelle utili, il riquadro in basso elenca le finestre."), 10F, false);
            w("", 5F, false);
            w(Lang.T("COME SI SCELGONO LE LINGUETTE"), 11F, true);
            w(Lang.T("Le linguette sono raccolte in sei gruppi nella barra in alto: In diretta (Posizione live e +- 24h, Ricognizione dei miei ostacoli, Volta celeste), Pianificazione (Distanza e Dgrd, Posizione della Luna), Collegamento (Budget EME, Rumore solare, Export in Excel dei calcoli, DEBUG FORMULE), Log (Mappa WWL e ADIF), Aiuto e tools (MANUALE D'USO APPROFONDITO, TEORIA E CONSIGLI SULL'EME, CAVI COASSIALI), Credits and thanks (ABOUT & CREDITS, CONTATTI DELL'AUTORE E RINGRAZIAMENTI, LICENZA D'USO). Clicca un gruppo nella prima riga e poi la linguetta nella seconda; ogni gruppo ricorda l'ultima linguetta aperta. Le linguette in grigio si attivano con la casella \"CALCOLI APPROFONDITI\"."), 10F, false);
            w(Lang.T("Schema di colori (impostazioni generali): Chiaro, Notte (toni di blu) o Nero (sfondo nero, adatto all'uso al buio e agli schermi OLED)."), 10F, false);
            w("", 5F, false);
            if (conLinguette) w(Lang.T("LE LINGUETTE"), 11F, true);
            if (conLinguette)
                foreach (string[] x in DescrizioniLinguette())
                {
                    w("• " + x[0], 10F, true);
                    w("   " + x[1], 10F, false);
                }
            w("", 5F, false);
            w(Lang.T("PARAMETRI MODIFICABILI: COSA SONO E COSA SIGNIFICANO"), 11F, true);
            foreach (string[] par in ParametriIstruzioni())
            {
                if (par.Length == 1) { w("", 3F, false); w(par[0], 10.5F, true); continue; }
                w("• " + par[0], 10F, true);
                w("   " + par[1], 10F, false);
            }
            w("", 5F, false);
            w(Lang.T("MNR E CFOM: COSA VOGLIONO DIRE"), 11F, true);
            foreach (string par in TestiMnrCfom()) { w(par, 10F, false); w("", 3F, false); }
            w("", 5F, false);
            w(Lang.T("CONSIGLI PER STAZIONI CON VINCOLI"), 11F, true);
            w(Lang.T("• Antenna fissa sull'orizzonte: imposta l'elevazione da 0 al limite superiore del lobo (es. 0-12°), attiva \"BETA- antenna senza elevazione\" nel budget con l'altezza reale da terra e cerca nella linguetta Distanza e Dgrd i giorni migliori: le finestre saranno brevi, al sorgere e al tramonto."), 10F, false);
            w(Lang.T("• Ostruzioni del QTH: se un ostacolo copre solo un settore, restringi il settore di azimut utile oppure alza l'elevazione minima; controlla il risultato nella Volta celeste (linee gialle)."), 10F, false);
            w(Lang.T("• Per un QSO con un DX, contano le finestre COMUNI (righe verdi con il DX attivo) e la Dgrd della stazione più svantaggiata."), 10F, false);
            w(Lang.T("• Vicino alla luna nuova controlla la linguetta Rumore solare: con il Sole vicino alla Luna il rumore può salire di molti dB."), 10F, false);
            w(Lang.T("• Prestazioni delle antenne: consulta le tabelle di VE7BQH (guadagno, G/T e temperatura d'antenna Ta delle antenne EME più diffuse) e inserisci nel Budget EME il valore Tant della tua antenna. Il rumore delle antenne in quelle tabelle è calcolato con l'antenna inclinata a 30° di elevazione."), 10F, false);
            w(Lang.T("• Quota della stazione: con un locator di 10 caratteri la quota del terreno viene presa automaticamente dal web (Open Topo Data, Open-Meteo); con locator più corti inseriscila a mano. È la quota del terreno nel punto del locator, non l'altezza dell'antenna sopra il suolo."), 10F, false);
            w("", 5F, false);
            w(Lang.T("IL SOLE VICINO ALLA LUNA"), 11F, true);
            w(Lang.T("Intorno alla luna nuova la Luna passa vicino al Sole nel cielo. Il Sole è una radiosorgente fortissima (da decine a migliaia di SFU secondo la frequenza e l'attività solare): quando entra nel lobo principale o nei primi lobi laterali dell'antenna, la temperatura di rumore del sistema sale di molti dB e l'eco della Luna può sparire, anche con una Dgrd ottima."), 10F, false);
            w(Lang.T("Nella linguetta Distanza e Dgrd, YAEC calcola per ogni giorno la distanza angolare minima tra Sole e Luna nelle ore utili e la confronta con la larghezza del fascio della tua antenna (θ ≈ √(41253/G), dal guadagno impostato nel Budget EME): ☀ rosso = Sole entro 3 larghezze del fascio, ☀ arancione = entro 6. La colonna \"Sole-Luna (°)\" della tabella riporta la separazione; la linguetta Rumore solare stima l'aumento del rumore con il flusso solare misurato."), 10F, false);
            w(Lang.T("Le antenne grandi (fascio stretto) soffrono meno: con un fascio di 2-3° si lavora anche a pochi gradi dal Sole, mentre con una Yagi singola a 144 MHz (fascio di circa 20°) servono decine di gradi. Vicino alla luna nuova si usa l'offset \"Icarus\": si punta l'antenna un poco più lontano dal Sole rispetto alla Luna, accettando una piccola perdita di guadagno in cambio di molto meno rumore (Bob Atkins KA1GT)."), 10F, false);
