        static double MapSize(int z) { return 256.0 * (1 << z); }
        static double LonToX(double lon, int z) { return (lon + 180.0) / 360.0 * MapSize(z); }
        static double LatToY(double lat, int z)
        {
            if (lat > 85.05) lat = 85.05;
            if (lat < -85.05) lat = -85.05;
            double r = lat * Math.PI / 180.0;
            return (1.0 - Math.Log(Math.Tan(r) + 1.0 / Math.Cos(r)) / Math.PI) / 2.0 * MapSize(z);
        }
        static double XToLon(double x, int z) { return x / MapSize(z) * 360.0 - 180.0; }
        static double YToLat(double y, int z)
        {
            double n = Math.PI * (1.0 - 2.0 * y / MapSize(z));
            return Math.Atan(Math.Sinh(n)) * 180.0 / Math.PI;
        }

