        // Luna e cielo a 144 MHz, gli stessi della schermata di avvio (usati anche nei contatti)
        public static Bitmap LunaImg()
        {
            try
            {
                using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(LUNA_JPG)))
                using (Image tmp = Image.FromStream(ms))
                    return new Bitmap(tmp);
            }
            catch { return null; }
        }

        public static Bitmap CieloImg()
        {
            Bitmap b = new Bitmap(360, 180);
            double lo = 150, hi = 4000;
            for (int j = 0; j < 180; j++)
                for (int i = 0; i < 360; i++)
                    b.SetPixel(i, j, MainForm.Spettro(CieloGsm.Tsky(360 - i - 0.5, 90 - j - 0.5, 144), lo, hi));
            return b;
        }

        public static Image LogoAri()
        {
            try
            {
                using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(LOGO_ARI_PNG)))
                using (Image tmp = Image.FromStream(ms))
                    return new Bitmap(tmp);
            }
            catch { return null; }
        }

        readonly Bitmap cielo;
        readonly Image luna;
        readonly Image logo = LogoAri();

        // Disco della Luna (usato anche per lo sfondo della schermata principale)
        public static Image ImmagineLuna()
        {
            try
            {
                using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(LUNA_JPG)))
                using (Image tmp = Image.FromStream(ms))
                    return new Bitmap(tmp);
            }
            catch { return null; }
        }
        // Icona della finestra e della barra delle applicazioni: la Luna stilizzata della schermata di avvio
        // (lo stesso disco è in YAEC.ico, incorporata nell'eseguibile da compila.bat con /win32icon)
        static Icon iconaLuna;
        public static Icon IconaLuna()
        {
            if (iconaLuna != null) return iconaLuna;
            try
            {
                Image l = ImmagineLuna();
                if (l == null) return iconaLuna;
                Bitmap bmp = new Bitmap(64, 64, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
                using (Graphics g = Graphics.FromImage(bmp))
                using (GraphicsPath gp = new GraphicsPath())
                {
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                    gp.AddEllipse(1, 1, 62, 62);
                    g.SetClip(gp);
                    g.DrawImage(l, 0, 0, 64, 64);
                }
                l.Dispose();
                iconaLuna = Icon.FromHandle(bmp.GetHicon());
            }
            catch { }
            return iconaLuna;
        }

        readonly Timer t = new Timer();
        readonly DateTime inizio = DateTime.UtcNow;
        const double Durata = 6.0;
        readonly float sc;

        readonly string nominativo;
        // messaggi del controllo dei file nella cartella data (scritti dal thread in background)
        volatile string statoDati = "";

        public SplashForm(string call)
        {
            nominativo = call ?? "";
            this.FormBorderStyle = FormBorderStyle.None;
            this.StartPosition = FormStartPosition.CenterScreen;
            this.ShowInTaskbar = true;
            this.Text = MainForm.TitoloProgramma;
            try { Icon ic = IconaLuna(); if (ic != null) this.Icon = ic; } catch { }
            this.DoubleBuffered = true;
            this.BackColor = Color.Black;
            using (Graphics g = this.CreateGraphics()) sc = g.DpiX / 96f;
            this.ClientSize = new Size((int)(720 * sc), (int)(420 * sc));

            // cielo intero in ascensione retta e declinazione, colorato dal blu al rosso a 144 MHz
            cielo = new Bitmap(360, 180);
            double lo = 150, hi = 4000;
            for (int j = 0; j < 180; j++)
                for (int i = 0; i < 360; i++)
                {
                    double ra = 360 - i - 0.5, dec = 90 - j - 0.5;
                    cielo.SetPixel(i, j, MainForm.Spettro(CieloGsm.Tsky(ra, dec, 144), lo, hi));
                }
            try
            {
                using (MemoryStream ms = new MemoryStream(Convert.FromBase64String(LUNA_JPG)))
                using (Image tmp = Image.FromStream(ms))
                    luna = new Bitmap(tmp);
            }
            catch { luna = null; }

            t.Interval = 40;
            t.Tick += (s, e) =>
            {
                if ((DateTime.UtcNow - inizio).TotalSeconds >= Durata) { t.Stop(); this.Close(); }
                else this.Invalidate();
            };
            this.Shown += (s, e) =>
            {
                t.Start();
                Lang.T("Cartella data pronta");   // tabella delle traduzioni pronta prima del thread
                System.Threading.Thread th = new System.Threading.Thread(() =>
                {
                    try { Dati.Controlla(m => { statoDati = m; }); } catch { }
                });
                th.IsBackground = true;
                th.Start();
            };
            this.Click += (s, e) => { t.Stop(); this.Close(); };
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.InterpolationMode = InterpolationMode.HighQualityBicubic;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
            Rectangle r = this.ClientRectangle;
            g.DrawImage(cielo, r);
            using (Brush velo = new SolidBrush(Color.FromArgb(89, 0, 0, 0))) g.FillRectangle(velo, r);

            // disco della Luna (180 px) con l'alone chiaro
            float d = 180 * sc;
            RectangleF rl = new RectangleF(r.Width / 2f - d / 2, 20 * sc, d, d);
            using (Brush alone = new SolidBrush(Color.FromArgb(69, 255, 255, 255)))
                g.FillEllipse(alone, rl.X - 9 * sc, rl.Y - 9 * sc, d + 18 * sc, d + 18 * sc);
            if (luna != null)
            {
                using (GraphicsPath gp = new GraphicsPath())
                {
                    gp.AddEllipse(rl);
                    Region old = g.Clip;
                    g.SetClip(gp);
                    float lw = luna.Width, lh = luna.Height, k = Math.Max(d / lw, d / lh);
                    g.DrawImage(luna, rl.X + (d - lw * k) / 2, rl.Y + (d - lh * k) / 2, lw * k, lh * k);
                    g.Clip = old;
                }
            }
            else using (Brush b = new SolidBrush(Color.Gainsboro)) g.FillEllipse(b, rl);

            Color giallo = Color.FromArgb(255, 235, 150);
            using (StringFormat sfc = new StringFormat())
            using (StringFormat sfr = new StringFormat())
            using (StringFormat sfl = new StringFormat())
            {
                sfc.Alignment = StringAlignment.Center;
                sfr.Alignment = StringAlignment.Far;
                sfl.Trimming = StringTrimming.EllipsisCharacter; sfl.FormatFlags = StringFormatFlags.NoWrap;
                // titolo e, subito sotto, la riga gialla
                string riga1 = MainForm.NomeProgramma + " " + MainForm.Versione;
                string riga2 = Lang.T("a cura di Costantino IC8TEM") + (nominativo.Length > 0 ? " " + Lang.T("per") + " " + nominativo : "");
                using (Font f1 = new Font(Lang.FontUi, 25 * sc, FontStyle.Bold, GraphicsUnit.Pixel))
                using (Font f2 = new Font(Lang.FontUi, 18.5f * sc, FontStyle.Bold, GraphicsUnit.Pixel))
                using (Brush gb = new SolidBrush(giallo))
                {
                    Ombra(g, riga1, f1, Brushes.White, new RectangleF(0, 212 * sc, r.Width, 36 * sc), sfc, 2 * sc);
                    Ombra(g, riga2, f2, gb, new RectangleF(0, 249 * sc, r.Width, 30 * sc), sfc, 2 * sc);
                }

                // fascia in basso: patrocinio con il logo, stato dei file e secondi
                using (LinearGradientBrush zona = new LinearGradientBrush(new RectangleF(0, 292 * sc, r.Width, 95 * sc), Color.FromArgb(0, 0, 0, 0), Color.FromArgb(89, 0, 0, 0), 90f))
                    g.FillRectangle(zona, 0, 292 * sc, r.Width, 94 * sc);
                float lL = 84 * sc, lx = r.Width - lL - 18 * sc, ly = 290 * sc;
                if (logo != null)
                {
                    using (Brush om = new SolidBrush(Color.FromArgb(120, 0, 0, 0))) g.FillEllipse(om, lx + 2 * sc, ly + 3 * sc, lL, lL);
                    g.DrawImage(logo, lx, ly, lL, lL);
                }
                float xr = r.Width - 114 * sc;
                using (Font fp1 = new Font(Lang.FontUi, 11.5f * sc, GraphicsUnit.Pixel))
                using (Font fp2 = new Font(Lang.FontUi, 12.5f * sc, FontStyle.Bold, GraphicsUnit.Pixel))
                using (Brush gb2 = new SolidBrush(giallo))
                {
                    Ombra(g, Lang.T("con il patrocinio della"), fp1, Brushes.White, new RectangleF(0, 310 * sc, xr, 17 * sc), sfr, sc);
                    Ombra(g, Lang.T("Sezione ARI Valle del Liri"), fp2, gb2, new RectangleF(0, 326 * sc, xr, 19 * sc), sfr, sc);
                }

                double tr = Math.Min(Durata, (DateTime.UtcNow - inizio).TotalSeconds);
                string sd = statoDati;
                using (Font f3 = new Font(Lang.FontUi, 12 * sc, GraphicsUnit.Pixel))
                using (Font f4 = new Font(Lang.FontUi, 11.5f * sc, GraphicsUnit.Pixel))
                using (Brush chiaro = new SolidBrush(Color.FromArgb(230, 236, 245)))
                {
                    if (!string.IsNullOrEmpty(sd))
                        Ombra(g, sd, f3, Brushes.White, new RectangleF(20 * sc, 365 * sc, 440 * sc, 18 * sc), sfl, sc);
                    string sec = string.Format(Lang.T("{0} s di {1}"), (int)Math.Floor(tr), (int)Durata);
                    Ombra(g, sec, f4, chiaro, new RectangleF(0, 372 * sc, r.Width - 20 * sc, 17 * sc), sfr, sc);
                }

                // barra verde che si riempie da sinistra verso destra
                float bx = 20 * sc, by = 394 * sc, bwt = r.Width - 40 * sc, bh = 10 * sc;
                float bw = (float)(bwt * tr / Durata);
                using (Brush fondo = new SolidBrush(Color.FromArgb(120, 0, 0, 0))) g.FillRectangle(fondo, bx, by, bwt, bh);
                using (Brush verde = new SolidBrush(Color.FromArgb(40, 200, 80))) g.FillRectangle(verde, bx, by, bw, bh);
                using (Pen bordo = new Pen(Color.FromArgb(180, 255, 255, 255))) g.DrawRectangle(bordo, bx, by, bwt, bh);
            }
        }

        static void Ombra(Graphics g, string s, Font f, Brush b, RectangleF rc, StringFormat sf, float o)
        {
            g.DrawString(s, f, Brushes.Black, new RectangleF(rc.X + o, rc.Y + o, rc.Width, rc.Height), sf);
            g.DrawString(s, f, b, rc, sf);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                t.Dispose();
                cielo.Dispose();
                if (luna != null) luna.Dispose();
                if (logo != null) logo.Dispose();
            }
            base.Dispose(disposing);
        }
    }

    // ---------- Documenti disegnati (manuale, DEBUG FORMULE): testo, tabelle e formule in stile Equation Editor ----------

    // Formule: piccolo linguaggio di marcatura
    //   \frac{a}{b}  frazione        x_{ab} / x^{2}  pedice / apice     \sqrt{x}  radice
    //   \p{x} ( )   \b{x} [ ]   \a{x} | |   (delimitatori che crescono col contenuto)
    //   \t{testo}  testo diritto con spazi    \h{x}  risultato evidenziato in giallo    \,  spazio sottile
    // Le lettere singole sono in corsivo (variabili), le parole di più lettere e i numeri sono diritti.
    abstract class MBox
    {
        public float W, A, D;   // larghezza, sopra e sotto la linea di base (pixel)
        public abstract void Draw(Graphics g, float x, float y, Color c);
    }

    class MTesto : MBox
    {
        public string T; public Font F;
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            using (Brush b = new SolidBrush(c)) g.DrawString(T, F, b, x, y - A, Formula.Sf);
        }
    }

    class MRiga : MBox
    {
        public List<MBox> Figli = new List<MBox>();
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            foreach (MBox m in Figli) { m.Draw(g, x, y, c); x += m.W; }
        }
    }

    class MFraz : MBox
    {
        public MBox Num, Den; public float Asse, Sp, Spess;
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            float ya = y - Asse;
            Num.Draw(g, x + (W - Num.W) / 2f, ya - Sp - Num.D, c);
            Den.Draw(g, x + (W - Den.W) / 2f, ya + Sp + Den.A, c);
            using (Pen p = new Pen(c, Spess)) g.DrawLine(p, x + Spess, ya, x + W - Spess, ya);
        }
    }

    class MScript : MBox
    {
        public MBox Base, Sub, Sup; public float SubY, SupY;
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            Base.Draw(g, x, y, c);
            float xs = x + Base.W;
            if (Sup != null) Sup.Draw(g, xs, y - SupY, c);
            if (Sub != null) Sub.Draw(g, xs, y + SubY, c);
        }
    }

    class MDelim : MBox
    {
        public MBox Dentro; public char Ap, Ch; public float Lp;
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            float top = y - A + 1, bot = y + D - 1, h = bot - top, w = Lp;
            using (Pen p = new Pen(c, Math.Max(1f, h / 26f)))
            {
                p.StartCap = LineCap.Round; p.EndCap = LineCap.Round;
                DisegnaDelim(g, p, Ap, x, top, w, h, true);
                Dentro.Draw(g, x + w, y, c);
                DisegnaDelim(g, p, Ch, x + w + Dentro.W, top, w, h, false);
            }
        }
        static void DisegnaDelim(Graphics g, Pen p, char d, float x, float top, float w, float h, bool sinistra)
        {
            float m = w * 0.5f;
            if (d == '(' || d == ')')
            {
                float x1 = sinistra ? x + w * 0.75f : x + w * 0.25f, x2 = sinistra ? x + w * 0.2f : x + w * 0.8f;
                using (GraphicsPath gp = new GraphicsPath())
                {
                    gp.AddBezier(x1, top, x2, top + h * 0.25f, x2, top + h * 0.75f, x1, top + h);
                    g.DrawPath(p, gp);
                }
            }
            else if (d == '[' || d == ']')
            {
                float xv = sinistra ? x + w * 0.35f : x + w * 0.65f, xo = sinistra ? x + w * 0.8f : x + w * 0.2f;
                g.DrawLines(p, new PointF[] { new PointF(xo, top), new PointF(xv, top), new PointF(xv, top + h), new PointF(xo, top + h) });
            }
            else if (d == '|') g.DrawLine(p, x + m, top, x + m, top + h);
        }
    }

    class MRad : MBox
    {
        public MBox Dentro; public float Lr;
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            float top = y - A + 1, bot = y + D;
            using (Pen p = new Pen(c, Math.Max(1f, (A + D) / 30f)))
            {
                p.LineJoin = LineJoin.Round;
                g.DrawLines(p, new PointF[] {
                    new PointF(x, bot - (A + D) * 0.4f), new PointF(x + Lr * 0.3f, bot - (A + D) * 0.48f),
                    new PointF(x + Lr * 0.6f, bot), new PointF(x + Lr, top), new PointF(x + W, top) });
            }
            Dentro.Draw(g, x + Lr + 2, y, c);
        }
    }

    class MEvid : MBox
    {
        public MBox Dentro; public float Pad;
        public override void Draw(Graphics g, float x, float y, Color c)
        {
            RectangleF r = new RectangleF(x + 1, y - A, W - 2, A + D);
            using (Brush b = new SolidBrush(Color.FromArgb(255, 243, 176))) g.FillRectangle(b, r);
            using (Pen p = new Pen(Color.FromArgb(224, 190, 70))) g.DrawRectangle(p, r.X, r.Y, r.Width, r.Height);
            Dentro.Draw(g, x + Pad, y, Color.FromArgb(40, 40, 40));
        }
    }

    class MSpazio : MBox
    {
        public override void Draw(Graphics g, float x, float y, Color c) { }
    }

    static class Formula
    {
        public static readonly StringFormat Sf = CreaSf();
        static StringFormat CreaSf()
        {
            StringFormat f = (StringFormat)StringFormat.GenericTypographic.Clone();
            f.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
            return f;
        }
        static string fam;
        public static string Famiglia
        {
            get
            {
                if (fam == null)
                {
                    fam = "Times New Roman";
                    try
                    {
                        foreach (FontFamily ff in FontFamily.Families)
                            if (ff.Name == "Cambria") { fam = "Cambria"; break; }
                    }
                    catch { }
                }
                return fam;
            }
        }
        static readonly Dictionary<string, Font> fonts = new Dictionary<string, Font>();
        static Font FontM(float px, bool corsivo)
        {
            px = (float)Math.Round(px * 2) / 2f;
            string k = px.ToString(CultureInfo.InvariantCulture) + (corsivo ? "i" : "r");
            Font f;
            if (!fonts.TryGetValue(k, out f))
            {
                f = new Font(Famiglia, Math.Max(5f, px), corsivo ? FontStyle.Italic : FontStyle.Regular, GraphicsUnit.Pixel);
                fonts[k] = f;
            }
            return f;
        }
        static Graphics gm;
        public static Graphics Misura
        {
            get
            {
                if (gm == null)
                {
                    gm = Graphics.FromImage(new Bitmap(4, 4));
                    gm.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;
                }
                return gm;
            }
        }

        static MTesto Atomo(string t, float px, bool corsivo, float dopo)
        {
            MTesto m = new MTesto();
            m.T = t; m.F = FontM(px, corsivo);
            FontFamily ff = m.F.FontFamily;
            FontStyle st = m.F.Style;
            float em = m.F.Size / ff.GetEmHeight(st);
            m.A = ff.GetCellAscent(st) * em * 0.86f;
            m.D = ff.GetCellDescent(st) * em * 0.9f;
            SizeF sz = Misura.MeasureString(t, m.F, 10000, Sf);
            m.W = sz.Width + (corsivo ? px * 0.06f : 0f) + dopo;
            return m;
        }

        static MSpazio Spazio(float w) { MSpazio s = new MSpazio(); s.W = w; return s; }

        static bool Operatore(char c) { return "=+−-·×≈→⇒<>≤≥±∓⋅/".IndexOf(c) >= 0; }

        public static MBox Analizza(string s, float px) { int i = 0; return Riga(s, ref i, px, false, '\0'); }

        static string Gruppo(string s, ref int i)
        {
            // legge {...} con parentesi annidate, oppure un solo carattere
            if (i >= s.Length) return "";
            if (s[i] != '{') { string c = s[i].ToString(); i++; return c; }
            int liv = 0, ini = i + 1;
            for (; i < s.Length; i++)
            {
                if (s[i] == '{') liv++;
                else if (s[i] == '}') { liv--; if (liv == 0) { string r = s.Substring(ini, i - ini); i++; return r; } }
            }
            return s.Substring(ini);
        }

        static MBox Riga(string s, ref int i, float px, bool script, char fine)
        {
            MRiga r = new MRiga();
            while (i < s.Length)
            {
                char c = s[i];
                if (c == fine) break;
                if (c == ' ') { i++; continue; }
                if (c == '\\')
                {
                    int j = i + 1;
                    while (j < s.Length && char.IsLetter(s[j])) j++;
                    string cmd = s.Substring(i + 1, j - i - 1);
                    if (cmd.Length == 0 && j < s.Length) { cmd = s[j].ToString(); j++; }
                    i = j;
                    MBox m = null;
                    switch (cmd)
                    {
                        case "frac":
                            {
                                string a = Gruppo(s, ref i), b = Gruppo(s, ref i);
                                float pf = script ? px : px * 0.94f;
                                MFraz f = new MFraz();
                                f.Num = Analizza(a, pf); f.Den = Analizza(b, pf);
                                f.Asse = px * 0.27f; f.Sp = px * 0.16f; f.Spess = Math.Max(1f, px / 18f);
                                f.W = Math.Max(f.Num.W, f.Den.W) + px * 0.3f;
                                f.A = f.Asse + f.Sp + f.Num.D + f.Num.A;
                                f.D = -f.Asse + f.Sp + f.Den.A + f.Den.D;
                                m = f; break;
                            }
                        case "sqrt":
                            {
                                MRad rd = new MRad();
                                rd.Dentro = Analizza(Gruppo(s, ref i), px);
                                rd.Lr = px * 0.6f;
                                rd.W = rd.Lr + rd.Dentro.W + px * 0.15f;
                                rd.A = rd.Dentro.A + px * 0.12f; rd.D = rd.Dentro.D;
                                m = rd; break;
                            }
                        case "p": case "b": case "a":
                            {
                                MDelim d = new MDelim();
                                d.Dentro = Analizza(Gruppo(s, ref i), px);
                                d.Ap = cmd == "p" ? '(' : (cmd == "b" ? '[' : '|');
                                d.Ch = cmd == "p" ? ')' : (cmd == "b" ? ']' : '|');
                                d.Lp = px * (cmd == "a" ? 0.3f : 0.38f);
                                d.W = d.Dentro.W + 2 * d.Lp;
                                d.A = Math.Max(d.Dentro.A, px * 0.72f) + px * 0.06f;
                                d.D = Math.Max(d.Dentro.D, px * 0.22f) + px * 0.06f;
                                m = d; break;
                            }
                        case "t":
                            m = Atomo(Gruppo(s, ref i), px, false, 0); break;
                        case "h":
                            {
                                MEvid e = new MEvid();
                                e.Dentro = Analizza(Gruppo(s, ref i), px);
                                e.Pad = px * 0.22f;
                                e.W = e.Dentro.W + 2 * e.Pad; e.A = e.Dentro.A + px * 0.08f; e.D = e.Dentro.D + px * 0.08f;
                                m = e; break;
                            }
                        case ",": m = Spazio(px * 0.18f); break;
                        case ";": m = Spazio(px * 0.5f); break;
                        case "quad": m = Spazio(px * 1.4f); break;
                        default: m = Atomo(cmd, px, false, 0); break;
                    }
                    r.Figli.Add(Script(s, ref i, px, m));
                    continue;
                }
                if (c == '{')
                {
                    MBox gr = Analizza(Gruppo(s, ref i), px);
                    r.Figli.Add(Script(s, ref i, px, gr));
                    continue;
                }
                MBox at;
                if (char.IsLetter(c) && c < 'ʰ')
                {
                    int j = i;
                    while (j < s.Length && char.IsLetter(s[j]) && s[j] < 'ʰ') j++;
                    string w = s.Substring(i, j - i);
                    i = j;
                    at = Atomo(w, px, w.Length == 1 && !script, 0);
                }
                else if (char.IsDigit(c))
                {
                    int j = i;
                    while (j < s.Length && (char.IsDigit(s[j]) || ((s[j] == ',' || s[j] == '.') && j + 1 < s.Length && char.IsDigit(s[j + 1])))) j++;
                    at = Atomo(s.Substring(i, j - i), px, false, 0);
                    i = j;
                }
                else if (Operatore(c))
                {
                    i++;
                    string t = c == '-' ? "−" : c.ToString();
                    bool binario = c != '/' && r.Figli.Count > 0;
                    if (binario && !script) r.Figli.Add(Spazio(px * (c == '·' || c == '×' ? 0.15f : 0.25f)));
                    at = Atomo(t, px, false, 0);
                    r.Figli.Add(at);
                    if (binario && !script) r.Figli.Add(Spazio(px * (c == '·' || c == '×' ? 0.15f : 0.25f)));
                    continue;
                }
                else if ((c >= 'Α' && c <= 'ω') || c == 'ϑ' || c == 'ϕ')
                {
                    i++;
                    at = Atomo(c.ToString(), px, !script && c >= 'α', 0);
                }
                else
                {
                    i++;
                    at = Atomo(c.ToString(), px, false, 0);
                }
                r.Figli.Add(Script(s, ref i, px, at));
            }
            Misura_(r);
            return r;
        }

        static MBox Script(string s, ref int i, float px, MBox baseBox)
        {
            MBox sub = null, sup = null;
            while (i < s.Length && (s[i] == '_' || s[i] == '^'))
            {
                bool basso = s[i] == '_';
                i++;
                string gtxt = Gruppo(s, ref i);
                int k = 0;
                MBox m = Riga(gtxt, ref k, px * 0.7f, true, '\0');
                if (basso) sub = m; else sup = m;
            }
            if (sub == null && sup == null) return baseBox;
            MScript sc = new MScript();
            sc.Base = baseBox; sc.Sub = sub; sc.Sup = sup;
            sc.SubY = Math.Max(px * 0.22f, sub == null ? 0 : sub.A - px * 0.35f);
            sc.SupY = Math.Max(px * 0.42f, baseBox.A - px * 0.35f);
            if (sup != null && sub != null) sc.SupY = Math.Max(sc.SupY, sup.D + px * 0.5f);
            sc.W = baseBox.W + Math.Max(sub == null ? 0 : sub.W, sup == null ? 0 : sup.W) + px * 0.05f;
            sc.A = Math.Max(baseBox.A, sup == null ? 0 : sc.SupY + sup.A);
            sc.D = Math.Max(baseBox.D, sub == null ? 0 : sc.SubY + sub.D);
            return sc;
        }

        static void Misura_(MRiga r)
        {
            r.W = 0; r.A = 0; r.D = 0;
            foreach (MBox m in r.Figli) { r.W += m.W; r.A = Math.Max(r.A, m.A); r.D = Math.Max(r.D, m.D); }
        }

        // ---- Esportazione in OMML (Office Math) per il documento di Word
        public static string Omml(string s)
        {
            StringBuilder sb = new StringBuilder();
            int i = 0;
            OmmlRiga(s, ref i, sb, false);
            return "<m:oMath>" + sb.ToString() + "</m:oMath>";
        }

        static string Xml(string t) { return t.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;"); }

        static void Run(StringBuilder sb, string t, bool diritto)
        {
            sb.Append("<m:r>");
            if (diritto) sb.Append("<m:rPr><m:sty m:val=\"p\"/></m:rPr>");
            sb.Append("<w:rPr><w:rFonts w:ascii=\"Cambria Math\" w:hAnsi=\"Cambria Math\"/></w:rPr><m:t xml:space=\"preserve\">").Append(Xml(t)).Append("</m:t></m:r>");
        }

        static string OmmlGruppo(string g)
        {
            StringBuilder sb = new StringBuilder();
            int k = 0;
            OmmlRiga(g, ref k, sb, false);
            return sb.ToString();
        }

        static void OmmlRiga(string s, ref int i, StringBuilder sb, bool script)
        {
            while (i < s.Length)
            {
                char c = s[i];
                if (c == ' ') { i++; continue; }
                StringBuilder el = new StringBuilder();
                if (c == '\\')
                {
                    int j = i + 1;
                    while (j < s.Length && char.IsLetter(s[j])) j++;
                    string cmd = s.Substring(i + 1, j - i - 1);
                    if (cmd.Length == 0 && j < s.Length) { cmd = s[j].ToString(); j++; }
                    i = j;
                    switch (cmd)
                    {
                        case "frac":
                            {
                                string a = Gruppo(s, ref i), b = Gruppo(s, ref i);
                                el.Append("<m:f><m:num>").Append(OmmlGruppo(a)).Append("</m:num><m:den>").Append(OmmlGruppo(b)).Append("</m:den></m:f>");
                                break;
                            }
                        case "sqrt":
                            el.Append("<m:rad><m:radPr><m:degHide m:val=\"1\"/></m:radPr><m:deg/><m:e>").Append(OmmlGruppo(Gruppo(s, ref i))).Append("</m:e></m:rad>");
                            break;
                        case "p": case "b": case "a":
                            {
                                string ap = cmd == "p" ? "(" : (cmd == "b" ? "[" : "|"), ch = cmd == "p" ? ")" : (cmd == "b" ? "]" : "|");
                                el.Append("<m:d><m:dPr><m:begChr m:val=\"").Append(ap).Append("\"/><m:endChr m:val=\"").Append(ch).Append("\"/></m:dPr><m:e>")
                                  .Append(OmmlGruppo(Gruppo(s, ref i))).Append("</m:e></m:d>");
                                break;
                            }
                        case "t": Run(el, Gruppo(s, ref i), true); break;
                        case "h":
                            el.Append("<m:borderBox><m:e>").Append(OmmlGruppo(Gruppo(s, ref i))).Append("</m:e></m:borderBox>");
                            break;
                        case ",": case ";": case "quad": Run(el, " ", true); break;
                        default: Run(el, cmd, true); break;
                    }
                }
                else if (c == '{') el.Append(OmmlGruppo(Gruppo(s, ref i)));
                else if (char.IsLetter(c) && c < 'ʰ')
                {
                    int j = i;
                    while (j < s.Length && char.IsLetter(s[j]) && s[j] < 'ʰ') j++;
                    string w = s.Substring(i, j - i); i = j;
                    Run(el, w, w.Length > 1 || script);
                }
                else if (char.IsDigit(c))
                {
                    int j = i;
                    while (j < s.Length && (char.IsDigit(s[j]) || ((s[j] == ',' || s[j] == '.') && j + 1 < s.Length && char.IsDigit(s[j + 1])))) j++;
                    Run(el, s.Substring(i, j - i), true); i = j;
                }
                else { i++; Run(el, c == '-' ? "−" : c.ToString(), true); }
                // pedici e apici
                string sub = null, sup = null;
                while (i < s.Length && (s[i] == '_' || s[i] == '^'))
                {
                    bool basso = s[i] == '_';
                    i++;
                    StringBuilder sg = new StringBuilder();
                    int k = 0;
                    string gtxt = Gruppo(s, ref i);
                    OmmlRiga(gtxt, ref k, sg, true);
                    if (basso) sub = sg.ToString(); else sup = sg.ToString();
                }
                if (sub != null && sup != null) sb.Append("<m:sSubSup><m:e>").Append(el).Append("</m:e><m:sub>").Append(sub).Append("</m:sub><m:sup>").Append(sup).Append("</m:sup></m:sSubSup>");
                else if (sub != null) sb.Append("<m:sSub><m:e>").Append(el).Append("</m:e><m:sub>").Append(sub).Append("</m:sub></m:sSub>");
                else if (sup != null) sb.Append("<m:sSup><m:e>").Append(el).Append("</m:e><m:sup>").Append(sup).Append("</m:sup></m:sSup>");
                else sb.Append(el);
            }
        }

        // Testo semplice equivalente (per copiare negli appunti)
        public static string Semplice(string s)
        {
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < s.Length)
            {
                char c = s[i];
                if (c == '\\')
                {
                    int j = i + 1;
                    while (j < s.Length && char.IsLetter(s[j])) j++;
                    string cmd = s.Substring(i + 1, j - i - 1);
                    if (cmd.Length == 0 && j < s.Length) { cmd = s[j].ToString(); j++; }
                    i = j;
                    switch (cmd)
                    {
                        case "frac": { string a = Gruppo(s, ref i), b = Gruppo(s, ref i); sb.Append("(" + Semplice(a) + ")/(" + Semplice(b) + ")"); break; }
                        case "sqrt": sb.Append("√(" + Semplice(Gruppo(s, ref i)) + ")"); break;
                        case "p": sb.Append("(" + Semplice(Gruppo(s, ref i)) + ")"); break;
                        case "b": sb.Append("[" + Semplice(Gruppo(s, ref i)) + "]"); break;
                        case "a": sb.Append("|" + Semplice(Gruppo(s, ref i)) + "|"); break;
                        case "t": case "h": sb.Append(Semplice(Gruppo(s, ref i))); break;
                        case ",": case ";": case "quad": sb.Append(" "); break;
                        default: sb.Append(cmd); break;
                    }
                }
                else if (c == '_' || c == '^')
                {
                    i++;
                    string gtxt = Gruppo(s, ref i);
                    if (c == '^') sb.Append("^" + (gtxt.Length > 1 ? "(" + Semplice(gtxt) + ")" : gtxt));
                    else sb.Append(Semplice(gtxt));
                }
                else if (c == '{') sb.Append(Semplice(Gruppo(s, ref i)));
                else { sb.Append(c); i++; }
            }
            return sb.ToString();
        }
    }

    enum DocTipo { Titolo, Sez, Sotto, Par, Punto, Formula, Tabella, Box, Didascalia, Fonte, Figura, Spazio, Linea, Colonne, Locatore }

    class DocBlocco
    {
        public DocTipo Tipo;
        public string Testo = "";
        public string Num = "";            // numero dell'equazione, es. (4.7.1)
        public string Valori;              // formula: seconda riga con i valori sostituiti
        public string Risultato;           // formula: risultato evidenziato
        public List<string[]> Righe;       // tabella: la prima riga è l'intestazione
        public bool[] Destra;              // tabella: colonne allineate a destra
        public int Stile;                  // box: 0 blu, 1 verde, 2 giallo
        public Func<int, int, Bitmap> ImmagineWH;   // figura larga (Stile 1): disegnata alla misura della colonna
        public Bitmap Img;
        public List<DocBlocco> Sx, Dx;     // due colonne affiancate
        public float Quota = 0.5f;         // larghezza della colonna di sinistra (frazione)
        public bool[] Centro;              // tabella: colonne centrate
        public HashSet<int> Evidenzia;     // tabella: righe evidenziate in verde
        public bool Nuovo;                 // titolo con l'etichetta "nuovo" nell'indice
        // posizione calcolata
        public float Y, H; public int Pagina;
        public object Cache; public float CacheW = -1;

        public static DocBlocco P(DocTipo t, string testo) { DocBlocco b = new DocBlocco(); b.Tipo = t; b.Testo = testo ?? ""; return b; }
    }

    // Una parola (o un pezzo di testo) già misurata per l'impaginazione
    class DocPezzo { public string T; public Font F; public MBox M; public float W, A, D; public string Url; public bool Spazio; public Color C = Color.Empty; }
    class DocLinea { public List<DocPezzo> Pezzi = new List<DocPezzo>(); public float W, A, D; public bool Gdi; }

    class DocView : Panel
    {
        public List<DocBlocco> Blocchi = new List<DocBlocco>();
        public bool Pagine;                // stile Word: pagine bianche su fondo grigio, con intestazione
        public string Intestazione = "";
        public float Zoom = 1f, Scala = 1f;
        public bool Rtl;
        public DocBlocco Lampeggia;
        float altezza, larghezzaTesto, xTesto;
        int nPagine = 1;
        readonly List<KeyValuePair<RectangleF, object>> link = new List<KeyValuePair<RectangleF, object>>();
        Font fP, fB, fI, fBI, fT, fS, fH3, fC, fF, fTh;
        float pxBase;

        public DocView()
        {
            DoubleBuffered = true;
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.UserPaint, true);
            AutoScroll = true;
            BackColor = Color.White;
        }

        float Px(float v) { return v * Scala * Zoom; }
        public float PageW { get { return Px(794); } }
        public float PageH { get { return Px(1123); } }
        float Margine { get { return Pagine ? Px(84) : Px(34); } }

        void Fonts()
        {
            float b = Px(15.5f);
            if (fP != null && Math.Abs(pxBase - b) < 0.01f) return;
            pxBase = b;
            foreach (Font f in new Font[] { fP, fB, fI, fBI, fT, fS, fH3, fC, fF, fTh }) if (f != null) f.Dispose();
            string fam = Lang.FontUi;
            fP = new Font(fam, b, FontStyle.Regular, GraphicsUnit.Pixel);
            fB = new Font(fam, b, FontStyle.Bold, GraphicsUnit.Pixel);
            fI = new Font(fam, b, FontStyle.Italic, GraphicsUnit.Pixel);
            fBI = new Font(fam, b, FontStyle.Bold | FontStyle.Italic, GraphicsUnit.Pixel);
            fT = new Font(fam, Px(Pagine ? 27 : 24), FontStyle.Bold, GraphicsUnit.Pixel);
            fS = new Font(fam, Px(23), FontStyle.Bold, GraphicsUnit.Pixel);          // sezione: grassetto blu scuro con la riga sotto
            fH3 = new Font(fam, Px(17), FontStyle.Regular, GraphicsUnit.Pixel);      // sottosezione: azzurro, non grassetto
            fC = new Font(fam, Px(13), FontStyle.Italic, GraphicsUnit.Pixel);
            fF = new Font(fam, Px(13), FontStyle.Regular, GraphicsUnit.Pixel);
            fTh = new Font(fam, Px(14), FontStyle.Bold, GraphicsUnit.Pixel);
        }

        public void Aggiorna()
        {
            foreach (DocBlocco b in Blocchi) b.CacheW = -1;
            Impagina();
            Invalidate();
        }

        protected override void OnResize(EventArgs e)
        {
            base.OnResize(e);
            Impagina();
        }

        static readonly Color Blu = Color.FromArgb(25, 65, 127), BluSez = Color.FromArgb(46, 116, 181), Testata = Color.FromArgb(68, 114, 196);

        // ---------------- impaginazione
        void Impagina()
        {
            if (Width < 50) return;
            Fonts();
            Graphics g = Formula.Misura;
            float m = Margine;
            float wPag = Pagine ? PageW : Math.Max(Px(300), ClientSize.Width - SystemInformation.VerticalScrollBarWidth);
            if (!Pagine) wPag = Math.Min(wPag, Px(1180));
            larghezzaTesto = wPag - 2 * m;
            float yTop = Pagine ? Px(24) : 0;
            float y = yTop + m * (Pagine ? 1.15f : 0.6f);
            int pag = 0;
            for (int k = 0; k < Blocchi.Count; k++)
            {
                DocBlocco b = Blocchi[k];
                float h = Altezza(g, b, larghezzaTesto);
                float sopra = SpazioSopra(b);
                if (Pagine)
                {
                    float fondo = yTop + pag * (PageH + Px(24)) + PageH - m * 0.8f;
                    bool tieni = (b.Tipo == DocTipo.Sez || b.Tipo == DocTipo.Sotto || b.Tipo == DocTipo.Titolo);
                    float serve = sopra + h + (tieni && k + 1 < Blocchi.Count ? Math.Min(Px(80), Altezza(g, Blocchi[k + 1], larghezzaTesto)) : 0);
                    if (y + serve > fondo && y > yTop + pag * (PageH + Px(24)) + m * 1.3f)
                    {
                        pag++;
                        y = yTop + pag * (PageH + Px(24)) + m * 1.15f;
                        sopra = 0;
                    }
                }
                y += sopra;
                b.Y = y; b.H = h; b.Pagina = pag;
                y += h;
            }
            nPagine = pag + 1;
            altezza = Pagine ? yTop + nPagine * (PageH + Px(24)) : y + m;
            float wTot = Pagine ? PageW + Px(48) : wPag;
            xTesto = Pagine ? Math.Max(Px(24), (ClientSize.Width - PageW) / 2f) + m : m;
            AutoScrollMinSize = new Size((int)wTot, (int)altezza);
        }

        float SpazioSopra(DocBlocco b)
        {
            switch (b.Tipo)
            {
                case DocTipo.Titolo: return Px(6);
                case DocTipo.Sez: return Px(22);
                case DocTipo.Sotto: return Px(14);
                case DocTipo.Formula: return Px(4);
                case DocTipo.Tabella: case DocTipo.Box: case DocTipo.Figura: case DocTipo.Colonne: return Px(8);
                case DocTipo.Locatore: return Px(6);
                case DocTipo.Didascalia: return Px(2);
                case DocTipo.Fonte: return Px(1);
                default: return Px(6);
            }
        }

        Font FontDi(DocBlocco b)
        {
            switch (b.Tipo)
            {
                case DocTipo.Titolo: return fT;
                case DocTipo.Sez: return fS;
                case DocTipo.Sotto: return b.Stile == 1 ? fS : fH3;
                case DocTipo.Didascalia: return b.Stile == 1 ? fF : fC;
                case DocTipo.Fonte: return fF;
                default: return fP;
            }
        }

        float Altezza(Graphics g, DocBlocco b, float w)
        {
            switch (b.Tipo)
            {
                case DocTipo.Spazio: return Px(10);
                case DocTipo.Linea: return Px(10);
                case DocTipo.Formula: return FormulaH(b, w);
                case DocTipo.Tabella: return TabellaH(g, b, w);
                case DocTipo.Figura:
                    if (b.Stile == 1) return w * 0.58f + TestoH(g, DidascaliaDi(b), fC, w) + Px(8);
                    return Px(190);
                case DocTipo.Colonne: return ColonneH(g, b, w);
                case DocTipo.Locatore: return Px(46);
                case DocTipo.Box:
                    if (b.Stile == 3) return Math.Max(Px(44), TestoH(g, b, FontDi(b), w - Px(34) - Px(46))) + Px(20);
                    if (b.Testo.StartsWith("✉ ")) return Math.Max(Px(40), TestoH(g, b, FontDi(b), w - Px(34) - Px(46))) + Px(20);
                    return TestoH(g, b, FontDi(b), w - Px(34)) + Px(20);
                case DocTipo.Punto:
                    return TestoH(g, b, fP, w - Px(22));
                case DocTipo.Titolo:
                    return TestoH(g, b, fT, w) + Px(12);
                case DocTipo.Sez:
                    return TestoH(g, b, fS, w) + Px(12);
                case DocTipo.Sotto:
                    return b.Stile == 1 ? TestoH(g, b, fS, w) + Px(12) : TestoH(g, b, fH3, w);
                case DocTipo.Fonte:
                    return TestoH(g, b, fF, w) + (b.Stile == 1 ? Px(10) : 0);
                default:
                    return TestoH(g, b, FontDi(b), w);
            }
        }

        DocBlocco DidascaliaDi(DocBlocco b)
        {
            if (!(b.Cache is DocBlocco)) b.Cache = DocBlocco.P(DocTipo.Didascalia, b.Testo);
            return (DocBlocco)b.Cache;
        }

        // ---- due colonne affiancate: l'altezza è quella della colonna più alta
        float LargSx(DocBlocco b, float w) { return (w - Px(22)) * b.Quota; }
        float LargDx(DocBlocco b, float w) { return (w - Px(22)) * (1 - b.Quota); }

        float ColonneH(Graphics g, DocBlocco b, float w)
        {
            float h1 = AltezzaLista(g, b.Sx, LargSx(b, w)), h2 = AltezzaLista(g, b.Dx, LargDx(b, w));
            return Math.Max(h1, h2);
        }

        float AltezzaLista(Graphics g, List<DocBlocco> l, float w)
        {
            float y = 0;
            if (l == null) return 0;
            for (int i = 0; i < l.Count; i++)
            {
                if (i > 0) y += SpazioSopra(l[i]);
                l[i].H = Altezza(g, l[i], w);
                y += l[i].H;
            }
            return y;
        }

        void DisegnaLista(Graphics g, List<DocBlocco> l, float x, float y, float w)
        {
            if (l == null) return;
            Graphics gm = Formula.Misura;
            for (int i = 0; i < l.Count; i++)
            {
                if (i > 0) y += SpazioSopra(l[i]);
                float h = Altezza(gm, l[i], w);
                DisegnaBlocco(g, l[i], x, y, w, h);
                y += h;
            }
        }

        // ---- locator d'esempio: coppie su fondi di colori diversi
        void DisegnaLocatore(Graphics g, DocBlocco b, float x, float y)
        {
            Color[] fondi = { Color.FromArgb(219, 234, 254), Color.FromArgb(220, 252, 231), Color.FromArgb(254, 243, 199), Color.FromArgb(237, 233, 254), Color.FromArgb(252, 231, 243), Color.FromArgb(204, 251, 241), Color.FromArgb(255, 237, 213) };
            string[] coppie = b.Testo.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            using (Font f = new Font("Consolas", Px(26), FontStyle.Regular, GraphicsUnit.Pixel))
            using (Brush br = new SolidBrush(Color.FromArgb(29, 36, 51)))
            {
                float xx = x + Px(30);
                for (int i = 0; i < coppie.Length; i++)
                {
                    SizeF sz = g.MeasureString(coppie[i], f, 1000, Formula.Sf);
                    RectangleF r = new RectangleF(xx, y + Px(4), sz.Width + Px(8), Px(38));
                    using (Brush bf = new SolidBrush(fondi[i % fondi.Length])) g.FillRectangle(bf, r);
                    g.DrawString(coppie[i], f, br, r.X + Px(4), r.Y + (r.Height - f.GetHeight(g)) / 2, Formula.Sf);
                    xx = r.Right + Px(4);
                }
            }
        }

        // ---- testo: impaginazione con grassetto **..**, corsivo *..*, formule in linea §..§ e indirizzi web
        bool Semplice(string t) { return t.IndexOf("**") < 0 && t.IndexOf('*') < 0 && t.IndexOf('§') < 0 && t.IndexOf("http") < 0 && t.IndexOf('@') < 0 && t.IndexOf(":}") < 0 && t.IndexOf('{') < 0; }

        float TestoH(Graphics g, DocBlocco b, Font f, float w)
        {
            List<DocLinea> ll = Linee(g, b, f, w);
            float h = 0;
            foreach (DocLinea l in ll) h += l.A + l.D;
            return h;
        }

        List<DocLinea> Linee(Graphics g, DocBlocco b, Font f, float w)
        {
            if (b.CacheW == w && b.Cache is List<DocLinea>) return (List<DocLinea>)b.Cache;
            List<DocLinea> ll = new List<DocLinea>();
            string t = b.Testo ?? "";
            float lh = f.GetHeight(g) * 1.18f;
            if (Rtl || Semplice(t))
            {
                // testo semplice: lo spezza GDI+ (vale per tutte le scritture, anche senza spazi o da destra a sinistra)
                using (StringFormat sf = new StringFormat())
                {
                    if (Rtl) sf.FormatFlags |= StringFormatFlags.DirectionRightToLeft;
                    string tt = Rtl ? t.Replace("**", "").Replace("§", "") : t;
                    SizeF sz = g.MeasureString(tt, f, new SizeF(w, 100000), sf);
                    DocLinea l = new DocLinea();
                    l.Gdi = true;
                    DocPezzo p = new DocPezzo(); p.T = tt; p.F = f; p.W = w;
                    l.Pezzi.Add(p);
                    int righe = Math.Max(1, (int)Math.Round(sz.Height / f.GetHeight(g)));
                    l.A = righe * lh * 0.8f; l.D = righe * lh * 0.2f;
                    ll.Add(l);
                }
                b.Cache = ll; b.CacheW = w;
                return ll;
            }
            List<DocPezzo> pezzi = Pezzi(g, t, f);
            DocLinea cur = new DocLinea();
            foreach (DocPezzo p in pezzi)
            {
                if (cur.W + p.W > w && cur.Pezzi.Count > 0 && !p.Spazio)
                {
                    Chiudi(cur, lh); ll.Add(cur); cur = new DocLinea();
                }
                if (cur.Pezzi.Count == 0 && p.Spazio) continue;
                cur.Pezzi.Add(p); cur.W += p.W;
            }
            if (cur.Pezzi.Count > 0) { Chiudi(cur, lh); ll.Add(cur); }
            b.Cache = ll; b.CacheW = w;
            return ll;
        }

        static void Chiudi(DocLinea l, float lh)
        {
            float a = lh * 0.78f, d = lh * 0.22f;
            foreach (DocPezzo p in l.Pezzi) { a = Math.Max(a, p.A + lh * 0.12f); d = Math.Max(d, p.D + lh * 0.06f); }
            l.A = a; l.D = d;
        }

        List<DocPezzo> Pezzi(Graphics g, string t, Font f)
        {
            List<DocPezzo> r = new List<DocPezzo>();
            bool bold = false, ital = false;
            StringBuilder parola = new StringBuilder();
            Font fb = f.Bold ? f : (f == fP ? fB : new Font(f, FontStyle.Bold));
            Action<string> Emetti = null;
            Func<Font> Cor = () => (bold && ital) ? fBI : (bold ? (f == fP ? fB : fb) : (ital ? (f == fP ? fI : f) : f));
            Color colore = Color.Empty;
            Emetti = (s) =>
            {
                if (s.Length == 0) return;
                DocPezzo p = new DocPezzo();
                p.T = s; p.F = Cor();
                p.C = colore;
                p.Spazio = s == " ";
                if (s.StartsWith("http")) p.Url = s.TrimEnd('.', ',', ';', ')');
                else if (s.IndexOf('@') > 0 && s.IndexOf('.') > s.IndexOf('@')) p.Url = "mailto:" + s.TrimEnd('.', ',', ';', ')');
                p.W = g.MeasureString(s, p.F, 10000, Formula.Sf).Width;
                float em = p.F.Size / p.F.FontFamily.GetEmHeight(p.F.Style);
                p.A = p.F.FontFamily.GetCellAscent(p.F.Style) * em;
                p.D = p.F.FontFamily.GetCellDescent(p.F.Style) * em;
                r.Add(p);
            };
            Action Svuota = () => { Emetti(parola.ToString()); parola.Length = 0; };
            int i = 0;
            while (i < t.Length)
            {
                char c = t[i];
                if (c == '*' && i + 1 < t.Length && t[i + 1] == '*') { Svuota(); bold = !bold; i += 2; continue; }
                if (c == '*' && (ital || AsteriscoChiuso(t, i))) { Svuota(); ital = !ital; i++; continue; }
                // colori: {r:testo} rosso, {g:testo} verde, {o:testo} arancio, {b:testo} blu
                if (c == '{' && i + 2 < t.Length && t[i + 2] == ':' && "rgob".IndexOf(t[i + 1]) >= 0 && t.IndexOf('}', i) > 0)
                {
                    Svuota();
                    char k = t[i + 1];
                    colore = k == 'r' ? Color.FromArgb(192, 57, 43) : (k == 'g' ? Color.FromArgb(23, 128, 61) : (k == 'o' ? Color.FromArgb(217, 119, 6) : Color.FromArgb(31, 111, 209)));
                    i += 3;
                    continue;
                }
                if (c == '}' && colore != Color.Empty) { Svuota(); colore = Color.Empty; i++; continue; }
                if (c == '§')
                {
                    Svuota();
                    int j = t.IndexOf('§', i + 1);
                    if (j < 0) j = t.Length;
                    MBox m = Formula.Analizza(t.Substring(i + 1, j - i - 1), f.Size * 1.06f);
                    DocPezzo p = new DocPezzo(); p.M = m; p.W = m.W + f.Size * 0.08f; p.A = m.A; p.D = m.D;
                    r.Add(p);
                    i = j + 1;
                    continue;
                }
                if (c == ' ' || c == '\n') { Svuota(); Emetti(" "); i++; continue; }
                // le scritture senza spazi (cinese, giapponese) vanno a capo tra un carattere e l'altro
                if ((c >= '⺀' && c <= '鿿') || (c >= '＀' && c <= '￯'))
                {
                    parola.Append(c); i++;
                    if (i < t.Length && "。、，．：；！？）」』".IndexOf(t[i]) >= 0) { parola.Append(t[i]); i++; }
                    Svuota();
                    continue;
                }
                parola.Append(c); i++;
            }
            Svuota();
            return r;
        }

        // un asterisco singolo apre il corsivo solo se più avanti c'è quello che lo chiude (gli altri sono richiami)
        static bool AsteriscoChiuso(string t, int i)
        {
            for (int j = i + 1; j < t.Length; j++)
            {
                if (t[j] != '*') continue;
                bool doppio = (j + 1 < t.Length && t[j + 1] == '*') || t[j - 1] == '*';
                if (!doppio) return true;
            }
            return false;
        }

        void DisegnaTesto(Graphics g, DocBlocco b, Font f, Color col, float x, float y, float w) { DisegnaTesto(g, b, f, col, x, y, w, 0); }

        // allinea: 0 sinistra, 1 destra, 2 centro
        void DisegnaTesto(Graphics g, DocBlocco b, Font f, Color col, float x, float y, float w, int allinea)
        {
            List<DocLinea> ll = Linee(g, b, f, w);
            if (ll.Count == 1 && ll[0].Gdi)
            {
                DocPezzo p = ll[0].Pezzi[0];
                using (StringFormat sf = new StringFormat())
                using (Brush br = new SolidBrush(col))
                {
                    if (Rtl) sf.FormatFlags |= StringFormatFlags.DirectionRightToLeft;
                    g.DrawString(p.T, p.F, br, new RectangleF(x, y, w + 2, ll[0].A + ll[0].D + 4), sf);
                }
                return;
            }
            foreach (DocLinea l in ll)
            {
                float xx = x + (allinea == 1 ? Math.Max(0, w - l.W) : (allinea == 2 ? Math.Max(0, (w - l.W) / 2) : 0)), base_ = y + l.A;
                foreach (DocPezzo p in l.Pezzi)
                {
                    if (p.M != null) p.M.Draw(g, xx, base_, col);
                    else
                    {
                        Color cc = p.Url != null ? Color.FromArgb(31, 111, 209) : (p.C != Color.Empty ? p.C : col);
                        using (Brush br = new SolidBrush(cc)) g.DrawString(p.T, p.F, br, xx, base_ - p.A, Formula.Sf);
                        if (p.Url != null)
                        {
                            using (Pen pn = new Pen(cc)) g.DrawLine(pn, xx, base_ + Px(2), xx + p.W, base_ + Px(2));
                            link.Add(new KeyValuePair<RectangleF, object>(new RectangleF(xx, base_ - p.A, p.W, p.A + p.D), p.Url));
                        }
                    }
                    xx += p.W;
                }
                y += l.A + l.D;
            }
        }

        // ---- formule
        class FormulaCache { public MBox L1, L2; public float H; }

        FormulaCache Formule(DocBlocco b)
        {
            if (b.Cache is FormulaCache && b.CacheW == larghezzaTesto) return (FormulaCache)b.Cache;
            float px = Px(19);
            FormulaCache fc = new FormulaCache();
            string l1 = b.Testo;
            if (b.Valori == null && b.Risultato != null) l1 += " = \\h{" + b.Risultato + "}";
            fc.L1 = Formula.Analizza(l1, px);
            if (b.Valori != null)
                fc.L2 = Formula.Analizza("= " + b.Valori + (b.Risultato != null ? " = \\h{" + b.Risultato + "}" : ""), px);
            fc.H = fc.L1.A + fc.L1.D + Px(10) + (fc.L2 != null ? fc.L2.A + fc.L2.D + Px(8) : 0);
            b.Cache = fc; b.CacheW = larghezzaTesto;
            return fc;
        }

        float FormulaH(DocBlocco b, float w) { return Formule(b).H; }

        void DisegnaFormula(Graphics g, DocBlocco b, float x, float y, float w)
        {
            FormulaCache fc = Formule(b);
            float xf = x + Px(26);
            float y1 = y + Px(5) + fc.L1.A;
            fc.L1.Draw(g, xf, y1, Color.FromArgb(20, 20, 20));
            if (b.Num.Length > 0)
                using (Brush br = new SolidBrush(Color.FromArgb(110, 110, 110)))
                using (StringFormat sf = new StringFormat())
                {
                    sf.Alignment = StringAlignment.Far;
                    g.DrawString(b.Num, fF, br, new RectangleF(x, y1 - fF.Size, w, fF.Size * 2), sf);
                }
            if (fc.L2 != null)
            {
                // la seconda riga parte allineata al segno "=" della prima, se c'è
                float xs = xf;
                MRiga r1 = fc.L1 as MRiga;
                if (r1 != null)
                {
                    float acc = 0;
                    foreach (MBox m in r1.Figli)
                    {
                        MTesto mt = m as MTesto;
                        if (mt != null && mt.T == "=") { xs = xf + acc - Px(5); break; }
                        acc += m.W;
                    }
                }
                if (xs + fc.L2.W > x + w) xs = Math.Max(xf, x + w - fc.L2.W);
                fc.L2.Draw(g, xs, y1 + fc.L1.D + Px(8) + fc.L2.A, Color.FromArgb(20, 20, 20));
            }
        }

        // ---- tabelle
        class TabCache { public float[] Cw; public float[] Rh; public List<DocBlocco[]> Celle; }

        TabCache Tab(Graphics g, DocBlocco b, float w)
        {
            if (b.Cache is TabCache && b.CacheW == w) return (TabCache)b.Cache;
            TabCache tc = new TabCache();
            int nc = 0;
            foreach (string[] r in b.Righe) nc = Math.Max(nc, r.Length);
            float pad = Px(8);
            float[] nat = new float[nc];
            tc.Celle = new List<DocBlocco[]>();
            for (int ri = 0; ri < b.Righe.Count; ri++)
            {
                DocBlocco[] cel = new DocBlocco[nc];
                for (int c = 0; c < nc; c++)
                {
                    cel[c] = DocBlocco.P(DocTipo.Par, c < b.Righe[ri].Length ? b.Righe[ri][c] : "");
                    Font f = ri == 0 ? fTh : fF;
                    float wn = 0, wb = 0;
                    string tx = TestoBarra(cel[c].Testo, out wb);
                    wb = wb >= 0 ? Px(130) : 0;
                    foreach (DocPezzo p in Pezzi(g, tx, f)) wn += p.W;
                    nat[c] = Math.Max(nat[c], Math.Min(wn, Px(420)) + 2 * pad + wb);
                }
                tc.Celle.Add(cel);
            }
            float tot = 0;
            foreach (float v in nat) tot += v;
            tc.Cw = new float[nc];
            for (int c = 0; c < nc; c++) tc.Cw[c] = tot <= w ? nat[c] * w / Math.Max(1, tot) : Math.Max(Px(40), nat[c] * w / tot);
            tc.Rh = new float[b.Righe.Count];
            for (int ri = 0; ri < b.Righe.Count; ri++)
            {
                float h = 0;
                for (int c = 0; c < nc; c++)
                {
                    float wb;
                    string tx = TestoBarra(tc.Celle[ri][c].Testo, out wb);
                    DocBlocco misura = wb >= 0 ? DocBlocco.P(DocTipo.Par, tx) : tc.Celle[ri][c];
                    h = Math.Max(h, TestoH(g, misura, ri == 0 ? fTh : fF, tc.Cw[c] - 2 * pad - (wb >= 0 ? Px(130) : 0)));
                }
                tc.Rh[ri] = h + Px(8);
            }
            b.Cache = tc; b.CacheW = w;
            return tc;
        }

        // "%bar:valore:massimo:colore%testo" -> testo; larghezza >= 0 se la cella ha la barra (-1 altrimenti)
        static string TestoBarra(string t, out float wb)
        {
            wb = -1;
            if (t == null || !t.StartsWith("%bar:")) return t;
            int j = t.IndexOf('%', 5);
            if (j < 0) return t;
            wb = 0;
            return t.Substring(j + 1).Trim();
        }

        static void LeggiBarra(string t, out float val, out float max, out Color c)
        {
            val = 0; max = 1; c = Color.FromArgb(31, 111, 209);
            int j = t.IndexOf('%', 5);
            string[] p = t.Substring(5, j - 5).Split(':');
            if (p.Length > 0) float.TryParse(p[0], NumberStyles.Float, CultureInfo.InvariantCulture, out val);
            if (p.Length > 1) float.TryParse(p[1], NumberStyles.Float, CultureInfo.InvariantCulture, out max);
            if (p.Length > 2)
                switch (p[2])
                {
                    case "r": c = Color.FromArgb(214, 48, 49); break;
                    case "o": c = Color.FromArgb(230, 145, 20); break;
                    case "y": c = Color.FromArgb(225, 175, 20); break;
                    case "g": c = Color.FromArgb(23, 128, 61); break;
                }
        }

        float TabellaH(Graphics g, DocBlocco b, float w)
        {
            TabCache tc = Tab(g, b, w);
            float h = 0;
            foreach (float r in tc.Rh) h += r;
            return h + Px(2);
        }

        void DisegnaTabella(Graphics g, DocBlocco b, float x, float y, float w)
        {
            TabCache tc = Tab(g, b, w);
            float pad = Px(8);
            for (int ri = 0; ri < tc.Celle.Count; ri++)
            {
                float h = tc.Rh[ri];
                Color fondo = ri == 0 ? Testata : (b.Evidenzia != null && b.Evidenzia.Contains(ri) ? Color.FromArgb(222, 244, 229) : (ri % 2 == 0 ? Color.FromArgb(238, 243, 251) : Color.White));
                using (Brush br = new SolidBrush(fondo)) g.FillRectangle(br, x, y, w, h);
                using (Pen pn = new Pen(Color.FromArgb(217, 226, 243))) g.DrawLine(pn, x, y + h, x + w, y + h);
                float xx = x;
                for (int c = 0; c < tc.Cw.Length; c++)
                {
                    DocBlocco cel = tc.Celle[ri][c];
                    Font f = ri == 0 ? fTh : fF;
                    float cw = tc.Cw[c] - 2 * pad;
                    bool destra = b.Destra != null && c < b.Destra.Length && b.Destra[c];
                    bool centro = b.Centro != null && c < b.Centro.Length && b.Centro[c];
                    Color ct = ri == 0 ? Color.White : Color.FromArgb(29, 36, 51);
                    float wb;
                    string tx = TestoBarra(cel.Testo, out wb);
                    if (wb >= 0 && ri > 0)
                    {
                        // cella con la barra colorata: barra proporzionale e poi il valore
                        float val, max; Color cb;
                        LeggiBarra(cel.Testo, out val, out max, out cb);
                        float wTesto = 0;
                        DocBlocco ct2 = DocBlocco.P(DocTipo.Par, tx);
                        foreach (DocPezzo pz in Pezzi(Formula.Misura, tx, f)) wTesto += pz.W;
                        float wMax = Math.Max(Px(10), cw - wTesto - Px(8));
                        float yb = y + h / 2 - Px(6);
                        float lb = val <= 0 ? Px(3) : Math.Max(Px(6), wMax * Math.Min(1f, val / Math.Max(0.001f, max)));
                        using (GraphicsPath gp = new GraphicsPath())
                        {
                            float rr = Math.Min(Px(6), lb / 2);
                            RectangleF rb = new RectangleF(xx + pad, yb, lb, Px(12));
                            if (rr > 0.5f)
                            {
                                gp.AddArc(rb.X, rb.Y, 2 * rr, rb.Height, 90, 180);
                                gp.AddArc(rb.Right - 2 * rr, rb.Y, 2 * rr, rb.Height, 270, 180);
                                gp.CloseFigure();
                                using (Brush bb = new SolidBrush(cb)) g.FillPath(bb, gp);
                            }
                            else using (Brush bb = new SolidBrush(cb)) g.FillRectangle(bb, rb);
                        }
                        DisegnaTesto(g, ct2, f, ct, xx + pad + lb + Px(6), y + Px(4), cw - lb - Px(6));
                    }
                    else if (!Rtl && (destra || centro) && Semplice(cel.Testo))
                    {
                        using (StringFormat sf = new StringFormat())
                        using (Brush br = new SolidBrush(ct))
                        {
                            sf.Alignment = destra ? StringAlignment.Far : StringAlignment.Center;
                            g.DrawString(cel.Testo, f, br, new RectangleF(xx + pad, y + Px(4), cw, h), sf);
                        }
                    }
                    else DisegnaTesto(g, cel, f, ct, xx + pad, y + Px(4), cw, Rtl ? 0 : (destra ? 1 : (centro ? 2 : 0)));
                    xx += tc.Cw[c];
                }
                y += h;
            }
        }

        // ---------------- disegno
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAlias;   // come nella misura: spazi regolari tra le parole
            g.Clear(Pagine ? Color.FromArgb(142, 150, 164) : Color.White);
            g.TranslateTransform(AutoScrollPosition.X, AutoScrollPosition.Y);
            link.Clear();
            float vis0 = -AutoScrollPosition.Y, vis1 = vis0 + ClientSize.Height;
            float m = Margine;
            if (Pagine)
            {
                float yTop = Px(24), xP = xTesto - m;
                for (int p = 0; p < nPagine; p++)
                {
                    float yp = yTop + p * (PageH + Px(24));
                    if (yp > vis1 || yp + PageH < vis0) continue;
                    using (Brush sh = new SolidBrush(Color.FromArgb(60, 0, 0, 0))) g.FillRectangle(sh, xP + Px(3), yp + Px(4), PageW, PageH);
                    g.FillRectangle(Brushes.White, xP, yp, PageW, PageH);
                    using (Brush br = new SolidBrush(Color.FromArgb(120, 120, 120)))
                    using (StringFormat sf = new StringFormat())
                    {
                        g.DrawString(Intestazione, fF, br, xP + m, yp + m * 0.45f);
                        sf.Alignment = StringAlignment.Far;
                        g.DrawString(string.Format(Lang.Cultura, Lang.T("Pagina {0} di {1}"), p + 1, nPagine), fF, br, new RectangleF(xP, yp + m * 0.45f, PageW - m, Px(20)), sf);
                    }
                    using (Pen pn = new Pen(Color.FromArgb(200, 200, 200))) g.DrawLine(pn, xP + m, yp + m * 0.45f + Px(20), xP + PageW - m, yp + m * 0.45f + Px(20));
                }
            }
            float x = xTesto, w = larghezzaTesto;
            foreach (DocBlocco b in Blocchi)
            {
                if (b.Y > vis1 || b.Y + b.H < vis0) continue;
                if (b == Lampeggia)
                    using (Brush br = new SolidBrush(Color.FromArgb(255, 246, 196))) g.FillRectangle(br, x - Px(10), b.Y - Px(2), w + Px(20), b.H + Px(4));
                DisegnaBlocco(g, b, x, b.Y, w, b.H);
            }
        }

        void DisegnaBlocco(Graphics g, DocBlocco b, float x, float y, float w, float h)
        {
            Color testo = Color.FromArgb(29, 36, 51);
            switch (b.Tipo)
            {
                case DocTipo.Titolo:
                    DisegnaTesto(g, b, fT, Blu, x, y, w);
                    using (Pen pn = new Pen(Blu, Px(2))) g.DrawLine(pn, x, y + h - Px(5), x + w, y + h - Px(5));
                    break;
                case DocTipo.Sez:
                    DisegnaTesto(g, b, fS, Blu, x, y, w);
                    using (Pen pn = new Pen(Blu, Px(2))) g.DrawLine(pn, x, y + h - Px(5), x + w, y + h - Px(5));
                    break;
                case DocTipo.Sotto:
                    if (b.Stile == 1)
                    {
                        DisegnaTesto(g, b, fS, Blu, x, y, w);
                        using (Pen pn = new Pen(Blu, Px(2))) g.DrawLine(pn, x, y + h - Px(5), x + w, y + h - Px(5));
                    }
                    else DisegnaTesto(g, b, fH3, BluSez, x, y, w);
                    break;
                case DocTipo.Par: DisegnaTesto(g, b, fP, testo, x, y, w); break;
                case DocTipo.Punto:
                    using (Brush br = new SolidBrush(BluSez)) g.FillEllipse(br, x + Px(6), y + fP.Size * 0.55f, Px(6), Px(6));
                    DisegnaTesto(g, b, fP, testo, x + Px(22), y, w - Px(22));
                    break;
                case DocTipo.Didascalia:
                    if (b.Stile == 1) DisegnaTesto(g, b, fF, Color.FromArgb(85, 85, 85), x + Px(26), y, w - Px(26));
                    else DisegnaTesto(g, b, fC, Color.FromArgb(85, 85, 85), x + Px(26), y, w - Px(26));
                    break;
                case DocTipo.Fonte:
                    if (b.Stile == 1)
                    {
                        using (Pen pn = new Pen(Color.FromArgb(221, 221, 221))) g.DrawLine(pn, x, y + Px(3), x + w, y + Px(3));
                        DisegnaTesto(g, b, fF, Color.FromArgb(85, 85, 85), x, y + Px(10), w);
                    }
                    else DisegnaTesto(g, b, fF, Color.FromArgb(85, 85, 85), x, y, w);
                    break;
                case DocTipo.Formula: DisegnaFormula(g, b, x, y, w); break;
                case DocTipo.Tabella: DisegnaTabella(g, b, x, y, w); break;
                case DocTipo.Linea:
                    using (Pen pn = new Pen(Color.FromArgb(210, 210, 210))) g.DrawLine(pn, x, y + Px(5), x + w, y + Px(5));
                    break;
                case DocTipo.Colonne:
                    DisegnaLista(g, b.Sx, x, y, LargSx(b, w));
                    DisegnaLista(g, b.Dx, x + LargSx(b, w) + Px(22), y, LargDx(b, w));
                    break;
                case DocTipo.Locatore: DisegnaLocatore(g, b, x, y); break;
                case DocTipo.Box:
                    if (b.Stile == 3)
                    {
                        // avvertenza: riquadro giallo, triangolo con il punto esclamativo nero, testo nero in ogni tema
                        using (GraphicsPath gp = new GraphicsPath())
                        {
                            float rr = Px(8);
                            RectangleF rb = new RectangleF(x, y, w, h);
                            gp.AddArc(rb.X, rb.Y, 2 * rr, 2 * rr, 180, 90); gp.AddArc(rb.Right - 2 * rr, rb.Y, 2 * rr, 2 * rr, 270, 90);
                            gp.AddArc(rb.Right - 2 * rr, rb.Bottom - 2 * rr, 2 * rr, 2 * rr, 0, 90); gp.AddArc(rb.X, rb.Bottom - 2 * rr, 2 * rr, 2 * rr, 90, 90);
                            gp.CloseFigure();
                            using (Brush br = new SolidBrush(Color.FromArgb(255, 236, 120))) g.FillPath(br, gp);
                            using (Pen pn = new Pen(Color.FromArgb(214, 170, 0), Px(1.5f))) g.DrawPath(pn, gp);
                        }
                        float lt = Px(30), xt = Rtl ? x + w - Px(14) - lt : x + Px(14), yt = y + h / 2 - lt * 0.45f;
                        PointF[] tri = { new PointF(xt + lt / 2, yt), new PointF(xt + lt, yt + lt * 0.88f), new PointF(xt, yt + lt * 0.88f) };
                        using (Pen pt = new Pen(Color.Black, Px(2.4f))) { pt.LineJoin = LineJoin.Round; g.DrawPolygon(pt, tri); }
                        using (Font fe = new Font(fP.FontFamily, Px(17), FontStyle.Bold, GraphicsUnit.Pixel))
                        using (StringFormat sf = new StringFormat())
                        {
                            sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center;
                            g.DrawString("!", fe, Brushes.Black, new RectangleF(xt, yt + lt * 0.22f, lt, lt * 0.66f), sf);
                        }
                        DisegnaTesto(g, b, fP, Color.Black, Rtl ? x + Px(18) : x + Px(18) + Px(46), y + Px(10), w - Px(34) - Px(46));
                        break;
                    }
                    {
                        Color fondo = b.Stile == 1 ? Color.FromArgb(231, 246, 236) : (b.Stile == 2 ? Color.FromArgb(255, 248, 230) : Color.FromArgb(238, 246, 255));
                        Color barra = b.Stile == 1 ? Color.FromArgb(23, 128, 61) : (b.Stile == 2 ? Color.FromArgb(224, 160, 40) : Color.FromArgb(31, 111, 209));
                        bool busta = b.Testo.StartsWith("✉ ");
                        if (b.Stile == 2 && busta)
                        {
                            // riquadro giallo con il bordo e l'icona della busta
                            using (GraphicsPath gp = new GraphicsPath())
                            {
                                float rr = Px(8);
                                RectangleF rb = new RectangleF(x, y, w, h);
                                gp.AddArc(rb.X, rb.Y, 2 * rr, 2 * rr, 180, 90); gp.AddArc(rb.Right - 2 * rr, rb.Y, 2 * rr, 2 * rr, 270, 90);
                                gp.AddArc(rb.Right - 2 * rr, rb.Bottom - 2 * rr, 2 * rr, 2 * rr, 0, 90); gp.AddArc(rb.X, rb.Bottom - 2 * rr, 2 * rr, 2 * rr, 90, 90);
                                gp.CloseFigure();
                                using (Brush br = new SolidBrush(fondo)) g.FillPath(br, gp);
                                using (Pen pn = new Pen(Color.FromArgb(240, 195, 109))) g.DrawPath(pn, gp);
                            }
                        }
                        else
                        {
                            using (Brush br = new SolidBrush(fondo)) g.FillRectangle(br, x, y, w, h);
                            using (Brush br = new SolidBrush(barra)) g.FillRectangle(br, Rtl ? x + w - Px(4) : x, y, Px(4), h);
                        }
                        if (busta)
                        {
                            using (Font fi = new Font(fP.FontFamily, Px(26), FontStyle.Regular, GraphicsUnit.Pixel))
                            using (Brush br = new SolidBrush(testo))
                                g.DrawString("✉", fi, br, x + Px(12), y + h / 2 - fi.GetHeight(g) / 2);
                            DocBlocco tb = DocBlocco.P(DocTipo.Par, b.Testo.Substring(2));
                            DisegnaTesto(g, tb, fP, testo, x + Px(18) + Px(46), y + Px(10), w - Px(34) - Px(46));
                        }
                        else DisegnaTesto(g, b, fP, testo, x + Px(18), y + Px(10), w - Px(34));
                        break;
                    }
                case DocTipo.Figura:
                    {
                        if (b.Stile == 1)
                        {
                            // figura larga quanto la colonna, didascalia sotto
                            int iw = (int)w, ih = (int)(w * 0.58f);
                            if ((b.Img == null || b.Img.Width != iw) && b.ImmagineWH != null)
                            {
                                if (b.Img != null) b.Img.Dispose();
                                try { b.Img = b.ImmagineWH(iw, ih); } catch { b.Img = null; }
                            }
                            RectangleF r = new RectangleF(x, y, iw, ih);
                            if (b.Img != null) g.DrawImage(b.Img, r);
                            DisegnaTesto(g, DidascaliaDi(b), fC, Color.FromArgb(85, 85, 85), x, y + ih + Px(6), w);
                            break;
                        }
                        RectangleF r0 = new RectangleF(x, y, Px(330), Px(186));
                        if (b.Img != null) g.DrawImage(b.Img, r0);
                        else using (HatchBrush hb = new HatchBrush(HatchStyle.WideUpwardDiagonal, Color.FromArgb(225, 229, 236), Color.FromArgb(244, 246, 249))) g.FillRectangle(hb, r0);
                        using (Pen pn = new Pen(Color.FromArgb(180, 188, 200))) g.DrawRectangle(pn, r0.X, r0.Y, r0.Width, r0.Height);
                        DocBlocco cap = DocBlocco.P(DocTipo.Didascalia, b.Testo);
                        DisegnaTesto(g, cap, fC, Color.FromArgb(85, 85, 85), r0.Right + Px(16), r0.Top + Px(40), w - r0.Width - Px(16));
                        break;
                    }
            }
        }

        protected override void OnScroll(ScrollEventArgs se) { base.OnScroll(se); Invalidate(); }
        protected override void OnMouseWheel(MouseEventArgs e) { base.OnMouseWheel(e); Invalidate(); }

        object LinkA(Point p)
        {
            PointF q = new PointF(p.X - AutoScrollPosition.X, p.Y - AutoScrollPosition.Y);
            foreach (KeyValuePair<RectangleF, object> kv in link) if (kv.Key.Contains(q)) return kv.Value;
            return null;
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            Cursor = LinkA(e.Location) != null ? Cursors.Hand : Cursors.Default;
        }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            base.OnMouseClick(e);
            object o = LinkA(e.Location);
            if (o is string) { try { System.Diagnostics.Process.Start((string)o); } catch { } }
            else if (o is Action) ((Action)o)();
        }

        public void VaiA(DocBlocco b)
        {
            if (b == null) return;
            AutoScrollPosition = new Point(0, (int)Math.Max(0, b.Y - Px(12)));
            Invalidate();
        }

        public DocBlocco Cerca(string testo, DocBlocco dopo)
        {
            if (string.IsNullOrEmpty(testo)) return null;
            int ini = dopo == null ? 0 : Blocchi.IndexOf(dopo) + 1;
            for (int n = 0; n < Blocchi.Count; n++)
            {
                DocBlocco b = Blocchi[(ini + n) % Blocchi.Count];
                string t = b.Testo ?? "";
                if (b.Righe != null) foreach (string[] r in b.Righe) t += " " + string.Join(" ", r);
                if (b.Tipo == DocTipo.Colonne)
                    foreach (List<DocBlocco> l in new List<DocBlocco>[] { b.Sx, b.Dx })
                        if (l != null)
                            foreach (DocBlocco c in l)
                            {
                                t += " " + (c.Testo ?? "");
                                if (c.Righe != null) foreach (string[] r in c.Righe) t += " " + string.Join(" ", r);
                            }
                if (t.IndexOf(testo, StringComparison.CurrentCultureIgnoreCase) >= 0) return b;
            }
            return null;
        }

        // Testo semplice del documento (appunti)
        public string TestoSemplice()
        {
            StringBuilder sb = new StringBuilder();
            foreach (DocBlocco b in Blocchi)
            {
                switch (b.Tipo)
                {
                    case DocTipo.Titolo: sb.AppendLine(b.Testo.ToUpper(Lang.Cultura)); sb.AppendLine(); break;
                    case DocTipo.Sez: sb.AppendLine(); sb.AppendLine(b.Testo); sb.AppendLine(new string('-', Math.Min(70, b.Testo.Length))); break;
                    case DocTipo.Sotto: sb.AppendLine(); sb.AppendLine("▸ " + b.Testo); break;
                    case DocTipo.Formula:
                        sb.AppendLine("    " + Formula.Semplice(b.Testo) + (b.Valori == null && b.Risultato != null ? " = " + Formula.Semplice(b.Risultato) : "") + (b.Num.Length > 0 ? "    " + b.Num : ""));
                        if (b.Valori != null) sb.AppendLine("      = " + Formula.Semplice(b.Valori) + (b.Risultato != null ? " = " + Formula.Semplice(b.Risultato) : ""));
                        break;
                    case DocTipo.Tabella:
                        foreach (string[] r in b.Righe) sb.AppendLine("    " + string.Join("  |  ", r));
                        break;
                    case DocTipo.Punto: sb.AppendLine("  • " + Pulisci(b.Testo)); break;
                    case DocTipo.Spazio: case DocTipo.Linea: sb.AppendLine(); break;
                    case DocTipo.Colonne:
                        foreach (List<DocBlocco> l in new List<DocBlocco>[] { b.Sx, b.Dx })
                            if (l != null)
                                foreach (DocBlocco c in l)
                                {
                                    if (c.Righe != null) foreach (string[] r in c.Righe) sb.AppendLine("    " + string.Join("  |  ", r));
                                    else sb.AppendLine(Pulisci(c.Testo));
                                }
                        break;
                    default: sb.AppendLine(Pulisci(b.Testo)); break;
                }
            }
            return sb.ToString();
        }

        static string Pulisci(string t)
        {
            StringBuilder sb = new StringBuilder();
            int i = 0;
            while (i < t.Length)
            {
                if (t[i] == '§')
                {
                    int j = t.IndexOf('§', i + 1);
                    if (j < 0) j = t.Length;
                    sb.Append(Formula.Semplice(t.Substring(i + 1, j - i - 1)));
                    i = j + 1;
                    continue;
                }
                if (t[i] != '*') sb.Append(t[i]);
                i++;
            }
            return sb.ToString();
        }

        // ---- documento di Word (.docx) con le formule in Office Math (Equation Editor di Word)
        public void SalvaDocx(string percorso, string titolo) { SalvaDocx(percorso, titolo, false); }

        // manuale = true: titoli su quattro livelli, capitoli a pagina nuova, sommario automatico, numero di pagina in fondo,
        // riquadri colorati, colonne affiancate, righe evidenziate, testo colorato e figure (abaco) come nel programma
        public void SalvaDocx(string percorso, string titolo, bool manuale)
        {
            StringBuilder d = new StringBuilder();
            List<byte[]> figure = new List<byte[]>();
            d.Append("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>");
            d.Append("<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\"")
             .Append(" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\"")
             .Append(" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:pic=\"http://schemas.openxmlformats.org/drawingml/2006/picture\"><w:body>");
            int nTitoli = 0;
            ScriviDocx(d, Blocchi, manuale, ref nTitoli, figure, 9638);
            d.Append("<w:sectPr>");
            if (manuale) d.Append("<w:footerReference w:type=\"default\" r:id=\"rIdPiede\"/>");
            d.Append("<w:pgSz w:w=\"11906\" w:h=\"16838\"/><w:pgMar w:top=\"1134\" w:right=\"1134\" w:bottom=\"1134\" w:left=\"1134\" w:header=\"567\" w:footer=\"567\" w:gutter=\"0\"/></w:sectPr></w:body></w:document>");
            string h1 = manuale
                ? "<w:pPr><w:keepNext/><w:pageBreakBefore/><w:pBdr><w:bottom w:val=\"single\" w:sz=\"8\" w:space=\"4\" w:color=\"19417F\"/></w:pBdr><w:spacing w:before=\"0\" w:after=\"160\"/><w:outlineLvl w:val=\"0\"/></w:pPr><w:rPr><w:b/><w:color w:val=\"19417F\"/><w:sz w:val=\"36\"/></w:rPr>"
                : "<w:pPr><w:keepNext/><w:spacing w:before=\"280\" w:after=\"80\"/><w:outlineLvl w:val=\"0\"/></w:pPr><w:rPr><w:color w:val=\"2E74B5\"/><w:sz w:val=\"30\"/></w:rPr>";
            string stili = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><w:styles xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\">"
                + "<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii=\"Calibri\" w:hAnsi=\"Calibri\" w:eastAsia=\"Calibri\" w:cs=\"Calibri\"/><w:sz w:val=\"21\"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after=\"80\" w:line=\"264\" w:lineRule=\"auto\"/></w:pPr></w:pPrDefault></w:docDefaults>"
                + "<w:style w:type=\"paragraph\" w:default=\"1\" w:styleId=\"Normal\"><w:name w:val=\"Normal\"/></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Title\"><w:name w:val=\"Title\"/><w:basedOn w:val=\"Normal\"/><w:pPr><w:pBdr><w:bottom w:val=\"single\" w:sz=\"8\" w:space=\"4\" w:color=\"19417F\"/></w:pBdr><w:spacing w:after=\"200\"/></w:pPr><w:rPr><w:color w:val=\"19417F\"/><w:sz w:val=\"40\"/></w:rPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Heading1\"><w:name w:val=\"heading 1\"/><w:basedOn w:val=\"Normal\"/><w:next w:val=\"Normal\"/>" + h1 + "</w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Heading2\"><w:name w:val=\"heading 2\"/><w:basedOn w:val=\"Normal\"/><w:next w:val=\"Normal\"/><w:pPr><w:keepNext/><w:spacing w:before=\"240\" w:after=\"60\"/><w:outlineLvl w:val=\"1\"/></w:pPr><w:rPr><w:b/><w:color w:val=\"19417F\"/><w:sz w:val=\"" + (manuale ? "28" : "22") + "\"/></w:rPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Heading3\"><w:name w:val=\"heading 3\"/><w:basedOn w:val=\"Normal\"/><w:next w:val=\"Normal\"/><w:pPr><w:keepNext/><w:spacing w:before=\"180\" w:after=\"40\"/><w:outlineLvl w:val=\"2\"/></w:pPr><w:rPr><w:color w:val=\"2E74B5\"/><w:sz w:val=\"25\"/></w:rPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Heading4\"><w:name w:val=\"heading 4\"/><w:basedOn w:val=\"Normal\"/><w:next w:val=\"Normal\"/><w:pPr><w:keepNext/><w:spacing w:before=\"140\" w:after=\"40\"/><w:outlineLvl w:val=\"3\"/></w:pPr><w:rPr><w:color w:val=\"2E74B5\"/><w:sz w:val=\"22\"/></w:rPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Caption\"><w:name w:val=\"caption\"/><w:basedOn w:val=\"Normal\"/><w:rPr><w:i/><w:color w:val=\"555555\"/><w:sz w:val=\"18\"/></w:rPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Fonte\"><w:name w:val=\"Fonte\"/><w:basedOn w:val=\"Normal\"/><w:pPr><w:spacing w:after=\"40\"/><w:ind w:left=\"284\" w:hanging=\"284\"/></w:pPr><w:rPr><w:color w:val=\"444444\"/><w:sz w:val=\"18\"/></w:rPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"Elenco\"><w:name w:val=\"Elenco\"/><w:basedOn w:val=\"Normal\"/><w:pPr><w:ind w:left=\"360\" w:hanging=\"240\"/></w:pPr></w:style>"
                + "<w:style w:type=\"paragraph\" w:styleId=\"TOCHeading\"><w:name w:val=\"TOC Heading\"/><w:basedOn w:val=\"Normal\"/><w:pPr><w:spacing w:before=\"240\" w:after=\"120\"/></w:pPr><w:rPr><w:b/><w:color w:val=\"19417F\"/><w:sz w:val=\"28\"/></w:rPr></w:style>"
                + "<w:style w:type=\"table\" w:styleId=\"TableGrid\"><w:name w:val=\"Table Grid\"/><w:tblPr><w:tblBorders><w:top w:val=\"single\" w:sz=\"4\" w:color=\"D9E2F3\"/><w:bottom w:val=\"single\" w:sz=\"4\" w:color=\"D9E2F3\"/><w:insideH w:val=\"single\" w:sz=\"4\" w:color=\"D9E2F3\"/></w:tblBorders><w:tblCellMar><w:left w:w=\"80\" w:type=\"dxa\"/><w:right w:w=\"80\" w:type=\"dxa\"/></w:tblCellMar></w:tblPr></w:style>"
                + "</w:styles>";
            StringBuilder tipi = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">"
                + "<Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/>"
                + "<Default Extension=\"png\" ContentType=\"image/png\"/>"
                + "<Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/>"
                + "<Override PartName=\"/word/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml\"/>");
            if (manuale)
                tipi.Append("<Override PartName=\"/word/settings.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml\"/>")
                    .Append("<Override PartName=\"/word/footer1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml\"/>");
            tipi.Append("</Types>");
            string rels = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"
                + "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/></Relationships>";
            StringBuilder drels = new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">"
                + "<Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/>");
            if (manuale)
                drels.Append("<Relationship Id=\"rIdImpost\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings\" Target=\"settings.xml\"/>")
                     .Append("<Relationship Id=\"rIdPiede\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer\" Target=\"footer1.xml\"/>");
            for (int i = 0; i < figure.Count; i++)
                drels.Append("<Relationship Id=\"rIdFig").Append(i + 1).Append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/image\" Target=\"media/figura").Append(i + 1).Append(".png\"/>");
            drels.Append("</Relationships>");
            // il sommario si compila all'apertura (Word chiede di aggiornare i campi)
            string impost = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><w:settings xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:updateFields w:val=\"true\"/></w:settings>";
            string piede = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?><w:ftr xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:p><w:pPr><w:jc w:val=\"center\"/></w:pPr>"
                + "<w:r><w:rPr><w:color w:val=\"777777\"/><w:sz w:val=\"17\"/></w:rPr><w:t xml:space=\"preserve\">" + X(titolo) + "  ·  </w:t></w:r>"
                + "<w:r><w:rPr><w:color w:val=\"777777\"/><w:sz w:val=\"17\"/></w:rPr><w:fldChar w:fldCharType=\"begin\"/></w:r><w:r><w:rPr><w:color w:val=\"777777\"/><w:sz w:val=\"17\"/></w:rPr><w:instrText xml:space=\"preserve\"> PAGE </w:instrText></w:r>"
                + "<w:r><w:rPr><w:color w:val=\"777777\"/><w:sz w:val=\"17\"/></w:rPr><w:fldChar w:fldCharType=\"separate\"/></w:r><w:r><w:rPr><w:color w:val=\"777777\"/><w:sz w:val=\"17\"/></w:rPr><w:t>1</w:t></w:r>"
                + "<w:r><w:rPr><w:color w:val=\"777777\"/><w:sz w:val=\"17\"/></w:rPr><w:fldChar w:fldCharType=\"end\"/></w:r></w:p></w:ftr>";
            if (File.Exists(percorso)) File.Delete(percorso);
            using (System.IO.Compression.ZipArchive z = System.IO.Compression.ZipFile.Open(percorso, System.IO.Compression.ZipArchiveMode.Create))
            {
                Voce(z, "[Content_Types].xml", tipi.ToString());
                Voce(z, "_rels/.rels", rels);
                Voce(z, "word/document.xml", d.ToString());
                Voce(z, "word/styles.xml", stili);
                Voce(z, "word/_rels/document.xml.rels", drels.ToString());
                if (manuale) { Voce(z, "word/settings.xml", impost); Voce(z, "word/footer1.xml", piede); }
                for (int i = 0; i < figure.Count; i++)
                {
                    System.IO.Compression.ZipArchiveEntry e = z.CreateEntry("word/media/figura" + (i + 1).ToString(CultureInfo.InvariantCulture) + ".png");
                    using (Stream s = e.Open()) s.Write(figure[i], 0, figure[i].Length);
                }
            }
        }

        // Scrive i blocchi (anche dentro le colonne affiancate); larghezza = larghezza utile in twip
        void ScriviDocx(StringBuilder d, List<DocBlocco> blocchi, bool manuale, ref int nTitoli, List<byte[]> figure, int larghezza)
        {
            CultureInfo inv = CultureInfo.InvariantCulture;
            foreach (DocBlocco b in blocchi)
            {
                switch (b.Tipo)
                {
                    case DocTipo.Titolo:
                        nTitoli++;
                        ParDocx(d, b.Testo, manuale && nTitoli > 1 ? "Heading1" : "Title");
                        break;
                    case DocTipo.Sez: ParDocx(d, b.Testo, manuale ? "Heading2" : "Heading1"); break;
                    case DocTipo.Sotto:
                        if (!manuale) ParDocx(d, b.Testo, "Heading2");
                        else ParDocx(d, b.Testo, b.Stile == 1 ? "Heading2" : (b.Testo.Length > 0 && char.IsDigit(b.Testo[0]) ? "Heading3" : "Heading4"));
                        break;
                    case DocTipo.Didascalia:
                        ParDocx(d, b.Testo, "Caption");
                        if (manuale && nTitoli == 1 && b == Blocchi[1])
                        {
                            // sommario dopo la copertina
                            d.Append("<w:p><w:pPr><w:pStyle w:val=\"TOCHeading\"/></w:pPr>");
                            RunDocx(d, Lang.T("Indice"), true, null);
                            d.Append("</w:p><w:p><w:r><w:fldChar w:fldCharType=\"begin\" w:dirty=\"true\"/></w:r><w:r><w:instrText xml:space=\"preserve\"> TOC \\o \"1-3\" \\h \\z \\u </w:instrText></w:r>")
                             .Append("<w:r><w:fldChar w:fldCharType=\"separate\"/></w:r>");
                            RunDocx(d, Lang.T("Aggiorna il sommario: tasto destro qui, Aggiorna campo."), false, "777777");
                            d.Append("<w:r><w:fldChar w:fldCharType=\"end\"/></w:r></w:p>");
                        }
                        break;
                    case DocTipo.Punto: ParDocx(d, "•\t" + b.Testo, "Elenco"); break;
                    case DocTipo.Fonte: ParDocx(d, b.Testo, b.Stile == 1 ? "Heading4" : "Fonte"); break;
                    case DocTipo.Box:
                        {
                            string fondo = b.Stile == 1 ? "E8F7EE" : (b.Stile == 2 ? "FFF8E6" : (b.Stile == 3 ? "FFEC78" : "EEF6FF"));
                            string bordo = b.Stile == 1 ? "17803D" : (b.Stile == 2 ? "F0C36D" : (b.Stile == 3 ? "D6AA00" : "1F6FD1"));
                            d.Append("<w:p><w:pPr><w:pBdr><w:left w:val=\"single\" w:sz=\"24\" w:space=\"6\" w:color=\"").Append(bordo).Append("\"/></w:pBdr>")
                             .Append("<w:shd w:val=\"clear\" w:color=\"auto\" w:fill=\"").Append(fondo).Append("\"/><w:spacing w:before=\"80\" w:after=\"120\"/><w:ind w:left=\"170\" w:right=\"113\"/></w:pPr>");
                            RunMarcati(d, (b.Stile == 3 ? "⚠ " : "") + b.Testo);
                            d.Append("</w:p>");
                            break;
                        }
                    case DocTipo.Formula:
                        {
                            string l1 = b.Testo + (b.Valori == null && b.Risultato != null ? " = \\h{" + b.Risultato + "}" : "");
                            // formula a sinistra e numero a destra, sulla stessa riga
                            d.Append("<w:p><w:pPr><w:tabs><w:tab w:val=\"right\" w:pos=\"").Append(larghezza.ToString(inv)).Append("\"/></w:tabs><w:ind w:left=\"340\"/></w:pPr>")
                             .Append(Formula.Omml(l1));
                            if (b.Num.Length > 0 && b.Valori == null)
                                d.Append("<w:r><w:tab/></w:r><w:r><w:rPr><w:color w:val=\"6B7280\"/><w:sz w:val=\"19\"/></w:rPr><w:t>").Append(X(b.Num)).Append("</w:t></w:r>");
                            d.Append("</w:p>");
                            if (b.Valori != null)
                            {
                                d.Append("<w:p><w:pPr><w:tabs><w:tab w:val=\"right\" w:pos=\"").Append(larghezza.ToString(inv)).Append("\"/></w:tabs><w:ind w:left=\"340\"/></w:pPr>")
                                 .Append(Formula.Omml("= " + b.Valori + (b.Risultato != null ? " = \\h{" + b.Risultato + "}" : "")));
                                if (b.Num.Length > 0)
                                    d.Append("<w:r><w:tab/></w:r><w:r><w:rPr><w:color w:val=\"6B7280\"/><w:sz w:val=\"19\"/></w:rPr><w:t>").Append(X(b.Num)).Append("</w:t></w:r>");
                                d.Append("</w:p>");
                            }
                            break;
                        }
                    case DocTipo.Tabella:
                        {
                            if (b.Righe == null || b.Righe.Count == 0) break;
                            d.Append("<w:tbl><w:tblPr><w:tblStyle w:val=\"TableGrid\"/><w:tblW w:w=\"5000\" w:type=\"pct\"/></w:tblPr>");
                            for (int ri = 0; ri < b.Righe.Count; ri++)
                            {
                                d.Append("<w:tr>");
                                if (ri == 0) d.Append("<w:trPr><w:tblHeader/></w:trPr>");
                                string fill = ri == 0 ? "4472C4" : (b.Evidenzia != null && b.Evidenzia.Contains(ri) ? "DEF4E5" : (ri % 2 == 0 ? "EEF3FB" : null));
                                for (int ci = 0; ci < b.Righe[ri].Length; ci++)
                                {
                                    d.Append("<w:tc>");
                                    if (fill != null) d.Append("<w:tcPr><w:shd w:val=\"clear\" w:color=\"auto\" w:fill=\"").Append(fill).Append("\"/></w:tcPr>");
                                    d.Append("<w:p><w:pPr><w:spacing w:after=\"0\"/>");
                                    bool destra = b.Destra != null && ci < b.Destra.Length && b.Destra[ci];
                                    bool centro = b.Centro != null && ci < b.Centro.Length && b.Centro[ci];
                                    if (destra) d.Append("<w:jc w:val=\"right\"/>"); else if (centro) d.Append("<w:jc w:val=\"center\"/>");
                                    d.Append("</w:pPr>");
                                    if (ri == 0) RunDocx(d, Pulisci(b.Righe[ri][ci]), true, "FFFFFF");
                                    else RunMarcati(d, b.Righe[ri][ci]);
                                    d.Append("</w:p></w:tc>");
                                }
                                d.Append("</w:tr>");
                            }
                            d.Append("</w:tbl><w:p><w:pPr><w:spacing w:after=\"0\"/></w:pPr></w:p>");
                            break;
                        }
                    case DocTipo.Colonne:
                        {
                            // due colonne affiancate: tabella senza bordi
                            int w1 = (int)(larghezza * Math.Max(0.2f, Math.Min(0.8f, b.Quota))), w2 = larghezza - w1;
                            d.Append("<w:tbl><w:tblPr><w:tblW w:w=\"").Append(larghezza.ToString(inv)).Append("\" w:type=\"dxa\"/><w:tblLayout w:type=\"fixed\"/>")
                             .Append("<w:tblCellMar><w:left w:w=\"0\" w:type=\"dxa\"/><w:right w:w=\"170\" w:type=\"dxa\"/></w:tblCellMar></w:tblPr><w:tblGrid><w:gridCol w:w=\"")
                             .Append(w1.ToString(inv)).Append("\"/><w:gridCol w:w=\"").Append(w2.ToString(inv)).Append("\"/></w:tblGrid><w:tr>");
                            List<DocBlocco>[] lati = { b.Sx ?? new List<DocBlocco>(), b.Dx ?? new List<DocBlocco>() };
                            int[] lw = { w1, w2 };
                            for (int k = 0; k < 2; k++)
                            {
                                d.Append("<w:tc><w:tcPr><w:tcW w:w=\"").Append(lw[k].ToString(inv)).Append("\" w:type=\"dxa\"/></w:tcPr>");
                                ScriviDocx(d, lati[k], manuale, ref nTitoli, figure, lw[k] - 170);
                                d.Append("<w:p><w:pPr><w:spacing w:after=\"0\"/></w:pPr></w:p></w:tc>");
                            }
                            d.Append("</w:tr></w:tbl>");
                            break;
                        }
                    case DocTipo.Figura:
                        {
                            Bitmap bm = null;
                            bool mia = false;
                            try
                            {
                                if (b.ImmagineWH != null) { bm = b.ImmagineWH(1500, 900); mia = true; }
                                else bm = b.Img;
                            }
                            catch { bm = null; }
                            if (bm != null)
                            {
                                byte[] png;
                                using (MemoryStream ms = new MemoryStream()) { bm.Save(ms, System.Drawing.Imaging.ImageFormat.Png); png = ms.ToArray(); }
                                long cx = (long)larghezza * 635L;   // da twip a EMU
                                long cy = cx * bm.Height / Math.Max(1, bm.Width);
                                figure.Add(png);
                                int n = figure.Count;
                                d.Append("<w:p><w:pPr><w:jc w:val=\"center\"/><w:keepNext/></w:pPr><w:r><w:drawing><wp:inline distT=\"0\" distB=\"0\" distL=\"0\" distR=\"0\"><wp:extent cx=\"")
                                 .Append(cx.ToString(inv)).Append("\" cy=\"").Append(cy.ToString(inv)).Append("\"/><wp:docPr id=\"").Append(n.ToString(inv)).Append("\" name=\"Figura ").Append(n.ToString(inv)).Append("\"/>")
                                 .Append("<a:graphic><a:graphicData uri=\"http://schemas.openxmlformats.org/drawingml/2006/picture\"><pic:pic><pic:nvPicPr><pic:cNvPr id=\"").Append(n.ToString(inv))
                                 .Append("\" name=\"figura").Append(n.ToString(inv)).Append(".png\"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed=\"rIdFig").Append(n.ToString(inv))
                                 .Append("\"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x=\"0\" y=\"0\"/><a:ext cx=\"").Append(cx.ToString(inv)).Append("\" cy=\"").Append(cy.ToString(inv))
                                 .Append("\"/></a:xfrm><a:prstGeom prst=\"rect\"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>");
                                if (mia) bm.Dispose();
                            }
                            if (b.Testo.Length > 0) ParDocx(d, b.Testo, "Caption");
                            break;
                        }
                    case DocTipo.Locatore:
                        d.Append("<w:p><w:pPr><w:ind w:left=\"340\"/></w:pPr><w:r><w:rPr><w:rFonts w:ascii=\"Consolas\" w:hAnsi=\"Consolas\"/><w:b/><w:color w:val=\"19417F\"/><w:sz w:val=\"30\"/></w:rPr><w:t xml:space=\"preserve\">")
                         .Append(X(b.Testo)).Append("</w:t></w:r></w:p>");
                        break;
                    case DocTipo.Spazio: case DocTipo.Linea: d.Append("<w:p/>"); break;
                    default: ParDocx(d, b.Testo, null); break;
                }
            }
        }

        // Testo con la marcatura del manuale: **grassetto**, *corsivo*, §formula§, {r:rosso} {g:verde} {o:arancione} {b:blu}, %bar:…%testo
        static void RunMarcati(StringBuilder d, string t)
        {
            t = t ?? "";
            bool gr = false, cor = false;
            string col = null;
            StringBuilder cur = new StringBuilder();
            int i = 0;
            Action fuori = () => { if (cur.Length > 0) { RunDocx(d, cur.ToString(), gr, col, cor); cur.Length = 0; } };
            while (i < t.Length)
            {
                char c = t[i];
                if (c == '*' && i + 1 < t.Length && t[i + 1] == '*') { fuori(); gr = !gr; i += 2; continue; }
                if (c == '*' && (cor || t.IndexOf('*', i + 1) > i + 1)) { fuori(); cor = !cor; i++; continue; }
                if (c == '§')
                {
                    fuori();
                    int j = t.IndexOf('§', i + 1);
                    if (j < 0) j = t.Length;
                    d.Append(Formula.Omml(t.Substring(i + 1, j - i - 1)));
                    i = j + 1;
                    continue;
                }
                if (c == '{' && i + 2 < t.Length && t[i + 2] == ':' && "rgob".IndexOf(t[i + 1]) >= 0 && t.IndexOf('}', i) > 0)
                {
                    fuori();
                    col = t[i + 1] == 'r' ? "C62828" : (t[i + 1] == 'g' ? "17803D" : (t[i + 1] == 'o' ? "D97706" : "1F6FD1"));
                    i += 3;
                    continue;
                }
                if (c == '}' && col != null) { fuori(); col = null; i++; continue; }
                if (c == '%' && t.Length > i + 5 && t.Substring(i, 5) == "%bar:")
                {
                    int j = t.IndexOf('%', i + 5);
                    if (j > 0) { i = j + 1; continue; }
                }
                cur.Append(c);
                i++;
            }
            fuori();
        }

        static void RunDocx(StringBuilder d, string t, bool grassetto, string colore) { RunDocx(d, t, grassetto, colore, false); }

        static void RunDocx(StringBuilder d, string t, bool grassetto, string colore, bool corsivo)
        {
            if (string.IsNullOrEmpty(t)) return;
            d.Append("<w:r>");
            if (grassetto || colore != null || corsivo)
            {
                d.Append("<w:rPr>");
                if (grassetto) d.Append("<w:b/>");
                if (corsivo) d.Append("<w:i/>");
                if (colore != null) d.Append("<w:color w:val=\"").Append(colore).Append("\"/>");
                d.Append("</w:rPr>");
            }
            d.Append("<w:t xml:space=\"preserve\">").Append(X(t)).Append("</w:t></w:r>");
        }

        static void ParDocx(StringBuilder d, string t, string stile)
        {
            d.Append("<w:p>");
            if (stile != null) d.Append("<w:pPr><w:pStyle w:val=\"").Append(stile).Append("\"/></w:pPr>");
            RunMarcati(d, t);
            d.Append("</w:p>");
        }

        static void Voce(System.IO.Compression.ZipArchive z, string nome, string testo)
        {
            System.IO.Compression.ZipArchiveEntry e = z.CreateEntry(nome);
            using (StreamWriter w = new StreamWriter(e.Open(), new UTF8Encoding(false))) w.Write(testo);
        }

        static string X(string t) { return (t ?? "").Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;"); }
    }

    // Fumetti scuri con il titolo colorato (stile unico per tutto il programma)
    static class Fumetto
    {
        static readonly Color Fondo = Color.FromArgb(29, 36, 51), Titolo = Color.FromArgb(201, 184, 255);
        const int Larg = 430;
        public static string Ultimo = "";   // testo dei fumetti mostrati con ToolTip.Show

        public static void Stile(ToolTip t)
        {
            t.OwnerDraw = true;
            t.AutoPopDelay = 30000;
            t.InitialDelay = 450;
            t.ReshowDelay = 150;
            t.Popup += (s, e) =>
            {
                string tit, corpo;
                string tx = t.GetToolTip(e.AssociatedControl);
                if (string.IsNullOrEmpty(tx)) tx = Ultimo;
                Dividi(e.AssociatedControl, tx, out tit, out corpo);
                Size sz = Misura(tit, corpo);
                e.ToolTipSize = sz;
            };
            t.Draw += (s, e) =>
            {
                string tit, corpo;
                Dividi(e.AssociatedControl, e.ToolTipText, out tit, out corpo);
                Disegna(e.Graphics, e.Bounds, tit, corpo);
            };
        }

        static Font fT, fC;
        static void Fonts()
        {
            if (fT != null && fT.FontFamily.Name == Lang.FontUi) return;
            fT = new Font(Lang.FontUi, 9.5F, FontStyle.Bold);
            fC = new Font(Lang.FontUi, 9.5F);
        }

        // il titolo è il testo del controllo (casella, pulsante, etichetta), se è breve
        public static void Dividi(Control c, string testo, out string tit, out string corpo)
        {
            tit = ""; corpo = testo ?? "";
            int k = corpo.IndexOf('\u0001');
            if (k >= 0) { tit = corpo.Substring(0, k); corpo = corpo.Substring(k + 1); return; }
            if (c != null && (c is CheckBox || c is Button || c is RadioButton || c is Label) && !string.IsNullOrEmpty(c.Text) && c.Text.Length <= 60 && c.Text.IndexOf('\n') < 0)
                tit = c.Text.Replace("&&", "&");
        }

        static Size Misura(string tit, string corpo)
        {
            Fonts();
            using (Bitmap b = new Bitmap(1, 1))
            using (Graphics g = Graphics.FromImage(b))
            {
                float w = 0, h = 0;
                if (tit.Length > 0) { SizeF st = g.MeasureString(tit, fT, Larg); w = st.Width; h += st.Height + 2; }
                SizeF sc = g.MeasureString(corpo, fC, Larg);
                w = Math.Max(w, sc.Width); h += sc.Height;
                return new Size((int)Math.Ceiling(w) + 26, (int)Math.Ceiling(h) + 18);
            }
        }

        public static void Disegna(Graphics g, Rectangle r, string tit, string corpo)
        {
            Fonts();
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
            using (Brush b = new SolidBrush(Fondo)) g.FillRectangle(b, r);
            float y = r.Top + 8;
            RectangleF rt = new RectangleF(r.Left + 12, y, r.Width - 22, r.Height);
            if (tit.Length > 0)
            {
                using (Brush b = new SolidBrush(Titolo)) g.DrawString(tit, fT, b, rt);
                y += g.MeasureString(tit, fT, Larg).Height + 2;
            }
            using (Brush b = new SolidBrush(Color.White)) g.DrawString(corpo, fC, b, new RectangleF(r.Left + 12, y, r.Width - 22, r.Bottom - y));
        }
    }

    // ---------- Database dei cavi coassiali 50 ohm (attenuazione in dB/100 m a 20 °C) ----------
    // Valori a 50, 70, 144, 222 e 432 MHz già calcolati: m = dalla scheda, i = interpolato (legge di potenza), e = estrapolato.
    // Cavi accorpati (≡): stesso tipo, diametro entro ±0,2 mm e attenuazione entro 0,2 dB/100 m in tutte le bande (valore medio).
    class Cavo
    {
        public string[] Nomi; public string[] Costruttori; public string Tipo; public double Diam; public string Anche; public string[] Fonti;
        public double[] Db = new double[5]; public char[] Segno = new char[5];
        public bool Personale;
        public bool Marino;     // cavo per ambienti marini: nel nome mostrato compare "(ambienti marini)"
        public string Nome { get { return Nomi[0]; } }
        public string NomeVisto { get { return Nomi[0] + (Marino ? " (" + Lang.T("ambienti marini") + ")" : ""); } }
        public string Etichetta { get { return NomeVisto + (Nomi.Length > 1 ? " ≡ " + string.Join(", ", Nomi, 1, Nomi.Length - 1) : "") + " · " + Diam.ToString("0.0", CultureInfo.CurrentCulture) + " mm"; } }

        // dB/100 m alla frequenza f (MHz): legge di potenza tra le due bande più vicine
        public double A100(double f)
        {
            double[] fb = CaviDb.Fb;
            int k = 0;
            while (k < fb.Length - 2 && f > fb[k + 1]) k++;
            double a = Db[k], b = Db[k + 1];
            if (a <= 0 || b <= 0) return Math.Max(a, b);
            double e = Math.Log(b / a) / Math.Log(fb[k + 1] / fb[k]);
            return a * Math.Pow(f / fb[k], e);
        }

        public double Perdita(double f, double metri) { return A100(f) * metri / 100.0; }
    }

    static class CaviDb
    {
        public static readonly double[] Fb = { 50, 70, 144, 222, 432 };
        public static readonly List<Cavo> Elenco = new List<Cavo>();

        static void A(string[] nomi, string[] cost, string tipo, double d, string anche, string[] fonti, double v50, char s50, double v70, char s70, double v144, char s144, double v222, char s222, double v432, char s432)
        {
            Cavo c = new Cavo();
            c.Nomi = nomi; c.Costruttori = cost; c.Tipo = tipo; c.Diam = d; c.Anche = anche; c.Fonti = fonti;
            c.Db = new double[] { v50, v70, v144, v222, v432 };
            c.Segno = new char[] { s50, s70, s144, s222, s432 };
            Elenco.Add(c);
        }

