        // Citazione completa di ogni fonte
        public static string Fonte(string breve)
        {
            switch (breve)
            {
                case "qsl.net/sv1bsx": return "SV1BSX, tabella delle attenuazioni dei cavi coassiali (qsl.net/sv1bsx) – valori da verificare sulle schede dei costruttori";
                case "moonrakeronline (SSB)": return "SSB-Electronic, schede tecniche Aircell / Ecoflex (distribuite da Moonraker UK, moonrakeronline.com)";
                case "Fairview / Times": return "Times Microwave Systems, schede LMR (distribuite da Fairview Microwave, fairviewmicrowave.com)";
                case "Times / iewc": return "Times Microwave Systems, scheda LMR-400 (iewc.com)";
                case "sivacavi.it": return "Siva Cavi, schede tecniche HF 240 / HF 287 / HF 400 (sivacavi.it)";
                case "RFS": return "RFS – Radio Frequency Systems, schede tecniche CELLFLEX LCF / SCF (rfsworld.com)";
                case "WiMo": return "WiMo, schede tecniche Messi & Paoloni Hyperflex / Ultraflex ed Ecoflex Plus (wimo.com)";
                case "szansy.com": return "Scheda del cavo SYV50-7 low loss (szansy.com)";
                case "CommScope": return "CommScope (Andrew), schede tecniche HELIAX LDF / FSJ (commscope.com)";
                case "Symair": return "Symair, schede tecniche HCAAYZ-50-12 / HCAHY-50-9 (symair.com)";
                case "Belden": return "Belden, schede tecniche H1000 (H1000C1), 8237 (RG-8/U) e 9913 (catalog.belden.com); per 8237 e 9913 i valori in dB/100 ft sono convertiti in dB/100 m";
                case "Tasker": return "Tasker (MILAN S.r.l.), schede tecniche RG 174, RG 58 CU / PUR, RG 223 U, RG 213 U, C526, C527, C529 e C538 (copie presso i distributori: komplekt-a.ru, chipdip.ru, deep-sound.ru, ormix.lv, triopak.fi)";
                case "messi.it": return "Messi & Paoloni, schede tecniche Airborne, Hyperflex e Ultraflex e catalogo dei cavi a 50 Ω 2026 (messi.it)";
                case "ssb.de": return "SSB-Electronic, schede tecniche SeaTex, Aircell 7 e Aircom Premium e catalogo dei cavi (ssb.de)";
                case "DD1US / EA5IP": return "Tabelle dei cavi coassiali di DD1US (dd1us.de, 27/04/2024) ed EA5IP (qsl.net/ea5ip): 5,5 dB a 144 MHz e 9,1 dB a 432 MHz; costruttore non indicato";
                case "Prospecta RT5020": return "Prospecta, scheda tecnica RT5020 (radiosystem.it)";
                case "Prospecta XT2400": return "Prospecta, scheda tecnica XT-2400 (hamradioshop.it)";
                case "Qaxial": return "QAXIAL, scheda tecnica LLF195 (qaxial.com, rf-microwave.com)";
                case "Caledonian MIL-C-17": return "Caledonian Cables, catalogo MIL-C-17F 50 Ω: RG 142 B/U (M17/60) e RG 393/U (M17/127) (caledonian-cables.net)";
                case "R.F. elettronica": return "R.F. elettronica di Rota Franco (Senago), scheda tecnica RG115 (rf-microwave.com)";
                default: return breve;
            }
        }

        public static string PercorsoPersonali { get { return Dati.Percorso("cavi_personali.txt"); } }

        // Cavi aggiunti dall'utente: una riga "nome;diametro;db50;db70;db144;db222;db432"
        public static void CaricaPersonali()
        {
            Elenco.RemoveAll(c => c.Personale);
            try
            {
                if (!File.Exists(PercorsoPersonali)) return;
                foreach (string riga in File.ReadAllLines(PercorsoPersonali, Encoding.UTF8))
                {
                    string[] p = riga.Split(';');
                    if (p.Length < 7 || p[0].Trim().Length == 0) continue;
                    Cavo c = new Cavo();
                    c.Nomi = new string[] { p[0].Trim() };
                    c.Costruttori = new string[] { Lang.T("personalizzato") };
                    c.Tipo = "personale";
                    c.Anche = "";
                    c.Fonti = new string[] { Lang.T("inserito dall'utente") };
                    c.Personale = true;
                    double.TryParse(p[1], NumberStyles.Float, CultureInfo.InvariantCulture, out c.Diam);
                    for (int i = 0; i < 5; i++)
                    {
                        double.TryParse(p[2 + i], NumberStyles.Float, CultureInfo.InvariantCulture, out c.Db[i]);
                        c.Segno[i] = 'm';
                    }
                    Elenco.Add(c);
                }
            }
            catch { }
        }

        public static void SalvaPersonali()
        {
            try
            {
                List<string> l = new List<string>();
                foreach (Cavo c in Elenco)
                    if (c.Personale)
                    {
                        StringBuilder sb = new StringBuilder(c.Nome.Replace(";", ","));
                        sb.Append(";" + c.Diam.ToString(CultureInfo.InvariantCulture));
                        foreach (double v in c.Db) sb.Append(";" + v.ToString(CultureInfo.InvariantCulture));
                        l.Add(sb.ToString());
                    }
                File.WriteAllLines(PercorsoPersonali, l.ToArray(), Encoding.UTF8);
            }
            catch { }
        }

        public static Cavo Trova(string nome)
        {
            foreach (Cavo c in Elenco) if (c.Nome == nome) return c;
            foreach (Cavo c in Elenco) if (Array.IndexOf(c.Nomi, nome) >= 0) return c;
            return null;
        }

        public static int Indice(string nome)
        {
            Cavo c = Trova(nome);
            return c == null ? -1 : Elenco.IndexOf(c);
        }
    }


    // Capitoli nuovi del manuale (v27) nelle lingue del programma; marcatura descritta in CostruisciManuale
    static class ManualeV27
    {
        static readonly Dictionary<string, Dictionary<string, string[]>> d = new Dictionary<string, Dictionary<string, string[]>>();
        static ManualeV27()
        {
            d["it"] = new Dictionary<string, string[]>();
            d["it"]["S32"] = new string[] {
                "## Il locator Maidenhead (WWL)",
                "Il **locator Maidenhead**, detto anche WWL (World Wide Locator) o QTH locator, è il codice con cui i radioamatori indicano la posizione della stazione. Lo ha ideato John Morris G4ANB ed è stato adottato dal Gruppo di lavoro VHF della IARU nell'aprile 1980, in una riunione a Maidenhead, in Inghilterra; ha sostituito il vecchio QRA locator, che copriva solo l'Europa [1]. Dal 1999 il riferimento geodetico è il WGS-84, lo stesso del GPS [1]. YAEC ricava dal locator latitudine e longitudine della stazione, e da queste tutti i calcoli.",
                "### Com'è fatto",
                "Il locator è una serie di coppie: ogni coppia indica prima la longitudine e poi la latitudine, e divide il rettangolo della coppia precedente in parti più piccole. Le coppie alternano lettere e cifre [1]. Esempio a 14 caratteri: **PM 95 UP 98 KB 75 MI** (Tokyo).",
                "@locator PM 95 UP 98 KB 75 MI",
                "|h| Coppia | Nome | Simboli | >Divide in | >Dimensione (lon × lat) | >Caratteri | >Lato a 35,7° (Tokyo) | >Errore massimo",
                "| 1ª | campo (field) | A … R | 18 × 18 | 20° × 10° | 2 | – | –",
                "| 2ª | quadrato (square) | 0 … 9 | 10 × 10 | 2° × 1° | 4 | 181 × 111 km | ±106 km",
                "| 3ª | sottoquadrato (subsquare) | A … X | 24 × 24 | 5′ × 2,5′ | 6 | 7,5 × 4,6 km | ±4,4 km",
                "|+ 4ª | quadrato esteso | 0 … 9 | 10 × 10 | 30″ × 15″ | **8** | 753 × 463 m | **±442 m**",
                "| 5ª | sottoquadrato esteso | A … X | 24 × 24 | 1,25″ × 0,625″ | **10** | 31 × 19 m | **±18 m**",
                "| 6ª | – | 0 … 9 | 10 × 10 | 0,125″ × 0,0625″ | 12 | 3,1 × 1,9 m | ±1,8 m",
                "| 7ª | – | A … X | 24 × 24 | 0,0052″ × 0,0026″ | 14 | 13 × 8 cm | ±8 cm",
                "~ Dimensioni dalle regole di [1]; lati ed errore massimo (metà della diagonale, con la stazione nel centro della casella) calcolati da YAEC per la latitudine di Tokyo: verso i poli il lato est-ovest si accorcia. Le lettere si scrivono in maiuscolo, come chiarito dalla IARU nel 2019 [1]; YAEC accetta anche le minuscole e le converte.",
                "> Oltre gli 8 caratteri non esiste uno standard comune: la 5ª coppia e le seguenti non sono definite formalmente, e la pratica più diffusa, quella seguita da YAEC, ripete le regole delle coppie precedenti (lettere in base 24, cifre in base 10). Altri programmi possono usare codifiche diverse, quindi un locator lungo potrebbe non essere letto allo stesso modo ovunque [1].",
                "### Quanti caratteri usare",
                "Nelle HF si usa di solito il quadrato (4 caratteri); nelle bande di YAEC, da 50 a 432 MHz, si usa il sottoquadrato (6 caratteri) [1]. Per lo scambio dei QSO e per i contest valgono queste regole: per esempio, nella Regione 1 IARU le distanze si misurano tra i centri dei sottoquadrati [1]. Per i calcoli di YAEC la scelta è diversa:",
                "|h| Caratteri | Uso consigliato in YAEC",
                "| 4 | solo per una stima grossolana: l'azimut e l'elevazione della Luna possono sbagliare fino a circa 1°, perché l'orizzonte locale si inclina di circa 1° ogni 111 km",
                "| 6 | il locator del DX, i QSO e il Budget EME: l'errore sulla direzione della Luna è di pochi centesimi di grado",
                "| **8** | la tua stazione, per la Ricognizione dei miei ostacoli: individua il quartiere o la collina",
                "|+ **10** | la tua stazione, con la massima resa: individua l'edificio o il traliccio dell'antenna",
                "| 12 – 14 | accettati, ma non aggiungono nulla: la precisione supera quella di un GPS comune (qualche metro) e le dimensioni dell'antenna stessa",
                "### Locator e ostacoli",
                "Per la direzione della Luna bastano 6 caratteri: la Luna è a circa 380 000 km, e i ±4,4 km di un locator a 6 caratteri cambiano azimut ed elevazione di circa 0,04°, una quantità trascurabile rispetto al fascio dell'antenna. Per gli **ostacoli locali** (edifici, alberi, colline) è il contrario: sono a poche decine o centinaia di metri dall'antenna, e con 6 caratteri la stazione può trovarsi ovunque in un rettangolo di 7,5 × 4,6 km, quindi gli ostacoli non si possono collocare. Con 8 caratteri l'errore scende a circa 450 m, con 10 a circa 20 m: è la precisione che serve alla linguetta **Ricognizione dei miei ostacoli** per disegnare correttamente le zone in cui l'antenna è coperta.",
                ">+ Consiglio pratico: ricava il locator a 10 caratteri dalle coordinate GPS del punto in cui sta l'antenna (non dell'ingresso di casa) e inseriscilo nella linguetta Posizione live e +- 24h come **locator mio**. Al DX basta il locator a 6 caratteri che ti comunica.",
                "[1] Wikipedia, “Maidenhead Locator System” (origine G4ANB e riunione IARU VHF di Maidenhead del 1980, struttura delle coppie, WGS-84 dal 1999, estensioni oltre gli 8 caratteri, chiarimento IARU 2019, uso in HF e VHF/UHF, distanze tra centri dei sottoquadrati) – https://en.wikipedia.org/wiki/Maidenhead_Locator_System"
            };
            d["it"]["S46"] = new string[] {
                "### Le formule del Budget EME",
                "La perdita di tratta segue l'equazione del radar: il segnale va dalla stazione alla Luna, una parte viene diffusa e torna verso la Terra. Le distanze §d_1§ e §d_2§ sono quelle topocentriche delle due stazioni all'istante scelto, quindi la differenza tra perigeo e apogeo (circa 2,3 dB) è già compresa.",
                "= λ = \\frac{c}{f} \\quad σ = 0,065 · π · R_L^2",
                "= L_{EME} = 10 · log_{10} \\b{\\frac{\\p{4π}^3 · d_1^2 · d_2^2}{σ · λ^2}} \\t{ dB}",
                "~ con §c = 299 792 458 \\t{ m/s}§, §R_L = 1 737,4 \\t{ km}§ (raggio della Luna), riflettività lunare 0,065.",
                "La potenza irradiata e il segnale ai morsetti dell'antenna ricevente:",
                "= EIRP = P_{dBW} − L_{TX} + G_{ant} + 10 · log_{10} N + G_g \\quad S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                "= G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}} \\quad L_{pol} = −20 · log_{10} \\a{cos D_{pol}}",
                "~ Ground gain (casella «BETA- antenna senza elevazione»): antenna a polarizzazione orizzontale all'altezza h, calcolato all'elevazione della Luna, al massimo +6 dB.",
                "La figura di rumore della catena di ricezione si ottiene con la formula di Friis, in valori lineari (§F = 10^{NF/10}§, §G = 10^{G_{dB}/10}§):",
                "= F_{tot} = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + … \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "La figura di rumore della radio è ricavata dal suo MDS, misurato nella banda B:",
                "= NF_{radio} = MDS + 174 − 10 · log_{10} B",
                "= T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e \\quad N = 10 · log_{10} \\p{k · T_{sys} · B} + 30 \\quad \\frac{S}{N} = S_{ant} − N",
                "~ con §k = 1,380649 · 10^{−23} \\t{ J/K}§ (Boltzmann) e B larghezza di banda in Hz. §T_{ant}§ è la temperatura d'antenna delle tabelle VE7BQH (antenna inclinata a 30°); §ΔT_{sky} = max \\p{0, T_{sky} − T_{rif}}§, con §T_{rif}§ = 200 K a 144 MHz scalato con indice 2,6.",
                "Il Budget EME non calcola un margine sul modo: mostra l'S/N stimato riportato alla banda di riferimento di 2500 Hz usata da WSJT-X e, accanto, la soglia tipica del modo scelto solo come riferimento. Una soglia non è un limite netto: con gli aiuti del decodificatore si decodifica anche più in basso, come mostrano la tabella del JT65 e le note qui sotto.",
                "= \\frac{S}{N}_{2500} = \\frac{S}{N}_{B} + 10 · log_{10} \\frac{B}{2500}",
                "|h| Modo | >Soglia tipica, messaggio singolo (2500 Hz) | Fonte",
                "| JT65 | −25 dB | [1]",
                "| JT9 | −27 dB | [1]",
                "| JT4 | −23 dB | [1]",
                "| FT8 | ≈ −20 dB | [1]",
                "| FT4 | ≈ −16,5 dB | [1]",
                "| Q65-15A | −22,2 dB | [2]",
                "| Q65-30A | −24,8 dB | [2]",
                "| Q65-60A | −27,6 dB | [2]",
                "| Q65-120A | −30,8 dB | [2]",
                "| Q65-300A | −33,8 dB | [2]",
                "| WSPR | −31 dB | [1]",
                "~ Soglie al 50 % di probabilità di decodifica, misurate su canale a rumore bianco (AWGN). Per il Q65 la decodifica *a priori* (AP), che sfrutta i nominativi già noti durante il QSO, aggiunge da 1,5 a 3,6 dB secondo il sottomodo (per esempio Q65-60A −30,2 dB) [2]; YAEC mostra come riferimento i valori senza AP, più prudenti. Con un Doppler spread di alcuni hertz la soglia peggiora: per il Q65-60A di circa 2 dB a 5 Hz e di circa 3 dB a 10 Hz (letti dal grafico di [2]). Struttura del Q65, sottomodi e confronto con il JT65 sono nel § 3.12. Per l'EME il documento consiglia Q65-60A in 50 e 144 MHz e Q65-60B in 432 MHz [2]: i sottomodi B – E hanno spaziatura dei toni e banda occupata 2 – 16 volte quelle del sottomodo A.",
                "Per il JT65 K1JT ha pubblicato i limiti per ogni tipo di decodifica, ottenuti con simulazioni del sottomodo JT65B [5]:",
                "|h| JT65: tipo di decodifica | >S/N (2500 Hz) | Fonte",
                "| Messaggio qualsiasi, anche testo libero | −24 dB | [5]",
                "| Nominativo presente nel database (Deep Search) | −28 dB | [5]",
                "| Messaggio qualsiasi con la media di più trasmissioni | −29 dB | [5]",
                "| Sola sincronizzazione (tempo e frequenza) | −30 dB | [5]",
                "| Messaggi brevi RO, RRR, 73 | −32 dB | [5]",
                "~ La guida di WSJT-X dà −25 dB per il messaggio singolo [1]. La Deep Search prova solo i messaggi con CQ o con il tuo nominativo e un nominativo e locator del database: un nominativo sconosciuto o un testo libero si decodificano solo con il decodificatore generale, con la media se serve [5]. La decodifica è «tutto o niente»: un messaggio si legge intero o per niente, non peggiora a poco a poco avvicinandosi al limite [5]. Per questo YAEC non segnala più i dB sopra o sotto la soglia.",
                "### Il ground gain nella pratica",
                "Il ground gain della casella «BETA- antenna senza elevazione» segue il modello del terreno piano e riflettente: il raggio diretto e quello riflesso si sommano quando la differenza di percorso è un numero semi-intero n di lunghezze d'onda e si annullano quando è intero, con §n · λ = 2 · H · sin α§; il punto di riflessione è a una distanza §D = \\frac{H}{tan α}§ dall'antenna [3]. Le prove di IK1UWL con gli echi della sua stazione (4 × 14 elementi a 121 m sul mare, costa ligure) mostrano che in pratica le cose sono più complicate [3]:",
                "• i picchi e i nulli sono molti e ravvicinati, ad angoli frazionari che un simulatore a passi di 1° come EZNEC non vede: con l'antenna alta sul mare si succedono ogni 3 minuti circa (3 periodi JT65) e causano un forte QSB a bassa elevazione, che non dipende dalla ionosfera;",
                "• il guadagno misurato è stato di circa 3 dB, non i 6 dB teorici: in un array le yagi superiori e inferiori sono a quote diverse (4,5 m), le loro riflessioni non sono in fase e contribuisce una sola coppia alla volta;",
                "• sotto i 2° di elevazione c'è un buco di guadagno e il massimo è intorno a 5°; elevando l'antenna l'effetto suolo cala e oltre la larghezza del lobo (circa 12° per il suo array) diventa trascurabile;",
                "• la rifrazione conta: la Luna è sorta a −0,51°, sotto l'orizzonte ottico di −0,35°; a 200 MHz, in aria secca, l'errore di rifrazione a 0° di elevazione è di −0,49°.",
                "IK3XTV ricorda che in teoria l'effetto suolo arriva a 6 dB, tanto che una singola yagi rende quasi come un array di 4, ma dipende molto dal terreno attorno all'antenna: è minore in città, migliore in aperta campagna e ancora di più vicino al mare. Si sfrutta al sorgere e al tramonto della Luna, tra circa 1° e 18 – 20° di elevazione [4].",
                "> Per questo nel Budget EME il ground gain è indicato come BETA: il valore calcolato (al massimo +6 dB) è un limite teorico. Con antenne alte sul mare o array di più yagi conviene aspettarsi circa la metà e un QSB marcato a bassa elevazione [3].",
                "[1] WSJT-X User Guide, K1JT e WSJT Development Group, § 7.1 (FT4 = FT8 + 3,5 dB).",
                "[2] J. Taylor K1JT, B. Somerville G4WJS, S. Franke K9AN, N. Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 aprile 2021 (WSJT-X 2.4.0), fornito da IC8TEM.",
                "[3] Giorgio Marchi IK1UWL, “Considerazioni sull'effetto suolo (Ground Gain)”, XXI Meeting EME, presentazione fornita da IC8TEM.",
                "[4] Flavio Egano IK3XTV, “EME (earth-moon-earth) con una singola Yagi in 144 MHz”, documento del 12 novembre 2010, fornito da IC8TEM.",
                "[5] J. Taylor K1JT, relazione sul JT65 alla conferenza EME 2006 (K1JT_eme2006.pdf): tabella dei livelli minimi di S/N in 2500 Hz.",
                "> Lo schema dell'impianto, a destra nella linguetta, ricava le perdite dai cavi scelti: in trasmissione cavo PA–relè + relè + cavo antenna, in ricezione cavo antenna + relè prima del preamplificatore e cavo di discesa dopo. Le attenuazioni dei cavi vengono dal database della linguetta CAVI COASSIALI (§ 3.8)."
            };
            d["it"]["S47"] = new string[] {
                "## Il preamplificatore e la figura di rumore della radio {nuovo}",
                "In EME il segnale che arriva all'antenna è di poco superiore al rumore (circa −149 dBm nell'esempio Tokyo – Cape Town). Il preamplificatore serve a due cose diverse: **recuperare il segnale** perso nei cavi verso la stazione e, soprattutto, **coprire la figura di rumore della radio**, che sui ricetrasmettitori commerciali in VHF/UHF va da circa 3 – 5 dB con il preampli interno acceso a 15 – 16 dB e oltre con il preampli spento.",
                "Il motivo sta nella formula di Friis: ogni stadio pesa sul rumore totale diviso per il guadagno di tutto ciò che lo precede. Il primo stadio decide quasi tutto.",
                "= F_{tot} = F_{LNA} + \\frac{F_{cavo} − 1}{G_{LNA}} + \\frac{F_{radio} − 1}{G_{LNA} · G_{cavo}} \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "~. F e G in valori lineari (§F = 10^{NF/10}§); per un cavo con perdita L in dB: §F_{cavo} = 10^{L/10}§ e §G_{cavo} = 10^{−L/10}§.",
                "@colonne 55",
                "#### Figura di rumore misurata di alcune radio",
                "|h| Radio | >MHz | Preampli | >NF (dB) | Fonte",
                "| Icom IC-9700 | 144 | spento / acceso | 16 / 3 | [1]",
                "| Icom IC-9700 | 432 | spento / acceso | 15 / 4 | [1]",
                "| Yaesu FT-991 | 50 | IPO / AMP1 / AMP2 | 29 / 17 / 8 | [2]",
                "| Yaesu FT-991 | 144 · 432 | – | 5 · 4 | [2]",
                "| Icom IC-275E | 144 | – | 5,6 | [3]",
                "| Icom IC-9100 | 144 · 432 | non indicato | ≈ 5 · ≈ 5 | [5]{r:*}",
                "| Icom IC-821H | 144 | – | 3,4 | [3]",
                "| Icom IC-910H | 144 | – | 3,7 | [3]",
                "| Icom IC-7000 | 144 | – | 5,6 | [3]",
                "| Kenwood TS-790E | 144 | – | 4,5 | [3]",
                "| Kenwood TS-2000 | 144 | acceso | 6,2 | [3]",
                "| Yaesu FT-847 | 144 | acceso / spento | 5,1 / 6,7 | [3]",
                "| Yaesu FT-817 | 144 | – | 5,4 | [3]",
                "| Yaesu FT-857D | 144 | – | 6,1 | [3]",
                "| Icom IC-746PRO | 50 | spento / P1 / P2 | 19 / 9 / 6 | [14]",
                "| Icom IC-746PRO | 144 | spento / acceso | 14 / 5,2 | [14]",
                "| Yaesu FT-897 | 50 | acceso / IPO | 3,6 / 8,7 | [15]",
                "| Yaesu FT-897 | 144 · 432 | sempre acceso | 5,9 · 7,7 | [15]",
                "~ [1] [2] misure di VA7OJ con sorgente di rumore calibrata; [3] misure DF9IC con il metodo del fattore Y, precisione ±0,5 dB, solo 144 MHz, dal 2005. Con il preampli interno acceso l'IC-9700 va in saturazione già da −9 a −27 dBm a 144 MHz [1]. * Valore da verificare: prova preliminare su un esemplare di pre-produzione, senza autore indicato. [14] NF ricavata dal rumore di fondo (MDS) misurato in 500 Hz: NF = MDS + 174 − 27 dB; con il preampli acceso a 144 MHz la dinamica di bloccaggio a 5 kHz scende da 99,9 a 88,4 dB. [15] NF ricavata dalla sensibilità SSB per 10 dB (S+N)/N con il filtro da 2450 Hz: NF = S − 9,5 + 174 − 10·log B; in 144 e 432 MHz il preampli è sempre inserito. Per [14] e [15] la precisione è indicativa, ±1 dB.",
                "@destra",
                "#### Esempio: 35 m di Sivacavi HF 400 (1,6 dB) a 144 MHz",
                "|h| Configurazione | >NF tot | >Te | >Tsys | >Peggiora S/N di",
                "| Radio sola, preampli interno spento (NF 16) | 17,6 dB | 16 398 K | 16 648 K | %bar:17.6:17.6:r%17,6 dB",
                "| Radio sola, preampli interno acceso (NF 3) | 4,6 dB | 546 K | 796 K | %bar:4.4:17.6:o%4,4 dB",
                "| LNA in antenna 0,5 dB / 20 dB + radio NF 16 | 2,3 dB | 199 K | 449 K | %bar:1.9:17.6:y%1,9 dB",
                "| **LNA in antenna 0,5 dB / 20 dB + radio NF 3** | **0,6 dB** | 41 K | 291 K | %bar:0:17.6:g%{g:**riferimento**}",
                "~ §T_{sys} = T_{ant}§ 250 K + §T_e§; il confronto è fatto a parità di segnale all'antenna.",
                "@fine",
                "Per la configurazione migliore, con i valori sostituiti:",
                "= F_{tot} = 1,1220 + \\frac{1,4454 − 1}{100} + \\frac{1,9953 − 1}{100 · 0,6918} = 1,1220 + 0,0045 + 0,0144 = 1,1409 \\quad ⇒ \\quad NF = 0,57 \\t{ dB}",
                ">! **In pratica.** Il preamplificatore va montato in antenna, prima del cavo di discesa e subito dopo il relè coassiale (che deve proteggerlo in trasmissione con un sequencer). Il suo guadagno deve essere abbastanza alto da rendere trascurabili il cavo e la radio: come regola, almeno 10 dB più della somma di perdita del cavo e figura di rumore della radio (nell'esempio 1,6 + 16 ≈ 18 dB → con 20 dB la radio pesa ancora 1,7 dB; con il preampli interno acceso pesa solo 0,05 dB). Troppo guadagno però riduce la dinamica della radio: con un buon LNA in antenna conviene spesso tenere spento il preampli interno e scegliere un LNA da 20 – 26 dB. Nel Budget EME queste scelte si fanno nello schema dell'impianto di ricezione, e la linguetta DEBUG FORMULE mostra il calcolo passo per passo.",
                "##+ Il transverter (facoltativo)",
                "Con un transverter la radio lavora a media frequenza (di solito 28 MHz per i 144 MHz) e il transverter diventa lo stadio che conta per il rumore: entra nella formula di Friis dopo il cavo di discesa, e la radio che lo segue pesa meno quanto più il transverter guadagna.",
                "= F_{comb} = F_{XV} + \\frac{F_{radio} − 1}{G_{XV}} \\quad \\t{es. } F_{comb} = 1,2589 + \\frac{10 − 1}{50,12} = 1,4385 ⇒ NF = 1,58 \\t{ dB}",
                "~ esempio: transverter con NF 1,0 dB e guadagno 17 dB (valori minimi del DEMI L144-28) davanti a una radio HF con NF 10 dB.",
                "@colonne 56",
                "#### Abaco: NF della combinazione al variare della radio e del guadagno del transverter",
                "@abaco Curve calcolate con la (3.7.3) per un transverter con NF 1,0 dB. Più il transverter guadagna, meno pesa la radio: con 25 dB di guadagno una radio con 20 dB di NF porta il totale a 2,0 dB; con 10 dB di guadagno la stessa radio porta il totale a 10,5 dB.",
                "@destra",
                "#### Transverter per 144 MHz (IF 28 MHz)",
                "|h| Costruttore · modello | >NF | >G RX | >TX | Fonte",
                "| DEMI L144-28 | < 1,0 dB | ≥ 17 dB | 25 / 50 W | [6]",
                "|+ **Kuhne (DB6NT) MKU 144 G2** (modulo) | 0,9 dB | 25 dB | 0,1 W¹ | [13]",
                "| Kuhne (DB6NT) TR 144 H +40 | 0,9 – 1,2 dB | 25 dB | 2 – 20 W | [7]",
                "| Kuhne (DB6NT) TR-144 Pro | {r:n.d.} | {r:n.d.} | 25 W | [8]",
                "| Q5 Signal L144-28M | < 1,0 dB | ≥ 20 dB | 25 / 75 / 150 W | [9]",
                "| HA1YA ME2T-PRO-II / ME2HT-PRO-II | 1,0 dB | ≤ 25 dB (regolabile) | 30 / 50 W | [10]",
                "| SSB-Electronic LT2S Mk II | {r:n.d.} | {r:n.d.} | – | [11]",
                "~ Valori dichiarati dai costruttori. MKU 144 G2: primo stadio con NF 0,5 dB, IP3 d'uscita in ricezione +23 dBm, IF in ingresso 2 – 50 mW o 60 – 2000 µW; ¹ pilota da 100 mW, da completare con un amplificatore Kuhne da 60 o 120 W. TR 144 H +40: contiene il modulo MKU 144 G2, da cui il guadagno di 25 dB (indicazione di IC8TEM). Con 25 dB di guadagno, davanti a una radio con NF 10 dB il totale è 0,99 dB, con NF 20 dB è 1,88 dB [13]. Il manuale Kuhne indica 1,2 dB nella tabella e 0,9 dB nel testo; con il preampli Kuhne MKU LNA 144 A il totale scende a 0,3 dB [7]. Q5 Signal L144-28M: NF massima 1,0 dB con guadagno di conversione minimo 20 dB, guadagno RX-IF regolabile dall'utente per tarare lo S-meter; IF fino a 25 W [9]. HA1YA ME2T-PRO-II: NF complessiva 1 dB (primo stadio PGA103+ con NF 0,7 dB), guadagno RX fino a 25 dB regolabile, OIP3 tipico +35 dBm, IIP3 tipico +10 dBm, reiezione d'immagine > 80 dB, IF in ingresso da −20 a +37 dBm [10].",
                "#### Combinazioni misurate (DF9IC, 144 MHz)",
                "|h| Radio + transverter | Preampli radio | >NF",
                "| Elecraft K2 + Kuhne TR144H+40 | – | 1,0 dB",
                "| IC-756PRO II + Kuhne TR144H | spento | 1,0 dB",
                "| IC-746 + Kuhne TR144H+40 | spento | 1,2 dB",
                "| FT-1000MP + Javornik (due esemplari) | spento | 0,9 · 1,4 dB",
                "| FT-1000 Mark V + Kuhne TR144H, IF 14 MHz | spento | 1,6 dB",
                "| FT-1000 Mark V + Kuhne TR144H, IF 28 MHz | spento / acceso | 6,0 / 1,7 dB",
                "| TS-870 + Javornik | spento | 1,9 dB",
                "| Elecraft K2 + XV144 | acceso | 6,0 dB",
                "~ Fonte [3]. Il caso FT-1000 Mark V a 28 MHz mostra l'abaco in pratica: con il preampli della radio spento la radio pesa molto (6,0 dB), con il preampli acceso si scende a 1,7 dB.",
                "@fine",
                "##+ Stazioni EME con FT-1000MP e transverter",
                "Due esempi documentati di FT-1000MP usato per l'EME in 144 MHz con un transverter: le misure di DF9IC [3] su FT-1000MP + transverter Javornik (NF 0,9 – 1,4 dB con il preampli della radio spento) e la stazione EME di **W3SZ** [12] (4 × M2 2MXP32, preampli LNA Technology in antenna per ogni polarizzazione, LMR-600 e linee rigide Andrew), che in trasmissione usa un **FT-1000MP Mark V** con transverter **SSB-Electronic LT2S Mk II** (IF 28 MHz) e un amplificatore 2 × GU-74B, mentre in ricezione usa l'hardware WSE e il software Linrad di SM5BSZ.",
                "> Nel Budget EME il transverter è un riquadro dello schema dell'impianto: si attiva con la sua casella, si sceglie il modello dall'elenco (oppure \"personalizzato\") e il programma ne prende figura di rumore e guadagno; lasciato spento, non entra nel calcolo. L'abaco qui sopra aiuta a capire se conviene accendere il preampli della radio.",
                ">! ✉ **Conosci un altro transverter o ne hai costruito uno?** Se hai interesse a far conoscere altri transverter o il tuo transverter, scrivi una mail all'autore: ccerrotta@gmail.com oppure ic8tem@gmail.com. Tutti i recapiti sono nella linguetta **CONTATTI DELL'AUTORE E RINGRAZIAMENTI**.",
                "##+ Il sequenziatore TX/RX",
                "Con un amplificatore di potenza (PA) e un preamplificatore vicino all'antenna (PRE), il PTT del computer non va alla radio ma a un **sequenziatore**, che comanda i relè e poi il PA e la radio nell'ordine giusto [16]. Lo schema più usato ha due discese: quella di ricezione può perdere qualche dB, perché sta dopo un preampli da 15 – 20 dB, mentre quella di trasmissione deve perdere il meno possibile (3 dB in trasmissione dimezzano la potenza irradiata). I relè, a riposo, tengono il PRE isolato dall'antenna: una protezione in più contro le scariche dei temporali [16].",
                "|h| ^Passo | Da RX a TX | Da TX a RX",
                "| ^1 | i relè commutano a freddo: radio → ingresso del PA, antenna → uscita del PA, PRE isolato | la radio smette di trasmettere",
                "| ^2 | si accende il PA | si spegne il PA",
                "| ^3 | la radio va in trasmissione | i relè tornano in ricezione, senza potenza in gioco",
                "~ Tra un passo e l'altro serve almeno il tempo di commutazione dei relè (15 – 30 ms) più i loro rimbalzi: IK1UWL consiglia 100 – 200 ms, anche per il PA se ha relè interni [16].",
                "Per il comando di trasmissione il PTT è meglio del VOX: il VOX può scattare per un rumore e non sfrutta il ritardo di circa 0,5 s con cui JT65 comincia a modulare dopo il PTT, quindi il preamplificatore resta protetto solo dal relè veloce dell'amplificatore; con il PTT quel ritardo commuta l'amplificatore prima della modulazione e si può aggiungere il sequenziatore [17].",
                ">! **Attenzione al preamplificatore.** Il relè T/R deve isolare molto bene l'uscita aperta: con 50 dB di isolamento e 500 W all'antenna arrivano 5 mW all'ingresso del PRE. Si cerca di avere almeno 60 dB, e i più prudenti aggiungono un secondo relè che in trasmissione chiude il PRE su un carico da 50 Ω. Il pulsante PTT del microfono va disabilitato: da quel momento si trasmette solo attraverso il sequenziatore (per l'SSB, un comando a pedale sul PTT del sequenziatore, disaccoppiato da quello del PC) [16].",
                "[1] Adam Farson VA7OJ/AB4OJ, “Icom IC-9700 Test Report”, issue 5, 19 marzo 2021 (prima edizione 19 giugno 2019), tabelle 1 e 5 – https://www.qsl.net/ab4oj/icom/ic9700/9700notes.pdf",
                "[2] Adam M. Farson VA7OJ/AB4OJ, “Yaesu FT-991 Test Report”, 25 luglio 2015, tabella 1 – https://www.qsl.net/ab4oj/test/docs/ft991notes.pdf",
                "[3] DF9IC con DARC OV Durlach A35, “Test of the Large Signal Behaviour of some 144 MHz Radios”, prove dal 27 febbraio 2005 – https://www.df9ic.de/tech/trxtest/trxtest.html",
                "[4] H. T. Friis, “Noise Figures of Radio Receivers”, Proceedings of the IRE, vol. 32 (1944).",
                "[5] Prova preliminare “ICOM IC-9100 review” su esemplare di pre-produzione prestato da Icom UK (autore e data non indicati) – https://manualmachine.com/icom/ic9100/26837637-review",
                "[6] Down East Microwave, “L144-28 Rev B” – manuale d'uso (specifiche: NF < 1,0 dB con guadagno di conversione ≥ 17 dB) – https://manualmachine.com/demi/l14428revb/26842141-user-guide",
                "[7] Kuhne electronic, “TR 144 H +40” – manuale d'uso – https://manuals.online/kuhne-electronic/transceiver/tr-144-h-40/user-manual/191pa",
                "[8] RigPix, “Kuhne TR-144 Pro” – https://rigpix.com/transverters/kuhne_tr144pro.htm",
                "[9] Q5 Signal, “VHF/UHF Transverters – L144-28M REV 2”, manuale (8 pagine), gennaio 2023, fornito da IC8TEM – http://q5signal.com/image/catalog/L144-28Mr2.pdf",
                "[10] HA1YA (Mechanics & Electronics), “ME2T-PRO-II & ME2HT-PRO-II 144MHz Transverter”, 25.09.2023, fornito da IC8TEM – http://www.ha1ya.hu/pdf/me2tpro2transverter.pdf",
                "[11] SSB-Electronic LT2S Mk II – citato in [12]",
                "[12] Roger Rehr W3SZ, descrizione della stazione EME – https://w3sz.com/EMEFrame1Source1.htm",
                "[13] Kuhne electronic GmbH, “MKU 144 G2 – Transverter module, 144 … 146 MHz, 28 … 30 MHz IF”, scheda tecnica (2 pagine), fornita da IC8TEM",
                "[14] ARRL Laboratory, “Icom IC-746PRO”, QST Product Review, maggio 2002 – https://www.radiomanual.info/schemi/ICOM_HF/IC-746Pro_review_ARRL_2002.pdf",
                "[15] Peter Hart G3SJX, “The Yaesu FT-897 HF/VHF/UHF Transceiver”, RadCom (RSGB), aprile 2003, pp. 18–20 – http://www.radiomanual.info/schemi/YAESU_HF/FT-897_review2_2003.pdf",
                "[16] Giorgio Marchi IK1UWL, “EME (Earth-Moon-Earth) – Guida operativa”, gennaio 2012, § 4 «Sequenziamento relè, PA e PRE», fornita da IC8TEM – http://www.qsl.net/ik3xtv",
                "[17] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, presentazione, luglio 2015, fornita da IC8TEM."
            };
            d["it"]["S48"] = new string[] {
                "## Cavi coassiali e perdite",
                "La linguetta **CAVI COASSIALI** raccoglie l'attenuazione dei cavi a 50 Ω più usati dai radioamatori, in dB ogni 100 m a 20 °C, nelle cinque bande di YAEC. Le schede dei costruttori danno valori a frequenze diverse; YAEC li ha riportati alle bande con la legge di potenza, una retta sul grafico log-log tra le due frequenze più vicine della scheda:",
                "= α(f) = α_1 · \\p{\\frac{f}{f_1}}^{n} \\quad n = \\frac{log \\p{α_2 / α_1}}{log \\p{f_2 / f_1}} \\quad L = α(f) · \\frac{ℓ}{100}",
                "~ α in dB/100 m, ℓ lunghezza del cavo in metri. Il numero pieno è il valore della scheda; ≈ indica un valore interpolato, e uno estrapolato oltre l'ultima frequenza della scheda.",
                "I cavi con lo stesso tipo, diametro uguale entro ±0,2 mm e attenuazione entro 0,2 dB/100 m in tutte le bande sono accorpati in una riga (≡), con il valore medio; le sigle equivalenti sono indicate con \"anche:\" (per esempio LMR-400 = HF400, CNT-400, 50-7 low loss; LMR-600 = CNT-600). Le sigle cinesi 50-3, 50-5, 50-7, 50-9, 50-12 indicano il diametro del dielettrico in millimetri.",
                "> Si possono aggiungere cavi personalizzati con le loro cinque attenuazioni: vengono salvati in data\\cavi_personali.txt e compaiono anche nelle tendine dello schema dell'impianto del Budget EME. Il fumetto di ogni riga della tabella cita la fonte di quel cavo.",
                "[1] Le fonti dei singoli cavi: schede di Times Microwave (LMR), RFS (CELLFLEX LCF/SCF), CommScope Andrew (HELIAX LDF/FSJ), Siva Cavi (HF 240/287/400), SSB-Electronic (Aircell, Ecoflex, Aircom Plus), Messi & Paoloni (Hyperflex, Ultraflex, tramite WiMo), Symair, SYV50-7 (szansy.com), Belden (H1000), Prospecta (RT5020, XT2400), QAXIAL (LLF195), Caledonian Cables, catalogo MIL-C-17F (RG-142, RG-393), R.F. elettronica di Senago (RG-115), le tabelle di DD1US ed EA5IP (H100) e la tabella di SV1BSX per RG-58, RG-213, H-155 e H-2000 (valori da verificare)."
            };
            d["it"]["S410"] = new string[] {
                "## Il Doppler, la compensazione e il CFOM",
                "La Luna si avvicina e si allontana dalle due stazioni per effetto della rotazione terrestre e del suo moto orbitale: la distanza R cambia di qualche centinaio di metri al secondo e il segnale torna spostato in frequenza. Lo spostamento è massimo quando la Luna sorge o tramonta, passa per zero quando transita a sud (o a nord) ed è proporzionale alla frequenza. YAEC lo calcola ogni secondo nella schermata principale, nel riquadro **Eco e frequenze (CFOM)**.",
                "### Quanto vale il Doppler",
                "Per l'eco della propria stazione il percorso si fa due volte (andata e ritorno):",
                "= f_{D,eco} = − \\frac{2f}{c} · \\frac{dR}{dt} \\quad \\t{es. } − \\frac{2 · 144,120 · 10^6}{299 792} · 0,222 = −213 \\t{ Hz}",
                "con f la frequenza in Hz, c = 299 792 km/s e dR/dt la velocità radiale della Luna in km/s (positiva se si allontana). Per il segnale del DX contano le due tratte, la sua e la tua:",
                "= f_{D,DX} = − \\frac{f}{c} · \\p{\\frac{dR_{io}}{dt} + \\frac{dR_{DX}}{dt}} \\quad \\t{es. } −480,7 · \\p{0,222 − 0,339} = +56 \\t{ Hz}",
                "~ esempio: Tokyo PM95 e Cape Town JF96, 06/11/2026 01:55 UTC, 144,120 MHz; dR/dt = +0,222 km/s a Tokyo e −0,339 km/s a Cape Town (valori YAEC).",
                "@colonne 62",
                "|h| Banda | >Doppler massimo dell'eco | >Compensazione",
                "| 50 MHz | ≈ ±120 Hz | non necessaria",
                "| 70 MHz | ≈ ±165 Hz | non necessaria",
                "| 144 MHz | fino a ≈ 340 Hz [1] | consigliata",
                "| 222 MHz | ≈ ±525 Hz | necessaria",
                "| 432 MHz | fino a ≈ 1000 Hz [1] | necessaria",
                "~ Valori per 144 e 432 MHz da [1]; 50, 70 e 222 MHz ricavati in proporzione alla frequenza (≈ = derivato).",
                "@destra",
                "> In 50 e 144 MHz il Doppler resta quasi sempre dentro la cascata del programma digitale e il decodificatore lo ritrova da solo; in 432 MHz può portare il segnale fuori dalla banda passante, e durante un periodo di 60 s cambia di qualche hertz, abbastanza da sembrare una deriva nei modi lenti [2].",
                "@fine",
                "### Compensare: chi corregge cosa",
                "Compensare il Doppler significa spostare la frequenza di trasmissione, di ricezione o entrambe, in modo che i segnali si incontrino sulla frequenza concordata (lo *sked*). Ogni stazione corregge il proprio Doppler e, quando lavora un DX, anche quello del DX [1]:",
                "|h| Situazione | Trasmissione | Ricezione",
                "| Chiamata CQ e ascolto del proprio eco | sulla frequenza dello sked | sked + Doppler dell'eco (3.10.1)",
                "| QSO con un DX noto (Doppler completo verso il DX) | corretta perché il DX ti riceva sullo sked | sked + Doppler DX → io (3.10.2)",
                "| CFOM, frequenza costante sulla Luna | sked − metà del proprio Doppler | sked + metà del proprio Doppler",
                "### CFOM – Constant Frequency On Moon",
                "Con il CFOM tutte le stazioni si comportano come se un trasmettitore virtuale sulla Luna fosse sintonizzato sullo sked: ognuna corregge solo metà del **proprio** Doppler in trasmissione e metà in ricezione, senza bisogno di conoscere il locator del corrispondente [2]:",
                "= f_{TX} = f_{sked} − \\frac{f_{D,eco}}{2} \\quad f_{RX} = f_{sked} + \\frac{f_{D,eco}}{2}",
                "|h| Esempio (Tokyo, Doppler dell'eco −213 Hz) | >Frequenza",
                "| Sked | 144.120,000 MHz",
                "| Trasmetti su (sked + 106,5 Hz) | {r:**144.120,107 MHz**}",
                "| Ricevi su (sked − 106,5 Hz) | {g:**144.119,894 MHz**}",
                "Il vantaggio è che più stazioni, e chiunque stia solo ascoltando, possono seguire un QSO sulla stessa frequenza senza ricalcolare il Doppler per ciascuna. YAEC mostra queste due frequenze nella schermata principale.",
                "### Il CAT della radio",
                "Il Doppler cambia di continuo, quindi la compensazione va aggiornata a ogni periodo. Il modo più semplice è lasciarla al programma digitale (per esempio la finestra *Astronomical Data* di WSJT-X) che, tramite il **CAT** della radio, regola i VFO di trasmissione e ricezione e mantiene la radio allineata alla frequenza giusta [1] [2]. Senza CAT si può usare lo split (un VFO per la trasmissione e uno per la ricezione) o il RIT, ritoccando a mano a ogni periodo: in 50 e 144 MHz è fattibile, in 432 MHz diventa scomodo [1].",
                "> Attenzione: per il CFOM la radio deve accettare il cambio di frequenza via CAT **anche durante la trasmissione**. Alcuni apparati non lo fanno (per esempio l'FT-897 citato in [2]): in quel caso si può comunque ricevere in CFOM, mentre la trasmissione resta a frequenza fissa. Con un transverter (§ 3.7) il CAT regola la radio a media frequenza: imposta nel programma lo scostamento del transverter, in modo che la frequenza mostrata sia quella reale.",
                "[1] Bob Atkins KA1GT, “Doppler 101 for 1296 MHz EME (…and other bands)” (dall'articolo sono usati solo i dati fino a 432 MHz) – https://bobatkins.com/radio/EME_doppler_101.html",
                "[2] Bob Atkins KA1GT, “CFOM – Constant Frequency On Moon Doppler Mode” – https://bobatkins.com/radio/CFOM.html"
            };
            d["it"]["S411"] = new string[] {
                "## Il puntamento: precisione, encoder e attuatori",
                "YAEC calcola azimut ed elevazione della Luna al centesimo di grado, ma il segnale arriva solo se l'antenna la segue davvero. Più il fascio è stretto, più conta la precisione meccanica del puntamento: nelle bande di YAEC (50 – 432 MHz) basta un buon rotore, mentre con i dischi delle bande superiori serve un vero sistema di attuazione.",
                "### Quanto si perde puntando male",
                "Con un errore di puntamento Δ e un fascio a metà potenza θ (stimato da YAEC con §θ ≈ \\sqrt{41253/G}§), la perdita si approssima con la formula del fascio gaussiano:",
                "= L_{punt} ≈ 12 · \\p{\\frac{Δ}{θ}}^2 \\t{ dB} \\quad \\t{es. } 12 · \\p{\\frac{3,6}{14,4}}^2 = 0,75 \\t{ dB}",
                "~ esempio: 4 yagi da 17 dBi in 144 MHz, guadagno totale 23 dBi, θ ≈ 14,4°; un errore di un quarto del fascio (3,6°) costa circa 0,75 dB. In EME la perdita si paga due volte, in trasmissione e in ricezione. Formula approssimata, valida per errori piccoli rispetto al fascio.",
                "### La risoluzione dell'encoder",
                "La posizione dell'antenna viene letta da un encoder (o da un potenziometro convertito in digitale): con n bit il giro completo si divide in §2^n§ passi e il passo più piccolo vale",
                "= Δ = \\frac{360°}{2^n} \\quad \\t{es. } n = 10: \\frac{360°}{1024} = 0,35°",
                "|h| ^Encoder | >Passi per giro | >Passo | >Perdita con l'array di 4 yagi (θ 14,4°, errore di 1 passo) | Adatto per",
                "| 8 bit | 256 | 1,406° | 0,114 dB | array di yagi in 50 e 144 MHz",
                "| 10 bit | 1.024 | 0,352° | 0,007 dB | 144 MHz con margine, 432 MHz con array piccoli",
                "| 12 bit | 4.096 | 0,088° | < 0,01 dB | 432 MHz con array grandi",
                "| 14 bit | 16.384 | 0,022° | < 0,01 dB | dischi a 10 e 24 GHz [1]",
                "| 16 bit | 65.536 | 0,005° | < 0,01 dB | oltre: limite dato dalla meccanica, non dall'encoder",
                "~ Passo e perdita calcolati con (3.11.2) e (3.11.1). Una regola pratica è tenere l'errore sotto un decimo del fascio: l'array di 4 yagi in 144 MHz si accontenta di 8 bit, un disco di 3 m a 10 GHz (fascio ≈ 0,7°) chiede almeno 13 – 14 bit.",
                "> Il numero di bit dice solo quanto finemente si *legge* la posizione: la precisione reale dipende anche dai giochi meccanici, dalla flessione del sostegno, dal vento e dalla taratura del nord e dell'orizzonte.",
                "### Array di yagi: attuatori e pulegge",
                "Negli array di yagi (accoppiamenti di 2, 4 o più antenne) il carico in elevazione è grande e sbilanciato. Sul mercato si trovano attuatori lineari con motore a vite senza fine: in queste soluzioni la vite serve solo a regolare il moto, mentre il sostegno meccanico del carico è affidato a pulegge. La vite senza fine ha il vantaggio di non girare all'indietro sotto il carico, così l'array resta fermo anche a motore spento.",
                "### Oltre i 432 MHz: i dischi",
                "Dai 902 MHz in su si usano soprattutto i dischi parabolici, e il tool [1] è pensato per le frequenze da 1 GHz in su. Con diametri importanti il fascio si restringe a pochi decimi di grado e c'è il rischio di non centrare perfettamente la Luna: più che di motori, la stazione ha bisogno di veri attuatori meccanici in azimut ed elevazione, con una precisione di puntamento legata in gran parte alla risoluzione in bit del comando. Il tool **EME Link Budget & Analysis Tool** di OE2IGL e DF3GJ [1] indica in ±0,035° un buon sistema di inseguimento e in ±0,1° uno normale, e calcola la perdita di puntamento insieme a tutti gli altri termini del collegamento.",
                ">+ YAEC si ferma ai 432 MHz. Per le bande superiori consigliamo il tool di OE2IGL e DF3GJ [1]: calcola il budget EME da 1 a 300 GHz con i parametri del disco (diametro, f/D, illuminatore, rugosità della superficie, efficienze), il puntamento, la librazione, il rumore del Sole e della Luna e l'attenuazione dell'atmosfera.",
                "[1] Gerald Ihninger OE2IGL e Joachim Köppen DF3GJ, “EME Link Budget & Analysis Tool (1-300 GHz)” – https://wettersat.bplaced.net/EME/EME.html"
            };
            d["it"]["S412"] = new string[] {
                "## I modi digitali per l'EME: Q65 e JT65",
                "Il Budget EME (§ 3.6) mostra l'S/N stimato accanto alla soglia tipica del modo digitale scelto. Questa sezione spiega da dove vengono le soglie del **Q65**, come è fatto il segnale e perché oggi il Q65 ha in gran parte sostituito il JT65 nell'EME delle bande di YAEC. I dati vengono da tre documenti: la guida rapida degli autori del Q65 [1], il confronto JT65A – Q65-60A di K1JT [2] e lo studio del processo di codifica di G4JNT [3].",
                "### Che cos'è il Q65",
                "Il Q65 è stato introdotto con WSJT-X 2.4.0 da K1JT, G4WJS, K9AN e IV3NWV per QSO minimi su percorsi particolarmente difficili; quando il Doppler spread supera qualche hertz è il più sensibile tra i modi di WSJT-X ed è adatto a troposcatter, rain scatter, scatter ionosferico, TEP ed EME dalle VHF in su [1]. Usa una modulazione FSK a **65 toni** e deriva dal QRA64 del 2016; rispetto a questo introduce [1]:",
                "• un nuovo codice correttore Q-ary Repeat Accumulate a basso rapporto, proposto da Nico Palermo IV3NWV [3] [4];",
                "• messaggi e sequenze identici a FST4, FT4, FT8 e MSK144;",
                "• un tono di sincronismo ben visibile sulla cascata e una «curva di sync» sensibile, efficace anche in presenza di ping di meteore;",
                "• sottomodi con periodi T/R di 15, 30, 60, 120 e 300 s e spaziature dei toni diverse;",
                "• una decodifica a liste per i messaggi che contengono parti già ricevute, **senza database di nominativi**;",
                "• la media dei messaggi, quando le singole trasmissioni sono troppo deboli, e la decodifica multipla su tutta la banda ricevuta.",
                "### I sottomodi",
                "Il nome del sottomodo unisce il periodo T/R e una lettera per la spaziatura dei toni: Q65-60A, Q65-120C e così via. Per i sottomodi A la tabella riporta le soglie misurate con simulazioni su canale a rumore bianco (AWGN), come S/N in 2500 Hz con il 50 % di probabilità di decodifica, senza e con la massima informazione *a priori* (AP) [1].",
                "|h| >T/R (s) | >Simbolo (s) | >Spaziatura A (Hz) | >Banda A (Hz) | >Trasmissione (s) | >S/N (dB) | >S/N max AP (dB)",
                "| 15 | 0,150 | 6,667 | 433 | 12,8 | −22,2 | −23,7",
                "| 30 | 0,300 | 3,333 | 217 | 25,5 | −24,8 | −26,6",
                "| 60 | 0,600 | 1,667 | 108 | 51,0 | −27,6 | −30,2",
                "| 120 | 1,333 | 0,750 | 49 | 113,3 | −30,8 | −32,5",
                "| 300 | 3,456 | 0,289 | 19 | 293,8 | −33,8 | −37,4",
                "~ Dati da [1]. I sottomodi B, C, D ed E hanno spaziatura e banda occupata 2, 4, 8 e 16 volte quelle del sottomodo A; non tutte le combinazioni esistono (per esempio 15D e 30E no) [1].",
                "I numeri della tabella seguono da poche relazioni, verificate da YAEC sui valori di [1]: la spaziatura del sottomodo A è l'inverso della durata del simbolo, la trasmissione dura 85 simboli e la banda occupata è di 65 spaziature.",
                "= Δf = \\frac{k}{t_s} \\quad k = 1, 2, 4, 8, 16 \\t{ (A … E)} \\quad T_{tx} = 85 · t_s \\quad B_{occ} = 65 · Δf",
                "~ esempio Q65-60A: §t_s§ = 0,600 s → Δf = 1,667 Hz, §T_{tx}§ = 51,0 s, §B_{occ}§ = 108 Hz. Passando da 60 a 120 s la soglia migliora di 3,2 dB, vicino ai 10 · log(113,3 / 51,0) = 3,5 dB attesi dalla trasmissione più lunga.",
                "### Sensibilità e Doppler spread",
                "Le soglie della tabella valgono senza allargamento del segnale. Nell'EME la Luna allarga ogni tono di qualche hertz (Doppler spread, o *libration fading*), e la soglia peggiora. Dal grafico di [1] per il Q65-60A senza AP:",
                "|h| >Doppler spread (Hz) | >S/N al 50 % (dB) | >Perdita (dB)",
                "| 0 | ≈ −27,4 | –",
                "| 5 | ≈ −25,6 | ≈ 1,8",
                "| 10 | ≈ −24,6 | ≈ 2,8",
                "| 20 | ≈ −23,2 | ≈ 4,2",
                "~ Valori letti da YAEC sulla figura 2 di [1] per interpolazione tra i punti (≈ = ricavato). La decodifica resta efficace fino a uno spread di circa dieci volte la spaziatura dei toni, e anche oltre [1]: per questo con spread maggiori si scelgono sottomodi con lettera più alta.",
                "> In YAEC le soglie di riferimento sono senza spread e senza AP: servono a confrontare giorni, bande e stazioni. Se sul tuo percorso il segnale è molto allargato, tieni conto della perdita della tabella, oppure imposta il modo *personalizzato* con la soglia corretta.",
                "### I messaggi del QSO a 60 s: Q65-60A, Q65-60B e Q65-60C",
                "In un QSO minimo i sei messaggi standard di WSJT-X (TX1 … TX6) non sono ricevuti tutti allo stesso modo: il decodificatore può usare le parti già note (decodifica *a priori*, AP) e la quantità di informazione nota cresce durante il QSO [1]. La tabella confronta i tre sottomodi più usati in EME con lo stesso periodo di 60 s.",
                "|h| Messaggio | Esempio | >AP in ricezione | >Q65-60A | >Q65-60B | >Q65-60C",
                "| TX6 – chiamata | CQ W9XYZ EN37 | >q1 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX1 – risposta con locator | W9XYZ K1ABC FN42 | >q2 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX2 – rapporto | K1ABC W9XYZ −25 | >q3 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX3 – R e rapporto | W9XYZ K1ABC R−26 | >q3 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX4 – conferma | K1ABC W9XYZ RRR | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| TX5 – saluti | W9XYZ K1ABC 73 | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| Spaziatura dei toni | – | – | >1,667 Hz | >3,333 Hz | >6,667 Hz",
                "| Banda occupata | – | – | >108 Hz | >217 Hz | >433 Hz",
                "| Spread ancora decodificabile (≈ 10 × spaziatura) | – | – | >≈ 17 Hz | >≈ 33 Hz | >≈ 67 Hz",
                "| Con 5 Hz di Doppler spread, senza AP | – | – | >≈ −25,6 | >perdita minore (n.d.) | >perdita minore (n.d.)",
                "~ S/N in dB riferiti a 2500 Hz, 50 % di probabilità di decodifica. −27,6 dB senza AP e −30,2 dB con l'AP massimo sono i valori del Q65-60A in [1]; per i sottomodi B e C sono ricavati dalla teoria: senza spread la sensibilità dipende dalla durata del simbolo (0,600 s), uguale nei tre sottomodi, e non dalla spaziatura. «n.d.» = non disponibile: [1] dà solo il guadagno massimo dell'AP (2,6 dB a 60 s), non quello dei livelli q1, q2 e q3, che è minore. Indicatori q1 … q4 come nella tabella del § «Impostazioni consigliate in WSJT-X»; spread decodificabile e valore a 5 Hz da [1] e dalla tabella del Doppler spread qui sopra. K1ABC, W9XYZ e i locator sono esempi.",
                ">! Questa tabella di confronto è derivata dall'analisi dei dati in nostro possesso sulla teoria di funzionamento del Q65 e non rispecchia per nulla ciò che avviene realmente, a causa del rumore naturale e antropico captato in diretta durante la ricezione.",
                "### Quale sottomodo per l'EME",
                "Per le bande di YAEC i sottomodi consigliati in [1] sono:",
                "|h| Uso | Sottomodo",
                "| EME in 50 e 144 MHz | Q65-60A",
                "| EME in 432 MHz | Q65-60B",
                "| Scatter ionosferico in 50 MHz | Q65-30A",
                "| Scatter ionosferico in 50 MHz con poca potenza | Q65-120E",
                "| TEP in 50 MHz | Q65-15C, Q65-30C",
                "| Scatter ionosferico in 144 MHz | Q65-60C",
                "~ Da [1], solo per le bande fino a 432 MHz. Gli autori invitano a sperimentare altre combinazioni.",
                "Il periodo di 30 s raddoppia la velocità del QSO con segnali relativamente forti, quello di 120 s guadagna circa 3 dB per singola trasmissione [2].",
                "### Q65 e JT65 a confronto",
                "Il **JT65A** è stato per quasi vent'anni il modo EME dei 6 metri: con la decodifica *Deep Search* arriva a −28 dB in 2500 Hz (−29 dB con la media dei messaggi, § 3.6), circa 15 dB sotto il livello necessario per il CW a orecchio, ma solo per i corrispondenti presenti nel database CALL3.TXT di nominativi e locator. In quei QSO l'informazione realmente trasmessa è molto poca: circa 14 bit per un nominativo e un locator scelti dal database, più 1 bit di rapporto e 1 bit di conferma [2].",
                "Il **Q65** trasmette sempre 78 bit di messaggio: anche un QSO minimo porta un nominativo qualsiasi (29 bit), un rapporto numerico vero (7 bit) e la conferma (1 bit), senza database [2]. K1JT ha preparato dieci file simulati con segnali a −29 dB e Doppler spread di 1 Hz, cinque JT65A e cinque Q65-60A per file, e ha provato a decodificarli in quattro modi, con 50 decodifiche possibili per prova [2]:",
                "|h| Prova | Modo | Nominativo e locator del DX | Deep Search | >Corrette | >Errate",
                "| 1 | JT65A | non noti | non disponibile | 0 | 0",
                "| 2 | JT65A | non noti | sì (DX nel CALL3.TXT) | 28 | 1",
                "| 3 | Q65-60A | non noti | – | 24 | 0",
                "| 4 | Q65-60A | noti (DX Call e DX Grid) | – | 49 | 0",
                "~ Da [2], tabella 1. Impostazioni JT65: Deep, Deep Search, AP, 6 schemi di cancellazione casuale, livello aggressivo 9; Q65: Fast, media attiva, azzeramento automatico della media.",
                "Le conclusioni dell'autore [2]: per le risposte alla propria chiamata il Q65-60A ha, per **qualunque** chiamante sconosciuto, circa la stessa sensibilità che il JT65A ha solo per chi è nel database; per tutti gli altri è più sensibile di **almeno 3 dB**, e lo è ancora di più nei messaggi successivi, quando entrambi i nominativi sono noti. Le decodifiche errate sono così rare da essere difficili da misurare. La media dei messaggi del JT65 serve per un solo chiamante già individuato, quella del Q65 funziona su tutta la banda visualizzata. Infine il JT65 dedica al sincronismo metà dell'energia trasmessa, il Q65 un quarto.",
                "> Il valore di −25 dB del JT65 nel Budget EME è quello della guida di WSJT-X senza Deep Search (§ 3.6); il −28 dB con Deep Search vale solo per i corrispondenti presenti nel database, il −29 dB con la media per qualunque messaggio.",
                ">! **Incongruenza tra le fonti.** Il documento di confronto JT65A – Q65-60A [2] indica −29 dB per il JT65A con Deep Search; la relazione di K1JT alla conferenza EME 2006, citata nel § 3.6, dà invece −28 dB per la Deep Search e −29 dB per la media dei messaggi. YAEC usa i valori del 2006. Le due fonti si riferiscono a sottomodi diversi: JT65B nelle simulazioni del 2006, JT65A in [2].",
                "### Come il Q65 costruisce il segnale",
                "G4JNT ha ricostruito dal codice sorgente di WSJT-X il percorso che porta dal messaggio ai toni trasmessi, verificandolo con il programma Q65CODE.EXE di WSJT-X [3]. In sintesi:",
                "• **Codifica della sorgente.** Come FST4, FT8, FT4 e MSK144, il messaggio diventa 71 bit di dati più 6 bit di tipo, 77 in tutto. Un testo libero ha fino a 13 caratteri di un alfabeto di 42 simboli (spazio, cifre, lettere e + - . / ?), e §42^{13}§ è minore di §2^{71}§; la modalità telemetria porta fino a 18 cifre esadecimali [3].",
                "• **Simboli.** Con un bit in più i 78 bit si dividono in 13 simboli di 6 bit, valori da 0 a 63 [3]: è la stessa lunghezza dei 78 bit di messaggio di [2].",
                "• **CRC.** Un controllo di 12 bit (due simboli), con polinomio 1100000001111 e i bit di ogni simbolo invertiti per compatibilità con il lavoro di IV3NWV, serve a scartare le decodifiche false [3]. Con il CRC i simboli diventano 15.",
                "• **Parità.** I 50 simboli di controllo nascono da una matrice «generatrice» di 15 × 50 elementi, con aritmetica nel campo di Galois GF(64): la somma è un XOR, il prodotto si fa con tabelle di logaritmi e antilogaritmi [3].",
                "• **Codice.** Il codice è un (65,15) a simboli di 6 bit; i due simboli del CRC vengono «perforati», cioè non trasmessi, e resta un codice effettivo (63,13) [1] [3].",
                "• **Sincronismo.** Ai 63 simboli si aggiungono 22 simboli di sincronismo, tutti sul tono 0, in posizioni pseudo-casuali fisse; i simboli trasmessi sono 85, con 65 toni: 0 per il sincronismo, da 1 a 64 per i dati [1] [3].",
                "= f_n = f_0 + n · Δf \\quad n = 0 … 64",
                "~ §f_0§ frequenza del tono 0, Δf spaziatura del sottomodo [3]. Con 22 simboli di sincronismo su 85 il sincronismo occupa circa un quarto della trasmissione, come osservato in [2].",
                "### Impostazioni consigliate in WSJT-X",
                "Per l'EME con il Q65 gli autori consigliano, in WSJT-X: *File → Settings → General* con **Enable VHF and submode features** e **Decode after EME delay** attivi e **Single decode** disattivo; nel menu *Decode* **Fast**, **Enable averaging** e **Auto Clear Avg after decode** [1]. Ogni decodifica Q65 porta la lettera «q» e una o due cifre: la prima indica l'informazione *a priori* usata, la seconda il numero di sequenze mediate [1].",
                "|h| Indicatore | Informazione a priori usata",
                "| q0 | nessuna",
                "| q1 | CQ",
                "| q2 | il mio nominativo",
                "| q3 | il mio nominativo e quello del DX",
                "| q4 | i due nominativi e RRR, RR73, 73 o nulla",
                "~ Da [1]. Gli autori avvertono di non dare troppo peso ai valori di S/N mostrati dal decodificatore, che stavano ancora migliorando [1]: per confronti con il Budget EME di YAEC conviene usare più QSO e non una sola lettura.",
                "### La procedura con le DXpedition (W7GJ)",
                "Lance Collister W7GJ, che attiva da anni spedizioni EME in 6 m, descrive come chiamare una DXpedition in Q65-60A durante un pile-up [6]. Prima di tutto servono l'orologio del computer molto preciso e la frequenza di trasmissione molto stabile [6].",
                "• **Turni.** La DXpedition trasmette sempre nella prima sequenza (minuti pari); chi chiama, nella seconda (minuti dispari) [6].",
                "• **Frequenza.** Scegli una frequenza libera nella banda passante e restaci: il Q65 fa la media delle chiamate di ogni stazione sulla sua frequenza, e se ti sposti il vantaggio delle chiamate precedenti si perde. Lascia circa 100 Hz tra te e gli altri e controlla che il Doppler non porti il tuo segnale fuori dalla banda passante del DX; ci si coordina sulla chat EME di ON4KST [6].",
                "• **Modo.** Si usa la procedura da contest digitale del Q65-60A: in WSJT-X, *File → Settings → Advanced*, una delle «Special Operating Activity» NA VHF, WW Digi o ARRL Digi (dopo la versione 2.6.1 anche Q65 Pileup). Metti nominativo e locator del DX in DX Call e DX Grid, premi Generate Std Msgs e parti dal messaggio TX2, non da CQ [6].",
                "• **Continua a chiamare.** In 6 m la propagazione tra stazioni a polarizzazione lineare è spesso non reciproca: il DX può ricevere te anche se tu non ricevi lui. Non smettere di chiamare e non tornare a un messaggio precedente se il DX è in QSO con altri o sparisce: ogni messaggio contiene i due nominativi e il QSO riprende da dove si era fermato. Con Q65 Pileup al DX serve almeno una tua decodifica per ogni passaggio della Luna [6].",
                "• **RRR, mai RR73.** In EME si usa sempre RRR: RR73 si invia una volta sola e il QSO viene registrato anche se l'altro non l'ha ricevuto. Il QSO è completo quando una delle due stazioni riceve l'RRR finale; chi lo riceve risponde 73 finché serve, quindi in *Settings → Behavior* non va spuntato «Disable Tx after sending 73» [6].",
                "• **Guarda lo schermo.** Anche se non decodifichi il DX, la sua traccia sul waterfall (Wide Graph) o la punta arancione del Q65 dicono che probabilmente lo riceverai appena ti risponde. Azzera a mano la media quando vedi che ha lavorato un altro: il prossimo potresti essere tu [6].",
                "|h| DX (prima sequenza, minuti pari) | Chi chiama (seconda sequenza, minuti dispari)",
                "| CQ TX7MB CI00 | TX7MB OH2BC KP30",
                "| OH2BC TX7MB R CI00 | TX7MB OH2BC RRR",
                "| G8BCG TX7MB R CI00 | TX7MB G8BCG RRR",
                "| G8BCG TX7MB 73 | TX7MB G8BCG 73",
                "~ Esempio ridotto da [6], con TX7MB (CI00) come DXpedition: ogni stazione che chiama resta sulla sua frequenza e passa a RRR quando riceve il proprio «R CI00».",
                "> Le finestre comuni con la Luna sono brevi, soprattutto al sorgere e al tramonto, quando molte stazioni sfruttano il ground gain: il Posizione live e +- 24h e la linguetta Distanza e Dgrd mostrano quando la Luna è visibile da entrambe le stazioni.",
                ">⚠ La discussione sui limiti teorici perde di significato nel momento in cui ci si trova a ricevere i segnali: un rumore locale improvviso può peggiorare l'ascolto, così come la rotazione di Faraday (§ 3.3).",
                "[1] Joe Taylor K1JT, Bill Somerville G4WJS, Steve Franke K9AN, Nico Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 aprile 2021 (WSJT-X 2.4.0), fornito da IC8TEM.",
                "[2] Joe Taylor K1JT, “Sensitivity Comparison of JT65A and Q65-60A” (file di prova JT65A_and_Q65-60A.zip), fornito da IC8TEM – https://physics.princeton.edu/pulsar/k1jt/JT65A_and_Q65-60A.zip",
                "[3] Andy Talbot G4JNT, “The Q65 Coding Process used in WSJT-X”, ottobre 2023, fornito da IC8TEM.",
                "[4] Nico Palermo IV3NWV, presentazione alla conferenza EME 2016 sui codici QRA, citata in [3] – http://www.eme2016.org/wp-content/uploads/2016/08/EME-2016-IV3NWV-Presentation.pdf",
                "[5] Codice sorgente di WSJT-X (file Q65_encoding_modules.F90 e altri), citato in [3] – https://wsjt.sourceforge.io/wsjtx.html",
                "[6] Lance Collister W7GJ, “Q65-60A QSO Procedure and Tips for EME DXpeditions”, revisione del 3 aprile 2023, fornito da IC8TEM – http://www.bigskyspaces.com/w7gj/"
            };
            d["it"]["S54"] = new string[] {
                "## Letteratura EME di SM5BSZ",
                "Leif Åsbrink SM5BSZ, autore di Linrad, ha pubblicato sul suo sito anche studi sull'EME che vanno oltre il suo software. Due lavori utili per capire il percorso Terra – Luna – Terra:",
                "• “Selecting Polarisation for EME” (25 aprile 1997): come la geometria, la riflessione sulla Luna, la rotazione di Faraday e l'assorbimento ionosferico cambiano la polarizzazione, con indicazioni pratiche per scegliere la polarizzazione in trasmissione e in ricezione secondo la frequenza – https://sm5bsz.com/polarity/emepol.htm",
                "• “EME Path Modulation” (23 febbraio 2000): spettri di una portante di alcuni minuti trasmessa da SM5FRH e ricevuta da SM5BSZ via Luna, con la componente speculare stretta e quella diffusa più larga, che si comportano diversamente con la polarizzazione – https://sm5bsz.com/sm5frh/sm5frh.htm",
                "Sul lato sportivo dell'EME: Henryk Kotowski SM0JHF, “Moonbouncers Are Also Contesters”, contesting.com, 20 maggio 2002 – https://www.contesting.com/articles/294"
            };
            d["it"]["S55"] = new string[] {
                "## Altri strumenti di calcolo EME",
                "• **EME Link Budget & Analysis Tool (1-300 GHz)** di Gerald Ihninger OE2IGL e Joachim Köppen DF3GJ: budget completo per le bande da 1 GHz in su, con i parametri del disco, il puntamento, la librazione e l'atmosfera – https://wettersat.bplaced.net/EME/EME.html",
                "• **WSJT-X** di Joe Taylor K1JT e collaboratori: modi digitali per l'EME (JT65, Q65 e altri) e la finestra Astronomical Data con il Doppler e il CAT – https://wsjt.sourceforge.io"
            };
            d["it"]["S43"] = new string[] {
                "## Polarizzazione, Dpol e MNR",
                "L'angolo di polarizzazione locale è calcolato come in WSJT-X dalla latitudine e dall'azimut ed elevazione della Luna; §D_{pol}§ è la differenza tra gli angoli delle due stazioni, tra −90° e +90°. La perdita per polarizzazione lineare (al massimo 30 dB) e la massima non reciprocità MNR (al massimo 25 dB) valgono:",
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}",
                "La rotazione di Faraday non è prevedibile e non è inclusa.",
                "Lo spostamento spaziale si calcola, perché dipende solo dalla posizione delle due stazioni: visto dalla Luna, un'antenna orizzontale al Polo Nord e una all'equatore appaiono una orizzontale e l'altra verticale. La rotazione di Faraday invece è casuale: il segnale attraversa la ionosfera due volte, all'andata e al ritorno, e ruota secondo la densità di elettroni del momento. Può capitare che tu senta il DX e lui non senta te; a 90° il segnale non si attenua, sparisce. Chi ha antenne orizzontali e verticali può ricevere sempre con la polarizzazione migliore e, se il corrispondente non risponde, commutare con un relè la polarizzazione di trasmissione [1].",
                "> Tra stazioni lontane, per esempio tra l'emisfero boreale e quello australe, la sola posizione geografica può portare §D_{pol}§ vicino a 90°. Quando nelle 24 ore successive supera 60°, il programma lo segnala con un avviso appena si inseriscono i locator [1].",
                "Con antenne a polarizzazione lineare la perdita per lo spostamento spaziale vale circa 3 dB a 45°, 6 dB a 60° e oltre 20 dB a 90°: per questo l'avviso scatta a 60° [2].",
                "### La rotazione di Faraday",
                "La ionosfera contiene elettroni liberi che, guidati dal campo magnetico terrestre, si muovono a spirale: un'onda a polarizzazione lineare che la attraversa esce con il piano di polarizzazione ruotato. È la rotazione di Faraday [3]. Dipende dal numero di elettroni lungo il percorso e cala con il quadrato della frequenza [3]:",
                "= F_{f} = F_{144} · \\p{\\frac{144}{f}}^{2}",
                "~ §F_{144}§ è la rotazione a 144 MHz, §f§ la frequenza in MHz. Un valore diurno tipico a 144 MHz è 180° con la Luna allo zenit e circa quattro volte tanto a 10° di elevazione, perché il percorso nella ionosfera è più lungo [3].",
                "|h| Banda | >Luna allo zenit | >Luna a 10° di elevazione",
                "| 50 MHz | >≈ 1.490° (oltre 4 giri) | >≈ 5.970°",
                "| 144 MHz | >180° | >≈ 720°",
                "| 432 MHz | >≈ 20° | >≈ 80°",
                "~ Rotazione per un passaggio nella ionosfera, valore diurno tipico; 144 MHz da [3], le altre bande ricavate da YAEC con la formula qui sopra (≈ = ricavato). Dai 1296 MHz in su si può considerare nulla [3].",
                "• **Non si annulla al ritorno.** Il verso della rotazione non dipende dalla direzione in cui viaggia l'onda: dopo il secondo passaggio nella ionosfera il segnale è ruotato ancora, nello stesso verso [3]. Ogni stazione aggiunge la rotazione della ionosfera sopra di sé.",
                "• **Cambia nel tempo.** La quantità di elettroni varia tra giorno e notte, all'alba e al tramonto e con l'attività solare: con il Sole molto attivo la rotazione è forte e può variare rapidamente, e durante le aurore la polarizzazione può cambiare in pochi millisecondi [3]. Per questo non si può prevedere da un calcolo.",
                "• **Si somma allo spostamento spaziale.** Lo spostamento spaziale (§D_{pol}§) ha segno opposto nei due sensi del collegamento, mentre la rotazione di Faraday ha lo stesso verso: in un senso le due rotazioni si sommano, nell'altro si sottraggono. Così può capitare che tu senta il DX e lui non senta te, o il contrario [1]. La perdita segue la stessa legge della §D_{pol}§, §L = −20 · log_{10} \\a{cos Δ}§, con Δ lo sfasamento totale: a 90° il segnale sparisce.",
                "• **Che cosa fare.** Da 50 a 432 MHz si usa la polarizzazione lineare: conviene un impianto che permetta di scegliere il piano di polarizzazione, meglio con una commutazione elettronica che ruotando meccanicamente tutta l'antenna [3]. Quando chiami CQ è più efficace alternare orizzontale e verticale che usare la polarizzazione circolare, che costa sempre 3 dB [3]. Con antenne orizzontali e verticali si riceve con la polarizzazione migliore e, se il corrispondente non risponde, si commuta quella di trasmissione [1].",
                "> In 432 MHz la rotazione di Faraday è piccola e conta soprattutto lo spostamento spaziale, che YAEC calcola; in 50 e 144 MHz può fare più giri ed è imprevedibile: la §D_{pol}§ e l'avviso oltre 60° tengono conto solo della parte spaziale.",
                "### Scegliere la polarizzazione per l'EME: sintesi dell'articolo di SM5BSZ",
                "L'articolo «Selecting Polarisation for EME» di Leif Åsbrink SM5BSZ (25 aprile 1997) è pubblico e si legge sul suo sito: https://sm5bsz.com/polarity/emepol.htm. L'autore di questo programma ritiene utile offrirne qui uno spunto di sintesi, scritto con parole proprie; per le spiegazioni complete si rimanda alla lettura integrale dell'articolo [3].",
                "• **Quattro effetti.** Lungo il percorso Terra – Luna – Terra la polarizzazione cambia per lo spostamento spaziale, per la riflessione sulla Luna, per la rotazione di Faraday e per l'assorbimento nella ionosfera [3].",
                "• **Spostamento spaziale.** Viste dalla Luna, due antenne lontane sulla Terra curva non sono parallele. Riguarda solo la polarizzazione lineare, si calcola con facilità e non dipende dalla frequenza [3]: è la §D_{pol}§ di YAEC.",
                "• **Riflessione sulla Luna.** Alle frequenze basse, come 144 MHz, la Luna si comporta come una sfera liscia: la polarizzazione lineare resta tale, quella circolare inverte il senso, e circa l'1 % dell'energia finisce nella polarizzazione «sbagliata». A 10 GHz la superficie è ruvida e il segnale torna depolarizzato [3].",
                "• **Rotazione di Faraday.** È descritta nel sottoparagrafo precedente: cala con il quadrato della frequenza, si somma all'andata e al ritorno e non si può prevedere [3].",
                "• **Assorbimento ionosferico.** Cala anch'esso con il quadrato della frequenza: a 144 MHz, di giorno e a 10° di elevazione, è di circa 0,1 dB. Conta solo con un'attività solare molto alta; durante le aurore forti la polarizzazione può cambiare più in fretta di quanto un ricevitore a banda stretta riesca a seguire [3].",
                "• **Da 50 a 432 MHz.** Quasi tutti usano yagi a polarizzazione lineare: l'autore consiglia un impianto con la polarizzazione lineare commutabile, meglio elettronicamente; una rotazione meccanica va bene se il quarto di giro richiede uno o pochi secondi [3]. In ricezione si sceglie la polarizzazione con il segnale più forte (un ricevitore a due canali è più rapido con i segnali deboli); quando si chiama CQ conviene alternare orizzontale e verticale, invece della circolare che perde sempre 3 dB [3].",
                "• **Da 10 GHz in su.** La Luna depolarizza il segnale, la polarizzazione di trasmissione non conta più e serve un ricevitore a due canali su due alimentatori ortogonali [3]. Sono frequenze fuori dalle bande di YAEC.",
                "• **Quale polarizzazione trasmettere.** Se ricevi una stazione, puoi ricavare con quale polarizzazione trasmetterle perché il tuo segnale le arrivi nel modo giusto [3]. Con gli angoli in gradi (0° orizzontale, 90° verticale), P è la polarizzazione di trasmissione dell'altra stazione, R quella con cui la ricevi, S lo spostamento spaziale, F la rotazione di Faraday e T la tua polarizzazione di trasmissione migliore:",
                "= R = P + S + F \\quad P = T − S + F \\quad T = 2 · S − R",
                "~ Eliminando F dalle prime due relazioni si ottiene §T = 2 · P + 2 · S − R§; per un'antenna lineare §2 · P§ vale 0° o 180°, che è la stessa polarizzazione, e resta §T = 2 · S − R§ [3]. Senza rotazione di Faraday (§F§ = 0, dai 1296 MHz in su) la polarizzazione migliore per trasmettere è la stessa con cui si riceve meglio, §T = R§. L'articolo segnala che la regola coincide con quella di KL7WE e cita il programma SKYMOON di W5UN per il calcolo di S [3].",
                "> In YAEC lo spostamento spaziale S è la §D_{pol}§ calcolata nella Posizione della Luna e nel Posizione live e +- 24h; la rotazione di Faraday F non si può calcolare. Per gli esempi, i casi particolari e le figure, leggi l'articolo completo di SM5BSZ [3].",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s",
                "[2] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, presentazione, luglio 2015, fornita da IC8TEM.",
                "[3] Leif Åsbrink SM5BSZ, “Selecting Polarisation for EME”, 25 aprile 1997 – https://sm5bsz.com/polarity/emepol.htm"
            };
            d["it"]["S44"] = new string[] {
                "## Rumore del cielo e Dgrd",
                "La temperatura del cielo dietro la Luna (§T_{sky}§) a 144 MHz è presa lungo l'eclittica da una tabella a passi di 2° (WSJT-X) e, nella Volta celeste, da una mappa di tutto il cielo a 2° derivata dal Global Sky Model; alle altre frequenze si scala con indice spettrale 2,6:",
                "= T(f) = \\p{T_{144} − 2,7} · \\p{\\frac{144}{f}}^{2,6} + 2,7 \\t{ K}",
                "La Dgrd, come in WSJT-X, somma l'effetto della distanza d della Luna e quello del rumore del cielo:",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2,6} \\t{ K}",
                "### Che cosa vuol dire la Dgrd",
                "La **Dgrd** (*degradation*, peggioramento) dice di quanti dB l'eco della Luna è peggiore, in quell'istante, rispetto alle condizioni migliori possibili: Luna al perigeo e cielo freddo dietro la Luna. Non dipende dalla stazione, ma solo dalla Luna e dal cielo: per questo serve a scegliere i giorni e le ore, non a calcolare il collegamento, che è il compito del Budget EME.",
                "• **0 dB** è il caso ideale; i valori sono sempre negativi. **−3 dB** vuol dire metà del rapporto S/N rispetto all'ideale, **−6 dB** un quarto.",
                "• Il primo termine della formula è la **distanza**: tra perigeo (circa 356 900 km) e apogeo (circa 406 700 km) l'eco cambia di circa 2,3 dB, perché la perdita di tratta cresce con la quarta potenza della distanza. Sembra poco, ma raddoppiare le antenne ne fa guadagnare in teoria 3 [1].",
                "• Il secondo termine è il **rumore del cielo** dietro la Luna: quando la Luna passa davanti alla Via Lattea la temperatura del cielo sale di molto e la Dgrd può scendere di parecchi dB, più di quanto pesi la distanza.",
                "• Valori tipici sono −1, −1,5 o −2 dB. Con la Luna sul centro della Galassia I2FAK ha visto −11 dB, le condizioni peggiori in assoluto, e ha completato lo stesso un QSO con una stazione molto debole, una DXpedition da Gibuti, grazie a un impianto di 16 + 16 antenne: con le condizioni così cattive ci vuole un impianto calibrato alla perfezione, e anche l'esperienza conta più delle previsioni del software [1].",
                "• Per chi ha una stazione piccola, ogni dB conta: un giorno con Dgrd −1 dB e uno con −5 dB possono fare la differenza tra un QSO completato e nessuna decodifica.",
                "> Nel programma: il riquadro DGRD del Posizione live e +- 24h mostra il valore di adesso tra il minimo e il massimo del grafico; la linguetta Distanza e Dgrd mostra il calendario dei prossimi giorni, il grafico con la distanza e i tre giorni migliori.",
                "### La Luna davanti alle sorgenti di rumore della Galassia",
                "Ogni mese la Luna percorre la fascia dell'eclittica (entro circa 5° da essa) e attraversa due volte la Via Lattea. I due passaggi non sono uguali:",
                "• **Sagittario, centro della Galassia**: è la zona più calda del cielo; a 144 MHz la temperatura del cielo dietro la Luna arriva a qualche migliaio di K, contro circa 200 K delle zone fredde, e quella zona è più rumorosa del Sole [1]. Qui la Luna è anche alla sua declinazione più bassa, intorno a −30° negli anni di massima declinazione: dal Nord Italia (circa 45° N) sale al massimo a 15 – 16° di elevazione e resta sopra i 5° circa 6 ore (circa 7 ore sopra l'orizzonte), mentre a +30° arriva a circa 75° e resta sopra i 5° circa 15 – 16 ore [1]. È il periodo peggiore del mese.",
                "• **Toro e Gemelli, dalla parte opposta (anticentro)**: la Via Lattea è molto meno calda, ma nel Toro, vicinissima all'eclittica, c'è la **Nebulosa del Granchio** (Taurus A), una delle radiosorgenti più forti del cielo: quando la Luna le passa davanti o accanto il rumore cresce.",
                "• Il rumore del cielo cresce scendendo di frequenza: a 50 MHz pesa molto più che a 144 MHz, a 432 MHz molto meno (il programma lo scala con l'indice spettrale 2,6).",
                "> Nel programma: la Volta celeste colora il cielo dal blu (freddo) al rosso (caldo) e mostra dove si trova la Luna; la colonna Tsky della Posizione della Luna e il calendario di Distanza e Dgrd dicono quando la Luna è davanti alle zone calde.",
                "### La declinazione della Luna",
                "La **declinazione** (§δ§) è la «latitudine» della Luna sul cielo: di quanti gradi sta a nord (+) o a sud (−) dell'equatore celeste. Il programma la calcola dalla data e dall'ora e la usa in tutti i calcoli (elevazione, finestre, Tsky, Dpol, Doppler): non va inserita. Conoscerla però aiuta a scegliere i giorni.",
                "• **Ciclo mensile**: in circa 27,3 giorni la declinazione va dal massimo a nord al massimo a sud e torna indietro. Con la Luna dalla parte del proprio emisfero (positiva al nord, negativa al sud) la Luna sale più alta e resta più ore sopra l'orizzonte; dalla parte opposta resta bassa e per poche ore [1].",
                "= El_{max} ≈ 90° − \\a{φ − δ} \\quad cos H_{0} = − tan φ · tan δ \\quad t_{su} = \\frac{2 · H_{0}}{15°} \\t{ h}",
                "~ §φ§ è la latitudine della stazione, §H_{0}§ l'angolo orario al sorgere e al tramonto, §t_{su}§ le ore con la Luna sopra l'orizzonte (senza ostacoli e senza rifrazione). Esempio a 41° N: con §δ§ = +28° la Luna arriva a circa 77° e resta su circa 15,7 ore; con §δ§ = −28° si ferma a circa 21° e resta su circa 8,3 ore.",
                "• **Collegamenti tra emisferi**: in un QSO nord – sud le due stazioni preferiscono declinazioni opposte; le finestre comuni più lunghe cadono spesso con la Luna vicina all'equatore celeste (declinazione intorno a 0°), quando nessuna delle due stazioni è sfavorita.",
                "• **Ciclo di 18,6 anni**: l'ampiezza dell'escursione mensile cambia lentamente, da circa ±18,3° a circa ±28,6°. Il massimo (lunistizio maggiore) c'è stato nel 2024 – 2025; verso il 2034 l'escursione sarà minima, con mesi meno estremi: la Luna non scenderà più così in basso, ma nemmeno salirà così in alto.",
                "• **Declinazione e rumore**: la Luna tocca la declinazione più bassa quando passa davanti al Sagittario, la zona più rumorosa del cielo, e quella più alta nel Toro e nei Gemelli, dove il cielo è più freddo. Per le stazioni dell'emisfero nord la settimana della declinazione più bassa somma quindi Luna bassa, poche ore utili e Tsky alta [1].",
                "> Nel programma: sotto il grafico della linguetta Distanza e Dgrd la curva della declinazione mostra i massimi a nord e a sud con la data; la zona verde indica quando la Luna è dalla parte del tuo emisfero (la curva si nasconde con la casella Curva della declinazione). Il valore di ogni istante è nella colonna facoltativa Declinazione (°) della Posizione della Luna e nel Posizione live e +- 24h.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["it"]["S45"] = new string[] {
                "### Perché il Sole conta",
                "Il **Sole** è la sorgente di rumore più forte del cielo. Intorno alla Luna nuova Sole e Luna sono vicini nel cielo: anche se il Sole resta fuori dal lobo principale, entra dai lobi laterali, ed entro poche larghezze del lobo il rumore in ricezione cresce di molto. Per questo, in pratica, la settimana della Luna nuova è quasi sempre da evitare.",
                "• Quanto pesa dipende dal guadagno dell'antenna (lobo più stretto, Sole più lontano in larghezze del lobo), dal livello dei lobi laterali e dall'**attività solare**: il flusso del Sole, in SFU, cambia da un giorno all'altro e cresce molto durante i brillamenti.",
                "• Per questo un'antenna con i **lobi laterali molto attenuati** è fondamentale: i lobi laterali raccolgono il rumore che c'è intorno e lo sommano a quello del lobo principale [1].",
                "• Durante un'eclissi di Sole la Luna è proprio davanti al Sole: I2FAK ha completato lo stesso un QSO puntando 2,5 – 3° a lato della Luna, così il lobo stretto del suo array attenuava il rumore del Sole [1].",
                "• Il Sole sotto l'orizzonte del ricevitore non conta, anche se la Luna è nuova.",
                "> Nel programma: il calendario di Distanza e Dgrd segna con il simbolo ☀ i giorni con il Sole vicino alla Luna (arancione o rosso); la linguetta Rumore solare calcola, con il flusso misurato, quanto rumore in più porta il Sole nell'istante scelto.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["it"]["S43F"] = new string[] {
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}"
            };
            d["it"]["S44F"] = new string[] {
                "= T(f) = \\p{T_{144} − 2,7} · \\p{\\frac{144}{f}}^{2,6} + 2,7 \\t{ K}",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2,6} \\t{ K}"
            };
            d["en"] = new Dictionary<string, string[]>();
            d["en"]["S32"] = new string[] {
                "## The Maidenhead locator (WWL)",
                "The **Maidenhead locator**, also called WWL (World Wide Locator) or QTH locator, is the code radio amateurs use to give the position of their station. It was devised by John Morris G4ANB and adopted by the IARU VHF Working Group in April 1980, at a meeting in Maidenhead, England; it replaced the old QRA locator, which only covered Europe [1]. Since 1999 the geodetic datum is WGS-84, the same as GPS [1]. YAEC derives the latitude and longitude of the station from the locator, and all the calculations from these.",
                "### How it is built",
                "The locator is a series of pairs: each pair gives first the longitude and then the latitude, and divides the rectangle of the previous pair into smaller parts. The pairs alternate letters and digits [1]. A 14-character example: **PM 95 UP 98 KB 75 MI** (Tokyo).",
                "@locator PM 95 UP 98 KB 75 MI",
                "|h| Pair | Name | Symbols | >Divides into | >Size (lon × lat) | >Characters | >Side at 35.7° (Tokyo) | >Maximum error",
                "| 1st | field | A … R | 18 × 18 | 20° × 10° | 2 | – | –",
                "| 2nd | square | 0 … 9 | 10 × 10 | 2° × 1° | 4 | 181 × 111 km | ±106 km",
                "| 3rd | subsquare | A … X | 24 × 24 | 5′ × 2.5′ | 6 | 7.5 × 4.6 km | ±4.4 km",
                "|+ 4th | extended square | 0 … 9 | 10 × 10 | 30″ × 15″ | **8** | 753 × 463 m | **±442 m**",
                "| 5th | extended subsquare | A … X | 24 × 24 | 1.25″ × 0.625″ | **10** | 31 × 19 m | **±18 m**",
                "| 6th | – | 0 … 9 | 10 × 10 | 0.125″ × 0.0625″ | 12 | 3.1 × 1.9 m | ±1.8 m",
                "| 7th | – | A … X | 24 × 24 | 0.0052″ × 0.0026″ | 14 | 13 × 8 cm | ±8 cm",
                "~ Sizes from the rules in [1]; sides and maximum error (half the diagonal, with the station at the centre of the box) computed by YAEC for the latitude of Tokyo: towards the poles the east-west side gets shorter. Letters are written in capitals, as clarified by the IARU in 2019 [1]; YAEC also accepts lower case and converts it.",
                "> Beyond 8 characters there is no common standard: the 5th pair and the following ones are not formally defined, and the most common practice, the one followed by YAEC, repeats the rules of the previous pairs (letters in base 24, digits in base 10). Other programs may use different encodings, so a long locator may not be read the same way everywhere [1].",
                "### How many characters to use",
                "On HF the square (4 characters) is usually used; on the YAEC bands, from 50 to 432 MHz, the subsquare (6 characters) is used [1]. These rules apply to QSO exchanges and contests: for example, in IARU Region 1 distances are measured between the centres of the subsquares [1]. For the YAEC calculations the choice is different:",
                "|h| Characters | Recommended use in YAEC",
                "| 4 | only for a rough estimate: the azimuth and elevation of the Moon can be wrong by up to about 1°, because the local horizon tilts by about 1° every 111 km",
                "| 6 | the DX locator, QSOs and the EME budget: the error on the Moon direction is a few hundredths of a degree",
                "| **8** | your station, for Reconnaissance of my obstacles: it identifies the neighbourhood or the hill",
                "|+ **10** | your station, with the best result: it identifies the building or the antenna tower",
                "| 12 – 14 | accepted, but they add nothing: the precision exceeds that of a common GPS (a few metres) and the size of the antenna itself",
                "### Locator and obstacles",
                "For the direction of the Moon 6 characters are enough: the Moon is about 380 000 km away, and the ±4.4 km of a 6-character locator change azimuth and elevation by about 0.04°, a negligible amount compared with the antenna beam. For **local obstacles** (buildings, trees, hills) it is the opposite: they are a few tens or hundreds of metres from the antenna, and with 6 characters the station can be anywhere in a 7.5 × 4.6 km rectangle, so the obstacles cannot be placed. With 8 characters the error drops to about 450 m, with 10 to about 20 m: this is the precision the **Reconnaissance of my obstacles** tab needs to draw correctly the zones where the antenna is blocked.",
                ">+ Practical tip: derive the 10-character locator from the GPS coordinates of the point where the antenna stands (not of the house entrance) and enter it in the Live position and +- 24h tab as **my locator**. For the DX the 6-character locator he gives you is enough.",
                "[1] Wikipedia, “Maidenhead Locator System” (origin G4ANB and IARU VHF meeting in Maidenhead in 1980, structure of the pairs, WGS-84 since 1999, extensions beyond 8 characters, IARU 2019 clarification, use on HF and VHF/UHF, distances between subsquare centres) – https://en.wikipedia.org/wiki/Maidenhead_Locator_System"
            };
            d["en"]["S46"] = new string[] {
                "### The EME budget formulas",
                "The path loss follows the radar equation: the signal goes from the station to the Moon, part of it is scattered and returns towards the Earth. The distances §d_1§ and §d_2§ are the topocentric distances of the two stations at the chosen instant, so the difference between perigee and apogee (about 2.3 dB) is already included.",
                "= λ = \\frac{c}{f} \\quad σ = 0.065 · π · R_M^2",
                "= L_{EME} = 10 · log_{10} \\b{\\frac{\\p{4π}^3 · d_1^2 · d_2^2}{σ · λ^2}} \\t{ dB}",
                "~ with §c = 299 792 458 \\t{ m/s}§, §R_M = 1 737.4 \\t{ km}§ (radius of the Moon), lunar reflectivity 0.065.",
                "The radiated power and the signal at the terminals of the receiving antenna:",
                "= EIRP = P_{dBW} − L_{TX} + G_{ant} + 10 · log_{10} N + G_g \\quad S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                "= G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}} \\quad L_{pol} = −20 · log_{10} \\a{cos D_{pol}}",
                "~ Ground gain (\"BETA- antenna without elevation\" checkbox): horizontally polarized antenna at height h, computed at the Moon elevation, at most +6 dB.",
                "The noise figure of the receiving chain is obtained with the Friis formula, in linear values (§F = 10^{NF/10}§, §G = 10^{G_{dB}/10}§):",
                "= F_{tot} = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + … \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "The noise figure of the radio is derived from its MDS, measured in the bandwidth B:",
                "= NF_{radio} = MDS + 174 − 10 · log_{10} B",
                "= T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e \\quad N = 10 · log_{10} \\p{k · T_{sys} · B} + 30 \\quad \\frac{S}{N} = S_{ant} − N",
                "~ with §k = 1.380649 · 10^{−23} \\t{ J/K}§ (Boltzmann) and B the bandwidth in Hz. §T_{ant}§ is the antenna temperature from the VE7BQH tables (antenna tilted at 30°); §ΔT_{sky} = max \\p{0, T_{sky} − T_{ref}}§, with §T_{ref}§ = 200 K at 144 MHz scaled with index 2.6.",
                "The EME budget does not compute a margin on the mode: it shows the estimated S/N referred to the 2500 Hz reference bandwidth used by WSJT-X and, next to it, the typical threshold of the chosen mode as a reference only. A threshold is not a hard limit: with the decoder's aids, decoding works even lower, as the JT65 table and the notes below show.",
                "= \\frac{S}{N}_{2500} = \\frac{S}{N}_{B} + 10 · log_{10} \\frac{B}{2500}",
                "|h| Mode | >Typical threshold, single message (2500 Hz) | Source",
                "| JT65 | −25 dB | [1]",
                "| JT9 | −27 dB | [1]",
                "| JT4 | −23 dB | [1]",
                "| FT8 | ≈ −20 dB | [1]",
                "| FT4 | ≈ −16.5 dB | [1]",
                "| Q65-15A | −22.2 dB | [2]",
                "| Q65-30A | −24.8 dB | [2]",
                "| Q65-60A | −27.6 dB | [2]",
                "| Q65-120A | −30.8 dB | [2]",
                "| Q65-300A | −33.8 dB | [2]",
                "| WSPR | −31 dB | [1]",
                "~ Thresholds for 50 % decode probability, measured on an additive white Gaussian noise (AWGN) channel. For Q65, *a priori* (AP) decoding, which uses the callsigns already known during the QSO, adds 1.5 to 3.6 dB depending on the submode (for example Q65-60A −30.2 dB) [2]; YAEC shows the more cautious values without AP as a reference. With a Doppler spread of a few hertz the threshold gets worse: for Q65-60A by about 2 dB at 5 Hz and about 3 dB at 10 Hz (read from the chart in [2]). The structure of Q65, its submodes and the comparison with JT65 are in § 3.12. For EME the document recommends Q65-60A on 50 and 144 MHz and Q65-60B on 432 MHz [2]: submodes B – E have tone spacing and occupied bandwidth 2 – 16 times those of submode A.",
                "For JT65, K1JT published the limits for each kind of decoding, obtained from simulations of the JT65B submode [5]:",
                "|h| JT65: kind of decoding | >S/N (2500 Hz) | Source",
                "| Any message, including plain text | −24 dB | [5]",
                "| Callsign in the database (Deep Search) | −28 dB | [5]",
                "| Any message, averaging several transmissions | −29 dB | [5]",
                "| Synchronization only (time and frequency) | −30 dB | [5]",
                "| Shorthand messages RO, RRR, 73 | −32 dB | [5]",
                "~ The WSJT-X guide gives −25 dB for a single message [1]. Deep Search only tests messages with CQ or your own callsign plus a callsign and locator from the database: an unknown callsign or plain text can only be decoded by the general decoder, with averaging if needed [5]. Decoding is «all or nothing»: a message is read in full or not at all, it does not degrade gradually near the limit [5]. This is why YAEC no longer shows the dB above or below the threshold.",
                "### Ground gain in practice",
                "The ground gain of the «BETA- antenna without elevation» checkbox follows the model of flat, reflecting ground: the direct and the reflected ray add up when the path difference is a half-integer number n of wavelengths and cancel when it is an integer, with §n · λ = 2 · H · sin α§; the reflection point is at a distance §D = \\frac{H}{tan α}§ from the antenna [3]. The tests made by IK1UWL with the echoes of his own station (4 × 14 elements at 121 m above the sea, Ligurian coast) show that in practice things are more complicated [3]:",
                "• peaks and nulls are many and close together, at fractional angles that a simulator working in 1° steps such as EZNEC does not see: with the antenna high above the sea they follow each other about every 3 minutes (3 JT65 periods) and cause strong QSB at low elevation, which does not depend on the ionosphere;",
                "• the measured gain was about 3 dB, not the theoretical 6 dB: in an array the upper and lower yagis are at different heights (4.5 m), their reflections are not in phase and only one pair contributes at a time;",
                "• below 2° of elevation there is a gain hole and the maximum is around 5°; when the antenna is elevated the ground effect decreases and beyond the beam width (about 12° for his array) it becomes negligible;",
                "• refraction matters: the Moon rose at −0.51°, below the optical horizon of −0.35°; at 200 MHz, in dry air, the refraction error at 0° elevation is −0.49°.",
                "IK3XTV points out that in theory the ground effect reaches 6 dB, so that a single yagi performs almost like an array of 4, but it depends a lot on the ground around the antenna: it is lower in town, better in open countryside and even more so near the sea. It is used at moonrise and moonset, between about 1° and 18 – 20° of elevation [4].",
                "> This is why the ground gain is marked BETA in the EME budget: the calculated value (at most +6 dB) is a theoretical limit. With antennas high above the sea or arrays of several yagis, expect about half of it and marked QSB at low elevation [3].",
                "[1] WSJT-X User Guide, K1JT and the WSJT Development Group, § 7.1 (FT4 = FT8 + 3.5 dB).",
                "[2] J. Taylor K1JT, B. Somerville G4WJS, S. Franke K9AN, N. Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 April 2021 (WSJT-X 2.4.0), supplied by IC8TEM.",
                "[3] Giorgio Marchi IK1UWL, “Considerazioni sull'effetto suolo (Ground Gain)”, 21st EME Meeting, presentation supplied by IC8TEM.",
                "[4] Flavio Egano IK3XTV, “EME (earth-moon-earth) con una singola Yagi in 144 MHz”, document of 12 November 2010, supplied by IC8TEM.",
                "[5] J. Taylor K1JT, paper on JT65 at the EME 2006 conference (K1JT_eme2006.pdf): table of minimum S/N levels in 2500 Hz.",
                "> The station diagram, on the right of the tab, derives the losses from the chosen cables: in transmission PA–relay cable + relay + antenna cable, in reception antenna cable + relay before the preamplifier and feed cable after it. The cable attenuations come from the database of the COAXIAL CABLES tab (§ 3.8)."
            };
            d["en"]["S47"] = new string[] {
                "## The preamplifier and the noise figure of the radio {nuovo}",
                "In EME the signal reaching the antenna is only slightly above the noise (about −149 dBm in the Tokyo – Cape Town example). The preamplifier has two different jobs: **recovering the signal** lost in the cables to the station and, above all, **covering the noise figure of the radio**, which on commercial VHF/UHF transceivers ranges from about 3 – 5 dB with the internal preamp on to 15 – 16 dB and more with the preamp off.",
                "The reason lies in the Friis formula: each stage weighs on the total noise divided by the gain of everything before it. The first stage decides almost everything.",
                "= F_{tot} = F_{LNA} + \\frac{F_{cable} − 1}{G_{LNA}} + \\frac{F_{radio} − 1}{G_{LNA} · G_{cable}} \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "~. F and G in linear values (§F = 10^{NF/10}§); for a cable with loss L in dB: §F_{cable} = 10^{L/10}§ and §G_{cable} = 10^{−L/10}§.",
                "@colonne 55",
                "#### Measured noise figure of some radios",
                "|h| Radio | >MHz | Preamp | >NF (dB) | Source",
                "| Icom IC-9700 | 144 | off / on | 16 / 3 | [1]",
                "| Icom IC-9700 | 432 | off / on | 15 / 4 | [1]",
                "| Yaesu FT-991 | 50 | IPO / AMP1 / AMP2 | 29 / 17 / 8 | [2]",
                "| Yaesu FT-991 | 144 · 432 | – | 5 · 4 | [2]",
                "| Icom IC-275E | 144 | – | 5.6 | [3]",
                "| Icom IC-9100 | 144 · 432 | not stated | ≈ 5 · ≈ 5 | [5]{r:*}",
                "| Icom IC-821H | 144 | – | 3.4 | [3]",
                "| Icom IC-910H | 144 | – | 3.7 | [3]",
                "| Icom IC-7000 | 144 | – | 5.6 | [3]",
                "| Kenwood TS-790E | 144 | – | 4.5 | [3]",
                "| Kenwood TS-2000 | 144 | on | 6.2 | [3]",
                "| Yaesu FT-847 | 144 | on / off | 5.1 / 6.7 | [3]",
                "| Yaesu FT-817 | 144 | – | 5.4 | [3]",
                "| Yaesu FT-857D | 144 | – | 6.1 | [3]",
                "| Icom IC-746PRO | 50 | off / P1 / P2 | 19 / 9 / 6 | [14]",
                "| Icom IC-746PRO | 144 | off / on | 14 / 5.2 | [14]",
                "| Yaesu FT-897 | 50 | on / IPO | 3.6 / 8.7 | [15]",
                "| Yaesu FT-897 | 144 · 432 | always on | 5.9 · 7.7 | [15]",
                "~ [1] [2] measurements by VA7OJ with a calibrated noise source; [3] measurements by DF9IC with the Y-factor method, accuracy ±0.5 dB, 144 MHz only, from 2005. With the internal preamp on, the IC-9700 already saturates from −9 to −27 dBm at 144 MHz [1]. * Value to be verified: preliminary test on a pre-production unit, author not stated. [14] NF derived from the noise floor (MDS) measured in 500 Hz: NF = MDS + 174 − 27 dB; with the preamp on at 144 MHz the blocking dynamic range at 5 kHz drops from 99.9 to 88.4 dB. [15] NF derived from the SSB sensitivity for 10 dB (S+N)/N with the 2450 Hz filter: NF = S − 9.5 + 174 − 10·log B; on 144 and 432 MHz the preamp is always in circuit. For [14] and [15] the accuracy is indicative, ±1 dB.",
                "@destra",
                "#### Example: 35 m of Sivacavi HF 400 (1.6 dB) at 144 MHz",
                "|h| Configuration | >Total NF | >Te | >Tsys | >Worsens S/N by",
                "| Radio alone, internal preamp off (NF 16) | 17.6 dB | 16 398 K | 16 648 K | %bar:17.6:17.6:r%17.6 dB",
                "| Radio alone, internal preamp on (NF 3) | 4.6 dB | 546 K | 796 K | %bar:4.4:17.6:o%4.4 dB",
                "| LNA at the antenna 0.5 dB / 20 dB + radio NF 16 | 2.3 dB | 199 K | 449 K | %bar:1.9:17.6:y%1.9 dB",
                "| **LNA at the antenna 0.5 dB / 20 dB + radio NF 3** | **0.6 dB** | 41 K | 291 K | %bar:0:17.6:g%{g:**reference**}",
                "~ §T_{sys} = T_{ant}§ 250 K + §T_e§; the comparison is made with the same signal at the antenna.",
                "@fine",
                "For the best configuration, with the values substituted:",
                "= F_{tot} = 1.1220 + \\frac{1.4454 − 1}{100} + \\frac{1.9953 − 1}{100 · 0.6918} = 1.1220 + 0.0045 + 0.0144 = 1.1409 \\quad ⇒ \\quad NF = 0.57 \\t{ dB}",
                ">! **In practice.** The preamplifier should be mounted at the antenna, before the feed cable and right after the coaxial relay (which must protect it during transmission with a sequencer). Its gain must be high enough to make the cable and the radio negligible: as a rule, at least 10 dB more than the sum of the cable loss and the radio noise figure (in the example 1.6 + 16 ≈ 18 dB → with 20 dB the radio still weighs 1.7 dB; with the internal preamp on it weighs only 0.05 dB). Too much gain, however, reduces the dynamic range of the radio: with a good LNA at the antenna it is often better to keep the internal preamp off and choose a 20 – 26 dB LNA. In the EME budget these choices are made in the diagram of the receiving installation, and the DEBUG FORMULE tab shows the calculation step by step.",
                "##+ The transverter (optional)",
                "With a transverter the radio works at an intermediate frequency (usually 28 MHz for 144 MHz) and the transverter becomes the stage that counts for noise: it enters the Friis formula after the feed cable, and the radio that follows it weighs less the more the transverter gains.",
                "= F_{comb} = F_{XV} + \\frac{F_{radio} − 1}{G_{XV}} \\quad \\t{e.g. } F_{comb} = 1.2589 + \\frac{10 − 1}{50.12} = 1.4385 ⇒ NF = 1.58 \\t{ dB}",
                "~ example: transverter with NF 1.0 dB and gain 17 dB (minimum values of the DEMI L144-28) in front of an HF radio with NF 10 dB.",
                "@colonne 56",
                "#### Chart: NF of the combination as the radio and the transverter gain vary",
                "@abaco Curves computed with (3.7.3) for a transverter with NF 1.0 dB. The more the transverter gains, the less the radio weighs: with 25 dB of gain a radio with 20 dB of NF brings the total to 2.0 dB; with 10 dB of gain the same radio brings the total to 10.5 dB.",
                "@destra",
                "#### Transverters for 144 MHz (IF 28 MHz)",
                "|h| Maker · model | >NF | >RX G | >TX | Source",
                "| DEMI L144-28 | < 1.0 dB | ≥ 17 dB | 25 / 50 W | [6]",
                "|+ **Kuhne (DB6NT) MKU 144 G2** (module) | 0.9 dB | 25 dB | 0.1 W¹ | [13]",
                "| Kuhne (DB6NT) TR 144 H +40 | 0.9 – 1.2 dB | 25 dB | 2 – 20 W | [7]",
                "| Kuhne (DB6NT) TR-144 Pro | {r:n.a.} | {r:n.a.} | 25 W | [8]",
                "| Q5 Signal L144-28M | < 1.0 dB | ≥ 20 dB | 25 / 75 / 150 W | [9]",
                "| HA1YA ME2T-PRO-II / ME2HT-PRO-II | 1.0 dB | ≤ 25 dB (adjustable) | 30 / 50 W | [10]",
                "| SSB-Electronic LT2S Mk II | {r:n.a.} | {r:n.a.} | – | [11]",
                "~ Values stated by the makers. MKU 144 G2: first stage with NF 0.5 dB, output IP3 in reception +23 dBm, IF input 2 – 50 mW or 60 – 2000 µW; ¹ 100 mW driver, to be completed with a Kuhne 60 or 120 W amplifier. TR 144 H +40: it contains the MKU 144 G2 module, hence the 25 dB gain (information from IC8TEM). With 25 dB of gain, in front of a radio with NF 10 dB the total is 0.99 dB, with NF 20 dB it is 1.88 dB [13]. The Kuhne manual states 1.2 dB in the table and 0.9 dB in the text; with the Kuhne MKU LNA 144 A preamp the total drops to 0.3 dB [7]. Q5 Signal L144-28M: maximum NF 1.0 dB with minimum conversion gain 20 dB, RX-IF gain adjustable by the user to calibrate the S-meter; IF up to 25 W [9]. HA1YA ME2T-PRO-II: overall NF 1 dB (first stage PGA103+ with NF 0.7 dB), RX gain adjustable up to 25 dB, typical OIP3 +35 dBm, typical IIP3 +10 dBm, image rejection > 80 dB, IF input from −20 to +37 dBm [10].",
                "#### Measured combinations (DF9IC, 144 MHz)",
                "|h| Radio + transverter | Radio preamp | >NF",
                "| Elecraft K2 + Kuhne TR144H+40 | – | 1.0 dB",
                "| IC-756PRO II + Kuhne TR144H | off | 1.0 dB",
                "| IC-746 + Kuhne TR144H+40 | off | 1.2 dB",
                "| FT-1000MP + Javornik (two units) | off | 0.9 · 1.4 dB",
                "| FT-1000 Mark V + Kuhne TR144H, IF 14 MHz | off | 1.6 dB",
                "| FT-1000 Mark V + Kuhne TR144H, IF 28 MHz | off / on | 6.0 / 1.7 dB",
                "| TS-870 + Javornik | off | 1.9 dB",
                "| Elecraft K2 + XV144 | on | 6.0 dB",
                "~ Source [3]. The FT-1000 Mark V case at 28 MHz shows the chart in practice: with the radio preamp off the radio weighs a lot (6.0 dB), with the preamp on it drops to 1.7 dB.",
                "@fine",
                "##+ EME stations with FT-1000MP and transverter",
                "Two documented examples of the FT-1000MP used for EME on 144 MHz with a transverter: the measurements by DF9IC [3] on FT-1000MP + Javornik transverter (NF 0.9 – 1.4 dB with the radio preamp off) and the EME station of **W3SZ** [12] (4 × M2 2MXP32, LNA Technology preamps at the antenna for each polarization, LMR-600 and Andrew hardline), which in transmission uses an **FT-1000MP Mark V** with an **SSB-Electronic LT2S Mk II** transverter (IF 28 MHz) and a 2 × GU-74B amplifier, while in reception it uses the WSE hardware and the Linrad software by SM5BSZ.",
                "> In the EME budget the transverter is a box of the station diagram: it is enabled with its checkbox, you pick the model from the list (or \"custom\") and the program takes its noise figure and gain; left off, it does not enter the calculation. The chart above helps to decide whether to turn on the radio preamp.",
                ">! ✉ **Do you know another transverter or have you built one?** If you would like to make other transverters or your own transverter known, write an e-mail to the author: ccerrotta@gmail.com or ic8tem@gmail.com. All contact details are in the **AUTHOR CONTACTS AND ACKNOWLEDGEMENTS** tab.",
                "##+ The TX/RX sequencer",
                "With a power amplifier (PA) and a preamplifier near the antenna (PRE), the computer PTT does not go to the radio but to a **sequencer**, which drives the relays and then the PA and the radio in the right order [16]. The most common layout has two feed lines: the receive line can lose a few dB, because it comes after a 15 – 20 dB preamp, while the transmit line must lose as little as possible (3 dB in transmission halve the radiated power). At rest the relays keep the PRE isolated from the antenna: extra protection against lightning discharges [16].",
                "|h| ^Step | From RX to TX | From TX to RX",
                "| ^1 | the relays switch cold: radio → PA input, antenna → PA output, PRE isolated | the radio stops transmitting",
                "| ^2 | the PA is switched on | the PA is switched off",
                "| ^3 | the radio goes into transmission | the relays go back to receive, with no power applied",
                "~ Between one step and the next you need at least the relay switching time (15 – 30 ms) plus their bounce: IK1UWL recommends 100 – 200 ms, also for the PA if it has internal relays [16].",
                "For keying the transmitter PTT is better than VOX: VOX can be tripped by noise and does not use the delay of about 0.5 s with which JT65 starts modulating after PTT, so the preamplifier is protected only by the fast relay of the amplifier; with PTT that delay switches the amplifier before modulation, and a sequencer can be added [17].",
                ">! **Watch the preamplifier.** The T/R relay must isolate the open port very well: with 50 dB of isolation and 500 W at the antenna, 5 mW reach the PRE input. Aim for at least 60 dB; the most careful add a second relay that terminates the PRE into a 50 Ω load during transmission. Disable the microphone PTT button: from then on you transmit only through the sequencer (for SSB, a foot switch on the sequencer PTT, decoupled from the PC one) [16].",
                "[1] Adam Farson VA7OJ/AB4OJ, “Icom IC-9700 Test Report”, issue 5, 19 March 2021 (first edition 19 June 2019), tables 1 and 5 – https://www.qsl.net/ab4oj/icom/ic9700/9700notes.pdf",
                "[2] Adam M. Farson VA7OJ/AB4OJ, “Yaesu FT-991 Test Report”, 25 July 2015, table 1 – https://www.qsl.net/ab4oj/test/docs/ft991notes.pdf",
                "[3] DF9IC with DARC OV Durlach A35, “Test of the Large Signal Behaviour of some 144 MHz Radios”, tests from 27 February 2005 – https://www.df9ic.de/tech/trxtest/trxtest.html",
                "[4] H. T. Friis, “Noise Figures of Radio Receivers”, Proceedings of the IRE, vol. 32 (1944).",
                "[5] Preliminary test “ICOM IC-9100 review” on a pre-production unit lent by Icom UK (author and date not stated) – https://manualmachine.com/icom/ic9100/26837637-review",
                "[6] Down East Microwave, “L144-28 Rev B” – user guide (specifications: NF < 1.0 dB with conversion gain ≥ 17 dB) – https://manualmachine.com/demi/l14428revb/26842141-user-guide",
                "[7] Kuhne electronic, “TR 144 H +40” – user manual – https://manuals.online/kuhne-electronic/transceiver/tr-144-h-40/user-manual/191pa",
                "[8] RigPix, “Kuhne TR-144 Pro” – https://rigpix.com/transverters/kuhne_tr144pro.htm",
                "[9] Q5 Signal, “VHF/UHF Transverters – L144-28M REV 2”, manual (8 pages), January 2023, supplied by IC8TEM – http://q5signal.com/image/catalog/L144-28Mr2.pdf",
                "[10] HA1YA (Mechanics & Electronics), “ME2T-PRO-II & ME2HT-PRO-II 144MHz Transverter”, 25.09.2023, supplied by IC8TEM – http://www.ha1ya.hu/pdf/me2tpro2transverter.pdf",
                "[11] SSB-Electronic LT2S Mk II – cited in [12]",
                "[12] Roger Rehr W3SZ, description of the EME station – https://w3sz.com/EMEFrame1Source1.htm",
                "[13] Kuhne electronic GmbH, “MKU 144 G2 – Transverter module, 144 … 146 MHz, 28 … 30 MHz IF”, data sheet (2 pages), supplied by IC8TEM",
                "[14] ARRL Laboratory, “Icom IC-746PRO”, QST Product Review, May 2002 – https://www.radiomanual.info/schemi/ICOM_HF/IC-746Pro_review_ARRL_2002.pdf",
                "[15] Peter Hart G3SJX, “The Yaesu FT-897 HF/VHF/UHF Transceiver”, RadCom (RSGB), April 2003, pp. 18–20 – http://www.radiomanual.info/schemi/YAESU_HF/FT-897_review2_2003.pdf",
                "[16] Giorgio Marchi IK1UWL, “EME (Earth-Moon-Earth) – Guida operativa”, January 2012, § 4 “Sequenziamento relè, PA e PRE”, supplied by IC8TEM – http://www.qsl.net/ik3xtv",
                "[17] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, presentation, July 2015, supplied by IC8TEM."
            };
            d["en"]["S48"] = new string[] {
                "## Coaxial cables and losses",
                "The **COAXIAL CABLES** tab collects the attenuation of the 50 Ω cables most used by radio amateurs, in dB per 100 m at 20 °C, on the five YAEC bands. The makers' data sheets give values at different frequencies; YAEC has brought them to the bands with the power law, a straight line on the log-log chart between the two nearest frequencies of the data sheet:",
                "= α(f) = α_1 · \\p{\\frac{f}{f_1}}^{n} \\quad n = \\frac{log \\p{α_2 / α_1}}{log \\p{f_2 / f_1}} \\quad L = α(f) · \\frac{ℓ}{100}",
                "~ α in dB/100 m, ℓ cable length in metres. A plain number is the data sheet value; ≈ marks an interpolated value, and e one extrapolated beyond the last frequency of the data sheet.",
                "Cables of the same type, with the same diameter within ±0.2 mm and attenuation within 0.2 dB/100 m on all bands are grouped in one row (≡), with the mean value; equivalent names are shown with \"also:\" (for example LMR-400 = HF400, CNT-400, 50-7 low loss; LMR-600 = CNT-600). The Chinese names 50-3, 50-5, 50-7, 50-9, 50-12 give the diameter of the dielectric in millimetres.",
                "> Custom cables can be added with their five attenuations: they are saved in data\\cavi_personali.txt and also appear in the drop-downs of the station diagram of the EME budget. The tooltip of each table row cites the source of that cable.",
                "[1] The sources of the individual cables: data sheets by Times Microwave (LMR), RFS (CELLFLEX LCF/SCF), CommScope Andrew (HELIAX LDF/FSJ), Siva Cavi (HF 240/287/400), SSB-Electronic (Aircell, Ecoflex, Aircom Plus), Messi & Paoloni (Hyperflex, Ultraflex, via WiMo), Symair, SYV50-7 (szansy.com), Belden (H1000), Prospecta (RT5020, XT2400), QAXIAL (LLF195), Caledonian Cables, MIL-C-17F catalogue (RG-142, RG-393), R.F. elettronica of Senago (RG-115), the tables by DD1US and EA5IP (H100) and the table by SV1BSX for RG-58, RG-213, H-155 and H-2000 (values to be verified)."
            };
            d["en"]["S410"] = new string[] {
                "## Doppler, compensation and CFOM",
                "The Moon approaches and recedes from the two stations because of the Earth's rotation and its own orbital motion: the distance R changes by a few hundred metres per second and the signal comes back shifted in frequency. The shift is greatest when the Moon rises or sets, passes through zero when it transits south (or north) and is proportional to the frequency. YAEC computes it every second on the main screen, in the **Echo and frequencies (CFOM)** card.",
                "### How large the Doppler is",
                "For the echo of your own station the path is travelled twice (there and back):",
                "= f_{D,echo} = − \\frac{2f}{c} · \\frac{dR}{dt} \\quad \\t{e.g. } − \\frac{2 · 144.120 · 10^6}{299 792} · 0.222 = −213 \\t{ Hz}",
                "with f the frequency in Hz, c = 299 792 km/s and dR/dt the radial velocity of the Moon in km/s (positive when it recedes). For the DX signal the two legs count, his and yours:",
                "= f_{D,DX} = − \\frac{f}{c} · \\p{\\frac{dR_{me}}{dt} + \\frac{dR_{DX}}{dt}} \\quad \\t{e.g. } −480.7 · \\p{0.222 − 0.339} = +56 \\t{ Hz}",
                "~ example: Tokyo PM95 and Cape Town JF96, 06/11/2026 01:55 UTC, 144.120 MHz; dR/dt = +0.222 km/s in Tokyo and −0.339 km/s in Cape Town (YAEC values).",
                "@colonne 62",
                "|h| Band | >Maximum echo Doppler | >Compensation",
                "| 50 MHz | ≈ ±120 Hz | not needed",
                "| 70 MHz | ≈ ±165 Hz | not needed",
                "| 144 MHz | up to ≈ 340 Hz [1] | recommended",
                "| 222 MHz | ≈ ±525 Hz | needed",
                "| 432 MHz | up to ≈ 1000 Hz [1] | needed",
                "~ Values for 144 and 432 MHz from [1]; 50, 70 and 222 MHz derived in proportion to the frequency (≈ = derived).",
                "@destra",
                "> On 50 and 144 MHz the Doppler almost always stays within the waterfall of the digital program and the decoder finds it by itself; on 432 MHz it can take the signal out of the passband, and during a 60 s period it changes by a few hertz, enough to look like drift in the slow modes [2].",
                "@fine",
                "### Compensating: who corrects what",
                "Compensating the Doppler means shifting the transmit frequency, the receive frequency or both, so that the signals meet on the agreed frequency (the *sked*). Each station corrects its own Doppler and, when working a DX, also that of the DX [1]:",
                "|h| Situation | Transmit | Receive",
                "| CQ call and listening to your own echo | on the sked frequency | sked + echo Doppler (3.10.1)",
                "| QSO with a known DX (full Doppler towards the DX) | corrected so that the DX receives you on the sked | sked + Doppler DX → me (3.10.2)",
                "| CFOM, constant frequency on the Moon | sked − half of your own Doppler | sked + half of your own Doppler",
                "### CFOM – Constant Frequency On Moon",
                "With CFOM all stations behave as if a virtual transmitter on the Moon were tuned to the sked: each corrects only half of its **own** Doppler in transmission and half in reception, without needing to know the locator of the other station [2]:",
                "= f_{TX} = f_{sked} − \\frac{f_{D,echo}}{2} \\quad f_{RX} = f_{sked} + \\frac{f_{D,echo}}{2}",
                "|h| Example (Tokyo, echo Doppler −213 Hz) | >Frequency",
                "| Sked | 144.120000 MHz",
                "| Transmit on (sked + 106.5 Hz) | {r:**144.120107 MHz**}",
                "| Receive on (sked − 106.5 Hz) | {g:**144.119894 MHz**}",
                "The advantage is that several stations, and anyone who is only listening, can follow a QSO on the same frequency without recalculating the Doppler for each one. YAEC shows these two frequencies on the main screen.",
                "### The radio CAT",
                "The Doppler changes continuously, so the compensation must be updated every period. The simplest way is to leave it to the digital program (for example the *Astronomical Data* window of WSJT-X) which, through the radio **CAT**, sets the transmit and receive VFOs and keeps the radio aligned to the right frequency [1] [2]. Without CAT you can use split (one VFO for transmission and one for reception) or RIT, adjusting by hand every period: on 50 and 144 MHz it is feasible, on 432 MHz it becomes awkward [1].",
                "> Caution: for CFOM the radio must accept the frequency change via CAT **also during transmission**. Some rigs do not (for example the FT-897 mentioned in [2]): in that case you can still receive in CFOM, while transmission stays on a fixed frequency. With a transverter (§ 3.7) the CAT sets the radio at the intermediate frequency: set the transverter offset in the program, so that the frequency shown is the real one.",
                "[1] Bob Atkins KA1GT, “Doppler 101 for 1296 MHz EME (…and other bands)” (only the data up to 432 MHz are used from the article) – https://bobatkins.com/radio/EME_doppler_101.html",
                "[2] Bob Atkins KA1GT, “CFOM – Constant Frequency On Moon Doppler Mode” – https://bobatkins.com/radio/CFOM.html"
            };
            d["en"]["S411"] = new string[] {
                "## Pointing: precision, encoders and actuators",
                "YAEC computes the azimuth and elevation of the Moon to a hundredth of a degree, but the signal only arrives if the antenna really follows it. The narrower the beam, the more the mechanical precision of the pointing counts: on the YAEC bands (50 – 432 MHz) a good rotator is enough, while the dishes of the higher bands need a real actuation system.",
                "### How much is lost by pointing badly",
                "With a pointing error Δ and a half-power beamwidth θ (estimated by YAEC with §θ ≈ \\sqrt{41253/G}§), the loss is approximated by the Gaussian beam formula:",
                "= L_{point} ≈ 12 · \\p{\\frac{Δ}{θ}}^2 \\t{ dB} \\quad \\t{e.g. } 12 · \\p{\\frac{3.6}{14.4}}^2 = 0.75 \\t{ dB}",
                "~ example: 4 yagis of 17 dBi on 144 MHz, total gain 23 dBi, θ ≈ 14.4°; an error of a quarter of the beam (3.6°) costs about 0.75 dB. In EME the loss is paid twice, in transmission and in reception. Approximate formula, valid for errors small compared with the beam.",
                "### Encoder resolution",
                "The antenna position is read by an encoder (or by a potentiometer converted to digital): with n bits the full turn is divided into §2^n§ steps and the smallest step is",
                "= Δ = \\frac{360°}{2^n} \\quad \\t{e.g. } n = 10: \\frac{360°}{1024} = 0.35°",
                "|h| ^Encoder | >Steps per turn | >Step | >Loss with the 4-yagi array (θ 14.4°, error of 1 step) | Suitable for",
                "| 8 bit | 256 | 1.406° | 0.114 dB | yagi arrays on 50 and 144 MHz",
                "| 10 bit | 1,024 | 0.352° | 0.007 dB | 144 MHz with margin, 432 MHz with small arrays",
                "| 12 bit | 4,096 | 0.088° | < 0.01 dB | 432 MHz with large arrays",
                "| 14 bit | 16,384 | 0.022° | < 0.01 dB | dishes at 10 and 24 GHz [1]",
                "| 16 bit | 65,536 | 0.005° | < 0.01 dB | beyond: limit set by the mechanics, not by the encoder",
                "~ Step and loss computed with (3.11.2) and (3.11.1). A practical rule is to keep the error below a tenth of the beam: the 4-yagi array on 144 MHz is happy with 8 bits, a 3 m dish at 10 GHz (beam ≈ 0.7°) needs at least 13 – 14 bits.",
                "> The number of bits only says how finely the position is *read*: the real precision also depends on mechanical play, the flexing of the support, the wind and the calibration of north and of the horizon.",
                "### Yagi arrays: actuators and pulleys",
                "In yagi arrays (combinations of 2, 4 or more antennas) the elevation load is large and unbalanced. Linear actuators with a worm-screw motor are available on the market: in these solutions the screw only regulates the motion, while the mechanical support of the load is entrusted to pulleys. The worm screw has the advantage of not turning backwards under the load, so the array stays still even with the motor off.",
                "### Above 432 MHz: dishes",
                "From 902 MHz upwards mostly parabolic dishes are used, and the tool [1] is designed for frequencies from 1 GHz upwards. With large diameters the beam narrows to a few tenths of a degree and there is a risk of not hitting the Moon perfectly: more than motors, the station needs real mechanical actuators in azimuth and elevation, with a pointing precision largely tied to the bit resolution of the control. The **EME Link Budget & Analysis Tool** by OE2IGL and DF3GJ [1] gives ±0.035° for a good tracking system and ±0.1° for a normal one, and computes the pointing loss together with all the other terms of the link.",
                ">+ YAEC stops at 432 MHz. For the higher bands we recommend the tool by OE2IGL and DF3GJ [1]: it computes the EME budget from 1 to 300 GHz with the dish parameters (diameter, f/D, feed, surface roughness, efficiencies), pointing, libration, Sun and Moon noise and atmospheric attenuation.",
                "[1] Gerald Ihninger OE2IGL and Joachim Köppen DF3GJ, “EME Link Budget & Analysis Tool (1-300 GHz)” – https://wettersat.bplaced.net/EME/EME.html"
            };
            d["en"]["S412"] = new string[] {
                "## Digital modes for EME: Q65 and JT65",
                "The EME budget (§ 3.6) shows the estimated S/N next to the typical threshold of the chosen digital mode. This section explains where the **Q65** thresholds come from, how the signal is built and why Q65 has today largely replaced JT65 for EME on the YAEC bands. The data come from three documents: the quick-start guide by the authors of Q65 [1], the JT65A – Q65-60A comparison by K1JT [2] and the study of the coding process by G4JNT [3].",
                "### What Q65 is",
                "Q65 was introduced with WSJT-X 2.4.0 by K1JT, G4WJS, K9AN and IV3NWV for minimal QSOs over especially difficult paths; when the Doppler spread exceeds a few hertz it is the most sensitive of the WSJT-X modes, and it suits troposcatter, rain scatter, ionospheric scatter, TEP and EME from VHF upwards [1]. It uses **65-tone** FSK and derives from QRA64 of 2016; compared with it, it introduces [1]:",
                "• a new low-rate Q-ary Repeat Accumulate error-correcting code, proposed by Nico Palermo IV3NWV [3] [4];",
                "• messages and sequencing identical to FST4, FT4, FT8 and MSK144;",
                "• a sync tone clearly visible on the waterfall and a sensitive “sync curve”, effective even with meteor pings;",
                "• submodes with T/R periods of 15, 30, 60, 120 and 300 s and different tone spacings;",
                "• list decoding for messages containing parts already received, **without a callsign database**;",
                "• message averaging, when single transmissions are too weak, and multiple decoding across the whole received band.",
                "### The submodes",
                "The submode name joins the T/R period and a letter for the tone spacing: Q65-60A, Q65-120C and so on. For the A submodes the table gives the thresholds measured by simulation on an additive white Gaussian noise (AWGN) channel, as S/N in 2500 Hz with 50 % decode probability, without and with the maximum *a priori* (AP) information [1].",
                "|h| >T/R (s) | >Symbol (s) | >A spacing (Hz) | >A bandwidth (Hz) | >Transmission (s) | >S/N (dB) | >S/N max AP (dB)",
                "| 15 | 0.150 | 6.667 | 433 | 12.8 | −22.2 | −23.7",
                "| 30 | 0.300 | 3.333 | 217 | 25.5 | −24.8 | −26.6",
                "| 60 | 0.600 | 1.667 | 108 | 51.0 | −27.6 | −30.2",
                "| 120 | 1.333 | 0.750 | 49 | 113.3 | −30.8 | −32.5",
                "| 300 | 3.456 | 0.289 | 19 | 293.8 | −33.8 | −37.4",
                "~ Data from [1]. Submodes B, C, D and E have tone spacing and occupied bandwidth 2, 4, 8 and 16 times those of submode A; not all combinations exist (for example 15D and 30E do not) [1].",
                "The numbers in the table follow from a few relations, checked by YAEC against the values in [1]: the A spacing is the inverse of the symbol length, the transmission lasts 85 symbols and the occupied bandwidth is 65 spacings.",
                "= Δf = \\frac{k}{t_s} \\quad k = 1, 2, 4, 8, 16 \\t{ (A … E)} \\quad T_{tx} = 85 · t_s \\quad B_{occ} = 65 · Δf",
                "~ example Q65-60A: §t_s§ = 0.600 s → Δf = 1.667 Hz, §T_{tx}§ = 51.0 s, §B_{occ}§ = 108 Hz. Going from 60 to 120 s the threshold improves by 3.2 dB, close to the 10 · log(113.3 / 51.0) = 3.5 dB expected from the longer transmission.",
                "### Sensitivity and Doppler spread",
                "The thresholds in the table apply without spreading of the signal. In EME the Moon spreads each tone by a few hertz (Doppler spread, or *libration fading*), and the threshold gets worse. From the chart in [1] for Q65-60A without AP:",
                "|h| >Doppler spread (Hz) | >S/N at 50 % (dB) | >Loss (dB)",
                "| 0 | ≈ −27.4 | –",
                "| 5 | ≈ −25.6 | ≈ 1.8",
                "| 10 | ≈ −24.6 | ≈ 2.8",
                "| 20 | ≈ −23.2 | ≈ 4.2",
                "~ Values read by YAEC from figure 2 of [1] by interpolating between the points (≈ = derived). Decoding remains effective up to a spread of about ten times the tone spacing, and even beyond [1]: this is why submodes with a higher letter are chosen for larger spreads.",
                "> In YAEC the reference thresholds are without spread and without AP: they are for comparing days, bands and stations. If on your path the signal is strongly spread, take the loss in the table into account, or set the *custom* mode with the corrected threshold.",
                "### QSO messages at 60 s: Q65-60A, Q65-60B and Q65-60C",
                "In a minimal QSO the six standard WSJT-X messages (TX1 … TX6) are not all received in the same way: the decoder can use the parts already known (*a priori* decoding, AP), and the amount of known information grows during the QSO [1]. The table compares the three submodes most used for EME with the same 60 s period.",
                "|h| Message | Example | >AP on reception | >Q65-60A | >Q65-60B | >Q65-60C",
                "| TX6 – call | CQ W9XYZ EN37 | >q1 | >−27.6 · AP: n.a. | >−27.6 · AP: n.a. | >−27.6 · AP: n.a.",
                "| TX1 – reply with locator | W9XYZ K1ABC FN42 | >q2 | >−27.6 · AP: n.a. | >−27.6 · AP: n.a. | >−27.6 · AP: n.a.",
                "| TX2 – report | K1ABC W9XYZ −25 | >q3 | >−27.6 · AP: n.a. | >−27.6 · AP: n.a. | >−27.6 · AP: n.a.",
                "| TX3 – R and report | W9XYZ K1ABC R−26 | >q3 | >−27.6 · AP: n.a. | >−27.6 · AP: n.a. | >−27.6 · AP: n.a.",
                "| TX4 – confirmation | K1ABC W9XYZ RRR | >q4 | >−27.6 → −30.2 | >−27.6 → −30.2 | >−27.6 → −30.2",
                "| TX5 – best regards | W9XYZ K1ABC 73 | >q4 | >−27.6 → −30.2 | >−27.6 → −30.2 | >−27.6 → −30.2",
                "| Tone spacing | – | – | >1.667 Hz | >3.333 Hz | >6.667 Hz",
                "| Occupied bandwidth | – | – | >108 Hz | >217 Hz | >433 Hz",
                "| Spread still decodable (≈ 10 × spacing) | – | – | >≈ 17 Hz | >≈ 33 Hz | >≈ 67 Hz",
                "| With 5 Hz of Doppler spread, without AP | – | – | >≈ −25.6 | >smaller loss (n.a.) | >smaller loss (n.a.)",
                "~ S/N in dB referred to 2500 Hz, 50 % decode probability. −27.6 dB without AP and −30.2 dB with maximum AP are the Q65-60A values in [1]; for submodes B and C they are derived from theory: without spread the sensitivity depends on the symbol length (0.600 s), the same in the three submodes, and not on the spacing. «n.a.» = not available: [1] only gives the maximum AP gain (2.6 dB at 60 s), not that of levels q1, q2 and q3, which is smaller. Indicators q1 … q4 as in the table of the § «Recommended settings in WSJT-X»; decodable spread and the 5 Hz value from [1] and from the Doppler spread table above. K1ABC, W9XYZ and the locators are examples.",
                ">! This comparison table is derived from analysing the data we have on how Q65 works in theory, and does not reflect at all what really happens, because of the natural and man-made noise picked up live during reception.",
                "### Which submode for EME",
                "For the YAEC bands the submodes recommended in [1] are:",
                "|h| Use | Submode",
                "| EME on 50 and 144 MHz | Q65-60A",
                "| EME on 432 MHz | Q65-60B",
                "| Ionospheric scatter on 50 MHz | Q65-30A",
                "| Low-power ionospheric scatter on 50 MHz | Q65-120E",
                "| TEP on 50 MHz | Q65-15C, Q65-30C",
                "| Ionospheric scatter on 144 MHz | Q65-60C",
                "~ From [1], only for the bands up to 432 MHz. The authors encourage experimenting with other combinations.",
                "The 30 s period doubles the QSO rate with relatively strong signals, the 120 s period gains about 3 dB per single transmission [2].",
                "### Q65 and JT65 compared",
                "**JT65A** was the EME mode of the 6-metre band for nearly twenty years: with *Deep Search* decoding it reaches −28 dB in 2500 Hz (−29 dB with message averaging, § 3.6), about 15 dB below the level needed for copying CW by ear, but only for stations listed in the CALL3.TXT database of callsigns and locators. In those QSOs very little information is actually sent: about 14 bits for a callsign and locator chosen from the database, plus a 1-bit report and a 1-bit acknowledgment [2].",
                "**Q65** always sends 78-bit messages: even a minimal QSO carries an arbitrary callsign (29 bits), a real numerical report (7 bits) and the acknowledgment (1 bit), without a database [2]. K1JT prepared ten simulated files with signals at −29 dB and 1 Hz Doppler spread, five JT65A and five Q65-60A per file, and tried to decode them in four ways, with 50 possible decodes per test [2]:",
                "|h| Test | Mode | DX callsign and locator | Deep Search | >Good | >Bad",
                "| 1 | JT65A | not known | not available | 0 | 0",
                "| 2 | JT65A | not known | yes (DX in CALL3.TXT) | 28 | 1",
                "| 3 | Q65-60A | not known | – | 24 | 0",
                "| 4 | Q65-60A | known (DX Call and DX Grid) | – | 49 | 0",
                "~ From [2], table 1. JT65 settings: Deep, Deep Search, AP, 6 random erasure patterns, aggressive level 9; Q65: Fast, averaging on, automatic clearing of the average.",
                "The author's conclusions [2]: for replies to one's CQ, Q65-60A has, for **any** unknown caller, about the same sensitivity that JT65A has only for callers in the database; for all others it is **at least 3 dB** more sensitive, and more still in later messages, when both callsigns are known. False decodes are so rare that they are hard to measure. JT65 message averaging works for a single caller already identified, Q65 averaging over the whole displayed band. Finally, JT65 devotes half of the transmitted energy to sync, Q65 a quarter.",
                "> The −25 dB value for JT65 in the EME budget is the one from the WSJT-X guide without Deep Search (§ 3.6); the −28 dB with Deep Search only applies to stations listed in the database, the −29 dB with averaging to any message.",
                ">! **Inconsistency between sources.** The JT65A – Q65-60A comparison document [2] gives −29 dB for JT65A with Deep Search; K1JT's paper at the EME 2006 conference, cited in § 3.6, gives instead −28 dB for Deep Search and −29 dB for message averaging. YAEC uses the 2006 values. The two sources refer to different submodes: JT65B in the 2006 simulations, JT65A in [2].",
                "### How Q65 builds the signal",
                "G4JNT reconstructed from the WSJT-X source code the path from the message to the transmitted tones, checking it with the WSJT-X program Q65CODE.EXE [3]. In short:",
                "• **Source coding.** As in FST4, FT8, FT4 and MSK144, the message becomes 71 data bits plus 6 type bits, 77 in all. A free text has up to 13 characters from a 42-symbol alphabet (space, digits, letters and + - . / ?), and §42^{13}§ is less than §2^{71}§; telemetry mode carries up to 18 hexadecimal digits [3].",
                "• **Symbols.** With one more bit the 78 bits are split into 13 six-bit symbols, values 0 to 63 [3]: the same length as the 78-bit messages of [2].",
                "• **CRC.** A 12-bit check (two symbols), with polynomial 1100000001111 and the bits of each symbol reversed for compatibility with the work of IV3NWV, is used to reject false decodes [3]. With the CRC there are 15 symbols.",
                "• **Parity.** The 50 check symbols come from a 15 × 50 “generator” matrix, with arithmetic in the Galois field GF(64): addition is an XOR, multiplication is done with tables of logarithms and antilogarithms [3].",
                "• **Code.** The code is a (65,15) code with six-bit symbols; the two CRC symbols are “punctured”, that is not transmitted, leaving an effective (63,13) code [1] [3].",
                "• **Synchronization.** 22 sync symbols, all on tone 0, in fixed pseudo-random positions are added to the 63 symbols; 85 symbols are transmitted, with 65 tones: 0 for sync, 1 to 64 for data [1] [3].",
                "= f_n = f_0 + n · Δf \\quad n = 0 … 64",
                "~ §f_0§ frequency of tone 0, Δf spacing of the submode [3]. With 22 sync symbols out of 85, sync takes about a quarter of the transmission, as noted in [2].",
                "### Recommended settings in WSJT-X",
                "For EME with Q65 the authors recommend, in WSJT-X: *File → Settings → General* with **Enable VHF and submode features** and **Decode after EME delay** on and **Single decode** off; in the *Decode* menu **Fast**, **Enable averaging** and **Auto Clear Avg after decode** [1]. Each Q65 decode carries the letter “q” and one or two digits: the first gives the *a priori* information used, the second the number of averaged sequences [1].",
                "|h| Flag | A priori information used",
                "| q0 | none",
                "| q1 | CQ",
                "| q2 | my callsign",
                "| q3 | my callsign and the DX callsign",
                "| q4 | both callsigns and RRR, RR73, 73 or blank",
                "~ From [1]. The authors warn not to pay too much attention to the S/N values shown by the decoder, which were still being improved [1]: for comparisons with the YAEC EME budget it is better to use several QSOs rather than a single reading.",
                "### The procedure with DXpeditions (W7GJ)",
                "Lance Collister W7GJ, who has been running 6 m EME expeditions for years, describes how to call a DXpedition in Q65-60A during a pile-up [6]. First of all, the computer clock must be very accurate and the transmit frequency very stable [6].",
                "• **Periods.** The DXpedition always transmits in the first sequence (even minutes); callers transmit in the second (odd minutes) [6].",
                "• **Frequency.** Choose a clear frequency in the passband and stay there: Q65 averages the calls of each station on its own frequency, and if you move the benefit of your previous calls is lost. Leave about 100 Hz between you and the others and check that Doppler does not take your signal out of the DX passband; callers coordinate on the ON4KST EME chat [6].",
                "• **Mode.** Use the Q65-60A digital-contest procedure: in WSJT-X, *File → Settings → Advanced*, one of the “Special Operating Activity” options NA VHF, WW Digi or ARRL Digi (after version 2.6.1 also Q65 Pileup). Enter the DX call and locator in DX Call and DX Grid, press Generate Std Msgs and start from message TX2, not from CQ [6].",
                "• **Keep calling.** On 6 m, propagation between linearly polarized stations is often non-reciprocal: the DX may copy you even if you do not copy him. Do not stop calling and do not go back to a previous message when the DX is in QSO with others or fades away: every message contains both callsigns and the QSO resumes where it stopped. With Q65 Pileup the DX needs at least one decode of you in each Moon pass [6].",
                "• **RRR, never RR73.** On EME always use RRR: RR73 is sent only once and the QSO is logged even if the other station did not receive it. The QSO is complete when one of the two stations receives the final RRR; whoever receives it answers 73 as long as needed, so in *Settings → Behavior* “Disable Tx after sending 73” must not be checked [6].",
                "• **Watch the screen.** Even if you do not decode the DX, his trace on the waterfall (Wide Graph) or the orange Q65 spike tell you that you will probably copy him as soon as he answers. Clear the average by hand when you see he has worked someone else: you may be next [6].",
                "|h| DX (first sequence, even minutes) | Callers (second sequence, odd minutes)",
                "| CQ TX7MB CI00 | TX7MB OH2BC KP30",
                "| OH2BC TX7MB R CI00 | TX7MB OH2BC RRR",
                "| G8BCG TX7MB R CI00 | TX7MB G8BCG RRR",
                "| G8BCG TX7MB 73 | TX7MB G8BCG 73",
                "~ Shortened example from [6], with TX7MB (CI00) as the DXpedition: each caller stays on its own frequency and switches to RRR when it receives its own “R CI00”.",
                "> Common Moon windows are short, especially at moonrise and moonset, when many stations use ground gain: the Live position and +- 24h tab and the Distance and Dgrd tab show when the Moon is visible from both stations.",
                ">⚠ The discussion of theoretical limits loses its meaning the moment you are actually receiving signals: a sudden local noise can make reception worse, and so can Faraday rotation (§ 3.3).",
                "[1] Joe Taylor K1JT, Bill Somerville G4WJS, Steve Franke K9AN, Nico Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 April 2021 (WSJT-X 2.4.0), supplied by IC8TEM.",
                "[2] Joe Taylor K1JT, “Sensitivity Comparison of JT65A and Q65-60A” (test files JT65A_and_Q65-60A.zip), supplied by IC8TEM – https://physics.princeton.edu/pulsar/k1jt/JT65A_and_Q65-60A.zip",
                "[3] Andy Talbot G4JNT, “The Q65 Coding Process used in WSJT-X”, October 2023, supplied by IC8TEM.",
                "[4] Nico Palermo IV3NWV, presentation at the EME 2016 conference on QRA codes, cited in [3] – http://www.eme2016.org/wp-content/uploads/2016/08/EME-2016-IV3NWV-Presentation.pdf",
                "[5] WSJT-X source code (file Q65_encoding_modules.F90 and others), cited in [3] – https://wsjt.sourceforge.io/wsjtx.html",
                "[6] Lance Collister W7GJ, “Q65-60A QSO Procedure and Tips for EME DXpeditions”, revised 3 April 2023, supplied by IC8TEM – http://www.bigskyspaces.com/w7gj/"
            };
            d["en"]["S54"] = new string[] {
                "## EME literature by SM5BSZ",
                "Leif Åsbrink SM5BSZ, author of Linrad, has also published on his website studies on EME that go beyond his software. Two works useful for understanding the Earth – Moon – Earth path:",
                "• “Selecting Polarisation for EME” (25 April 1997): how geometry, reflection on the Moon, Faraday rotation and ionospheric absorption change the polarization, with practical advice on choosing the polarization in transmission and reception according to the frequency – https://sm5bsz.com/polarity/emepol.htm",
                "• “EME Path Modulation” (23 February 2000): spectra of a carrier of a few minutes transmitted by SM5FRH and received by SM5BSZ via the Moon, with the narrow specular component and the wider diffuse one, which behave differently with polarization – https://sm5bsz.com/sm5frh/sm5frh.htm",
                "On the sporting side of EME: Henryk Kotowski SM0JHF, “Moonbouncers Are Also Contesters”, contesting.com, 20 May 2002 – https://www.contesting.com/articles/294"
            };
            d["en"]["S55"] = new string[] {
                "## Other EME calculation tools",
                "• **EME Link Budget & Analysis Tool (1-300 GHz)** by Gerald Ihninger OE2IGL and Joachim Köppen DF3GJ: complete budget for the bands from 1 GHz upwards, with dish parameters, pointing, libration and atmosphere – https://wettersat.bplaced.net/EME/EME.html",
                "• **WSJT-X** by Joe Taylor K1JT and co-workers: digital modes for EME (JT65, Q65 and others) and the Astronomical Data window with Doppler and CAT – https://wsjt.sourceforge.io"
            };
            d["en"]["S43"] = new string[] {
                "## Polarization, Dpol and MNR",
                "The local polarization angle is computed as in WSJT-X from the latitude and from the azimuth and elevation of the Moon; §D_{pol}§ is the difference between the angles of the two stations, between −90° and +90°. The linear polarization loss (at most 30 dB) and the maximum non-reciprocity MNR (at most 25 dB) are:",
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}",
                "Faraday rotation cannot be predicted and is not included.",
                "The spatial offset can be calculated, because it depends only on the position of the two stations: seen from the Moon, a horizontal antenna at the North Pole and one at the equator look one horizontal and the other vertical. Faraday rotation instead is random: the signal crosses the ionosphere twice, going and coming back, and rotates according to the electron density of the moment. It may happen that you hear the DX and he does not hear you; at 90° the signal is not attenuated, it disappears. Those who have horizontal and vertical antennas can always receive with the best polarization and, if the other station does not answer, switch the transmit polarization with a relay [1].",
                "> Between distant stations, for example between the northern and the southern hemisphere, the geographic position alone can bring §D_{pol}§ close to 90°. When it exceeds 60° in the next 24 hours, the program shows a warning as soon as the locators are entered [1].",
                "With linearly polarized antennas the spatial-offset loss is about 3 dB at 45°, 6 dB at 60° and more than 20 dB at 90°: this is why the warning starts at 60° [2].",
                "### Faraday rotation",
                "The ionosphere contains free electrons which, guided by the Earth's magnetic field, move in spirals: a linearly polarised wave passing through it comes out with its plane of polarisation rotated. This is Faraday rotation [3]. It depends on the number of electrons along the path and falls with the square of the frequency [3]:",
                "= F_{f} = F_{144} · \\p{\\frac{144}{f}}^{2}",
                "~ §F_{144}§ is the rotation at 144 MHz, §f§ the frequency in MHz. A typical daytime value at 144 MHz is 180° with the Moon at the zenith and about four times as much at 10° elevation, because the path through the ionosphere is longer [3].",
                "|h| Band | >Moon at the zenith | >Moon at 10° elevation",
                "| 50 MHz | >≈ 1,490° (more than 4 turns) | >≈ 5,970°",
                "| 144 MHz | >180° | >≈ 720°",
                "| 432 MHz | >≈ 20° | >≈ 80°",
                "~ Rotation for one pass through the ionosphere, typical daytime value; 144 MHz from [3], the other bands derived by YAEC with the formula above (≈ = derived). From 1296 MHz upwards it can be taken as zero [3].",
                "• **It does not cancel on the way back.** The sense of rotation does not depend on the direction in which the wave travels: after the second pass through the ionosphere the signal is rotated again, in the same sense [3]. Each station adds the rotation of the ionosphere above it.",
                "• **It changes with time.** The number of electrons varies between day and night, at sunrise and sunset and with solar activity: with a very active Sun the rotation is strong and may vary rapidly, and during auroras the polarisation can change within a few milliseconds [3]. This is why it cannot be predicted by a calculation.",
                "• **It adds to the spatial offset.** The spatial offset (§D_{pol}§) has opposite sign in the two directions of the link, while Faraday rotation keeps the same sense: in one direction the two rotations add, in the other they subtract. So it can happen that you hear the DX and he does not hear you, or the other way round [1]. The loss follows the same law as §D_{pol}§, §L = −20 · log_{10} \\a{cos Δ}§, with Δ the total offset: at 90° the signal disappears.",
                "• **What to do.** From 50 to 432 MHz linear polarisation is used: a system that lets you choose the plane of polarisation is a good idea, preferably switched electronically rather than by turning the whole antenna mechanically [3]. When calling CQ it is more effective to alternate horizontal and vertical than to use circular polarisation, which always costs 3 dB [3]. With horizontal and vertical antennas you receive on the better polarisation and, if the other station does not answer, switch the transmitting one [1].",
                "> On 432 MHz Faraday rotation is small and the spatial offset, which YAEC computes, dominates; on 50 and 144 MHz it can make several turns and is unpredictable: §D_{pol}§ and the warning above 60° only account for the spatial part.",
                "### Choosing polarisation for EME: summary of the SM5BSZ article",
                "The article «Selecting Polarisation for EME» by Leif Åsbrink SM5BSZ (25 April 1997) is public and can be read on his website: https://sm5bsz.com/polarity/emepol.htm. The author of this program considers it useful to offer here a summary of it, written in his own words, as a starting point; for the full explanations please read the complete article [3].",
                "• **Four effects.** Along the Earth – Moon – Earth path the polarisation changes because of the spatial offset, the reflection on the Moon, Faraday rotation and absorption in the ionosphere [3].",
                "• **Spatial offset.** Seen from the Moon, two distant antennas on the curved Earth are not parallel. It only concerns linear polarisation, is easy to calculate and does not depend on frequency [3]: it is YAEC's §D_{pol}§.",
                "• **Reflection on the Moon.** At low frequencies, such as 144 MHz, the Moon behaves like a smooth sphere: linear polarisation stays linear, circular polarisation reverses its sense, and about 1 % of the energy ends up in the «wrong» polarisation. At 10 GHz the surface is rough and the signal comes back depolarised [3].",
                "• **Faraday rotation.** It is described in the previous subsection: it falls with the square of the frequency, adds on the way out and on the way back, and cannot be predicted [3].",
                "• **Ionospheric absorption.** It also falls with the square of the frequency: at 144 MHz, by day and at 10° elevation, it is about 0.1 dB. It only matters with very high solar activity; during strong auroras the polarisation can change faster than a narrow-band receiver can follow [3].",
                "• **From 50 to 432 MHz.** Almost everyone uses linearly polarised yagis: the author recommends a system with switchable linear polarisation, preferably electronic; a mechanical rotation is fine if the quarter turn takes one or a few seconds [3]. On reception you choose the polarisation with the strongest signal (a two-channel receiver is quicker with weak signals); when calling CQ it is better to alternate horizontal and vertical than to use circular, which always loses 3 dB [3].",
                "• **From 10 GHz upwards.** The Moon depolarises the signal, the transmitting polarisation no longer matters, and a two-channel receiver on two orthogonal feeds is needed [3]. These frequencies are outside the YAEC bands.",
                "• **Which polarisation to transmit.** If you receive a station, you can work out which polarisation to transmit so that your signal reaches it correctly [3]. With angles in degrees (0° horizontal, 90° vertical), P is the other station's transmitting polarisation, R the one you receive it with, S the spatial offset, F the Faraday rotation and T your best transmitting polarisation:",
                "= R = P + S + F \\quad P = T − S + F \\quad T = 2 · S − R",
                "~ Eliminating F from the first two relations gives §T = 2 · P + 2 · S − R§; for a linear antenna §2 · P§ is 0° or 180°, which is the same polarisation, leaving §T = 2 · S − R§ [3]. Without Faraday rotation (§F§ = 0, from 1296 MHz upwards) the best polarisation for transmitting is the same one you receive best with, §T = R§. The article notes that the rule matches KL7WE's and cites W5UN's SKYMOON program for calculating S [3].",
                "> In YAEC the spatial offset S is the §D_{pol}§ computed in Moon position and in Live position and +- 24h; Faraday rotation F cannot be calculated. For the examples, special cases and figures, read the full SM5BSZ article [3].",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s",
                "[2] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, presentation, July 2015, supplied by IC8TEM.",
                "[3] Leif Åsbrink SM5BSZ, “Selecting Polarisation for EME”, 25 April 1997 – https://sm5bsz.com/polarity/emepol.htm"
            };
            d["en"]["S44"] = new string[] {
                "## Sky noise and Dgrd",
                "The sky temperature behind the Moon (§T_{sky}§) at 144 MHz is taken along the ecliptic from a table in 2° steps (WSJT-X) and, in the Sky view, from a 2° all-sky map derived from the Global Sky Model; other frequencies are scaled with spectral index 2.6:",
                "= T(f) = \\p{T_{144} − 2.7} · \\p{\\frac{144}{f}}^{2.6} + 2.7 \\t{ K}",
                "Dgrd, as in WSJT-X, adds the effect of the Moon distance d and that of the sky noise:",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2.6} \\t{ K}",
                "### What Dgrd means",
                "**Dgrd** (*degradation*) tells how many dB the Moon echo is worse, at that moment, than in the best possible conditions: Moon at perigee and cold sky behind the Moon. It does not depend on the station, only on the Moon and the sky: this is why it is used to choose days and hours, not to calculate the link, which is the job of the EME budget.",
                "• **0 dB** is the ideal case; values are always negative. **−3 dB** means half the S/N of the ideal case, **−6 dB** a quarter.",
                "• The first term of the formula is the **distance**: between perigee (about 356 900 km) and apogee (about 406 700 km) the echo changes by about 2.3 dB, because the path loss grows with the fourth power of the distance. It looks small, but doubling the antennas gains only 3 dB in theory [1].",
                "• The second term is the **sky noise** behind the Moon: when the Moon passes in front of the Milky Way the sky temperature rises a lot and Dgrd can drop by several dB, more than the distance does.",
                "• Typical values are −1, −1.5 or −2 dB. With the Moon on the centre of the Galaxy I2FAK saw −11 dB, the worst possible conditions, and still completed a QSO with a very weak station, a DXpedition from Djibouti, thanks to a 16 + 16 antenna system: in such bad conditions the station must be perfectly calibrated, and experience counts more than the software predictions [1].",
                "• For a small station every dB counts: a day with Dgrd −1 dB and one with −5 dB can make the difference between a completed QSO and no decode at all.",
                "> In the program: the DGRD box of the Live position and +- 24h tab shows the current value between the minimum and the maximum of the chart; the Distance and Dgrd tab shows the calendar of the next days, the chart with the distance and the three best days.",
                "### The Moon in front of the noise sources of the Galaxy",
                "Every month the Moon travels along the band of the ecliptic (within about 5° of it) and crosses the Milky Way twice. The two crossings are not the same:",
                "• **Sagittarius, centre of the Galaxy**: the hottest part of the sky; at 144 MHz the sky temperature behind the Moon reaches a few thousand K, against about 200 K in the cold regions, and that region is noisier than the Sun [1]. Here the Moon is also at its lowest declination, around −30° in the years of maximum declination: from northern Italy (about 45° N) it rises to only 15 – 16° of elevation and stays above 5° for about 6 hours (about 7 hours above the horizon), while at +30° it reaches about 75° and stays above 5° for about 15 – 16 hours [1]. It is the worst period of the month.",
                "• **Taurus and Gemini, on the opposite side (anticentre)**: the Milky Way is much less hot, but in Taurus, very close to the ecliptic, lies the **Crab Nebula** (Taurus A), one of the strongest radio sources in the sky: when the Moon passes in front of it or next to it the noise rises.",
                "• Sky noise grows as the frequency goes down: at 50 MHz it weighs much more than at 144 MHz, at 432 MHz much less (the program scales it with the spectral index 2.6).",
                "> In the program: the Sky view colours the sky from blue (cold) to red (hot) and shows where the Moon is; the Tsky column of the Moon position tab and the calendar of Distance and Dgrd tell when the Moon is in front of the hot regions.",
                "### The Moon's declination",
                "The **declination** (§δ§) is the Moon's «latitude» on the sky: how many degrees it is north (+) or south (−) of the celestial equator. The program computes it from the date and time and uses it in every calculation (elevation, windows, Tsky, Dpol, Doppler): you do not enter it. Knowing it, however, helps you choose the days.",
                "• **Monthly cycle**: in about 27.3 days the declination goes from its northern maximum to its southern maximum and back. With the Moon on the side of your own hemisphere (positive in the north, negative in the south) it rises higher and stays above the horizon for more hours; on the opposite side it stays low and up for only a few hours [1].",
                "= El_{max} ≈ 90° − \\a{φ − δ} \\quad cos H_{0} = − tan φ · tan δ \\quad t_{su} = \\frac{2 · H_{0}}{15°} \\t{ h}",
                "~ §φ§ is the station latitude, §H_{0}§ the hour angle at moonrise and moonset, §t_{su}§ the hours with the Moon above the horizon (no obstacles, no refraction). Example at 41° N: with §δ§ = +28° the Moon reaches about 77° and stays up about 15.7 hours; with §δ§ = −28° it stops at about 21° and stays up about 8.3 hours.",
                "• **Links between hemispheres**: in a north – south QSO the two stations prefer opposite declinations; the longest common windows often come with the Moon near the celestial equator (declination around 0°), when neither station is at a disadvantage.",
                "• **18.6-year cycle**: the width of the monthly swing changes slowly, from about ±18.3° to about ±28.6°. The maximum (major lunar standstill) was in 2024 – 2025; towards 2034 the swing will be at its minimum, with less extreme months: the Moon will not go so low, but it will not climb so high either.",
                "• **Declination and noise**: the Moon reaches its lowest declination when it passes in front of Sagittarius, the noisiest part of the sky, and its highest in Taurus and Gemini, where the sky is colder. For stations in the northern hemisphere, the week of lowest declination therefore combines a low Moon, few useful hours and high Tsky [1].",
                "> In the program: below the chart of the Distance and Dgrd tab, the declination curve shows the northern and southern maxima with their date; the green area shows when the Moon is on the side of your hemisphere (hide the curve with the Declination curve box). The value at each instant is in the optional Declination (°) column of the Moon position tab and in Live position and +- 24h.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["en"]["S45"] = new string[] {
                "### Why the Sun matters",
                "The **Sun** is the strongest noise source in the sky. Around new Moon the Sun and the Moon are close in the sky: even if the Sun stays out of the main lobe, it enters through the side lobes, and within a few beam widths the received noise grows a lot. This is why, in practice, the week of the new Moon is almost always to be avoided.",
                "• How much it weighs depends on the antenna gain (narrower lobe, Sun farther away in beam widths), on the side-lobe level and on **solar activity**: the solar flux, in SFU, changes from one day to the next and grows a lot during flares.",
                "• This is why an antenna with **strongly attenuated side lobes** is essential: the side lobes pick up the surrounding noise and add it to that of the main lobe [1].",
                "• During a solar eclipse the Moon is right in front of the Sun: I2FAK still completed a QSO by pointing 2.5 – 3° to one side of the Moon, so the narrow lobe of his array attenuated the Sun noise [1].",
                "• The Sun below the receiver horizon does not count, even at new Moon.",
                "> In the program: the calendar of Distance and Dgrd marks with the ☀ symbol the days with the Sun close to the Moon (orange or red); the Solar noise tab calculates, with the measured flux, how much extra noise the Sun brings at the chosen moment.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["de"] = new Dictionary<string, string[]>();
            d["de"]["S32"] = new string[] {
                "## Der Maidenhead-Locator (WWL)",
                "Der **Maidenhead-Locator**, auch WWL (World Wide Locator) oder QTH-Locator genannt, ist der Code, mit dem Funkamateure den Standort ihrer Station angeben. Er wurde von John Morris G4ANB entwickelt und im April 1980 von der VHF-Arbeitsgruppe der IARU auf einem Treffen in Maidenhead (England) angenommen; er ersetzte den alten QRA-Locator, der nur Europa abdeckte [1]. Seit 1999 ist das geodätische Datum WGS-84, dasselbe wie beim GPS [1]. YAEC leitet aus dem Locator die geografische Breite und Länge der Station ab und daraus alle Berechnungen.",
                "### Wie er aufgebaut ist",
                "Der Locator ist eine Folge von Paaren: Jedes Paar gibt zuerst die Länge und dann die Breite an und unterteilt das Rechteck des vorhergehenden Paares in kleinere Teile. Die Paare wechseln zwischen Buchstaben und Ziffern [1]. Ein Beispiel mit 14 Zeichen: **PM 95 UP 98 KB 75 MI** (Tokio).",
                "@locator PM 95 UP 98 KB 75 MI",
                "|h| Paar | Name | Zeichen | >Unterteilung | >Größe (Länge × Breite) | >Stellen | >Seitenlänge bei 35,7° (Tokio) | >Maximaler Fehler",
                "| 1. | Feld (field) | A … R | 18 × 18 | 20° × 10° | 2 | – | –",
                "| 2. | Großfeld (square) | 0 … 9 | 10 × 10 | 2° × 1° | 4 | 181 × 111 km | ±106 km",
                "| 3. | Kleinfeld (subsquare) | A … X | 24 × 24 | 5′ × 2,5′ | 6 | 7,5 × 4,6 km | ±4,4 km",
                "|+ 4. | erweitertes Großfeld | 0 … 9 | 10 × 10 | 30″ × 15″ | **8** | 753 × 463 m | **±442 m**",
                "| 5. | erweitertes Kleinfeld | A … X | 24 × 24 | 1,25″ × 0,625″ | **10** | 31 × 19 m | **±18 m**",
                "| 6. | – | 0 … 9 | 10 × 10 | 0,125″ × 0,0625″ | 12 | 3,1 × 1,9 m | ±1,8 m",
                "| 7. | – | A … X | 24 × 24 | 0,0052″ × 0,0026″ | 14 | 13 × 8 cm | ±8 cm",
                "~ Größen nach den Regeln in [1]; Seitenlängen und maximaler Fehler (halbe Diagonale, Station in der Mitte des Feldes) von YAEC für die Breite von Tokio berechnet: zu den Polen hin wird die Ost-West-Seite kürzer. Buchstaben werden groß geschrieben, wie die IARU 2019 klargestellt hat [1]; YAEC akzeptiert auch Kleinbuchstaben und wandelt sie um.",
                "> Über 8 Zeichen hinaus gibt es keinen gemeinsamen Standard: Das 5. und die folgenden Paare sind nicht formal festgelegt, und die verbreitetste Praxis, der auch YAEC folgt, wiederholt die Regeln der vorhergehenden Paare (Buchstaben zur Basis 24, Ziffern zur Basis 10). Andere Programme können andere Kodierungen verwenden, daher wird ein langer Locator nicht überall gleich gelesen [1].",
                "### Wie viele Zeichen verwenden",
                "Auf KW wird meist das Großfeld (4 Zeichen) verwendet, auf den YAEC-Bändern von 50 bis 432 MHz das Kleinfeld (6 Zeichen) [1]. Diese Regeln gelten für den QSO-Austausch und für Conteste: In der IARU-Region 1 werden zum Beispiel die Entfernungen zwischen den Mittelpunkten der Kleinfelder gemessen [1]. Für die Berechnungen von YAEC sieht die Wahl anders aus:",
                "|h| Zeichen | Empfohlene Verwendung in YAEC",
                "| 4 | nur für eine grobe Schätzung: Azimut und Elevation des Mondes können bis zu etwa 1° falsch sein, weil sich der lokale Horizont alle 111 km um etwa 1° neigt",
                "| 6 | Locator der DX-Station, QSOs und EME-Budget: Der Fehler in der Mondrichtung beträgt wenige Hundertstel Grad",
                "| **8** | eigene Station, für die Erkundung meiner Hindernisse: Er bestimmt das Wohnviertel oder den Hügel",
                "|+ **10** | eigene Station, mit dem besten Ergebnis: Er bestimmt das Gebäude oder den Antennenmast",
                "| 12 – 14 | werden akzeptiert, bringen aber nichts: Die Genauigkeit übersteigt die eines gewöhnlichen GPS (wenige Meter) und die Größe der Antenne selbst",
                "### Locator und Hindernisse",
                "Für die Richtung des Mondes genügen 6 Zeichen: Der Mond ist etwa 380 000 km entfernt, und die ±4,4 km eines 6-stelligen Locators ändern Azimut und Elevation um etwa 0,04°, verglichen mit dem Öffnungswinkel der Antenne vernachlässigbar. Bei **lokalen Hindernissen** (Gebäude, Bäume, Hügel) ist es umgekehrt: Sie sind einige zehn oder hundert Meter von der Antenne entfernt, und mit 6 Zeichen kann die Station irgendwo in einem Rechteck von 7,5 × 4,6 km liegen, sodass sich die Hindernisse nicht einordnen lassen. Mit 8 Zeichen sinkt der Fehler auf etwa 450 m, mit 10 auf etwa 20 m: Das ist die Genauigkeit, die der Reiter **Reconnaissance of my obstacles** braucht, um die Bereiche, in denen die Antenne verdeckt ist, richtig zu zeichnen.",
                ">+ Praktischer Tipp: Ermitteln Sie den 10-stelligen Locator aus den GPS-Koordinaten des Punktes, an dem die Antenne steht (nicht des Hauseingangs), und tragen Sie ihn im Reiter Position live und +- 24h als **my locator** ein. Für die DX-Station genügt der 6-stellige Locator, den sie Ihnen nennt.",
                "[1] Wikipedia, “Maidenhead Locator System” (Ursprung G4ANB und IARU-VHF-Treffen in Maidenhead 1980, Aufbau der Paare, WGS-84 seit 1999, Erweiterungen über 8 Zeichen hinaus, Klarstellung der IARU 2019, Verwendung auf KW und VHF/UHF, Entfernungen zwischen Kleinfeldmittelpunkten) – https://en.wikipedia.org/wiki/Maidenhead_Locator_System"
            };
            d["de"]["S46"] = new string[] {
                "### Die Formeln des EME-Budgets",
                "Die Streckendämpfung folgt der Radargleichung: Das Signal geht von der Station zum Mond, ein Teil davon wird gestreut und kehrt zur Erde zurück. Die Entfernungen §d_1§ und §d_2§ sind die topozentrischen Entfernungen der beiden Stationen im gewählten Zeitpunkt, daher ist der Unterschied zwischen Perigäum und Apogäum (etwa 2,3 dB) bereits enthalten.",
                "= λ = \\frac{c}{f} \\quad σ = 0.065 · π · R_M^2",
                "= L_{EME} = 10 · log_{10} \\b{\\frac{\\p{4π}^3 · d_1^2 · d_2^2}{σ · λ^2}} \\t{ dB}",
                "~ mit §c = 299 792 458 \\t{ m/s}§, §R_M = 1 737,4 \\t{ km}§ (Mondradius), Reflexionsvermögen des Mondes 0,065.",
                "Die abgestrahlte Leistung und das Signal an den Klemmen der Empfangsantenne:",
                "= EIRP = P_{dBW} − L_{TX} + G_{ant} + 10 · log_{10} N + G_g \\quad S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                "= G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}} \\quad L_{pol} = −20 · log_{10} \\a{cos D_{pol}}",
                "~ Bodengewinn (Kontrollkästchen „BETA- antenna without elevation“): horizontal polarisierte Antenne in der Höhe h, berechnet bei der Mondelevation, höchstens +6 dB.",
                "Die Rauschzahl der Empfangskette ergibt sich aus der Friis-Formel, in linearen Werten (§F = 10^{NF/10}§, §G = 10^{G_{dB}/10}§):",
                "= F_{tot} = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + … \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "Die Rauschzahl des Funkgeräts wird aus seinem MDS abgeleitet, gemessen in der Bandbreite B:",
                "= NF_{radio} = MDS + 174 − 10 · log_{10} B",
                "= T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e \\quad N = 10 · log_{10} \\p{k · T_{sys} · B} + 30 \\quad \\frac{S}{N} = S_{ant} − N",
                "~ mit §k = 1,380649 · 10^{−23} \\t{ J/K}§ (Boltzmann) und B der Bandbreite in Hz. §T_{ant}§ ist die Antennentemperatur aus den Tabellen von VE7BQH (Antenne um 30° geneigt); §ΔT_{sky} = max \\p{0, T_{sky} − T_{ref}}§, mit §T_{ref}§ = 200 K bei 144 MHz, skaliert mit dem Index 2,6.",
                "Das EME-Budget berechnet keine Reserve für die Betriebsart: Es zeigt das geschätzte S/N, bezogen auf die von WSJT-X verwendete Referenzbandbreite von 2500 Hz, und daneben die typische Schwelle der gewählten Betriebsart nur als Anhaltspunkt. Eine Schwelle ist keine harte Grenze: Mit den Hilfen des Dekoders gelingt die Dekodierung auch darunter, wie die Tabelle zu JT65 und die Anmerkungen unten zeigen.",
                "= \\frac{S}{N}_{2500} = \\frac{S}{N}_{B} + 10 · log_{10} \\frac{B}{2500}",
                "|h| Betriebsart | >Typische Schwelle, einzelne Nachricht (2500 Hz) | Quelle",
                "| JT65 | −25 dB | [1]",
                "| JT9 | −27 dB | [1]",
                "| JT4 | −23 dB | [1]",
                "| FT8 | ≈ −20 dB | [1]",
                "| FT4 | ≈ −16,5 dB | [1]",
                "| Q65-15A | −22,2 dB | [2]",
                "| Q65-30A | −24,8 dB | [2]",
                "| Q65-60A | −27,6 dB | [2]",
                "| Q65-120A | −30,8 dB | [2]",
                "| Q65-300A | −33,8 dB | [2]",
                "| WSPR | −31 dB | [1]",
                "~ Schwellen für 50 % Dekodierwahrscheinlichkeit, gemessen auf einem Kanal mit additivem weißem gaußschem Rauschen (AWGN). Bei Q65 bringt die *A-priori*-Dekodierung (AP), die die im QSO bereits bekannten Rufzeichen nutzt, je nach Untermodus 1,5 bis 3,6 dB (zum Beispiel Q65-60A −30,2 dB) [2]; YAEC zeigt die vorsichtigeren Werte ohne AP als Anhaltspunkt. Mit einer Doppler-Verbreiterung von einigen Hertz verschlechtert sich die Schwelle: bei Q65-60A um etwa 2 dB bei 5 Hz und etwa 3 dB bei 10 Hz (abgelesen aus dem Diagramm in [2]). Aufbau von Q65, seine Untermodi und der Vergleich mit JT65 stehen in § 3.12. Für EME empfiehlt das Dokument Q65-60A auf 50 und 144 MHz und Q65-60B auf 432 MHz [2]: Die Untermodi B – E haben den 2- bis 16-fachen Tonabstand und die 2- bis 16-fache belegte Bandbreite des Untermodus A.",
                "Für JT65 hat K1JT die Grenzen für jede Art der Dekodierung veröffentlicht, ermittelt durch Simulationen des Untermodus JT65B [5]:",
                "|h| JT65: Art der Dekodierung | >S/N (2500 Hz) | Quelle",
                "| Beliebige Nachricht, auch Freitext | −24 dB | [5]",
                "| Rufzeichen in der Datenbank (Deep Search) | −28 dB | [5]",
                "| Beliebige Nachricht, mit Mittelung mehrerer Aussendungen | −29 dB | [5]",
                "| Nur Synchronisation (Zeit und Frequenz) | −30 dB | [5]",
                "| Kurznachrichten RO, RRR, 73 | −32 dB | [5]",
                "~ Die Anleitung von WSJT-X nennt −25 dB für eine einzelne Nachricht [1]. Deep Search prüft nur Nachrichten mit CQ oder dem eigenen Rufzeichen plus einem Rufzeichen und Locator aus der Datenbank: Ein unbekanntes Rufzeichen oder Freitext lässt sich nur mit dem allgemeinen Dekoder dekodieren, bei Bedarf mit Mittelung [5]. Die Dekodierung ist „alles oder nichts“: Eine Nachricht wird ganz oder gar nicht gelesen, sie verschlechtert sich nicht allmählich in der Nähe der Grenze [5]. Deshalb zeigt YAEC die dB über oder unter der Schwelle nicht mehr an.",
                "### Bodengewinn in der Praxis",
                "Der Bodengewinn des Kontrollkästchens „BETA- antenna without elevation“ folgt dem Modell des ebenen, reflektierenden Bodens: Direkter und reflektierter Strahl addieren sich, wenn der Wegunterschied eine halbzahlige Anzahl n von Wellenlängen beträgt, und löschen sich aus, wenn er ganzzahlig ist, mit §n · λ = 2 · H · sin α§; der Reflexionspunkt liegt in der Entfernung §D = \\frac{H}{tan α}§ von der Antenne [3]. Die Versuche von IK1UWL mit den Echos seiner eigenen Station (4 × 14 Elemente auf 121 m über dem Meer, ligurische Küste) zeigen, dass die Dinge in der Praxis komplizierter sind [3]:",
                "• Maxima und Nullstellen sind zahlreich und dicht beieinander, bei Bruchteilen von Grad, die ein Simulator mit 1°-Schritten wie EZNEC nicht sieht: Mit der Antenne hoch über dem Meer folgen sie etwa alle 3 Minuten aufeinander (3 JT65-Perioden) und verursachen bei niedriger Elevation starkes QSB, das nicht von der Ionosphäre abhängt;",
                "• der gemessene Gewinn lag bei etwa 3 dB, nicht bei den theoretischen 6 dB: In einer Gruppe stehen die oberen und unteren Yagis auf verschiedenen Höhen (4,5 m), ihre Reflexionen sind nicht in Phase und es trägt jeweils nur ein Paar bei;",
                "• unter 2° Elevation gibt es ein Gewinnloch, und das Maximum liegt bei etwa 5°; hebt man die Antenne an, nimmt der Bodeneffekt ab und wird jenseits der Breite der Keule (etwa 12° für seine Gruppe) vernachlässigbar;",
                "• die Refraktion zählt: Der Mond ging bei −0,51° auf, unter dem optischen Horizont von −0,35°; bei 200 MHz beträgt der Refraktionsfehler in trockener Luft bei 0° Elevation −0,49°.",
                "IK3XTV weist darauf hin, dass der Bodeneffekt theoretisch 6 dB erreicht, sodass eine einzelne Yagi fast wie eine Gruppe aus 4 arbeitet; er hängt aber stark vom Gelände um die Antenne ab: In der Stadt ist er geringer, auf freiem Land besser und in Meeresnähe noch größer. Man nutzt ihn bei Mondaufgang und Monduntergang, zwischen etwa 1° und 18 – 20° Elevation [4].",
                "> Deshalb ist der Bodengewinn im EME-Budget als BETA gekennzeichnet: Der berechnete Wert (höchstens +6 dB) ist eine theoretische Grenze. Mit Antennen hoch über dem Meer oder Gruppen aus mehreren Yagis sollte man etwa die Hälfte davon und ausgeprägtes QSB bei niedriger Elevation erwarten [3].",
                "[1] WSJT-X User Guide, K1JT and the WSJT Development Group, § 7.1 (FT4 = FT8 + 3,5 dB).",
                "[2] J. Taylor K1JT, B. Somerville G4WJS, S. Franke K9AN, N. Palermo IV3NWV, “Quick-Start Guide to Q65”, 3. April 2021 (WSJT-X 2.4.0), zur Verfügung gestellt von IC8TEM.",
                "[3] Giorgio Marchi IK1UWL, “Considerazioni sull'effetto suolo (Ground Gain)”, 21. EME-Meeting, Präsentation zur Verfügung gestellt von IC8TEM.",
                "[4] Flavio Egano IK3XTV, “EME (earth-moon-earth) con una singola Yagi in 144 MHz”, Dokument vom 12. November 2010, zur Verfügung gestellt von IC8TEM.",
                "[5] J. Taylor K1JT, Vortrag über JT65 auf der EME-Konferenz 2006 (K1JT_eme2006.pdf): Tabelle der minimalen S/N-Werte in 2500 Hz.",
                "> Das Stationsschema rechts im Reiter leitet die Verluste aus den gewählten Kabeln ab: beim Senden Kabel PA–Relais + Relais + Antennenkabel, beim Empfang Antennenkabel + Relais vor dem Vorverstärker und Speiseleitung danach. Die Kabeldämpfungen stammen aus der Datenbank des Reiters COAXIAL CABLES (§ 3.8)."
            };
            d["de"]["S47"] = new string[] {
                "## Der Vorverstärker und die Rauschzahl des Funkgeräts {nuovo}",
                "Bei EME liegt das an der Antenne ankommende Signal nur knapp über dem Rauschen (etwa −149 dBm im Beispiel Tokio – Kapstadt). Der Vorverstärker hat zwei verschiedene Aufgaben: **das Signal zurückzugewinnen**, das in den Kabeln zur Station verloren geht, und vor allem **die Rauschzahl des Funkgeräts zu überdecken**, die bei handelsüblichen VHF/UHF-Transceivern von etwa 3 – 5 dB mit eingeschaltetem internem Vorverstärker bis zu 15 – 16 dB und mehr mit ausgeschaltetem Vorverstärker reicht.",
                "Der Grund liegt in der Friis-Formel: Jede Stufe geht in das Gesamtrauschen geteilt durch die Verstärkung aller vorhergehenden Stufen ein. Die erste Stufe entscheidet fast alles.",
                "= F_{tot} = F_{LNA} + \\frac{F_{cable} − 1}{G_{LNA}} + \\frac{F_{radio} − 1}{G_{LNA} · G_{cable}} \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "~. F und G in linearen Werten (§F = 10^{NF/10}§); für ein Kabel mit der Dämpfung L in dB: §F_{cable} = 10^{L/10}§ und §G_{cable} = 10^{−L/10}§.",
                "@colonne 55",
                "#### Gemessene Rauschzahl einiger Funkgeräte",
                "|h| Funkgerät | >MHz | Vorverstärker | >NF (dB) | Quelle",
                "| Icom IC-9700 | 144 | aus / ein | 16 / 3 | [1]",
                "| Icom IC-9700 | 432 | aus / ein | 15 / 4 | [1]",
                "| Yaesu FT-991 | 50 | IPO / AMP1 / AMP2 | 29 / 17 / 8 | [2]",
                "| Yaesu FT-991 | 144 · 432 | – | 5 · 4 | [2]",
                "| Icom IC-275E | 144 | – | 5,6 | [3]",
                "| Icom IC-9100 | 144 · 432 | nicht angegeben | ≈ 5 · ≈ 5 | [5]{r:*}",
                "| Icom IC-821H | 144 | – | 3,4 | [3]",
                "| Icom IC-910H | 144 | – | 3,7 | [3]",
                "| Icom IC-7000 | 144 | – | 5,6 | [3]",
                "| Kenwood TS-790E | 144 | – | 4,5 | [3]",
                "| Kenwood TS-2000 | 144 | ein | 6,2 | [3]",
                "| Yaesu FT-847 | 144 | ein / aus | 5,1 / 6,7 | [3]",
                "| Yaesu FT-817 | 144 | – | 5,4 | [3]",
                "| Yaesu FT-857D | 144 | – | 6,1 | [3]",
                "| Icom IC-746PRO | 50 | aus / P1 / P2 | 19 / 9 / 6 | [14]",
                "| Icom IC-746PRO | 144 | aus / ein | 14 / 5,2 | [14]",
                "| Yaesu FT-897 | 50 | ein / IPO | 3,6 / 8,7 | [15]",
                "| Yaesu FT-897 | 144 · 432 | immer ein | 5,9 · 7,7 | [15]",
                "~ [1] [2] Messungen von VA7OJ mit kalibrierter Rauschquelle; [3] Messungen von DF9IC mit der Y-Faktor-Methode, Genauigkeit ±0,5 dB, nur 144 MHz, aus dem Jahr 2005. Mit eingeschaltetem internem Vorverstärker geht das IC-9700 bei 144 MHz bereits ab −9 bis −27 dBm in die Sättigung [1]. * Wert zu überprüfen: vorläufiger Test an einem Vorserienmuster, Autor nicht angegeben. [14] NF aus dem Grundrauschen (MDS), gemessen in 500 Hz, abgeleitet: NF = MDS + 174 − 27 dB; mit eingeschaltetem Vorverstärker sinkt bei 144 MHz der Blocking-Dynamikbereich bei 5 kHz von 99,9 auf 88,4 dB. [15] NF aus der SSB-Empfindlichkeit für 10 dB (S+N)/N mit dem 2450-Hz-Filter abgeleitet: NF = S − 9,5 + 174 − 10·log B; auf 144 und 432 MHz ist der Vorverstärker immer eingeschleift. Für [14] und [15] ist die Genauigkeit ein Richtwert, ±1 dB.",
                "@destra",
                "#### Beispiel: 35 m Sivacavi HF 400 (1,6 dB) bei 144 MHz",
                "|h| Konfiguration | >Gesamt-NF | >Te | >Tsys | >Verschlechtert S/N um",
                "| Nur Funkgerät, interner Vorverstärker aus (NF 16) | 17,6 dB | 16 398 K | 16 648 K | %bar:17.6:17.6:r%17,6 dB",
                "| Nur Funkgerät, interner Vorverstärker ein (NF 3) | 4,6 dB | 546 K | 796 K | %bar:4.4:17.6:o%4,4 dB",
                "| LNA an der Antenne 0,5 dB / 20 dB + Funkgerät NF 16 | 2,3 dB | 199 K | 449 K | %bar:1.9:17.6:y%1,9 dB",
                "| **LNA an der Antenne 0,5 dB / 20 dB + Funkgerät NF 3** | **0,6 dB** | 41 K | 291 K | %bar:0:17.6:g%{g:**Referenz**}",
                "~ §T_{sys} = T_{ant}§ 250 K + §T_e§; der Vergleich erfolgt mit demselben Signal an der Antenne.",
                "@fine",
                "Für die beste Konfiguration, mit eingesetzten Werten:",
                "= F_{tot} = 1.1220 + \\frac{1.4454 − 1}{100} + \\frac{1.9953 − 1}{100 · 0.6918} = 1.1220 + 0.0045 + 0.0144 = 1.1409 \\quad ⇒ \\quad NF = 0.57 \\t{ dB}",
                ">! **In der Praxis.** Der Vorverstärker sollte an der Antenne montiert werden, vor der Speiseleitung und direkt nach dem Koaxrelais (das ihn beim Senden mit einem Sequenzer schützen muss). Seine Verstärkung muss hoch genug sein, damit Kabel und Funkgerät vernachlässigbar werden: als Faustregel mindestens 10 dB mehr als die Summe aus Kabeldämpfung und Rauschzahl des Funkgeräts (im Beispiel 1,6 + 16 ≈ 18 dB → mit 20 dB fällt das Funkgerät noch mit 1,7 dB ins Gewicht; mit eingeschaltetem internem Vorverstärker nur mit 0,05 dB). Zu viel Verstärkung verringert jedoch den Dynamikbereich des Funkgeräts: Mit einem guten LNA an der Antenne ist es oft besser, den internen Vorverstärker auszuschalten und einen LNA mit 20 – 26 dB zu wählen. Im EME-Budget werden diese Entscheidungen im Schema der Empfangsanlage getroffen, und der Reiter DEBUG FORMULE zeigt die Berechnung Schritt für Schritt.",
                "##+ Der Transverter (optional)",
                "Mit einem Transverter arbeitet das Funkgerät auf einer Zwischenfrequenz (meist 28 MHz für 144 MHz), und der Transverter wird zur für das Rauschen maßgeblichen Stufe: Er geht nach der Speiseleitung in die Friis-Formel ein, und das nachfolgende Funkgerät fällt umso weniger ins Gewicht, je mehr der Transverter verstärkt.",
                "= F_{comb} = F_{XV} + \\frac{F_{radio} − 1}{G_{XV}} \\quad \\t{e.g. } F_{comb} = 1.2589 + \\frac{10 − 1}{50.12} = 1.4385 ⇒ NF = 1.58 \\t{ dB}",
                "~ Beispiel: Transverter mit NF 1,0 dB und Verstärkung 17 dB (Mindestwerte des DEMI L144-28) vor einem KW-Funkgerät mit NF 10 dB.",
                "@colonne 56",
                "#### Diagramm: NF der Kombination in Abhängigkeit von Funkgerät und Transverterverstärkung",
                "@abaco Kurven berechnet mit (3.7.3) für einen Transverter mit NF 1,0 dB. Je mehr der Transverter verstärkt, desto weniger fällt das Funkgerät ins Gewicht: Mit 25 dB Verstärkung bringt ein Funkgerät mit 20 dB NF die Gesamtrauschzahl auf 2,0 dB; mit 10 dB Verstärkung bringt dasselbe Funkgerät sie auf 10,5 dB.",
                "@destra",
                "#### Transverter für 144 MHz (ZF 28 MHz)",
                "|h| Hersteller · Modell | >NF | >RX-Verst. | >TX | Quelle",
                "| DEMI L144-28 | < 1,0 dB | ≥ 17 dB | 25 / 50 W | [6]",
                "|+ **Kuhne (DB6NT) MKU 144 G2** (Modul) | 0,9 dB | 25 dB | 0,1 W¹ | [13]",
                "| Kuhne (DB6NT) TR 144 H +40 | 0,9 – 1,2 dB | 25 dB | 2 – 20 W | [7]",
                "| Kuhne (DB6NT) TR-144 Pro | {r:k. A.} | {r:k. A.} | 25 W | [8]",
                "| Q5 Signal L144-28M | < 1,0 dB | ≥ 20 dB | 25 / 75 / 150 W | [9]",
                "| HA1YA ME2T-PRO-II / ME2HT-PRO-II | 1,0 dB | ≤ 25 dB (einstellbar) | 30 / 50 W | [10]",
                "| SSB-Electronic LT2S Mk II | {r:k. A.} | {r:k. A.} | – | [11]",
                "~ Herstellerangaben. MKU 144 G2: erste Stufe mit NF 0,5 dB, Ausgangs-IP3 im Empfang +23 dBm, ZF-Eingang 2 – 50 mW oder 60 – 2000 µW; ¹ 100-mW-Treiber, zu ergänzen durch einen Kuhne-Verstärker mit 60 oder 120 W. TR 144 H +40: enthält das Modul MKU 144 G2, daher die Verstärkung von 25 dB (Information von IC8TEM). Mit 25 dB Verstärkung beträgt die Gesamtrauschzahl vor einem Funkgerät mit NF 10 dB 0,99 dB, mit NF 20 dB 1,88 dB [13]. Das Kuhne-Handbuch nennt in der Tabelle 1,2 dB und im Text 0,9 dB; mit dem Vorverstärker Kuhne MKU LNA 144 A sinkt die Gesamtrauschzahl auf 0,3 dB [7]. Q5 Signal L144-28M: maximale NF 1,0 dB bei minimaler Konversionsverstärkung 20 dB, RX-ZF-Verstärkung vom Benutzer zur Kalibrierung des S-Meters einstellbar; ZF bis 25 W [9]. HA1YA ME2T-PRO-II: Gesamt-NF 1 dB (erste Stufe PGA103+ mit NF 0,7 dB), RX-Verstärkung einstellbar bis 25 dB, OIP3 typisch +35 dBm, IIP3 typisch +10 dBm, Spiegelfrequenzunterdrückung > 80 dB, ZF-Eingang von −20 bis +37 dBm [10].",
                "#### Gemessene Kombinationen (DF9IC, 144 MHz)",
                "|h| Funkgerät + Transverter | Vorverstärker des Funkgeräts | >NF",
                "| Elecraft K2 + Kuhne TR144H+40 | – | 1,0 dB",
                "| IC-756PRO II + Kuhne TR144H | aus | 1,0 dB",
                "| IC-746 + Kuhne TR144H+40 | aus | 1,2 dB",
                "| FT-1000MP + Javornik (zwei Geräte) | aus | 0,9 · 1,4 dB",
                "| FT-1000 Mark V + Kuhne TR144H, ZF 14 MHz | aus | 1,6 dB",
                "| FT-1000 Mark V + Kuhne TR144H, ZF 28 MHz | aus / ein | 6,0 / 1,7 dB",
                "| TS-870 + Javornik | aus | 1,9 dB",
                "| Elecraft K2 + XV144 | ein | 6,0 dB",
                "~ Quelle [3]. Der Fall FT-1000 Mark V bei 28 MHz zeigt das Diagramm in der Praxis: Mit ausgeschaltetem Vorverstärker fällt das Funkgerät stark ins Gewicht (6,0 dB), mit eingeschaltetem Vorverstärker sinkt der Wert auf 1,7 dB.",
                "@fine",
                "##+ EME-Stationen mit FT-1000MP und Transverter",
                "Zwei dokumentierte Beispiele für den Einsatz des FT-1000MP für EME auf 144 MHz mit Transverter: die Messungen von DF9IC [3] an FT-1000MP + Javornik-Transverter (NF 0,9 – 1,4 dB mit ausgeschaltetem Vorverstärker des Funkgeräts) und die EME-Station von **W3SZ** [12] (4 × M2 2MXP32, Vorverstärker von LNA Technology an der Antenne für jede Polarisation, LMR-600 und Andrew-Hardline), die beim Senden einen **FT-1000MP Mark V** mit einem Transverter **SSB-Electronic LT2S Mk II** (ZF 28 MHz) und eine Endstufe mit 2 × GU-74B verwendet, beim Empfang dagegen die WSE-Hardware und die Software Linrad von SM5BSZ.",
                "> Im EME-Budget ist der Transverter ein Kästchen des Stationsschemas: Er wird mit seinem Kontrollkästchen aktiviert, man wählt das Modell aus der Liste (oder „custom“), und das Programm übernimmt Rauschzahl und Verstärkung; ausgeschaltet geht er nicht in die Berechnung ein. Das Diagramm oben hilft bei der Entscheidung, ob der Vorverstärker des Funkgeräts eingeschaltet werden soll.",
                ">! ✉ **Kennen Sie einen weiteren Transverter oder haben Sie selbst einen gebaut?** Wenn Sie weitere Transverter oder Ihren eigenen Transverter bekannt machen möchten, schreiben Sie eine E-Mail an den Autor: ccerrotta@gmail.com oder ic8tem@gmail.com. Alle Kontaktdaten stehen im Reiter **AUTHOR CONTACTS AND ACKNOWLEDGEMENTS**.",
                "##+ Der TX/RX-Sequenzer",
                "Mit einer Endstufe (PA) und einem Vorverstärker an der Antenne (PRE) geht die PTT des Computers nicht zum Funkgerät, sondern zu einem **Sequenzer**, der die Relais und danach die PA und das Funkgerät in der richtigen Reihenfolge schaltet [16]. Der übliche Aufbau hat zwei Speiseleitungen: Die Empfangsleitung darf einige dB verlieren, weil sie hinter einem Vorverstärker mit 15 – 20 dB liegt, während die Sendeleitung so wenig wie möglich verlieren darf (3 dB beim Senden halbieren die abgestrahlte Leistung). In Ruhestellung halten die Relais den PRE von der Antenne getrennt: ein zusätzlicher Schutz gegen Blitzentladungen [16].",
                "|h| ^Schritt | Von RX auf TX | Von TX auf RX",
                "| ^1 | die Relais schalten kalt um: Funkgerät → PA-Eingang, Antenne → PA-Ausgang, PRE getrennt | das Funkgerät hört auf zu senden",
                "| ^2 | die PA wird eingeschaltet | die PA wird ausgeschaltet",
                "| ^3 | das Funkgerät geht auf Senden | die Relais schalten ohne anliegende Leistung auf Empfang zurück",
                "~ Zwischen zwei Schritten braucht man mindestens die Umschaltzeit der Relais (15 – 30 ms) plus ihr Prellen: IK1UWL empfiehlt 100 – 200 ms, auch für die PA, wenn sie interne Relais hat [16].",
                "Zum Tasten des Senders ist PTT besser als VOX: VOX kann durch ein Geräusch ausgelöst werden und nutzt nicht die Verzögerung von etwa 0,5 s, mit der JT65 nach der PTT zu modulieren beginnt, sodass der Vorverstärker nur durch das schnelle Relais der Endstufe geschützt ist; mit PTT schaltet diese Verzögerung die Endstufe vor der Modulation um, und man kann den Sequenzer hinzufügen [17].",
                ">! **Vorsicht mit dem Vorverstärker.** Das T/R-Relais muss den offenen Anschluss sehr gut isolieren: Bei 50 dB Isolation und 500 W an der Antenne gelangen 5 mW an den Eingang des PRE. Anzustreben sind mindestens 60 dB; Vorsichtige fügen ein zweites Relais hinzu, das den PRE beim Senden auf eine 50-Ω-Last schaltet. Die PTT-Taste des Mikrofons wird deaktiviert: Ab dann wird nur noch über den Sequenzer gesendet (für SSB ein Fußschalter an der PTT des Sequenzers, entkoppelt von der des PCs) [16].",
                "[1] Adam Farson VA7OJ/AB4OJ, “Icom IC-9700 Test Report”, Ausgabe 5, 19. März 2021 (Erstausgabe 19. Juni 2019), Tabellen 1 und 5 – https://www.qsl.net/ab4oj/icom/ic9700/9700notes.pdf",
                "[2] Adam M. Farson VA7OJ/AB4OJ, “Yaesu FT-991 Test Report”, 25. Juli 2015, Tabelle 1 – https://www.qsl.net/ab4oj/test/docs/ft991notes.pdf",
                "[3] DF9IC mit DARC OV Durlach A35, “Test of the Large Signal Behaviour of some 144 MHz Radios”, Tests ab 27. Februar 2005 – https://www.df9ic.de/tech/trxtest/trxtest.html",
                "[4] H. T. Friis, “Noise Figures of Radio Receivers”, Proceedings of the IRE, Bd. 32 (1944).",
                "[5] Vorläufiger Test “ICOM IC-9100 review” an einem von Icom UK geliehenen Vorserienmuster (Autor und Datum nicht angegeben) – https://manualmachine.com/icom/ic9100/26837637-review",
                "[6] Down East Microwave, “L144-28 Rev B” – Benutzerhandbuch (Spezifikationen: NF < 1,0 dB bei Konversionsverstärkung ≥ 17 dB) – https://manualmachine.com/demi/l14428revb/26842141-user-guide",
                "[7] Kuhne electronic, “TR 144 H +40” – Benutzerhandbuch – https://manuals.online/kuhne-electronic/transceiver/tr-144-h-40/user-manual/191pa",
                "[8] RigPix, “Kuhne TR-144 Pro” – https://rigpix.com/transverters/kuhne_tr144pro.htm",
                "[9] Q5 Signal, “VHF/UHF Transverters – L144-28M REV 2”, Handbuch (8 Seiten), Januar 2023, zur Verfügung gestellt von IC8TEM – http://q5signal.com/image/catalog/L144-28Mr2.pdf",
                "[10] HA1YA (Mechanics & Electronics), “ME2T-PRO-II & ME2HT-PRO-II 144MHz Transverter”, 25.09.2023, zur Verfügung gestellt von IC8TEM – http://www.ha1ya.hu/pdf/me2tpro2transverter.pdf",
                "[11] SSB-Electronic LT2S Mk II – zitiert in [12]",
                "[12] Roger Rehr W3SZ, Beschreibung der EME-Station – https://w3sz.com/EMEFrame1Source1.htm",
                "[13] Kuhne electronic GmbH, “MKU 144 G2 – Transverter module, 144 … 146 MHz, 28 … 30 MHz IF”, Datenblatt (2 Seiten), zur Verfügung gestellt von IC8TEM",
                "[14] ARRL Laboratory, “Icom IC-746PRO”, QST Product Review, Mai 2002 – https://www.radiomanual.info/schemi/ICOM_HF/IC-746Pro_review_ARRL_2002.pdf",
                "[15] Peter Hart G3SJX, “The Yaesu FT-897 HF/VHF/UHF Transceiver”, RadCom (RSGB), April 2003, S. 18–20 – http://www.radiomanual.info/schemi/YAESU_HF/FT-897_review2_2003.pdf",
                "[16] Giorgio Marchi IK1UWL, “EME (Earth-Moon-Earth) – Guida operativa”, Januar 2012, § 4 “Sequenziamento relè, PA e PRE”, bereitgestellt von IC8TEM – http://www.qsl.net/ik3xtv",
                "[17] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, Präsentation, Juli 2015, bereitgestellt von IC8TEM."
            };
            d["de"]["S48"] = new string[] {
                "## Koaxialkabel und Verluste",
                "Der Reiter **COAXIAL CABLES** sammelt die Dämpfung der bei Funkamateuren gebräuchlichsten 50-Ω-Kabel in dB pro 100 m bei 20 °C auf den fünf YAEC-Bändern. Die Datenblätter der Hersteller geben Werte bei anderen Frequenzen an; YAEC hat sie mit dem Potenzgesetz auf die Bänder umgerechnet, einer Geraden im doppelt logarithmischen Diagramm zwischen den beiden nächstgelegenen Frequenzen des Datenblatts:",
                "= α(f) = α_1 · \\p{\\frac{f}{f_1}}^{n} \\quad n = \\frac{log \\p{α_2 / α_1}}{log \\p{f_2 / f_1}} \\quad L = α(f) · \\frac{ℓ}{100}",
                "~ α in dB/100 m, ℓ Kabellänge in Metern. Eine einfache Zahl ist der Datenblattwert; ≈ kennzeichnet einen interpolierten Wert und e einen über die letzte Frequenz des Datenblatts hinaus extrapolierten.",
                "Kabel desselben Typs mit gleichem Durchmesser innerhalb ±0,2 mm und einer Dämpfung innerhalb 0,2 dB/100 m auf allen Bändern sind in einer Zeile (≡) mit dem Mittelwert zusammengefasst; gleichwertige Bezeichnungen werden mit „also:“ angezeigt (zum Beispiel LMR-400 = HF400, CNT-400, 50-7 low loss; LMR-600 = CNT-600). Die chinesischen Bezeichnungen 50-3, 50-5, 50-7, 50-9, 50-12 geben den Durchmesser des Dielektrikums in Millimetern an.",
                "> Eigene Kabel können mit ihren fünf Dämpfungswerten hinzugefügt werden: Sie werden in data\\cavi_personali.txt gespeichert und erscheinen auch in den Auswahllisten des Stationsschemas im EME-Budget. Der Tooltip jeder Tabellenzeile nennt die Quelle des betreffenden Kabels.",
                "[1] Die Quellen der einzelnen Kabel: Datenblätter von Times Microwave (LMR), RFS (CELLFLEX LCF/SCF), CommScope Andrew (HELIAX LDF/FSJ), Siva Cavi (HF 240/287/400), SSB-Electronic (Aircell, Ecoflex, Aircom Plus), Messi & Paoloni (Hyperflex, Ultraflex, über WiMo), Symair, SYV50-7 (szansy.com), Belden (H1000), Prospecta (RT5020, XT2400), QAXIAL (LLF195), Caledonian Cables, Katalog MIL-C-17F (RG-142, RG-393), R.F. elettronica aus Senago (RG-115), die Tabellen von DD1US und EA5IP (H100) und die Tabelle von SV1BSX für RG-58, RG-213, H-155 und H-2000 (Werte zu überprüfen)."
            };
            d["de"]["S410"] = new string[] {
                "## Doppler, Kompensation und CFOM",
                "Der Mond nähert sich den beiden Stationen und entfernt sich von ihnen, bedingt durch die Erdrotation und seine eigene Bahnbewegung: Die Entfernung R ändert sich um einige hundert Meter pro Sekunde, und das Signal kommt frequenzverschoben zurück. Die Verschiebung ist bei Mondaufgang und Monduntergang am größten, geht beim Durchgang durch Süden (oder Norden) durch null und ist proportional zur Frequenz. YAEC berechnet sie jede Sekunde auf dem Hauptbildschirm in der Karte **Echo and frequencies (CFOM)**.",
                "### Wie groß der Doppler ist",
                "Beim Echo der eigenen Station wird der Weg zweimal durchlaufen (hin und zurück):",
                "= f_{D,echo} = − \\frac{2f}{c} · \\frac{dR}{dt} \\quad \\t{e.g. } − \\frac{2 · 144.120 · 10^6}{299 792} · 0.222 = −213 \\t{ Hz}",
                "mit f der Frequenz in Hz, c = 299 792 km/s und dR/dt der Radialgeschwindigkeit des Mondes in km/s (positiv, wenn er sich entfernt). Beim Signal der DX-Station zählen beide Teilstrecken, ihre und Ihre:",
                "= f_{D,DX} = − \\frac{f}{c} · \\p{\\frac{dR_{me}}{dt} + \\frac{dR_{DX}}{dt}} \\quad \\t{e.g. } −480.7 · \\p{0.222 − 0.339} = +56 \\t{ Hz}",
                "~ Beispiel: Tokio PM95 und Kapstadt JF96, 06.11.2026 01:55 UTC, 144,120 MHz; dR/dt = +0,222 km/s in Tokio und −0,339 km/s in Kapstadt (YAEC-Werte).",
                "@colonne 62",
                "|h| Band | >Maximaler Echo-Doppler | >Kompensation",
                "| 50 MHz | ≈ ±120 Hz | nicht nötig",
                "| 70 MHz | ≈ ±165 Hz | nicht nötig",
                "| 144 MHz | bis ≈ 340 Hz [1] | empfohlen",
                "| 222 MHz | ≈ ±525 Hz | nötig",
                "| 432 MHz | bis ≈ 1000 Hz [1] | nötig",
                "~ Werte für 144 und 432 MHz aus [1]; 50, 70 und 222 MHz proportional zur Frequenz abgeleitet (≈ = abgeleitet).",
                "@destra",
                "> Auf 50 und 144 MHz bleibt der Doppler fast immer innerhalb des Wasserfalls des Digitalprogramms, und der Dekoder findet ihn selbst; auf 432 MHz kann er das Signal aus dem Durchlassbereich schieben, und während einer 60-s-Periode ändert er sich um einige Hertz, genug, um in den langsamen Betriebsarten wie eine Drift auszusehen [2].",
                "@fine",
                "### Kompensieren: wer korrigiert was",
                "Den Doppler zu kompensieren bedeutet, die Sendefrequenz, die Empfangsfrequenz oder beide so zu verschieben, dass sich die Signale auf der vereinbarten Frequenz (dem *Sked*) treffen. Jede Station korrigiert ihren eigenen Doppler und, beim Verkehr mit einer DX-Station, auch den der DX-Station [1]:",
                "|h| Situation | Senden | Empfangen",
                "| CQ-Ruf und Abhören des eigenen Echos | auf der Sked-Frequenz | Sked + Echo-Doppler (3.10.1)",
                "| QSO mit bekannter DX-Station (voller Doppler zur DX-Station) | so korrigiert, dass die DX-Station Sie auf dem Sked empfängt | Sked + Doppler DX → ich (3.10.2)",
                "| CFOM, konstante Frequenz auf dem Mond | Sked − halber eigener Doppler | Sked + halber eigener Doppler",
                "### CFOM – Constant Frequency On Moon",
                "Bei CFOM verhalten sich alle Stationen so, als wäre ein virtueller Sender auf dem Mond auf das Sked abgestimmt: Jede korrigiert nur die Hälfte ihres **eigenen** Dopplers beim Senden und die Hälfte beim Empfang, ohne den Locator der anderen Station kennen zu müssen [2]:",
                "= f_{TX} = f_{sked} − \\frac{f_{D,echo}}{2} \\quad f_{RX} = f_{sked} + \\frac{f_{D,echo}}{2}",
                "|h| Beispiel (Tokio, Echo-Doppler −213 Hz) | >Frequenz",
                "| Sked | 144,120000 MHz",
                "| Senden auf (Sked + 106,5 Hz) | {r:**144,120107 MHz**}",
                "| Empfangen auf (Sked − 106,5 Hz) | {g:**144,119894 MHz**}",
                "Der Vorteil ist, dass mehrere Stationen und jeder, der nur zuhört, ein QSO auf derselben Frequenz verfolgen können, ohne den Doppler für jede einzelne neu zu berechnen. YAEC zeigt diese beiden Frequenzen auf dem Hauptbildschirm an.",
                "### Die CAT-Steuerung des Funkgeräts",
                "Der Doppler ändert sich ständig, daher muss die Kompensation in jeder Periode aktualisiert werden. Am einfachsten überlässt man sie dem Digitalprogramm (zum Beispiel dem Fenster *Astronomical Data* von WSJT-X), das über die **CAT**-Schnittstelle des Funkgeräts die Sende- und Empfangs-VFOs einstellt und das Funkgerät auf der richtigen Frequenz hält [1] [2]. Ohne CAT kann man Split (ein VFO zum Senden und einer zum Empfangen) oder RIT verwenden und in jeder Periode von Hand nachstellen: Auf 50 und 144 MHz ist das machbar, auf 432 MHz wird es umständlich [1].",
                "> Achtung: Für CFOM muss das Funkgerät den Frequenzwechsel über CAT **auch während des Sendens** annehmen. Manche Geräte tun das nicht (zum Beispiel das in [2] erwähnte FT-897): In diesem Fall kann man trotzdem in CFOM empfangen, während das Senden auf einer festen Frequenz bleibt. Mit einem Transverter (§ 3.7) stellt die CAT-Steuerung das Funkgerät auf der Zwischenfrequenz ein: Stellen Sie im Programm die Transverter-Ablage ein, damit die angezeigte Frequenz die tatsächliche ist.",
                "[1] Bob Atkins KA1GT, “Doppler 101 for 1296 MHz EME (…and other bands)” (aus dem Artikel werden nur die Daten bis 432 MHz verwendet) – https://bobatkins.com/radio/EME_doppler_101.html",
                "[2] Bob Atkins KA1GT, “CFOM – Constant Frequency On Moon Doppler Mode” – https://bobatkins.com/radio/CFOM.html"
            };
            d["de"]["S411"] = new string[] {
                "## Ausrichtung: Genauigkeit, Encoder und Stellantriebe",
                "YAEC berechnet Azimut und Elevation des Mondes auf ein Hundertstel Grad genau, aber das Signal kommt nur an, wenn die Antenne ihm wirklich folgt. Je schmaler die Keule, desto mehr zählt die mechanische Genauigkeit der Ausrichtung: Auf den YAEC-Bändern (50 – 432 MHz) genügt ein guter Rotor, während die Parabolspiegel der höheren Bänder ein richtiges Stellsystem brauchen.",
                "### Wie viel eine schlechte Ausrichtung kostet",
                "Bei einem Ausrichtungsfehler Δ und einem Halbwertsöffnungswinkel θ (von YAEC mit §θ ≈ \\sqrt{41253/G}§ geschätzt) wird der Verlust mit der Formel der gaußschen Keule angenähert:",
                "= L_{point} ≈ 12 · \\p{\\frac{Δ}{θ}}^2 \\t{ dB} \\quad \\t{e.g. } 12 · \\p{\\frac{3.6}{14.4}}^2 = 0.75 \\t{ dB}",
                "~ Beispiel: 4 Yagis mit 17 dBi auf 144 MHz, Gesamtgewinn 23 dBi, θ ≈ 14,4°; ein Fehler von einem Viertel der Keule (3,6°) kostet etwa 0,75 dB. Bei EME zahlt man den Verlust zweimal, beim Senden und beim Empfang. Näherungsformel, gültig für Fehler, die klein gegenüber der Keule sind.",
                "### Auflösung des Encoders",
                "Die Antennenposition wird von einem Encoder gelesen (oder von einem digital gewandelten Potentiometer): Mit n Bit wird die volle Umdrehung in §2^n§ Schritte geteilt, und der kleinste Schritt ist",
                "= Δ = \\frac{360°}{2^n} \\quad \\t{e.g. } n = 10: \\frac{360°}{1024} = 0.35°",
                "|h| ^Encoder | >Schritte pro Umdrehung | >Schritt | >Verlust mit der 4-Yagi-Gruppe (θ 14,4°, Fehler 1 Schritt) | Geeignet für",
                "| 8 Bit | 256 | 1,406° | 0,114 dB | Yagi-Gruppen auf 50 und 144 MHz",
                "| 10 Bit | 1.024 | 0,352° | 0,007 dB | 144 MHz mit Reserve, 432 MHz mit kleinen Gruppen",
                "| 12 Bit | 4.096 | 0,088° | < 0,01 dB | 432 MHz mit großen Gruppen",
                "| 14 Bit | 16.384 | 0,022° | < 0,01 dB | Parabolspiegel für 10 und 24 GHz [1]",
                "| 16 Bit | 65.536 | 0,005° | < 0,01 dB | darüber: Grenze durch die Mechanik, nicht durch den Encoder",
                "~ Schritt und Verlust berechnet mit (3.11.2) und (3.11.1). Eine praktische Regel ist, den Fehler unter einem Zehntel der Keule zu halten: Die 4-Yagi-Gruppe auf 144 MHz kommt mit 8 Bit aus, ein 3-m-Spiegel bei 10 GHz (Keule ≈ 0,7°) braucht mindestens 13 – 14 Bit.",
                "> Die Anzahl der Bits sagt nur, wie fein die Position *gelesen* wird: Die tatsächliche Genauigkeit hängt auch vom mechanischen Spiel, der Durchbiegung der Halterung, dem Wind und der Kalibrierung von Nord und Horizont ab.",
                "### Yagi-Gruppen: Stellantriebe und Umlenkrollen",
                "Bei Yagi-Gruppen (Kombinationen aus 2, 4 oder mehr Antennen) ist die Elevationslast groß und unausgeglichen. Auf dem Markt gibt es Linearantriebe mit Schneckengetriebemotor: Bei diesen Lösungen regelt die Spindel nur die Bewegung, während die mechanische Aufnahme der Last Umlenkrollen übertragen wird. Das Schneckengetriebe hat den Vorteil, dass es sich unter Last nicht zurückdreht, sodass die Gruppe auch bei ausgeschaltetem Motor stehen bleibt.",
                "### Oberhalb 432 MHz: Parabolspiegel",
                "Ab 902 MHz werden meist Parabolspiegel verwendet, und das Werkzeug [1] ist für Frequenzen ab 1 GHz ausgelegt. Bei großen Durchmessern wird die Keule wenige Zehntel Grad schmal, und es besteht die Gefahr, den Mond nicht genau zu treffen: Mehr als Motoren braucht die Station richtige mechanische Stellantriebe in Azimut und Elevation, wobei die Ausrichtgenauigkeit weitgehend von der Bitauflösung der Steuerung abhängt. Das **EME Link Budget & Analysis Tool** von OE2IGL und DF3GJ [1] nennt ±0,035° für ein gutes Nachführsystem und ±0,1° für ein normales und berechnet den Ausrichtungsverlust zusammen mit allen anderen Termen der Verbindung.",
                ">+ YAEC endet bei 432 MHz. Für die höheren Bänder empfehlen wir das Werkzeug von OE2IGL und DF3GJ [1]: Es berechnet das EME-Budget von 1 bis 300 GHz mit den Spiegelparametern (Durchmesser, f/D, Erreger, Oberflächenrauheit, Wirkungsgrade), Ausrichtung, Libration, Sonnen- und Mondrauschen und atmosphärischer Dämpfung.",
                "[1] Gerald Ihninger OE2IGL und Joachim Köppen DF3GJ, “EME Link Budget & Analysis Tool (1-300 GHz)” – https://wettersat.bplaced.net/EME/EME.html"
            };
            d["de"]["S412"] = new string[] {
                "## Digitale Betriebsarten für EME: Q65 und JT65",
                "Das EME-Budget (§ 3.6) zeigt das geschätzte S/N neben der typischen Schwelle der gewählten digitalen Betriebsart. Dieser Abschnitt erklärt, woher die Schwellen von **Q65** stammen, wie das Signal aufgebaut ist und warum Q65 heute JT65 für EME auf den YAEC-Bändern weitgehend abgelöst hat. Die Daten stammen aus drei Dokumenten: der Kurzanleitung der Autoren von Q65 [1], dem Vergleich JT65A – Q65-60A von K1JT [2] und der Untersuchung des Kodierverfahrens durch G4JNT [3].",
                "### Was Q65 ist",
                "Q65 wurde mit WSJT-X 2.4.0 von K1JT, G4WJS, K9AN und IV3NWV für minimale QSOs über besonders schwierige Strecken eingeführt; wenn die Doppler-Verbreiterung einige Hertz übersteigt, ist es die empfindlichste der WSJT-X-Betriebsarten, und es eignet sich für Troposcatter, Regenscatter, ionosphärischen Scatter, TEP und EME ab VHF aufwärts [1]. Es verwendet FSK mit **65 Tönen** und geht auf QRA64 von 2016 zurück; gegenüber diesem führt es ein [1]:",
                "• einen neuen fehlerkorrigierenden Q-ären Repeat-Accumulate-Code mit niedriger Rate, vorgeschlagen von Nico Palermo IV3NWV [3] [4];",
                "• Nachrichten und Ablauf identisch mit FST4, FT4, FT8 und MSK144;",
                "• einen im Wasserfall gut sichtbaren Synchronton und eine empfindliche „Sync-Kurve“, wirksam auch bei Meteor-Pings;",
                "• Untermodi mit T/R-Perioden von 15, 30, 60, 120 und 300 s und unterschiedlichen Tonabständen;",
                "• Listendekodierung für Nachrichten, die bereits empfangene Teile enthalten, **ohne Rufzeichendatenbank**;",
                "• Mittelung von Nachrichten, wenn einzelne Aussendungen zu schwach sind, und Mehrfachdekodierung über das gesamte Empfangsband.",
                "### Die Untermodi",
                "Der Name des Untermodus verbindet die T/R-Periode mit einem Buchstaben für den Tonabstand: Q65-60A, Q65-120C und so weiter. Für die A-Untermodi gibt die Tabelle die durch Simulation auf einem Kanal mit additivem weißem gaußschem Rauschen (AWGN) gemessenen Schwellen an, als S/N in 2500 Hz bei 50 % Dekodierwahrscheinlichkeit, ohne und mit maximaler *A-priori*-Information (AP) [1].",
                "|h| >T/R (s) | >Symbol (s) | >Abstand A (Hz) | >Bandbreite A (Hz) | >Aussendung (s) | >S/N (dB) | >S/N max. AP (dB)",
                "| 15 | 0,150 | 6,667 | 433 | 12,8 | −22,2 | −23,7",
                "| 30 | 0,300 | 3,333 | 217 | 25,5 | −24,8 | −26,6",
                "| 60 | 0,600 | 1,667 | 108 | 51,0 | −27,6 | −30,2",
                "| 120 | 1,333 | 0,750 | 49 | 113,3 | −30,8 | −32,5",
                "| 300 | 3,456 | 0,289 | 19 | 293,8 | −33,8 | −37,4",
                "~ Daten aus [1]. Die Untermodi B, C, D und E haben den 2-, 4-, 8- und 16-fachen Tonabstand und die entsprechend vielfache belegte Bandbreite des Untermodus A; nicht alle Kombinationen existieren (zum Beispiel gibt es 15D und 30E nicht) [1].",
                "Die Zahlen der Tabelle folgen aus wenigen Beziehungen, die YAEC mit den Werten in [1] überprüft hat: Der Abstand A ist der Kehrwert der Symboldauer, die Aussendung dauert 85 Symbole und die belegte Bandbreite beträgt 65 Abstände.",
                "= Δf = \\frac{k}{t_s} \\quad k = 1, 2, 4, 8, 16 \\t{ (A … E)} \\quad T_{tx} = 85 · t_s \\quad B_{occ} = 65 · Δf",
                "~ Beispiel Q65-60A: §t_s§ = 0,600 s → Δf = 1,667 Hz, §T_{tx}§ = 51,0 s, §B_{occ}§ = 108 Hz. Beim Übergang von 60 auf 120 s verbessert sich die Schwelle um 3,2 dB, nahe an den 10 · log(113,3 / 51,0) = 3,5 dB, die man von der längeren Aussendung erwartet.",
                "### Empfindlichkeit und Doppler-Verbreiterung",
                "Die Schwellen der Tabelle gelten ohne Verbreiterung des Signals. Bei EME verbreitert der Mond jeden Ton um einige Hertz (Doppler-Verbreiterung oder *Librationsfading*), und die Schwelle verschlechtert sich. Aus dem Diagramm in [1] für Q65-60A ohne AP:",
                "|h| >Doppler-Verbreiterung (Hz) | >S/N bei 50 % (dB) | >Verlust (dB)",
                "| 0 | ≈ −27,4 | –",
                "| 5 | ≈ −25,6 | ≈ 1,8",
                "| 10 | ≈ −24,6 | ≈ 2,8",
                "| 20 | ≈ −23,2 | ≈ 4,2",
                "~ Werte von YAEC aus Abbildung 2 von [1] durch Interpolation zwischen den Punkten abgelesen (≈ = abgeleitet). Die Dekodierung bleibt bis zu einer Verbreiterung von etwa dem Zehnfachen des Tonabstands wirksam, und sogar darüber hinaus [1]: Deshalb wählt man bei größerer Verbreiterung Untermodi mit höherem Buchstaben.",
                "> In YAEC gelten die Referenzschwellen ohne Verbreiterung und ohne AP: Sie dienen zum Vergleichen von Tagen, Bändern und Stationen. Ist das Signal auf Ihrer Strecke stark verbreitert, berücksichtigen Sie den Verlust aus der Tabelle oder stellen Sie die Betriebsart *custom* mit der korrigierten Schwelle ein.",
                "### Die QSO-Nachrichten bei 60 s: Q65-60A, Q65-60B und Q65-60C",
                "In einem minimalen QSO werden die sechs Standardnachrichten von WSJT-X (TX1 … TX6) nicht alle gleich empfangen: Der Decoder kann die bereits bekannten Teile nutzen (Dekodierung *a priori*, AP), und die Menge der bekannten Information wächst im Laufe des QSO [1]. Die Tabelle vergleicht die drei für EME meistverwendeten Untermodi bei derselben Periode von 60 s.",
                "|h| Nachricht | Beispiel | >AP beim Empfang | >Q65-60A | >Q65-60B | >Q65-60C",
                "| TX6 – Anruf | CQ W9XYZ EN37 | >q1 | >−27,6 · AP: k. A. | >−27,6 · AP: k. A. | >−27,6 · AP: k. A.",
                "| TX1 – Antwort mit Locator | W9XYZ K1ABC FN42 | >q2 | >−27,6 · AP: k. A. | >−27,6 · AP: k. A. | >−27,6 · AP: k. A.",
                "| TX2 – Rapport | K1ABC W9XYZ −25 | >q3 | >−27,6 · AP: k. A. | >−27,6 · AP: k. A. | >−27,6 · AP: k. A.",
                "| TX3 – R und Rapport | W9XYZ K1ABC R−26 | >q3 | >−27,6 · AP: k. A. | >−27,6 · AP: k. A. | >−27,6 · AP: k. A.",
                "| TX4 – Bestätigung | K1ABC W9XYZ RRR | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| TX5 – Grüße | W9XYZ K1ABC 73 | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| Tonabstand | – | – | >1,667 Hz | >3,333 Hz | >6,667 Hz",
                "| Belegte Bandbreite | – | – | >108 Hz | >217 Hz | >433 Hz",
                "| Noch dekodierbare Verbreiterung (≈ 10 × Abstand) | – | – | >≈ 17 Hz | >≈ 33 Hz | >≈ 67 Hz",
                "| Mit 5 Hz Doppler-Verbreiterung, ohne AP | – | – | >≈ −25,6 | >geringerer Verlust (k. A.) | >geringerer Verlust (k. A.)",
                "~ S/N in dB bezogen auf 2500 Hz, 50 % Dekodierwahrscheinlichkeit. −27,6 dB ohne AP und −30,2 dB mit maximaler AP sind die Werte von Q65-60A in [1]; für die Untermodi B und C sind sie aus der Theorie abgeleitet: Ohne Verbreiterung hängt die Empfindlichkeit von der Symboldauer (0,600 s) ab, die in den drei Untermodi gleich ist, und nicht vom Abstand. „k. A.“ = nicht verfügbar: [1] nennt nur den maximalen AP-Gewinn (2,6 dB bei 60 s), nicht den der Stufen q1, q2 und q3, der kleiner ist. Kennungen q1 … q4 wie in der Tabelle des § „Empfohlene Einstellungen in WSJT-X“; dekodierbare Verbreiterung und Wert bei 5 Hz aus [1] und aus der Tabelle der Doppler-Verbreiterung oben. K1ABC, W9XYZ und die Locator sind Beispiele.",
                ">! Diese Vergleichstabelle ist aus der Analyse der uns vorliegenden Daten über die Funktionstheorie von Q65 abgeleitet und spiegelt keineswegs wider, was tatsächlich geschieht, wegen des natürlichen und vom Menschen verursachten (anthropogenen) Rauschens, das während des Empfangs live aufgenommen wird.",
                "### Welcher Untermodus für EME",
                "Für die YAEC-Bänder sind die in [1] empfohlenen Untermodi:",
                "|h| Verwendung | Untermodus",
                "| EME auf 50 und 144 MHz | Q65-60A",
                "| EME auf 432 MHz | Q65-60B",
                "| Ionosphärischer Scatter auf 50 MHz | Q65-30A",
                "| Ionosphärischer Scatter mit kleiner Leistung auf 50 MHz | Q65-120E",
                "| TEP auf 50 MHz | Q65-15C, Q65-30C",
                "| Ionosphärischer Scatter auf 144 MHz | Q65-60C",
                "~ Aus [1], nur für die Bänder bis 432 MHz. Die Autoren ermutigen dazu, mit anderen Kombinationen zu experimentieren.",
                "Die 30-s-Periode verdoppelt die QSO-Rate bei relativ starken Signalen, die 120-s-Periode gewinnt etwa 3 dB pro einzelner Aussendung [2].",
                "### Q65 und JT65 im Vergleich",
                "**JT65A** war fast zwanzig Jahre lang die EME-Betriebsart des 6-m-Bands: Mit der *Deep-Search*-Dekodierung erreicht es −28 dB in 2500 Hz (−29 dB mit Nachrichtenmittelung, § 3.6), etwa 15 dB unter dem Pegel, der für das Hören von CW nach Gehör nötig ist, aber nur für Stationen, die in der Datenbank CALL3.TXT mit Rufzeichen und Locatoren aufgeführt sind. In diesen QSOs wird tatsächlich sehr wenig Information übertragen: etwa 14 Bit für ein aus der Datenbank gewähltes Rufzeichen mit Locator, dazu ein Rapport von 1 Bit und eine Bestätigung von 1 Bit [2].",
                "**Q65** sendet immer Nachrichten mit 78 Bit: Auch ein minimales QSO überträgt ein beliebiges Rufzeichen (29 Bit), einen echten numerischen Rapport (7 Bit) und die Bestätigung (1 Bit), ohne Datenbank [2]. K1JT erstellte zehn simulierte Dateien mit Signalen bei −29 dB und 1 Hz Doppler-Verbreiterung, je Datei fünf JT65A- und fünf Q65-60A-Signale, und versuchte sie auf vier Arten zu dekodieren, mit 50 möglichen Dekodierungen je Test [2]:",
                "|h| Test | Betriebsart | Rufzeichen und Locator der DX-Station | Deep Search | >Richtig | >Falsch",
                "| 1 | JT65A | nicht bekannt | nicht verfügbar | 0 | 0",
                "| 2 | JT65A | nicht bekannt | ja (DX in CALL3.TXT) | 28 | 1",
                "| 3 | Q65-60A | nicht bekannt | – | 24 | 0",
                "| 4 | Q65-60A | bekannt (DX Call und DX Grid) | – | 49 | 0",
                "~ Aus [2], Tabelle 1. Einstellungen JT65: Deep, Deep Search, AP, 6 zufällige Löschmuster, Aggressivitätsstufe 9; Q65: Fast, Mittelung ein, automatisches Löschen des Mittelwerts.",
                "Die Schlussfolgerungen des Autors [2]: Bei Antworten auf den eigenen CQ-Ruf hat Q65-60A für **jede** unbekannte rufende Station etwa dieselbe Empfindlichkeit, die JT65A nur für Stationen in der Datenbank hat; für alle anderen ist es **mindestens 3 dB** empfindlicher, und noch mehr bei späteren Nachrichten, wenn beide Rufzeichen bekannt sind. Falschdekodierungen sind so selten, dass sie schwer zu messen sind. Die Nachrichtenmittelung von JT65 funktioniert für eine einzelne, bereits erkannte rufende Station, die von Q65 über das gesamte angezeigte Band. Schließlich verwendet JT65 die Hälfte der gesendeten Energie für die Synchronisation, Q65 ein Viertel.",
                "> Der Wert −25 dB für JT65 im EME-Budget ist der aus der WSJT-X-Anleitung ohne Deep Search (§ 3.6); die −28 dB mit Deep Search gelten nur für Stationen, die in der Datenbank aufgeführt sind, die −29 dB mit Mittelung für jede beliebige Nachricht.",
                ">! **Widerspruch zwischen den Quellen.** Das Vergleichsdokument JT65A – Q65-60A [2] nennt −29 dB für JT65A mit Deep Search; der Vortrag von K1JT auf der Konferenz EME 2006, zitiert in § 3.6, gibt dagegen −28 dB für Deep Search und −29 dB für die Nachrichtenmittelung an. YAEC verwendet die Werte von 2006. Die beiden Quellen beziehen sich auf verschiedene Untermodi: JT65B in den Simulationen von 2006, JT65A in [2].",
                "### Wie Q65 das Signal aufbaut",
                "G4JNT hat aus dem Quellcode von WSJT-X den Weg von der Nachricht zu den gesendeten Tönen rekonstruiert und ihn mit dem WSJT-X-Programm Q65CODE.EXE überprüft [3]. Kurz zusammengefasst:",
                "• **Quellenkodierung.** Wie bei FST4, FT8, FT4 und MSK144 wird die Nachricht zu 71 Datenbits plus 6 Typbits, insgesamt 77. Ein freier Text hat bis zu 13 Zeichen aus einem Alphabet von 42 Symbolen (Leerzeichen, Ziffern, Buchstaben und + - . / ?), und §42^{13}§ ist kleiner als §2^{71}§; der Telemetriemodus überträgt bis zu 18 Hexadezimalziffern [3].",
                "• **Symbole.** Mit einem weiteren Bit werden die 78 Bit in 13 Symbole zu je sechs Bit aufgeteilt, Werte 0 bis 63 [3]: dieselbe Länge wie die 78-Bit-Nachrichten in [2].",
                "• **CRC.** Eine 12-Bit-Prüfsumme (zwei Symbole) mit dem Polynom 1100000001111 und in jedem Symbol umgekehrter Bitreihenfolge zur Kompatibilität mit der Arbeit von IV3NWV dient zum Verwerfen von Falschdekodierungen [3]. Mit dem CRC sind es 15 Symbole.",
                "• **Parität.** Die 50 Prüfsymbole stammen aus einer „Generator“-Matrix 15 × 50, mit Arithmetik im Galois-Feld GF(64): Die Addition ist ein XOR, die Multiplikation erfolgt mit Logarithmus- und Antilogarithmustabellen [3].",
                "• **Code.** Der Code ist ein (65,15)-Code mit Symbolen zu sechs Bit; die beiden CRC-Symbole werden „punktiert“, also nicht gesendet, sodass ein effektiver (63,13)-Code bleibt [1] [3].",
                "• **Synchronisation.** Zu den 63 Symbolen kommen 22 Synchronsymbole, alle auf Ton 0, an festen pseudozufälligen Positionen; gesendet werden 85 Symbole mit 65 Tönen: 0 für die Synchronisation, 1 bis 64 für die Daten [1] [3].",
                "= f_n = f_0 + n · Δf \\quad n = 0 … 64",
                "~ §f_0§ Frequenz von Ton 0, Δf Abstand des Untermodus [3]. Mit 22 Synchronsymbolen von 85 belegt die Synchronisation etwa ein Viertel der Aussendung, wie in [2] angemerkt.",
                "### Empfohlene Einstellungen in WSJT-X",
                "Für EME mit Q65 empfehlen die Autoren in WSJT-X: *File → Settings → General* mit **Enable VHF and submode features** und **Decode after EME delay** eingeschaltet und **Single decode** ausgeschaltet; im Menü *Decode* **Fast**, **Enable averaging** und **Auto Clear Avg after decode** [1]. Jede Q65-Dekodierung trägt den Buchstaben „q“ und eine oder zwei Ziffern: Die erste gibt die verwendete *A-priori*-Information an, die zweite die Anzahl der gemittelten Sequenzen [1].",
                "|h| Kennung | Verwendete A-priori-Information",
                "| q0 | keine",
                "| q1 | CQ",
                "| q2 | mein Rufzeichen",
                "| q3 | mein Rufzeichen und das Rufzeichen der DX-Station",
                "| q4 | beide Rufzeichen und RRR, RR73, 73 oder leer",
                "~ Aus [1]. Die Autoren warnen davor, den vom Dekoder angezeigten S/N-Werten zu viel Bedeutung beizumessen, da diese noch verbessert wurden [1]: Für Vergleiche mit dem EME-Budget von YAEC verwendet man besser mehrere QSOs statt einer einzelnen Ablesung.",
                "### Das Verfahren mit DXpeditionen (W7GJ)",
                "Lance Collister W7GJ, der seit Jahren EME-Expeditionen auf 6 m durchführt, beschreibt, wie man eine DXpedition in Q65-60A während eines Pile-ups anruft [6]. Vor allem müssen die Computeruhr sehr genau und die Sendefrequenz sehr stabil sein [6].",
                "• **Perioden.** Die DXpedition sendet immer in der ersten Sequenz (gerade Minuten); die Anrufer senden in der zweiten (ungerade Minuten) [6].",
                "• **Frequenz.** Wählen Sie eine freie Frequenz im Durchlassbereich und bleiben Sie dort: Q65 mittelt die Anrufe jeder Station auf ihrer eigenen Frequenz, und wenn Sie wechseln, geht der Vorteil Ihrer früheren Anrufe verloren. Lassen Sie etwa 100 Hz Abstand zu den anderen und prüfen Sie, dass der Doppler Ihr Signal nicht aus dem Durchlassbereich des DX schiebt; die Anrufer stimmen sich im EME-Chat von ON4KST ab [6].",
                "• **Betriebsart.** Verwenden Sie das Digital-Contest-Verfahren von Q65-60A: in WSJT-X unter *File → Settings → Advanced* eine der „Special Operating Activity“-Optionen NA VHF, WW Digi oder ARRL Digi (nach Version 2.6.1 auch Q65 Pileup). Tragen Sie Rufzeichen und Locator des DX in DX Call und DX Grid ein, drücken Sie Generate Std Msgs und beginnen Sie mit der Nachricht TX2, nicht mit CQ [6].",
                "• **Weiter rufen.** Auf 6 m ist die Ausbreitung zwischen linear polarisierten Stationen oft nicht reziprok: Der DX kann Sie aufnehmen, auch wenn Sie ihn nicht aufnehmen. Hören Sie nicht auf zu rufen und kehren Sie nicht zu einer früheren Nachricht zurück, wenn der DX mit anderen im QSO ist oder verschwindet: Jede Nachricht enthält beide Rufzeichen, und das QSO geht dort weiter, wo es stehen geblieben ist. Mit Q65 Pileup braucht der DX bei jedem Durchgang des Mondes mindestens eine Dekodierung von Ihnen [6].",
                "• **RRR, nie RR73.** Bei EME immer RRR verwenden: RR73 wird nur einmal gesendet, und das QSO wird geloggt, auch wenn die Gegenstation es nicht empfangen hat. Das QSO ist vollständig, wenn eine der beiden Stationen das abschließende RRR empfängt; wer es empfängt, antwortet so lange wie nötig mit 73, deshalb darf unter *Settings → Behavior* „Disable Tx after sending 73“ nicht angehakt sein [6].",
                "• **Den Bildschirm beobachten.** Auch wenn Sie den DX nicht dekodieren, zeigen seine Spur im Wasserfall (Wide Graph) oder die orangefarbene Q65-Spitze, dass Sie ihn wahrscheinlich aufnehmen werden, sobald er antwortet. Löschen Sie den Mittelwert von Hand, wenn Sie sehen, dass er jemand anderen gearbeitet hat: Der Nächste könnten Sie sein [6].",
                "|h| DX (erste Sequenz, gerade Minuten) | Anrufer (zweite Sequenz, ungerade Minuten)",
                "| CQ TX7MB CI00 | TX7MB OH2BC KP30",
                "| OH2BC TX7MB R CI00 | TX7MB OH2BC RRR",
                "| G8BCG TX7MB R CI00 | TX7MB G8BCG RRR",
                "| G8BCG TX7MB 73 | TX7MB G8BCG 73",
                "~ Gekürztes Beispiel aus [6], mit TX7MB (CI00) als DXpedition: Jeder Anrufer bleibt auf seiner eigenen Frequenz und geht zu RRR über, wenn er sein eigenes „R CI00“ empfängt.",
                "> Gemeinsame Mondfenster sind kurz, besonders bei Mondaufgang und Monduntergang, wenn viele Stationen den Bodeneffekt nutzen: Der Reiter Position live und +- 24h und der Reiter Entfernung und Dgrd zeigen, wann der Mond von beiden Stationen aus sichtbar ist.",
                ">⚠ Die Betrachtung der theoretischen Grenzen verliert ihre Bedeutung in dem Moment, in dem man die Signale tatsächlich empfängt: Ein plötzliches lokales Rauschen kann den Empfang verschlechtern, ebenso wie die Faraday-Drehung (§ 3.3).",
                "[1] Joe Taylor K1JT, Bill Somerville G4WJS, Steve Franke K9AN, Nico Palermo IV3NWV, “Quick-Start Guide to Q65”, 3. April 2021 (WSJT-X 2.4.0), zur Verfügung gestellt von IC8TEM.",
                "[2] Joe Taylor K1JT, “Sensitivity Comparison of JT65A and Q65-60A” (Testdateien JT65A_and_Q65-60A.zip), zur Verfügung gestellt von IC8TEM – https://physics.princeton.edu/pulsar/k1jt/JT65A_and_Q65-60A.zip",
                "[3] Andy Talbot G4JNT, “The Q65 Coding Process used in WSJT-X”, Oktober 2023, zur Verfügung gestellt von IC8TEM.",
                "[4] Nico Palermo IV3NWV, Vortrag auf der Konferenz EME 2016 über QRA-Codes, zitiert in [3] – http://www.eme2016.org/wp-content/uploads/2016/08/EME-2016-IV3NWV-Presentation.pdf",
                "[5] Quellcode von WSJT-X (Datei Q65_encoding_modules.F90 und andere), zitiert in [3] – https://wsjt.sourceforge.io/wsjtx.html",
                "[6] Lance Collister W7GJ, “Q65-60A QSO Procedure and Tips for EME DXpeditions”, überarbeitet am 3. April 2023, zur Verfügung gestellt von IC8TEM – http://www.bigskyspaces.com/w7gj/"
            };
            d["de"]["S54"] = new string[] {
                "## EME-Literatur von SM5BSZ",
                "Leif Åsbrink SM5BSZ, Autor von Linrad, hat auf seiner Website auch Untersuchungen zu EME veröffentlicht, die über seine Software hinausgehen. Zwei nützliche Arbeiten zum Verständnis des Weges Erde – Mond – Erde:",
                "• “Selecting Polarisation for EME” (25. April 1997): wie Geometrie, Reflexion am Mond, Faraday-Drehung und ionosphärische Absorption die Polarisation verändern, mit praktischen Hinweisen zur Wahl der Polarisation beim Senden und Empfangen je nach Frequenz – https://sm5bsz.com/polarity/emepol.htm",
                "• “EME Path Modulation” (23. Februar 2000): Spektren eines einige Minuten langen Trägers, gesendet von SM5FRH und von SM5BSZ über den Mond empfangen, mit der schmalen spiegelnden Komponente und der breiteren diffusen, die sich bezüglich der Polarisation unterschiedlich verhalten – https://sm5bsz.com/sm5frh/sm5frh.htm",
                "Zur sportlichen Seite von EME: Henryk Kotowski SM0JHF, “Moonbouncers Are Also Contesters”, contesting.com, 20. Mai 2002 – https://www.contesting.com/articles/294"
            };
            d["de"]["S55"] = new string[] {
                "## Andere EME-Rechenwerkzeuge",
                "• **EME Link Budget & Analysis Tool (1-300 GHz)** von Gerald Ihninger OE2IGL und Joachim Köppen DF3GJ: vollständiges Budget für die Bänder ab 1 GHz, mit Spiegelparametern, Ausrichtung, Libration und Atmosphäre – https://wettersat.bplaced.net/EME/EME.html",
                "• **WSJT-X** von Joe Taylor K1JT und Mitarbeitern: digitale Betriebsarten für EME (JT65, Q65 und andere) und das Fenster Astronomical Data mit Doppler und CAT – https://wsjt.sourceforge.io"
            };
            d["de"]["S43"] = new string[] {
                "## Polarisation, Dpol und MNR",
                "Der lokale Polarisationswinkel wird wie in WSJT-X aus der geografischen Breite sowie aus Azimut und Elevation des Mondes berechnet; §D_{pol}§ ist die Differenz zwischen den Winkeln der beiden Stationen, zwischen −90° und +90°. Der lineare Polarisationsverlust (höchstens 30 dB) und die maximale Nicht-Reziprozität MNR (höchstens 25 dB) betragen:",
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}",
                "Die Faraday-Drehung lässt sich nicht vorhersagen und ist nicht berücksichtigt.",
                "Der räumliche Polarisationsversatz lässt sich berechnen, weil er nur von der Lage der beiden Stationen abhängt: Vom Mond aus gesehen erscheinen eine horizontale Antenne am Nordpol und eine am Äquator die eine horizontal und die andere vertikal. Die Faraday-Drehung dagegen ist zufällig: Das Signal durchquert die Ionosphäre zweimal, auf dem Hin- und auf dem Rückweg, und dreht sich je nach der momentanen Elektronendichte. Es kann vorkommen, dass Sie den DX hören und er Sie nicht; bei 90° wird das Signal nicht gedämpft, es verschwindet. Wer horizontale und vertikale Antennen hat, kann immer mit der besten Polarisation empfangen und, wenn die Gegenstation nicht antwortet, die Sendepolarisation mit einem Relais umschalten [1].",
                "> Zwischen weit entfernten Stationen, zum Beispiel zwischen Nord- und Südhalbkugel, kann schon die geografische Lage §D_{pol}§ nahe an 90° bringen. Überschreitet es in den nächsten 24 Stunden 60°, zeigt das Programm gleich nach der Eingabe der Locator eine Warnung [1].",
                "Bei linear polarisierten Antennen beträgt der Verlust durch den räumlichen Polarisationsversatz etwa 3 dB bei 45°, 6 dB bei 60° und mehr als 20 dB bei 90°: Deshalb setzt die Warnung bei 60° ein [2].",
                "### Die Faraday-Drehung",
                "Die Ionosphäre enthält freie Elektronen, die sich, vom Erdmagnetfeld geführt, auf Spiralbahnen bewegen: Eine linear polarisierte Welle, die sie durchquert, tritt mit gedrehter Polarisationsebene wieder aus. Das ist die Faraday-Drehung [3]. Sie hängt von der Zahl der Elektronen entlang des Weges ab und nimmt mit dem Quadrat der Frequenz ab [3]:",
                "= F_{f} = F_{144} · \\p{\\frac{144}{f}}^{2}",
                "~ §F_{144}§ ist die Drehung bei 144 MHz, §f§ die Frequenz in MHz. Ein typischer Tageswert bei 144 MHz ist 180° mit dem Mond im Zenit und etwa das Vierfache bei 10° Elevation, weil der Weg durch die Ionosphäre länger ist [3].",
                "|h| Band | >Mond im Zenit | >Mond bei 10° Elevation",
                "| 50 MHz | >≈ 1.490° (mehr als 4 Umdrehungen) | >≈ 5.970°",
                "| 144 MHz | >180° | >≈ 720°",
                "| 432 MHz | >≈ 20° | >≈ 80°",
                "~ Drehung bei einem Durchgang durch die Ionosphäre, typischer Tageswert; 144 MHz aus [3], die übrigen Bänder von YAEC mit der obigen Formel abgeleitet (≈ = abgeleitet). Ab 1296 MHz kann sie als null angesehen werden [3].",
                "• **Sie hebt sich auf dem Rückweg nicht auf.** Der Drehsinn hängt nicht von der Richtung ab, in der sich die Welle ausbreitet: Nach dem zweiten Durchgang durch die Ionosphäre ist das Signal erneut gedreht, im gleichen Sinn [3]. Jede Station fügt die Drehung der Ionosphäre über ihr hinzu.",
                "• **Sie ändert sich mit der Zeit.** Die Elektronenmenge schwankt zwischen Tag und Nacht, bei Sonnenaufgang und Sonnenuntergang und mit der Sonnenaktivität: Bei sehr aktiver Sonne ist die Drehung stark und kann sich schnell ändern, und bei Polarlichtern kann sich die Polarisation innerhalb weniger Millisekunden ändern [3]. Deshalb lässt sie sich nicht durch eine Rechnung vorhersagen.",
                "• **Sie addiert sich zum räumlichen Polarisationsversatz.** Der räumliche Polarisationsversatz (§D_{pol}§) hat in den beiden Richtungen der Verbindung entgegengesetztes Vorzeichen, während die Faraday-Drehung den gleichen Sinn behält: In der einen Richtung addieren sich die beiden Drehungen, in der anderen subtrahieren sie sich. So kann es vorkommen, dass Sie den DX hören und er Sie nicht, oder umgekehrt [1]. Der Verlust folgt demselben Gesetz wie bei §D_{pol}§, §L = −20 · log_{10} \\a{cos Δ}§, mit Δ als gesamtem Versatz: Bei 90° verschwindet das Signal.",
                "• **Was tun.** Von 50 bis 432 MHz wird lineare Polarisation verwendet: Sinnvoll ist eine Anlage, mit der sich die Polarisationsebene wählen lässt, besser elektronisch umgeschaltet als durch mechanisches Drehen der ganzen Antenne [3]. Beim CQ-Rufen ist es wirksamer, zwischen horizontal und vertikal zu wechseln, als zirkulare Polarisation zu verwenden, die immer 3 dB kostet [3]. Mit horizontalen und vertikalen Antennen empfängt man mit der besseren Polarisation und schaltet, wenn die Gegenstation nicht antwortet, die Sendepolarisation um [1].",
                "> Bei 432 MHz ist die Faraday-Drehung klein, und es überwiegt der räumliche Polarisationsversatz, den YAEC berechnet; bei 50 und 144 MHz kann sie mehrere Umdrehungen erreichen und ist unvorhersehbar: §D_{pol}§ und die Warnung über 60° berücksichtigen nur den räumlichen Anteil.",
                "### Die Polarisation für EME wählen: Zusammenfassung des Artikels von SM5BSZ",
                "Der Artikel „Selecting Polarisation for EME“ von Leif Åsbrink SM5BSZ (25. April 1997) ist öffentlich und auf seiner Website zu lesen: https://sm5bsz.com/polarity/emepol.htm. Der Autor dieses Programms hält es für nützlich, hier eine Zusammenfassung davon als Anregung anzubieten, in eigenen Worten geschrieben; für die vollständigen Erklärungen sei auf die Lektüre des ganzen Artikels verwiesen [3].",
                "• **Vier Effekte.** Auf dem Weg Erde – Mond – Erde ändert sich die Polarisation durch den räumlichen Polarisationsversatz, die Reflexion am Mond, die Faraday-Drehung und die Absorption in der Ionosphäre [3].",
                "• **Räumlicher Polarisationsversatz.** Vom Mond aus gesehen sind zwei weit entfernte Antennen auf der gekrümmten Erde nicht parallel. Er betrifft nur die lineare Polarisation, lässt sich leicht berechnen und hängt nicht von der Frequenz ab [3]: Er ist §D_{pol}§ in YAEC.",
                "• **Reflexion am Mond.** Bei niedrigen Frequenzen wie 144 MHz verhält sich der Mond wie eine glatte Kugel: Lineare Polarisation bleibt linear, zirkulare kehrt ihren Drehsinn um, und etwa 1 % der Energie landet in der „falschen“ Polarisation. Bei 10 GHz ist die Oberfläche rau, und das Signal kommt depolarisiert zurück [3].",
                "• **Faraday-Drehung.** Sie ist im vorigen Unterabschnitt beschrieben: Sie nimmt mit dem Quadrat der Frequenz ab, addiert sich auf dem Hin- und Rückweg und lässt sich nicht vorhersagen [3].",
                "• **Ionosphärische Absorption.** Auch sie nimmt mit dem Quadrat der Frequenz ab: Bei 144 MHz beträgt sie tagsüber und bei 10° Elevation etwa 0,1 dB. Sie spielt nur bei sehr hoher Sonnenaktivität eine Rolle; bei starken Polarlichtern kann sich die Polarisation schneller ändern, als ein schmalbandiger Empfänger folgen kann [3].",
                "• **Von 50 bis 432 MHz.** Fast alle verwenden linear polarisierte Yagis: Der Autor empfiehlt eine Anlage mit umschaltbarer linearer Polarisation, am besten elektronisch; eine mechanische Drehung ist in Ordnung, wenn die Vierteldrehung eine oder wenige Sekunden dauert [3]. Beim Empfang wählt man die Polarisation mit dem stärksten Signal (ein Zweikanalempfänger ist bei schwachen Signalen schneller); beim CQ-Rufen wechselt man besser zwischen horizontal und vertikal, statt zirkulare Polarisation zu verwenden, die immer 3 dB kostet [3].",
                "• **Ab 10 GHz.** Der Mond depolarisiert das Signal, die Sendepolarisation spielt keine Rolle mehr, und man braucht einen Zweikanalempfänger an zwei orthogonalen Erregern [3]. Diese Frequenzen liegen außerhalb der Bänder von YAEC.",
                "• **Mit welcher Polarisation senden.** Wenn Sie eine Station empfangen, können Sie ermitteln, mit welcher Polarisation Sie ihr senden müssen, damit Ihr Signal richtig bei ihr ankommt [3]. Mit Winkeln in Grad (0° horizontal, 90° vertikal) ist P die Sendepolarisation der anderen Station, R die, mit der Sie sie empfangen, S der räumliche Polarisationsversatz, F die Faraday-Drehung und T Ihre beste Sendepolarisation:",
                "= R = P + S + F \\quad P = T − S + F \\quad T = 2 · S − R",
                "~ Eliminiert man F aus den ersten beiden Beziehungen, erhält man §T = 2 · P + 2 · S − R§; für eine lineare Antenne ist §2 · P§ gleich 0° oder 180°, also dieselbe Polarisation, und es bleibt §T = 2 · S − R§ [3]. Ohne Faraday-Drehung (§F§ = 0, ab 1296 MHz) ist die beste Sendepolarisation dieselbe, mit der man am besten empfängt, §T = R§. Der Artikel weist darauf hin, dass die Regel mit der von KL7WE übereinstimmt, und nennt das Programm SKYMOON von W5UN zur Berechnung von S [3].",
                "> In YAEC ist der räumliche Polarisationsversatz S der in den Reitern Mondposition und Position live und +- 24h berechnete Wert §D_{pol}§; die Faraday-Drehung F lässt sich nicht berechnen. Für die Beispiele, die Sonderfälle und die Abbildungen lesen Sie den vollständigen Artikel von SM5BSZ [3].",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s",
                "[2] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, Präsentation, Juli 2015, zur Verfügung gestellt von IC8TEM.",
                "[3] Leif Åsbrink SM5BSZ, “Selecting Polarisation for EME”, 25. April 1997 – https://sm5bsz.com/polarity/emepol.htm"
            };
            d["de"]["S44"] = new string[] {
                "## Himmelsrauschen und Dgrd",
                "Die Himmelstemperatur hinter dem Mond (§T_{sky}§) bei 144 MHz wird entlang der Ekliptik aus einer Tabelle in 2°-Schritten (WSJT-X) entnommen und in der Ansicht Sky aus einer Ganzhimmelskarte mit 2° Auflösung, abgeleitet aus dem Global Sky Model; andere Frequenzen werden mit dem Spektralindex 2,6 skaliert:",
                "= T(f) = \\p{T_{144} − 2.7} · \\p{\\frac{144}{f}}^{2.6} + 2.7 \\t{ K}",
                "Dgrd fügt wie in WSJT-X den Einfluss der Mondentfernung d und den des Himmelsrauschens hinzu:",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2.6} \\t{ K}",
                "### Was die Dgrd bedeutet",
                "Die **Dgrd** (*degradation*, Verschlechterung) gibt an, um wie viele dB das Mondecho in diesem Augenblick schlechter ist als unter den bestmöglichen Bedingungen: Mond im Perigäum und kalter Himmel hinter dem Mond. Sie hängt nicht von der Station ab, sondern nur vom Mond und vom Himmel: Deshalb dient sie dazu, Tage und Stunden auszuwählen, nicht dazu, die Verbindung zu berechnen – das ist die Aufgabe des EME-Budgets.",
                "• **0 dB** ist der Idealfall; die Werte sind immer negativ. **−3 dB** bedeutet das halbe S/N gegenüber dem Idealfall, **−6 dB** ein Viertel.",
                "• Der erste Term der Formel ist die **Entfernung**: Zwischen Perigäum (etwa 356 900 km) und Apogäum (etwa 406 700 km) ändert sich das Echo um etwa 2,3 dB, weil die Streckendämpfung mit der vierten Potenz der Entfernung wächst. Das scheint wenig, aber eine Verdopplung der Antennen bringt theoretisch nur 3 dB [1].",
                "• Der zweite Term ist das **Himmelsrauschen** hinter dem Mond: Wenn der Mond vor der Milchstraße vorbeizieht, steigt die Himmelstemperatur stark an, und die Dgrd kann um mehrere dB fallen, mehr als durch die Entfernung.",
                "• Typische Werte sind −1, −1,5 oder −2 dB. Mit dem Mond auf dem Zentrum der Galaxis sah I2FAK −11 dB, die schlechtestmöglichen Bedingungen, und schloss trotzdem ein QSO mit einer sehr schwachen Station ab, einer DXpedition aus Dschibuti, dank einer Anlage mit 16 + 16 Antennen: Unter so schlechten Bedingungen muss die Station perfekt kalibriert sein, und die Erfahrung zählt mehr als die Vorhersagen der Software [1].",
                "• Für eine kleine Station zählt jedes dB: Ein Tag mit Dgrd −1 dB und einer mit −5 dB können den Unterschied zwischen einem vollständigen QSO und gar keiner Dekodierung ausmachen.",
                "> Im Programm: Das DGRD-Feld im Reiter Position live und +- 24h zeigt den aktuellen Wert zwischen dem Minimum und dem Maximum des Diagramms; der Reiter Entfernung und Dgrd zeigt den Kalender der nächsten Tage, das Diagramm mit der Entfernung und die drei besten Tage.",
                "### Der Mond vor den Rauschquellen der Galaxis",
                "Jeden Monat wandert der Mond entlang des Bandes der Ekliptik (innerhalb von etwa 5° davon) und kreuzt zweimal die Milchstraße. Die beiden Durchgänge sind nicht gleich:",
                "• **Schütze, Zentrum der Galaxis**: der heißeste Bereich des Himmels; bei 144 MHz erreicht die Himmelstemperatur hinter dem Mond einige tausend K, gegenüber etwa 200 K in den kalten Bereichen, und dieser Bereich rauscht stärker als die Sonne [1]. Hier steht der Mond auch auf seiner tiefsten Deklination, um −30° in den Jahren maximaler Deklination: Von Norditalien aus (etwa 45° N) steigt er nur auf 15 – 16° Elevation und bleibt etwa 6 Stunden über 5° (etwa 7 Stunden über dem Horizont), während er bei +30° etwa 75° erreicht und etwa 15 – 16 Stunden über 5° bleibt [1]. Das ist die schlechteste Zeit des Monats.",
                "• **Stier und Zwillinge, auf der Gegenseite (Antizentrum)**: Die Milchstraße ist viel weniger heiß, aber im Stier, ganz nah an der Ekliptik, liegt der **Krebsnebel** (Taurus A), eine der stärksten Radioquellen des Himmels: Wenn der Mond vor ihm oder neben ihm vorbeizieht, steigt das Rauschen.",
                "• Das Himmelsrauschen wächst mit abnehmender Frequenz: Bei 50 MHz wiegt es viel mehr als bei 144 MHz, bei 432 MHz viel weniger (das Programm skaliert es mit dem Spektralindex 2,6).",
                "> Im Programm: Die Ansicht Sky färbt den Himmel von Blau (kalt) bis Rot (heiß) und zeigt, wo der Mond steht; die Spalte Tsky im Reiter Mondposition und der Kalender von Entfernung und Dgrd zeigen, wann der Mond vor den heißen Bereichen steht.",
                "### Die Deklination des Mondes",
                "Die **Deklination** (§δ§) ist die „Breite“ des Mondes am Himmel: um wie viele Grad er nördlich (+) oder südlich (−) des Himmelsäquators steht. Das Programm berechnet sie aus Datum und Uhrzeit und verwendet sie in allen Berechnungen (Elevation, Fenster, Tsky, Dpol, Doppler): Sie müssen sie nicht eingeben. Sie zu kennen, hilft aber bei der Wahl der Tage.",
                "• **Monatlicher Zyklus**: In etwa 27,3 Tagen geht die Deklination vom nördlichen zum südlichen Maximum und wieder zurück. Steht der Mond auf der Seite Ihrer eigenen Hemisphäre (positiv im Norden, negativ im Süden), steigt er höher und bleibt mehr Stunden über dem Horizont; auf der Gegenseite bleibt er tief und nur wenige Stunden oben [1].",
                "= El_{max} ≈ 90° − \\a{φ − δ} \\quad cos H_{0} = − tan φ · tan δ \\quad t_{su} = \\frac{2 · H_{0}}{15°} \\t{ h}",
                "~ §φ§ ist die Breite der Station, §H_{0}§ der Stundenwinkel bei Mondaufgang und Monduntergang, §t_{su}§ die Zahl der Stunden mit dem Mond über dem Horizont (ohne Hindernisse und ohne Refraktion). Beispiel bei 41° N: Mit §δ§ = +28° erreicht der Mond etwa 77° und bleibt etwa 15,7 Stunden oben; mit §δ§ = −28° kommt er nur auf etwa 21° und bleibt etwa 8,3 Stunden oben.",
                "• **Verbindungen zwischen den Hemisphären**: In einem Nord – Süd-QSO bevorzugen die beiden Stationen entgegengesetzte Deklinationen; die längsten gemeinsamen Fenster ergeben sich oft, wenn der Mond nahe am Himmelsäquator steht (Deklination um 0°) und keine der beiden Stationen benachteiligt ist.",
                "• **Zyklus von 18,6 Jahren**: Die Weite des monatlichen Hubs ändert sich langsam, von etwa ±18,3° bis etwa ±28,6°. Das Maximum (große Mondwende) lag in den Jahren 2024 – 2025; gegen 2034 wird der Hub am kleinsten sein, mit weniger extremen Monaten: Der Mond sinkt dann nicht mehr so tief, steigt aber auch nicht mehr so hoch.",
                "• **Deklination und Rauschen**: Die tiefste Deklination erreicht der Mond, wenn er vor dem Schützen vorbeizieht, dem am stärksten rauschenden Bereich des Himmels, und die höchste in Stier und Zwillingen, wo der Himmel kälter ist. Für Stationen auf der Nordhalbkugel vereint die Woche der tiefsten Deklination daher einen tiefen Mond, wenige nutzbare Stunden und eine hohe Tsky [1].",
                "> Im Programm: Unter dem Diagramm des Reiters Entfernung und Dgrd zeigt die Deklinationskurve die nördlichen und südlichen Maxima mit Datum; der grüne Bereich zeigt, wann der Mond auf der Seite Ihrer Hemisphäre steht (die Kurve lässt sich mit dem Kästchen Deklinationskurve ausblenden). Der Wert zu jedem Zeitpunkt steht in der optionalen Spalte Deklination (°) des Reiters Mondposition und im Reiter Position live und +- 24h.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["de"]["S45"] = new string[] {
                "### Warum die Sonne zählt",
                "Die **Sonne** ist die stärkste Rauschquelle am Himmel. Um Neumond stehen Sonne und Mond am Himmel nahe beieinander: Auch wenn die Sonne außerhalb der Hauptkeule bleibt, kommt sie über die Nebenkeulen herein, und innerhalb weniger Keulenbreiten steigt das Empfangsrauschen stark an. Deshalb ist die Woche um Neumond in der Praxis fast immer zu meiden.",
                "• Wie stark sie ins Gewicht fällt, hängt vom Antennengewinn ab (schmalere Keule, Sonne in Keulenbreiten weiter entfernt), vom Pegel der Nebenkeulen und von der **Sonnenaktivität**: Der Sonnenfluss in SFU ändert sich von Tag zu Tag und steigt bei Flares stark an.",
                "• Deshalb ist eine Antenne mit **stark gedämpften Nebenkeulen** unerlässlich: Die Nebenkeulen nehmen das Rauschen der Umgebung auf und addieren es zu dem der Hauptkeule [1].",
                "• Bei einer Sonnenfinsternis steht der Mond genau vor der Sonne: I2FAK schloss trotzdem ein QSO ab, indem er 2,5 – 3° neben den Mond zielte, sodass die schmale Keule seiner Gruppe das Sonnenrauschen dämpfte [1].",
                "• Die Sonne unter dem Horizont des Empfängers zählt nicht, auch nicht bei Neumond.",
                "> Im Programm: Der Kalender von Entfernung und Dgrd markiert mit dem Symbol ☀ die Tage, an denen die Sonne nahe am Mond steht (orange oder rot); der Reiter Sonnenrauschen berechnet mit dem gemessenen Fluss, wie viel zusätzliches Rauschen die Sonne im gewählten Augenblick bringt.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["fr"] = new Dictionary<string, string[]>();
            d["fr"]["S32"] = new string[] {
                "## Le locator Maidenhead (WWL)",
                "Le **locator Maidenhead**, appelé aussi WWL (World Wide Locator) ou QTH locator, est le code que les radioamateurs utilisent pour indiquer la position de leur station. Il a été conçu par John Morris G4ANB et adopté par le groupe de travail VHF de l'IARU en avril 1980, lors d'une réunion à Maidenhead, en Angleterre ; il a remplacé l'ancien QRA locator, qui ne couvrait que l'Europe [1]. Depuis 1999 le système géodésique de référence est le WGS-84, le même que celui du GPS [1]. YAEC tire du locator la latitude et la longitude de la station, et de celles-ci tous les calculs.",
                "### Comment il est construit",
                "Le locator est une suite de paires : chaque paire donne d'abord la longitude puis la latitude, et divise le rectangle de la paire précédente en parties plus petites. Les paires alternent lettres et chiffres [1]. Un exemple à 14 caractères : **PM 95 UP 98 KB 75 MI** (Tokyo).",
                "@locator PM 95 UP 98 KB 75 MI",
                "|h| Paire | Nom | Symboles | >Divise en | >Taille (lon × lat) | >Caractères | >Côté à 35,7° (Tokyo) | >Erreur maximale",
                "| 1re | champ (field) | A … R | 18 × 18 | 20° × 10° | 2 | – | –",
                "| 2e | carré (square) | 0 … 9 | 10 × 10 | 2° × 1° | 4 | 181 × 111 km | ±106 km",
                "| 3e | sous-carré (subsquare) | A … X | 24 × 24 | 5′ × 2,5′ | 6 | 7,5 × 4,6 km | ±4,4 km",
                "|+ 4e | carré étendu | 0 … 9 | 10 × 10 | 30″ × 15″ | **8** | 753 × 463 m | **±442 m**",
                "| 5e | sous-carré étendu | A … X | 24 × 24 | 1,25″ × 0,625″ | **10** | 31 × 19 m | **±18 m**",
                "| 6e | – | 0 … 9 | 10 × 10 | 0,125″ × 0,0625″ | 12 | 3,1 × 1,9 m | ±1,8 m",
                "| 7e | – | A … X | 24 × 24 | 0,0052″ × 0,0026″ | 14 | 13 × 8 cm | ±8 cm",
                "~ Tailles tirées des règles de [1] ; côtés et erreur maximale (moitié de la diagonale, avec la station au centre du rectangle) calculés par YAEC pour la latitude de Tokyo : vers les pôles le côté est-ouest se raccourcit. Les lettres s'écrivent en majuscules, comme l'a précisé l'IARU en 2019 [1] ; YAEC accepte aussi les minuscules et les convertit.",
                "> Au-delà de 8 caractères il n'existe pas de norme commune : la 5e paire et les suivantes ne sont pas formellement définies, et la pratique la plus courante, celle que suit YAEC, reprend les règles des paires précédentes (lettres en base 24, chiffres en base 10). D'autres programmes peuvent utiliser des codages différents, si bien qu'un locator long peut ne pas être lu de la même façon partout [1].",
                "### Combien de caractères utiliser",
                "En HF on utilise généralement le carré (4 caractères) ; sur les bandes de YAEC, de 50 à 432 MHz, on utilise le sous-carré (6 caractères) [1]. Ces règles s'appliquent aux échanges en QSO et aux concours : par exemple, en Région 1 de l'IARU les distances se mesurent entre les centres des sous-carrés [1]. Pour les calculs de YAEC le choix est différent :",
                "|h| Caractères | Usage conseillé dans YAEC",
                "| 4 | seulement pour une estimation grossière : l'azimut et l'élévation de la Lune peuvent être faux jusqu'à environ 1°, car l'horizon local s'incline d'environ 1° tous les 111 km",
                "| 6 | le locator du DX, les QSO et le bilan EME : l'erreur sur la direction de la Lune est de quelques centièmes de degré",
                "| **8** | votre station, pour Reconnaissance of my obstacles : il identifie le quartier ou la colline",
                "|+ **10** | votre station, avec le meilleur résultat : il identifie le bâtiment ou le pylône de l'antenne",
                "| 12 – 14 | acceptés, mais ils n'apportent rien : la précision dépasse celle d'un GPS courant (quelques mètres) et la taille de l'antenne elle-même",
                "### Locator et obstacles",
                "Pour la direction de la Lune 6 caractères suffisent : la Lune est à environ 380 000 km, et les ±4,4 km d'un locator à 6 caractères modifient l'azimut et l'élévation d'environ 0,04°, une quantité négligeable par rapport au lobe de l'antenne. Pour les **obstacles locaux** (bâtiments, arbres, collines) c'est l'inverse : ils se trouvent à quelques dizaines ou centaines de mètres de l'antenne, et avec 6 caractères la station peut être n'importe où dans un rectangle de 7,5 × 4,6 km, si bien que les obstacles ne peuvent pas être placés. Avec 8 caractères l'erreur tombe à environ 450 m, avec 10 à environ 20 m : c'est la précision dont l'onglet **Reconnaissance of my obstacles** a besoin pour tracer correctement les zones où l'antenne est masquée.",
                ">+ Conseil pratique : tirez le locator à 10 caractères des coordonnées GPS du point où se trouve l'antenne (et non de l'entrée de la maison) et saisissez-le dans l'onglet Position en direct et +- 24h comme **my locator**. Pour le DX, le locator à 6 caractères qu'il vous donne suffit.",
                "[1] Wikipedia, “Maidenhead Locator System” (origine G4ANB et réunion VHF de l'IARU à Maidenhead en 1980, structure des paires, WGS-84 depuis 1999, extensions au-delà de 8 caractères, précision de l'IARU de 2019, usage en HF et en VHF/UHF, distances entre centres des sous-carrés) – https://en.wikipedia.org/wiki/Maidenhead_Locator_System"
            };
            d["fr"]["S46"] = new string[] {
                "### Les formules du bilan EME",
                "L'affaiblissement de trajet suit l'équation du radar : le signal va de la station à la Lune, une partie est diffusée et revient vers la Terre. Les distances §d_1§ et §d_2§ sont les distances topocentriques des deux stations à l'instant choisi, si bien que la différence entre périgée et apogée (environ 2,3 dB) est déjà incluse.",
                "= λ = \\frac{c}{f} \\quad σ = 0.065 · π · R_M^2",
                "= L_{EME} = 10 · log_{10} \\b{\\frac{\\p{4π}^3 · d_1^2 · d_2^2}{σ · λ^2}} \\t{ dB}",
                "~ avec §c = 299 792 458 \\t{ m/s}§, §R_M = 1 737,4 \\t{ km}§ (rayon de la Lune), réflectivité lunaire 0,065.",
                "La puissance rayonnée et le signal aux bornes de l'antenne de réception :",
                "= EIRP = P_{dBW} − L_{TX} + G_{ant} + 10 · log_{10} N + G_g \\quad S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                "= G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}} \\quad L_{pol} = −20 · log_{10} \\a{cos D_{pol}}",
                "~ Gain de sol (case « BETA- antenna without elevation ») : antenne à polarisation horizontale à la hauteur h, calculé à l'élévation de la Lune, au maximum +6 dB.",
                "Le facteur de bruit de la chaîne de réception s'obtient avec la formule de Friis, en valeurs linéaires (§F = 10^{NF/10}§, §G = 10^{G_{dB}/10}§) :",
                "= F_{tot} = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + … \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "Le facteur de bruit du poste se déduit de son MDS, mesuré dans la bande passante B :",
                "= NF_{radio} = MDS + 174 − 10 · log_{10} B",
                "= T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e \\quad N = 10 · log_{10} \\p{k · T_{sys} · B} + 30 \\quad \\frac{S}{N} = S_{ant} − N",
                "~ avec §k = 1,380649 · 10^{−23} \\t{ J/K}§ (Boltzmann) et B la bande passante en Hz. §T_{ant}§ est la température d'antenne tirée des tables de VE7BQH (antenne inclinée à 30°) ; §ΔT_{sky} = max \\p{0, T_{sky} − T_{ref}}§, avec §T_{ref}§ = 200 K à 144 MHz, mis à l'échelle avec l'indice 2,6.",
                "Le bilan EME ne calcule pas de marge sur le mode : il affiche le S/N estimé, ramené à la bande de référence de 2500 Hz utilisée par WSJT-X, et, à côté, le seuil typique du mode choisi, à titre de référence seulement. Un seuil n'est pas une limite stricte : avec les aides du décodeur, on décode même plus bas, comme le montrent le tableau du JT65 et les notes ci-dessous.",
                "= \\frac{S}{N}_{2500} = \\frac{S}{N}_{B} + 10 · log_{10} \\frac{B}{2500}",
                "|h| Mode | >Seuil typique, message unique (2500 Hz) | Source",
                "| JT65 | −25 dB | [1]",
                "| JT9 | −27 dB | [1]",
                "| JT4 | −23 dB | [1]",
                "| FT8 | ≈ −20 dB | [1]",
                "| FT4 | ≈ −16,5 dB | [1]",
                "| Q65-15A | −22,2 dB | [2]",
                "| Q65-30A | −24,8 dB | [2]",
                "| Q65-60A | −27,6 dB | [2]",
                "| Q65-120A | −30,8 dB | [2]",
                "| Q65-300A | −33,8 dB | [2]",
                "| WSPR | −31 dB | [1]",
                "~ Seuils pour une probabilité de décodage de 50 %, mesurés sur un canal à bruit blanc gaussien additif (AWGN). Pour Q65, le décodage *a priori* (AP), qui utilise les indicatifs déjà connus pendant le QSO, ajoute de 1,5 à 3,6 dB selon le sous-mode (par exemple Q65-60A −30,2 dB) [2] ; YAEC affiche comme référence les valeurs plus prudentes sans AP. Avec un étalement Doppler de quelques hertz le seuil se dégrade : pour Q65-60A d'environ 2 dB à 5 Hz et d'environ 3 dB à 10 Hz (lu sur le graphique de [2]). La structure de Q65, ses sous-modes et la comparaison avec JT65 se trouvent au § 3.12. Pour l'EME le document conseille Q65-60A sur 50 et 144 MHz et Q65-60B sur 432 MHz [2] : les sous-modes B – E ont un espacement des tons et une bande occupée 2 – 16 fois ceux du sous-mode A.",
                "Pour le JT65, K1JT a publié les limites de chaque type de décodage, obtenues par des simulations du sous-mode JT65B [5] :",
                "|h| JT65 : type de décodage | >S/N (2500 Hz) | Source",
                "| Message quelconque, y compris texte libre | −24 dB | [5]",
                "| Indicatif présent dans la base de données (Deep Search) | −28 dB | [5]",
                "| Message quelconque avec moyennage de plusieurs émissions | −29 dB | [5]",
                "| Synchronisation seule (temps et fréquence) | −30 dB | [5]",
                "| Messages abrégés RO, RRR, 73 | −32 dB | [5]",
                "~ Le guide de WSJT-X donne −25 dB pour un message unique [1]. Le décodage Deep Search ne teste que les messages avec CQ ou votre indicatif plus un indicatif et un locator de la base de données : un indicatif inconnu ou un texte libre ne se décodent qu'avec le décodeur général, avec le moyennage si nécessaire [5]. Le décodage est « tout ou rien » : un message se lit en entier ou pas du tout, il ne se dégrade pas peu à peu à l'approche de la limite [5]. C'est pourquoi YAEC n'indique plus les dB au-dessus ou au-dessous du seuil.",
                "### Le gain de sol en pratique",
                "Le gain de sol de la case « BETA- antenna without elevation » suit le modèle du sol plan et réfléchissant : le rayon direct et le rayon réfléchi s'additionnent quand la différence de trajet est un nombre demi-entier n de longueurs d'onde et s'annulent quand elle est entière, avec §n · λ = 2 · H · sin α§ ; le point de réflexion se trouve à une distance §D = \\frac{H}{tan α}§ de l'antenne [3]. Les essais d'IK1UWL avec les échos de sa propre station (4 × 14 éléments à 121 m au-dessus de la mer, côte ligure) montrent qu'en pratique les choses sont plus compliquées [3] :",
                "• les maxima et les nuls sont nombreux et rapprochés, à des angles fractionnaires qu'un simulateur travaillant par pas de 1° comme EZNEC ne voit pas : avec l'antenne haute au-dessus de la mer, ils se succèdent environ toutes les 3 minutes (3 périodes JT65) et provoquent un fort QSB à basse élévation, qui ne dépend pas de l'ionosphère ;",
                "• le gain mesuré a été d'environ 3 dB, et non des 6 dB théoriques : dans un groupement, les yagis supérieures et inférieures sont à des hauteurs différentes (4,5 m), leurs réflexions ne sont pas en phase et une seule paire contribue à la fois ;",
                "• sous 2° d'élévation il y a un trou de gain et le maximum se situe vers 5° ; en élevant l'antenne, l'effet de sol diminue et au-delà de la largeur du lobe (environ 12° pour son groupement) il devient négligeable ;",
                "• la réfraction compte : la Lune s'est levée à −0,51°, sous l'horizon optique de −0,35° ; à 200 MHz, en air sec, l'erreur de réfraction à 0° d'élévation est de −0,49°.",
                "IK3XTV rappelle qu'en théorie l'effet de sol atteint 6 dB, si bien qu'une seule yagi rend presque autant qu'un groupement de 4, mais il dépend beaucoup du terrain autour de l'antenne : il est plus faible en ville, meilleur en rase campagne et plus encore près de la mer. On en profite au lever et au coucher de la Lune, entre environ 1° et 18 – 20° d'élévation [4].",
                "> C'est pourquoi, dans le bilan EME, le gain de sol est marqué BETA : la valeur calculée (au maximum +6 dB) est une limite théorique. Avec des antennes hautes au-dessus de la mer ou des groupements de plusieurs yagis, il faut s'attendre à environ la moitié et à un QSB marqué à basse élévation [3].",
                "[1] WSJT-X User Guide, K1JT et le WSJT Development Group, § 7.1 (FT4 = FT8 + 3,5 dB).",
                "[2] J. Taylor K1JT, B. Somerville G4WJS, S. Franke K9AN, N. Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 avril 2021 (WSJT-X 2.4.0), fourni par IC8TEM.",
                "[3] Giorgio Marchi IK1UWL, “Considerazioni sull'effetto suolo (Ground Gain)”, 21e Meeting EME, présentation fournie par IC8TEM.",
                "[4] Flavio Egano IK3XTV, “EME (earth-moon-earth) con una singola Yagi in 144 MHz”, document du 12 novembre 2010, fourni par IC8TEM.",
                "[5] J. Taylor K1JT, exposé sur le JT65 à la conférence EME 2006 (K1JT_eme2006.pdf) : tableau des niveaux minimaux de S/N en 2500 Hz.",
                "> Le schéma de la station, à droite de l'onglet, déduit les pertes des câbles choisis : en émission câble PA–relais + relais + câble d'antenne, en réception câble d'antenne + relais avant le préampli et câble de descente après celui-ci. Les affaiblissements des câbles proviennent de la base de données de l'onglet COAXIAL CABLES (§ 3.8)."
            };
            d["fr"]["S47"] = new string[] {
                "## Le préampli et le facteur de bruit du poste {nuovo}",
                "En EME le signal qui arrive à l'antenne n'est que légèrement au-dessus du bruit (environ −149 dBm dans l'exemple Tokyo – Le Cap). Le préampli a deux rôles distincts : **récupérer le signal** perdu dans les câbles jusqu'à la station et, surtout, **couvrir le facteur de bruit du poste**, qui sur les transceivers VHF/UHF du commerce va d'environ 3 – 5 dB avec le préampli interne en service à 15 – 16 dB et plus avec le préampli hors service.",
                "La raison se trouve dans la formule de Friis : chaque étage pèse sur le bruit total divisé par le gain de tout ce qui le précède. Le premier étage décide presque de tout.",
                "= F_{tot} = F_{LNA} + \\frac{F_{cable} − 1}{G_{LNA}} + \\frac{F_{radio} − 1}{G_{LNA} · G_{cable}} \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "~. F et G en valeurs linéaires (§F = 10^{NF/10}§) ; pour un câble d'affaiblissement L en dB : §F_{cable} = 10^{L/10}§ et §G_{cable} = 10^{−L/10}§.",
                "@colonne 55",
                "#### Facteur de bruit mesuré de quelques postes",
                "|h| Poste | >MHz | Préampli | >NF (dB) | Source",
                "| Icom IC-9700 | 144 | off / on | 16 / 3 | [1]",
                "| Icom IC-9700 | 432 | off / on | 15 / 4 | [1]",
                "| Yaesu FT-991 | 50 | IPO / AMP1 / AMP2 | 29 / 17 / 8 | [2]",
                "| Yaesu FT-991 | 144 · 432 | – | 5 · 4 | [2]",
                "| Icom IC-275E | 144 | – | 5,6 | [3]",
                "| Icom IC-9100 | 144 · 432 | non indiqué | ≈ 5 · ≈ 5 | [5]{r:*}",
                "| Icom IC-821H | 144 | – | 3,4 | [3]",
                "| Icom IC-910H | 144 | – | 3,7 | [3]",
                "| Icom IC-7000 | 144 | – | 5,6 | [3]",
                "| Kenwood TS-790E | 144 | – | 4,5 | [3]",
                "| Kenwood TS-2000 | 144 | on | 6,2 | [3]",
                "| Yaesu FT-847 | 144 | on / off | 5,1 / 6,7 | [3]",
                "| Yaesu FT-817 | 144 | – | 5,4 | [3]",
                "| Yaesu FT-857D | 144 | – | 6,1 | [3]",
                "| Icom IC-746PRO | 50 | off / P1 / P2 | 19 / 9 / 6 | [14]",
                "| Icom IC-746PRO | 144 | off / on | 14 / 5,2 | [14]",
                "| Yaesu FT-897 | 50 | on / IPO | 3,6 / 8,7 | [15]",
                "| Yaesu FT-897 | 144 · 432 | toujours on | 5,9 · 7,7 | [15]",
                "~ [1] [2] mesures de VA7OJ avec une source de bruit étalonnée ; [3] mesures de DF9IC par la méthode du facteur Y, précision ±0,5 dB, 144 MHz seulement, de 2005. Avec le préampli interne en service, l'IC-9700 sature déjà de −9 à −27 dBm à 144 MHz [1]. * Valeur à vérifier : essai préliminaire sur un exemplaire de présérie, auteur non indiqué. [14] NF déduit du plancher de bruit (MDS) mesuré dans 500 Hz : NF = MDS + 174 − 27 dB ; avec le préampli en service à 144 MHz la dynamique de blocage à 5 kHz passe de 99,9 à 88,4 dB. [15] NF déduit de la sensibilité SSB pour 10 dB (S+N)/N avec le filtre de 2450 Hz : NF = S − 9,5 + 174 − 10·log B ; sur 144 et 432 MHz le préampli est toujours en circuit. Pour [14] et [15] la précision est indicative, ±1 dB.",
                "@destra",
                "#### Exemple : 35 m de Sivacavi HF 400 (1,6 dB) à 144 MHz",
                "|h| Configuration | >NF total | >Te | >Tsys | >Dégrade le S/N de",
                "| Poste seul, préampli interne hors service (NF 16) | 17,6 dB | 16 398 K | 16 648 K | %bar:17.6:17.6:r%17,6 dB",
                "| Poste seul, préampli interne en service (NF 3) | 4,6 dB | 546 K | 796 K | %bar:4.4:17.6:o%4,4 dB",
                "| LNA à l'antenne 0,5 dB / 20 dB + poste NF 16 | 2,3 dB | 199 K | 449 K | %bar:1.9:17.6:y%1,9 dB",
                "| **LNA à l'antenne 0,5 dB / 20 dB + poste NF 3** | **0,6 dB** | 41 K | 291 K | %bar:0:17.6:g%{g:**référence**}",
                "~ §T_{sys} = T_{ant}§ 250 K + §T_e§ ; la comparaison est faite avec le même signal à l'antenne.",
                "@fine",
                "Pour la meilleure configuration, avec les valeurs remplacées :",
                "= F_{tot} = 1.1220 + \\frac{1.4454 − 1}{100} + \\frac{1.9953 − 1}{100 · 0.6918} = 1.1220 + 0.0045 + 0.0144 = 1.1409 \\quad ⇒ \\quad NF = 0.57 \\t{ dB}",
                ">! **En pratique.** Le préampli doit être monté à l'antenne, avant le câble de descente et juste après le relais coaxial (qui doit le protéger pendant l'émission grâce à un séquenceur). Son gain doit être assez élevé pour rendre le câble et le poste négligeables : en règle générale, au moins 10 dB de plus que la somme de l'affaiblissement du câble et du facteur de bruit du poste (dans l'exemple 1,6 + 16 ≈ 18 dB → avec 20 dB le poste pèse encore 1,7 dB ; avec le préampli interne en service il ne pèse que 0,05 dB). Un gain trop élevé réduit toutefois la dynamique du poste : avec un bon LNA à l'antenne il vaut souvent mieux laisser le préampli interne hors service et choisir un LNA de 20 – 26 dB. Dans le bilan EME ces choix se font dans le schéma de l'installation de réception, et l'onglet DEBUG FORMULE montre le calcul pas à pas.",
                "##+ Le transverter (facultatif)",
                "Avec un transverter le poste travaille sur une fréquence intermédiaire (généralement 28 MHz pour 144 MHz) et le transverter devient l'étage qui compte pour le bruit : il entre dans la formule de Friis après le câble de descente, et le poste qui le suit pèse d'autant moins que le transverter a de gain.",
                "= F_{comb} = F_{XV} + \\frac{F_{radio} − 1}{G_{XV}} \\quad \\t{e.g. } F_{comb} = 1.2589 + \\frac{10 − 1}{50.12} = 1.4385 ⇒ NF = 1.58 \\t{ dB}",
                "~ exemple : transverter avec NF 1,0 dB et gain 17 dB (valeurs minimales du DEMI L144-28) devant un poste HF avec NF 10 dB.",
                "@colonne 56",
                "#### Abaque : NF de l'ensemble en fonction du poste et du gain du transverter",
                "@abaco Courbes calculées avec (3.7.3) pour un transverter avec NF 1,0 dB. Plus le transverter a de gain, moins le poste pèse : avec 25 dB de gain un poste avec 20 dB de NF porte le total à 2,0 dB ; avec 10 dB de gain le même poste porte le total à 10,5 dB.",
                "@destra",
                "#### Transverters pour 144 MHz (FI 28 MHz)",
                "|h| Fabricant · modèle | >NF | >G RX | >TX | Source",
                "| DEMI L144-28 | < 1,0 dB | ≥ 17 dB | 25 / 50 W | [6]",
                "|+ **Kuhne (DB6NT) MKU 144 G2** (module) | 0,9 dB | 25 dB | 0,1 W¹ | [13]",
                "| Kuhne (DB6NT) TR 144 H +40 | 0,9 – 1,2 dB | 25 dB | 2 – 20 W | [7]",
                "| Kuhne (DB6NT) TR-144 Pro | {r:n.d.} | {r:n.d.} | 25 W | [8]",
                "| Q5 Signal L144-28M | < 1,0 dB | ≥ 20 dB | 25 / 75 / 150 W | [9]",
                "| HA1YA ME2T-PRO-II / ME2HT-PRO-II | 1,0 dB | ≤ 25 dB (réglable) | 30 / 50 W | [10]",
                "| SSB-Electronic LT2S Mk II | {r:n.d.} | {r:n.d.} | – | [11]",
                "~ Valeurs déclarées par les fabricants. MKU 144 G2 : premier étage avec NF 0,5 dB, IP3 de sortie en réception +23 dBm, entrée FI 2 – 50 mW ou 60 – 2000 µW ; ¹ excitateur de 100 mW, à compléter par un amplificateur Kuhne de 60 ou 120 W. TR 144 H +40 : il contient le module MKU 144 G2, d'où le gain de 25 dB (information de IC8TEM). Avec 25 dB de gain, devant un poste avec NF 10 dB le total est de 0,99 dB, avec NF 20 dB il est de 1,88 dB [13]. Le manuel Kuhne indique 1,2 dB dans le tableau et 0,9 dB dans le texte ; avec le préampli Kuhne MKU LNA 144 A le total descend à 0,3 dB [7]. Q5 Signal L144-28M : NF maximal 1,0 dB avec gain de conversion minimal 20 dB, gain RX-FI réglable par l'utilisateur pour étalonner le S-mètre ; FI jusqu'à 25 W [9]. HA1YA ME2T-PRO-II : NF global 1 dB (premier étage PGA103+ avec NF 0,7 dB), gain RX réglable jusqu'à 25 dB, OIP3 typique +35 dBm, IIP3 typique +10 dBm, réjection de la fréquence image > 80 dB, entrée FI de −20 à +37 dBm [10].",
                "#### Combinaisons mesurées (DF9IC, 144 MHz)",
                "|h| Poste + transverter | Préampli du poste | >NF",
                "| Elecraft K2 + Kuhne TR144H+40 | – | 1,0 dB",
                "| IC-756PRO II + Kuhne TR144H | off | 1,0 dB",
                "| IC-746 + Kuhne TR144H+40 | off | 1,2 dB",
                "| FT-1000MP + Javornik (deux exemplaires) | off | 0,9 · 1,4 dB",
                "| FT-1000 Mark V + Kuhne TR144H, FI 14 MHz | off | 1,6 dB",
                "| FT-1000 Mark V + Kuhne TR144H, FI 28 MHz | off / on | 6,0 / 1,7 dB",
                "| TS-870 + Javornik | off | 1,9 dB",
                "| Elecraft K2 + XV144 | on | 6,0 dB",
                "~ Source [3]. Le cas du FT-1000 Mark V à 28 MHz illustre l'abaque en pratique : avec le préampli du poste hors service le poste pèse beaucoup (6,0 dB), avec le préampli en service on descend à 1,7 dB.",
                "@fine",
                "##+ Stations EME avec FT-1000MP et transverter",
                "Deux exemples documentés de FT-1000MP utilisé en EME sur 144 MHz avec un transverter : les mesures de DF9IC [3] sur FT-1000MP + transverter Javornik (NF 0,9 – 1,4 dB avec le préampli du poste hors service) et la station EME de **W3SZ** [12] (4 × M2 2MXP32, préamplis LNA Technology à l'antenne pour chaque polarisation, LMR-600 et hardline Andrew), qui en émission utilise un **FT-1000MP Mark V** avec un transverter **SSB-Electronic LT2S Mk II** (FI 28 MHz) et un amplificateur 2 × GU-74B, tandis qu'en réception elle utilise le matériel WSE et le logiciel Linrad de SM5BSZ.",
                "> Dans le bilan EME le transverter est un bloc du schéma de la station : on l'active avec sa case à cocher, on choisit le modèle dans la liste (ou « custom ») et le programme reprend son facteur de bruit et son gain ; désactivé, il n'entre pas dans le calcul. L'abaque ci-dessus aide à décider s'il faut mettre en service le préampli du poste.",
                ">! ✉ **Vous connaissez un autre transverter ou vous en avez construit un ?** Si vous souhaitez faire connaître d'autres transverters ou votre propre transverter, écrivez un e-mail à l'auteur : ccerrotta@gmail.com ou ic8tem@gmail.com. Toutes les coordonnées se trouvent dans l'onglet **AUTHOR CONTACTS AND ACKNOWLEDGEMENTS**.",
                "##+ Le séquenceur TX/RX",
                "Avec un amplificateur de puissance (PA) et un préampli près de l'antenne (PRE), le PTT de l'ordinateur ne va pas au poste mais à un **séquenceur**, qui commande les relais puis le PA et le poste dans le bon ordre [16]. Le schéma le plus courant comporte deux descentes : celle de réception peut perdre quelques dB, car elle se trouve après un préampli de 15 – 20 dB, tandis que celle d'émission doit perdre le moins possible (3 dB en émission divisent par deux la puissance rayonnée). Au repos, les relais tiennent le PRE isolé de l'antenne : une protection de plus contre les décharges orageuses [16].",
                "|h| ^Étape | De RX à TX | De TX à RX",
                "| ^1 | les relais commutent à froid : poste → entrée du PA, antenne → sortie du PA, PRE isolé | le poste cesse d'émettre",
                "| ^2 | le PA est mis en marche | le PA est arrêté",
                "| ^3 | le poste passe en émission | les relais reviennent en réception, sans puissance en jeu",
                "~ Entre deux étapes il faut au moins le temps de commutation des relais (15 – 30 ms) plus leurs rebonds : IK1UWL conseille 100 – 200 ms, y compris pour le PA s'il a des relais internes [16].",
                "Pour la commande d'émission, le PTT vaut mieux que le VOX : le VOX peut se déclencher sur un bruit et ne profite pas du retard d'environ 0,5 s avec lequel JT65 commence à moduler après le PTT, de sorte que le préampli n'est protégé que par le relais rapide de l'amplificateur ; avec le PTT, ce retard commute l'amplificateur avant la modulation et l'on peut ajouter le séquenceur [17].",
                ">! **Attention au préampli.** Le relais T/R doit très bien isoler la voie ouverte : avec 50 dB d'isolation et 500 W à l'antenne, 5 mW arrivent à l'entrée du PRE. On vise au moins 60 dB, et les plus prudents ajoutent un second relais qui, en émission, ferme le PRE sur une charge de 50 Ω. Le bouton PTT du micro doit être désactivé : dès lors on n'émet plus qu'à travers le séquenceur (en SSB, une pédale sur le PTT du séquenceur, découplée de celle du PC) [16].",
                "[1] Adam Farson VA7OJ/AB4OJ, “Icom IC-9700 Test Report”, édition 5, 19 mars 2021 (première édition 19 juin 2019), tableaux 1 et 5 – https://www.qsl.net/ab4oj/icom/ic9700/9700notes.pdf",
                "[2] Adam M. Farson VA7OJ/AB4OJ, “Yaesu FT-991 Test Report”, 25 juillet 2015, tableau 1 – https://www.qsl.net/ab4oj/test/docs/ft991notes.pdf",
                "[3] DF9IC avec le DARC OV Durlach A35, “Test of the Large Signal Behaviour of some 144 MHz Radios”, essais du 27 février 2005 – https://www.df9ic.de/tech/trxtest/trxtest.html",
                "[4] H. T. Friis, “Noise Figures of Radio Receivers”, Proceedings of the IRE, vol. 32 (1944).",
                "[5] Essai préliminaire “ICOM IC-9100 review” sur un exemplaire de présérie prêté par Icom UK (auteur et date non indiqués) – https://manualmachine.com/icom/ic9100/26837637-review",
                "[6] Down East Microwave, “L144-28 Rev B” – guide d'utilisation (caractéristiques : NF < 1,0 dB avec gain de conversion ≥ 17 dB) – https://manualmachine.com/demi/l14428revb/26842141-user-guide",
                "[7] Kuhne electronic, “TR 144 H +40” – manuel d'utilisation – https://manuals.online/kuhne-electronic/transceiver/tr-144-h-40/user-manual/191pa",
                "[8] RigPix, “Kuhne TR-144 Pro” – https://rigpix.com/transverters/kuhne_tr144pro.htm",
                "[9] Q5 Signal, “VHF/UHF Transverters – L144-28M REV 2”, manuel (8 pages), janvier 2023, fourni par IC8TEM – http://q5signal.com/image/catalog/L144-28Mr2.pdf",
                "[10] HA1YA (Mechanics & Electronics), “ME2T-PRO-II & ME2HT-PRO-II 144MHz Transverter”, 25.09.2023, fourni par IC8TEM – http://www.ha1ya.hu/pdf/me2tpro2transverter.pdf",
                "[11] SSB-Electronic LT2S Mk II – cité dans [12]",
                "[12] Roger Rehr W3SZ, description de la station EME – https://w3sz.com/EMEFrame1Source1.htm",
                "[13] Kuhne electronic GmbH, “MKU 144 G2 – Transverter module, 144 … 146 MHz, 28 … 30 MHz IF”, fiche technique (2 pages), fournie par IC8TEM",
                "[14] ARRL Laboratory, “Icom IC-746PRO”, QST Product Review, mai 2002 – https://www.radiomanual.info/schemi/ICOM_HF/IC-746Pro_review_ARRL_2002.pdf",
                "[15] Peter Hart G3SJX, “The Yaesu FT-897 HF/VHF/UHF Transceiver”, RadCom (RSGB), avril 2003, pp. 18–20 – http://www.radiomanual.info/schemi/YAESU_HF/FT-897_review2_2003.pdf",
                "[16] Giorgio Marchi IK1UWL, “EME (Earth-Moon-Earth) – Guida operativa”, janvier 2012, § 4 “Sequenziamento relè, PA e PRE”, fourni par IC8TEM – http://www.qsl.net/ik3xtv",
                "[17] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, présentation, juillet 2015, fournie par IC8TEM."
            };
            d["fr"]["S48"] = new string[] {
                "## Câbles coaxiaux et pertes",
                "L'onglet **COAXIAL CABLES** rassemble l'affaiblissement des câbles 50 Ω les plus utilisés par les radioamateurs, en dB pour 100 m à 20 °C, sur les cinq bandes de YAEC. Les fiches techniques des fabricants donnent des valeurs à des fréquences différentes ; YAEC les a ramenées aux bandes avec la loi de puissance, une droite sur le graphique log-log entre les deux fréquences les plus proches de la fiche technique :",
                "= α(f) = α_1 · \\p{\\frac{f}{f_1}}^{n} \\quad n = \\frac{log \\p{α_2 / α_1}}{log \\p{f_2 / f_1}} \\quad L = α(f) · \\frac{ℓ}{100}",
                "~ α en dB/100 m, ℓ longueur du câble en mètres. Un nombre simple est la valeur de la fiche technique ; ≈ signale une valeur interpolée, et e une valeur extrapolée au-delà de la dernière fréquence de la fiche technique.",
                "Les câbles du même type, de même diamètre à ±0,2 mm près et d'affaiblissement à 0,2 dB/100 m près sur toutes les bandes sont regroupés sur une seule ligne (≡), avec la valeur moyenne ; les noms équivalents sont indiqués avec « also: » (par exemple LMR-400 = HF400, CNT-400, 50-7 low loss ; LMR-600 = CNT-600). Les noms chinois 50-3, 50-5, 50-7, 50-9, 50-12 donnent le diamètre du diélectrique en millimètres.",
                "> On peut ajouter des câbles personnels avec leurs cinq affaiblissements : ils sont enregistrés dans data\\cavi_personali.txt et apparaissent aussi dans les listes déroulantes du schéma de la station du bilan EME. L'infobulle de chaque ligne du tableau cite la source de ce câble.",
                "[1] Les sources des différents câbles : fiches techniques de Times Microwave (LMR), RFS (CELLFLEX LCF/SCF), CommScope Andrew (HELIAX LDF/FSJ), Siva Cavi (HF 240/287/400), SSB-Electronic (Aircell, Ecoflex, Aircom Plus), Messi & Paoloni (Hyperflex, Ultraflex, via WiMo), Symair, SYV50-7 (szansy.com), Belden (H1000), Prospecta (RT5020, XT2400), QAXIAL (LLF195), Caledonian Cables, catalogue MIL-C-17F (RG-142, RG-393), R.F. elettronica de Senago (RG-115), les tables de DD1US et EA5IP (H100) et la table de SV1BSX pour RG-58, RG-213, H-155 et H-2000 (valeurs à vérifier)."
            };
            d["fr"]["S410"] = new string[] {
                "## Doppler, compensation et CFOM",
                "La Lune s'approche et s'éloigne des deux stations à cause de la rotation de la Terre et de son propre mouvement orbital : la distance R varie de quelques centaines de mètres par seconde et le signal revient décalé en fréquence. Le décalage est maximal quand la Lune se lève ou se couche, passe par zéro quand elle transite au sud (ou au nord) et est proportionnel à la fréquence. YAEC le calcule chaque seconde sur l'écran principal, dans la carte **Echo and frequencies (CFOM)**.",
                "### Quelle est l'ampleur du Doppler",
                "Pour l'écho de sa propre station le trajet est parcouru deux fois (aller et retour) :",
                "= f_{D,echo} = − \\frac{2f}{c} · \\frac{dR}{dt} \\quad \\t{e.g. } − \\frac{2 · 144.120 · 10^6}{299 792} · 0.222 = −213 \\t{ Hz}",
                "avec f la fréquence en Hz, c = 299 792 km/s et dR/dt la vitesse radiale de la Lune en km/s (positive quand elle s'éloigne). Pour le signal du DX on compte les deux branches, la sienne et la vôtre :",
                "= f_{D,DX} = − \\frac{f}{c} · \\p{\\frac{dR_{me}}{dt} + \\frac{dR_{DX}}{dt}} \\quad \\t{e.g. } −480.7 · \\p{0.222 − 0.339} = +56 \\t{ Hz}",
                "~ exemple : Tokyo PM95 et Le Cap JF96, 06/11/2026 01:55 UTC, 144,120 MHz ; dR/dt = +0,222 km/s à Tokyo et −0,339 km/s au Cap (valeurs YAEC).",
                "@colonne 62",
                "|h| Bande | >Doppler maximal de l'écho | >Compensation",
                "| 50 MHz | ≈ ±120 Hz | inutile",
                "| 70 MHz | ≈ ±165 Hz | inutile",
                "| 144 MHz | jusqu'à ≈ 340 Hz [1] | conseillée",
                "| 222 MHz | ≈ ±525 Hz | nécessaire",
                "| 432 MHz | jusqu'à ≈ 1000 Hz [1] | nécessaire",
                "~ Valeurs pour 144 et 432 MHz tirées de [1] ; 50, 70 et 222 MHz déduites proportionnellement à la fréquence (≈ = déduit).",
                "@destra",
                "> Sur 50 et 144 MHz le Doppler reste presque toujours dans la chute d'eau (waterfall) du programme numérique et le décodeur le trouve tout seul ; sur 432 MHz il peut faire sortir le signal de la bande passante, et pendant une période de 60 s il varie de quelques hertz, assez pour ressembler à une dérive dans les modes lents [2].",
                "@fine",
                "### Compenser : qui corrige quoi",
                "Compenser le Doppler signifie décaler la fréquence d'émission, celle de réception ou les deux, afin que les signaux se rencontrent sur la fréquence convenue (le *sked*). Chaque station corrige son propre Doppler et, quand elle contacte un DX, aussi celui du DX [1] :",
                "|h| Situation | Émission | Réception",
                "| Appel CQ et écoute de son propre écho | sur la fréquence du sked | sked + Doppler de l'écho (3.10.1)",
                "| QSO avec un DX connu (Doppler complet vers le DX) | corrigée pour que le DX vous reçoive sur le sked | sked + Doppler DX → moi (3.10.2)",
                "| CFOM, fréquence constante sur la Lune | sked − la moitié de son propre Doppler | sked + la moitié de son propre Doppler",
                "### CFOM – Constant Frequency On Moon",
                "Avec le CFOM toutes les stations se comportent comme si un émetteur virtuel sur la Lune était accordé sur le sked : chacune ne corrige que la moitié de son **propre** Doppler en émission et la moitié en réception, sans avoir besoin de connaître le locator de l'autre station [2] :",
                "= f_{TX} = f_{sked} − \\frac{f_{D,echo}}{2} \\quad f_{RX} = f_{sked} + \\frac{f_{D,echo}}{2}",
                "|h| Exemple (Tokyo, Doppler de l'écho −213 Hz) | >Fréquence",
                "| Sked | 144,120000 MHz",
                "| Émission sur (sked + 106,5 Hz) | {r:**144,120107 MHz**}",
                "| Réception sur (sked − 106,5 Hz) | {g:**144,119894 MHz**}",
                "L'avantage est que plusieurs stations, et quiconque se contente d'écouter, peuvent suivre un QSO sur la même fréquence sans recalculer le Doppler pour chacune. YAEC affiche ces deux fréquences sur l'écran principal.",
                "### Le CAT du poste",
                "Le Doppler varie en permanence, donc la compensation doit être mise à jour à chaque période. Le plus simple est de la confier au programme numérique (par exemple la fenêtre *Astronomical Data* de WSJT-X) qui, par le **CAT** du poste, règle les VFO d'émission et de réception et maintient le poste sur la bonne fréquence [1] [2]. Sans CAT on peut utiliser le split (un VFO pour l'émission et un pour la réception) ou le RIT, en corrigeant à la main à chaque période : sur 50 et 144 MHz c'est faisable, sur 432 MHz cela devient malcommode [1].",
                "> Attention : pour le CFOM le poste doit accepter le changement de fréquence par CAT **même pendant l'émission**. Certains appareils ne le font pas (par exemple le FT-897 cité dans [2]) : dans ce cas on peut tout de même recevoir en CFOM, tandis que l'émission reste sur une fréquence fixe. Avec un transverter (§ 3.7) le CAT règle le poste sur la fréquence intermédiaire : indiquez le décalage du transverter dans le programme, afin que la fréquence affichée soit la fréquence réelle.",
                "[1] Bob Atkins KA1GT, “Doppler 101 for 1296 MHz EME (…and other bands)” (seules les données jusqu'à 432 MHz sont reprises de l'article) – https://bobatkins.com/radio/EME_doppler_101.html",
                "[2] Bob Atkins KA1GT, “CFOM – Constant Frequency On Moon Doppler Mode” – https://bobatkins.com/radio/CFOM.html"
            };
            d["fr"]["S411"] = new string[] {
                "## Pointage : précision, codeurs et actionneurs",
                "YAEC calcule l'azimut et l'élévation de la Lune au centième de degré, mais le signal n'arrive que si l'antenne la suit réellement. Plus le lobe est étroit, plus la précision mécanique du pointage compte : sur les bandes de YAEC (50 – 432 MHz) un bon rotor suffit, tandis que les paraboles des bandes plus hautes demandent un véritable système d'actionnement.",
                "### Combien on perd en pointant mal",
                "Avec une erreur de pointage Δ et une ouverture à mi-puissance θ (estimée par YAEC avec §θ ≈ \\sqrt{41253/G}§), la perte est approchée par la formule du lobe gaussien :",
                "= L_{point} ≈ 12 · \\p{\\frac{Δ}{θ}}^2 \\t{ dB} \\quad \\t{e.g. } 12 · \\p{\\frac{3.6}{14.4}}^2 = 0.75 \\t{ dB}",
                "~ exemple : 4 yagis de 17 dBi sur 144 MHz, gain total 23 dBi, θ ≈ 14,4° ; une erreur d'un quart du lobe (3,6°) coûte environ 0,75 dB. En EME la perte se paie deux fois, en émission et en réception. Formule approchée, valable pour des erreurs petites par rapport au lobe.",
                "### Résolution du codeur",
                "La position de l'antenne est lue par un codeur (ou par un potentiomètre converti en numérique) : avec n bits le tour complet est divisé en §2^n§ pas et le plus petit pas est",
                "= Δ = \\frac{360°}{2^n} \\quad \\t{e.g. } n = 10: \\frac{360°}{1024} = 0.35°",
                "|h| ^Codeur | >Pas par tour | >Pas | >Perte avec le groupement de 4 yagis (θ 14,4°, erreur de 1 pas) | Adapté à",
                "| 8 bits | 256 | 1,406° | 0,114 dB | groupements de yagis sur 50 et 144 MHz",
                "| 10 bits | 1 024 | 0,352° | 0,007 dB | 144 MHz avec marge, 432 MHz avec petits groupements",
                "| 12 bits | 4 096 | 0,088° | < 0,01 dB | 432 MHz avec grands groupements",
                "| 14 bits | 16 384 | 0,022° | < 0,01 dB | paraboles à 10 et 24 GHz [1]",
                "| 16 bits | 65 536 | 0,005° | < 0,01 dB | au-delà : limite fixée par la mécanique, non par le codeur",
                "~ Pas et perte calculés avec (3.11.2) et (3.11.1). Une règle pratique est de garder l'erreur sous un dixième du lobe : le groupement de 4 yagis sur 144 MHz se contente de 8 bits, une parabole de 3 m à 10 GHz (lobe ≈ 0,7°) demande au moins 13 – 14 bits.",
                "> Le nombre de bits dit seulement avec quelle finesse la position est *lue* : la précision réelle dépend aussi du jeu mécanique, de la flexion du support, du vent et de l'étalonnage du nord et de l'horizon.",
                "### Groupements de yagis : actionneurs et poulies",
                "Dans les groupements de yagis (combinaisons de 2, 4 antennes ou plus) la charge en élévation est importante et déséquilibrée. On trouve dans le commerce des vérins linéaires à moteur et vis sans fin : dans ces solutions la vis ne fait que régler le mouvement, tandis que le soutien mécanique de la charge est confié à des poulies. La vis sans fin a l'avantage de ne pas tourner à l'envers sous la charge, si bien que le groupement reste immobile même moteur arrêté.",
                "### Au-delà de 432 MHz : les paraboles",
                "À partir de 902 MHz on utilise surtout des paraboles, et l'outil [1] est conçu pour les fréquences à partir de 1 GHz. Avec de grands diamètres le lobe se rétrécit à quelques dixièmes de degré et l'on risque de ne pas viser parfaitement la Lune : plus que de moteurs, la station a besoin de véritables actionneurs mécaniques en azimut et en élévation, avec une précision de pointage largement liée à la résolution en bits de la commande. L'**EME Link Budget & Analysis Tool** de OE2IGL et DF3GJ [1] indique ±0,035° pour un bon système de poursuite et ±0,1° pour un système normal, et calcule la perte de pointage avec tous les autres termes de la liaison.",
                ">+ YAEC s'arrête à 432 MHz. Pour les bandes plus hautes nous conseillons l'outil de OE2IGL et DF3GJ [1] : il calcule le bilan EME de 1 à 300 GHz avec les paramètres de la parabole (diamètre, f/D, source, rugosité de surface, rendements), le pointage, la libration, le bruit du Soleil et de la Lune et l'affaiblissement atmosphérique.",
                "[1] Gerald Ihninger OE2IGL et Joachim Köppen DF3GJ, “EME Link Budget & Analysis Tool (1-300 GHz)” – https://wettersat.bplaced.net/EME/EME.html"
            };
            d["fr"]["S412"] = new string[] {
                "## Modes numériques pour l'EME : Q65 et JT65",
                "Le bilan EME (§ 3.6) affiche le S/N estimé à côté du seuil typique du mode numérique choisi. Cette section explique d'où viennent les seuils de **Q65**, comment le signal est construit et pourquoi Q65 a aujourd'hui largement remplacé JT65 pour l'EME sur les bandes de YAEC. Les données proviennent de trois documents : le guide de démarrage rapide des auteurs de Q65 [1], la comparaison JT65A – Q65-60A de K1JT [2] et l'étude du processus de codage de G4JNT [3].",
                "### Qu'est-ce que Q65",
                "Q65 a été introduit avec WSJT-X 2.4.0 par K1JT, G4WJS, K9AN et IV3NWV pour des QSO minimaux sur des trajets particulièrement difficiles ; quand l'étalement Doppler dépasse quelques hertz c'est le plus sensible des modes de WSJT-X, et il convient à la troposcatter, au rain scatter, à la diffusion ionosphérique, à la TEP et à l'EME à partir de la VHF [1]. Il utilise une FSK à **65 tons** et dérive de QRA64 de 2016 ; par rapport à celui-ci, il introduit [1] :",
                "• un nouveau code correcteur d'erreurs Q-ary Repeat Accumulate à faible débit, proposé par Nico Palermo IV3NWV [3] [4] ;",
                "• des messages et un séquencement identiques à FST4, FT4, FT8 et MSK144 ;",
                "• un ton de synchronisation bien visible sur la chute d'eau et une « courbe de synchro » sensible, efficace même avec les pings de météores ;",
                "• des sous-modes avec des périodes T/R de 15, 30, 60, 120 et 300 s et différents espacements des tons ;",
                "• le décodage par liste pour les messages contenant des parties déjà reçues, **sans base de données d'indicatifs** ;",
                "• le moyennage des messages, quand les émissions isolées sont trop faibles, et le décodage multiple sur toute la bande reçue.",
                "### Les sous-modes",
                "Le nom du sous-mode associe la période T/R et une lettre pour l'espacement des tons : Q65-60A, Q65-120C et ainsi de suite. Pour les sous-modes A le tableau donne les seuils mesurés par simulation sur un canal à bruit blanc gaussien additif (AWGN), sous forme de S/N dans 2500 Hz avec une probabilité de décodage de 50 %, sans et avec l'information *a priori* (AP) maximale [1].",
                "|h| >T/R (s) | >Symbole (s) | >Espacement A (Hz) | >Bande A (Hz) | >Émission (s) | >S/N (dB) | >S/N AP max (dB)",
                "| 15 | 0,150 | 6,667 | 433 | 12,8 | −22,2 | −23,7",
                "| 30 | 0,300 | 3,333 | 217 | 25,5 | −24,8 | −26,6",
                "| 60 | 0,600 | 1,667 | 108 | 51,0 | −27,6 | −30,2",
                "| 120 | 1,333 | 0,750 | 49 | 113,3 | −30,8 | −32,5",
                "| 300 | 3,456 | 0,289 | 19 | 293,8 | −33,8 | −37,4",
                "~ Données de [1]. Les sous-modes B, C, D et E ont un espacement des tons et une bande occupée 2, 4, 8 et 16 fois ceux du sous-mode A ; toutes les combinaisons n'existent pas (par exemple 15D et 30E n'existent pas) [1].",
                "Les nombres du tableau découlent de quelques relations, vérifiées par YAEC par rapport aux valeurs de [1] : l'espacement A est l'inverse de la durée du symbole, l'émission dure 85 symboles et la bande occupée vaut 65 espacements.",
                "= Δf = \\frac{k}{t_s} \\quad k = 1, 2, 4, 8, 16 \\t{ (A … E)} \\quad T_{tx} = 85 · t_s \\quad B_{occ} = 65 · Δf",
                "~ exemple Q65-60A : §t_s§ = 0,600 s → Δf = 1,667 Hz, §T_{tx}§ = 51,0 s, §B_{occ}§ = 108 Hz. En passant de 60 à 120 s le seuil s'améliore de 3,2 dB, proche des 10 · log(113,3 / 51,0) = 3,5 dB attendus de l'émission plus longue.",
                "### Sensibilité et étalement Doppler",
                "Les seuils du tableau valent sans étalement du signal. En EME la Lune étale chaque ton de quelques hertz (étalement Doppler, ou *libration fading*), et le seuil se dégrade. D'après le graphique de [1] pour Q65-60A sans AP :",
                "|h| >Étalement Doppler (Hz) | >S/N à 50 % (dB) | >Perte (dB)",
                "| 0 | ≈ −27,4 | –",
                "| 5 | ≈ −25,6 | ≈ 1,8",
                "| 10 | ≈ −24,6 | ≈ 2,8",
                "| 20 | ≈ −23,2 | ≈ 4,2",
                "~ Valeurs lues par YAEC sur la figure 2 de [1] en interpolant entre les points (≈ = déduit). Le décodage reste efficace jusqu'à un étalement d'environ dix fois l'espacement des tons, et même au-delà [1] : c'est pourquoi on choisit les sous-modes de lettre plus élevée pour les étalements plus importants.",
                "> Dans YAEC les seuils de référence sont sans étalement et sans AP : ils servent à comparer des jours, des bandes et des stations. Si sur votre trajet le signal est fortement étalé, tenez compte de la perte du tableau, ou choisissez le mode *custom* avec le seuil corrigé.",
                "### Les messages du QSO à 60 s : Q65-60A, Q65-60B et Q65-60C",
                "Dans un QSO minimal, les six messages standard de WSJT-X (TX1 … TX6) ne sont pas tous reçus de la même façon : le décodeur peut utiliser les parties déjà connues (décodage *a priori*, AP), et la quantité d'information connue augmente au cours du QSO [1]. Le tableau compare les trois sous-modes les plus utilisés en EME avec la même période de 60 s.",
                "|h| Message | Exemple | >AP en réception | >Q65-60A | >Q65-60B | >Q65-60C",
                "| TX6 – appel | CQ W9XYZ EN37 | >q1 | >−27,6 · AP : n.d. | >−27,6 · AP : n.d. | >−27,6 · AP : n.d.",
                "| TX1 – réponse avec locator | W9XYZ K1ABC FN42 | >q2 | >−27,6 · AP : n.d. | >−27,6 · AP : n.d. | >−27,6 · AP : n.d.",
                "| TX2 – report | K1ABC W9XYZ −25 | >q3 | >−27,6 · AP : n.d. | >−27,6 · AP : n.d. | >−27,6 · AP : n.d.",
                "| TX3 – R et report | W9XYZ K1ABC R−26 | >q3 | >−27,6 · AP : n.d. | >−27,6 · AP : n.d. | >−27,6 · AP : n.d.",
                "| TX4 – confirmation | K1ABC W9XYZ RRR | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| TX5 – salutations | W9XYZ K1ABC 73 | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| Espacement des tons | – | – | >1,667 Hz | >3,333 Hz | >6,667 Hz",
                "| Bande occupée | – | – | >108 Hz | >217 Hz | >433 Hz",
                "| Étalement encore décodable (≈ 10 × espacement) | – | – | >≈ 17 Hz | >≈ 33 Hz | >≈ 67 Hz",
                "| Avec 5 Hz d'étalement Doppler, sans AP | – | – | >≈ −25,6 | >perte moindre (n.d.) | >perte moindre (n.d.)",
                "~ S/N en dB rapporté à 2500 Hz, probabilité de décodage de 50 %. −27,6 dB sans AP et −30,2 dB avec l'AP maximale sont les valeurs du Q65-60A dans [1] ; pour les sous-modes B et C elles sont déduites de la théorie : sans étalement, la sensibilité dépend de la durée du symbole (0,600 s), identique dans les trois sous-modes, et non de l'espacement. « n.d. » = non disponible : [1] ne donne que le gain maximal de l'AP (2,6 dB à 60 s), pas celui des niveaux q1, q2 et q3, qui est moindre. Indicateurs q1 … q4 comme dans le tableau du § « Réglages conseillés dans WSJT-X » ; étalement décodable et valeur à 5 Hz d'après [1] et le tableau de l'étalement Doppler ci-dessus. K1ABC, W9XYZ et les locators sont des exemples.",
                ">! Ce tableau comparatif est dérivé de l'analyse des données en notre possession sur la théorie de fonctionnement du Q65, et ne reflète en rien ce qui se passe réellement, à cause du bruit naturel et anthropique (d'origine humaine) capté en direct pendant la réception.",
                "### Quel sous-mode pour l'EME",
                "Pour les bandes de YAEC les sous-modes conseillés dans [1] sont :",
                "|h| Usage | Sous-mode",
                "| EME sur 50 et 144 MHz | Q65-60A",
                "| EME sur 432 MHz | Q65-60B",
                "| Diffusion ionosphérique sur 50 MHz | Q65-30A",
                "| Diffusion ionosphérique à faible puissance sur 50 MHz | Q65-120E",
                "| TEP sur 50 MHz | Q65-15C, Q65-30C",
                "| Diffusion ionosphérique sur 144 MHz | Q65-60C",
                "~ D'après [1], seulement pour les bandes jusqu'à 432 MHz. Les auteurs encouragent à expérimenter d'autres combinaisons.",
                "La période de 30 s double le rythme des QSO avec des signaux relativement forts, la période de 120 s gagne environ 3 dB par émission isolée [2].",
                "### Q65 et JT65 comparés",
                "**JT65A** a été le mode EME de la bande des 6 mètres pendant près de vingt ans : avec le décodage *Deep Search* il atteint −28 dB dans 2500 Hz (−29 dB avec le moyennage des messages, § 3.6), environ 15 dB sous le niveau nécessaire pour lire la CW à l'oreille, mais seulement pour les stations figurant dans la base de données CALL3.TXT d'indicatifs et de locators. Dans ces QSO on transmet en réalité très peu d'information : environ 14 bits pour un indicatif et un locator choisis dans la base, plus un report de 1 bit et un accusé de réception de 1 bit [2].",
                "**Q65** transmet toujours des messages de 78 bits : même un QSO minimal contient un indicatif quelconque (29 bits), un vrai report numérique (7 bits) et l'accusé de réception (1 bit), sans base de données [2]. K1JT a préparé dix fichiers simulés avec des signaux à −29 dB et un étalement Doppler de 1 Hz, cinq JT65A et cinq Q65-60A par fichier, et a essayé de les décoder de quatre façons, avec 50 décodages possibles par essai [2] :",
                "|h| Essai | Mode | Indicatif et locator du DX | Deep Search | >Bons | >Faux",
                "| 1 | JT65A | inconnus | non disponible | 0 | 0",
                "| 2 | JT65A | inconnus | oui (DX dans CALL3.TXT) | 28 | 1",
                "| 3 | Q65-60A | inconnus | – | 24 | 0",
                "| 4 | Q65-60A | connus (DX Call et DX Grid) | – | 49 | 0",
                "~ D'après [2], tableau 1. Réglages JT65 : Deep, Deep Search, AP, 6 motifs d'effacement aléatoires, niveau agressif 9 ; Q65 : Fast, moyennage activé, effacement automatique de la moyenne.",
                "Les conclusions de l'auteur [2] : pour les réponses à son propre CQ, Q65-60A a, pour **n'importe quel** correspondant inconnu, à peu près la sensibilité que JT65A n'a que pour les correspondants présents dans la base ; pour tous les autres il est **au moins 3 dB** plus sensible, et davantage encore dans les messages suivants, quand les deux indicatifs sont connus. Les faux décodages sont si rares qu'ils sont difficiles à mesurer. Le moyennage des messages de JT65 fonctionne pour un seul correspondant déjà identifié, celui de Q65 sur toute la bande affichée. Enfin, JT65 consacre la moitié de l'énergie émise à la synchronisation, Q65 un quart.",
                "> La valeur de −25 dB pour JT65 dans le bilan EME est celle du guide de WSJT-X sans Deep Search (§ 3.6) ; les −28 dB avec Deep Search ne valent que pour les stations présentes dans la base de données, les −29 dB avec moyennage pour n'importe quel message.",
                ">! **Incohérence entre les sources.** Le document de comparaison JT65A – Q65-60A [2] indique −29 dB pour le JT65A avec Deep Search ; l'exposé de K1JT à la conférence EME 2006, cité au § 3.6, donne en revanche −28 dB pour le Deep Search et −29 dB pour le moyennage des messages. YAEC utilise les valeurs de 2006. Les deux sources se réfèrent à des sous-modes différents : JT65B dans les simulations de 2006, JT65A dans [2].",
                "### Comment Q65 construit le signal",
                "G4JNT a reconstitué à partir du code source de WSJT-X le chemin du message aux tons émis, en le vérifiant avec le programme Q65CODE.EXE de WSJT-X [3]. En résumé :",
                "• **Codage de source.** Comme dans FST4, FT8, FT4 et MSK144, le message devient 71 bits de données plus 6 bits de type, 77 en tout. Un texte libre compte jusqu'à 13 caractères d'un alphabet de 42 symboles (espace, chiffres, lettres et + - . / ?), et §42^{13}§ est inférieur à §2^{71}§ ; le mode télémétrie transporte jusqu'à 18 chiffres hexadécimaux [3].",
                "• **Symboles.** Avec un bit de plus, les 78 bits sont répartis en 13 symboles de six bits, de valeurs 0 à 63 [3] : la même longueur que les messages de 78 bits de [2].",
                "• **CRC.** Un contrôle de 12 bits (deux symboles), avec le polynôme 1100000001111 et les bits de chaque symbole inversés pour la compatibilité avec le travail de IV3NWV, sert à rejeter les faux décodages [3]. Avec le CRC on a 15 symboles.",
                "• **Parité.** Les 50 symboles de contrôle proviennent d'une matrice « génératrice » 15 × 50, avec une arithmétique dans le corps de Galois GF(64) : l'addition est un XOR, la multiplication se fait avec des tables de logarithmes et d'antilogarithmes [3].",
                "• **Code.** Le code est un code (65,15) à symboles de six bits ; les deux symboles du CRC sont « poinçonnés », c'est-à-dire non transmis, ce qui laisse un code effectif (63,13) [1] [3].",
                "• **Synchronisation.** 22 symboles de synchro, tous sur le ton 0, à des positions pseudo-aléatoires fixes, sont ajoutés aux 63 symboles ; 85 symboles sont émis, avec 65 tons : 0 pour la synchro, 1 à 64 pour les données [1] [3].",
                "= f_n = f_0 + n · Δf \\quad n = 0 … 64",
                "~ §f_0§ fréquence du ton 0, Δf espacement du sous-mode [3]. Avec 22 symboles de synchro sur 85, la synchronisation occupe environ un quart de l'émission, comme le note [2].",
                "### Réglages conseillés dans WSJT-X",
                "Pour l'EME en Q65 les auteurs conseillent, dans WSJT-X : *File → Settings → General* avec **Enable VHF and submode features** et **Decode after EME delay** activés et **Single decode** désactivé ; dans le menu *Decode* **Fast**, **Enable averaging** et **Auto Clear Avg after decode** [1]. Chaque décodage Q65 porte la lettre « q » et un ou deux chiffres : le premier indique l'information *a priori* utilisée, le second le nombre de séquences moyennées [1].",
                "|h| Indicateur | Information a priori utilisée",
                "| q0 | aucune",
                "| q1 | CQ",
                "| q2 | mon indicatif",
                "| q3 | mon indicatif et l'indicatif du DX",
                "| q4 | les deux indicatifs et RRR, RR73, 73 ou vide",
                "~ D'après [1]. Les auteurs recommandent de ne pas accorder trop d'attention aux valeurs de S/N affichées par le décodeur, qui étaient encore en cours d'amélioration [1] : pour les comparaisons avec le bilan EME de YAEC il vaut mieux utiliser plusieurs QSO plutôt qu'une seule lecture.",
                "### La procédure avec les DXpéditions (W7GJ)",
                "Lance Collister W7GJ, qui mène depuis des années des expéditions EME sur 6 m, décrit comment appeler une DXpédition en Q65-60A pendant un pile-up [6]. Avant tout, l'horloge de l'ordinateur doit être très précise et la fréquence d'émission très stable [6].",
                "• **Périodes.** La DXpédition émet toujours dans la première séquence (minutes paires) ; ceux qui appellent émettent dans la seconde (minutes impaires) [6].",
                "• **Fréquence.** Choisissez une fréquence libre dans la bande passante et restez-y : Q65 fait la moyenne des appels de chaque station sur sa propre fréquence, et si vous vous déplacez, le bénéfice de vos appels précédents est perdu. Laissez environ 100 Hz entre vous et les autres et vérifiez que le Doppler ne fait pas sortir votre signal de la bande passante du DX ; les stations qui appellent se coordonnent sur le chat EME d'ON4KST [6].",
                "• **Mode.** Utilisez la procédure de contest numérique du Q65-60A : dans WSJT-X, *File → Settings → Advanced*, l'une des options « Special Operating Activity » NA VHF, WW Digi ou ARRL Digi (après la version 2.6.1, aussi Q65 Pileup). Saisissez l'indicatif et le locator du DX dans DX Call et DX Grid, appuyez sur Generate Std Msgs et partez du message TX2, pas de CQ [6].",
                "• **Continuez d'appeler.** Sur 6 m, la propagation entre stations à polarisation linéaire est souvent non réciproque : le DX peut vous recevoir même si vous ne le recevez pas. N'arrêtez pas d'appeler et ne revenez pas à un message précédent si le DX est en QSO avec d'autres ou disparaît : chaque message contient les deux indicatifs et le QSO reprend là où il s'était arrêté. Avec Q65 Pileup, le DX a besoin d'au moins un décodage de votre signal à chaque passage de la Lune [6].",
                "• **RRR, jamais RR73.** En EME, utilisez toujours RRR : RR73 n'est envoyé qu'une fois et le QSO est enregistré même si l'autre station ne l'a pas reçu. Le QSO est complet quand l'une des deux stations reçoit le RRR final ; celle qui le reçoit répond 73 aussi longtemps que nécessaire, donc dans *Settings → Behavior* la case « Disable Tx after sending 73 » ne doit pas être cochée [6].",
                "• **Regardez l'écran.** Même si vous ne décodez pas le DX, sa trace sur la chute d'eau (Wide Graph) ou la pointe orange du Q65 vous indiquent que vous le recevrez probablement dès qu'il répondra. Effacez la moyenne à la main quand vous voyez qu'il a contacté quelqu'un d'autre : le prochain, ce pourrait être vous [6].",
                "|h| DX (première séquence, minutes paires) | Appelants (seconde séquence, minutes impaires)",
                "| CQ TX7MB CI00 | TX7MB OH2BC KP30",
                "| OH2BC TX7MB R CI00 | TX7MB OH2BC RRR",
                "| G8BCG TX7MB R CI00 | TX7MB G8BCG RRR",
                "| G8BCG TX7MB 73 | TX7MB G8BCG 73",
                "~ Exemple abrégé d'après [6], avec TX7MB (CI00) comme DXpédition : chaque station qui appelle reste sur sa propre fréquence et passe à RRR quand elle reçoit son propre « R CI00 ».",
                "> Les fenêtres lunaires communes sont courtes, surtout au lever et au coucher de la Lune, quand beaucoup de stations profitent de l'effet de sol : l'onglet Position en direct et +- 24h et l'onglet Distance et Dgrd montrent quand la Lune est visible des deux stations.",
                ">⚠ La discussion sur les limites théoriques perd son sens au moment où l'on reçoit effectivement les signaux : un bruit local soudain peut dégrader l'écoute, tout comme la rotation de Faraday (§ 3.3).",
                "[1] Joe Taylor K1JT, Bill Somerville G4WJS, Steve Franke K9AN, Nico Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 avril 2021 (WSJT-X 2.4.0), fourni par IC8TEM.",
                "[2] Joe Taylor K1JT, “Sensitivity Comparison of JT65A and Q65-60A” (fichiers d'essai JT65A_and_Q65-60A.zip), fourni par IC8TEM – https://physics.princeton.edu/pulsar/k1jt/JT65A_and_Q65-60A.zip",
                "[3] Andy Talbot G4JNT, “The Q65 Coding Process used in WSJT-X”, octobre 2023, fourni par IC8TEM.",
                "[4] Nico Palermo IV3NWV, présentation à la conférence EME 2016 sur les codes QRA, citée dans [3] – http://www.eme2016.org/wp-content/uploads/2016/08/EME-2016-IV3NWV-Presentation.pdf",
                "[5] Code source de WSJT-X (fichier Q65_encoding_modules.F90 et autres), cité dans [3] – https://wsjt.sourceforge.io/wsjtx.html",
                "[6] Lance Collister W7GJ, “Q65-60A QSO Procedure and Tips for EME DXpeditions”, révisé le 3 avril 2023, fourni par IC8TEM – http://www.bigskyspaces.com/w7gj/"
            };
            d["fr"]["S54"] = new string[] {
                "## Littérature EME de SM5BSZ",
                "Leif Åsbrink SM5BSZ, auteur de Linrad, a également publié sur son site des études sur l'EME qui vont au-delà de son logiciel. Deux travaux utiles pour comprendre le trajet Terre – Lune – Terre :",
                "• “Selecting Polarisation for EME” (25 avril 1997) : comment la géométrie, la réflexion sur la Lune, la rotation de Faraday et l'absorption ionosphérique modifient la polarisation, avec des conseils pratiques pour choisir la polarisation en émission et en réception selon la fréquence – https://sm5bsz.com/polarity/emepol.htm",
                "• “EME Path Modulation” (23 février 2000) : spectres d'une porteuse de quelques minutes émise par SM5FRH et reçue par SM5BSZ via la Lune, avec la composante spéculaire étroite et la composante diffuse plus large, qui se comportent différemment selon la polarisation – https://sm5bsz.com/sm5frh/sm5frh.htm",
                "Sur le versant sportif de l'EME : Henryk Kotowski SM0JHF, “Moonbouncers Are Also Contesters”, contesting.com, 20 mai 2002 – https://www.contesting.com/articles/294"
            };
            d["fr"]["S55"] = new string[] {
                "## Autres outils de calcul EME",
                "• **EME Link Budget & Analysis Tool (1-300 GHz)** de Gerald Ihninger OE2IGL et Joachim Köppen DF3GJ : bilan complet pour les bandes à partir de 1 GHz, avec paramètres de la parabole, pointage, libration et atmosphère – https://wettersat.bplaced.net/EME/EME.html",
                "• **WSJT-X** de Joe Taylor K1JT et collaborateurs : modes numériques pour l'EME (JT65, Q65 et autres) et la fenêtre Astronomical Data avec Doppler et CAT – https://wsjt.sourceforge.io"
            };
            d["fr"]["S43"] = new string[] {
                "## Polarisation, Dpol et MNR",
                "L'angle de polarisation local est calculé comme dans WSJT-X à partir de la latitude et de l'azimut et de l'élévation de la Lune ; §D_{pol}§ est la différence entre les angles des deux stations, comprise entre −90° et +90°. La perte de polarisation linéaire (au maximum 30 dB) et la non-réciprocité maximale MNR (au maximum 25 dB) valent :",
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}",
                "La rotation de Faraday ne peut pas être prévue et n'est pas incluse.",
                "Le décalage spatial de polarisation peut se calculer, car il ne dépend que de la position des deux stations : vues depuis la Lune, une antenne horizontale au pôle Nord et une autre à l'équateur apparaissent l'une horizontale et l'autre verticale. La rotation de Faraday, en revanche, est aléatoire : le signal traverse deux fois l'ionosphère, à l'aller et au retour, et tourne selon la densité électronique du moment. Il peut arriver que vous entendiez le DX et qu'il ne vous entende pas ; à 90° le signal n'est pas atténué, il disparaît. Qui dispose d'antennes horizontales et verticales peut toujours recevoir avec la meilleure polarisation et, si le correspondant ne répond pas, commuter la polarisation d'émission avec un relais [1].",
                "> Entre stations éloignées, par exemple entre l'hémisphère nord et l'hémisphère sud, la seule position géographique peut amener §D_{pol}§ près de 90°. S'il dépasse 60° dans les 24 heures suivantes, le programme affiche un avertissement dès la saisie des locators [1].",
                "Avec des antennes à polarisation linéaire, la perte due au décalage spatial de polarisation vaut environ 3 dB à 45°, 6 dB à 60° et plus de 20 dB à 90° : c'est pourquoi l'avertissement se déclenche à 60° [2].",
                "### La rotation de Faraday",
                "L'ionosphère contient des électrons libres qui, guidés par le champ magnétique terrestre, se déplacent en spirale : une onde à polarisation linéaire qui la traverse en ressort avec son plan de polarisation tourné. C'est la rotation de Faraday [3]. Elle dépend du nombre d'électrons le long du trajet et diminue avec le carré de la fréquence [3] :",
                "= F_{f} = F_{144} · \\p{\\frac{144}{f}}^{2}",
                "~ §F_{144}§ est la rotation à 144 MHz, §f§ la fréquence en MHz. Une valeur diurne typique à 144 MHz est de 180° avec la Lune au zénith et d'environ quatre fois plus à 10° d'élévation, car le trajet dans l'ionosphère est plus long [3].",
                "|h| Bande | >Lune au zénith | >Lune à 10° d'élévation",
                "| 50 MHz | >≈ 1 490° (plus de 4 tours) | >≈ 5 970°",
                "| 144 MHz | >180° | >≈ 720°",
                "| 432 MHz | >≈ 20° | >≈ 80°",
                "~ Rotation pour un passage dans l'ionosphère, valeur diurne typique ; 144 MHz d'après [3], les autres bandes dérivées par YAEC avec la formule ci-dessus (≈ = dérivé). À partir de 1296 MHz, on peut la considérer comme nulle [3].",
                "• **Elle ne s'annule pas au retour.** Le sens de rotation ne dépend pas de la direction dans laquelle se propage l'onde : après le second passage dans l'ionosphère, le signal est de nouveau tourné, dans le même sens [3]. Chaque station ajoute la rotation de l'ionosphère située au-dessus d'elle.",
                "• **Elle varie dans le temps.** La quantité d'électrons varie entre le jour et la nuit, au lever et au coucher du soleil et avec l'activité solaire : avec un Soleil très actif, la rotation est forte et peut varier rapidement, et pendant les aurores la polarisation peut changer en quelques millisecondes [3]. C'est pourquoi on ne peut pas la prévoir par un calcul.",
                "• **Elle s'ajoute au décalage spatial.** Le décalage spatial de polarisation (§D_{pol}§) a un signe opposé dans les deux sens de la liaison, tandis que la rotation de Faraday garde le même sens : dans un sens les deux rotations s'additionnent, dans l'autre elles se soustraient. Il peut ainsi arriver que vous entendiez le DX et qu'il ne vous entende pas, ou l'inverse [1]. La perte suit la même loi que §D_{pol}§, §L = −20 · log_{10} \\a{cos Δ}§, avec Δ le décalage total : à 90° le signal disparaît.",
                "• **Que faire.** De 50 à 432 MHz, on utilise la polarisation linéaire : il est utile d'avoir une installation qui permette de choisir le plan de polarisation, de préférence par commutation électronique plutôt qu'en tournant mécaniquement toute l'antenne [3]. Quand vous lancez CQ, il est plus efficace d'alterner horizontale et verticale que d'utiliser la polarisation circulaire, qui coûte toujours 3 dB [3]. Avec des antennes horizontales et verticales, on reçoit avec la meilleure polarisation et, si le correspondant ne répond pas, on commute celle d'émission [1].",
                "> À 432 MHz, la rotation de Faraday est faible et c'est le décalage spatial, calculé par YAEC, qui domine ; à 50 et 144 MHz, elle peut faire plusieurs tours et elle est imprévisible : §D_{pol}§ et l'avertissement au-delà de 60° ne tiennent compte que de la partie spatiale.",
                "### Choisir la polarisation pour l'EME : résumé de l'article de SM5BSZ",
                "L'article « Selecting Polarisation for EME » de Leif Åsbrink SM5BSZ (25 avril 1997) est public et se lit sur son site : https://sm5bsz.com/polarity/emepol.htm. L'auteur de ce programme juge utile d'en offrir ici un résumé, comme point de départ, rédigé avec ses propres mots ; pour les explications complètes, on se reportera à la lecture intégrale de l'article [3].",
                "• **Quatre effets.** Le long du trajet Terre – Lune – Terre, la polarisation change à cause du décalage spatial, de la réflexion sur la Lune, de la rotation de Faraday et de l'absorption dans l'ionosphère [3].",
                "• **Décalage spatial.** Vues depuis la Lune, deux antennes éloignées sur la Terre courbe ne sont pas parallèles. Il ne concerne que la polarisation linéaire, se calcule facilement et ne dépend pas de la fréquence [3] : c'est le §D_{pol}§ de YAEC.",
                "• **Réflexion sur la Lune.** Aux basses fréquences, comme 144 MHz, la Lune se comporte comme une sphère lisse : la polarisation linéaire reste linéaire, la circulaire inverse son sens, et environ 1 % de l'énergie se retrouve dans la « mauvaise » polarisation. À 10 GHz, la surface est rugueuse et le signal revient dépolarisé [3].",
                "• **Rotation de Faraday.** Elle est décrite dans la sous-section précédente : elle diminue avec le carré de la fréquence, s'ajoute à l'aller et au retour et ne peut pas être prévue [3].",
                "• **Absorption ionosphérique.** Elle diminue elle aussi avec le carré de la fréquence : à 144 MHz, de jour et à 10° d'élévation, elle est d'environ 0,1 dB. Elle ne compte qu'avec une activité solaire très forte ; lors de fortes aurores, la polarisation peut changer plus vite qu'un récepteur à bande étroite ne peut la suivre [3].",
                "• **De 50 à 432 MHz.** Presque tout le monde utilise des yagis à polarisation linéaire : l'auteur conseille une installation à polarisation linéaire commutable, de préférence électroniquement ; une rotation mécanique convient si le quart de tour prend une ou quelques secondes [3]. En réception, on choisit la polarisation qui donne le signal le plus fort (un récepteur à deux canaux est plus rapide avec les signaux faibles) ; quand on lance CQ, il vaut mieux alterner horizontale et verticale plutôt qu'utiliser la circulaire, qui perd toujours 3 dB [3].",
                "• **À partir de 10 GHz.** La Lune dépolarise le signal, la polarisation d'émission n'a plus d'importance et il faut un récepteur à deux canaux sur deux sources orthogonales [3]. Ces fréquences sont en dehors des bandes de YAEC.",
                "• **Quelle polarisation émettre.** Si vous recevez une station, vous pouvez déterminer avec quelle polarisation lui émettre pour que votre signal lui parvienne correctement [3]. Avec les angles en degrés (0° horizontale, 90° verticale), P est la polarisation d'émission de l'autre station, R celle avec laquelle vous la recevez, S le décalage spatial, F la rotation de Faraday et T votre meilleure polarisation d'émission :",
                "= R = P + S + F \\quad P = T − S + F \\quad T = 2 · S − R",
                "~ En éliminant F des deux premières relations, on obtient §T = 2 · P + 2 · S − R§ ; pour une antenne linéaire, §2 · P§ vaut 0° ou 180°, ce qui est la même polarisation, et il reste §T = 2 · S − R§ [3]. Sans rotation de Faraday (§F§ = 0, à partir de 1296 MHz), la meilleure polarisation pour émettre est celle avec laquelle on reçoit le mieux, §T = R§. L'article signale que la règle coïncide avec celle de KL7WE et cite le programme SKYMOON de W5UN pour le calcul de S [3].",
                "> Dans YAEC, le décalage spatial S est le §D_{pol}§ calculé dans les onglets Position de la Lune et Position en direct et +- 24h ; la rotation de Faraday F ne peut pas être calculée. Pour les exemples, les cas particuliers et les figures, lisez l'article complet de SM5BSZ [3].",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s",
                "[2] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, présentation, juillet 2015, fournie par IC8TEM.",
                "[3] Leif Åsbrink SM5BSZ, “Selecting Polarisation for EME”, 25 avril 1997 – https://sm5bsz.com/polarity/emepol.htm"
            };
            d["fr"]["S44"] = new string[] {
                "## Bruit du ciel et Dgrd",
                "La température du ciel derrière la Lune (§T_{sky}§) à 144 MHz est tirée le long de l'écliptique d'une table au pas de 2° (WSJT-X) et, dans la vue Sky, d'une carte de tout le ciel au pas de 2° dérivée du Global Sky Model ; les autres fréquences sont mises à l'échelle avec l'indice spectral 2,6 :",
                "= T(f) = \\p{T_{144} − 2.7} · \\p{\\frac{144}{f}}^{2.6} + 2.7 \\t{ K}",
                "Dgrd, comme dans WSJT-X, ajoute l'effet de la distance d de la Lune et celui du bruit du ciel :",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2.6} \\t{ K}",
                "### Ce que signifie la Dgrd",
                "La **Dgrd** (*degradation*, dégradation) indique de combien de dB l'écho de la Lune est moins bon, à cet instant, que dans les meilleures conditions possibles : Lune au périgée et ciel froid derrière la Lune. Elle ne dépend pas de la station, mais seulement de la Lune et du ciel : c'est pourquoi elle sert à choisir les jours et les heures, et non à calculer la liaison, ce qui est le rôle du bilan EME.",
                "• **0 dB** est le cas idéal ; les valeurs sont toujours négatives. **−3 dB** signifie la moitié du rapport S/N du cas idéal, **−6 dB** un quart.",
                "• Le premier terme de la formule est la **distance** : entre le périgée (environ 356 900 km) et l'apogée (environ 406 700 km), l'écho varie d'environ 2,3 dB, car l'affaiblissement de trajet croît avec la puissance quatrième de la distance. Cela paraît peu, mais doubler les antennes ne fait gagner en théorie que 3 dB [1].",
                "• Le second terme est le **bruit du ciel** derrière la Lune : quand la Lune passe devant la Voie lactée, la température du ciel monte beaucoup et la Dgrd peut baisser de plusieurs dB, plus que l'effet de la distance.",
                "• Les valeurs typiques sont −1, −1,5 ou −2 dB. Avec la Lune sur le centre de la Galaxie, I2FAK a vu −11 dB, les pires conditions possibles, et a quand même réalisé un QSO avec une station très faible, une DXpédition depuis Djibouti, grâce à un système de 16 + 16 antennes : dans des conditions aussi mauvaises, la station doit être parfaitement calibrée, et l'expérience compte plus que les prévisions du logiciel [1].",
                "• Pour une petite station chaque dB compte : un jour avec une Dgrd de −1 dB et un autre à −5 dB peuvent faire la différence entre un QSO complet et aucun décodage.",
                "> Dans le programme : la case DGRD de l'onglet Position en direct et +- 24h montre la valeur actuelle entre le minimum et le maximum du graphique ; l'onglet Distance et Dgrd montre le calendrier des prochains jours, le graphique avec la distance et les trois meilleurs jours.",
                "### La Lune devant les sources de bruit de la Galaxie",
                "Chaque mois, la Lune parcourt la bande de l'écliptique (à environ 5° près) et traverse deux fois la Voie lactée. Les deux passages ne sont pas identiques :",
                "• **Sagittaire, centre de la Galaxie** : la zone la plus chaude du ciel ; à 144 MHz, la température du ciel derrière la Lune atteint quelques milliers de K, contre environ 200 K dans les zones froides, et cette zone est plus bruyante que le Soleil [1]. Ici la Lune est aussi à sa déclinaison la plus basse, vers −30° les années de déclinaison maximale : depuis le nord de l'Italie (environ 45° N) elle ne monte qu'à 15 – 16° d'élévation et reste au-dessus de 5° environ 6 heures (environ 7 heures au-dessus de l'horizon), alors qu'à +30° elle atteint environ 75° et reste au-dessus de 5° environ 15 – 16 heures [1]. C'est la pire période du mois.",
                "• **Taureau et Gémeaux, du côté opposé (anticentre)** : la Voie lactée est beaucoup moins chaude, mais dans le Taureau, tout près de l'écliptique, se trouve la **nébuleuse du Crabe** (Taurus A), l'une des radiosources les plus fortes du ciel : quand la Lune passe devant elle ou à côté, le bruit augmente.",
                "• Le bruit du ciel augmente quand la fréquence baisse : à 50 MHz il pèse beaucoup plus qu'à 144 MHz, à 432 MHz beaucoup moins (le programme le met à l'échelle avec l'indice spectral 2,6).",
                "> Dans le programme : la vue Sky colore le ciel du bleu (froid) au rouge (chaud) et montre où se trouve la Lune ; la colonne Tsky de l'onglet Position de la Lune et le calendrier de Distance et Dgrd indiquent quand la Lune est devant les zones chaudes.",
                "### La déclinaison de la Lune",
                "La **déclinaison** (§δ§) est la « latitude » de la Lune sur le ciel : de combien de degrés elle se trouve au nord (+) ou au sud (−) de l'équateur céleste. Le programme la calcule à partir de la date et de l'heure et l'utilise dans tous les calculs (élévation, fenêtres, Tsky, Dpol, Doppler) : vous n'avez pas à la saisir. La connaître aide toutefois à choisir les jours.",
                "• **Cycle mensuel** : en environ 27,3 jours, la déclinaison passe du maximum nord au maximum sud et revient. Avec la Lune du côté de votre hémisphère (positive au nord, négative au sud), elle monte plus haut et reste plus d'heures au-dessus de l'horizon ; du côté opposé, elle reste basse et levée seulement quelques heures [1].",
                "= El_{max} ≈ 90° − \\a{φ − δ} \\quad cos H_{0} = − tan φ · tan δ \\quad t_{su} = \\frac{2 · H_{0}}{15°} \\t{ h}",
                "~ §φ§ est la latitude de la station, §H_{0}§ l'angle horaire au lever et au coucher de la Lune, §t_{su}§ le nombre d'heures avec la Lune au-dessus de l'horizon (sans obstacles ni réfraction). Exemple à 41° N : avec §δ§ = +28°, la Lune atteint environ 77° et reste levée environ 15,7 heures ; avec §δ§ = −28°, elle s'arrête vers 21° et reste levée environ 8,3 heures.",
                "• **Liaisons entre hémisphères** : dans un QSO nord – sud, les deux stations préfèrent des déclinaisons opposées ; les fenêtres communes les plus longues tombent souvent avec la Lune proche de l'équateur céleste (déclinaison autour de 0°), quand aucune des deux stations n'est défavorisée.",
                "• **Cycle de 18,6 ans** : l'amplitude de l'excursion mensuelle change lentement, d'environ ±18,3° à environ ±28,6°. Le maximum (lunistice majeur) a eu lieu en 2024 – 2025 ; vers 2034, l'excursion sera minimale, avec des mois moins extrêmes : la Lune ne descendra plus aussi bas, mais elle ne montera pas non plus aussi haut.",
                "• **Déclinaison et bruit** : la Lune atteint sa déclinaison la plus basse quand elle passe devant le Sagittaire, la zone la plus bruyante du ciel, et la plus haute dans le Taureau et les Gémeaux, où le ciel est plus froid. Pour les stations de l'hémisphère nord, la semaine de la déclinaison la plus basse cumule donc une Lune basse, peu d'heures utiles et une Tsky élevée [1].",
                "> Dans le programme : sous le graphique de l'onglet Distance et Dgrd, la courbe de déclinaison montre les maxima nord et sud avec leur date ; la zone verte indique quand la Lune est du côté de votre hémisphère (la courbe se masque avec la case Courbe de déclinaison). La valeur à chaque instant se trouve dans la colonne facultative Déclinaison (°) de l'onglet Position de la Lune et dans l'onglet Position en direct et +- 24h.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["fr"]["S45"] = new string[] {
                "### Pourquoi le Soleil compte",
                "Le **Soleil** est la source de bruit la plus forte du ciel. Autour de la nouvelle Lune, le Soleil et la Lune sont proches dans le ciel : même si le Soleil reste hors du lobe principal, il entre par les lobes secondaires, et à moins de quelques largeurs de lobe le bruit reçu augmente beaucoup. C'est pourquoi, en pratique, la semaine de la nouvelle Lune est presque toujours à éviter.",
                "• Son poids dépend du gain de l'antenne (lobe plus étroit, Soleil plus éloigné en largeurs de lobe), du niveau des lobes secondaires et de l'**activité solaire** : le flux solaire, en SFU, change d'un jour à l'autre et augmente fortement pendant les éruptions.",
                "• C'est pourquoi une antenne aux **lobes secondaires très atténués** est essentielle : les lobes secondaires captent le bruit environnant et l'ajoutent à celui du lobe principal [1].",
                "• Pendant une éclipse de Soleil, la Lune est juste devant le Soleil : I2FAK a quand même réalisé un QSO en pointant 2,5 – 3° à côté de la Lune, de sorte que le lobe étroit de son groupement atténuait le bruit du Soleil [1].",
                "• Le Soleil sous l'horizon du récepteur ne compte pas, même à la nouvelle Lune.",
                "> Dans le programme : le calendrier de Distance et Dgrd marque avec le symbole ☀ les jours où le Soleil est proche de la Lune (orange ou rouge) ; l'onglet Bruit solaire calcule, avec le flux mesuré, combien de bruit supplémentaire le Soleil apporte à l'instant choisi.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["es"] = new Dictionary<string, string[]>();
            d["es"]["S32"] = new string[] {
                "## El locator Maidenhead (WWL)",
                "El **locator Maidenhead**, también llamado WWL (World Wide Locator) o QTH locator, es el código que usan los radioaficionados para indicar la posición de su estación. Fue ideado por John Morris G4ANB y adoptado por el Grupo de Trabajo VHF de la IARU en abril de 1980, en una reunión celebrada en Maidenhead, Inglaterra; sustituyó al antiguo QRA locator, que solo cubría Europa [1]. Desde 1999 el datum geodésico es WGS-84, el mismo del GPS [1]. YAEC obtiene del locator la latitud y la longitud de la estación, y de estas todos los cálculos.",
                "### Cómo se construye",
                "El locator es una serie de pares: cada par da primero la longitud y después la latitud, y divide el rectángulo del par anterior en partes más pequeñas. Los pares alternan letras y cifras [1]. Un ejemplo de 14 caracteres: **PM 95 UP 98 KB 75 MI** (Tokio).",
                "@locator PM 95 UP 98 KB 75 MI",
                "|h| Par | Nombre | Símbolos | >Se divide en | >Tamaño (lon × lat) | >Caracteres | >Lado a 35,7° (Tokio) | >Error máximo",
                "| 1.º | campo (field) | A … R | 18 × 18 | 20° × 10° | 2 | – | –",
                "| 2.º | cuadrado (square) | 0 … 9 | 10 × 10 | 2° × 1° | 4 | 181 × 111 km | ±106 km",
                "| 3.º | subcuadrado (subsquare) | A … X | 24 × 24 | 5′ × 2,5′ | 6 | 7,5 × 4,6 km | ±4,4 km",
                "|+ 4.º | cuadrado extendido | 0 … 9 | 10 × 10 | 30″ × 15″ | **8** | 753 × 463 m | **±442 m**",
                "| 5.º | subcuadrado extendido | A … X | 24 × 24 | 1,25″ × 0,625″ | **10** | 31 × 19 m | **±18 m**",
                "| 6.º | – | 0 … 9 | 10 × 10 | 0,125″ × 0,0625″ | 12 | 3,1 × 1,9 m | ±1,8 m",
                "| 7.º | – | A … X | 24 × 24 | 0,0052″ × 0,0026″ | 14 | 13 × 8 cm | ±8 cm",
                "~ Tamaños según las reglas de [1]; lados y error máximo (la mitad de la diagonal, con la estación en el centro del recuadro) calculados por YAEC para la latitud de Tokio: hacia los polos el lado este-oeste se acorta. Las letras se escriben en mayúsculas, como aclaró la IARU en 2019 [1]; YAEC acepta también minúsculas y las convierte.",
                "> Más allá de 8 caracteres no existe un estándar común: el 5.º par y los siguientes no están definidos formalmente, y la práctica más habitual, la que sigue YAEC, repite las reglas de los pares anteriores (letras en base 24, cifras en base 10). Otros programas pueden usar codificaciones distintas, por lo que un locator largo podría no interpretarse igual en todas partes [1].",
                "### Cuántos caracteres usar",
                "En HF se suele usar el cuadrado (4 caracteres); en las bandas de YAEC, de 50 a 432 MHz, se usa el subcuadrado (6 caracteres) [1]. Estas reglas valen para el intercambio en los QSO y en los concursos: por ejemplo, en la Región 1 de la IARU las distancias se miden entre los centros de los subcuadrados [1]. Para los cálculos de YAEC la elección es distinta:",
                "|h| Caracteres | Uso recomendado en YAEC",
                "| 4 | solo para una estimación aproximada: el acimut y la elevación de la Luna pueden errar hasta cerca de 1°, porque el horizonte local se inclina cerca de 1° cada 111 km",
                "| 6 | el locator del DX, los QSO y el balance EME: el error en la dirección de la Luna es de pocas centésimas de grado",
                "| **8** | tu estación, para Reconocimiento de mis obstáculos: identifica el barrio o la colina",
                "|+ **10** | tu estación, con el mejor resultado: identifica el edificio o la torre de la antena",
                "| 12 – 14 | aceptados, pero no aportan nada: la precisión supera la de un GPS corriente (unos pocos metros) y el tamaño de la propia antena",
                "### Locator y obstáculos",
                "Para la dirección de la Luna bastan 6 caracteres: la Luna está a unos 380 000 km, y los ±4,4 km de un locator de 6 caracteres cambian el acimut y la elevación en unos 0,04°, una cantidad despreciable frente al haz de la antena. Para los **obstáculos locales** (edificios, árboles, colinas) ocurre lo contrario: están a pocas decenas o centenas de metros de la antena, y con 6 caracteres la estación puede estar en cualquier punto de un rectángulo de 7,5 × 4,6 km, de modo que los obstáculos no pueden situarse. Con 8 caracteres el error baja a unos 450 m, con 10 a unos 20 m: esta es la precisión que necesita la pestaña **Reconocimiento de mis obstáculos** para dibujar correctamente las zonas en las que la antena está bloqueada.",
                ">+ Consejo práctico: obtén el locator de 10 caracteres a partir de las coordenadas GPS del punto donde está la antena (no de la entrada de la casa) e introdúcelo en la pestaña Posición en vivo y +- 24h como **mi locator**. Para el DX basta el locator de 6 caracteres que te comunique.",
                "[1] Wikipedia, “Maidenhead Locator System” (origen G4ANB y reunión VHF de la IARU en Maidenhead en 1980, estructura de los pares, WGS-84 desde 1999, extensiones más allá de 8 caracteres, aclaración IARU de 2019, uso en HF y VHF/UHF, distancias entre centros de subcuadrados) – https://en.wikipedia.org/wiki/Maidenhead_Locator_System"
            };
            d["es"]["S46"] = new string[] {
                "### Las fórmulas del balance EME",
                "La pérdida del trayecto sigue la ecuación del radar: la señal va de la estación a la Luna, una parte se dispersa y vuelve hacia la Tierra. Las distancias §d_1§ y §d_2§ son las distancias topocéntricas de las dos estaciones en el instante elegido, por lo que la diferencia entre perigeo y apogeo (unos 2,3 dB) ya está incluida.",
                "= λ = \\frac{c}{f} \\quad σ = 0.065 · π · R_M^2",
                "= L_{EME} = 10 · log_{10} \\b{\\frac{\\p{4π}^3 · d_1^2 · d_2^2}{σ · λ^2}} \\t{ dB}",
                "~ con §c = 299 792 458 \\t{ m/s}§, §R_M = 1 737,4 \\t{ km}§ (radio de la Luna), reflectividad lunar 0,065.",
                "La potencia radiada y la señal en los bornes de la antena receptora:",
                "= EIRP = P_{dBW} − L_{TX} + G_{ant} + 10 · log_{10} N + G_g \\quad S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                "= G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}} \\quad L_{pol} = −20 · log_{10} \\a{cos D_{pol}}",
                "~ Ganancia de suelo (casilla \"BETA- antenna without elevation\"): antena de polarización horizontal a la altura h, calculada a la elevación de la Luna, como máximo +6 dB.",
                "La figura de ruido de la cadena receptora se obtiene con la fórmula de Friis, en valores lineales (§F = 10^{NF/10}§, §G = 10^{G_{dB}/10}§):",
                "= F_{tot} = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + … \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "La figura de ruido de la radio se deduce de su MDS, medido en el ancho de banda B:",
                "= NF_{radio} = MDS + 174 − 10 · log_{10} B",
                "= T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e \\quad N = 10 · log_{10} \\p{k · T_{sys} · B} + 30 \\quad \\frac{S}{N} = S_{ant} − N",
                "~ con §k = 1,380649 · 10^{−23} \\t{ J/K}§ (Boltzmann) y B el ancho de banda en Hz. §T_{ant}§ es la temperatura de antena de las tablas de VE7BQH (antena inclinada 30°); §ΔT_{sky} = max \\p{0, T_{sky} − T_{ref}}§, con §T_{ref}§ = 200 K a 144 MHz escalada con índice 2,6.",
                "El balance EME no calcula un margen sobre el modo: muestra la S/N estimada, referida al ancho de banda de referencia de 2500 Hz usado por WSJT-X, y a su lado el umbral típico del modo elegido, solo como referencia. Un umbral no es un límite estricto: con las ayudas del decodificador se decodifica incluso por debajo, como muestran la tabla del JT65 y las notas de abajo.",
                "= \\frac{S}{N}_{2500} = \\frac{S}{N}_{B} + 10 · log_{10} \\frac{B}{2500}",
                "|h| Modo | >Umbral típico, mensaje único (2500 Hz) | Fuente",
                "| JT65 | −25 dB | [1]",
                "| JT9 | −27 dB | [1]",
                "| JT4 | −23 dB | [1]",
                "| FT8 | ≈ −20 dB | [1]",
                "| FT4 | ≈ −16,5 dB | [1]",
                "| Q65-15A | −22,2 dB | [2]",
                "| Q65-30A | −24,8 dB | [2]",
                "| Q65-60A | −27,6 dB | [2]",
                "| Q65-120A | −30,8 dB | [2]",
                "| Q65-300A | −33,8 dB | [2]",
                "| WSPR | −31 dB | [1]",
                "~ Umbrales para una probabilidad de decodificación del 50 %, medidos en un canal de ruido blanco gaussiano aditivo (AWGN). En Q65 la decodificación *a priori* (AP), que usa los indicativos ya conocidos durante el QSO, añade de 1,5 a 3,6 dB según el submodo (por ejemplo Q65-60A −30,2 dB) [2]; YAEC muestra como referencia los valores más prudentes sin AP. Con una dispersión Doppler de pocos hercios el umbral empeora: en Q65-60A unos 2 dB a 5 Hz y unos 3 dB a 10 Hz (leído en el gráfico de [2]). La estructura de Q65, sus submodos y la comparación con JT65 están en el § 3.12. Para EME el documento recomienda Q65-60A en 50 y 144 MHz y Q65-60B en 432 MHz [2]: los submodos B – E tienen una separación de tonos y un ancho de banda ocupado de 2 – 16 veces los del submodo A.",
                "Para el JT65, K1JT publicó los límites de cada tipo de decodificación, obtenidos con simulaciones del submodo JT65B [5]:",
                "|h| JT65: tipo de decodificación | >S/N (2500 Hz) | Fuente",
                "| Cualquier mensaje, también texto libre | −24 dB | [5]",
                "| Indicativo presente en la base de datos (Deep Search) | −28 dB | [5]",
                "| Cualquier mensaje con promediado de varias transmisiones | −29 dB | [5]",
                "| Solo sincronización (tiempo y frecuencia) | −30 dB | [5]",
                "| Mensajes abreviados RO, RRR, 73 | −32 dB | [5]",
                "~ La guía de WSJT-X da −25 dB para un mensaje único [1]. La decodificación Deep Search solo prueba mensajes con CQ o con tu indicativo más un indicativo y un locator de la base de datos: un indicativo desconocido o un texto libre solo se decodifican con el decodificador general, con promediado si hace falta [5]. La decodificación es “todo o nada”: un mensaje se lee entero o no se lee, no empeora poco a poco al acercarse al límite [5]. Por eso YAEC ya no muestra los dB por encima o por debajo del umbral.",
                "### La ganancia de suelo en la práctica",
                "La ganancia de suelo de la casilla \"BETA- antenna without elevation\" sigue el modelo del terreno plano y reflectante: el rayo directo y el reflejado se suman cuando la diferencia de trayecto es un número semientero n de longitudes de onda y se anulan cuando es entero, con §n · λ = 2 · H · sin α§; el punto de reflexión está a una distancia §D = \\frac{H}{tan α}§ de la antena [3]. Las pruebas de IK1UWL con los ecos de su propia estación (4 × 14 elementos a 121 m sobre el mar, costa de Liguria) muestran que en la práctica las cosas son más complicadas [3]:",
                "• los picos y los nulos son muchos y muy próximos, en ángulos fraccionarios que un simulador con pasos de 1° como EZNEC no ve: con la antena alta sobre el mar se suceden aproximadamente cada 3 minutos (3 periodos de JT65) y causan un fuerte QSB a baja elevación, que no depende de la ionosfera;",
                "• la ganancia medida fue de unos 3 dB, no los 6 dB teóricos: en un sistema las yagis superiores e inferiores están a alturas distintas (4,5 m), sus reflexiones no están en fase y solo contribuye un par cada vez;",
                "• por debajo de 2° de elevación hay un hueco de ganancia y el máximo está hacia 5°; al elevar la antena el efecto suelo disminuye y, más allá del ancho del haz (unos 12° para su sistema), se vuelve despreciable;",
                "• la refracción cuenta: la Luna salió a −0,51°, por debajo del horizonte óptico de −0,35°; a 200 MHz, en aire seco, el error de refracción a 0° de elevación es de −0,49°.",
                "IK3XTV recuerda que en teoría el efecto suelo llega a 6 dB, de modo que una sola yagi rinde casi como un sistema de 4, pero depende mucho del terreno alrededor de la antena: es menor en la ciudad, mejor en campo abierto y todavía más cerca del mar. Se aprovecha en la salida y la puesta de la Luna, entre aproximadamente 1° y 18 – 20° de elevación [4].",
                "> Por eso en el balance EME la ganancia de suelo aparece como BETA: el valor calculado (como máximo +6 dB) es un límite teórico. Con antenas altas sobre el mar o sistemas de varias yagis conviene esperar aproximadamente la mitad y un QSB marcado a baja elevación [3].",
                "[1] WSJT-X User Guide, K1JT y el WSJT Development Group, § 7.1 (FT4 = FT8 + 3,5 dB).",
                "[2] J. Taylor K1JT, B. Somerville G4WJS, S. Franke K9AN, N. Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 de abril de 2021 (WSJT-X 2.4.0), facilitado por IC8TEM.",
                "[3] Giorgio Marchi IK1UWL, “Considerazioni sull'effetto suolo (Ground Gain)”, 21.º Meeting EME, presentación facilitada por IC8TEM.",
                "[4] Flavio Egano IK3XTV, “EME (earth-moon-earth) con una singola Yagi in 144 MHz”, documento del 12 de noviembre de 2010, facilitado por IC8TEM.",
                "[5] J. Taylor K1JT, ponencia sobre JT65 en la conferencia EME 2006 (K1JT_eme2006.pdf): tabla de los niveles mínimos de S/N en 2500 Hz.",
                "> El esquema de la estación, a la derecha de la pestaña, deduce las pérdidas de los cables elegidos: en transmisión cable PA–relé + relé + cable de antena, en recepción cable de antena + relé antes del preamplificador y cable de bajada después de él. Las atenuaciones de los cables proceden de la base de datos de la pestaña COAXIAL CABLES (§ 3.8)."
            };
            d["es"]["S47"] = new string[] {
                "## El preamplificador y la figura de ruido de la radio {nuovo}",
                "En EME la señal que llega a la antena está apenas por encima del ruido (unos −149 dBm en el ejemplo Tokio – Ciudad del Cabo). El preamplificador tiene dos funciones distintas: **recuperar la señal** perdida en los cables hasta la estación y, sobre todo, **cubrir la figura de ruido de la radio**, que en los transceptores comerciales de VHF/UHF va de unos 3 – 5 dB con el preamplificador interno activado a 15 – 16 dB y más con el preamplificador desactivado.",
                "La razón está en la fórmula de Friis: cada etapa pesa sobre el ruido total dividida por la ganancia de todo lo que la precede. La primera etapa lo decide casi todo.",
                "= F_{tot} = F_{LNA} + \\frac{F_{cable} − 1}{G_{LNA}} + \\frac{F_{radio} − 1}{G_{LNA} · G_{cable}} \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "~. F y G en valores lineales (§F = 10^{NF/10}§); para un cable con pérdida L en dB: §F_{cable} = 10^{L/10}§ y §G_{cable} = 10^{−L/10}§.",
                "@colonne 55",
                "#### Figura de ruido medida de algunas radios",
                "|h| Radio | >MHz | Preamplificador | >NF (dB) | Fuente",
                "| Icom IC-9700 | 144 | off / on | 16 / 3 | [1]",
                "| Icom IC-9700 | 432 | off / on | 15 / 4 | [1]",
                "| Yaesu FT-991 | 50 | IPO / AMP1 / AMP2 | 29 / 17 / 8 | [2]",
                "| Yaesu FT-991 | 144 · 432 | – | 5 · 4 | [2]",
                "| Icom IC-275E | 144 | – | 5,6 | [3]",
                "| Icom IC-9100 | 144 · 432 | no indicado | ≈ 5 · ≈ 5 | [5]{r:*}",
                "| Icom IC-821H | 144 | – | 3,4 | [3]",
                "| Icom IC-910H | 144 | – | 3,7 | [3]",
                "| Icom IC-7000 | 144 | – | 5,6 | [3]",
                "| Kenwood TS-790E | 144 | – | 4,5 | [3]",
                "| Kenwood TS-2000 | 144 | on | 6,2 | [3]",
                "| Yaesu FT-847 | 144 | on / off | 5,1 / 6,7 | [3]",
                "| Yaesu FT-817 | 144 | – | 5,4 | [3]",
                "| Yaesu FT-857D | 144 | – | 6,1 | [3]",
                "| Icom IC-746PRO | 50 | off / P1 / P2 | 19 / 9 / 6 | [14]",
                "| Icom IC-746PRO | 144 | off / on | 14 / 5,2 | [14]",
                "| Yaesu FT-897 | 50 | on / IPO | 3,6 / 8,7 | [15]",
                "| Yaesu FT-897 | 144 · 432 | siempre on | 5,9 · 7,7 | [15]",
                "~ [1] [2] medidas de VA7OJ con una fuente de ruido calibrada; [3] medidas de DF9IC con el método del factor Y, precisión ±0,5 dB, solo 144 MHz, de 2005. Con el preamplificador interno activado, el IC-9700 ya satura entre −9 y −27 dBm en 144 MHz [1]. * Valor por verificar: prueba preliminar en una unidad de preserie, autor no indicado. [14] NF deducida del ruido de fondo (MDS) medido en 500 Hz: NF = MDS + 174 − 27 dB; con el preamplificador activado en 144 MHz el rango dinámico de bloqueo a 5 kHz baja de 99,9 a 88,4 dB. [15] NF deducida de la sensibilidad en SSB para 10 dB (S+N)/N con el filtro de 2450 Hz: NF = S − 9,5 + 174 − 10·log B; en 144 y 432 MHz el preamplificador está siempre en circuito. Para [14] y [15] la precisión es orientativa, ±1 dB.",
                "@destra",
                "#### Ejemplo: 35 m de Sivacavi HF 400 (1,6 dB) a 144 MHz",
                "|h| Configuración | >NF total | >Te | >Tsys | >Empeora la S/N en",
                "| Solo la radio, preamplificador interno desactivado (NF 16) | 17,6 dB | 16 398 K | 16 648 K | %bar:17.6:17.6:r%17,6 dB",
                "| Solo la radio, preamplificador interno activado (NF 3) | 4,6 dB | 546 K | 796 K | %bar:4.4:17.6:o%4,4 dB",
                "| LNA en la antena 0,5 dB / 20 dB + radio NF 16 | 2,3 dB | 199 K | 449 K | %bar:1.9:17.6:y%1,9 dB",
                "| **LNA en la antena 0,5 dB / 20 dB + radio NF 3** | **0,6 dB** | 41 K | 291 K | %bar:0:17.6:g%{g:**referencia**}",
                "~ §T_{sys} = T_{ant}§ 250 K + §T_e§; la comparación se hace con la misma señal en la antena.",
                "@fine",
                "Para la mejor configuración, sustituyendo los valores:",
                "= F_{tot} = 1.1220 + \\frac{1.4454 − 1}{100} + \\frac{1.9953 − 1}{100 · 0.6918} = 1.1220 + 0.0045 + 0.0144 = 1.1409 \\quad ⇒ \\quad NF = 0.57 \\t{ dB}",
                ">! **En la práctica.** El preamplificador debe montarse en la antena, antes del cable de bajada y justo después del relé coaxial (que debe protegerlo durante la transmisión con un secuenciador). Su ganancia debe ser lo bastante alta para que el cable y la radio sean despreciables: como regla, al menos 10 dB más que la suma de la pérdida del cable y la figura de ruido de la radio (en el ejemplo 1,6 + 16 ≈ 18 dB → con 20 dB la radio pesa aún 1,7 dB; con el preamplificador interno activado pesa solo 0,05 dB). Sin embargo, demasiada ganancia reduce el rango dinámico de la radio: con un buen LNA en la antena a menudo es mejor mantener desactivado el preamplificador interno y elegir un LNA de 20 – 26 dB. En el balance EME estas elecciones se hacen en el esquema de la instalación receptora, y la pestaña DEBUG FORMULE muestra el cálculo paso a paso.",
                "##+ El transverter (opcional)",
                "Con un transverter la radio trabaja en una frecuencia intermedia (normalmente 28 MHz para 144 MHz) y el transverter pasa a ser la etapa que cuenta para el ruido: entra en la fórmula de Friis después del cable de bajada, y la radio que le sigue pesa tanto menos cuanto más gana el transverter.",
                "= F_{comb} = F_{XV} + \\frac{F_{radio} − 1}{G_{XV}} \\quad \\t{e.g. } F_{comb} = 1.2589 + \\frac{10 − 1}{50.12} = 1.4385 ⇒ NF = 1.58 \\t{ dB}",
                "~ ejemplo: transverter con NF 1,0 dB y ganancia 17 dB (valores mínimos del DEMI L144-28) delante de una radio de HF con NF 10 dB.",
                "@colonne 56",
                "#### Gráfico: NF del conjunto al variar la radio y la ganancia del transverter",
                "@abaco Curvas calculadas con (3.7.3) para un transverter con NF 1,0 dB. Cuanto más gana el transverter, menos pesa la radio: con 25 dB de ganancia una radio con 20 dB de NF lleva el total a 2,0 dB; con 10 dB de ganancia la misma radio lleva el total a 10,5 dB.",
                "@destra",
                "#### Transverters para 144 MHz (FI 28 MHz)",
                "|h| Fabricante · modelo | >NF | >G RX | >TX | Fuente",
                "| DEMI L144-28 | < 1,0 dB | ≥ 17 dB | 25 / 50 W | [6]",
                "|+ **Kuhne (DB6NT) MKU 144 G2** (módulo) | 0,9 dB | 25 dB | 0,1 W¹ | [13]",
                "| Kuhne (DB6NT) TR 144 H +40 | 0,9 – 1,2 dB | 25 dB | 2 – 20 W | [7]",
                "| Kuhne (DB6NT) TR-144 Pro | {r:n.d.} | {r:n.d.} | 25 W | [8]",
                "| Q5 Signal L144-28M | < 1,0 dB | ≥ 20 dB | 25 / 75 / 150 W | [9]",
                "| HA1YA ME2T-PRO-II / ME2HT-PRO-II | 1,0 dB | ≤ 25 dB (ajustable) | 30 / 50 W | [10]",
                "| SSB-Electronic LT2S Mk II | {r:n.d.} | {r:n.d.} | – | [11]",
                "~ Valores declarados por los fabricantes. MKU 144 G2: primera etapa con NF 0,5 dB, IP3 de salida en recepción +23 dBm, entrada de FI 2 – 50 mW o 60 – 2000 µW; ¹ excitador de 100 mW, a completar con un amplificador Kuhne de 60 o 120 W. TR 144 H +40: contiene el módulo MKU 144 G2, de ahí la ganancia de 25 dB (información de IC8TEM). Con 25 dB de ganancia, delante de una radio con NF 10 dB el total es 0,99 dB, con NF 20 dB es 1,88 dB [13]. El manual de Kuhne indica 1,2 dB en la tabla y 0,9 dB en el texto; con el preamplificador Kuhne MKU LNA 144 A el total baja a 0,3 dB [7]. Q5 Signal L144-28M: NF máxima 1,0 dB con ganancia mínima de conversión 20 dB, ganancia RX-FI ajustable por el usuario para calibrar el S-meter; FI hasta 25 W [9]. HA1YA ME2T-PRO-II: NF global 1 dB (primera etapa PGA103+ con NF 0,7 dB), ganancia RX ajustable hasta 25 dB, OIP3 típico +35 dBm, IIP3 típico +10 dBm, rechazo de imagen > 80 dB, entrada de FI de −20 a +37 dBm [10].",
                "#### Combinaciones medidas (DF9IC, 144 MHz)",
                "|h| Radio + transverter | Preamplificador de la radio | >NF",
                "| Elecraft K2 + Kuhne TR144H+40 | – | 1,0 dB",
                "| IC-756PRO II + Kuhne TR144H | off | 1,0 dB",
                "| IC-746 + Kuhne TR144H+40 | off | 1,2 dB",
                "| FT-1000MP + Javornik (dos unidades) | off | 0,9 · 1,4 dB",
                "| FT-1000 Mark V + Kuhne TR144H, FI 14 MHz | off | 1,6 dB",
                "| FT-1000 Mark V + Kuhne TR144H, FI 28 MHz | off / on | 6,0 / 1,7 dB",
                "| TS-870 + Javornik | off | 1,9 dB",
                "| Elecraft K2 + XV144 | on | 6,0 dB",
                "~ Fuente [3]. El caso del FT-1000 Mark V a 28 MHz muestra el gráfico en la práctica: con el preamplificador de la radio desactivado la radio pesa mucho (6,0 dB), con el preamplificador activado baja a 1,7 dB.",
                "@fine",
                "##+ Estaciones EME con FT-1000MP y transverter",
                "Dos ejemplos documentados del FT-1000MP usado para EME en 144 MHz con un transverter: las medidas de DF9IC [3] con FT-1000MP + transverter Javornik (NF 0,9 – 1,4 dB con el preamplificador de la radio desactivado) y la estación EME de **W3SZ** [12] (4 × M2 2MXP32, preamplificadores LNA Technology en la antena para cada polarización, LMR-600 y hardline Andrew), que en transmisión usa un **FT-1000MP Mark V** con un transverter **SSB-Electronic LT2S Mk II** (FI 28 MHz) y un amplificador 2 × GU-74B, mientras que en recepción usa el hardware WSE y el software Linrad de SM5BSZ.",
                "> En el balance EME el transverter es un bloque del esquema de la estación: se activa con su casilla, se elige el modelo de la lista (o \"custom\") y el programa toma su figura de ruido y su ganancia; si está desactivado, no entra en el cálculo. El gráfico anterior ayuda a decidir si activar el preamplificador de la radio.",
                ">! ✉ **¿Conoces otro transverter o has construido uno?** Si quieres dar a conocer otros transverters o tu propio transverter, escribe un e-mail al autor: ccerrotta@gmail.com o ic8tem@gmail.com. Todos los datos de contacto están en la pestaña **AUTHOR CONTACTS AND ACKNOWLEDGEMENTS**.",
                "##+ El secuenciador TX/RX",
                "Con un amplificador de potencia (PA) y un preamplificador junto a la antena (PRE), el PTT del ordenador no va a la radio sino a un **secuenciador**, que acciona los relés y luego el PA y la radio en el orden correcto [16]. El esquema más habitual tiene dos cables de bajada: el de recepción puede perder algunos dB, porque está después de un preamplificador de 15 – 20 dB, mientras que el de transmisión debe perder lo menos posible (3 dB en transmisión reducen a la mitad la potencia radiada). En reposo, los relés mantienen el PRE aislado de la antena: una protección más contra las descargas de las tormentas [16].",
                "|h| ^Paso | De RX a TX | De TX a RX",
                "| ^1 | los relés conmutan en frío: radio → entrada del PA, antena → salida del PA, PRE aislado | la radio deja de transmitir",
                "| ^2 | se enciende el PA | se apaga el PA",
                "| ^3 | la radio pasa a transmisión | los relés vuelven a recepción, sin potencia aplicada",
                "~ Entre un paso y otro hace falta al menos el tiempo de conmutación de los relés (15 – 30 ms) más sus rebotes: IK1UWL aconseja 100 – 200 ms, también para el PA si tiene relés internos [16].",
                "Para el mando de transmisión el PTT es mejor que el VOX: el VOX puede dispararse por un ruido y no aprovecha el retardo de unos 0,5 s con el que JT65 empieza a modular después del PTT, así que el preamplificador queda protegido solo por el relé rápido del amplificador; con el PTT ese retardo conmuta el amplificador antes de la modulación y se puede añadir el secuenciador [17].",
                ">! **Cuidado con el preamplificador.** El relé T/R debe aislar muy bien la puerta abierta: con 50 dB de aislamiento y 500 W en la antena llegan 5 mW a la entrada del PRE. Se procura tener al menos 60 dB, y los más prudentes añaden un segundo relé que en transmisión cierra el PRE sobre una carga de 50 Ω. Hay que desactivar el pulsador PTT del micrófono: a partir de entonces solo se transmite a través del secuenciador (para SSB, un pedal en el PTT del secuenciador, desacoplado del del PC) [16].",
                "[1] Adam Farson VA7OJ/AB4OJ, “Icom IC-9700 Test Report”, edición 5, 19 de marzo de 2021 (primera edición 19 de junio de 2019), tablas 1 y 5 – https://www.qsl.net/ab4oj/icom/ic9700/9700notes.pdf",
                "[2] Adam M. Farson VA7OJ/AB4OJ, “Yaesu FT-991 Test Report”, 25 de julio de 2015, tabla 1 – https://www.qsl.net/ab4oj/test/docs/ft991notes.pdf",
                "[3] DF9IC con DARC OV Durlach A35, “Test of the Large Signal Behaviour of some 144 MHz Radios”, pruebas del 27 de febrero de 2005 – https://www.df9ic.de/tech/trxtest/trxtest.html",
                "[4] H. T. Friis, “Noise Figures of Radio Receivers”, Proceedings of the IRE, vol. 32 (1944).",
                "[5] Prueba preliminar “ICOM IC-9100 review” en una unidad de preserie prestada por Icom UK (autor y fecha no indicados) – https://manualmachine.com/icom/ic9100/26837637-review",
                "[6] Down East Microwave, “L144-28 Rev B” – guía del usuario (especificaciones: NF < 1,0 dB con ganancia de conversión ≥ 17 dB) – https://manualmachine.com/demi/l14428revb/26842141-user-guide",
                "[7] Kuhne electronic, “TR 144 H +40” – manual del usuario – https://manuals.online/kuhne-electronic/transceiver/tr-144-h-40/user-manual/191pa",
                "[8] RigPix, “Kuhne TR-144 Pro” – https://rigpix.com/transverters/kuhne_tr144pro.htm",
                "[9] Q5 Signal, “VHF/UHF Transverters – L144-28M REV 2”, manual (8 páginas), enero de 2023, facilitado por IC8TEM – http://q5signal.com/image/catalog/L144-28Mr2.pdf",
                "[10] HA1YA (Mechanics & Electronics), “ME2T-PRO-II & ME2HT-PRO-II 144MHz Transverter”, 25.09.2023, facilitado por IC8TEM – http://www.ha1ya.hu/pdf/me2tpro2transverter.pdf",
                "[11] SSB-Electronic LT2S Mk II – citado en [12]",
                "[12] Roger Rehr W3SZ, descripción de la estación EME – https://w3sz.com/EMEFrame1Source1.htm",
                "[13] Kuhne electronic GmbH, “MKU 144 G2 – Transverter module, 144 … 146 MHz, 28 … 30 MHz IF”, hoja de datos (2 páginas), facilitada por IC8TEM",
                "[14] ARRL Laboratory, “Icom IC-746PRO”, QST Product Review, mayo de 2002 – https://www.radiomanual.info/schemi/ICOM_HF/IC-746Pro_review_ARRL_2002.pdf",
                "[15] Peter Hart G3SJX, “The Yaesu FT-897 HF/VHF/UHF Transceiver”, RadCom (RSGB), abril de 2003, pp. 18–20 – http://www.radiomanual.info/schemi/YAESU_HF/FT-897_review2_2003.pdf",
                "[16] Giorgio Marchi IK1UWL, “EME (Earth-Moon-Earth) – Guida operativa”, enero de 2012, § 4 “Sequenziamento relè, PA e PRE”, facilitada por IC8TEM – http://www.qsl.net/ik3xtv",
                "[17] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, presentación, julio de 2015, facilitada por IC8TEM."
            };
            d["es"]["S48"] = new string[] {
                "## Cables coaxiales y pérdidas",
                "La pestaña **COAXIAL CABLES** recoge la atenuación de los cables de 50 Ω más usados por los radioaficionados, en dB por 100 m a 20 °C, en las cinco bandas de YAEC. Las hojas de datos de los fabricantes dan valores a frecuencias distintas; YAEC los ha llevado a las bandas con la ley de potencia, una recta en el gráfico log-log entre las dos frecuencias más cercanas de la hoja de datos:",
                "= α(f) = α_1 · \\p{\\frac{f}{f_1}}^{n} \\quad n = \\frac{log \\p{α_2 / α_1}}{log \\p{f_2 / f_1}} \\quad L = α(f) · \\frac{ℓ}{100}",
                "~ α en dB/100 m, ℓ longitud del cable en metros. Un número sin marca es el valor de la hoja de datos; ≈ indica un valor interpolado, y e uno extrapolado más allá de la última frecuencia de la hoja de datos.",
                "Los cables del mismo tipo, con el mismo diámetro dentro de ±0,2 mm y una atenuación dentro de 0,2 dB/100 m en todas las bandas se agrupan en una sola fila (≡), con el valor medio; los nombres equivalentes se muestran con \"also:\" (por ejemplo LMR-400 = HF400, CNT-400, 50-7 low loss; LMR-600 = CNT-600). Los nombres chinos 50-3, 50-5, 50-7, 50-9, 50-12 indican el diámetro del dieléctrico en milímetros.",
                "> Se pueden añadir cables personalizados con sus cinco atenuaciones: se guardan en data\\cavi_personali.txt y aparecen también en los desplegables del esquema de la estación del balance EME. La información emergente de cada fila de la tabla cita la fuente de ese cable.",
                "[1] Las fuentes de cada cable: hojas de datos de Times Microwave (LMR), RFS (CELLFLEX LCF/SCF), CommScope Andrew (HELIAX LDF/FSJ), Siva Cavi (HF 240/287/400), SSB-Electronic (Aircell, Ecoflex, Aircom Plus), Messi & Paoloni (Hyperflex, Ultraflex, vía WiMo), Symair, SYV50-7 (szansy.com), Belden (H1000), Prospecta (RT5020, XT2400), QAXIAL (LLF195), Caledonian Cables, catálogo MIL-C-17F (RG-142, RG-393), R.F. elettronica de Senago (RG-115), las tablas de DD1US y EA5IP (H100) y la tabla de SV1BSX para RG-58, RG-213, H-155 y H-2000 (valores por verificar)."
            };
            d["es"]["S410"] = new string[] {
                "## Doppler, compensación y CFOM",
                "La Luna se acerca y se aleja de las dos estaciones por la rotación de la Tierra y por su propio movimiento orbital: la distancia R cambia unos cientos de metros por segundo y la señal vuelve desplazada en frecuencia. El desplazamiento es máximo cuando la Luna sale o se pone, pasa por cero cuando transita por el sur (o por el norte) y es proporcional a la frecuencia. YAEC lo calcula cada segundo en la pantalla principal, en la tarjeta **Echo and frequencies (CFOM)**.",
                "### Cuánto vale el Doppler",
                "Para el eco de la propia estación el trayecto se recorre dos veces (ida y vuelta):",
                "= f_{D,echo} = − \\frac{2f}{c} · \\frac{dR}{dt} \\quad \\t{e.g. } − \\frac{2 · 144.120 · 10^6}{299 792} · 0.222 = −213 \\t{ Hz}",
                "con f la frecuencia en Hz, c = 299 792 km/s y dR/dt la velocidad radial de la Luna en km/s (positiva cuando se aleja). Para la señal del DX cuentan los dos tramos, el suyo y el tuyo:",
                "= f_{D,DX} = − \\frac{f}{c} · \\p{\\frac{dR_{me}}{dt} + \\frac{dR_{DX}}{dt}} \\quad \\t{e.g. } −480.7 · \\p{0.222 − 0.339} = +56 \\t{ Hz}",
                "~ ejemplo: Tokio PM95 y Ciudad del Cabo JF96, 06/11/2026 01:55 UTC, 144,120 MHz; dR/dt = +0,222 km/s en Tokio y −0,339 km/s en Ciudad del Cabo (valores de YAEC).",
                "@colonne 62",
                "|h| Banda | >Doppler máximo del eco | >Compensación",
                "| 50 MHz | ≈ ±120 Hz | no necesaria",
                "| 70 MHz | ≈ ±165 Hz | no necesaria",
                "| 144 MHz | hasta ≈ 340 Hz [1] | recomendada",
                "| 222 MHz | ≈ ±525 Hz | necesaria",
                "| 432 MHz | hasta ≈ 1000 Hz [1] | necesaria",
                "~ Valores para 144 y 432 MHz de [1]; 50, 70 y 222 MHz deducidos en proporción a la frecuencia (≈ = deducido).",
                "@destra",
                "> En 50 y 144 MHz el Doppler queda casi siempre dentro de la cascada (waterfall) del programa digital y el decodificador lo encuentra por sí solo; en 432 MHz puede sacar la señal de la banda de paso, y durante un periodo de 60 s cambia unos pocos hercios, lo bastante para parecer una deriva en los modos lentos [2].",
                "@fine",
                "### Compensar: quién corrige qué",
                "Compensar el Doppler significa desplazar la frecuencia de transmisión, la de recepción o ambas, para que las señales se encuentren en la frecuencia acordada (el *sked*). Cada estación corrige su propio Doppler y, cuando trabaja con un DX, también el del DX [1]:",
                "|h| Situación | Transmisión | Recepción",
                "| Llamada CQ y escucha del propio eco | en la frecuencia del sked | sked + Doppler del eco (3.10.1)",
                "| QSO con un DX conocido (Doppler completo hacia el DX) | corregida para que el DX te reciba en el sked | sked + Doppler DX → yo (3.10.2)",
                "| CFOM, frecuencia constante en la Luna | sked − la mitad del propio Doppler | sked + la mitad del propio Doppler",
                "### CFOM – Constant Frequency On Moon",
                "Con CFOM todas las estaciones se comportan como si un transmisor virtual en la Luna estuviera sintonizado en el sked: cada una corrige solo la mitad de su **propio** Doppler en transmisión y la mitad en recepción, sin necesidad de conocer el locator de la otra estación [2]:",
                "= f_{TX} = f_{sked} − \\frac{f_{D,echo}}{2} \\quad f_{RX} = f_{sked} + \\frac{f_{D,echo}}{2}",
                "|h| Ejemplo (Tokio, Doppler del eco −213 Hz) | >Frecuencia",
                "| Sked | 144,120000 MHz",
                "| Transmitir en (sked + 106,5 Hz) | {r:**144,120107 MHz**}",
                "| Recibir en (sked − 106,5 Hz) | {g:**144,119894 MHz**}",
                "La ventaja es que varias estaciones, y quien solo escucha, pueden seguir un QSO en la misma frecuencia sin recalcular el Doppler para cada una. YAEC muestra estas dos frecuencias en la pantalla principal.",
                "### El CAT de la radio",
                "El Doppler cambia continuamente, por lo que la compensación debe actualizarse en cada periodo. La forma más sencilla es dejarla al programa digital (por ejemplo la ventana *Astronomical Data* de WSJT-X) que, a través del **CAT** de la radio, ajusta los VFO de transmisión y recepción y mantiene la radio en la frecuencia correcta [1] [2]. Sin CAT se puede usar el split (un VFO para transmitir y otro para recibir) o el RIT, ajustando a mano en cada periodo: en 50 y 144 MHz es factible, en 432 MHz resulta incómodo [1].",
                "> Atención: para CFOM la radio debe aceptar el cambio de frecuencia por CAT **también durante la transmisión**. Algunos equipos no lo hacen (por ejemplo el FT-897 citado en [2]): en ese caso se puede recibir igualmente en CFOM, mientras que la transmisión queda en una frecuencia fija. Con un transverter (§ 3.7) el CAT ajusta la radio en la frecuencia intermedia: configura el desplazamiento del transverter en el programa, para que la frecuencia mostrada sea la real.",
                "[1] Bob Atkins KA1GT, “Doppler 101 for 1296 MHz EME (…and other bands)” (del artículo solo se usan los datos hasta 432 MHz) – https://bobatkins.com/radio/EME_doppler_101.html",
                "[2] Bob Atkins KA1GT, “CFOM – Constant Frequency On Moon Doppler Mode” – https://bobatkins.com/radio/CFOM.html"
            };
            d["es"]["S411"] = new string[] {
                "## Apuntamiento: precisión, encoders y actuadores",
                "YAEC calcula el acimut y la elevación de la Luna con una precisión de una centésima de grado, pero la señal solo llega si la antena la sigue de verdad. Cuanto más estrecho es el haz, más cuenta la precisión mecánica del apuntamiento: en las bandas de YAEC (50 – 432 MHz) basta un buen rotor, mientras que las parábolas de las bandas superiores necesitan un verdadero sistema de actuación.",
                "### Cuánto se pierde apuntando mal",
                "Con un error de apuntamiento Δ y un ancho de haz a media potencia θ (estimado por YAEC con §θ ≈ \\sqrt{41253/G}§), la pérdida se aproxima con la fórmula del haz gaussiano:",
                "= L_{point} ≈ 12 · \\p{\\frac{Δ}{θ}}^2 \\t{ dB} \\quad \\t{e.g. } 12 · \\p{\\frac{3.6}{14.4}}^2 = 0.75 \\t{ dB}",
                "~ ejemplo: 4 yagis de 17 dBi en 144 MHz, ganancia total 23 dBi, θ ≈ 14,4°; un error de un cuarto del haz (3,6°) cuesta unos 0,75 dB. En EME la pérdida se paga dos veces, en transmisión y en recepción. Fórmula aproximada, válida para errores pequeños frente al haz.",
                "### Resolución del encoder",
                "La posición de la antena la lee un encoder (o un potenciómetro convertido a digital): con n bits la vuelta completa se divide en §2^n§ pasos y el paso más pequeño es",
                "= Δ = \\frac{360°}{2^n} \\quad \\t{e.g. } n = 10: \\frac{360°}{1024} = 0.35°",
                "|h| ^Encoder | >Pasos por vuelta | >Paso | >Pérdida con el sistema de 4 yagis (θ 14,4°, error de 1 paso) | Adecuado para",
                "| 8 bits | 256 | 1,406° | 0,114 dB | sistemas de yagis en 50 y 144 MHz",
                "| 10 bits | 1024 | 0,352° | 0,007 dB | 144 MHz con margen, 432 MHz con sistemas pequeños",
                "| 12 bits | 4096 | 0,088° | < 0,01 dB | 432 MHz con sistemas grandes",
                "| 14 bits | 16 384 | 0,022° | < 0,01 dB | parábolas en 10 y 24 GHz [1]",
                "| 16 bits | 65 536 | 0,005° | < 0,01 dB | más allá: límite impuesto por la mecánica, no por el encoder",
                "~ Paso y pérdida calculados con (3.11.2) y (3.11.1). Una regla práctica es mantener el error por debajo de una décima del haz: al sistema de 4 yagis en 144 MHz le bastan 8 bits, una parábola de 3 m en 10 GHz (haz ≈ 0,7°) necesita al menos 13 – 14 bits.",
                "> El número de bits solo indica con qué finura se *lee* la posición: la precisión real depende también de los juegos mecánicos, de la flexión del soporte, del viento y de la calibración del norte y del horizonte.",
                "### Sistemas de yagis: actuadores y poleas",
                "En los sistemas de yagis (combinaciones de 2, 4 o más antenas) la carga en elevación es grande y desequilibrada. En el mercado existen actuadores lineales con motor de tornillo sin fin: en estas soluciones el tornillo solo regula el movimiento, mientras que el soporte mecánico de la carga se confía a poleas. El tornillo sin fin tiene la ventaja de no girar hacia atrás bajo la carga, por lo que el sistema permanece quieto incluso con el motor apagado.",
                "### Por encima de 432 MHz: parábolas",
                "Desde 902 MHz hacia arriba se usan sobre todo parábolas, y la herramienta [1] está pensada para frecuencias desde 1 GHz hacia arriba. Con diámetros grandes el haz se estrecha a pocas décimas de grado y existe el riesgo de no apuntar perfectamente a la Luna: más que motores, la estación necesita verdaderos actuadores mecánicos en acimut y elevación, con una precisión de apuntamiento ligada en gran medida a la resolución en bits del control. La **EME Link Budget & Analysis Tool** de OE2IGL y DF3GJ [1] indica ±0,035° para un buen sistema de seguimiento y ±0,1° para uno normal, y calcula la pérdida de apuntamiento junto con todos los demás términos del enlace.",
                ">+ YAEC se detiene en 432 MHz. Para las bandas superiores recomendamos la herramienta de OE2IGL y DF3GJ [1]: calcula el balance EME de 1 a 300 GHz con los parámetros de la parábola (diámetro, f/D, iluminador, rugosidad de la superficie, eficiencias), el apuntamiento, la libración, el ruido del Sol y de la Luna y la atenuación atmosférica.",
                "[1] Gerald Ihninger OE2IGL y Joachim Köppen DF3GJ, “EME Link Budget & Analysis Tool (1-300 GHz)” – https://wettersat.bplaced.net/EME/EME.html"
            };
            d["es"]["S412"] = new string[] {
                "## Modos digitales para EME: Q65 y JT65",
                "El balance EME (§ 3.6) muestra la S/N estimada junto al umbral típico del modo digital elegido. Esta sección explica de dónde proceden los umbrales de **Q65**, cómo se construye la señal y por qué Q65 ha sustituido hoy en gran medida a JT65 para EME en las bandas de YAEC. Los datos proceden de tres documentos: la guía rápida de los autores de Q65 [1], la comparación JT65A – Q65-60A de K1JT [2] y el estudio del proceso de codificación de G4JNT [3].",
                "### Qué es Q65",
                "Q65 fue introducido con WSJT-X 2.4.0 por K1JT, G4WJS, K9AN e IV3NWV para QSO mínimos en trayectos especialmente difíciles; cuando la dispersión Doppler supera unos pocos hercios es el más sensible de los modos de WSJT-X, y es adecuado para troposcatter, rain scatter, dispersión ionosférica, TEP y EME desde VHF hacia arriba [1]. Usa FSK de **65 tonos** y deriva de QRA64 de 2016; respecto a este introduce [1]:",
                "• un nuevo código corrector de errores Q-ary Repeat Accumulate de baja tasa, propuesto por Nico Palermo IV3NWV [3] [4];",
                "• mensajes y secuencias idénticos a FST4, FT4, FT8 y MSK144;",
                "• un tono de sincronismo bien visible en la cascada y una “curva de sincronismo” sensible, eficaz incluso con pings de meteoros;",
                "• submodos con periodos T/R de 15, 30, 60, 120 y 300 s y distintas separaciones de tonos;",
                "• decodificación por listas para mensajes que contienen partes ya recibidas, **sin base de datos de indicativos**;",
                "• promediado de mensajes, cuando las transmisiones individuales son demasiado débiles, y decodificación múltiple en toda la banda recibida.",
                "### Los submodos",
                "El nombre del submodo une el periodo T/R y una letra para la separación de tonos: Q65-60A, Q65-120C, etc. Para los submodos A la tabla da los umbrales medidos por simulación en un canal de ruido blanco gaussiano aditivo (AWGN), como S/N en 2500 Hz con una probabilidad de decodificación del 50 %, sin y con la máxima información *a priori* (AP) [1].",
                "|h| >T/R (s) | >Símbolo (s) | >Separación A (Hz) | >Ancho de banda A (Hz) | >Transmisión (s) | >S/N (dB) | >S/N AP máx. (dB)",
                "| 15 | 0,150 | 6,667 | 433 | 12,8 | −22,2 | −23,7",
                "| 30 | 0,300 | 3,333 | 217 | 25,5 | −24,8 | −26,6",
                "| 60 | 0,600 | 1,667 | 108 | 51,0 | −27,6 | −30,2",
                "| 120 | 1,333 | 0,750 | 49 | 113,3 | −30,8 | −32,5",
                "| 300 | 3,456 | 0,289 | 19 | 293,8 | −33,8 | −37,4",
                "~ Datos de [1]. Los submodos B, C, D y E tienen una separación de tonos y un ancho de banda ocupado de 2, 4, 8 y 16 veces los del submodo A; no existen todas las combinaciones (por ejemplo 15D y 30E no existen) [1].",
                "Los números de la tabla se deducen de unas pocas relaciones, verificadas por YAEC con los valores de [1]: la separación A es la inversa de la duración del símbolo, la transmisión dura 85 símbolos y el ancho de banda ocupado es de 65 separaciones.",
                "= Δf = \\frac{k}{t_s} \\quad k = 1, 2, 4, 8, 16 \\t{ (A … E)} \\quad T_{tx} = 85 · t_s \\quad B_{occ} = 65 · Δf",
                "~ ejemplo Q65-60A: §t_s§ = 0,600 s → Δf = 1,667 Hz, §T_{tx}§ = 51,0 s, §B_{occ}§ = 108 Hz. Al pasar de 60 a 120 s el umbral mejora 3,2 dB, cerca de los 10 · log(113,3 / 51,0) = 3,5 dB esperados por la transmisión más larga.",
                "### Sensibilidad y dispersión Doppler",
                "Los umbrales de la tabla valen sin dispersión de la señal. En EME la Luna ensancha cada tono unos pocos hercios (dispersión Doppler, o *libration fading*), y el umbral empeora. Del gráfico de [1] para Q65-60A sin AP:",
                "|h| >Dispersión Doppler (Hz) | >S/N al 50 % (dB) | >Pérdida (dB)",
                "| 0 | ≈ −27,4 | –",
                "| 5 | ≈ −25,6 | ≈ 1,8",
                "| 10 | ≈ −24,6 | ≈ 2,8",
                "| 20 | ≈ −23,2 | ≈ 4,2",
                "~ Valores leídos por YAEC en la figura 2 de [1] interpolando entre los puntos (≈ = deducido). La decodificación sigue siendo eficaz hasta una dispersión de unas diez veces la separación de tonos, e incluso más allá [1]: por eso para dispersiones mayores se eligen submodos con una letra más alta.",
                "> En YAEC los umbrales de referencia son sin dispersión y sin AP: sirven para comparar días, bandas y estaciones. Si en tu trayecto la señal está muy dispersa, ten en cuenta la pérdida de la tabla, o configura el modo *custom* con el umbral corregido.",
                "### Los mensajes del QSO a 60 s: Q65-60A, Q65-60B y Q65-60C",
                "En un QSO mínimo los seis mensajes estándar de WSJT-X (TX1 … TX6) no se reciben todos de la misma manera: el decodificador puede usar las partes ya conocidas (decodificación *a priori*, AP), y la cantidad de información conocida crece durante el QSO [1]. La tabla compara los tres submodos más usados en EME con el mismo periodo de 60 s.",
                "|h| Mensaje | Ejemplo | >AP en recepción | >Q65-60A | >Q65-60B | >Q65-60C",
                "| TX6 – llamada | CQ W9XYZ EN37 | >q1 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX1 – respuesta con locator | W9XYZ K1ABC FN42 | >q2 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX2 – informe | K1ABC W9XYZ −25 | >q3 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX3 – R e informe | W9XYZ K1ABC R−26 | >q3 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX4 – confirmación | K1ABC W9XYZ RRR | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| TX5 – saludos | W9XYZ K1ABC 73 | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| Separación de tonos | – | – | >1,667 Hz | >3,333 Hz | >6,667 Hz",
                "| Ancho de banda ocupado | – | – | >108 Hz | >217 Hz | >433 Hz",
                "| Dispersión aún decodificable (≈ 10 × separación) | – | – | >≈ 17 Hz | >≈ 33 Hz | >≈ 67 Hz",
                "| Con 5 Hz de dispersión Doppler, sin AP | – | – | >≈ −25,6 | >pérdida menor (n.d.) | >pérdida menor (n.d.)",
                "~ S/N en dB referida a 2500 Hz, probabilidad de decodificación del 50 %. −27,6 dB sin AP y −30,2 dB con la AP máxima son los valores del Q65-60A en [1]; para los submodos B y C se deducen de la teoría: sin dispersión la sensibilidad depende de la duración del símbolo (0,600 s), igual en los tres submodos, y no de la separación. “n.d.” = no disponible: [1] solo da la ganancia máxima de la AP (2,6 dB a 60 s), no la de los niveles q1, q2 y q3, que es menor. Indicadores q1 … q4 como en la tabla del § “Ajustes recomendados en WSJT-X”; dispersión decodificable y valor a 5 Hz de [1] y de la tabla de la dispersión Doppler de arriba. K1ABC, W9XYZ y los locators son ejemplos.",
                ">! Esta tabla comparativa se deriva del análisis de los datos que obran en nuestro poder sobre la teoría de funcionamiento del Q65, y no refleja en absoluto lo que ocurre realmente, debido al ruido natural y antrópico (de origen humano) captado en directo durante la recepción.",
                "### Qué submodo para EME",
                "Para las bandas de YAEC los submodos recomendados en [1] son:",
                "|h| Uso | Submodo",
                "| EME en 50 y 144 MHz | Q65-60A",
                "| EME en 432 MHz | Q65-60B",
                "| Dispersión ionosférica en 50 MHz | Q65-30A",
                "| Dispersión ionosférica de baja potencia en 50 MHz | Q65-120E",
                "| TEP en 50 MHz | Q65-15C, Q65-30C",
                "| Dispersión ionosférica en 144 MHz | Q65-60C",
                "~ De [1], solo para las bandas hasta 432 MHz. Los autores animan a experimentar con otras combinaciones.",
                "El periodo de 30 s duplica el ritmo de QSO con señales relativamente fuertes, el periodo de 120 s gana unos 3 dB por cada transmisión individual [2].",
                "### Q65 y JT65 comparados",
                "**JT65A** fue el modo EME de la banda de 6 metros durante casi veinte años: con la decodificación *Deep Search* alcanza −28 dB en 2500 Hz (−29 dB con el promediado de mensajes, § 3.6), unos 15 dB por debajo del nivel necesario para copiar CW de oído, pero solo para las estaciones incluidas en la base de datos CALL3.TXT de indicativos y locators. En esos QSO se envía en realidad muy poca información: unos 14 bits para un indicativo y un locator elegidos de la base de datos, más un informe de 1 bit y una confirmación de 1 bit [2].",
                "**Q65** envía siempre mensajes de 78 bits: incluso un QSO mínimo transporta un indicativo arbitrario (29 bits), un informe numérico real (7 bits) y la confirmación (1 bit), sin base de datos [2]. K1JT preparó diez ficheros simulados con señales a −29 dB y 1 Hz de dispersión Doppler, cinco JT65A y cinco Q65-60A por fichero, e intentó decodificarlos de cuatro maneras, con 50 decodificaciones posibles por prueba [2]:",
                "|h| Prueba | Modo | Indicativo y locator del DX | Deep Search | >Correctas | >Erróneas",
                "| 1 | JT65A | no conocidos | no disponible | 0 | 0",
                "| 2 | JT65A | no conocidos | sí (DX en CALL3.TXT) | 28 | 1",
                "| 3 | Q65-60A | no conocidos | – | 24 | 0",
                "| 4 | Q65-60A | conocidos (DX Call y DX Grid) | – | 49 | 0",
                "~ De [2], tabla 1. Ajustes de JT65: Deep, Deep Search, AP, 6 patrones de borrado aleatorios, nivel agresivo 9; Q65: Fast, promediado activado, borrado automático del promedio.",
                "Las conclusiones del autor [2]: en las respuestas al propio CQ, Q65-60A tiene, para **cualquier** corresponsal desconocido, más o menos la misma sensibilidad que JT65A tiene solo para los corresponsales de la base de datos; para todos los demás es **al menos 3 dB** más sensible, y aún más en los mensajes siguientes, cuando se conocen ambos indicativos. Las decodificaciones falsas son tan raras que resultan difíciles de medir. El promediado de mensajes de JT65 funciona para un único corresponsal ya identificado, el de Q65 sobre toda la banda mostrada. Por último, JT65 dedica la mitad de la energía transmitida al sincronismo, Q65 una cuarta parte.",
                "> El valor de −25 dB para JT65 en el balance EME es el de la guía de WSJT-X sin Deep Search (§ 3.6); los −28 dB con Deep Search solo valen para las estaciones incluidas en la base de datos, los −29 dB con promediado para cualquier mensaje.",
                ">! **Incoherencia entre las fuentes.** El documento de comparación JT65A – Q65-60A [2] indica −29 dB para JT65A con Deep Search; la ponencia de K1JT en la conferencia EME 2006, citada en el § 3.6, da en cambio −28 dB para Deep Search y −29 dB para el promediado de mensajes. YAEC usa los valores de 2006. Las dos fuentes se refieren a submodos distintos: JT65B en las simulaciones de 2006, JT65A en [2].",
                "### Cómo construye Q65 la señal",
                "G4JNT reconstruyó a partir del código fuente de WSJT-X el camino del mensaje a los tonos transmitidos, verificándolo con el programa Q65CODE.EXE de WSJT-X [3]. En resumen:",
                "• **Codificación de la fuente.** Como en FST4, FT8, FT4 y MSK144, el mensaje se convierte en 71 bits de datos más 6 bits de tipo, 77 en total. Un texto libre tiene hasta 13 caracteres de un alfabeto de 42 símbolos (espacio, cifras, letras y + - . / ?), y §42^{13}§ es menor que §2^{71}§; el modo de telemetría transporta hasta 18 cifras hexadecimales [3].",
                "• **Símbolos.** Con un bit más, los 78 bits se dividen en 13 símbolos de seis bits, con valores de 0 a 63 [3]: la misma longitud que los mensajes de 78 bits de [2].",
                "• **CRC.** Un control de 12 bits (dos símbolos), con polinomio 1100000001111 y los bits de cada símbolo invertidos por compatibilidad con el trabajo de IV3NWV, sirve para rechazar las decodificaciones falsas [3]. Con el CRC hay 15 símbolos.",
                "• **Paridad.** Los 50 símbolos de control proceden de una matriz “generadora” de 15 × 50, con aritmética en el cuerpo de Galois GF(64): la suma es un XOR, la multiplicación se hace con tablas de logaritmos y antilogaritmos [3].",
                "• **Código.** El código es un código (65,15) con símbolos de seis bits; los dos símbolos del CRC se “perforan”, es decir, no se transmiten, lo que deja un código efectivo (63,13) [1] [3].",
                "• **Sincronización.** A los 63 símbolos se añaden 22 símbolos de sincronismo, todos en el tono 0, en posiciones pseudoaleatorias fijas; se transmiten 85 símbolos, con 65 tonos: 0 para el sincronismo, de 1 a 64 para los datos [1] [3].",
                "= f_n = f_0 + n · Δf \\quad n = 0 … 64",
                "~ §f_0§ frecuencia del tono 0, Δf separación del submodo [3]. Con 22 símbolos de sincronismo de 85, el sincronismo ocupa cerca de una cuarta parte de la transmisión, como se señala en [2].",
                "### Ajustes recomendados en WSJT-X",
                "Para EME con Q65 los autores recomiendan, en WSJT-X: *File → Settings → General* con **Enable VHF and submode features** y **Decode after EME delay** activados y **Single decode** desactivado; en el menú *Decode* **Fast**, **Enable averaging** y **Auto Clear Avg after decode** [1]. Cada decodificación Q65 lleva la letra “q” y una o dos cifras: la primera indica la información *a priori* usada, la segunda el número de secuencias promediadas [1].",
                "|h| Indicador | Información a priori usada",
                "| q0 | ninguna",
                "| q1 | CQ",
                "| q2 | mi indicativo",
                "| q3 | mi indicativo y el indicativo del DX",
                "| q4 | ambos indicativos y RRR, RR73, 73 o vacío",
                "~ De [1]. Los autores advierten de no prestar demasiada atención a los valores de S/N mostrados por el decodificador, que aún se estaban mejorando [1]: para comparar con el balance EME de YAEC es mejor usar varios QSO que una sola lectura.",
                "### El procedimiento con las DXpediciones (W7GJ)",
                "Lance Collister W7GJ, que lleva años realizando expediciones EME en 6 m, describe cómo llamar a una DXpedición en Q65-60A durante un pile-up [6]. Ante todo, el reloj del ordenador debe ser muy preciso y la frecuencia de transmisión muy estable [6].",
                "• **Periodos.** La DXpedición transmite siempre en la primera secuencia (minutos pares); quienes llaman, en la segunda (minutos impares) [6].",
                "• **Frecuencia.** Elige una frecuencia libre dentro de la banda de paso y quédate en ella: Q65 promedia las llamadas de cada estación en su propia frecuencia, y si te mueves se pierde el beneficio de tus llamadas anteriores. Deja unos 100 Hz entre tú y los demás y comprueba que el Doppler no saque tu señal de la banda de paso del DX; quienes llaman se coordinan en el chat EME de ON4KST [6].",
                "• **Modo.** Usa el procedimiento de concurso digital del Q65-60A: en WSJT-X, *File → Settings → Advanced*, una de las opciones “Special Operating Activity” NA VHF, WW Digi o ARRL Digi (después de la versión 2.6.1 también Q65 Pileup). Introduce el indicativo y el locator del DX en DX Call y DX Grid, pulsa Generate Std Msgs y empieza por el mensaje TX2, no por CQ [6].",
                "• **Sigue llamando.** En 6 m la propagación entre estaciones con polarización lineal es a menudo no recíproca: el DX puede copiarte aunque tú no lo copies a él. No dejes de llamar ni vuelvas a un mensaje anterior si el DX está en QSO con otros o desaparece: cada mensaje contiene los dos indicativos y el QSO se reanuda donde se quedó. Con Q65 Pileup el DX necesita al menos una decodificación tuya en cada paso de la Luna [6].",
                "• **RRR, nunca RR73.** En EME usa siempre RRR: RR73 se envía una sola vez y el QSO queda registrado aunque la otra estación no lo haya recibido. El QSO está completo cuando una de las dos estaciones recibe el RRR final; quien lo recibe responde 73 el tiempo que haga falta, por lo que en *Settings → Behavior* “Disable Tx after sending 73” no debe estar marcado [6].",
                "• **Mira la pantalla.** Aunque no decodifiques al DX, su traza en la cascada (Wide Graph) o el pico naranja del Q65 te indican que probablemente lo copiarás en cuanto conteste. Borra el promedio a mano cuando veas que ha trabajado a otro: el siguiente podrías ser tú [6].",
                "|h| DX (primera secuencia, minutos pares) | Quienes llaman (segunda secuencia, minutos impares)",
                "| CQ TX7MB CI00 | TX7MB OH2BC KP30",
                "| OH2BC TX7MB R CI00 | TX7MB OH2BC RRR",
                "| G8BCG TX7MB R CI00 | TX7MB G8BCG RRR",
                "| G8BCG TX7MB 73 | TX7MB G8BCG 73",
                "~ Ejemplo abreviado de [6], con TX7MB (CI00) como DXpedición: cada estación que llama se queda en su propia frecuencia y pasa a RRR cuando recibe su propio “R CI00”.",
                "> Las ventanas lunares comunes son cortas, sobre todo en la salida y la puesta de la Luna, cuando muchas estaciones aprovechan el efecto suelo: la pestaña Posición en vivo y +- 24h y la pestaña Distancia y Dgrd muestran cuándo la Luna es visible desde ambas estaciones.",
                ">⚠ La discusión sobre los límites teóricos pierde su sentido en el momento en que se están recibiendo las señales: un ruido local repentino puede empeorar la escucha, al igual que la rotación de Faraday (§ 3.3).",
                "[1] Joe Taylor K1JT, Bill Somerville G4WJS, Steve Franke K9AN, Nico Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 de abril de 2021 (WSJT-X 2.4.0), facilitado por IC8TEM.",
                "[2] Joe Taylor K1JT, “Sensitivity Comparison of JT65A and Q65-60A” (ficheros de prueba JT65A_and_Q65-60A.zip), facilitado por IC8TEM – https://physics.princeton.edu/pulsar/k1jt/JT65A_and_Q65-60A.zip",
                "[3] Andy Talbot G4JNT, “The Q65 Coding Process used in WSJT-X”, octubre de 2023, facilitado por IC8TEM.",
                "[4] Nico Palermo IV3NWV, presentación en la conferencia EME 2016 sobre los códigos QRA, citada en [3] – http://www.eme2016.org/wp-content/uploads/2016/08/EME-2016-IV3NWV-Presentation.pdf",
                "[5] Código fuente de WSJT-X (fichero Q65_encoding_modules.F90 y otros), citado en [3] – https://wsjt.sourceforge.io/wsjtx.html",
                "[6] Lance Collister W7GJ, “Q65-60A QSO Procedure and Tips for EME DXpeditions”, revisado el 3 de abril de 2023, facilitado por IC8TEM – http://www.bigskyspaces.com/w7gj/"
            };
            d["es"]["S54"] = new string[] {
                "## Literatura EME de SM5BSZ",
                "Leif Åsbrink SM5BSZ, autor de Linrad, también ha publicado en su sitio web estudios sobre EME que van más allá de su software. Dos trabajos útiles para comprender el trayecto Tierra – Luna – Tierra:",
                "• “Selecting Polarisation for EME” (25 de abril de 1997): cómo la geometría, la reflexión en la Luna, la rotación de Faraday y la absorción ionosférica modifican la polarización, con consejos prácticos para elegir la polarización en transmisión y en recepción según la frecuencia – https://sm5bsz.com/polarity/emepol.htm",
                "• “EME Path Modulation” (23 de febrero de 2000): espectros de una portadora de unos minutos transmitida por SM5FRH y recibida por SM5BSZ vía Luna, con la componente especular estrecha y la difusa más ancha, que se comportan de forma distinta con la polarización – https://sm5bsz.com/sm5frh/sm5frh.htm",
                "En cuanto al aspecto deportivo del EME: Henryk Kotowski SM0JHF, “Moonbouncers Are Also Contesters”, contesting.com, 20 de mayo de 2002 – https://www.contesting.com/articles/294"
            };
            d["es"]["S55"] = new string[] {
                "## Otras herramientas de cálculo EME",
                "• **EME Link Budget & Analysis Tool (1-300 GHz)** de Gerald Ihninger OE2IGL y Joachim Köppen DF3GJ: balance completo para las bandas desde 1 GHz hacia arriba, con parámetros de la parábola, apuntamiento, libración y atmósfera – https://wettersat.bplaced.net/EME/EME.html",
                "• **WSJT-X** de Joe Taylor K1JT y colaboradores: modos digitales para EME (JT65, Q65 y otros) y la ventana Astronomical Data con Doppler y CAT – https://wsjt.sourceforge.io"
            };
            d["es"]["S43"] = new string[] {
                "## Polarización, Dpol y MNR",
                "El ángulo de polarización local se calcula como en WSJT-X a partir de la latitud y del acimut y la elevación de la Luna; §D_{pol}§ es la diferencia entre los ángulos de las dos estaciones, entre −90° y +90°. La pérdida por polarización lineal (como máximo 30 dB) y la no reciprocidad máxima MNR (como máximo 25 dB) son:",
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}",
                "La rotación de Faraday no puede predecirse y no está incluida.",
                "El desplazamiento espacial de la polarización se puede calcular, porque depende solo de la posición de las dos estaciones: vistas desde la Luna, una antena horizontal en el Polo Norte y otra en el ecuador aparecen una horizontal y la otra vertical. La rotación de Faraday, en cambio, es aleatoria: la señal atraviesa la ionosfera dos veces, a la ida y a la vuelta, y gira según la densidad de electrones del momento. Puede ocurrir que tú oigas al DX y él no te oiga; a 90° la señal no se atenúa, desaparece. Quien tiene antenas horizontales y verticales puede recibir siempre con la mejor polarización y, si el corresponsal no responde, conmutar con un relé la polarización de transmisión [1].",
                "> Entre estaciones lejanas, por ejemplo entre el hemisferio norte y el sur, la sola posición geográfica puede llevar §D_{pol}§ cerca de 90°. Si supera 60° en las 24 horas siguientes, el programa muestra un aviso en cuanto se introducen los locators [1].",
                "Con antenas de polarización lineal la pérdida por el desplazamiento espacial de la polarización es de unos 3 dB a 45°, 6 dB a 60° y más de 20 dB a 90°: por eso el aviso salta a 60° [2].",
                "### La rotación de Faraday",
                "La ionosfera contiene electrones libres que, guiados por el campo magnético terrestre, se mueven en espiral: una onda con polarización lineal que la atraviesa sale con el plano de polarización girado. Es la rotación de Faraday [3]. Depende del número de electrones a lo largo del trayecto y disminuye con el cuadrado de la frecuencia [3]:",
                "= F_{f} = F_{144} · \\p{\\frac{144}{f}}^{2}",
                "~ §F_{144}§ es la rotación a 144 MHz, §f§ la frecuencia en MHz. Un valor diurno típico a 144 MHz es 180° con la Luna en el cenit y unas cuatro veces más a 10° de elevación, porque el trayecto por la ionosfera es más largo [3].",
                "|h| Banda | >Luna en el cenit | >Luna a 10° de elevación",
                "| 50 MHz | >≈ 1490° (más de 4 vueltas) | >≈ 5970°",
                "| 144 MHz | >180° | >≈ 720°",
                "| 432 MHz | >≈ 20° | >≈ 80°",
                "~ Rotación por un paso a través de la ionosfera, valor diurno típico; 144 MHz según [3], las demás bandas derivadas por YAEC con la fórmula anterior (≈ = derivado). A partir de 1296 MHz se puede considerar nula [3].",
                "• **No se anula a la vuelta.** El sentido de la rotación no depende de la dirección en que viaja la onda: tras el segundo paso por la ionosfera la señal queda girada otra vez, en el mismo sentido [3]. Cada estación añade la rotación de la ionosfera que tiene encima.",
                "• **Cambia con el tiempo.** La cantidad de electrones varía entre el día y la noche, al amanecer y al atardecer y con la actividad solar: con el Sol muy activo la rotación es fuerte y puede variar rápidamente, y durante las auroras la polarización puede cambiar en pocos milisegundos [3]. Por eso no se puede predecir mediante un cálculo.",
                "• **Se suma al desplazamiento espacial.** El desplazamiento espacial de la polarización (§D_{pol}§) tiene signo opuesto en los dos sentidos del enlace, mientras que la rotación de Faraday mantiene el mismo sentido: en un sentido las dos rotaciones se suman, en el otro se restan. Así puede ocurrir que tú oigas al DX y él no te oiga, o al revés [1]. La pérdida sigue la misma ley que la §D_{pol}§, §L = −20 · log_{10} \\a{cos Δ}§, con Δ el desplazamiento total: a 90° la señal desaparece.",
                "• **Qué hacer.** De 50 a 432 MHz se usa la polarización lineal: conviene una instalación que permita elegir el plano de polarización, mejor con conmutación electrónica que girando mecánicamente toda la antena [3]. Cuando llamas CQ es más eficaz alternar horizontal y vertical que usar la polarización circular, que cuesta siempre 3 dB [3]. Con antenas horizontales y verticales se recibe con la mejor polarización y, si el corresponsal no responde, se conmuta la de transmisión [1].",
                "> En 432 MHz la rotación de Faraday es pequeña y predomina el desplazamiento espacial, que YAEC calcula; en 50 y 144 MHz puede dar varias vueltas y es imprevisible: la §D_{pol}§ y el aviso por encima de 60° solo tienen en cuenta la parte espacial.",
                "### Elegir la polarización para EME: resumen del artículo de SM5BSZ",
                "El artículo “Selecting Polarisation for EME” de Leif Åsbrink SM5BSZ (25 de abril de 1997) es público y se puede leer en su sitio web: https://sm5bsz.com/polarity/emepol.htm. El autor de este programa considera útil ofrecer aquí un resumen, como punto de partida, escrito con sus propias palabras; para las explicaciones completas se remite a la lectura íntegra del artículo [3].",
                "• **Cuatro efectos.** A lo largo del trayecto Tierra – Luna – Tierra la polarización cambia por el desplazamiento espacial, la reflexión en la Luna, la rotación de Faraday y la absorción en la ionosfera [3].",
                "• **Desplazamiento espacial.** Vistas desde la Luna, dos antenas lejanas sobre la Tierra curva no son paralelas. Solo afecta a la polarización lineal, se calcula con facilidad y no depende de la frecuencia [3]: es la §D_{pol}§ de YAEC.",
                "• **Reflexión en la Luna.** En las frecuencias bajas, como 144 MHz, la Luna se comporta como una esfera lisa: la polarización lineal sigue siendo lineal, la circular invierte su sentido, y cerca del 1 % de la energía acaba en la polarización “equivocada”. En 10 GHz la superficie es rugosa y la señal vuelve despolarizada [3].",
                "• **Rotación de Faraday.** Se describe en el subapartado anterior: disminuye con el cuadrado de la frecuencia, se suma a la ida y a la vuelta y no se puede prever [3].",
                "• **Absorción ionosférica.** También disminuye con el cuadrado de la frecuencia: en 144 MHz, de día y a 10° de elevación, es de unos 0,1 dB. Solo cuenta con una actividad solar muy alta; durante las auroras fuertes la polarización puede cambiar más deprisa de lo que un receptor de banda estrecha consigue seguir [3].",
                "• **De 50 a 432 MHz.** Casi todos usan yagis con polarización lineal: el autor aconseja una instalación con la polarización lineal conmutable, mejor electrónicamente; una rotación mecánica sirve si el cuarto de vuelta requiere uno o pocos segundos [3]. En recepción se elige la polarización con la señal más fuerte (un receptor de dos canales es más rápido con señales débiles); cuando se llama CQ conviene alternar horizontal y vertical, en lugar de usar la circular, que pierde siempre 3 dB [3].",
                "• **De 10 GHz en adelante.** La Luna despolariza la señal, la polarización de transmisión ya no importa y hace falta un receptor de dos canales sobre dos alimentadores ortogonales [3]. Son frecuencias fuera de las bandas de YAEC.",
                "• **Qué polarización transmitir.** Si recibes una estación, puedes deducir con qué polarización transmitirle para que tu señal le llegue de la forma correcta [3]. Con los ángulos en grados (0° horizontal, 90° vertical), P es la polarización de transmisión de la otra estación, R aquella con la que la recibes, S el desplazamiento espacial, F la rotación de Faraday y T tu mejor polarización de transmisión:",
                "= R = P + S + F \\quad P = T − S + F \\quad T = 2 · S − R",
                "~ Eliminando F de las dos primeras relaciones se obtiene §T = 2 · P + 2 · S − R§; para una antena lineal §2 · P§ vale 0° o 180°, que es la misma polarización, y queda §T = 2 · S − R§ [3]. Sin rotación de Faraday (§F§ = 0, desde 1296 MHz en adelante) la mejor polarización para transmitir es la misma con la que se recibe mejor, §T = R§. El artículo señala que la regla coincide con la de KL7WE y cita el programa SKYMOON de W5UN para el cálculo de S [3].",
                "> En YAEC el desplazamiento espacial S es la §D_{pol}§ calculada en las pestañas Posición de la Luna y Posición en vivo y +- 24h; la rotación de Faraday F no se puede calcular. Para los ejemplos, los casos particulares y las figuras, lee el artículo completo de SM5BSZ [3].",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s",
                "[2] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, presentación, julio de 2015, facilitada por IC8TEM.",
                "[3] Leif Åsbrink SM5BSZ, “Selecting Polarisation for EME”, 25 de abril de 1997 – https://sm5bsz.com/polarity/emepol.htm"
            };
            d["es"]["S44"] = new string[] {
                "## Ruido del cielo y Dgrd",
                "La temperatura del cielo detrás de la Luna (§T_{sky}§) a 144 MHz se toma a lo largo de la eclíptica de una tabla en pasos de 2° (WSJT-X) y, en la vista Sky, de un mapa de todo el cielo con resolución de 2° derivado del Global Sky Model; las demás frecuencias se escalan con índice espectral 2,6:",
                "= T(f) = \\p{T_{144} − 2.7} · \\p{\\frac{144}{f}}^{2.6} + 2.7 \\t{ K}",
                "Dgrd, como en WSJT-X, suma el efecto de la distancia d de la Luna y el del ruido del cielo:",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2.6} \\t{ K}",
                "### Qué significa la Dgrd",
                "La **Dgrd** (*degradation*, degradación) indica cuántos dB es peor el eco de la Luna, en ese instante, que en las mejores condiciones posibles: Luna en el perigeo y cielo frío detrás de la Luna. No depende de la estación, sino solo de la Luna y del cielo: por eso sirve para elegir los días y las horas, no para calcular el enlace, que es la tarea del balance EME.",
                "• **0 dB** es el caso ideal; los valores son siempre negativos. **−3 dB** significa la mitad de la relación S/N respecto al caso ideal, **−6 dB** una cuarta parte.",
                "• El primer término de la fórmula es la **distancia**: entre el perigeo (unos 356 900 km) y el apogeo (unos 406 700 km) el eco cambia unos 2,3 dB, porque la pérdida de trayecto crece con la cuarta potencia de la distancia. Parece poco, pero duplicar las antenas solo hace ganar 3 dB en teoría [1].",
                "• El segundo término es el **ruido del cielo** detrás de la Luna: cuando la Luna pasa por delante de la Vía Láctea, la temperatura del cielo sube mucho y la Dgrd puede bajar varios dB, más de lo que pesa la distancia.",
                "• Los valores típicos son −1, −1,5 o −2 dB. Con la Luna sobre el centro de la Galaxia, I2FAK vio −11 dB, las peores condiciones posibles, y aun así completó un QSO con una estación muy débil, una DXpedición desde Yibuti, gracias a un sistema de 16 + 16 antenas: con condiciones tan malas la estación debe estar perfectamente calibrada, y la experiencia cuenta más que las previsiones del software [1].",
                "• Para una estación pequeña cada dB cuenta: un día con Dgrd de −1 dB y otro con −5 dB pueden marcar la diferencia entre un QSO completado y ninguna decodificación.",
                "> En el programa: el recuadro DGRD de la pestaña Posición en vivo y +- 24h muestra el valor actual entre el mínimo y el máximo del gráfico; la pestaña Distancia y Dgrd muestra el calendario de los próximos días, el gráfico con la distancia y los tres mejores días.",
                "### La Luna delante de las fuentes de ruido de la Galaxia",
                "Cada mes la Luna recorre la franja de la eclíptica (a menos de unos 5° de ella) y cruza dos veces la Vía Láctea. Los dos pasos no son iguales:",
                "• **Sagitario, centro de la Galaxia**: la zona más caliente del cielo; a 144 MHz la temperatura del cielo detrás de la Luna llega a algunos miles de K, frente a unos 200 K de las zonas frías, y esa zona es más ruidosa que el Sol [1]. Aquí la Luna está también en su declinación más baja, en torno a −30° en los años de declinación máxima: desde el norte de Italia (unos 45° N) sube solo hasta 15 – 16° de elevación y permanece por encima de 5° unas 6 horas (unas 7 horas sobre el horizonte), mientras que a +30° llega a unos 75° y permanece por encima de 5° unas 15 – 16 horas [1]. Es el peor periodo del mes.",
                "• **Tauro y Géminis, en el lado opuesto (anticentro)**: la Vía Láctea es mucho menos caliente, pero en Tauro, muy cerca de la eclíptica, está la **nebulosa del Cangrejo** (Taurus A), una de las radiofuentes más fuertes del cielo: cuando la Luna pasa por delante o al lado, el ruido aumenta.",
                "• El ruido del cielo crece al bajar la frecuencia: a 50 MHz pesa mucho más que a 144 MHz, a 432 MHz mucho menos (el programa lo escala con el índice espectral 2,6).",
                "> En el programa: la vista Sky colorea el cielo del azul (frío) al rojo (caliente) y muestra dónde está la Luna; la columna Tsky de la pestaña Posición de la Luna y el calendario de Distancia y Dgrd indican cuándo la Luna está delante de las zonas calientes.",
                "### La declinación de la Luna",
                "La **declinación** (§δ§) es la “latitud” de la Luna en el cielo: cuántos grados está al norte (+) o al sur (−) del ecuador celeste. El programa la calcula a partir de la fecha y la hora y la usa en todos los cálculos (elevación, ventanas, Tsky, Dpol, Doppler): no hay que introducirla. Pero conocerla ayuda a elegir los días.",
                "• **Ciclo mensual**: en unos 27,3 días la declinación va del máximo norte al máximo sur y vuelve. Con la Luna del lado de tu hemisferio (positiva en el norte, negativa en el sur) sube más alto y permanece más horas sobre el horizonte; del lado opuesto se queda baja y sobre el horizonte solo unas pocas horas [1].",
                "= El_{max} ≈ 90° − \\a{φ − δ} \\quad cos H_{0} = − tan φ · tan δ \\quad t_{su} = \\frac{2 · H_{0}}{15°} \\t{ h}",
                "~ §φ§ es la latitud de la estación, §H_{0}§ el ángulo horario en la salida y en la puesta de la Luna, §t_{su}§ las horas con la Luna sobre el horizonte (sin obstáculos y sin refracción). Ejemplo a 41° N: con §δ§ = +28° la Luna llega a unos 77° y permanece arriba unas 15,7 horas; con §δ§ = −28° se queda en unos 21° y permanece arriba unas 8,3 horas.",
                "• **Enlaces entre hemisferios**: en un QSO norte – sur las dos estaciones prefieren declinaciones opuestas; las ventanas comunes más largas suelen darse con la Luna cerca del ecuador celeste (declinación en torno a 0°), cuando ninguna de las dos estaciones está en desventaja.",
                "• **Ciclo de 18,6 años**: la amplitud de la oscilación mensual cambia lentamente, de unos ±18,3° a unos ±28,6°. El máximo (parada lunar mayor) se produjo en 2024 – 2025; hacia 2034 la oscilación será mínima, con meses menos extremos: la Luna ya no bajará tanto, pero tampoco subirá tan alto.",
                "• **Declinación y ruido**: la Luna alcanza su declinación más baja cuando pasa por delante de Sagitario, la zona más ruidosa del cielo, y la más alta en Tauro y Géminis, donde el cielo es más frío. Para las estaciones del hemisferio norte, la semana de declinación más baja reúne por tanto Luna baja, pocas horas útiles y Tsky alta [1].",
                "> En el programa: debajo del gráfico de la pestaña Distancia y Dgrd, la curva de declinación muestra los máximos norte y sur con su fecha; la zona verde indica cuándo la Luna está del lado de tu hemisferio (la curva se oculta con la casilla Curva de declinación). El valor de cada instante está en la columna opcional Declinación (°) de la pestaña Posición de la Luna y en la pestaña Posición en vivo y +- 24h.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["es"]["S45"] = new string[] {
                "### Por qué cuenta el Sol",
                "El **Sol** es la fuente de ruido más fuerte del cielo. Alrededor de la Luna nueva, el Sol y la Luna están cerca en el cielo: aunque el Sol quede fuera del lóbulo principal, entra por los lóbulos laterales, y a pocos anchos de haz el ruido recibido crece mucho. Por eso, en la práctica, la semana de la Luna nueva casi siempre conviene evitarla.",
                "• Cuánto pesa depende de la ganancia de la antena (lóbulo más estrecho, Sol más lejano en anchos de haz), del nivel de los lóbulos laterales y de la **actividad solar**: el flujo solar, en SFU, cambia de un día a otro y crece mucho durante las fulguraciones.",
                "• Por eso una antena con los **lóbulos laterales muy atenuados** es fundamental: los lóbulos laterales recogen el ruido de alrededor y lo suman al del lóbulo principal [1].",
                "• Durante un eclipse de Sol la Luna está justo delante del Sol: I2FAK completó aun así un QSO apuntando 2,5 – 3° a un lado de la Luna, de modo que el lóbulo estrecho de su sistema atenuaba el ruido del Sol [1].",
                "• El Sol por debajo del horizonte del receptor no cuenta, aunque sea Luna nueva.",
                "> En el programa: el calendario de Distancia y Dgrd marca con el símbolo ☀ los días con el Sol cerca de la Luna (naranja o rojo); la pestaña Ruido solar calcula, con el flujo medido, cuánto ruido adicional aporta el Sol en el instante elegido.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["pt"] = new Dictionary<string, string[]>();
            d["pt"]["S32"] = new string[] {
                "## O locator Maidenhead (WWL)",
                "O **locator Maidenhead**, também chamado WWL (World Wide Locator) ou QTH locator, é o código que os radioamadores usam para indicar a posição da sua estação. Foi concebido por John Morris G4ANB e adotado pelo Grupo de Trabalho VHF da IARU em abril de 1980, numa reunião em Maidenhead, Inglaterra; substituiu o antigo QRA locator, que cobria apenas a Europa [1]. Desde 1999 o datum geodésico é o WGS-84, o mesmo do GPS [1]. O YAEC obtém do locator a latitude e a longitude da estação e, a partir destas, todos os cálculos.",
                "### Como é construído",
                "O locator é uma série de pares: cada par indica primeiro a longitude e depois a latitude, e divide o retângulo do par anterior em partes mais pequenas. Os pares alternam letras e algarismos [1]. Um exemplo de 14 caracteres: **PM 95 UP 98 KB 75 MI** (Tóquio).",
                "@locator PM 95 UP 98 KB 75 MI",
                "|h| Par | Nome | Símbolos | >Divide em | >Dimensão (lon × lat) | >Caracteres | >Lado a 35,7° (Tóquio) | >Erro máximo",
                "| 1.º | campo (field) | A … R | 18 × 18 | 20° × 10° | 2 | – | –",
                "| 2.º | quadrado (square) | 0 … 9 | 10 × 10 | 2° × 1° | 4 | 181 × 111 km | ±106 km",
                "| 3.º | subquadrado (subsquare) | A … X | 24 × 24 | 5′ × 2,5′ | 6 | 7,5 × 4,6 km | ±4,4 km",
                "|+ 4.º | quadrado estendido | 0 … 9 | 10 × 10 | 30″ × 15″ | **8** | 753 × 463 m | **±442 m**",
                "| 5.º | subquadrado estendido | A … X | 24 × 24 | 1,25″ × 0,625″ | **10** | 31 × 19 m | **±18 m**",
                "| 6.º | – | 0 … 9 | 10 × 10 | 0,125″ × 0,0625″ | 12 | 3,1 × 1,9 m | ±1,8 m",
                "| 7.º | – | A … X | 24 × 24 | 0,0052″ × 0,0026″ | 14 | 13 × 8 cm | ±8 cm",
                "~ Dimensões segundo as regras de [1]; lados e erro máximo (metade da diagonal, com a estação no centro do retângulo) calculados pelo YAEC para a latitude de Tóquio: em direção aos polos o lado este-oeste fica mais curto. As letras escrevem-se em maiúsculas, como esclarecido pela IARU em 2019 [1]; o YAEC aceita também minúsculas e converte-as.",
                "> Para além dos 8 caracteres não existe uma norma comum: o 5.º par e os seguintes não estão formalmente definidos, e a prática mais comum, seguida pelo YAEC, repete as regras dos pares anteriores (letras em base 24, algarismos em base 10). Outros programas podem usar codificações diferentes, pelo que um locator longo pode não ser lido da mesma forma em todo o lado [1].",
                "### Quantos caracteres usar",
                "Em HF usa-se normalmente o quadrado (4 caracteres); nas bandas do YAEC, de 50 a 432 MHz, usa-se o subquadrado (6 caracteres) [1]. Estas regras aplicam-se às trocas de QSO e aos concursos: por exemplo, na Região 1 da IARU as distâncias medem-se entre os centros dos subquadrados [1]. Para os cálculos do YAEC a escolha é diferente:",
                "|h| Caracteres | Utilização recomendada no YAEC",
                "| 4 | apenas para uma estimativa grosseira: o azimute e a elevação da Lua podem errar até cerca de 1°, porque o horizonte local inclina-se cerca de 1° a cada 111 km",
                "| 6 | o locator do DX, os QSO e o budget EME: o erro na direção da Lua é de poucas centésimas de grau",
                "| **8** | a sua estação, para Reconnaissance of my obstacles: identifica o bairro ou a colina",
                "|+ **10** | a sua estação, com o melhor resultado: identifica o edifício ou a torre da antena",
                "| 12 – 14 | aceites, mas não acrescentam nada: a precisão ultrapassa a de um GPS comum (alguns metros) e a dimensão da própria antena",
                "### Locator e obstáculos",
                "Para a direção da Lua bastam 6 caracteres: a Lua está a cerca de 380 000 km, e os ±4,4 km de um locator de 6 caracteres alteram o azimute e a elevação em cerca de 0,04°, um valor desprezável face ao feixe da antena. Para os **obstáculos locais** (edifícios, árvores, colinas) é o contrário: estão a algumas dezenas ou centenas de metros da antena e, com 6 caracteres, a estação pode estar em qualquer ponto de um retângulo de 7,5 × 4,6 km, pelo que os obstáculos não podem ser posicionados. Com 8 caracteres o erro desce para cerca de 450 m, com 10 para cerca de 20 m: é esta a precisão de que o separador **Reconnaissance of my obstacles** precisa para desenhar corretamente as zonas em que a antena está obstruída.",
                ">+ Conselho prático: obtenha o locator de 10 caracteres a partir das coordenadas GPS do ponto onde está a antena (não da entrada da casa) e introduza-o no separador Posição em direto e +- 24h como **my locator**. Para o DX basta o locator de 6 caracteres que ele lhe fornece.",
                "[1] Wikipedia, “Maidenhead Locator System” (origem G4ANB e reunião VHF da IARU em Maidenhead em 1980, estrutura dos pares, WGS-84 desde 1999, extensões para além de 8 caracteres, esclarecimento da IARU de 2019, utilização em HF e VHF/UHF, distâncias entre centros de subquadrados) – https://en.wikipedia.org/wiki/Maidenhead_Locator_System"
            };
            d["pt"]["S46"] = new string[] {
                "### As fórmulas do budget EME",
                "A perda de percurso segue a equação do radar: o sinal vai da estação até à Lua, parte dele é difundida e regressa em direção à Terra. As distâncias §d_1§ e §d_2§ são as distâncias topocêntricas das duas estações no instante escolhido, pelo que a diferença entre perigeu e apogeu (cerca de 2,3 dB) já está incluída.",
                "= λ = \\frac{c}{f} \\quad σ = 0.065 · π · R_M^2",
                "= L_{EME} = 10 · log_{10} \\b{\\frac{\\p{4π}^3 · d_1^2 · d_2^2}{σ · λ^2}} \\t{ dB}",
                "~ com §c = 299 792 458 \\t{ m/s}§, §R_M = 1 737,4 \\t{ km}§ (raio da Lua), refletividade lunar 0,065.",
                "A potência irradiada e o sinal nos terminais da antena de receção:",
                "= EIRP = P_{dBW} − L_{TX} + G_{ant} + 10 · log_{10} N + G_g \\quad S_{ant} = EIRP + 30 − L_{EME} − L_{pol} + G_{RX}",
                "= G_g = 20 · log_{10} \\a{2 · sin \\p{\\frac{2π · h · sin El}{λ}}} \\quad L_{pol} = −20 · log_{10} \\a{cos D_{pol}}",
                "~ Ganho de solo (caixa de verificação “BETA- antenna without elevation”): antena de polarização horizontal à altura h, calculado na elevação da Lua, no máximo +6 dB.",
                "A figura de ruído da cadeia de receção obtém-se com a fórmula de Friis, em valores lineares (§F = 10^{NF/10}§, §G = 10^{G_{dB}/10}§):",
                "= F_{tot} = F_1 + \\frac{F_2 − 1}{G_1} + \\frac{F_3 − 1}{G_1 G_2} + … \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "A figura de ruído do rádio deriva do seu MDS, medido na largura de banda B:",
                "= NF_{radio} = MDS + 174 − 10 · log_{10} B",
                "= T_{sys} = T_{ant} + ΔT_{sky} + T_{sun} + T_e \\quad N = 10 · log_{10} \\p{k · T_{sys} · B} + 30 \\quad \\frac{S}{N} = S_{ant} − N",
                "~ com §k = 1,380649 · 10^{−23} \\t{ J/K}§ (Boltzmann) e B a largura de banda em Hz. §T_{ant}§ é a temperatura de antena das tabelas de VE7BQH (antena inclinada a 30°); §ΔT_{sky} = max \\p{0, T_{sky} − T_{ref}}§, com §T_{ref}§ = 200 K a 144 MHz escalada com índice 2,6.",
                "O budget EME não calcula uma margem sobre o modo: mostra a S/N estimada, referida à largura de banda de referência de 2500 Hz usada pelo WSJT-X, e ao lado o limiar típico do modo escolhido, apenas como referência. Um limiar não é um limite rígido: com as ajudas do descodificador, descodifica-se mesmo abaixo dele, como mostram a tabela do JT65 e as notas abaixo.",
                "= \\frac{S}{N}_{2500} = \\frac{S}{N}_{B} + 10 · log_{10} \\frac{B}{2500}",
                "|h| Modo | >Limiar típico, mensagem única (2500 Hz) | Fonte",
                "| JT65 | −25 dB | [1]",
                "| JT9 | −27 dB | [1]",
                "| JT4 | −23 dB | [1]",
                "| FT8 | ≈ −20 dB | [1]",
                "| FT4 | ≈ −16,5 dB | [1]",
                "| Q65-15A | −22,2 dB | [2]",
                "| Q65-30A | −24,8 dB | [2]",
                "| Q65-60A | −27,6 dB | [2]",
                "| Q65-120A | −30,8 dB | [2]",
                "| Q65-300A | −33,8 dB | [2]",
                "| WSPR | −31 dB | [1]",
                "~ Limiares para 50 % de probabilidade de descodificação, medidos num canal de ruído branco gaussiano aditivo (AWGN). Para o Q65, a descodificação *a priori* (AP), que usa os indicativos já conhecidos durante o QSO, acrescenta 1,5 a 3,6 dB consoante o submodo (por exemplo Q65-60A −30,2 dB) [2]; o YAEC mostra como referência os valores mais prudentes sem AP. Com um Doppler spread de alguns hertz o limiar piora: para o Q65-60A cerca de 2 dB a 5 Hz e cerca de 3 dB a 10 Hz (lido no gráfico de [2]). A estrutura do Q65, os seus submodos e a comparação com o JT65 estão no § 3.12. Para EME o documento recomenda Q65-60A em 50 e 144 MHz e Q65-60B em 432 MHz [2]: os submodos B – E têm espaçamento entre tons e largura de banda ocupada 2 – 16 vezes as do submodo A.",
                "Para o JT65, K1JT publicou os limites de cada tipo de descodificação, obtidos com simulações do submodo JT65B [5]:",
                "|h| JT65: tipo de descodificação | >S/N (2500 Hz) | Fonte",
                "| Qualquer mensagem, incluindo texto livre | −24 dB | [5]",
                "| Indicativo presente na base de dados (Deep Search) | −28 dB | [5]",
                "| Qualquer mensagem com média de várias transmissões | −29 dB | [5]",
                "| Só sincronização (tempo e frequência) | −30 dB | [5]",
                "| Mensagens abreviadas RO, RRR, 73 | −32 dB | [5]",
                "~ O guia do WSJT-X indica −25 dB para uma mensagem única [1]. A descodificação Deep Search só testa mensagens com CQ ou com o seu indicativo mais um indicativo e um locator da base de dados: um indicativo desconhecido ou um texto livre só são descodificados pelo descodificador geral, com média se necessário [5]. A descodificação é “tudo ou nada”: uma mensagem lê-se inteira ou não se lê, não piora aos poucos perto do limite [5]. Por isso o YAEC já não mostra os dB acima ou abaixo do limiar.",
                "### O ganho de solo na prática",
                "O ganho de solo da caixa de verificação “BETA- antenna without elevation” segue o modelo do terreno plano e refletor: o raio direto e o refletido somam-se quando a diferença de percurso é um número semi-inteiro n de comprimentos de onda e anulam-se quando é inteiro, com §n · λ = 2 · H · sin α§; o ponto de reflexão fica a uma distância §D = \\frac{H}{tan α}§ da antena [3]. Os ensaios de IK1UWL com os ecos da sua própria estação (4 × 14 elementos a 121 m acima do mar, costa da Ligúria) mostram que na prática as coisas são mais complicadas [3]:",
                "• os picos e os nulos são muitos e próximos, em ângulos fracionários que um simulador com passos de 1° como o EZNEC não vê: com a antena alta acima do mar sucedem-se aproximadamente a cada 3 minutos (3 períodos de JT65) e causam um forte QSB a baixa elevação, que não depende da ionosfera;",
                "• o ganho medido foi de cerca de 3 dB, e não os 6 dB teóricos: num agrupamento as yagis superiores e inferiores estão a alturas diferentes (4,5 m), as suas reflexões não estão em fase e só contribui um par de cada vez;",
                "• abaixo de 2° de elevação há um buraco de ganho e o máximo situa-se por volta de 5°; ao elevar a antena o efeito de solo diminui e, para lá da largura do feixe (cerca de 12° para o seu agrupamento), torna-se desprezável;",
                "• a refração conta: a Lua nasceu a −0,51°, abaixo do horizonte ótico de −0,35°; a 200 MHz, em ar seco, o erro de refração a 0° de elevação é de −0,49°.",
                "IK3XTV lembra que, em teoria, o efeito de solo chega a 6 dB, de modo que uma única yagi rende quase como um agrupamento de 4, mas depende muito do terreno à volta da antena: é menor na cidade, melhor em campo aberto e ainda mais perto do mar. Aproveita-se no nascer e no pôr da Lua, entre cerca de 1° e 18 – 20° de elevação [4].",
                "> Por isso, no budget EME, o ganho de solo está marcado como BETA: o valor calculado (no máximo +6 dB) é um limite teórico. Com antenas altas acima do mar ou agrupamentos de várias yagis, convém esperar cerca de metade e um QSB acentuado a baixa elevação [3].",
                "[1] WSJT-X User Guide, K1JT and the WSJT Development Group, § 7.1 (FT4 = FT8 + 3,5 dB).",
                "[2] J. Taylor K1JT, B. Somerville G4WJS, S. Franke K9AN, N. Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 de abril de 2021 (WSJT-X 2.4.0), fornecido por IC8TEM.",
                "[3] Giorgio Marchi IK1UWL, “Considerazioni sull'effetto suolo (Ground Gain)”, 21.º Meeting EME, apresentação fornecida por IC8TEM.",
                "[4] Flavio Egano IK3XTV, “EME (earth-moon-earth) con una singola Yagi in 144 MHz”, documento de 12 de novembro de 2010, fornecido por IC8TEM.",
                "[5] J. Taylor K1JT, comunicação sobre o JT65 na conferência EME 2006 (K1JT_eme2006.pdf): tabela dos níveis mínimos de S/N em 2500 Hz.",
                "> O esquema da estação, à direita do separador, obtém as perdas a partir dos cabos escolhidos: em transmissão cabo PA–relé + relé + cabo de antena, em receção cabo de antena + relé antes do pré-amplificador e cabo de descida depois dele. As atenuações dos cabos vêm da base de dados do separador COAXIAL CABLES (§ 3.8)."
            };
            d["pt"]["S47"] = new string[] {
                "## O pré-amplificador e a figura de ruído do rádio {nuovo}",
                "Em EME o sinal que chega à antena está apenas ligeiramente acima do ruído (cerca de −149 dBm no exemplo Tóquio – Cidade do Cabo). O pré-amplificador tem duas funções diferentes: **recuperar o sinal** perdido nos cabos até à estação e, sobretudo, **cobrir a figura de ruído do rádio**, que nos transcetores VHF/UHF comerciais vai de cerca de 3 – 5 dB com o pré-amplificador interno ligado até 15 – 16 dB e mais com ele desligado.",
                "A razão está na fórmula de Friis: cada andar pesa no ruído total dividido pelo ganho de tudo o que está antes dele. O primeiro andar decide quase tudo.",
                "= F_{tot} = F_{LNA} + \\frac{F_{cable} − 1}{G_{LNA}} + \\frac{F_{radio} − 1}{G_{LNA} · G_{cable}} \\quad T_e = 290 · \\p{F_{tot} − 1} \\t{ K}",
                "~. F e G em valores lineares (§F = 10^{NF/10}§); para um cabo com perda L em dB: §F_{cable} = 10^{L/10}§ e §G_{cable} = 10^{−L/10}§.",
                "@colonne 55",
                "#### Figura de ruído medida de alguns rádios",
                "|h| Rádio | >MHz | Pré-amp. | >NF (dB) | Fonte",
                "| Icom IC-9700 | 144 | desligado / ligado | 16 / 3 | [1]",
                "| Icom IC-9700 | 432 | desligado / ligado | 15 / 4 | [1]",
                "| Yaesu FT-991 | 50 | IPO / AMP1 / AMP2 | 29 / 17 / 8 | [2]",
                "| Yaesu FT-991 | 144 · 432 | – | 5 · 4 | [2]",
                "| Icom IC-275E | 144 | – | 5,6 | [3]",
                "| Icom IC-9100 | 144 · 432 | não indicado | ≈ 5 · ≈ 5 | [5]{r:*}",
                "| Icom IC-821H | 144 | – | 3,4 | [3]",
                "| Icom IC-910H | 144 | – | 3,7 | [3]",
                "| Icom IC-7000 | 144 | – | 5,6 | [3]",
                "| Kenwood TS-790E | 144 | – | 4,5 | [3]",
                "| Kenwood TS-2000 | 144 | ligado | 6,2 | [3]",
                "| Yaesu FT-847 | 144 | ligado / desligado | 5,1 / 6,7 | [3]",
                "| Yaesu FT-817 | 144 | – | 5,4 | [3]",
                "| Yaesu FT-857D | 144 | – | 6,1 | [3]",
                "| Icom IC-746PRO | 50 | desligado / P1 / P2 | 19 / 9 / 6 | [14]",
                "| Icom IC-746PRO | 144 | desligado / ligado | 14 / 5,2 | [14]",
                "| Yaesu FT-897 | 50 | ligado / IPO | 3,6 / 8,7 | [15]",
                "| Yaesu FT-897 | 144 · 432 | sempre ligado | 5,9 · 7,7 | [15]",
                "~ [1] [2] medições de VA7OJ com uma fonte de ruído calibrada; [3] medições de DF9IC com o método do fator Y, precisão ±0,5 dB, apenas 144 MHz, de 2005. Com o pré-amplificador interno ligado, o IC-9700 já satura entre −9 e −27 dBm a 144 MHz [1]. * Valor a verificar: ensaio preliminar numa unidade de pré-produção, autor não indicado. [14] NF obtida a partir do ruído de fundo (MDS) medido em 500 Hz: NF = MDS + 174 − 27 dB; com o pré-amplificador ligado a 144 MHz a gama dinâmica de bloqueio a 5 kHz desce de 99,9 para 88,4 dB. [15] NF obtida a partir da sensibilidade SSB para 10 dB (S+N)/N com o filtro de 2450 Hz: NF = S − 9,5 + 174 − 10·log B; em 144 e 432 MHz o pré-amplificador está sempre em circuito. Para [14] e [15] a precisão é indicativa, ±1 dB.",
                "@destra",
                "#### Exemplo: 35 m de Sivacavi HF 400 (1,6 dB) a 144 MHz",
                "|h| Configuração | >NF total | >Te | >Tsys | >Piora a S/N em",
                "| Só o rádio, pré-amplificador interno desligado (NF 16) | 17,6 dB | 16 398 K | 16 648 K | %bar:17.6:17.6:r%17,6 dB",
                "| Só o rádio, pré-amplificador interno ligado (NF 3) | 4,6 dB | 546 K | 796 K | %bar:4.4:17.6:o%4,4 dB",
                "| LNA na antena 0,5 dB / 20 dB + rádio NF 16 | 2,3 dB | 199 K | 449 K | %bar:1.9:17.6:y%1,9 dB",
                "| **LNA na antena 0,5 dB / 20 dB + rádio NF 3** | **0,6 dB** | 41 K | 291 K | %bar:0:17.6:g%{g:**referência**}",
                "~ §T_{sys} = T_{ant}§ 250 K + §T_e§; a comparação é feita com o mesmo sinal na antena.",
                "@fine",
                "Para a melhor configuração, com os valores substituídos:",
                "= F_{tot} = 1.1220 + \\frac{1.4454 − 1}{100} + \\frac{1.9953 − 1}{100 · 0.6918} = 1.1220 + 0.0045 + 0.0144 = 1.1409 \\quad ⇒ \\quad NF = 0.57 \\t{ dB}",
                ">! **Na prática.** O pré-amplificador deve ser montado na antena, antes do cabo de descida e logo a seguir ao relé coaxial (que deve protegê-lo durante a transmissão com um sequenciador). O seu ganho deve ser suficientemente elevado para tornar desprezáveis o cabo e o rádio: como regra, pelo menos 10 dB acima da soma da perda do cabo e da figura de ruído do rádio (no exemplo 1,6 + 16 ≈ 18 dB → com 20 dB o rádio ainda pesa 1,7 dB; com o pré-amplificador interno ligado pesa apenas 0,05 dB). Ganho a mais, porém, reduz a gama dinâmica do rádio: com um bom LNA na antena é muitas vezes preferível manter desligado o pré-amplificador interno e escolher um LNA de 20 – 26 dB. No budget EME estas escolhas fazem-se no esquema da instalação de receção, e o separador DEBUG FORMULE mostra o cálculo passo a passo.",
                "##+ O transverter (opcional)",
                "Com um transverter o rádio trabalha numa frequência intermédia (normalmente 28 MHz para 144 MHz) e o transverter passa a ser o andar que conta para o ruído: entra na fórmula de Friis depois do cabo de descida, e o rádio que se lhe segue pesa tanto menos quanto mais o transverter ganha.",
                "= F_{comb} = F_{XV} + \\frac{F_{radio} − 1}{G_{XV}} \\quad \\t{e.g. } F_{comb} = 1.2589 + \\frac{10 − 1}{50.12} = 1.4385 ⇒ NF = 1.58 \\t{ dB}",
                "~ exemplo: transverter com NF 1,0 dB e ganho 17 dB (valores mínimos do DEMI L144-28) à frente de um rádio HF com NF 10 dB.",
                "@colonne 56",
                "#### Gráfico: NF da combinação em função do rádio e do ganho do transverter",
                "@abaco Curvas calculadas com (3.7.3) para um transverter com NF 1,0 dB. Quanto mais o transverter ganha, menos o rádio pesa: com 25 dB de ganho um rádio com 20 dB de NF leva o total a 2,0 dB; com 10 dB de ganho o mesmo rádio leva o total a 10,5 dB.",
                "@destra",
                "#### Transverters para 144 MHz (FI 28 MHz)",
                "|h| Fabricante · modelo | >NF | >G RX | >TX | Fonte",
                "| DEMI L144-28 | < 1,0 dB | ≥ 17 dB | 25 / 50 W | [6]",
                "|+ **Kuhne (DB6NT) MKU 144 G2** (módulo) | 0,9 dB | 25 dB | 0,1 W¹ | [13]",
                "| Kuhne (DB6NT) TR 144 H +40 | 0,9 – 1,2 dB | 25 dB | 2 – 20 W | [7]",
                "| Kuhne (DB6NT) TR-144 Pro | {r:n.d.} | {r:n.d.} | 25 W | [8]",
                "| Q5 Signal L144-28M | < 1,0 dB | ≥ 20 dB | 25 / 75 / 150 W | [9]",
                "| HA1YA ME2T-PRO-II / ME2HT-PRO-II | 1,0 dB | ≤ 25 dB (ajustável) | 30 / 50 W | [10]",
                "| SSB-Electronic LT2S Mk II | {r:n.d.} | {r:n.d.} | – | [11]",
                "~ Valores declarados pelos fabricantes. MKU 144 G2: primeiro andar com NF 0,5 dB, IP3 de saída em receção +23 dBm, entrada FI 2 – 50 mW ou 60 – 2000 µW; ¹ excitador de 100 mW, a completar com um amplificador Kuhne de 60 ou 120 W. TR 144 H +40: contém o módulo MKU 144 G2, daí o ganho de 25 dB (informação de IC8TEM). Com 25 dB de ganho, à frente de um rádio com NF 10 dB o total é 0,99 dB, com NF 20 dB é 1,88 dB [13]. O manual da Kuhne indica 1,2 dB na tabela e 0,9 dB no texto; com o pré-amplificador Kuhne MKU LNA 144 A o total desce para 0,3 dB [7]. Q5 Signal L144-28M: NF máxima 1,0 dB com ganho de conversão mínimo de 20 dB, ganho RX-FI ajustável pelo utilizador para calibrar o S-meter; FI até 25 W [9]. HA1YA ME2T-PRO-II: NF global 1 dB (primeiro andar PGA103+ com NF 0,7 dB), ganho RX ajustável até 25 dB, OIP3 típico +35 dBm, IIP3 típico +10 dBm, rejeição de imagem > 80 dB, entrada FI de −20 a +37 dBm [10].",
                "#### Combinações medidas (DF9IC, 144 MHz)",
                "|h| Rádio + transverter | Pré-amp. do rádio | >NF",
                "| Elecraft K2 + Kuhne TR144H+40 | – | 1,0 dB",
                "| IC-756PRO II + Kuhne TR144H | desligado | 1,0 dB",
                "| IC-746 + Kuhne TR144H+40 | desligado | 1,2 dB",
                "| FT-1000MP + Javornik (duas unidades) | desligado | 0,9 · 1,4 dB",
                "| FT-1000 Mark V + Kuhne TR144H, FI 14 MHz | desligado | 1,6 dB",
                "| FT-1000 Mark V + Kuhne TR144H, FI 28 MHz | desligado / ligado | 6,0 / 1,7 dB",
                "| TS-870 + Javornik | desligado | 1,9 dB",
                "| Elecraft K2 + XV144 | ligado | 6,0 dB",
                "~ Fonte [3]. O caso do FT-1000 Mark V a 28 MHz mostra o gráfico na prática: com o pré-amplificador do rádio desligado o rádio pesa muito (6,0 dB), com o pré-amplificador ligado desce para 1,7 dB.",
                "@fine",
                "##+ Estações EME com FT-1000MP e transverter",
                "Dois exemplos documentados do FT-1000MP usado em EME em 144 MHz com transverter: as medições de DF9IC [3] sobre FT-1000MP + transverter Javornik (NF 0,9 – 1,4 dB com o pré-amplificador do rádio desligado) e a estação EME de **W3SZ** [12] (4 × M2 2MXP32, pré-amplificadores LNA Technology na antena para cada polarização, LMR-600 e hardline Andrew), que em transmissão usa um **FT-1000MP Mark V** com um transverter **SSB-Electronic LT2S Mk II** (FI 28 MHz) e um amplificador 2 × GU-74B, enquanto em receção usa o hardware WSE e o software Linrad de SM5BSZ.",
                "> No budget EME o transverter é um bloco do esquema da estação: ativa-se com a sua caixa de verificação, escolhe-se o modelo na lista (ou “custom”) e o programa obtém a sua figura de ruído e o seu ganho; desativado, não entra no cálculo. O gráfico acima ajuda a decidir se se deve ligar o pré-amplificador do rádio.",
                ">! ✉ **Conhece outro transverter ou construiu um?** Se quiser dar a conhecer outros transverters ou o seu próprio transverter, escreva um e-mail ao autor: ccerrotta@gmail.com ou ic8tem@gmail.com. Todos os contactos estão no separador **AUTHOR CONTACTS AND ACKNOWLEDGEMENTS**.",
                "##+ O sequenciador TX/RX",
                "Com um amplificador de potência (PA) e um pré-amplificador junto à antena (PRE), o PTT do computador não vai para o rádio mas para um **sequenciador**, que comanda os relés e depois o PA e o rádio pela ordem certa [16]. O esquema mais usado tem dois cabos de descida: o de receção pode perder alguns dB, porque fica depois de um pré-amplificador de 15 – 20 dB, enquanto o de transmissão deve perder o menos possível (3 dB em transmissão reduzem para metade a potência irradiada). Em repouso, os relés mantêm o PRE isolado da antena: uma proteção extra contra as descargas das trovoadas [16].",
                "|h| ^Passo | De RX para TX | De TX para RX",
                "| ^1 | os relés comutam a frio: rádio → entrada do PA, antena → saída do PA, PRE isolado | o rádio deixa de transmitir",
                "| ^2 | o PA é ligado | o PA é desligado",
                "| ^3 | o rádio passa a transmitir | os relés voltam à receção, sem potência aplicada",
                "~ Entre um passo e o seguinte é preciso pelo menos o tempo de comutação dos relés (15 – 30 ms) mais os seus ressaltos: IK1UWL aconselha 100 – 200 ms, também para o PA se tiver relés internos [16].",
                "Para o comando de transmissão, o PTT é melhor do que o VOX: o VOX pode disparar com um ruído e não aproveita o atraso de cerca de 0,5 s com que o JT65 começa a modular depois do PTT, pelo que o pré-amplificador fica protegido apenas pelo relé rápido do amplificador; com o PTT, esse atraso comuta o amplificador antes da modulação e pode acrescentar-se o sequenciador [17].",
                ">! **Atenção ao pré-amplificador.** O relé T/R deve isolar muito bem a porta aberta: com 50 dB de isolamento e 500 W na antena chegam 5 mW à entrada do PRE. Procura-se ter pelo menos 60 dB, e os mais prudentes acrescentam um segundo relé que em transmissão fecha o PRE sobre uma carga de 50 Ω. O botão PTT do microfone deve ser desativado: a partir daí transmite-se apenas através do sequenciador (em SSB, um pedal no PTT do sequenciador, desacoplado do do PC) [16].",
                "[1] Adam Farson VA7OJ/AB4OJ, “Icom IC-9700 Test Report”, edição 5, 19 de março de 2021 (primeira edição 19 de junho de 2019), tabelas 1 e 5 – https://www.qsl.net/ab4oj/icom/ic9700/9700notes.pdf",
                "[2] Adam M. Farson VA7OJ/AB4OJ, “Yaesu FT-991 Test Report”, 25 de julho de 2015, tabela 1 – https://www.qsl.net/ab4oj/test/docs/ft991notes.pdf",
                "[3] DF9IC com DARC OV Durlach A35, “Test of the Large Signal Behaviour of some 144 MHz Radios”, ensaios de 27 de fevereiro de 2005 – https://www.df9ic.de/tech/trxtest/trxtest.html",
                "[4] H. T. Friis, “Noise Figures of Radio Receivers”, Proceedings of the IRE, vol. 32 (1944).",
                "[5] Ensaio preliminar “ICOM IC-9100 review” numa unidade de pré-produção emprestada pela Icom UK (autor e data não indicados) – https://manualmachine.com/icom/ic9100/26837637-review",
                "[6] Down East Microwave, “L144-28 Rev B” – guia do utilizador (especificações: NF < 1,0 dB com ganho de conversão ≥ 17 dB) – https://manualmachine.com/demi/l14428revb/26842141-user-guide",
                "[7] Kuhne electronic, “TR 144 H +40” – manual do utilizador – https://manuals.online/kuhne-electronic/transceiver/tr-144-h-40/user-manual/191pa",
                "[8] RigPix, “Kuhne TR-144 Pro” – https://rigpix.com/transverters/kuhne_tr144pro.htm",
                "[9] Q5 Signal, “VHF/UHF Transverters – L144-28M REV 2”, manual (8 páginas), janeiro de 2023, fornecido por IC8TEM – http://q5signal.com/image/catalog/L144-28Mr2.pdf",
                "[10] HA1YA (Mechanics & Electronics), “ME2T-PRO-II & ME2HT-PRO-II 144MHz Transverter”, 25.09.2023, fornecido por IC8TEM – http://www.ha1ya.hu/pdf/me2tpro2transverter.pdf",
                "[11] SSB-Electronic LT2S Mk II – citado em [12]",
                "[12] Roger Rehr W3SZ, descrição da estação EME – https://w3sz.com/EMEFrame1Source1.htm",
                "[13] Kuhne electronic GmbH, “MKU 144 G2 – Transverter module, 144 … 146 MHz, 28 … 30 MHz IF”, folha de dados (2 páginas), fornecida por IC8TEM",
                "[14] ARRL Laboratory, “Icom IC-746PRO”, QST Product Review, maio de 2002 – https://www.radiomanual.info/schemi/ICOM_HF/IC-746Pro_review_ARRL_2002.pdf",
                "[15] Peter Hart G3SJX, “The Yaesu FT-897 HF/VHF/UHF Transceiver”, RadCom (RSGB), abril de 2003, pp. 18–20 – http://www.radiomanual.info/schemi/YAESU_HF/FT-897_review2_2003.pdf",
                "[16] Giorgio Marchi IK1UWL, “EME (Earth-Moon-Earth) – Guida operativa”, janeiro de 2012, § 4 “Sequenziamento relè, PA e PRE”, fornecido por IC8TEM – http://www.qsl.net/ik3xtv",
                "[17] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, apresentação, julho de 2015, fornecida por IC8TEM."
            };
            d["pt"]["S48"] = new string[] {
                "## Cabos coaxiais e perdas",
                "O separador **COAXIAL CABLES** reúne a atenuação dos cabos de 50 Ω mais usados pelos radioamadores, em dB por 100 m a 20 °C, nas cinco bandas do YAEC. As folhas de dados dos fabricantes dão valores em frequências diferentes; o YAEC levou-os às bandas com a lei de potência, uma reta no gráfico log-log entre as duas frequências mais próximas da folha de dados:",
                "= α(f) = α_1 · \\p{\\frac{f}{f_1}}^{n} \\quad n = \\frac{log \\p{α_2 / α_1}}{log \\p{f_2 / f_1}} \\quad L = α(f) · \\frac{ℓ}{100}",
                "~ α em dB/100 m, ℓ comprimento do cabo em metros. Um número simples é o valor da folha de dados; ≈ indica um valor interpolado, e e um valor extrapolado para além da última frequência da folha de dados.",
                "Os cabos do mesmo tipo, com o mesmo diâmetro dentro de ±0,2 mm e atenuação dentro de 0,2 dB/100 m em todas as bandas, são agrupados numa única linha (≡), com o valor médio; os nomes equivalentes são indicados com “also:” (por exemplo LMR-400 = HF400, CNT-400, 50-7 low loss; LMR-600 = CNT-600). Os nomes chineses 50-3, 50-5, 50-7, 50-9, 50-12 indicam o diâmetro do dielétrico em milímetros.",
                "> É possível acrescentar cabos personalizados com as suas cinco atenuações: são guardados em data\\cavi_personali.txt e aparecem também nas listas pendentes do esquema da estação do budget EME. A dica (tooltip) de cada linha da tabela cita a fonte desse cabo.",
                "[1] As fontes de cada cabo: folhas de dados da Times Microwave (LMR), RFS (CELLFLEX LCF/SCF), CommScope Andrew (HELIAX LDF/FSJ), Siva Cavi (HF 240/287/400), SSB-Electronic (Aircell, Ecoflex, Aircom Plus), Messi & Paoloni (Hyperflex, Ultraflex, via WiMo), Symair, SYV50-7 (szansy.com), Belden (H1000), Prospecta (RT5020, XT2400), QAXIAL (LLF195), Caledonian Cables, catálogo MIL-C-17F (RG-142, RG-393), R.F. elettronica de Senago (RG-115), as tabelas de DD1US e EA5IP (H100) e a tabela de SV1BSX para RG-58, RG-213, H-155 e H-2000 (valores a verificar)."
            };
            d["pt"]["S410"] = new string[] {
                "## Doppler, compensação e CFOM",
                "A Lua aproxima-se e afasta-se das duas estações devido à rotação da Terra e ao seu próprio movimento orbital: a distância R varia algumas centenas de metros por segundo e o sinal regressa deslocado em frequência. O desvio é máximo quando a Lua nasce ou se põe, passa por zero quando transita a sul (ou a norte) e é proporcional à frequência. O YAEC calcula-o a cada segundo no ecrã principal, no cartão **Echo and frequencies (CFOM)**.",
                "### Qual a dimensão do Doppler",
                "Para o eco da própria estação o percurso é feito duas vezes (ida e volta):",
                "= f_{D,echo} = − \\frac{2f}{c} · \\frac{dR}{dt} \\quad \\t{e.g. } − \\frac{2 · 144.120 · 10^6}{299 792} · 0.222 = −213 \\t{ Hz}",
                "com f a frequência em Hz, c = 299 792 km/s e dR/dt a velocidade radial da Lua em km/s (positiva quando se afasta). Para o sinal do DX contam os dois troços, o dele e o seu:",
                "= f_{D,DX} = − \\frac{f}{c} · \\p{\\frac{dR_{me}}{dt} + \\frac{dR_{DX}}{dt}} \\quad \\t{e.g. } −480.7 · \\p{0.222 − 0.339} = +56 \\t{ Hz}",
                "~ exemplo: Tóquio PM95 e Cidade do Cabo JF96, 06/11/2026 01:55 UTC, 144,120 MHz; dR/dt = +0,222 km/s em Tóquio e −0,339 km/s na Cidade do Cabo (valores do YAEC).",
                "@colonne 62",
                "|h| Banda | >Doppler máximo do eco | >Compensação",
                "| 50 MHz | ≈ ±120 Hz | não necessária",
                "| 70 MHz | ≈ ±165 Hz | não necessária",
                "| 144 MHz | até ≈ 340 Hz [1] | recomendada",
                "| 222 MHz | ≈ ±525 Hz | necessária",
                "| 432 MHz | até ≈ 1000 Hz [1] | necessária",
                "~ Valores para 144 e 432 MHz de [1]; 50, 70 e 222 MHz obtidos proporcionalmente à frequência (≈ = derivado).",
                "@destra",
                "> Em 50 e 144 MHz o Doppler fica quase sempre dentro do waterfall do programa digital e o descodificador encontra-o sozinho; em 432 MHz pode levar o sinal para fora da banda passante, e durante um período de 60 s varia alguns hertz, o suficiente para parecer deriva nos modos lentos [2].",
                "@fine",
                "### Compensar: quem corrige o quê",
                "Compensar o Doppler significa deslocar a frequência de transmissão, a de receção ou ambas, para que os sinais se encontrem na frequência combinada (o *sked*). Cada estação corrige o seu próprio Doppler e, quando trabalha um DX, também o do DX [1]:",
                "|h| Situação | Transmissão | Receção",
                "| Chamada CQ e escuta do próprio eco | na frequência do sked | sked + Doppler do eco (3.10.1)",
                "| QSO com um DX conhecido (Doppler total em direção ao DX) | corrigida para que o DX o receba no sked | sked + Doppler DX → eu (3.10.2)",
                "| CFOM, frequência constante na Lua | sked − metade do próprio Doppler | sked + metade do próprio Doppler",
                "### CFOM – Constant Frequency On Moon",
                "Com o CFOM todas as estações comportam-se como se um transmissor virtual na Lua estivesse sintonizado no sked: cada uma corrige apenas metade do seu **próprio** Doppler em transmissão e metade em receção, sem precisar de conhecer o locator da outra estação [2]:",
                "= f_{TX} = f_{sked} − \\frac{f_{D,echo}}{2} \\quad f_{RX} = f_{sked} + \\frac{f_{D,echo}}{2}",
                "|h| Exemplo (Tóquio, Doppler do eco −213 Hz) | >Frequência",
                "| Sked | 144,120000 MHz",
                "| Transmitir em (sked + 106,5 Hz) | {r:**144,120107 MHz**}",
                "| Receber em (sked − 106,5 Hz) | {g:**144,119894 MHz**}",
                "A vantagem é que várias estações, e quem esteja apenas a escutar, podem acompanhar um QSO na mesma frequência sem recalcular o Doppler para cada uma. O YAEC mostra estas duas frequências no ecrã principal.",
                "### O CAT do rádio",
                "O Doppler varia continuamente, pelo que a compensação deve ser atualizada a cada período. A forma mais simples é deixá-la ao programa digital (por exemplo a janela *Astronomical Data* do WSJT-X) que, através do **CAT** do rádio, define os VFO de transmissão e de receção e mantém o rádio alinhado na frequência certa [1] [2]. Sem CAT pode usar-se o split (um VFO para transmissão e outro para receção) ou o RIT, ajustando à mão a cada período: em 50 e 144 MHz é viável, em 432 MHz torna-se incómodo [1].",
                "> Atenção: para o CFOM o rádio tem de aceitar a mudança de frequência via CAT **também durante a transmissão**. Alguns equipamentos não o fazem (por exemplo o FT-897 citado em [2]): nesse caso pode-se continuar a receber em CFOM, enquanto a transmissão fica numa frequência fixa. Com um transverter (§ 3.7) o CAT define o rádio na frequência intermédia: configure o desvio do transverter no programa, para que a frequência mostrada seja a real.",
                "[1] Bob Atkins KA1GT, “Doppler 101 for 1296 MHz EME (…and other bands)” (do artigo usam-se apenas os dados até 432 MHz) – https://bobatkins.com/radio/EME_doppler_101.html",
                "[2] Bob Atkins KA1GT, “CFOM – Constant Frequency On Moon Doppler Mode” – https://bobatkins.com/radio/CFOM.html"
            };
            d["pt"]["S411"] = new string[] {
                "## Apontamento: precisão, encoders e atuadores",
                "O YAEC calcula o azimute e a elevação da Lua ao centésimo de grau, mas o sinal só chega se a antena a seguir realmente. Quanto mais estreito o feixe, mais conta a precisão mecânica do apontamento: nas bandas do YAEC (50 – 432 MHz) basta um bom rotor, enquanto as parabólicas das bandas superiores precisam de um verdadeiro sistema de atuação.",
                "### Quanto se perde ao apontar mal",
                "Com um erro de apontamento Δ e uma largura de feixe a meia potência θ (estimada pelo YAEC com §θ ≈ \\sqrt{41253/G}§), a perda é aproximada pela fórmula do feixe gaussiano:",
                "= L_{point} ≈ 12 · \\p{\\frac{Δ}{θ}}^2 \\t{ dB} \\quad \\t{e.g. } 12 · \\p{\\frac{3.6}{14.4}}^2 = 0.75 \\t{ dB}",
                "~ exemplo: 4 yagis de 17 dBi em 144 MHz, ganho total 23 dBi, θ ≈ 14,4°; um erro de um quarto do feixe (3,6°) custa cerca de 0,75 dB. Em EME a perda paga-se duas vezes, em transmissão e em receção. Fórmula aproximada, válida para erros pequenos face ao feixe.",
                "### Resolução do encoder",
                "A posição da antena é lida por um encoder (ou por um potenciómetro convertido para digital): com n bits a volta completa é dividida em §2^n§ passos e o passo mais pequeno é",
                "= Δ = \\frac{360°}{2^n} \\quad \\t{e.g. } n = 10: \\frac{360°}{1024} = 0.35°",
                "|h| ^Encoder | >Passos por volta | >Passo | >Perda com o agrupamento de 4 yagis (θ 14,4°, erro de 1 passo) | Adequado para",
                "| 8 bit | 256 | 1,406° | 0,114 dB | agrupamentos de yagis em 50 e 144 MHz",
                "| 10 bit | 1 024 | 0,352° | 0,007 dB | 144 MHz com margem, 432 MHz com agrupamentos pequenos",
                "| 12 bit | 4 096 | 0,088° | < 0,01 dB | 432 MHz com agrupamentos grandes",
                "| 14 bit | 16 384 | 0,022° | < 0,01 dB | parabólicas a 10 e 24 GHz [1]",
                "| 16 bit | 65 536 | 0,005° | < 0,01 dB | mais além: limite imposto pela mecânica, não pelo encoder",
                "~ Passo e perda calculados com (3.11.2) e (3.11.1). Uma regra prática é manter o erro abaixo de um décimo do feixe: o agrupamento de 4 yagis em 144 MHz fica satisfeito com 8 bits, uma parabólica de 3 m a 10 GHz (feixe ≈ 0,7°) precisa de pelo menos 13 – 14 bits.",
                "> O número de bits indica apenas com que finura a posição é *lida*: a precisão real depende também das folgas mecânicas, da flexão do suporte, do vento e da calibração do norte e do horizonte.",
                "### Agrupamentos de yagis: atuadores e roldanas",
                "Nos agrupamentos de yagis (combinações de 2, 4 ou mais antenas) a carga em elevação é grande e desequilibrada. Existem no mercado atuadores lineares com motor de parafuso sem-fim: nestas soluções o parafuso apenas regula o movimento, enquanto a sustentação mecânica da carga é confiada a roldanas. O parafuso sem-fim tem a vantagem de não rodar para trás sob a carga, pelo que o agrupamento fica parado mesmo com o motor desligado.",
                "### Acima de 432 MHz: parabólicas",
                "De 902 MHz para cima usam-se sobretudo antenas parabólicas, e a ferramenta [1] foi concebida para frequências a partir de 1 GHz. Com diâmetros grandes o feixe estreita para poucas décimas de grau e há o risco de não acertar perfeitamente na Lua: mais do que motores, a estação precisa de verdadeiros atuadores mecânicos em azimute e elevação, com uma precisão de apontamento largamente ligada à resolução em bits do controlo. A **EME Link Budget & Analysis Tool** de OE2IGL e DF3GJ [1] indica ±0,035° para um bom sistema de seguimento e ±0,1° para um normal, e calcula a perda de apontamento juntamente com todos os outros termos da ligação.",
                ">+ O YAEC fica pelos 432 MHz. Para as bandas superiores recomendamos a ferramenta de OE2IGL e DF3GJ [1]: calcula o budget EME de 1 a 300 GHz com os parâmetros da parabólica (diâmetro, f/D, alimentador, rugosidade da superfície, eficiências), apontamento, libração, ruído do Sol e da Lua e atenuação atmosférica.",
                "[1] Gerald Ihninger OE2IGL e Joachim Köppen DF3GJ, “EME Link Budget & Analysis Tool (1-300 GHz)” – https://wettersat.bplaced.net/EME/EME.html"
            };
            d["pt"]["S412"] = new string[] {
                "## Modos digitais para EME: Q65 e JT65",
                "O budget EME (§ 3.6) mostra a S/N estimada ao lado do limiar típico do modo digital escolhido. Esta secção explica de onde vêm os limiares do **Q65**, como é construído o sinal e porque é que o Q65 substituiu hoje em grande parte o JT65 para EME nas bandas do YAEC. Os dados vêm de três documentos: o guia de início rápido dos autores do Q65 [1], a comparação JT65A – Q65-60A de K1JT [2] e o estudo do processo de codificação de G4JNT [3].",
                "### O que é o Q65",
                "O Q65 foi introduzido com o WSJT-X 2.4.0 por K1JT, G4WJS, K9AN e IV3NWV para QSO mínimos em percursos particularmente difíceis; quando o Doppler spread ultrapassa alguns hertz é o mais sensível dos modos do WSJT-X, e adequa-se a troposcatter, rain scatter, dispersão ionosférica, TEP e EME de VHF para cima [1]. Usa FSK de **65 tons** e deriva do QRA64 de 2016; em relação a este, introduz [1]:",
                "• um novo código corretor de erros Q-ary Repeat Accumulate de baixa taxa, proposto por Nico Palermo IV3NWV [3] [4];",
                "• mensagens e sequenciação idênticas às de FST4, FT4, FT8 e MSK144;",
                "• um tom de sincronismo bem visível no waterfall e uma “curva de sincronismo” sensível, eficaz mesmo com pings de meteoros;",
                "• submodos com períodos T/R de 15, 30, 60, 120 e 300 s e espaçamentos entre tons diferentes;",
                "• descodificação por lista para mensagens que contêm partes já recebidas, **sem base de dados de indicativos**;",
                "• média de mensagens, quando as transmissões individuais são demasiado fracas, e descodificação múltipla em toda a banda recebida.",
                "### Os submodos",
                "O nome do submodo junta o período T/R e uma letra para o espaçamento entre tons: Q65-60A, Q65-120C e assim por diante. Para os submodos A a tabela apresenta os limiares medidos por simulação num canal de ruído branco gaussiano aditivo (AWGN), como S/N em 2500 Hz com 50 % de probabilidade de descodificação, sem e com a máxima informação *a priori* (AP) [1].",
                "|h| >T/R (s) | >Símbolo (s) | >Espaçamento A (Hz) | >Largura de banda A (Hz) | >Transmissão (s) | >S/N (dB) | >S/N AP máx. (dB)",
                "| 15 | 0,150 | 6,667 | 433 | 12,8 | −22,2 | −23,7",
                "| 30 | 0,300 | 3,333 | 217 | 25,5 | −24,8 | −26,6",
                "| 60 | 0,600 | 1,667 | 108 | 51,0 | −27,6 | −30,2",
                "| 120 | 1,333 | 0,750 | 49 | 113,3 | −30,8 | −32,5",
                "| 300 | 3,456 | 0,289 | 19 | 293,8 | −33,8 | −37,4",
                "~ Dados de [1]. Os submodos B, C, D e E têm espaçamento entre tons e largura de banda ocupada 2, 4, 8 e 16 vezes as do submodo A; nem todas as combinações existem (por exemplo 15D e 30E não existem) [1].",
                "Os números da tabela decorrem de algumas relações, verificadas pelo YAEC com os valores de [1]: o espaçamento A é o inverso da duração do símbolo, a transmissão dura 85 símbolos e a largura de banda ocupada é de 65 espaçamentos.",
                "= Δf = \\frac{k}{t_s} \\quad k = 1, 2, 4, 8, 16 \\t{ (A … E)} \\quad T_{tx} = 85 · t_s \\quad B_{occ} = 65 · Δf",
                "~ exemplo Q65-60A: §t_s§ = 0,600 s → Δf = 1,667 Hz, §T_{tx}§ = 51,0 s, §B_{occ}§ = 108 Hz. Passando de 60 para 120 s o limiar melhora 3,2 dB, perto dos 10 · log(113,3 / 51,0) = 3,5 dB esperados pela transmissão mais longa.",
                "### Sensibilidade e Doppler spread",
                "Os limiares da tabela aplicam-se sem dispersão do sinal. Em EME a Lua alarga cada tom em alguns hertz (Doppler spread, ou *libration fading*), e o limiar piora. Do gráfico de [1] para o Q65-60A sem AP:",
                "|h| >Doppler spread (Hz) | >S/N a 50 % (dB) | >Perda (dB)",
                "| 0 | ≈ −27,4 | –",
                "| 5 | ≈ −25,6 | ≈ 1,8",
                "| 10 | ≈ −24,6 | ≈ 2,8",
                "| 20 | ≈ −23,2 | ≈ 4,2",
                "~ Valores lidos pelo YAEC na figura 2 de [1] interpolando entre os pontos (≈ = derivado). A descodificação continua eficaz até um spread de cerca de dez vezes o espaçamento entre tons, e mesmo além [1]: é por isso que para spreads maiores se escolhem submodos com uma letra mais alta.",
                "> No YAEC os limiares de referência são sem spread e sem AP: servem para comparar dias, bandas e estações. Se no seu percurso o sinal estiver muito disperso, tenha em conta a perda da tabela, ou configure o modo *custom* com o limiar corrigido.",
                "### As mensagens do QSO a 60 s: Q65-60A, Q65-60B e Q65-60C",
                "Num QSO mínimo as seis mensagens padrão do WSJT-X (TX1 … TX6) não são todas recebidas da mesma forma: o descodificador pode usar as partes já conhecidas (descodificação *a priori*, AP), e a quantidade de informação conhecida cresce durante o QSO [1]. A tabela compara os três submodos mais usados em EME com o mesmo período de 60 s.",
                "|h| Mensagem | Exemplo | >AP na receção | >Q65-60A | >Q65-60B | >Q65-60C",
                "| TX6 – chamada | CQ W9XYZ EN37 | >q1 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX1 – resposta com locator | W9XYZ K1ABC FN42 | >q2 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX2 – relatório | K1ABC W9XYZ −25 | >q3 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX3 – R e relatório | W9XYZ K1ABC R−26 | >q3 | >−27,6 · AP: n.d. | >−27,6 · AP: n.d. | >−27,6 · AP: n.d.",
                "| TX4 – confirmação | K1ABC W9XYZ RRR | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| TX5 – cumprimentos | W9XYZ K1ABC 73 | >q4 | >−27,6 → −30,2 | >−27,6 → −30,2 | >−27,6 → −30,2",
                "| Espaçamento entre tons | – | – | >1,667 Hz | >3,333 Hz | >6,667 Hz",
                "| Largura de banda ocupada | – | – | >108 Hz | >217 Hz | >433 Hz",
                "| Spread ainda descodificável (≈ 10 × espaçamento) | – | – | >≈ 17 Hz | >≈ 33 Hz | >≈ 67 Hz",
                "| Com 5 Hz de Doppler spread, sem AP | – | – | >≈ −25,6 | >perda menor (n.d.) | >perda menor (n.d.)",
                "~ S/N em dB referida a 2500 Hz, 50 % de probabilidade de descodificação. −27,6 dB sem AP e −30,2 dB com a AP máxima são os valores do Q65-60A em [1]; para os submodos B e C são derivados da teoria: sem spread a sensibilidade depende da duração do símbolo (0,600 s), igual nos três submodos, e não do espaçamento. “n.d.” = não disponível: [1] dá apenas o ganho máximo da AP (2,6 dB a 60 s), não o dos níveis q1, q2 e q3, que é menor. Indicadores q1 … q4 como na tabela do § “Configurações recomendadas no WSJT-X”; spread descodificável e valor a 5 Hz de [1] e da tabela do Doppler spread acima. K1ABC, W9XYZ e os locators são exemplos.",
                ">! Esta tabela comparativa é derivada da análise dos dados em nossa posse sobre a teoria de funcionamento do Q65, e não reflete de todo o que acontece realmente, devido ao ruído natural e antrópico (de origem humana) captado em direto durante a receção.",
                "### Que submodo para EME",
                "Para as bandas do YAEC os submodos recomendados em [1] são:",
                "|h| Utilização | Submodo",
                "| EME em 50 e 144 MHz | Q65-60A",
                "| EME em 432 MHz | Q65-60B",
                "| Dispersão ionosférica em 50 MHz | Q65-30A",
                "| Dispersão ionosférica de baixa potência em 50 MHz | Q65-120E",
                "| TEP em 50 MHz | Q65-15C, Q65-30C",
                "| Dispersão ionosférica em 144 MHz | Q65-60C",
                "~ De [1], apenas para as bandas até 432 MHz. Os autores incentivam a experimentar outras combinações.",
                "O período de 30 s duplica o ritmo de QSO com sinais relativamente fortes, o período de 120 s ganha cerca de 3 dB por transmissão individual [2].",
                "### Q65 e JT65 comparados",
                "O **JT65A** foi o modo EME da banda dos 6 metros durante quase vinte anos: com a descodificação *Deep Search* chega a −28 dB em 2500 Hz (−29 dB com a média de mensagens, § 3.6), cerca de 15 dB abaixo do nível necessário para copiar CW de ouvido, mas apenas para as estações listadas na base de dados CALL3.TXT de indicativos e locators. Nesses QSO transmite-se na realidade muito pouca informação: cerca de 14 bits para um indicativo e locator escolhidos da base de dados, mais um relatório de 1 bit e uma confirmação de 1 bit [2].",
                "O **Q65** envia sempre mensagens de 78 bits: mesmo um QSO mínimo transporta um indicativo arbitrário (29 bits), um relatório numérico real (7 bits) e a confirmação (1 bit), sem base de dados [2]. K1JT preparou dez ficheiros simulados com sinais a −29 dB e 1 Hz de Doppler spread, cinco JT65A e cinco Q65-60A por ficheiro, e tentou descodificá-los de quatro formas, com 50 descodificações possíveis por ensaio [2]:",
                "|h| Ensaio | Modo | Indicativo e locator do DX | Deep Search | >Corretas | >Erradas",
                "| 1 | JT65A | não conhecidos | não disponível | 0 | 0",
                "| 2 | JT65A | não conhecidos | sim (DX em CALL3.TXT) | 28 | 1",
                "| 3 | Q65-60A | não conhecidos | – | 24 | 0",
                "| 4 | Q65-60A | conhecidos (DX Call e DX Grid) | – | 49 | 0",
                "~ De [2], tabela 1. Configuração JT65: Deep, Deep Search, AP, 6 padrões de apagamento aleatórios, nível agressivo 9; Q65: Fast, média ativa, limpeza automática da média.",
                "As conclusões do autor [2]: para as respostas ao próprio CQ, o Q65-60A tem, para **qualquer** chamador desconhecido, aproximadamente a mesma sensibilidade que o JT65A tem apenas para os chamadores da base de dados; para todos os outros é **pelo menos 3 dB** mais sensível, e ainda mais nas mensagens seguintes, quando ambos os indicativos são conhecidos. As descodificações falsas são tão raras que são difíceis de medir. A média de mensagens do JT65 funciona para um único chamador já identificado, a média do Q65 em toda a banda mostrada. Por fim, o JT65 dedica metade da energia transmitida ao sincronismo, o Q65 um quarto.",
                "> O valor de −25 dB para o JT65 no budget EME é o do guia do WSJT-X sem Deep Search (§ 3.6); os −28 dB com Deep Search aplicam-se apenas às estações listadas na base de dados, os −29 dB com média a qualquer mensagem.",
                ">! **Incoerência entre as fontes.** O documento de comparação JT65A – Q65-60A [2] indica −29 dB para o JT65A com Deep Search; a comunicação de K1JT na conferência EME 2006, citada no § 3.6, dá em vez disso −28 dB para a Deep Search e −29 dB para a média de mensagens. O YAEC usa os valores de 2006. As duas fontes referem-se a submodos diferentes: JT65B nas simulações de 2006, JT65A em [2].",
                "### Como o Q65 constrói o sinal",
                "G4JNT reconstruiu a partir do código-fonte do WSJT-X o percurso da mensagem até aos tons transmitidos, verificando-o com o programa Q65CODE.EXE do WSJT-X [3]. Em resumo:",
                "• **Codificação da fonte.** Como em FST4, FT8, FT4 e MSK144, a mensagem torna-se 71 bits de dados mais 6 bits de tipo, 77 no total. Um texto livre tem até 13 caracteres de um alfabeto de 42 símbolos (espaço, algarismos, letras e + - . / ?), e §42^{13}§ é menor que §2^{71}§; o modo de telemetria transporta até 18 algarismos hexadecimais [3].",
                "• **Símbolos.** Com mais um bit, os 78 bits são divididos em 13 símbolos de seis bits, valores de 0 a 63 [3]: o mesmo comprimento das mensagens de 78 bits de [2].",
                "• **CRC.** Uma verificação de 12 bits (dois símbolos), com polinómio 1100000001111 e os bits de cada símbolo invertidos por compatibilidade com o trabalho de IV3NWV, é usada para rejeitar descodificações falsas [3]. Com o CRC há 15 símbolos.",
                "• **Paridade.** Os 50 símbolos de verificação provêm de uma matriz “geradora” de 15 × 50, com aritmética no corpo de Galois GF(64): a adição é um XOR, a multiplicação faz-se com tabelas de logaritmos e antilogaritmos [3].",
                "• **Código.** O código é um código (65,15) com símbolos de seis bits; os dois símbolos do CRC são “perfurados” (punctured), isto é, não transmitidos, deixando um código efetivo (63,13) [1] [3].",
                "• **Sincronização.** Aos 63 símbolos juntam-se 22 símbolos de sincronismo, todos no tom 0, em posições pseudoaleatórias fixas; transmitem-se 85 símbolos, com 65 tons: 0 para o sincronismo, 1 a 64 para os dados [1] [3].",
                "= f_n = f_0 + n · Δf \\quad n = 0 … 64",
                "~ §f_0§ frequência do tom 0, Δf espaçamento do submodo [3]. Com 22 símbolos de sincronismo em 85, o sincronismo ocupa cerca de um quarto da transmissão, como observado em [2].",
                "### Configurações recomendadas no WSJT-X",
                "Para EME com Q65 os autores recomendam, no WSJT-X: *File → Settings → General* com **Enable VHF and submode features** e **Decode after EME delay** ativados e **Single decode** desativado; no menu *Decode* **Fast**, **Enable averaging** e **Auto Clear Avg after decode** [1]. Cada descodificação Q65 tem a letra “q” e um ou dois algarismos: o primeiro indica a informação *a priori* usada, o segundo o número de sequências em média [1].",
                "|h| Indicador | Informação a priori usada",
                "| q0 | nenhuma",
                "| q1 | CQ",
                "| q2 | o meu indicativo",
                "| q3 | o meu indicativo e o indicativo do DX",
                "| q4 | ambos os indicativos e RRR, RR73, 73 ou vazio",
                "~ De [1]. Os autores advertem para não dar demasiada atenção aos valores de S/N mostrados pelo descodificador, que ainda estavam a ser melhorados [1]: para comparações com o budget EME do YAEC é melhor usar vários QSO do que uma única leitura.",
                "### O procedimento com as DXpedições (W7GJ)",
                "Lance Collister W7GJ, que há anos realiza expedições EME em 6 m, descreve como chamar uma DXpedição em Q65-60A durante um pile-up [6]. Antes de mais, o relógio do computador tem de ser muito preciso e a frequência de transmissão muito estável [6].",
                "• **Períodos.** A DXpedição transmite sempre na primeira sequência (minutos pares); quem chama transmite na segunda (minutos ímpares) [6].",
                "• **Frequência.** Escolha uma frequência livre na banda passante e fique nela: o Q65 faz a média das chamadas de cada estação na sua própria frequência e, se mudar, perde-se o benefício das chamadas anteriores. Deixe cerca de 100 Hz entre si e os outros e verifique que o Doppler não leva o seu sinal para fora da banda passante do DX; quem chama coordena-se no chat EME de ON4KST [6].",
                "• **Modo.** Use o procedimento de contest digital do Q65-60A: no WSJT-X, *File → Settings → Advanced*, uma das opções “Special Operating Activity” NA VHF, WW Digi ou ARRL Digi (depois da versão 2.6.1 também Q65 Pileup). Introduza o indicativo e o locator do DX em DX Call e DX Grid, carregue em Generate Std Msgs e comece pela mensagem TX2, não por CQ [6].",
                "• **Continue a chamar.** Em 6 m, a propagação entre estações com polarização linear é muitas vezes não recíproca: o DX pode copiá-lo mesmo que você não o copie. Não pare de chamar nem volte a uma mensagem anterior quando o DX estiver em QSO com outros ou desaparecer: cada mensagem contém os dois indicativos e o QSO retoma onde parou. Com Q65 Pileup, o DX precisa de pelo menos uma descodificação sua em cada passagem da Lua [6].",
                "• **RRR, nunca RR73.** Em EME use sempre RRR: o RR73 é enviado uma só vez e o QSO fica registado mesmo que a outra estação não o tenha recebido. O QSO está completo quando uma das duas estações recebe o RRR final; quem o recebe responde 73 enquanto for preciso, por isso em *Settings → Behavior* “Disable Tx after sending 73” não deve estar assinalado [6].",
                "• **Observe o ecrã.** Mesmo que não descodifique o DX, o seu traço no waterfall (Wide Graph) ou o pico laranja do Q65 indicam que provavelmente o vai copiar logo que ele responda. Limpe a média à mão quando vir que ele trabalhou outra estação: a seguinte pode ser a sua [6].",
                "|h| DX (primeira sequência, minutos pares) | Quem chama (segunda sequência, minutos ímpares)",
                "| CQ TX7MB CI00 | TX7MB OH2BC KP30",
                "| OH2BC TX7MB R CI00 | TX7MB OH2BC RRR",
                "| G8BCG TX7MB R CI00 | TX7MB G8BCG RRR",
                "| G8BCG TX7MB 73 | TX7MB G8BCG 73",
                "~ Exemplo abreviado de [6], com TX7MB (CI00) como DXpedição: cada estação que chama fica na sua própria frequência e passa a RRR quando recebe o seu próprio “R CI00”.",
                "> As janelas lunares comuns são curtas, sobretudo no nascer e no pôr da Lua, quando muitas estações aproveitam o efeito de solo: o separador Posição em direto e +- 24h e o separador Distância e Dgrd mostram quando a Lua é visível de ambas as estações.",
                ">⚠ A discussão sobre os limites teóricos perde o seu significado no momento em que se estão a receber os sinais: um ruído local repentino pode piorar a escuta, tal como a rotação de Faraday (§ 3.3).",
                "[1] Joe Taylor K1JT, Bill Somerville G4WJS, Steve Franke K9AN, Nico Palermo IV3NWV, “Quick-Start Guide to Q65”, 3 de abril de 2021 (WSJT-X 2.4.0), fornecido por IC8TEM.",
                "[2] Joe Taylor K1JT, “Sensitivity Comparison of JT65A and Q65-60A” (ficheiros de teste JT65A_and_Q65-60A.zip), fornecido por IC8TEM – https://physics.princeton.edu/pulsar/k1jt/JT65A_and_Q65-60A.zip",
                "[3] Andy Talbot G4JNT, “The Q65 Coding Process used in WSJT-X”, outubro de 2023, fornecido por IC8TEM.",
                "[4] Nico Palermo IV3NWV, apresentação na conferência EME 2016 sobre os códigos QRA, citada em [3] – http://www.eme2016.org/wp-content/uploads/2016/08/EME-2016-IV3NWV-Presentation.pdf",
                "[5] Código-fonte do WSJT-X (ficheiro Q65_encoding_modules.F90 e outros), citado em [3] – https://wsjt.sourceforge.io/wsjtx.html",
                "[6] Lance Collister W7GJ, “Q65-60A QSO Procedure and Tips for EME DXpeditions”, revisto em 3 de abril de 2023, fornecido por IC8TEM – http://www.bigskyspaces.com/w7gj/"
            };
            d["pt"]["S54"] = new string[] {
                "## Literatura EME de SM5BSZ",
                "Leif Åsbrink SM5BSZ, autor do Linrad, publicou também no seu sítio web estudos sobre EME que vão além do seu software. Dois trabalhos úteis para compreender o percurso Terra – Lua – Terra:",
                "• “Selecting Polarisation for EME” (25 de abril de 1997): como a geometria, a reflexão na Lua, a rotação de Faraday e a absorção ionosférica alteram a polarização, com conselhos práticos sobre a escolha da polarização em transmissão e em receção em função da frequência – https://sm5bsz.com/polarity/emepol.htm",
                "• “EME Path Modulation” (23 de fevereiro de 2000): espectros de uma portadora de alguns minutos transmitida por SM5FRH e recebida por SM5BSZ via Lua, com a componente especular estreita e a difusa mais larga, que se comportam de modo diferente com a polarização – https://sm5bsz.com/sm5frh/sm5frh.htm",
                "Sobre o lado desportivo do EME: Henryk Kotowski SM0JHF, “Moonbouncers Are Also Contesters”, contesting.com, 20 de maio de 2002 – https://www.contesting.com/articles/294"
            };
            d["pt"]["S55"] = new string[] {
                "## Outras ferramentas de cálculo EME",
                "• **EME Link Budget & Analysis Tool (1-300 GHz)** de Gerald Ihninger OE2IGL e Joachim Köppen DF3GJ: budget completo para as bandas a partir de 1 GHz, com parâmetros da parabólica, apontamento, libração e atmosfera – https://wettersat.bplaced.net/EME/EME.html",
                "• **WSJT-X** de Joe Taylor K1JT e colaboradores: modos digitais para EME (JT65, Q65 e outros) e a janela Astronomical Data com Doppler e CAT – https://wsjt.sourceforge.io"
            };
            d["pt"]["S43"] = new string[] {
                "## Polarização, Dpol e MNR",
                "O ângulo de polarização local é calculado como no WSJT-X a partir da latitude e do azimute e da elevação da Lua; §D_{pol}§ é a diferença entre os ângulos das duas estações, entre −90° e +90°. A perda de polarização linear (no máximo 30 dB) e a não reciprocidade máxima MNR (no máximo 25 dB) são:",
                "= L_{pol} = −20 · log_{10} \\a{cos D_{pol}} \\quad MNR = −20 · log_{10} \\a{cos \\p{2 · D_{pol}}}",
                "A rotação de Faraday não pode ser prevista e não está incluída.",
                "O desvio espacial da polarização pode ser calculado, porque depende apenas da posição das duas estações: vistas da Lua, uma antena horizontal no Polo Norte e outra no equador parecem uma horizontal e a outra vertical. A rotação de Faraday, pelo contrário, é aleatória: o sinal atravessa a ionosfera duas vezes, na ida e na volta, e roda conforme a densidade de eletrões do momento. Pode acontecer que você ouça o DX e ele não o ouça a si; a 90° o sinal não é atenuado, desaparece. Quem tem antenas horizontais e verticais pode receber sempre com a melhor polarização e, se o correspondente não responder, comutar com um relé a polarização de transmissão [1].",
                "> Entre estações distantes, por exemplo entre o hemisfério norte e o sul, só a posição geográfica pode levar §D_{pol}§ perto de 90°. Se ultrapassar 60° nas 24 horas seguintes, o programa mostra um aviso logo que se introduzem os locators [1].",
                "Com antenas de polarização linear, a perda devida ao desvio espacial da polarização é de cerca de 3 dB a 45°, 6 dB a 60° e mais de 20 dB a 90°: é por isso que o aviso dispara a 60° [2].",
                "### A rotação de Faraday",
                "A ionosfera contém eletrões livres que, guiados pelo campo magnético terrestre, se movem em espiral: uma onda com polarização linear que a atravessa sai com o plano de polarização rodado. É a rotação de Faraday [3]. Depende do número de eletrões ao longo do percurso e diminui com o quadrado da frequência [3]:",
                "= F_{f} = F_{144} · \\p{\\frac{144}{f}}^{2}",
                "~ §F_{144}§ é a rotação a 144 MHz, §f§ a frequência em MHz. Um valor diurno típico a 144 MHz é 180° com a Lua no zénite e cerca de quatro vezes mais a 10° de elevação, porque o percurso na ionosfera é mais longo [3].",
                "|h| Banda | >Lua no zénite | >Lua a 10° de elevação",
                "| 50 MHz | >≈ 1 490° (mais de 4 voltas) | >≈ 5 970°",
                "| 144 MHz | >180° | >≈ 720°",
                "| 432 MHz | >≈ 20° | >≈ 80°",
                "~ Rotação por uma passagem na ionosfera, valor diurno típico; 144 MHz segundo [3], as outras bandas derivadas pelo YAEC com a fórmula acima (≈ = derivado). A partir de 1296 MHz pode considerar-se nula [3].",
                "• **Não se anula no regresso.** O sentido da rotação não depende da direção em que a onda viaja: depois da segunda passagem na ionosfera o sinal fica novamente rodado, no mesmo sentido [3]. Cada estação acrescenta a rotação da ionosfera que tem por cima.",
                "• **Muda com o tempo.** A quantidade de eletrões varia entre o dia e a noite, ao nascer e ao pôr do sol e com a atividade solar: com o Sol muito ativo a rotação é forte e pode variar rapidamente, e durante as auroras a polarização pode mudar em poucos milissegundos [3]. Por isso não pode ser prevista por um cálculo.",
                "• **Soma-se ao desvio espacial.** O desvio espacial da polarização (§D_{pol}§) tem sinal oposto nos dois sentidos da ligação, enquanto a rotação de Faraday mantém o mesmo sentido: num sentido as duas rotações somam-se, no outro subtraem-se. Assim pode acontecer que você ouça o DX e ele não o ouça a si, ou o contrário [1]. A perda segue a mesma lei da §D_{pol}§, §L = −20 · log_{10} \\a{cos Δ}§, com Δ o desvio total: a 90° o sinal desaparece.",
                "• **O que fazer.** De 50 a 432 MHz usa-se a polarização linear: convém uma instalação que permita escolher o plano de polarização, de preferência com comutação eletrónica em vez de rodar mecanicamente toda a antena [3]. Quando chama CQ é mais eficaz alternar horizontal e vertical do que usar a polarização circular, que custa sempre 3 dB [3]. Com antenas horizontais e verticais recebe-se com a melhor polarização e, se o correspondente não responder, comuta-se a de transmissão [1].",
                "> Em 432 MHz a rotação de Faraday é pequena e predomina o desvio espacial, que o YAEC calcula; em 50 e 144 MHz pode dar várias voltas e é imprevisível: a §D_{pol}§ e o aviso acima de 60° só têm em conta a parte espacial.",
                "### Escolher a polarização para EME: resumo do artigo de SM5BSZ",
                "O artigo “Selecting Polarisation for EME” de Leif Åsbrink SM5BSZ (25 de abril de 1997) é público e pode ser lido no seu sítio web: https://sm5bsz.com/polarity/emepol.htm. O autor deste programa considera útil oferecer aqui um resumo, como ponto de partida, escrito com as suas próprias palavras; para as explicações completas, remete-se para a leitura integral do artigo [3].",
                "• **Quatro efeitos.** Ao longo do percurso Terra – Lua – Terra a polarização muda devido ao desvio espacial, à reflexão na Lua, à rotação de Faraday e à absorção na ionosfera [3].",
                "• **Desvio espacial.** Vistas da Lua, duas antenas distantes sobre a Terra curva não são paralelas. Diz respeito apenas à polarização linear, calcula-se facilmente e não depende da frequência [3]: é a §D_{pol}§ do YAEC.",
                "• **Reflexão na Lua.** Nas frequências baixas, como 144 MHz, a Lua comporta-se como uma esfera lisa: a polarização linear continua linear, a circular inverte o sentido, e cerca de 1 % da energia acaba na polarização “errada”. A 10 GHz a superfície é rugosa e o sinal volta despolarizado [3].",
                "• **Rotação de Faraday.** É descrita na subsecção anterior: diminui com o quadrado da frequência, soma-se na ida e na volta e não pode ser prevista [3].",
                "• **Absorção ionosférica.** Também diminui com o quadrado da frequência: a 144 MHz, de dia e a 10° de elevação, é de cerca de 0,1 dB. Só conta com uma atividade solar muito alta; durante auroras fortes a polarização pode mudar mais depressa do que um recetor de banda estreita consegue acompanhar [3].",
                "• **De 50 a 432 MHz.** Quase todos usam yagis com polarização linear: o autor recomenda uma instalação com a polarização linear comutável, de preferência eletronicamente; uma rotação mecânica serve se o quarto de volta demorar um ou poucos segundos [3]. Na receção escolhe-se a polarização com o sinal mais forte (um recetor de dois canais é mais rápido com sinais fracos); quando se chama CQ convém alternar horizontal e vertical, em vez de usar a circular, que perde sempre 3 dB [3].",
                "• **De 10 GHz para cima.** A Lua despolariza o sinal, a polarização de transmissão deixa de contar e é preciso um recetor de dois canais em dois alimentadores ortogonais [3]. São frequências fora das bandas do YAEC.",
                "• **Que polarização transmitir.** Se recebe uma estação, pode deduzir com que polarização lhe deve transmitir para que o seu sinal lhe chegue corretamente [3]. Com os ângulos em graus (0° horizontal, 90° vertical), P é a polarização de transmissão da outra estação, R aquela com que a recebe, S o desvio espacial, F a rotação de Faraday e T a sua melhor polarização de transmissão:",
                "= R = P + S + F \\quad P = T − S + F \\quad T = 2 · S − R",
                "~ Eliminando F das duas primeiras relações obtém-se §T = 2 · P + 2 · S − R§; para uma antena linear §2 · P§ vale 0° ou 180°, que é a mesma polarização, e fica §T = 2 · S − R§ [3]. Sem rotação de Faraday (§F§ = 0, a partir de 1296 MHz) a melhor polarização para transmitir é a mesma com que se recebe melhor, §T = R§. O artigo assinala que a regra coincide com a de KL7WE e cita o programa SKYMOON de W5UN para o cálculo de S [3].",
                "> No YAEC o desvio espacial S é a §D_{pol}§ calculada nos separadores Posição da Lua e Posição em direto e +- 24h; a rotação de Faraday F não pode ser calculada. Para os exemplos, os casos particulares e as figuras, leia o artigo completo de SM5BSZ [3].",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s",
                "[2] Paul Bock K4MSG, “Beginner's Guide to Small-station EME”, apresentação, julho de 2015, fornecida por IC8TEM.",
                "[3] Leif Åsbrink SM5BSZ, “Selecting Polarisation for EME”, 25 de abril de 1997 – https://sm5bsz.com/polarity/emepol.htm"
            };
            d["pt"]["S44"] = new string[] {
                "## Ruído do céu e Dgrd",
                "A temperatura do céu atrás da Lua (§T_{sky}§) a 144 MHz é obtida ao longo da eclíptica a partir de uma tabela em passos de 2° (WSJT-X) e, na vista Sky, de um mapa de todo o céu a 2° derivado do Global Sky Model; as outras frequências são escaladas com índice espectral 2,6:",
                "= T(f) = \\p{T_{144} − 2.7} · \\p{\\frac{144}{f}}^{2.6} + 2.7 \\t{ K}",
                "O Dgrd, como no WSJT-X, soma o efeito da distância d da Lua e o do ruído do céu:",
                "= Dgrd = −40 · log_{10} \\frac{d}{\\t{356 903 km}} − 10 · log_{10} \\frac{T_{sky} + 80 \\t{ K}}{T_{sky,min} + 80 \\t{ K}}",
                "= T_{sky,min} = 13 · \\p{\\frac{408}{f}}^{2.6} \\t{ K}",
                "### O que significa a Dgrd",
                "A **Dgrd** (*degradation*, degradação) indica quantos dB o eco da Lua é pior, nesse instante, do que nas melhores condições possíveis: Lua no perigeu e céu frio atrás da Lua. Não depende da estação, mas apenas da Lua e do céu: por isso serve para escolher os dias e as horas, não para calcular a ligação, que é a função do budget EME.",
                "• **0 dB** é o caso ideal; os valores são sempre negativos. **−3 dB** significa metade da relação S/N em relação ao caso ideal, **−6 dB** um quarto.",
                "• O primeiro termo da fórmula é a **distância**: entre o perigeu (cerca de 356 900 km) e o apogeu (cerca de 406 700 km) o eco varia cerca de 2,3 dB, porque a perda de percurso cresce com a quarta potência da distância. Parece pouco, mas duplicar as antenas só faz ganhar 3 dB em teoria [1].",
                "• O segundo termo é o **ruído do céu** atrás da Lua: quando a Lua passa à frente da Via Láctea, a temperatura do céu sobe muito e a Dgrd pode descer vários dB, mais do que pesa a distância.",
                "• Os valores típicos são −1, −1,5 ou −2 dB. Com a Lua sobre o centro da Galáxia, I2FAK viu −11 dB, as piores condições possíveis, e mesmo assim completou um QSO com uma estação muito fraca, uma DXpedição a partir do Djibuti, graças a um sistema de 16 + 16 antenas: em condições tão más a estação tem de estar perfeitamente calibrada, e a experiência conta mais do que as previsões do software [1].",
                "• Para uma estação pequena cada dB conta: um dia com Dgrd de −1 dB e outro com −5 dB podem fazer a diferença entre um QSO completado e nenhuma descodificação.",
                "> No programa: a caixa DGRD do separador Posição em direto e +- 24h mostra o valor atual entre o mínimo e o máximo do gráfico; o separador Distância e Dgrd mostra o calendário dos próximos dias, o gráfico com a distância e os três melhores dias.",
                "### A Lua à frente das fontes de ruído da Galáxia",
                "Todos os meses a Lua percorre a faixa da eclíptica (a menos de cerca de 5° dela) e atravessa duas vezes a Via Láctea. As duas passagens não são iguais:",
                "• **Sagitário, centro da Galáxia**: a zona mais quente do céu; a 144 MHz a temperatura do céu atrás da Lua chega a alguns milhares de K, contra cerca de 200 K nas zonas frias, e essa zona é mais ruidosa do que o Sol [1]. Aqui a Lua está também na sua declinação mais baixa, por volta de −30° nos anos de declinação máxima: a partir do norte de Itália (cerca de 45° N) sobe apenas até 15 – 16° de elevação e fica acima dos 5° cerca de 6 horas (cerca de 7 horas acima do horizonte), enquanto a +30° chega a cerca de 75° e fica acima dos 5° cerca de 15 – 16 horas [1]. É o pior período do mês.",
                "• **Touro e Gémeos, do lado oposto (anticentro)**: a Via Láctea é muito menos quente, mas no Touro, muito perto da eclíptica, encontra-se a **Nebulosa do Caranguejo** (Taurus A), uma das radiofontes mais fortes do céu: quando a Lua passa à frente dela ou ao lado, o ruído aumenta.",
                "• O ruído do céu cresce à medida que a frequência desce: a 50 MHz pesa muito mais do que a 144 MHz, a 432 MHz muito menos (o programa escala-o com o índice espectral 2,6).",
                "> No programa: a vista Sky colore o céu do azul (frio) ao vermelho (quente) e mostra onde está a Lua; a coluna Tsky do separador Posição da Lua e o calendário de Distância e Dgrd indicam quando a Lua está à frente das zonas quentes.",
                "### A declinação da Lua",
                "A **declinação** (§δ§) é a “latitude” da Lua no céu: quantos graus está a norte (+) ou a sul (−) do equador celeste. O programa calcula-a a partir da data e da hora e usa-a em todos os cálculos (elevação, janelas, Tsky, Dpol, Doppler): não é preciso introduzi-la. Conhecê-la, porém, ajuda a escolher os dias.",
                "• **Ciclo mensal**: em cerca de 27,3 dias a declinação vai do máximo a norte ao máximo a sul e volta. Com a Lua do lado do seu hemisfério (positiva a norte, negativa a sul) a Lua sobe mais alto e fica mais horas acima do horizonte; do lado oposto fica baixa e acima do horizonte apenas algumas horas [1].",
                "= El_{max} ≈ 90° − \\a{φ − δ} \\quad cos H_{0} = − tan φ · tan δ \\quad t_{su} = \\frac{2 · H_{0}}{15°} \\t{ h}",
                "~ §φ§ é a latitude da estação, §H_{0}§ o ângulo horário no nascer e no ocaso da Lua, §t_{su}§ as horas com a Lua acima do horizonte (sem obstáculos e sem refração). Exemplo a 41° N: com §δ§ = +28° a Lua chega a cerca de 77° e fica acima do horizonte cerca de 15,7 horas; com §δ§ = −28° fica-se por cerca de 21° e fica acima do horizonte cerca de 8,3 horas.",
                "• **Ligações entre hemisférios**: num QSO norte – sul as duas estações preferem declinações opostas; as janelas comuns mais longas ocorrem muitas vezes com a Lua perto do equador celeste (declinação por volta de 0°), quando nenhuma das duas estações fica em desvantagem.",
                "• **Ciclo de 18,6 anos**: a amplitude da excursão mensal muda lentamente, de cerca de ±18,3° a cerca de ±28,6°. O máximo (lunistício maior) foi em 2024 – 2025; por volta de 2034 a excursão será mínima, com meses menos extremos: a Lua não descerá tão baixo, mas também não subirá tão alto.",
                "• **Declinação e ruído**: a Lua atinge a declinação mais baixa quando passa à frente do Sagitário, a zona mais ruidosa do céu, e a mais alta no Touro e nos Gémeos, onde o céu é mais frio. Para as estações do hemisfério norte, a semana da declinação mais baixa junta portanto Lua baixa, poucas horas úteis e Tsky alta [1].",
                "> No programa: por baixo do gráfico do separador Distância e Dgrd, a curva da declinação mostra os máximos a norte e a sul com a data; a zona verde indica quando a Lua está do lado do seu hemisfério (a curva oculta-se com a caixa Curva da declinação). O valor de cada instante está na coluna opcional Declinação (°) do separador Posição da Lua e no separador Posição em direto e +- 24h.",
                "[1] Franco I2FAK – YouTube: “Radioamatori – To the moon and back con I2FAK Franco – Prima parte” – https://www.youtube.com/watch?v=aNsnSweIvPY ; “Radioamatori – L'intervista a Franco I2FAK – Seconda parte” – https://www.youtube.com/watch?v=GPVNLiUiD_s"
            };
            d["pt"]["S45"] = new string[] {
                "### Porque é que o Sol conta",
                "O **Sol** é a fonte de ruído mais forte do céu. Perto da Lua nova, o Sol e a Lua estão próximos no céu: mesmo que o Sol fique fora do lóbulo principal, entra pelos lóbulos laterais, e a poucas larguras de feixe o ruído recebido cresce muito. Por isso, na prática, a semana da Lua nova é quase sempre de evitar.",
                "• O quanto pesa depende do ganho da antena (lóbulo mais estreito, Sol mais afastado em larguras de feixe), do nível dos lóbulos laterais e da **atividade solar**: o fluxo solar, em SFU, muda de um dia para o outro e cresce muito durante as erupções.",
                "• Por isso uma antena com os **lóbulos laterais muito atenuados** é fundamental: os lóbulos laterais captam o ruído em redor e somam-no ao do lóbulo principal [1].",
                "• Durante um eclipse do Sol a Lua está mesmo à frente do Sol: I2FAK completou mesmo assim um QSO apontando 2,5 – 3° ao lado da Lua, de modo que o lóbulo estreito do seu agrupamento atenuava o ruído do Sol [1].",
                "• O Sol abaixo do horizonte do recetor não conta, mesmo com Lua nova.",
